/// Per-layer weights (openai-moe.cpp:30-66 load_arch_tensors).
#[derive(Clone)]
pub struct GptOssLayerWeights {
    pub attn_norm: TensorId,
    /// attn_post_norm — applied to the attention residual *before* the MoE
    /// (openai-moe.cpp:132-135)
    pub attn_post_norm: TensorId,
    pub wq: TensorId,
    pub wk: TensorId,
    pub wv: TensorId,
    /// optional q/k/v biases: the gpt-oss GGUFs carry attn_q/attn_k/attn_v
    /// biases (k is all-zero, q/v are not) and build_qkv applies them
    /// (llama-graph.cpp:1710-1718) — create_tensor_qkv loads them with
    /// TENSOR_NOT_REQUIRED so they are used whenever present.
    pub wq_b: Option<TensorId>,
    pub wk_b: Option<TensorId>,
    pub wv_b: Option<TensorId>,
    pub wo: TensorId,
    /// always present in gpt-oss GGUFs (openai-moe.cpp:58)
    pub wo_b: TensorId,
    /// F32 [n_head] attention sink logits (openai-moe.cpp:50)
    pub attn_sinks: TensorId,
    pub ffn_gate_inp: TensorId,
    pub ffn_gate_inp_b: TensorId,
    pub ffn_up_exps: TensorId,
    pub ffn_up_exps_b: TensorId,
    pub ffn_gate_exps: TensorId,
    pub ffn_gate_exps_b: TensorId,
    pub ffn_down_exps: TensorId,
    pub ffn_down_exps_b: TensorId,
}

pub struct GptOssModelWeights {
    pub tok_embd: TensorId,
    pub output_norm: TensorId,
    pub output: TensorId,
    pub output_b: Option<TensorId>,
    pub layers: Vec<GptOssLayerWeights>,
}

/// MoE / SWA parameters of the gpt-oss graph (hparams + the constants in
/// llama-graph.cpp:2288-2290).
#[derive(Clone)]
pub struct GptOssParams {
    /// hparams.n_expert (openai-moe.cpp:136)
    pub n_expert: i64,
    /// hparams.n_expert_used(il) — the top-k width of argsort_top_k
    /// (llama-graph.cpp:2109)
    pub n_expert_used: Vec<u32>,
    /// LLM_FFN_SWIGLU_OAI_MOE constants (llama-graph.cpp:2288-2290)
    pub swiglu_oai_alpha: f32,
    pub swiglu_oai_limit: f32,
    /// hparams.expert_weights_scale; C scales only when != 0 && != 1
    /// (llama-graph.cpp:2183-2186)
    pub expert_weights_scale: f32,
    /// hparams.is_swa(il) (openai-moe.cpp:12 load_swa_pattern(ml, 2))
    pub is_swa: Vec<bool>,
    /// hparams.rope_freq_base_train_swa / rope_freq_scale_train_swa
    /// (openai-moe.cpp:14-17; `get_rope_freq_base/scale`, llama-model.cpp:2251)
    pub rope_freq_base_swa: f32,
    pub rope_freq_scale_swa: f32,
}

impl Default for GptOssParams {
    fn default() -> Self {
        GptOssParams {
            n_expert: 0,
            n_expert_used: Vec::new(),
            swiglu_oai_alpha: 1.702,
            swiglu_oai_limit: 7.0,
            expert_weights_scale: 1.0,
            is_swa: Vec::new(),
            rope_freq_base_swa: 0.0,
            rope_freq_scale_swa: 1.0,
        }
    }
}

/// verify against src/models/openai-moe.cpp:73-175 llama_model_openai_moe::graph::graph —
/// RMS norm → separate QKV (no q/k/v bias) → RoPE NEOX with per-layer
/// freq_base/freq_scale (SWA-aware) → kv-cache MHA with attention sinks →
/// residual + attn_post_norm → MoE (softmax-after-top-k routing, per-expert
/// biases, swiglu_oai activation) → residual → final norm → lm_head.
///
/// PARTIAL (reported, not worked around):
///   * SWA layers are wired (`hparams.is_swa(il)` → the second cache of the
///     `iswa` pair, llama-graph.cpp:3131-3133): the builder itself needs
///     nothing special (attn_kv_cached selects cache/mask/idx per layer), but
///     the driver has to pass the hparams — `DecodeContext::new_with_swa` with
///     `SwaCacheSpec::from_hparams` for gpt-oss-20b's n_swa = 128. With
///     `new_with` the unified cache is used and the result is exact while
///     n_kv <= n_swa = 128.
///   * FA+sinks is wired (flash_attn_ext_sinks -> src[4], ops.cpp:8811)
///     gpt-oss reference output is reproduced with it (see gpt_oss_e2e.rs).
#[allow(clippy::too_many_arguments)]
pub fn build_gpt_oss_forward(
    ctx: &mut Context,
    w: &GptOssModelWeights,
    p: &AttnParams,
    gp: &GptOssParams,
    kv: &KvCache,
    inp: &DecodeInputs,
    sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    assert_eq!(
        w.layers.len(),
        gp.n_expert_used.len(),
        "GptOssParams::n_expert_used must have one entry per layer"
    );
    if !gp.is_swa.is_empty() {
        assert_eq!(
            w.layers.len(),
            gp.is_swa.len(),
            "GptOssParams::is_swa per layer"
        );
    }
    let _ = sinfo; // scatter indices travel in inp.row_idx (same as the other builders)
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(4096);

    // inpL = embd lookup (build_inp_embd, openai-moe.cpp:76, lora at
    // llama-graph.cpp:2389-2405)
    let inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    let mut inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_sa = inp_l;

        // per-layer rope params (openai-moe.cpp:86-87 → llama-model.cpp:2251):
        // SWA layers read the *_swa copies
        let is_swa = gp.is_swa.get(il).copied().unwrap_or(false);
        let (freq_base, freq_scale) = if is_swa {
            (gp.rope_freq_base_swa, gp.rope_freq_scale_swa)
        } else {
            (p.freq_base, p.freq_scale)
        };

        // attn_norm (openai-moe.cpp:92-96, LLM_NORM_RMS)
        let cur = build_norm_rms(ctx, inp_l, lw.attn_norm, p.norm_eps);
        ctx.set_name(cur, &format!("attn_norm-{il}")); // cb(cur, "attn_norm", il) :87

        // build_qkv separate path (llama-graph.cpp:1687-1735 with build_lora_mm
        // at :1689/1703/1717): plain mul_mat + reshape_3d; gpt-oss has no q/k/v
        // biases
        let mut q = crate::adapter::lora_mm(ctx, lw.wq, cur);
        if let Some(b) = lw.wq_b {
            q = ctx.add(q, b);
        }
        ctx.set_name(q, &format!("Qcur-{il}")); // cb(Qcur, "Qcur", il) :107
        let mut k = crate::adapter::lora_mm(ctx, lw.wk, cur);
        if let Some(b) = lw.wk_b {
            k = ctx.add(k, b);
        }
        ctx.set_name(k, &format!("Kcur-{il}")); // cb(Kcur, "Kcur", il) :108
        let mut v = crate::adapter::lora_mm(ctx, lw.wv, cur);
        if let Some(b) = lw.wv_b {
            v = ctx.add(v, b);
        }
        ctx.set_name(v, &format!("Vcur-{il}")); // cb(Vcur, "Vcur", il) :109
        let q = ctx.reshape_3d(q, p.n_embd_head_k, p.n_head, t);
        let k = ctx.reshape_3d(k, p.n_embd_head_k, p.n_head_kv, t);
        let v = ctx.reshape_3d(v, p.n_embd_head_v, p.n_head_kv, t);

        // rope Q/K (openai-moe.cpp:95-113), NEOX, n_rot = head_dim
        let q = ctx.rope_ext(
            q,
            inp.pos,
            None,
            p.n_rot as i32,
            p.rope_mode,
            p.n_ctx_orig,
            freq_base,
            freq_scale,
            p.ext_factor,
            p.attn_factor,
            p.beta_fast,
            p.beta_slow,
        );
        ctx.set_name(q, &format!("Qcur-{il}"));
        let k = ctx.rope_ext(
            k,
            inp.pos,
            None,
            p.n_rot as i32,
            p.rope_mode,
            p.n_ctx_orig,
            freq_base,
            freq_scale,
            p.ext_factor,
            p.attn_factor,
            p.beta_fast,
            p.beta_slow,
        );
        ctx.set_name(k, &format!("Kcur-{il}"));

        // build_attn (openai-moe.cpp:115-121) with kq_scale = 1/sqrt(n_rot) and
        // the layer's attention sinks
        let kq_scale = 1.0 / (p.n_rot as f32).sqrt();
        let cur = attn_kv_cached(
            ctx,
            &mut graph,
            kv,
            il,
            p,
            inp,
            n_kv,
            q,
            k,
            v,
            kq_scale,
            0.0,
            None,
            Some(lw.attn_sinks),
            Some(lw.wo),
            Some(lw.wo_b),
        );
        ctx.set_name(cur, &format!("attn_out-{il}")); // cb(cur, "attn_out", il) :115

        // ffn_inp = attn_out + inpSA (openai-moe.cpp:122)
        let ffn_inp = ctx.add(cur, inp_sa);
        ctx.set_name(ffn_inp, &format!("ffn_inp-{il}")); // cb(ffn_inp, il) :123

        // attn_post_norm on the residual branch (openai-moe.cpp:132-135)
        let cur = build_norm_rms(ctx, ffn_inp, lw.attn_post_norm, p.norm_eps);
        ctx.set_name(cur, &format!("attn_post_norm-{il}")); // cb(cur, il) :129

        // MoE branch (openai-moe.cpp:138-141 → build_moe_ffn
        // llama-graph.cpp:1993-2368 with LLM_FFN_SWIGLU_OAI_MOE, norm_w = false,
        // SOFTMAX_WEIGHT gating)
        let cur = build_moe_ffn_gpt_oss(ctx, &mut graph, cur, lw, gp, il);
        ctx.set_name(cur, &format!("ffn_moe_out-{il}")); // cb(cur, il) :143

        // residual (openai-moe.cpp:145)
        inp_l = ctx.add(cur, ffn_inp);
        ctx.set_name(inp_l, &format!("l_out-{il}")); // cb(cur, "l_out", il) :148
    }

    // final norm + lm_head (openai-moe.cpp:158-170). C reduces to the output
    // rows via inp_out_ids first (openai-moe.cpp:160-162) — identical values.
    let cur = build_norm_rms(ctx, inp_l, w.output_norm, p.norm_eps);
    ctx.set_name(cur, "result_norm"); // cb(cur, "result_norm", -1) :165
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let mut logits = crate::adapter::lora_mm(ctx, w.output, cur);
    if let Some(b) = w.output_b {
        logits = ctx.add(logits, b);
    }
    ctx.set_name(logits, "result_output"); // cb(cur, "result_output", -1) :171
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

/// build_moe_ffn for gpt-oss (llama-graph.cpp:1993-2368) with
/// `LLAMA_EXPERT_GATING_FUNC_TYPE_SOFTMAX_WEIGHT`: the router logits are used
/// **unsoftmaxed** for the top-k selection and the softmax is applied to the
/// k selected weights afterwards.
#[allow(clippy::too_many_arguments)]
fn build_moe_ffn_gpt_oss(
    ctx: &mut Context,
    graph: &mut Graph,
    cur: TensorId,
    lw: &GptOssLayerWeights,
    gp: &GptOssParams,
    il: usize,
) -> TensorId {
    let n_embd = ctx.ne(cur)[0];
    let n_tokens = ctx.ne(cur)[1];
    let n_expert = gp.n_expert;
    let n_expert_used = gp.n_expert_used[il] as i64;

    // logits = gate_inp @ cur + gate_inp_b (llama-graph.cpp:2013-2026,
    // build_lora_mm at :2025)
    let logits = crate::adapter::lora_mm(ctx, lw.ffn_gate_inp, cur); // [n_expert, n_tokens]
    let logits = ctx.add(logits, lw.ffn_gate_inp_b);

    // probs = logits (SOFTMAX_WEIGHT keeps the raw logits, :2043-2047)
    let selection_probs = logits;

    // selected_experts = argsort_top_k(selection_probs, n_expert_used)
    // (llama-graph.cpp:2109) — DESC argsort, first-k strided view
    let selected_experts = ctx.argsort_top_k(selection_probs, n_expert_used as i32);

    // weights = get_rows(reshape_3d(probs, 1, n_expert, n_tokens), selected)
    // (llama-graph.cpp:2130-2132)
    let probs = ctx.reshape_3d(selection_probs, 1, n_expert, n_tokens);
    let weights = ctx.get_rows(probs, selected_experts); // [1, k, n_tokens]
    let weights = ctx.reshape_2d(weights, n_expert_used, n_tokens);
    // soft_max over the k selected weights (:2135-2141)
    let weights = ctx.soft_max(weights);
    let weights = ctx.reshape_3d(weights, 1, n_expert_used, n_tokens);

    // w_scale (llama-graph.cpp:2183-2186): skipped when 0 or 1 (gpt-oss: 1)
    let weights = if gp.expert_weights_scale != 0.0 && gp.expert_weights_scale != 1.0 {
        ctx.scale(weights, gp.expert_weights_scale)
    } else {
        weights
    };

    // cur = reshape_3d(cur, n_embd, 1, n_tokens) (:2188)
    let cur3 = ctx.reshape_3d(cur, n_embd, 1, n_tokens);

    // up / gate experts (llama-graph.cpp:2210-2237, build_lora_mm_id at
    // :2190/2203): separate gate+up path
    let up = crate::adapter::lora_mm_id(ctx, lw.ffn_up_exps, cur3, selected_experts);
    let up = ctx.add_id(up, lw.ffn_up_exps_b, selected_experts);
    let gate = crate::adapter::lora_mm_id(ctx, lw.ffn_gate_exps, cur3, selected_experts);
    let gate = ctx.add_id(gate, lw.ffn_gate_exps_b, selected_experts);

    // LLM_FFN_SWIGLU_OAI_MOE (llama-graph.cpp:2306-2313):
    // ggml_swiglu_oai(gate, up, alpha = 1.702, limit = 7.0)
    let cur = ctx.swiglu_oai(gate, up, gp.swiglu_oai_alpha, gp.swiglu_oai_limit);

    // down experts + bias (:2320-2328, build_lora_mm_id at :2304)
    let experts = crate::adapter::lora_mm_id(ctx, lw.ffn_down_exps, cur, selected_experts);
    let experts = ctx.add_id(experts, lw.ffn_down_exps_b, selected_experts);

    // experts *= weights (:2330-2333)
    let experts = ctx.mul(experts, weights);

    // aggregate: n_expert_used views + sequential adds (:2341-2358). The views
    // are expanded explicitly like C's ggml_build_forward_expand so the graph
    // never prunes them.
    let nb1 = ctx.nb(experts)[1] as usize;
    let nb2 = ctx.nb(experts)[2] as usize;
    let mut moe_out = ctx.view_2d(experts, n_embd, n_tokens, nb2, 0);
    graph.build_forward(ctx, moe_out);
    for i in 1..n_expert_used as usize {
        let vi = ctx.view_2d(experts, n_embd, n_tokens, nb2, i * nb1);
        graph.build_forward(ctx, vi);
        moe_out = ctx.add(moe_out, vi);
        graph.build_forward(ctx, moe_out);
    }
    moe_out
}

// ======================================================================
// shared helpers — llama-graph.cpp ports
// ======================================================================

/// build_norm LLM_NORM_RMS (llama-graph.cpp:1583-1616): rms_norm then mul by
/// the weight vector (plain-w semantics — llama/phi3; gemma uses (1+w)).
pub(crate) fn build_norm_rms(ctx: &mut Context, x: TensorId, w: TensorId, eps: f32) -> TensorId {
    let n = ctx.rms_norm(x, eps);
    ctx.mul(n, w)
}

/// build_ffn LLM_FFN_SILU + LLM_FFN_PAR (llama-graph.cpp:1748-1857):
/// gate/up in parallel on the normed input, silu(gate) * up, then down
/// (+ optional biases).
#[allow(clippy::too_many_arguments)]
pub(crate) fn build_ffn_silu_par(
    ctx: &mut Context,
    cur: TensorId,
    gate: TensorId,
    gate_b: Option<TensorId>,
    up: TensorId,
    up_b: Option<TensorId>,
    down: TensorId,
    down_b: Option<TensorId>,
) -> TensorId {
    let mut g = crate::adapter::lora_mm(ctx, gate, cur);
    if let Some(b) = gate_b {
        g = ctx.add(g, b);
    }
    let mut u = crate::adapter::lora_mm(ctx, up, cur);
    if let Some(b) = up_b {
        u = ctx.add(u, b);
    }
    let g = ctx.silu(g);
    let prod = ctx.mul(g, u);
    let mut out = crate::adapter::lora_mm(ctx, down, prod);
    if let Some(b) = down_b {
        out = ctx.add(out, b);
    }
    out
}

/// build_attn (llama-graph.cpp:2851-2924) + build_attn_mha over the unified KV
/// cache. Two branches (llama-graph.cpp:2626):
///   * `p.use_flash_attn` (FA, :2627-2669): permute q/k/v → ggml_flash_attn_ext
///     with the F16 mask → reshape_2d, then wo. See graph::flash_attn_core.
///   * non-FA (:2670-2733):
///   1. scatter K/V rows into the cache via set_rows (cpy_k/cpy_v,
///      llama-kv-cache.cpp:1318/1353 — dims 0/1 merged with view_2d so fused
///      qkv V views work unchanged)
///   2. kq = mul_mat(k_cache_view, q) with GQA broadcast
///   3. [attention softcap — PARTIAL, requires tanh; must be 0.0]
///   4. soft_max_ext(kq, mask, kq_scale, max_bias)
///   5. kqv = mul_mat(v_cont, kq); permute/cont back to [n_embd, T]
///   6. wo projection (+ optional bias)
///
/// `q`/`k` are post-rope [head_dim, heads/kv_heads, T]; `v` may be a strided
/// view (phi3 fused qkv). The set_rows writes have no downstream consumers
/// (reads view the cache base) and are expanded explicitly per layer.
#[allow(clippy::too_many_arguments)]
fn attn_kv_cached(
    ctx: &mut Context,
    graph: &mut Graph,
    kv: &KvCache,
    il: usize,
    p: &AttnParams,
    inp: &DecodeInputs,
    n_kv: u32,
    q: TensorId,
    k: TensorId,
    v: TensorId,
    kq_scale: f32,
    // hparams.f_max_alibi_bias (llama-graph.cpp:2643 / :2705) — the ALiBi
    // max bias of `ggml_flash_attn_ext` / `ggml_soft_max_ext`. 0.0 for every
    // non-ALiBi arch (the value all pre-batch-3 call sites hard-coded); the
    // ALiBi archs pass hparams.f_max_alibi_bias > 0, which switches both
    // kernels to the per-head slope path (ops.cpp:8685-8705 / :5618-5637).
    max_bias: f32,
    // llama-graph.cpp:2691-2698 `if (hparams.attn_soft_cap)`: Some(cap) runs
    // `kq = scale(kq, 1/cap); kq = tanh(kq); kq = scale(kq, cap)` between the
    // kq matmul and soft_max_ext; None skips it (llama/qwen2/phi3/gemma3).
    attn_logit_softcapping: Option<f32>,
    // ggml_soft_max_add_sinks (llama-graph.cpp:2701-2702): F32 [n_head] attention
    // sink logits attached as src[2] of the softmax (gpt-oss). Ignored by the FA
    // branch, which needs ggml_flash_attn_ext sinks (TODO, see below).
    attn_sinks: Option<TensorId>,
    // llama-graph.cpp:2851 `build_attn(..., wo, ...)`: None skips the output
    // projection (qwen35's full-attention layer applies sigmoid(gate) first and
    // projects afterwards, qwen35.cpp:341-347)
    wo: Option<TensorId>,
    wo_b: Option<TensorId>,
) -> TensorId {
    let t = ctx.ne(q)[2];

    // Per-layer cache selection — llama-graph.cpp:3131-3133 (`mctx_cur = is_swa
    // ? mctx_iswa->get_swa() : mctx_iswa->get_base()`) plus the matching inputs
    // of `llm_graph_input_attn_kv_iswa::set_input` (:612-651): a SWA layer
    // writes/scatters into the second cache (`self_k_idxs_swa`), reads its own
    // n_kv rows and uses the window mask (`self_kq_mask_swa`). `layers[il]` and
    // the view strides already resolve through the layer's own cache
    // (kv_cache.rs `cache_size_of`).
    let is_swa = kv.layer_is_swa(il);
    let (row_idx, kq_mask, n_kv) = if is_swa {
        let step = kv
            .swa_step
            .expect("SWA layer without the iswa step inputs (KvCache::swa_step)");
        (step.row_idx, step.kq_mask, kv.n_kv_swa())
    } else {
        (inp.row_idx, inp.kq_mask, n_kv)
    };

    // cpy_k/cpy_v: merge head dims 0/1 into one row dim (requires
    // nb[1] == row_size(head_dim), guaranteed for post-rope tensors and the
    // fused-qkv views), then set_rows scatter at the cache's row indices
    let k_rows = {
        let nb2 = ctx.nb(k)[2] as usize;
        ctx.view_2d(k, p.n_embd_head_k * p.n_head_kv, t, nb2, 0)
    };
    let v_rows = {
        let nb2 = ctx.nb(v)[2] as usize;
        ctx.view_2d(v, p.n_embd_head_v * p.n_head_kv, t, nb2, 0)
    };
    let k_dst = ctx.set_rows(kv.layers[il].k, k_rows, row_idx);
    let v_dst = ctx.set_rows(kv.layers[il].v, v_rows, row_idx);
    graph.build_forward(ctx, k_dst);
    graph.build_forward(ctx, v_dst);

    // cache views [head_dim, n_head_kv, n_kv, 1]
    let k_view = kv.get_k(ctx, il, p.n_embd_head_k, p.n_head_kv, n_kv);
    let v_view = kv.get_v(ctx, il, p.n_embd_head_v, p.n_head_kv, n_kv);

    // FA branch — verify against build_attn_mha use_flash_attn (llama-graph.cpp:2626-2669):
    // `cparams.flash_attn && kq_b == nullptr`. None of these four archs has a
    // KQ bias, so the flag alone selects FA.
    //   * max_bias = hparams.f_max_alibi_bias (the `max_bias` parameter — 0.0
    //     for every non-ALiBi model, same value the non-FA soft_max_ext call
    //     below passes)
    //   * logit_softcap = hparams.attn_soft_cap ? f_attn_logit_softcapping : 0.0
    //     (llama-graph.cpp:2643-2644) — exactly this call's `attn_logit_softcapping`
    //     Option: gemma2 = Some(cap), llama/gemma3/phi3 = None → 0.0.
    //     C's FA kernel applies the cap itself (`s = cap*tanhf(s)` after the
    //     scale/softcap pre-division, ops.cpp:8675-8677/8760-8762), reproducing
    //     the non-FA `scale(1/cap) → tanh → scale(cap)` chain at :2691-2698.
    if p.use_flash_attn {
        // sinks ride src[4] (ggml_flash_attn_ext_add_sinks, llama-graph.cpp:2646)
        let kqv = graph::flash_attn_core_sinks(
            ctx,
            q,
            k_view,
            v_view,
            kq_mask,
            attn_sinks,
            kq_scale,
            max_bias,
            attn_logit_softcapping.unwrap_or(0.0),
        );
        ctx.set_name(kqv, &format!("kqv_out-{il}")); // cb(cur, "kqv_out", il) :2801
                                                     // wo projection + optional bias (llama-graph.cpp:2906-2921,
                                                     // build_lora_mm at :2909)
        return match wo {
            Some(wo) => {
                let mut cur = crate::adapter::lora_mm(ctx, wo, kqv);
                if let Some(b) = wo_b {
                    cur = ctx.add(cur, b);
                }
                cur
            }
            None => kqv,
        };
    }

    // [head_dim, heads, T] → [head_dim, T, heads]
    let q = ctx.permute(q, 0, 2, 1, 3);
    let k_view = ctx.permute(k_view, 0, 2, 1, 3);

    // kq = mul_mat(k, q) → [n_kv, T, heads] (GQA broadcast r2,
    // llama-graph.cpp:2671)
    let mut kq = ctx.mul_mat(k_view, q);
    ctx.set_name(kq, &format!("kq-{il}")); // cb(kq, "kq", il) llama-graph.cpp:2672
                                           // attn logit softcap (llama-graph.cpp:2691-2698), order exactly as C:
                                           // scale(1/cap) → tanh → scale(cap)
    if let Some(cap) = attn_logit_softcapping {
        kq = ctx.scale(kq, 1.0 / cap);
        kq = ctx.tanh(kq);
        kq = ctx.scale(kq, cap);
    }
    kq = ctx.soft_max_ext(kq, Some(kq_mask), kq_scale, max_bias);
    ctx.set_name(kq, &format!("kq_soft_max-{il}")); // cb(kq_soft_max, il) :2707
                                                    // ggml_soft_max_add_sinks (llama-graph.cpp:2701-2702)
    if let Some(sk) = attn_sinks {
        ctx.soft_max_add_sinks(kq, Some(sk));
    }

    // non-FA v path (llama-graph.cpp:2709-2715): permute → transpose → cont
    let v_view = ctx.permute(v_view, 0, 2, 1, 3);
    let v_t = ctx.transpose(v_view);
    let v_c = ctx.cont(v_t);
    let kqv = ctx.mul_mat(v_c, kq); // [head_dim, T, heads]
    ctx.set_name(kqv, &format!("kqv-{il}")); // cb(kqv, "kqv", il) :2716

    // back to [n_embd, T] (llama-graph.cpp:2724-2727)
    let kqv = ctx.permute(kqv, 0, 2, 1, 3);
    let kqv = ctx.cont(kqv);
    let kqv = ctx.reshape_2d(kqv, p.n_embd_head_v * p.n_head, t);
    ctx.set_name(kqv, &format!("kqv_out-{il}")); // cb(cur, "kqv_out", il) :2733

    // wo projection + optional bias (llama-graph.cpp:2906-2921,
    // build_lora_mm at :2909) — cb(cur, "attn_out", il)
    match wo {
        Some(wo) => {
            let mut cur = crate::adapter::lora_mm(ctx, wo, kqv);
            ctx.set_name(cur, &format!("attn_out-{il}"));
            if let Some(b) = wo_b {
                cur = ctx.add(cur, b);
            }
            cur
        }
        None => kqv,
    }
}

// ======================================================================
// recurrent state — llama_memory_recurrent, single-sequence slice
// ======================================================================

/// One state cell per recurrent layer (conv window + SSM state), the
/// `n_rs_seq == 0` / `K == 1` slice of src/llama-memory-recurrent.cpp.
///
/// The C module keeps the states in a persistent cache tensor per layer
/// (`get_r_l` / `get_s_l`) and addresses a cell through `ids` (the memory
/// head). This port models a single sequence with a single cell (slot 0), so
/// the `ids` indirection degenerates to a constant 0 — the graph still passes
/// an I32 ids tensor with that value so the kernels keep C's addressing.
///
/// The tensors live in the caller's Context and must be allocated **before**
/// `Context::mark()`/`reset_graph_to` (llama.cpp allocates them outside the
/// per-ubatch graph too).
pub struct RecurrentState {
    /// per layer: conv window, F32 {n_embd_r} (None on attention layers)
    pub conv: Vec<Option<TensorId>>,
    /// per layer: SSM state, F32 {n_embd_s} (None on attention layers)
    pub ssm: Vec<Option<TensorId>>,
    /// per layer: the PLE conv history, F32 {ple_conv_state()}
    /// (`cache_ple_r_l`, llama-memory-recurrent.cpp:110-114 — "the PLE
    /// history needs its own row: Meta must mirror it while the delta-net
    /// conv state next door stays split"). qwen4exp's PLE layers only.
    pub ple: Vec<Option<TensorId>>,
    pub n_embd_r: i64,
    pub n_embd_s: i64,
}

impl RecurrentState {
    /// Allocate one zeroed cell per recurrent layer (llama_memory_recurrent's
    /// `rs_zero` cell: a fresh sequence starts from an all-zero state).
    pub fn new(ctx: &mut Context, is_recr: &[bool], n_embd_r: u32, n_embd_s: u32) -> Self {
        Self::new_with_ple(ctx, is_recr, n_embd_r, n_embd_s, &[], 0)
    }

    /// the PLE-aware form: `is_ple` marks the layers that carry a
    /// `cache_ple_r_l` history row of `n_embd_ple` width (0 = no PLE module)
    pub fn new_with_ple(
        ctx: &mut Context,
        is_recr: &[bool],
        n_embd_r: u32,
        n_embd_s: u32,
        is_ple: &[bool],
        n_embd_ple: u32,
    ) -> Self {
        let mut conv = Vec::with_capacity(is_recr.len());
        let mut ssm = Vec::with_capacity(is_recr.len());
        let mut ple = Vec::with_capacity(is_recr.len());
        for (il, &r) in is_recr.iter().enumerate() {
            let want_ple = n_embd_ple > 0 && is_ple.get(il).copied().unwrap_or(false);
            if r {
                let c = ctx.new_tensor_1d(GgmlType::F32, n_embd_r as i64);
                ctx.arena_resize_tensor(c);
                conv.push(Some(c));
                if n_embd_s > 0 {
                    let s = ctx.new_tensor_1d(GgmlType::F32, n_embd_s as i64);
                    ctx.arena_resize_tensor(s);
                    ssm.push(Some(s));
                } else {
                    ssm.push(None);
                }
                if want_ple {
                    let q = ctx.new_tensor_1d(GgmlType::F32, n_embd_ple as i64);
                    ctx.arena_resize_tensor(q);
                    ple.push(Some(q));
                } else {
                    ple.push(None);
                }
            } else {
                conv.push(None);
                ssm.push(None);
                ple.push(None);
            }
        }
        let mut st = RecurrentState {
            conv,
            ssm,
            ple,
            n_embd_r: n_embd_r as i64,
            n_embd_s: n_embd_s as i64,
        };
        st.zero(ctx);
        st
    }

    /// Zero every cell (llama_memory_recurrent `rs_zero` handling: the state of
    /// a sequence that has no history must start at 0).
    pub fn zero(&mut self, ctx: &mut Context) {
        for t in self.conv.iter().chain(self.ssm.iter()).chain(self.ple.iter()).flatten() {
            let len = ctx.nbytes(*t);
            ctx.data_bytes_mut(*t).unwrap()[..len].fill(0);
        }
    }

    pub fn n_layer(&self) -> usize {
        self.conv.len()
    }
}

