/// Per-layer weights (granite-hybrid.cpp:41-139 load_arch_tensors). Recurrent
/// layers (`n_head_kv == 0`) carry the mamba2 mixer; the others attention
/// (create_tensor_qkv with no biases).
#[derive(Clone)]
pub struct GraniteLayerWeights {
    pub attn_norm: TensorId,
    /// mamba2 mixer (recurrent layers only)
    pub ssm_in: Option<TensorId>,
    pub ssm_conv1d: Option<TensorId>,
    pub ssm_conv1d_b: Option<TensorId>,
    pub ssm_dt_b: Option<TensorId>,
    pub ssm_a: Option<TensorId>,
    pub ssm_d: Option<TensorId>,
    pub ssm_norm: Option<TensorId>,
    pub ssm_out: Option<TensorId>,
    /// attention layers only
    pub wq: Option<TensorId>,
    pub wk: Option<TensorId>,
    pub wv: Option<TensorId>,
    pub wo: Option<TensorId>,
    pub wo_b: Option<TensorId>,
    /// rope factors (llama-model.cpp get_rope_factors: None for il == 0)
    pub rope_freqs: Option<TensorId>,
    /// feed-forward (dense or the shared-expert branch)
    pub ffn_norm: TensorId,
    pub ffn_gate: Option<TensorId>,
    pub ffn_down: Option<TensorId>,
    pub ffn_up: Option<TensorId>,
    pub ffn_gate_b: Option<TensorId>,
    pub ffn_down_b: Option<TensorId>,
    pub ffn_up_b: Option<TensorId>,
    /// MoE router + experts
    pub ffn_gate_inp: Option<TensorId>,
    pub ffn_gate_exps: Option<TensorId>,
    pub ffn_down_exps: Option<TensorId>,
    pub ffn_up_exps: Option<TensorId>,
    /// shared expert
    pub ffn_gate_shexp: Option<TensorId>,
    pub ffn_down_shexp: Option<TensorId>,
    pub ffn_up_shexp: Option<TensorId>,
}

pub struct GraniteModelWeights {
    pub tok_embd: TensorId,
    pub output_norm: TensorId,
    pub output: TensorId,
    pub layers: Vec<GraniteLayerWeights>,
}

/// Granite-hybrid hparams (granite-hybrid.cpp:3-40) + the determinants of the
/// graph (mamba-base.cpp / llama-graph.cpp build_attn/build_ffn).
#[derive(Clone)]
pub struct GraniteParams {
    /// global attention/rope params (n_head/n_head_kv = the *attention* layer
    /// values; `builder` asserts the per-layer dims agree)
    pub attn: AttnParams,
    pub n_embd: i64,
    /// per-layer attention geometry (recurrent layers have n_head_kv == 0)
    pub n_head: Vec<u32>,
    pub n_head_kv: Vec<u32>,
    pub n_embd_head_k: Vec<u32>,
    pub n_embd_head_v: Vec<u32>,
    pub is_recr: Vec<bool>,
    pub has_rope: Vec<bool>,
    /// mamba2 (hparams.ssm_*)
    pub d_conv: i64,
    pub d_inner: i64,
    pub d_state: i64,
    pub n_ssm_head: i64,
    pub n_group: i64,
    /// granite scalars (granite-hybrid.cpp:4-9)
    pub f_logit_scale: f32,
    pub f_residual_scale: f32,
    pub f_embedding_scale: f32,
    /// 0.0 → 1/sqrt(n_embd_head) (granite-hybrid.cpp:225-226)
    pub f_attention_scale: f32,
    /// MoE (granite-hybrid.cpp:124-139)
    pub n_expert: i64,
    pub n_expert_used: Vec<u32>,
    pub n_ff_shexp: i64,
    pub expert_weights_scale: f32,
    /// hparams.n_embd_r (conv cell) / hparams.n_embd_s (SSM cell)
    pub n_embd_r: u32,
    pub n_embd_s: u32,
}

/// verify against src/models/granite-hybrid.cpp:143-198 `graph::graph` —
/// embedding scale → per layer (rms attn_norm → mamba2 mixer | attention) →
/// residual-scaled FFN (dense / MoE + shared expert) → final norm (logit
/// scale) → lm_head.
///
/// Notes / partial items (also in the agent report):
///   * the mamba2 mixer (`build_mamba2_layer`, mamba-base.cpp:153-302) runs the
///     full C chain: ssm_in projection → causal 1D conv (+bias, silu) →
///     ssm_scan → `+ x*D` → swiglu_split(z, ·) → grouped rms_norm → ssm_out.
///   * the recurrent state is a single cell (one sequence, K = 1): the C
///     rollback snapshots (`cparams.n_rs_seq`) and multi-sequence cells are not
///     modelled.
///   * `ggml_get_rows(inp_out_ids)` (the last-layer row pruning) is skipped —
///     it only shapes the output, the values are identical.
///   * rope freq factors (`get_rope_factors` != NULL) are not representable in
///     TensorMeta::src (see the module header) — granite-4.0-h-* sets
///     `rope.scaling.finetuned = false`, so `has_rope` is false and no rope
///     runs at all.
pub fn build_granite_forward(
    ctx: &mut Context,
    w: &GraniteModelWeights,
    p: &GraniteParams,
    st: &RecurrentState,
    kv: &KvCache,
    inp: &DecodeInputs,
    _sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(4096);
    assert_eq!(p.is_recr.len(), n_layer, "GraniteParams::is_recr per layer");
    assert_eq!(st.n_layer(), n_layer, "RecurrentState per layer");

    // inpL = build_inp_embd (llama-graph.cpp:2428-2440): embd lookup + the
    // Granite embedding scale; the lora delta of :2389-2405 lands before the
    // scale, so it is scaled with the embeddings exactly like the C
    let inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    let mut inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);
    if p.f_embedding_scale != 0.0 {
        inp_l = ctx.scale(inp_l, p.f_embedding_scale);
    }

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_sa = inp_l;

        // build_norm(LLM_NORM_RMS)
        let cur = build_norm_rms(ctx, inp_l, lw.attn_norm, p.norm_eps());

        let cur = if p.is_recr[il] {
            build_mamba2_layer(ctx, &mut graph, p, lw, st, il, cur, t)
        } else {
            build_granite_attention(ctx, &mut graph, p, lw, kv, inp, n_kv, cur, t, il)
        };

        inp_l = build_granite_ffn(ctx, &mut graph, p, lw, il, cur, inp_sa);
    }

    // final norm + lm_head + logit scale (granite-hybrid.cpp:186-195)
    // res->t_embd = cur (granite-hybrid.cpp:187) — before the lm_head
    let embd = build_norm_rms(ctx, inp_l, w.output_norm, p.norm_eps());
    let embd = graph::out_rows(ctx, embd, inp.out_ids);
    let mut cur = crate::adapter::lora_mm(ctx, w.output, embd);
    if p.f_logit_scale != 0.0 {
        cur = ctx.scale(cur, 1.0 / p.f_logit_scale);
    }
    graph.build_forward(ctx, cur);
    ForwardResult {
        logits: cur,
        graph,
        embd: Some(embd),
    }
}

impl GraniteParams {
    pub fn norm_eps(&self) -> f32 {
        self.attn.norm_eps
    }
}

/// build_mamba2_layer (mamba-base.cpp:153-302) — the granite recurrent mixer.
/// Delegates to the arch-independent [`build_mamba2_mixer`] (batch 5 lifted
/// the body verbatim so mamba2 / nemotron-h reuse it, exactly like the C
/// `llm_build_mamba_base::build_mamba2_layer` callers).
fn build_mamba2_layer(
    ctx: &mut Context,
    graph: &mut Graph,
    p: &GraniteParams,
    lw: &GraniteLayerWeights,
    st: &RecurrentState,
    il: usize,
    cur: TensorId,
    t: i64,
) -> TensorId {
    let mixer = Mamba2Mixer {
        ssm_in: lw.ssm_in.expect("ssm_in"),
        ssm_conv1d: lw.ssm_conv1d.expect("ssm_conv1d"),
        ssm_conv1d_b: lw.ssm_conv1d_b,
        ssm_dt_b: lw.ssm_dt_b.expect("ssm_dt_b"),
        ssm_a: lw.ssm_a.expect("ssm_a"),
        ssm_d: lw.ssm_d.expect("ssm_d"),
        ssm_norm: lw.ssm_norm,
        ssm_out: lw.ssm_out.expect("ssm_out"),
    };
    build_mamba2_mixer(
        ctx,
        graph,
        p.d_conv,
        p.d_inner,
        p.d_state,
        p.n_ssm_head,
        p.n_group,
        p.norm_eps(),
        &mixer,
        st,
        il,
        cur,
        t,
    )
}

/// The mamba2 mixer tensors of one layer — exactly the
/// `model.layers[il].ssm_*` reads of mamba-base.cpp:153-302.
pub struct Mamba2Mixer {
    pub ssm_in: TensorId,
    pub ssm_conv1d: TensorId,
    /// mamba2/granite-hybrid carry it (granite optional, mamba2 required);
    /// nemotron-h's is TENSOR_NOT_REQUIRED
    pub ssm_conv1d_b: Option<TensorId>,
    pub ssm_dt_b: TensorId,
    pub ssm_a: TensorId,
    pub ssm_d: TensorId,
    /// grouped RMS norm weight — present for every mamba2-variant arch
    pub ssm_norm: Option<TensorId>,
    pub ssm_out: TensorId,
}

/// `llm_build_mamba_base::build_mamba2_layer` (mamba-base.cpp:153-302), the
/// single-sequence (n_seqs == 1, K == 1) slice: conv state write-back, the
/// causal 1D conv (+bias, silu), the dt/B/C split, `ggml_ssm_scan`, the final
/// SSM state write-back, `+ x*D`, swiglu_split(z, ·), grouped rms_norm and the
/// out projection.
#[allow(clippy::too_many_arguments)]
fn build_mamba2_mixer(
    ctx: &mut Context,
    graph: &mut Graph,
    d_conv: i64,
    d_inner: i64,
    d_state: i64,
    n_head: i64,
    n_group: i64,
    norm_eps: f32,
    m: &Mamba2Mixer,
    st: &RecurrentState,
    il: usize,
    cur: TensorId,
    t: i64,
) -> TensorId {
    let head_dim = d_inner / n_head;
    let conv_dim = d_inner + 2 * n_group * d_state;
    let d_in_proj = 2 * d_inner + 2 * n_group * d_state + n_head;
    let one = ctx.new_i32(0); // ids {n_seqs=1}: single cell → slot 0

    // ggml_tensor * conv = build_rs(...); reshape_3d(d_conv - 1, conv_dim, n_seqs)
    let conv_state = st.conv[il].expect("recurrent conv state");
    let conv = ctx.reshape_3d(conv_state, d_conv - 1, conv_dim, 1);

    // {n_embd, d_in_proj} @ {n_embd, n_tokens} => {d_in_proj, n_tokens}
    let zx_bc_dt = crate::adapter::lora_mm(ctx, m.ssm_in, cur);
    let zx_bc_dt = ctx.reshape_3d(zx_bc_dt, d_in_proj, t, 1);

    // split in three (mamba-base.cpp:197-202)
    let zx_nb = *ctx.nb(zx_bc_dt);
    let z = ctx.view_4d(
        zx_bc_dt,
        head_dim,
        n_head,
        t,
        1,
        (head_dim * 4) as usize,
        zx_nb[1] as usize,
        zx_nb[2] as usize,
        0,
    );
    let xbc = ctx.view_3d(
        zx_bc_dt,
        conv_dim,
        t,
        1,
        zx_nb[1] as usize,
        zx_nb[2] as usize,
        d_inner as usize * 4,
    );
    let dt = ctx.view_3d(
        zx_bc_dt,
        n_head,
        t,
        1,
        zx_nb[1] as usize,
        zx_nb[2] as usize,
        (2 * d_inner + 2 * n_group * d_state) as usize * 4,
    );

    // conv block: state write-back + ssm_conv + bias + silu (mamba-base.cpp:204-238)
    let xbc = {
        let xbc_t = ctx.transpose(xbc);
        let conv_x = ctx.concat(conv, xbc_t, 0);
        let cx_nb = *ctx.nb(conv_x);
        let row_count = (d_conv - 1) * conv_dim;

        // last (d_conv - 1) columns → the state cell (K = 1 → slot 0)
        let last_conv = ctx.view_3d(
            conv_x,
            d_conv - 1,
            conv_dim,
            1,
            cx_nb[1] as usize,
            cx_nb[2] as usize,
            t as usize * cx_nb[0] as usize,
        );
        let state_nb = *ctx.nb(conv_state);
        let state_dst = ctx.view_2d(conv_state, row_count, 1, state_nb[1] as usize, 0);
        let cpy = ctx.cpy(last_conv, state_dst);
        graph.build_forward(ctx, cpy);

        let mut xbc = ctx.ssm_conv(conv_x, m.ssm_conv1d);
        if let Some(b) = m.ssm_conv1d_b {
            xbc = ctx.add(xbc, b);
        }
        ctx.silu(xbc)
    };

    // ssm block (mamba-base.cpp:240-300)
    let xbc_nb = *ctx.nb(xbc);
    let x = ctx.view_4d(
        xbc,
        head_dim,
        n_head,
        t,
        1,
        (head_dim * 4) as usize,
        xbc_nb[1] as usize,
        xbc_nb[2] as usize,
        0,
    );
    let b4 = ctx.view_4d(
        xbc,
        d_state,
        n_group,
        t,
        1,
        (d_state * 4) as usize,
        xbc_nb[1] as usize,
        xbc_nb[2] as usize,
        d_inner as usize * 4,
    );
    let c4 = ctx.view_4d(
        xbc,
        d_state,
        n_group,
        t,
        1,
        (d_state * 4) as usize,
        xbc_nb[1] as usize,
        xbc_nb[2] as usize,
        (d_inner + n_group * d_state) as usize * 4,
    );

    // dt = add(cont(dt), ssm_dt_b)
    let dt = ctx.cont(dt);
    let dt = ctx.add(dt, m.ssm_dt_b);

    let ssm_state = st.ssm[il].expect("recurrent ssm state");
    let ssm_view = ctx.reshape_4d(ssm_state, d_state, head_dim, n_head, 1);
    let y_ssm = ctx.ssm_scan(ssm_view, x, dt, m.ssm_a, b4, c4, one, 1);

    // store the final state: cpy(view of y_ssm's state part → ssm_states_all)
    {
        let d = d_state * d_inner;
        let state_src = ctx.view_3d(
            y_ssm,
            d,
            1,
            1,
            (d * 4) as usize,
            (d * 4) as usize,
            (t * d_inner) as usize * 4,
        );
        let st_nb = *ctx.nb(ssm_state);
        let state_dst = ctx.view_2d(ssm_state, d, 1, st_nb[1] as usize, 0);
        let cpy = ctx.cpy(state_src, state_dst);
        graph.build_forward(ctx, cpy);
    }

    // y = view_4d(y_ssm, ...) ; y += x * ssm_d ; y = swiglu_split(cont(z), y)
    let y = ctx.view_4d(
        y_ssm,
        head_dim,
        n_head,
        t,
        1,
        (head_dim * 4) as usize,
        (n_head * head_dim * 4) as usize,
        (t * n_head * head_dim * 4) as usize,
        0,
    );
    let xd = ctx.mul(x, m.ssm_d);
    let y = ctx.add(y, xd);
    // NB: z must be contiguous for the GLU (ggml_glu_impl asserts contiguous_1)
    let zc = ctx.cont(z);
    let mut y = ctx.swiglu_split(zc, y);

    // grouped rms_norm then out_proj (mamba-base.cpp:290-299)
    if let Some(norm_w) = m.ssm_norm {
        let y4 = ctx.reshape_4d(y, d_inner / n_group, n_group, t, 1);
        y = build_norm_rms(ctx, y4, norm_w, norm_eps);
    }
    let y = ctx.reshape_2d(y, d_inner, t);
    crate::adapter::lora_mm(ctx, m.ssm_out, y)
}

/// granite-hybrid.cpp:200-241 `build_attention_layer`.
#[allow(clippy::too_many_arguments)]
fn build_granite_attention(
    ctx: &mut Context,
    graph: &mut Graph,
    p: &GraniteParams,
    lw: &GraniteLayerWeights,
    kv: &KvCache,
    inp: &DecodeInputs,
    n_kv: u32,
    cur: TensorId,
    t: i64,
    il: usize,
) -> TensorId {
    let a = &p.attn;
    // build_qkv (llama-graph.cpp:1687-1735, build_lora_mm at
    // :1689/1703/1717): plain mul_mat. granite calls
    // `create_tensor_qkv(..., 0)` — no q/k/v biases are loaded (the C
    // build_qkv bias branches are therefore dead for this arch). The loader
    // rejects a fused `attn_qkv.weight` granite/minicpm file up front (no
    // real file carries one), so only the separate branch exists here.
    let q = crate::adapter::lora_mm(ctx, lw.wq.expect("wq"), cur);
    let k = crate::adapter::lora_mm(ctx, lw.wk.expect("wk"), cur);
    let v = crate::adapter::lora_mm(ctx, lw.wv.expect("wv"), cur);
    let q = ctx.reshape_3d(q, a.n_embd_head_k, a.n_head, t);
    let k = ctx.reshape_3d(k, a.n_embd_head_k, a.n_head_kv, t);
    let v = ctx.reshape_3d(v, a.n_embd_head_v, a.n_head_kv, t);

    // rope only when hparams.has_rope(il) (granite-hybrid.cpp:213-224)
    let (q, k) = if p.has_rope[il] {
        let rf = lw.rope_freqs;
        let q = ctx.rope_ext(
            q,
            inp.pos,
            rf,
            a.n_rot as i32,
            a.rope_mode,
            a.n_ctx_orig,
            a.freq_base,
            a.freq_scale,
            a.ext_factor,
            a.attn_factor,
            a.beta_fast,
            a.beta_slow,
        );
        let k = ctx.rope_ext(
            k,
            inp.pos,
            rf,
            a.n_rot as i32,
            a.rope_mode,
            a.n_ctx_orig,
            a.freq_base,
            a.freq_scale,
            a.ext_factor,
            a.attn_factor,
            a.beta_fast,
            a.beta_slow,
        );
        (q, k)
    } else {
        (q, k)
    };

    let n_embd_head = a.n_embd_head_v;
    let kq_scale = if p.f_attention_scale == 0.0 {
        1.0 / (n_embd_head as f32).sqrt()
    } else {
        p.f_attention_scale
    };
    attn_kv_cached(
        ctx,
        graph,
        kv,
        il,
        a,
        inp,
        n_kv,
        q,
        k,
        v,
        kq_scale,
        0.0,
        None,
        None,
        Some(lw.wo.expect("wo")),
        lw.wo_b,
    )
}

/// granite-hybrid.cpp:244-302 `build_layer_ffn` — residual scaling + dense /
/// MoE(+shared expert) FFN + second residual scale.
fn build_granite_ffn(
    ctx: &mut Context,
    graph: &mut Graph,
    p: &GraniteParams,
    lw: &GraniteLayerWeights,
    il: usize,
    cur: TensorId,
    inp_sa: TensorId,
) -> TensorId {
    let cur = if p.f_residual_scale != 0.0 {
        ctx.scale(cur, p.f_residual_scale)
    } else {
        cur
    };
    let ffn_inp = ctx.add(cur, inp_sa);

    let normed = build_norm_rms(ctx, ffn_inp, lw.ffn_norm, p.norm_eps());

    let cur = if let Some(gate_inp) = lw.ffn_gate_inp {
        // MoE branch: build_moe_ffn(cur, gate_inp, up_exps, gate_exps, down_exps,
        // nullptr, n_expert, n_expert_used, LLM_FFN_SILU, norm_w = true,
        // expert_weights_scale, LLAMA_EXPERT_GATING_FUNC_TYPE_SOFTMAX, il)
        let n_expert = p.n_expert;
        let n_expert_used = p.n_expert_used.get(il).copied().unwrap_or(0) as i64;
        let moe = build_moe_ffn_silu(
            ctx,
            graph,
            normed,
            gate_inp,
            None,
            lw.ffn_up_exps.expect("ffn_up_exps"),
            None,
            lw.ffn_gate_exps,
            None,
            lw.ffn_down_exps.expect("ffn_down_exps"),
            None,
            None,
            n_expert,
            n_expert_used,
            true,
            p.expert_weights_scale,
            EXPERT_GATING_SOFTMAX,
        );
        if p.n_ff_shexp > 0 {
            let shexp = build_ffn_silu_par(
                ctx,
                normed,
                lw.ffn_gate_shexp.expect("ffn_gate_shexp"),
                None,
                lw.ffn_up_shexp.expect("ffn_up_shexp"),
                None,
                lw.ffn_down_shexp.expect("ffn_down_shexp"),
                None,
            );
            ctx.add(moe, shexp)
        } else {
            moe
        }
    } else {
        build_ffn_silu_par(
            ctx,
            normed,
            lw.ffn_gate.expect("ffn_gate"),
            lw.ffn_gate_b,
            lw.ffn_up.expect("ffn_up"),
            lw.ffn_up_b,
            lw.ffn_down.expect("ffn_down"),
            lw.ffn_down_b,
        )
    };

    let cur = if p.f_residual_scale != 0.0 {
        ctx.scale(cur, p.f_residual_scale)
    } else {
        cur
    };
    ctx.add(cur, ffn_inp)
}

// ======================================================================
// shared MoE helper — llama-graph.cpp:1993-2360 build_moe_ffn (SILU path)
// ======================================================================

/// llama_expert_gating_func_type (llama.h): the two the granite/lfm2 graphs use
pub const EXPERT_GATING_SOFTMAX: i32 = 1;
pub const EXPERT_GATING_SIGMOID: i32 = 2;
pub const EXPERT_GATING_SOFTMAX_WEIGHT: i32 = 3;

/// build_moe_ffn (llama-graph.cpp:1993-2360) for `LLM_FFN_SILU`, the
/// `SOFTMAX` / `SOFTMAX_WEIGHT` gating functions and the optional
/// `exp_probs_b` selection bias (DeepSeek-V3 style — lfm2moe sets it):
///
///   1. logits = gate_inp @ cur (+bias)
///   2. probs  = soft_max(logits)                     [SOFTMAX]
///      probs  = logits                               [SOFTMAX_WEIGHT]
///   3. selection_probs = probs (+ exp_probs_b)  ← the *bias* only steers the
///      top-k, the weights are read from the unbiased `probs`
///   4. selected = argsort_top_k(selection_probs, n_expert_used)
///   5. weights = get_rows(reshape_3d(probs, 1, n_expert, n_tokens), selected)
///      [SOFTMAX_WEIGHT: + soft_max over the k selected weights]
///   6. norm_w: weights /= clamp(sum_rows(weights), 6.103515625e-5, INF)
///   7. w_scale (skipped when 0 or 1)
///   8. up/gate experts → swiglu_split → down experts → `* weights`
///   9. sum the n_expert_used strided views (llama-graph.cpp:2329-2358)
///
/// NB: `n_expert_used` (the top-k width) and the per-layer
/// `hparams.n_expert_used(il)` are the same value for granite/lfm2.
#[allow(clippy::too_many_arguments)]
fn build_moe_ffn_silu(
    ctx: &mut Context,
    graph: &mut Graph,
    cur: TensorId,
    gate_inp: TensorId,
    gate_inp_b: Option<TensorId>,
    up_exps: TensorId,
    up_exps_b: Option<TensorId>,
    gate_exps: Option<TensorId>,
    gate_exps_b: Option<TensorId>,
    down_exps: TensorId,
    down_exps_b: Option<TensorId>,
    exp_probs_b: Option<TensorId>,
    n_expert: i64,
    n_expert_used: i64,
    norm_w: bool,
    w_scale: f32,
    gating_op: i32,
) -> TensorId {
    let n_embd = ctx.ne(cur)[0];
    let n_tokens = ctx.ne(cur)[1];

    let mut logits = crate::adapter::lora_mm(ctx, gate_inp, cur); // [n_expert, n_tokens]
    if let Some(b) = gate_inp_b {
        logits = ctx.add(logits, b);
    }
    let probs = match gating_op {
        EXPERT_GATING_SOFTMAX => ctx.soft_max(logits),
        EXPERT_GATING_SIGMOID => ctx.sigmoid(logits),
        EXPERT_GATING_SOFTMAX_WEIGHT => logits,
        other => unimplemented!("build_moe_ffn: gating op {other}"),
    };

    // selection bias (llama-graph.cpp:2063-2067) — steers the top-k only
    let selection_probs = match exp_probs_b {
        Some(b) => ctx.add(probs, b),
        None => probs,
    };

    let selected = ctx.argsort_top_k(selection_probs, n_expert_used as i32);

    let probs3 = ctx.reshape_3d(probs, 1, n_expert, n_tokens);
    let mut weights = ctx.get_rows(probs3, selected); // [1, k, n_tokens]

    if gating_op == EXPERT_GATING_SOFTMAX_WEIGHT {
        let w2 = ctx.reshape_2d(weights, n_expert_used, n_tokens);
        let w2 = ctx.soft_max(w2);
        weights = ctx.reshape_3d(w2, 1, n_expert_used, n_tokens);
    }

    if norm_w {
        let w2 = ctx.reshape_2d(weights, n_expert_used, n_tokens);
        let sum = ctx.sum_rows(w2); // [1, n_tokens]
        let sum = ctx.clamp(sum, 6.103515625e-5, f32::INFINITY);
        let w2 = ctx.div(w2, sum);
        weights = ctx.reshape_3d(w2, 1, n_expert_used, n_tokens);
    }
    if w_scale != 0.0 && w_scale != 1.0 {
        weights = ctx.scale(weights, w_scale);
    }
    graph.build_forward(ctx, weights);

    let cur3 = ctx.reshape_3d(cur, n_embd, 1, n_tokens);
    let mut up = crate::adapter::lora_mm_id(ctx, up_exps, cur3, selected);
    if let Some(b) = up_exps_b {
        up = ctx.add_id(up, b, selected);
    }
    let gate = gate_exps.map(|ge| {
        let mut g = crate::adapter::lora_mm_id(ctx, ge, cur3, selected);
        if let Some(b) = gate_exps_b {
            g = ctx.add_id(g, b, selected);
        }
        g
    });
    let act = match gate {
        Some(g) => ctx.swiglu_split(g, up),
        None => ctx.silu(up),
    };
    let mut experts = crate::adapter::lora_mm_id(ctx, down_exps, act, selected);
    if let Some(b) = down_exps_b {
        experts = ctx.add_id(experts, b, selected);
    }
    let experts = ctx.mul(experts, weights);
    graph.build_forward(ctx, experts);

    // aggregate the k expert views (llama-graph.cpp:2329-2358)
    let nb1 = ctx.nb(experts)[1] as usize;
    let nb2 = ctx.nb(experts)[2] as usize;
    let mut moe_out = ctx.view_2d(experts, n_embd, n_tokens, nb2, 0);
    graph.build_forward(ctx, moe_out);
    for i in 1..n_expert_used as usize {
        let vi = ctx.view_2d(experts, n_embd, n_tokens, nb2, i * nb1);
        graph.build_forward(ctx, vi);
        moe_out = ctx.add(moe_out, vi);
        graph.build_forward(ctx, moe_out);
    }
    if n_expert_used == 1 {
        moe_out = ctx.cont(moe_out);
    }
    moe_out
}

// ======================================================================
// lfm2moe — verify against src/models/lfm2moe.cpp → lfm2.cpp graph<> (shared code)
// ======================================================================

/// Per-layer weights (lfm2moe.cpp:44-80 load_arch_tensors).
pub struct Lfm2LayerWeights {
    pub attn_norm: TensorId,
    /// recurrent (shortconv) layers
    pub shortconv_conv: Option<TensorId>,
    pub shortconv_in_proj: Option<TensorId>,
    pub shortconv_out_proj: Option<TensorId>,
    /// attention layers
    pub wq: Option<TensorId>,
    pub wk: Option<TensorId>,
    pub wv: Option<TensorId>,
    pub wo: Option<TensorId>,
    pub attn_q_norm: Option<TensorId>,
    pub attn_k_norm: Option<TensorId>,
    pub wq_b: Option<TensorId>,
    pub wk_b: Option<TensorId>,
    pub wv_b: Option<TensorId>,
    /// FFN (dense lead layers)
    pub ffn_norm: TensorId,
    pub ffn_gate: Option<TensorId>,
    pub ffn_down: Option<TensorId>,
    pub ffn_up: Option<TensorId>,
    /// MoE layers
    pub ffn_gate_inp: Option<TensorId>,
    pub ffn_gate_exps: Option<TensorId>,
    pub ffn_down_exps: Option<TensorId>,
    pub ffn_up_exps: Option<TensorId>,
    pub ffn_exp_probs_b: Option<TensorId>,
}

pub struct Lfm2ModelWeights {
    pub tok_embd: TensorId,
    /// `token_embd_norm` (LLM_TENSOR_OUTPUT_NORM_LFM2)
    pub output_norm: TensorId,
    pub output: TensorId,
    pub layers: Vec<Lfm2LayerWeights>,
}

#[derive(Clone)]
pub struct Lfm2Params {
    /// global attention/rope params (n_head_kv = the attention layer value)
    pub attn: AttnParams,
    pub n_embd: i64,
    pub n_head: Vec<u32>,
    pub n_head_kv: Vec<u32>,
    pub n_embd_head_k: Vec<u32>,
    pub n_embd_head_v: Vec<u32>,
    pub is_recr: Vec<bool>,
    /// n_shortconv_l_cache (lfm2moe.cpp:6)
    pub n_shortconv_l_cache: i64,
    pub n_layer_dense_lead: u32,
    pub n_expert: i64,
    pub n_expert_used: Vec<u32>,
    pub n_ff_exp: u32,
    pub expert_weights_scale: f32,
    pub expert_gating_func: i32,
    /// hparams.causal_attn (lfm2.cpp:21): the shortconv block's window layout
    pub causal_attn: bool,
    /// hparams.n_embd_r == n_embd * (n_shortconv_l_cache - 1)
    pub n_embd_r: u32,
}

/// verify against src/models/lfm2moe.cpp `build_arch_graph` → lfm2.cpp:100-295
/// `graph<>::graph`:
///   per layer: rms `operator_norm` → (shortconv block | gated attention
///   block) → residual → `ffn_norm` → (dense FFN | MoE) → residual;
///   final `token_embd_norm` → tied lm_head.
///
/// PARTIAL: the non-causal shortconv branch (lfm2.cpp:200-205, `ggml_pad_ext`)
/// is not ported — `hparams.causal_attn` is asserted instead. SWA is wired
/// through `attn_kv_cached` like every other builder (the per-layer cache/mask
/// selection of llama-graph.cpp:3131-3133), so an lfm2 file with
/// `attention.sliding_window` is exact once its driver creates the `iswa` pair
/// (`DecodeContext::new_with_swa`).
pub fn build_lfm2_forward(
    ctx: &mut Context,
    w: &Lfm2ModelWeights,
    p: &Lfm2Params,
    st: &RecurrentState,
    kv: &KvCache,
    inp: &DecodeInputs,
    _sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(4096);
    assert_eq!(p.is_recr.len(), n_layer, "Lfm2Params::is_recr per layer");
    assert!(
        p.causal_attn,
        "lfm2 non-causal shortconv (ggml_pad_ext) not ported"
    );

    let mut cur = ctx.get_rows(w.tok_embd, inp.tokens);
    // build_inp_embd's lora delta (llama-graph.cpp:2389-2405)
    cur = crate::adapter::lora_embd(ctx, w.tok_embd, cur, inp.tokens);

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let prev_cur = cur;

        // build_norm(cur, attn_norm, LLM_NORM_RMS) — "operator_norm"
        cur = build_norm_rms(ctx, cur, lw.attn_norm, p.attn.norm_eps);

        cur = if p.is_recr[il] {
            build_shortconv_block(ctx, &mut graph, p, lw, st, il, cur, t)
        } else {
            build_lfm2_attention(ctx, &mut graph, p, lw, kv, inp, n_kv, cur, t, il)
        };

        cur = ctx.add(prev_cur, cur);

        // ffn (lfm2.cpp:270-277)
        let normed = build_norm_rms(ctx, cur, lw.ffn_norm, p.attn.norm_eps);
        let is_moe_layer = il >= p.n_layer_dense_lead as usize;
        let ffn_out = if is_moe_layer {
            build_moe_ffn_silu(
                ctx,
                &mut graph,
                normed,
                lw.ffn_gate_inp.expect("ffn_gate_inp"),
                None,
                lw.ffn_up_exps.expect("ffn_up_exps"),
                None,
                lw.ffn_gate_exps,
                None,
                lw.ffn_down_exps.expect("ffn_down_exps"),
                None,
                lw.ffn_exp_probs_b,
                p.n_expert,
                p.n_expert_used.get(il).copied().unwrap_or(0) as i64,
                true,
                p.expert_weights_scale,
                p.expert_gating_func,
            )
        } else {
            build_ffn_silu_par(
                ctx,
                normed,
                lw.ffn_gate.expect("ffn_gate"),
                None,
                lw.ffn_up.expect("ffn_up"),
                None,
                lw.ffn_down.expect("ffn_down"),
                None,
            )
        };
        cur = ctx.add(cur, ffn_out);
    }

    // token_embd_norm + tied output (lfm2.cpp:283-292, build_lora_mm at :288)
    let cur = build_norm_rms(ctx, cur, w.output_norm, p.attn.norm_eps);
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let logits = crate::adapter::lora_mm(ctx, w.output, cur);
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

/// lfm2.cpp:159-228 `build_shortconv_block` — the LFM2 conv mixer with the
/// rolling conv state (d_conv == l_cache - 1 history rows).
fn build_shortconv_block(
    ctx: &mut Context,
    graph: &mut Graph,
    p: &Lfm2Params,
    lw: &Lfm2LayerWeights,
    st: &RecurrentState,
    il: usize,
    cur: TensorId,
    t: i64,
) -> TensorId {
    let n_embd = p.n_embd;
    assert!(p.n_shortconv_l_cache > 1, "n_shortconv_l_cache must be > 1");
    let d_conv = p.n_shortconv_l_cache - 1;

    // {n_embd, n_tokens} => {n_embd, n_seq_tokens, n_seqs}
    let cur = ctx.reshape_3d(cur, n_embd, t, 1);

    let bcx = crate::adapter::lora_mm(ctx, lw.shortconv_in_proj.expect("shortconv_in_proj"), cur);
    let bcx_nb = *ctx.nb(bcx);
    let chunk = n_embd;
    let view = |ctx: &mut Context, off: i64| {
        ctx.view_3d(
            bcx,
            chunk,
            t,
            1,
            bcx_nb[1] as usize,
            bcx_nb[2] as usize,
            off as usize * 4,
        )
    };
    let b = view(ctx, 0);
    let c = view(ctx, chunk);
    let x = view(ctx, 2 * chunk);

    // bx = transpose(b * x) — {n_embd, t} → {t, n_embd}
    let bx_mul = ctx.mul(b, x);
    let bx = ctx.transpose(bx_mul);

    // conv state: reshape_3d(build_rs(...), d_conv, n_embd, n_seqs)
    let conv_state = st.conv[il].expect("recurrent conv state");
    let conv = ctx.reshape_3d(conv_state, d_conv, n_embd, 1);

    // causal: prepend the state (lfm2.cpp:196-198)
    let bx = ctx.concat(conv, bx, 0);

    // write the state back: slot 0 = the final state (K = 1)
    {
        let bx_nb = *ctx.nb(bx);
        let bx_ne0 = ctx.ne(bx)[0];
        let snap = ctx.view_3d(
            bx,
            d_conv,
            n_embd,
            1,
            bx_nb[1] as usize,
            bx_nb[2] as usize,
            (bx_ne0 - d_conv) as usize * 4,
        );
        let st_nb = *ctx.nb(conv_state);
        let dst = ctx.view_2d(conv_state, d_conv * n_embd, 1, st_nb[1] as usize, 0);
        let cpy = ctx.cpy(snap, dst);
        graph.build_forward(ctx, cpy);
    }

    // conv_out = ggml_ssm_conv(bx, shortconv.conv); y = c * conv_out
    let conv_out = ctx.ssm_conv(bx, lw.shortconv_conv.expect("shortconv_conv"));
    let y = ctx.mul(c, conv_out);
    let y = crate::adapter::lora_mm(ctx, lw.shortconv_out_proj.expect("shortconv_out_proj"), y);
    ctx.reshape_2d(y, n_embd, t)
}

/// lfm2.cpp:118-157 `build_attn_block` — gated attention with per-head q/k RMS
/// norms and rope.
#[allow(clippy::too_many_arguments)]
fn build_lfm2_attention(
    ctx: &mut Context,
    graph: &mut Graph,
    p: &Lfm2Params,
    lw: &Lfm2LayerWeights,
    kv: &KvCache,
    inp: &DecodeInputs,
    n_kv: u32,
    cur: TensorId,
    t: i64,
    il: usize,
) -> TensorId {
    let a = &p.attn;
    let n_embd_head = a.n_embd_head_v;
    assert_eq!(
        a.n_embd_head_k, n_embd_head,
        "lfm2: n_embd_k_gqa == n_embd_v_gqa"
    );

    let mut q = crate::adapter::lora_mm(ctx, lw.wq.expect("wq"), cur);
    let mut k = crate::adapter::lora_mm(ctx, lw.wk.expect("wk"), cur);
    let mut v = crate::adapter::lora_mm(ctx, lw.wv.expect("wv"), cur);
    if let Some(b) = lw.wq_b {
        q = ctx.add(q, b);
    }
    if let Some(b) = lw.wk_b {
        k = ctx.add(k, b);
    }
    if let Some(b) = lw.wv_b {
        v = ctx.add(v, b);
    }
    let q = ctx.reshape_3d(q, a.n_embd_head_k, a.n_head, t);
    let k = ctx.reshape_3d(k, a.n_embd_head_k, a.n_head_kv, t);
    let v = ctx.reshape_3d(v, a.n_embd_head_v, a.n_head_kv, t);

    // qk norm (lfm2.cpp:129-132)
    let q = build_norm_rms(ctx, q, lw.attn_q_norm.expect("attn_q_norm"), a.norm_eps);
    let k = build_norm_rms(ctx, k, lw.attn_k_norm.expect("attn_k_norm"), a.norm_eps);

    // rope (lfm2.cpp:134-139)
    let q = ctx.rope_ext(
        q,
        inp.pos,
        None,
        a.n_rot as i32,
        a.rope_mode,
        a.n_ctx_orig,
        a.freq_base,
        a.freq_scale,
        a.ext_factor,
        a.attn_factor,
        a.beta_fast,
        a.beta_slow,
    );
    let k = ctx.rope_ext(
        k,
        inp.pos,
        None,
        a.n_rot as i32,
        a.rope_mode,
        a.n_ctx_orig,
        a.freq_base,
        a.freq_scale,
        a.ext_factor,
        a.attn_factor,
        a.beta_fast,
        a.beta_slow,
    );

    let kq_scale = 1.0 / (n_embd_head as f32).sqrt();
    attn_kv_cached(
        ctx,
        graph,
        kv,
        il,
        a,
        inp,
        n_kv,
        q,
        k,
        v,
        kq_scale,
        0.0,
        None,
        None,
        Some(lw.wo.expect("wo")),
        None,
    )
}

