// bert — verify against src/models/bert.cpp:64-221 llama_model_bert::graph
// ======================================================================

/// Per-layer weights of the `LLM_ARCH_BERT` branch (bert.cpp:43-61). The
/// jina-bert variants share the loop but need members this port does not load
/// (`attn_q_norm`/`attn_k_norm`, `attn_norm_2`, the MoE branch) — see the
/// builder's doc.
pub struct BertLayerWeights {
    /// separate Q/K/V (`create_tensor_qkv` falls back to these when the file
    /// has no fused `attn_qkv`; bge-m3 has none) — bert.cpp:46
    pub wq: TensorId,
    pub wk: TensorId,
    pub wv: TensorId,
    pub wq_b: Option<TensorId>,
    pub wk_b: Option<TensorId>,
    pub wv_b: Option<TensorId>,
    pub wo: TensorId,
    pub wo_b: Option<TensorId>,
    /// post-attention layer norm (bert.cpp:51-52)
    pub attn_out_norm: TensorId,
    pub attn_out_norm_b: TensorId,
    /// FFN up/down with biases (bert.cpp:54-57)
    pub ffn_up: TensorId,
    pub ffn_up_b: Option<TensorId>,
    pub ffn_down: TensorId,
    pub ffn_down_b: Option<TensorId>,
    /// final per-layer norm (bert.cpp:59-60)
    pub layer_out_norm: TensorId,
    pub layer_out_norm_b: TensorId,
}

pub struct BertModelWeights {
    pub tok_embd: TensorId,
    /// `type_embd` = `token_types.weight` [n_embd, n_token_types]
    /// (bert.cpp:30); optional, and row 0 only (bert.cpp:85-88)
    pub type_embd: Option<TensorId>,
    /// `pos_embd` = `position_embd.weight` [n_embd, n_ctx_train] (bert.cpp:32)
    pub pos_embd: TensorId,
    /// `tok_norm` / `tok_norm_b` (bert.cpp:40-41) — the embedding layer norm,
    /// the only model-level norm the BERT file carries
    pub tok_norm: TensorId,
    pub tok_norm_b: TensorId,
    pub layers: Vec<BertLayerWeights>,
    pub n_embd: i64,
}

/// verify against src/models/bert.cpp:68-221 — token + type + position embeddings,
/// embedding layer norm, then per layer: MHA with biases and
/// `1/sqrt(n_embd_head)` scale, residual, post-attention layer norm, GELU
/// feed-forward (sequential, bert.cpp:181-185), residual, output layer norm.
/// `res->t_embd` is the raw last hidden state (bert.cpp:218) — pooling is a
/// separate step (`build_pooling`).
///
/// Not ported, all dead for `LLM_ARCH_BERT` (the branches are keyed on other
/// archs): the jina q/k norms (bert.cpp:109-123, only loaded by
/// jina-bert-v3), RoPE (bert.cpp:126-133), `attn_norm_2` (bert.cpp:156-159),
/// the MoE branch (bert.cpp:165-178), the jina-bert-v2 GEGLU branch
/// (bert.cpp:187-195) and the `LLM_ARCH_NOMIC_BERT*` FFN (bert.cpp:179-186 —
/// the plain `LLM_ARCH_BERT` arm is the sequential-GELU one below).
/// The non-FA branch of build_attn_mha is used: with `cparams.flash_attn`
/// (the reference default is AUTO → enabled) the C would instead cast k/v to
/// F16 and run ggml_flash_attn_ext (llama-graph.cpp:2626-2669) — the port has
/// no `cast` op, and the reference dump is anchored to FA off like the decode
/// path.
pub fn build_bert_forward(
    ctx: &mut Context,
    w: &BertModelWeights,
    p: &EncoderParams,
    inp: &EncodeInputs,
    n_tokens: usize,
) -> EncodeResult {
    let t = n_tokens as i64;
    // C asserts n_embd_head_v == n_embd_head_k (bert.cpp:71); the port keeps a
    // single `n_embd_head` because that assert is what the loader enforces.
    let n_embd_head = p.n_embd_head;
    let mut graph = Graph::new(1024);

    // inpL = build_inp_embd(model.tok_embd) (bert.cpp:82)
    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);

    // token types are hardcoded to zero ("Sentence A") — bert.cpp:85-88: a
    // 1-D view of row 0 of type_embd, added (broadcast) to every token
    if let Some(te) = w.type_embd {
        let type_row0 = ctx.view_1d(te, w.n_embd, 0);
        inp_l = ctx.add(inp_l, type_row0);
    }
    // absolute position embeddings (bert.cpp:89-91)
    let pos = inp.pos.expect("bert: build_inp_pos");
    let pos_row = ctx.get_rows(w.pos_embd, pos);
    inp_l = ctx.add(pos_row, inp_l);

    // embed layer norm (bert.cpp:95, build_norm LLM_NORM → f_norm_eps)
    let mut inp_l = build_norm(
        ctx,
        inp_l,
        Some(w.tok_norm),
        Some(w.tok_norm_b),
        p.f_norm_eps,
    );

    let mut layer_outs = Vec::with_capacity(w.layers.len());
    let n_layer = w.layers.len();
    for il in 0..n_layer {
        let lw = &w.layers[il];
        let mut cur = inp_l;

        // build_qkv separate path with biases (llama-graph.cpp:1687-1735,
        // build_lora_mm at :1689/1703/1717) —
        // no q/k norms, no rope for this arch
        let mut q = crate::adapter::lora_mm(ctx, lw.wq, cur);
        if let Some(b) = lw.wq_b {
            q = ctx.add(q, b);
        }
        let mut k = crate::adapter::lora_mm(ctx, lw.wk, cur);
        if let Some(b) = lw.wk_b {
            k = ctx.add(k, b);
        }
        let mut v = crate::adapter::lora_mm(ctx, lw.wv, cur);
        if let Some(b) = lw.wv_b {
            v = ctx.add(v, b);
        }
        let q = ctx.reshape_3d(q, n_embd_head, p.n_head, t);
        let k = ctx.reshape_3d(k, n_embd_head, p.n_head_kv, t);
        let v = ctx.reshape_3d(v, n_embd_head, p.n_head_kv, t);

        // build_attn (bert.cpp:139-141) with kq_scale = 1/sqrt(n_embd_head)
        let kq_scale = 1.0 / (n_embd_head as f32).sqrt();
        cur = attn_no_cache(
            ctx,
            q,
            k,
            v,
            None,
            inp.kq_mask,
            kq_scale,
            Some(lw.wo),
            lw.wo_b,
        );

        // last-layer output-row selection (bert.cpp:145-148) — the identity
        // row set for `encode` (see EncodeInputs::out_ids)
        if il == n_layer - 1 {
            cur = ctx.get_rows(cur, inp.out_ids);
            inp_l = ctx.get_rows(inp_l, inp.out_ids);
        }

        // re-add the layer input (bert.cpp:151)
        let mut cur = ctx.add(cur, inp_l);

        // attention layer norm (bert.cpp:154, LLM_NORM)
        cur = build_norm(
            ctx,
            cur,
            Some(lw.attn_out_norm),
            Some(lw.attn_out_norm_b),
            p.f_norm_eps,
        );

        let ffn_inp = cur;

        // feed-forward: build_ffn LLM_FFN_GELU + LLM_FFN_SEQ (bert.cpp:181-185,
        // build_lora_mm at llama-graph.cpp:1926)
        // = mul_mat(up) + bias → gelu → mul_mat(down) + bias
        let mut tmp = crate::adapter::lora_mm(ctx, lw.ffn_up, cur);
        if let Some(b) = lw.ffn_up_b {
            tmp = ctx.add(tmp, b);
        }
        let tmp = ctx.gelu(tmp);
        let mut ffn = crate::adapter::lora_mm(ctx, lw.ffn_down, tmp);
        if let Some(b) = lw.ffn_down_b {
            ffn = ctx.add(ffn, b);
        }

        // attentions bypass the intermediate layer (bert.cpp:206)
        let cur = ctx.add(ffn, ffn_inp);

        // output layer norm (bert.cpp:209, LLM_NORM)
        let cur = build_norm(
            ctx,
            cur,
            Some(lw.layer_out_norm),
            Some(lw.layer_out_norm_b),
            p.f_norm_eps,
        );

        inp_l = cur;
        layer_outs.push(cur);
    }

    // res->t_embd = cur (bert.cpp:215-218)
    graph.build_forward(ctx, inp_l);
    EncodeResult {
        embd: inp_l,
        layer_outs,
        graph,
    }
}

// ======================================================================
// the bert variants — src/models/{jina-bert-v2,jina-bert-v3,nomic-bert,
// nomic-bert-moe}.cpp, whose `using graph = llama_model_bert::graph`
// (models.h) instantiates the SAME bert.cpp:68-221 body with the arch-keyed
// branches live. This builder is that body with every branch ported; the
// plain LLM_ARCH_BERT arm stays on build_bert_forward above (its anchors).
// ======================================================================

/// Which arch's branches of the shared bert.cpp graph body to take.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum BertVariant {
    /// `LLM_ARCH_JINA_BERT_V2` — no inp_pos (bert.cpp:77-79), ALiBi
    /// (jina-bert-v2.cpp:5 f_max_alibi_bias = 8.0), q/k norms + attn_norm_2
    /// + the GEGLU/GELU parallel FFN (bert.cpp:187-195)
    JinaV2,
    /// `LLM_ARCH_JINA_BERT_V3` — rope'd Q/K (bert.cpp:126-133) + the
    /// GELU-sequential FFN (bert.cpp:179-186)
    JinaV3,
    /// `LLM_ARCH_NOMIC_BERT` — rope'd + the gated SwiGLU parallel FFN
    /// (bert.cpp:196-203, the plain `else` arm)
    Nomic,
    /// `LLM_ARCH_NOMIC_BERT_MOE` — rope'd + `moe_every_n_layers` MoE layers
    /// (bert.cpp:165-178) interleaved with the GELU-sequential FFN
    NomicMoe,
}

/// Per-layer weights the variant loaders create (jina-bert-v2.cpp:25-60 /
/// jina-bert-v3.cpp:25-43 / nomic-bert.cpp:25-45 / nomic-bert-moe.cpp:26-50 —
/// all through `create_tensor_qkv`, hence the fused/separate pair).
pub struct BertVariantLayerWeights {
    /// create_tensor_qkv (llama-model.cpp:3270): the fused tensor, else the
    /// separate triple
    pub wqkv: Option<TensorId>,
    pub wqkv_b: Option<TensorId>,
    pub wq: Option<TensorId>,
    pub wq_b: Option<TensorId>,
    pub wk: Option<TensorId>,
    pub wk_b: Option<TensorId>,
    pub wv: Option<TensorId>,
    pub wv_b: Option<TensorId>,
    pub wo: TensorId,
    pub wo_b: Option<TensorId>,
    pub attn_out_norm: TensorId,
    pub attn_out_norm_b: TensorId,
    /// jina-bert-v2's full-width Q/K norms (jina-bert-v2.cpp:30-34,
    /// bert.cpp:109-123)
    pub attn_q_norm: Option<TensorId>,
    pub attn_q_norm_b: Option<TensorId>,
    pub attn_k_norm: Option<TensorId>,
    pub attn_k_norm_b: Option<TensorId>,
    /// jina-bert-v2's second post-attention norm (jina-bert-v2.cpp:42-43,
    /// bert.cpp:156-159)
    pub attn_norm_2: Option<TensorId>,
    pub attn_norm_2_b: Option<TensorId>,
    pub ffn_gate: Option<TensorId>,
    pub ffn_up: Option<TensorId>,
    pub ffn_up_b: Option<TensorId>,
    pub ffn_down: Option<TensorId>,
    pub ffn_down_b: Option<TensorId>,
    /// the MoE layers of nomic-bert-moe (nomic-bert-moe.cpp:38-40)
    pub ffn_up_exps: Option<TensorId>,
    pub ffn_down_exps: Option<TensorId>,
    pub ffn_gate_inp: Option<TensorId>,
    pub layer_out_norm: TensorId,
    pub layer_out_norm_b: TensorId,
}

pub struct BertVariantModelWeights {
    pub variant: BertVariant,
    pub tok_embd: TensorId,
    /// row 0 only (bert.cpp:85-88)
    pub type_embd: Option<TensorId>,
    pub tok_norm: TensorId,
    pub tok_norm_b: TensorId,
    pub layers: Vec<BertVariantLayerWeights>,
    pub n_embd: i64,
    /// the reranker head of the RANK-pooled files (jina-bert-v2.cpp:23-24
    /// `cls`/`cls_b` — tanh flavor); None for plain embedders
    pub rank_head: Option<RankHead>,
}

/// The hparams facts the variant branches of the bert.cpp body read beyond
/// [`EncoderParams`] (which still carries n_head / n_head_kv / n_embd_head /
/// f_norm_eps / pool + the rope facts via `euro_rope` for the driver).
pub struct BertVariantParams {
    /// jina-bert-v2.cpp:5 `hparams.f_max_alibi_bias = 8.0f` — rides the mask
    /// fill and soft_max_ext (llama-graph.cpp:442 / :2705)
    pub max_alibi_bias: f32,
    /// `hparams.moe_every_n_layers` (nomic-bert-moe.cpp:5)
    pub moe_every_n_layers: u32,
    pub n_expert: i64,
    pub n_expert_used: i64,
    /// `hparams.expert_weights_scale` (bert.cpp:175)
    pub expert_weights_scale: f32,
    /// `hparams.n_ff()` — the width the jina-bert-v2 up_contains_gate test
    /// compares ffn_up->ne[1] against (bert.cpp:188)
    pub n_ff: i64,
}

/// build_moe_ffn of the bert MoE branch (bert.cpp:165-178 → llama-graph.cpp:
/// 2003-2364): SOFTMAX gating, `norm_w = false`, no expert biases, LLM_FFN_GELU
/// with no gate tensor — i.e. build_moe_ffn_silu's skeleton minus the
/// SOFTMAX_WEIGHT / norm_w paths and with gelu as the expert activation.
#[allow(clippy::too_many_arguments)]
fn build_moe_ffn_bert(
    ctx: &mut Context,
    graph: &mut Graph,
    cur: TensorId,
    gate_inp: TensorId,
    up_exps: TensorId,
    down_exps: TensorId,
    n_expert: i64,
    n_expert_used: i64,
    w_scale: f32,
) -> TensorId {
    let n_embd = ctx.ne(cur)[0];
    let n_tokens = ctx.ne(cur)[1];

    // SOFTMAX gating (bert.cpp:176)
    let logits = crate::adapter::lora_mm(ctx, gate_inp, cur);
    let probs = ctx.soft_max(logits);

    let selected = ctx.argsort_top_k(probs, n_expert_used as i32);

    let probs3 = ctx.reshape_3d(probs, 1, n_expert, n_tokens);
    let mut weights = ctx.get_rows(probs3, selected); // [1, k, n_tokens]

    // norm_w == false (bert.cpp:174) — no sum_rows/clamp/div renormalization
    if w_scale != 0.0 && w_scale != 1.0 {
        weights = ctx.scale(weights, w_scale);
    }
    graph.build_forward(ctx, weights);

    let cur3 = ctx.reshape_3d(cur, n_embd, 1, n_tokens);
    let up = crate::adapter::lora_mm_id(ctx, up_exps, cur3, selected);
    // LLM_FFN_GELU, gate == NULL (llama-graph.cpp:2256-2262)
    let act = ctx.gelu(up);
    let experts = crate::adapter::lora_mm_id(ctx, down_exps, act, selected);
    let experts = ctx.mul(experts, weights);
    graph.build_forward(ctx, experts);

    // aggregate the k expert views (llama-graph.cpp:2329-2358)
    let nb1 = ctx.nb(experts)[1] as usize;
    let nb2 = ctx.nb(experts)[2] as usize;
    let mut moe_out = ctx.view_2d(experts, n_embd, n_tokens, nb2, 0);
    graph.build_forward(ctx, moe_out);
    for i in 1..n_expert_used as usize {
        let vi = ctx.view_2d(experts, n_embd, n_tokens, nb2, i * nb1);
        graph.build_forward(ctx, vi);
        moe_out = ctx.add(moe_out, vi);
        graph.build_forward(ctx, moe_out);
    }
    if n_expert_used == 1 {
        moe_out = ctx.cont(moe_out);
    }
    moe_out
}

/// verify against src/models/bert.cpp:68-221 `llama_model_bert::graph` with the variant
/// arch branches live — the body the four `using graph =` loader files
/// instantiate (models.h: `llama_model_{jina_bert_v2, jina_bert_v3,
/// nomic_bert, nomic_bert_moe}`). Differences from the plain BERT arm
/// ([`build_bert_forward`]):
///
///   * no `pos_embd` add (that is `model.arch == LLM_ARCH_BERT` only,
///     bert.cpp:89-91) and no `build_inp_pos` for jina-bert-v2 (:77-79);
///   * the full-width jina q/k norms (:109-123, jina-bert-v2's tensors);
///   * the RoPE pair (:126-133, NOMIC_BERT / NOMIC_BERT_MOE / JINA_BERT_V3);
///   * `attn_norm_2` — a second re-add + norm (:156-159, jina-bert-v2);
///   * the MoE branch (:165-178, nomic-bert-moe's every-nth layers) and the
///     per-arch FFN arms (:179-203 — GELU-SEQ for JINA_V3/NOMIC_MOE's dense
///     layers, the jina-v2 GEGLU/GELU-PAR pair, nomic's SwiGLU-PAR).
#[allow(clippy::too_many_arguments)]
pub fn build_bert_variant_forward(
    ctx: &mut Context,
    w: &BertVariantModelWeights,
    p: &EncoderParams,
    vp: &BertVariantParams,
    rope: &EurobertRope,
    inp: &EncodeInputs,
    n_tokens: usize,
) -> EncodeResult {
    let t = n_tokens as i64;
    let n_embd_head = p.n_embd_head;
    let mut graph = Graph::new(1024);

    // if (model.arch != LLM_ARCH_JINA_BERT_V2) inp_pos = build_inp_pos()
    // (bert.cpp:77-79) — jina-bert-v2 has no position input at all
    let inp_pos = match w.variant {
        BertVariant::JinaV2 => None,
        _ => Some(inp.pos.expect("bert variant: build_inp_pos")),
    };

    // inpL = build_inp_embd(model.tok_embd) (bert.cpp:82)
    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);

    // token types are hardcoded to zero ("Sentence A") (bert.cpp:85-88)
    if let Some(te) = w.type_embd {
        let type_row0 = ctx.view_1d(te, w.n_embd, 0);
        inp_l = ctx.add(inp_l, type_row0);
    }
    // (no pos_embd — the :89-91 add is LLM_ARCH_BERT only)

    // embed layer norm (bert.cpp:95)
    let mut inp_l = build_norm(
        ctx,
        inp_l,
        Some(w.tok_norm),
        Some(w.tok_norm_b),
        p.f_norm_eps,
    );

    let mut layer_outs = Vec::with_capacity(w.layers.len());
    let n_layer = w.layers.len();
    for il in 0..n_layer {
        let lw = &w.layers[il];
        let mut cur = inp_l;

        // build_qkv (bert.cpp:106-107) — create_tensor_qkv loads either form
        let (mut q, mut k, v) = if let Some(wqkv) = lw.wqkv {
            qkv_fused_plain(ctx, wqkv, lw.wqkv_b, n_embd_head, p.n_head, p.n_head_kv, cur, t)
        } else {
            let mut q = crate::adapter::lora_mm(ctx, lw.wq.expect("bert variant wq"), cur);
            if let Some(b) = lw.wq_b {
                q = ctx.add(q, b);
            }
            let mut k = crate::adapter::lora_mm(ctx, lw.wk.expect("bert variant wk"), cur);
            if let Some(b) = lw.wk_b {
                k = ctx.add(k, b);
            }
            let mut v = crate::adapter::lora_mm(ctx, lw.wv.expect("bert variant wv"), cur);
            if let Some(b) = lw.wv_b {
                v = ctx.add(v, b);
            }
            let q = ctx.reshape_3d(q, n_embd_head, p.n_head, t);
            let k = ctx.reshape_3d(k, n_embd_head, p.n_head_kv, t);
            let v = ctx.reshape_3d(v, n_embd_head, p.n_head_kv, t);
            (q, k, v)
        };

        // the jina q/k norms (bert.cpp:109-123) — norm the FULL q/k width,
        // then reshape back to per-head 3d
        if let Some(qn) = lw.attn_q_norm {
            q = ctx.reshape_2d(q, n_embd_head * p.n_head, t);
            q = build_norm(ctx, q, Some(qn), lw.attn_q_norm_b, p.f_norm_eps);
            q = ctx.reshape_3d(q, n_embd_head, p.n_head, t);
        }
        if let Some(kn) = lw.attn_k_norm {
            k = ctx.reshape_2d(k, n_embd_head * p.n_head_kv, t);
            k = build_norm(ctx, k, Some(kn), lw.attn_k_norm_b, p.f_norm_eps);
            k = ctx.reshape_3d(k, n_embd_head, p.n_head_kv, t);
        }

        // RoPE (bert.cpp:126-133) — NOMIC_BERT / NOMIC_BERT_MOE / JINA_BERT_V3
        if matches!(
            w.variant,
            BertVariant::Nomic | BertVariant::NomicMoe | BertVariant::JinaV3
        ) {
            let pos = inp_pos.expect("rope'd bert variant: build_inp_pos");
            let r = |ctx: &mut Context, x: TensorId| {
                ctx.rope_ext(
                    x,
                    pos,
                    None,
                    rope.n_rot,
                    rope.rope_mode,
                    rope.n_ctx_orig,
                    rope.freq_base,
                    rope.freq_scale,
                    rope.ext_factor,
                    rope.attn_factor,
                    rope.beta_fast,
                    rope.beta_slow,
                )
            };
            q = r(ctx, q);
            k = r(ctx, k);
        }

        // build_attn (bert.cpp:139-141) — max_bias = f_max_alibi_bias for the
        // ALiBi family (llama-graph.cpp:2705)
        let kq_scale = 1.0 / (n_embd_head as f32).sqrt();
        cur = attn_no_cache_ext(
            ctx,
            q,
            k,
            v,
            None,
            inp.kq_mask,
            kq_scale,
            vp.max_alibi_bias,
            Some(lw.wo),
            lw.wo_b,
        );

        // last-layer output-row selection (bert.cpp:145-148)
        if il == n_layer - 1 {
            cur = ctx.get_rows(cur, inp.out_ids);
            inp_l = ctx.get_rows(inp_l, inp.out_ids);
        }

        // re-add the layer input (bert.cpp:151)
        let mut cur = ctx.add(cur, inp_l);

        // attention layer norm (bert.cpp:154)
        cur = build_norm(
            ctx,
            cur,
            Some(lw.attn_out_norm),
            Some(lw.attn_out_norm_b),
            p.f_norm_eps,
        );

        // attn_norm_2 (bert.cpp:156-159) — jina-bert-v2's extra re-add + norm
        if let Some(n2) = lw.attn_norm_2 {
            cur = ctx.add(cur, inp_l);
            cur = build_norm(ctx, cur, Some(n2), lw.attn_norm_2_b, p.f_norm_eps);
        }

        let ffn_inp = cur;

        // feed-forward network (bert.cpp:165-203)
        let ffn = if vp.moe_every_n_layers > 0 && il % vp.moe_every_n_layers as usize == 1 {
            // MoE branch (bert.cpp:165-178)
            build_moe_ffn_bert(
                ctx,
                &mut graph,
                ffn_inp,
                lw.ffn_gate_inp.expect("nomic-bert-moe layer: ffn_gate_inp"),
                lw.ffn_up_exps.expect("nomic-bert-moe layer: ffn_up_exps"),
                lw.ffn_down_exps
                    .expect("nomic-bert-moe layer: ffn_down_exps"),
                vp.n_expert,
                vp.n_expert_used,
                vp.expert_weights_scale,
            )
        } else if matches!(w.variant, BertVariant::JinaV3 | BertVariant::NomicMoe) {
            // bert.cpp:179-186 — GELU sequential with biases
            let mut tmp =
                crate::adapter::lora_mm(ctx, lw.ffn_up.expect("ffn_up"), ffn_inp);
            if let Some(b) = lw.ffn_up_b {
                tmp = ctx.add(tmp, b);
            }
            let tmp = ctx.gelu(tmp);
            let mut out =
                crate::adapter::lora_mm(ctx, lw.ffn_down.expect("ffn_down"), tmp);
            if let Some(b) = lw.ffn_down_b {
                out = ctx.add(out, b);
            }
            out
        } else if w.variant == BertVariant::JinaV2 {
            // bert.cpp:187-195 — GEGLU when the gate is folded into ffn_up
            // (up->ne[1] != n_ff), plain GELU otherwise
            let up = lw.ffn_up.expect("jina-bert-v2 ffn_up");
            let up_contains_gate = lw.ffn_gate.is_none() && ctx.ne(up)[1] != vp.n_ff;
            // tmp = up @ x + up_b (build_ffn's up stage, llama-graph.cpp:1786-1795)
            let mut tmp = crate::adapter::lora_mm(ctx, up, ffn_inp);
            if let Some(b) = lw.ffn_up_b {
                tmp = ctx.add(tmp, b);
            }
            let act = if let Some(gate) = lw.ffn_gate {
                // gate @ x (LLM_FFN_PAR) → geglu_split(gate, tmp)
                // (llama-graph.cpp:1858-1863)
                let g = crate::adapter::lora_mm(ctx, gate, ffn_inp);
                ctx.geglu_split(g, tmp)
            } else if up_contains_gate {
                // ggml_geglu(tmp) — the single-tensor GLU, composed over the
                // two half-views (bit-identical by construction: the C kernel
                // with src1 == NULL reads src0[i] and src0[i + nc], the same
                // elements the views expose — the plamo2 precedent)
                let n_half = ctx.ne(tmp)[0] / 2;
                let nb1 = ctx.nb(tmp)[1] as usize;
                let first = ctx.view_2d(tmp, n_half, t, nb1, 0);
                let second = ctx.view_2d(tmp, n_half, t, nb1, (n_half * 4) as usize);
                ctx.geglu_split(first, second)
            } else {
                // plain GELU (llama-graph.cpp:1865-1871)
                ctx.gelu(tmp)
            };
            let mut out = crate::adapter::lora_mm(ctx, lw.ffn_down.expect("ffn_down"), act);
            if let Some(b) = lw.ffn_down_b {
                out = ctx.add(out, b);
            }
            out
        } else {
            // nomic-bert — bert.cpp:196-203: SwiGLU parallel, no biases
            let gate = crate::adapter::lora_mm(ctx, lw.ffn_gate.expect("nomic ffn_gate"), ffn_inp);
            let up = crate::adapter::lora_mm(ctx, lw.ffn_up.expect("nomic ffn_up"), ffn_inp);
            // ggml_swiglu_split(gate, up) (llama-graph.cpp:1835-1841)
            let act = ctx.swiglu_split(gate, up);
            crate::adapter::lora_mm(ctx, lw.ffn_down.expect("nomic ffn_down"), act)
        };

        // attentions bypass the intermediate layer (bert.cpp:206)
        let cur = ctx.add(ffn, ffn_inp);

        // output layer norm (bert.cpp:209)
        let cur = build_norm(
            ctx,
            cur,
            Some(lw.layer_out_norm),
            Some(lw.layer_out_norm_b),
            p.f_norm_eps,
        );

        inp_l = cur;
        layer_outs.push(cur);
    }

    // res->t_embd = cur (bert.cpp:215-218)
    graph.build_forward(ctx, inp_l);
    EncodeResult {
        embd: inp_l,
        layer_outs,
        graph,
    }
}

// ======================================================================
// neo-bert — verify against src/models/neo-bert.cpp:43-134 llama_model_neo_bert::graph
// ======================================================================

/// Per-layer weights (neo-bert.cpp:24-36): fused QKV (n_embd + 2*n_embd_gqa
/// wide), RMS pre-norms, bias-free SwiGLU FFN with the gate folded into
/// ffn_up ([n_embd, n_ff*2]).
pub struct NeoBertLayerWeights {
    pub attn_norm: TensorId,
    pub wqkv: TensorId,
    pub wo: TensorId,
    pub ffn_norm: TensorId,
    pub ffn_up: TensorId,
    pub ffn_down: TensorId,
}

pub struct NeoBertModelWeights {
    pub tok_embd: TensorId,
    /// `enc.output_norm.weight` (neo-bert.cpp:22) — the encoder's final RMS
    /// norm, mapped onto the generic output_norm slot like t5encoder
    pub output_norm_enc: TensorId,
    pub layers: Vec<NeoBertLayerWeights>,
}

/// verify against src/models/neo-bert.cpp:43-134 — RMS pre-norm → fused-QKV attention
/// with NORM-mode rope and `1/sqrt(n_embd_head)` scale → residual → RMS norm →
/// SWIGLU-sequential FFN (`ggml_swiglu(up)` over the half-views) → residual;
/// final `enc.output_norm` RMS norm. No token/type/position embeddings beyond
/// the token table and no embedding layer norm (:52-54).
pub fn build_neo_bert_forward(
    ctx: &mut Context,
    w: &NeoBertModelWeights,
    p: &EncoderParams,
    rope: &EurobertRope,
    inp: &EncodeInputs,
    n_tokens: usize,
) -> EncodeResult {
    let t = n_tokens as i64;
    let n_embd_head = p.n_embd_head;
    let eps = p.f_norm_rms_eps;
    let mut graph = Graph::new(1024);

    let inp_pos = inp.pos.expect("neo-bert: build_inp_pos");

    // inpL = build_inp_embd(model.tok_embd) (neo-bert.cpp:53)
    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);

    let mut layer_outs = Vec::with_capacity(w.layers.len());
    let n_layer = w.layers.len();
    for il in 0..n_layer {
        let lw = &w.layers[il];

        // pre-norm (neo-bert.cpp:64-66)
        let cur = build_norm_rms(ctx, inp_l, lw.attn_norm, eps);

        // build_qkv fused (neo-bert.cpp:69-70) + rope NORM-mode (:73-83)
        let (mut q, mut k, v) =
            qkv_fused_plain(ctx, lw.wqkv, None, n_embd_head, p.n_head, p.n_head_kv, cur, t);
        let r = |ctx: &mut Context, x: TensorId| {
            ctx.rope_ext(
                x,
                inp_pos,
                None,
                rope.n_rot,
                rope.rope_mode,
                rope.n_ctx_orig,
                rope.freq_base,
                rope.freq_scale,
                rope.ext_factor,
                rope.attn_factor,
                rope.beta_fast,
                rope.beta_slow,
            )
        };
        q = r(ctx, q);
        k = r(ctx, k);

        // build_attn, no wo bias (neo-bert.cpp:89-91)
        let kq_scale = 1.0 / (n_embd_head as f32).sqrt();
        let mut cur = attn_no_cache(
            ctx,
            q,
            k,
            v,
            None,
            inp.kq_mask,
            kq_scale,
            Some(lw.wo),
            None,
        );

        // last-layer output-row selection (neo-bert.cpp:94-97)
        if il == n_layer - 1 {
            cur = ctx.get_rows(cur, inp.out_ids);
            inp_l = ctx.get_rows(inp_l, inp.out_ids);
        }

        // re-add the layer input (neo-bert.cpp:99)
        let cur = ctx.add(cur, inp_l);
        let ffn_inp = cur;

        // pre-norm (neo-bert.cpp:105-107)
        let cur = build_norm_rms(ctx, ffn_inp, lw.ffn_norm, eps);

        // LLM_FFN_SWIGLU + LLM_FFN_SEQ, gate == NULL (neo-bert.cpp:111-116):
        // up {n_embd, 2*n_ff} → ggml_swiglu → down — the fused single-tensor
        // GLU composed over the half-views (the plamo2 precedent: the C
        // kernel computes silu(src0[i]) * src0[i + nc], the same elements the
        // views expose)
        let up = crate::adapter::lora_mm(ctx, lw.ffn_up, cur);
        let n_ff = ctx.ne(up)[0] / 2;
        let nb1 = ctx.nb(up)[1] as usize;
        let first = ctx.view_2d(up, n_ff, t, nb1, 0);
        let second = ctx.view_2d(up, n_ff, t, nb1, (n_ff * 4) as usize);
        let act = ctx.swiglu_split(first, second);
        let cur = crate::adapter::lora_mm(ctx, lw.ffn_down, act);

        // attentions bypass the intermediate layer (neo-bert.cpp:119)
        let cur = ctx.add(cur, ffn_inp);

        inp_l = cur;
        layer_outs.push(cur);
    }

    // final RMS norm (neo-bert.cpp:126-128)
    let cur = build_norm_rms(ctx, inp_l, w.output_norm_enc, eps);

    graph.build_forward(ctx, cur);
    EncodeResult {
        embd: cur,
        layer_outs,
        graph,
    }
}

// ======================================================================
// modern-bert — verify against src/models/modern-bert.cpp:72-172
// llama_model_modern_bert::graph
// ======================================================================

/// The symmetric-SWA + per-layer-rope facts of modern-bert's hparams
/// (modern-bert.cpp:4-11): `get_rope_freq_base/scale` (llama-model.cpp:2251-
/// 2257) swap to the *_swa pair on the SWA layers, and build_attn reads the
/// kq_mask_swa twin on those layers.
pub struct ModernBertSwa {
    pub is_swa: Vec<bool>,
    pub n_swa: u32,
    pub freq_base: f32,
    pub freq_scale: f32,
    pub freq_base_swa: f32,
    pub freq_scale_swa: f32,
}

/// The resolved FFN op (`hparams.llm_ffn_op`, modern-bert.cpp:17-21): GEGLU by
/// default, `hidden_activation` override for the SiLU derivatives (granite
/// embedding).
pub struct ModernBertParams {
    pub swa: ModernBertSwa,
    /// the `hparams.llm_ffn_op` of the file (GEGLU default)
    pub ffn_op: crate::hparams::LlmFfnOpType,
}

/// Per-layer weights (modern-bert.cpp:42-59): fused 3*n_embd QKV, LayerNorms
/// (layer 0's attn_norm optional — identity), the 2*n_ff-wide up with the
/// gate folded in, no biases anywhere.
pub struct ModernBertLayerWeights {
    /// None on layer 0 of headless files (modern-bert.cpp:45-50)
    pub attn_norm: Option<TensorId>,
    /// decision-head blocks only (a7b94df2c modern-bert.cpp:93) — None on
    /// the encoder layers
    pub attn_norm_b: Option<TensorId>,
    pub wqkv: TensorId,
    /// decision-head blocks only (:95)
    pub wqkv_b: Option<TensorId>,
    pub wo: TensorId,
    /// decision-head blocks only (:96)
    pub wo_b: Option<TensorId>,
    pub ffn_norm: TensorId,
    /// decision-head blocks only (:102)
    pub ffn_norm_b: Option<TensorId>,
    pub ffn_up: TensorId,
    /// decision-head blocks only (:103; the head up is plain [n_embd,
    /// n_ff_head], not gated)
    pub ffn_up_b: Option<TensorId>,
    pub ffn_down: TensorId,
    /// decision-head blocks only (:104)
    pub ffn_down_b: Option<TensorId>,
}

/// the scorer of the modern-bert decision model (a7b94df2c
/// modern-bert.cpp:111-122): cls head norm → cls mm+bias → gelu_erf →
/// cls_out mm+bias, evaluated once per question type and concatenated
pub struct ModernBertDecisionHead {
    pub type_embd: TensorId,
    pub cls: TensorId,
    pub cls_b: TensorId,
    pub cls_norm: TensorId,
    pub cls_norm_b: TensorId,
    pub cls_out: TensorId,
    pub cls_out_b: TensorId,
}

pub struct ModernBertModelWeights {
    pub tok_embd: TensorId,
    pub tok_norm: TensorId,
    /// the final LayerNorm (modern-bert.cpp:40)
    pub output_norm: TensorId,
    /// encoder blocks + the trailing decision blocks (all n_layer entries;
    /// `n_layer_decision` of them at the tail belong to the head)
    pub layers: Vec<ModernBertLayerWeights>,
    /// `hparams.n_layer_decision` (a7b94df2c) — 0 on plain embedders
    pub n_layer_decision: usize,
    /// the decision head (a7b94df2c) — present iff n_layer_decision > 0
    pub decision: Option<ModernBertDecisionHead>,
    /// the GTE reranker head (modern-bert.cpp:61-64) — read by RANK pooling
    /// only ([`RankHead`]); None for headless embedder files
    pub rank_head: Option<RankHead>,
}

/// verify against src/models/modern-bert.cpp:72-172 — embedding layer norm, then per
/// layer: optional attention LayerNorm (identity on layer 0) → fused-QKV
/// attention with NORM... NEOX-mode rope at the layer's own freq base (SWA
/// layers get the *_swa pair) and the symmetric-SWA mask twin on those layers
/// → residual → ffn LayerNorm → the `llm_ffn_op` FFN over the 2*n_ff-wide up
/// (GEGLU default, SwiGLU for the granite derivatives) → residual; final
/// output LayerNorm. `res->t_embd` only; the reranker head is pooling-side.
pub fn build_modern_bert_forward(
    ctx: &mut Context,
    w: &ModernBertModelWeights,
    p: &EncoderParams,
    mp: &ModernBertParams,
    rope: &EurobertRope,
    inp: &EncodeInputs,
    n_tokens: usize,
) -> EncodeResult {
    use crate::hparams::LlmFfnOpType as Op;
    let t = n_tokens as i64;
    let n_embd_head = p.n_embd_head;
    let mut graph = Graph::new(1024);

    let inp_pos = inp.pos.expect("modern-bert: build_inp_pos");

    // inpL = build_inp_embd + embed layer norm (modern-bert.cpp:82-87)
    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = build_norm(ctx, inp_l, Some(w.tok_norm), None, p.f_norm_eps);

    let n_layer = w.layers.len();
    // the trailing decision blocks run in the head only (a7b94df2c
    // modern-bert.cpp:153-155)
    let n_layer_enc = n_layer - w.n_layer_decision;
    let mut layer_outs = Vec::with_capacity(n_layer_enc);
    for il in 0..n_layer_enc {
        let lw = &w.layers[il];

        // model.get_rope_freq_base/scale(cparams, il) (modern-bert.cpp:94-95,
        // llama-model.cpp:2251-2257)
        let (freq_base_l, freq_scale_l) = if mp.swa.is_swa.get(il).copied().unwrap_or(false) {
            (mp.swa.freq_base_swa, mp.swa.freq_scale_swa)
        } else {
            (mp.swa.freq_base, mp.swa.freq_scale)
        };

        // attention layer norm — identity when the layer has no tensor
        // (modern-bert.cpp:100-105)
        let mut cur = inp_l;
        if let Some(an) = lw.attn_norm {
            cur = build_norm(ctx, inp_l, Some(an), None, p.f_norm_eps);
        }

        // build_qkv fused (modern-bert.cpp:108-109) + rope (:112-122)
        let (mut q, mut k, v) =
            qkv_fused_plain(ctx, lw.wqkv, None, n_embd_head, p.n_head, p.n_head_kv, cur, t);
        let r = |ctx: &mut Context, x: TensorId| {
            ctx.rope_ext(
                x,
                inp_pos,
                None,
                rope.n_rot,
                rope.rope_mode,
                rope.n_ctx_orig,
                freq_base_l,
                freq_scale_l,
                rope.ext_factor,
                rope.attn_factor,
                rope.beta_fast,
                rope.beta_slow,
            )
        };
        q = r(ctx, q);
        k = r(ctx, k);

        // build_attn (modern-bert.cpp:128-130) — the SWA layers read the
        // kq_mask_swa twin (llama-graph.cpp:2795 `is_swa ? get_kq_mask_swa`)
        let kq_scale = 1.0 / (n_embd_head as f32).sqrt();
        let mask = if mp.swa.is_swa.get(il).copied().unwrap_or(false) {
            inp.kq_mask_swa
                .expect("modern-bert: SWA layer needs the kq_mask_swa twin")
        } else {
            inp.kq_mask
        };
        let mut cur = attn_no_cache(ctx, q, k, v, None, mask, kq_scale, Some(lw.wo), None);

        // last-layer output-row selection (modern-bert.cpp:133-136)
        if il == n_layer_enc - 1 {
            cur = ctx.get_rows(cur, inp.out_ids);
            inp_l = ctx.get_rows(inp_l, inp.out_ids);
        }

        // ffn_inp = cur + inpL (modern-bert.cpp:139)
        let ffn_inp = ctx.add(cur, inp_l);

        // attention layer norm of the FFN stage (modern-bert.cpp:143-145)
        let cur = build_norm(ctx, ffn_inp, Some(lw.ffn_norm), None, p.f_norm_eps);

        // build_ffn: up {n_embd, 2*n_ff} with the gate folded in, gate ==
        // NULL, LLM_FFN_SEQ (modern-bert.cpp:148-154) — the op decides how
        // the wide up is split
        let up = crate::adapter::lora_mm(ctx, lw.ffn_up, cur);
        let n_half = ctx.ne(up)[0] / 2;
        let nb1 = ctx.nb(up)[1] as usize;
        let first = ctx.view_2d(up, n_half, t, nb1, 0);
        let second = ctx.view_2d(up, n_half, t, nb1, (n_half * 4) as usize);
        let act = match mp.ffn_op {
            // ggml_geglu(up) (llama-graph.cpp:1904-1908)
            Op::GEGLU => ctx.geglu_split(first, second),
            // hidden_activation "silu"/"swish"/"swiglu" → LLM_FFN_SWIGLU →
            // ggml_swiglu(up) (llama-graph.cpp:1926-1930)
            Op::SWIGLU => ctx.swiglu_split(first, second),
            // hidden_activation "reglu" → LLM_FFN_REGLU → ggml_reglu(up)
            // (llama-graph.cpp:1912-1916)
            Op::REGLU => ctx.reglu_split(first, second),
            other => unimplemented!(
                "modern-bert: ffn op {other:?} (not a gated op of the \
                 LLM_FFN_OP_TYPES_FROM_STRING table, llama-model.cpp:1042-1050)"
            ),
        };
        let cur = crate::adapter::lora_mm(ctx, lw.ffn_down, act);

        // attentions bypass the intermediate layer (modern-bert.cpp:157)
        let cur = ctx.add(cur, ffn_inp);

        inp_l = cur;
        layer_outs.push(cur);
    }

    // final norm (modern-bert.cpp:165-167)
    let cur = build_norm(ctx, inp_l, Some(w.output_norm), None, p.f_norm_eps);

    // the decision head replaces t_embd with the per-type scores (a7b94df2c
    // modern-bert.cpp:233-235)
    let cur = if w.n_layer_decision > 0 {
        let head = w.decision.as_ref().expect("decision head weights");
        build_modern_bert_decision_head(ctx, w, p, head, cur, inp, n_layer, n_tokens)
    } else {
        cur
    };

    graph.build_forward(ctx, cur);
    EncodeResult {
        embd: cur,
        layer_outs,
        graph,
    }
}

/// `build_decision_head` (a7b94df2c modern-bert.cpp:239-305) — one
/// plain pre-norm block stack per question type (choice, score, noul),
/// seeded with the matching token-type row, no positional encoding; the
/// scorer runs cls → gelu_erf → cls_out and the three score rows concat.
#[allow(clippy::too_many_arguments)]
fn build_modern_bert_decision_head(
    ctx: &mut Context,
    w: &ModernBertModelWeights,
    p: &EncoderParams,
    head: &ModernBertDecisionHead,
    inp: TensorId,
    einp: &EncodeInputs,
    n_layer: usize,
    n_tokens: usize,
) -> TensorId {
    let t = n_tokens as i64;
    let n_embd = ctx.ne(inp)[0];
    let n_embd_head = p.n_embd_head;
    let n_layer_enc = n_layer - w.n_layer_decision;

    let mut scores: Option<TensorId> = None;

    // the question type is not a graph input, so the head is evaluated for
    // each of them (N_DECISION_TYPES = 3)
    for it in 0..3u32 {
        // type_row = view_1d(type_embd, n_embd, it*nb[1]) (:245-246)
        let nb1 = ctx.nb(head.type_embd)[1] as usize;
        let type_row = ctx.view_1d(head.type_embd, n_embd, it as usize * nb1);
        let mut inp_l = ctx.add(inp, type_row);

        for il in n_layer_enc..n_layer {
            let lw = &w.layers[il];

            let cur = build_norm(ctx, inp_l, lw.attn_norm, lw.attn_norm_b, p.f_norm_eps);

            // no positional encoding in the head (:252-253)
            let (q, k, v) = qkv_fused_plain(
                ctx,
                lw.wqkv,
                lw.wqkv_b,
                n_embd_head,
                p.n_head,
                p.n_head_kv,
                cur,
                t,
            );

            let kq_scale = 1.0 / (n_embd_head as f32).sqrt();
            let cur = attn_no_cache(
                ctx,
                q,
                k,
                v,
                None,
                einp.kq_mask,
                kq_scale,
                Some(lw.wo),
                lw.wo_b,
            );

            // the last block narrows to the output rows (:258-261); the
            // port's encoder driver always provides out_ids
            let mut cur = cur;
            if il == n_layer - 1 {
                cur = ctx.get_rows(cur, einp.out_ids);
                inp_l = ctx.get_rows(inp_l, einp.out_ids);
            }

            let ffn_inp = ctx.add(cur, inp_l);

            // LLM_NORM ffn_norm with bias (:266-267)
            let cur = build_norm(ctx, ffn_inp, Some(lw.ffn_norm), lw.ffn_norm_b, p.f_norm_eps);

            // LLM_FFN_RELU over the plain [n_embd, n_ff_head] up with bias
            // (:269-276)
            let up = crate::adapter::lora_mm(ctx, lw.ffn_up, cur);
            let up = match lw.ffn_up_b {
                Some(b) => ctx.add(up, b),
                None => up,
            };
            let act = ctx.relu(up);
            let cur = crate::adapter::lora_mm(ctx, lw.ffn_down, act);
            let cur = match lw.ffn_down_b {
                Some(b) => ctx.add(cur, b),
                None => cur,
            };

            inp_l = ctx.add(cur, ffn_inp);
        }

        // scorer (:279-283): cls_norm → cls+b → gelu_erf → cls_out+b
        let cur = build_norm(ctx, inp_l, Some(head.cls_norm), Some(head.cls_norm_b), p.f_norm_eps);
        let cur = crate::adapter::lora_mm(ctx, head.cls, cur);
        let cur = ctx.add(cur, head.cls_b);
        let cur = ctx.gelu_erf(cur);
        let cur = crate::adapter::lora_mm(ctx, head.cls_out, cur);
        let cur = ctx.add(cur, head.cls_out_b);

        scores = Some(match scores {
            None => cur,
            Some(s) => ctx.concat(s, cur, 0),
        });
    }
    let scores = scores.unwrap();
    ctx.set_name(scores, "decision_scores");
    scores
}

// ======================================================================
// t5encoder — verify against src/models/t5.cpp:264-358 llama_model_t5::graph<true>
// ======================================================================

/// Per-layer weights of the encoder half (t5encoder.cpp:24-39 / t5.cpp:63-78,
/// identical tensor set). The decoder-side members (`attn_norm`, `wq`, `wk`,
/// cross-attention, ...) are not loaded — see COVERAGE.md.
pub struct T5EncoderLayerWeights {
    pub attn_norm_enc: TensorId,
    /// `attn_rel_b_enc` — optional; the graph falls back to layer 0's tensor
    /// when a layer has none (t5.cpp:305, true for every layer but blk.0 of
    /// the local t5-v1_1-xxl-encoder file)
    pub attn_rel_b_enc: Option<TensorId>,
    pub wq_enc: TensorId,
    pub wk_enc: TensorId,
    pub wv_enc: TensorId,
    pub wo_enc: TensorId,
    pub ffn_norm_enc: TensorId,
    /// `ffn_gate_enc` — present for t5 v1.1 / flan (gated GELU), absent for
    /// t5 1.0 (relu) — t5.cpp:333-334
    pub ffn_gate_enc: Option<TensorId>,
    pub ffn_down_enc: TensorId,
    pub ffn_up_enc: TensorId,
}

pub struct T5EncoderModelWeights {
    pub tok_embd: TensorId,
    /// `output_norm_enc` = `enc.output_norm.weight` (t5encoder.cpp:17) —
    /// the encoder's final RMS norm
    pub output_norm_enc: TensorId,
    pub layers: Vec<T5EncoderLayerWeights>,
}

/// verify against src/models/t5.cpp:264-358 `graph<true>` (the `LLM_GRAPH_TYPE_ENCODER`
/// instantiation, t5.cpp:360-370; t5encoder.cpp:42-44 uses the same body).
///
/// Per layer: RMS norm → Q/K/V projections (no bias in T5) → relative-position
/// bias added to the pre-softmax logits (`build_pos_bias`) → MHA with
/// kq_scale = 1.0 (t5.cpp:310; T5 does *not* scale by 1/sqrt(head)) → residual
/// → RMS norm → gated GELU FFN → residual. `res->t_embd` is the `enc_norm`
/// output (t5.cpp:350-355).
///
/// Always the non-FA branch: `kq_b != nullptr` disables FA unconditionally
/// (llama-graph.cpp:2626 `use_flash_attn = cparams.flash_attn && kq_b == nullptr`).
///
/// Not ported: `build_cvec` control vectors (t5.cpp:341 — no cvec support in
/// this port), the `n_layer != dec_n_layer` decoder block resize
/// (t5.cpp:57-60, decoder only), and the ungated (t5 1.0) FFN which needs
/// `ggml_relu` (t5.cpp:231 / :333 — not ported in crates/ggml).
pub fn build_t5_encoder_forward(
    ctx: &mut Context,
    w: &T5EncoderModelWeights,
    p: &EncoderParams,
    inp: &EncodeInputs,
    n_tokens: usize,
) -> EncodeResult {
    let t = n_tokens as i64;
    // C asserts n_embd_head_v == n_embd_head_k (t5.cpp:268) — see
    // EncoderParams::n_embd_head
    let n_embd_head = p.n_embd_head;
    let mut graph = Graph::new(1024);

    // inpL = build_inp_embd(model.tok_embd) (t5.cpp:273)
    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    let pos_bucket = inp.pos_bucket.expect("t5: build_inp_pos_bucket_enc");

    let mut layer_outs = Vec::with_capacity(w.layers.len());
    for (il, lw) in w.layers.iter().enumerate() {
        let inp_sa = inp_l;

        // norm (t5.cpp:285-287, LLM_NORM_RMS → f_norm_rms_eps), no bias
        let cur = build_norm_rms(ctx, inp_l, lw.attn_norm_enc, p.f_norm_rms_eps);

        // Q/K/V (t5.cpp:292-303, build_lora_mm at llama-graph.cpp:1689-1717) with
        // n_embd_k_gqa == n_embd_v_gqa == n_embd
        let q = crate::adapter::lora_mm(ctx, lw.wq_enc, cur);
        let k = crate::adapter::lora_mm(ctx, lw.wk_enc, cur);
        let v = crate::adapter::lora_mm(ctx, lw.wv_enc, cur);
        let q = ctx.reshape_3d(q, n_embd_head, p.n_head, t);
        let k = ctx.reshape_3d(k, n_embd_head, p.n_head_kv, t);
        let v = ctx.reshape_3d(v, n_embd_head, p.n_head_kv, t);

        // relative position bias — fall back to layer 0's table (t5.cpp:305)
        let attn_rel_b = match lw.attn_rel_b_enc {
            Some(b) => b,
            None => w.layers[0]
                .attn_rel_b_enc
                .expect("t5: no layer carries attn_rel_b_enc"),
        };
        let kq_b = build_pos_bias(ctx, pos_bucket, attn_rel_b);

        // kq_scale = 1.0 (t5.cpp:310), wo has no bias
        let cur = attn_no_cache(
            ctx,
            q,
            k,
            v,
            Some(kq_b),
            inp.kq_mask,
            1.0,
            Some(lw.wo_enc),
            None,
        );

        // last-layer output-row selection (t5.cpp:313-316)
        let (mut cur, mut inp_sa) = (cur, inp_sa);
        if il == w.layers.len() - 1 {
            cur = ctx.get_rows(cur, inp.out_ids);
            inp_sa = ctx.get_rows(inp_sa, inp.out_ids);
        }

        let ffn_inp = ctx.add(cur, inp_sa);

        // FFN norm (t5.cpp:322-324)
        let cur = build_norm_rms(ctx, ffn_inp, lw.ffn_norm_enc, p.f_norm_rms_eps);

        // T5 uses relu, flan-T5 uses gelu-gated (t5.cpp:327-335)
        let cur = match lw.ffn_gate_enc {
            Some(gate) => {
                // LLM_FFN_GELU + LLM_FFN_PAR → ggml_geglu_split
                // (llama-graph.cpp:1843-1851, build_lora_mm at :1786/1803/1926)
                let g = crate::adapter::lora_mm(ctx, gate, cur);
                let u = crate::adapter::lora_mm(ctx, lw.ffn_up_enc, cur);
                let act = ctx.geglu_split(g, u);
                crate::adapter::lora_mm(ctx, lw.ffn_down_enc, act)
            }
            None => {
                // build_ffn LLM_FFN_RELU + LLM_FFN_SEQ with gate == NULL
                // (t5.cpp:333-334 — t5 1.0). relu reached crates/ggml with the
                // unary-op set (GGML_UNARY_OP_RELU, ops.rs:44), so the branch
                // the encoder long documented as unportable now computes.
                let u = crate::adapter::lora_mm(ctx, lw.ffn_up_enc, cur);
                let u = ctx.relu(u);
                crate::adapter::lora_mm(ctx, lw.ffn_down_enc, u)
            }
        };

        let cur = ctx.add(cur, ffn_inp);
        // build_cvec (t5.cpp:341) — control vectors are not ported
        inp_l = cur;
        layer_outs.push(cur);
    }

    // enc_norm + res->t_embd (t5.cpp:347-355, LLM_NORM_RMS)
    let cur = build_norm_rms(ctx, inp_l, w.output_norm_enc, p.f_norm_rms_eps);
    graph.build_forward(ctx, cur);
    EncodeResult {
        embd: cur,
        layer_outs,
        graph,
    }
}

/// `build_norm` (llama-graph.cpp:1583-1613) for LLM_NORM: layer norm with eps,
/// then optional weight / bias.
fn build_norm(
    ctx: &mut Context,
    x: TensorId,
    w: Option<TensorId>,
    b: Option<TensorId>,
    eps: f32,
) -> TensorId {
    let mut cur = ctx.norm(x, eps);
    if let Some(w) = w {
        cur = ctx.mul(cur, w);
    }
    if let Some(b) = b {
        cur = ctx.add(cur, b);
    }
    cur
}

// ======================================================================
// arch batch: gpt2 / phi2 / starcoder2 / command-r / gptneox / olmo2
//
// Six structurally distinct dense archs landed together (2026-09-24). They
// add only four small helpers on top of what the earlier builders expose:
//   * `build_ffn_gelu_seq` — build_ffn LLM_FFN_GELU + LLM_FFN_SEQ with
//     `gate == NULL` (llama-graph.cpp:1748-1857), used by gpt2/phi2/
//     starcoder2/gptneox
//   * `qkv_fused`   — build_qkv's `layer.wqkv` branch (llama-graph.cpp:
//     1649-1686): one mul_mat + fused bias + three view_3d segments
//   * `qkv_separate_parts` / `rope_qk` — the else branch of build_qkv
//     (llama-graph.cpp:1687-1735) and the inline `ggml_rope_ext` call each of
//     these arch files spells out
// `build_norm` (LLM_NORM: ggml_norm + optional weight/bias) and
// `build_norm_rms` are reused unchanged, as is `attn_kv_cached`.
// ======================================================================

/// `build_ffn` LLM_FFN_GELU + LLM_FFN_SEQ with `gate == NULL` (llama-graph.cpp:
/// 1748-1857; the GELU branch at :1795-1800, the seq branch at :1836-1852):
/// up (+bias) → ggml_gelu → down (+bias).
fn build_ffn_gelu_seq(
    ctx: &mut Context,
    cur: TensorId,
    up: TensorId,
    up_b: Option<TensorId>,
    down: TensorId,
    down_b: Option<TensorId>,
) -> TensorId {
    let mut u = crate::adapter::lora_mm(ctx, up, cur);
    if let Some(b) = up_b {
        u = ctx.add(u, b);
    }
    // LLM_FFN_GELU (llama-graph.cpp:1795-1800): plain `ggml_gelu` with the
    // default op params (0 == GGML_GELU_FP16, ggml.c's gelu table)
    let g = ctx.gelu(u);
    let mut out = crate::adapter::lora_mm(ctx, down, g);
    if let Some(b) = down_b {
        out = ctx.add(out, b);
    }
    out
}

/// `build_qkv`'s fused branch with `reshape == true` (llama-graph.cpp:
/// 1649-1681): wqkv mul_mat → optional fused bias (C also handles the concat
/// of separate q/k/v biases at :1656-1661; `create_tensor_qkv` already
/// resolved which bias tensors the file carries, and the port's
/// `ModelLoader` loads `wq_b`/`wk_b`/`wv_b` only when the fused bias is
/// absent) → view_3d split into Q/K/V.
fn qkv_fused(
    ctx: &mut Context,
    lw_qkv: TensorId,
    lw_qkv_b: Option<TensorId>,
    p: &AttnParams,
    cur: TensorId,
    t: i64,
) -> (TensorId, TensorId, TensorId) {
    let mut qkv = crate::adapter::lora_mm(ctx, lw_qkv, cur);
    if let Some(b) = lw_qkv_b {
        qkv = ctx.add(qkv, b);
    }
    let n_embd_q = p.n_embd_head_k * p.n_head;
    let n_embd_k = p.n_embd_head_k * p.n_head_kv;
    let nb1 = ctx.nb(qkv)[1] as usize;
    let hd_k = p.n_embd_head_k as usize;
    let hd_v = p.n_embd_head_v as usize;
    // verify against llama-graph.cpp:1667-1674 the three-way view_3d
    let q = ctx.view_3d(qkv, p.n_embd_head_k, p.n_head, t, hd_k * 4, nb1, 0);
    let k = ctx.view_3d(
        qkv,
        p.n_embd_head_k,
        p.n_head_kv,
        t,
        hd_k * 4,
        nb1,
        n_embd_q as usize * 4,
    );
    let v = ctx.view_3d(
        qkv,
        p.n_embd_head_v,
        p.n_head_kv,
        t,
        hd_v * 4,
        nb1,
        (n_embd_q + n_embd_k) as usize * 4,
    );
    (q, k, v)
}

/// `build_qkv`'s separate-Q/K/V branch with `reshape == true` (llama-graph.cpp:
/// 1687-1735) abbreviated to what the batch archs need: three mul_mats, the
/// optional per-tensor bias, then the 3D reshape. `f_clamp_kqv` is 0.0f for
/// every arch here (no GGUF key sets it — llama-hparams.h:217 holds the only
/// non-default assignment site, and no loader writes it).
#[allow(clippy::too_many_arguments)]
fn qkv_separate_parts(
    ctx: &mut Context,
    wq: TensorId,
    wq_b: Option<TensorId>,
    wk: TensorId,
    wk_b: Option<TensorId>,
    wv: TensorId,
    wv_b: Option<TensorId>,
    p: &AttnParams,
    cur: TensorId,
    t: i64,
) -> (TensorId, TensorId, TensorId) {
    let mut q = crate::adapter::lora_mm(ctx, wq, cur);
    if let Some(b) = wq_b {
        q = ctx.add(q, b);
    }
    let mut k = crate::adapter::lora_mm(ctx, wk, cur);
    if let Some(b) = wk_b {
        k = ctx.add(k, b);
    }
    let mut v = crate::adapter::lora_mm(ctx, wv, cur);
    if let Some(b) = wv_b {
        v = ctx.add(v, b);
    }
    // llama-graph.cpp:1738-1746 ggml_reshape_3d on each of Q/K/V
    let q = ctx.reshape_3d(q, p.n_embd_head_k, p.n_head, t);
    let k = ctx.reshape_3d(k, p.n_embd_head_k, p.n_head_kv, t);
    let v = ctx.reshape_3d(v, p.n_embd_head_v, p.n_head_kv, t);
    (q, k, v)
}

/// The `ggml_rope_ext(ctx0, ., inp_pos, nullptr, n_rot, rope_type, n_ctx_orig,
/// freq_base, freq_scale, ext_factor, attn_factor, beta_fast, beta_slow)` call
/// the batch arch files spell out inline (phi2.cpp:77-87, starcoder2.cpp:
/// 92-102, gptneox.cpp:112-122, olmo2.cpp:126-139).
fn rope_qk(
    ctx: &mut Context,
    p: &AttnParams,
    pos: TensorId,
    q: TensorId,
    k: TensorId,
) -> (TensorId, TensorId) {
    let r = |ctx: &mut Context, x: TensorId| {
        ctx.rope_ext(
            x,
            pos,
            None,
            p.n_rot as i32,
            p.rope_mode,
            p.n_ctx_orig,
            p.freq_base,
            p.freq_scale,
            p.ext_factor,
            p.attn_factor,
            p.beta_fast,
            p.beta_slow,
        )
    };
    let q = r(ctx, q);
    let k = r(ctx, k);
    (q, k)
}

