pub struct Phi2Params {
    pub attn: AttnParams,
}

/// verify against src/models/phi2.cpp:47-142 `llama_model_phi2::graph::graph` —
/// LayerNorm norms with bias, NEOX rope, the Q pre-scale `1/sqrt(head_dim)`
/// with a softmax scale of exactly 1.0 (:93-99), GELU-seq FFN, and the phi2
/// quirk that the FFN consumes `attn_norm_output` rather than the residual
/// (:108).
#[allow(clippy::too_many_arguments)]
pub fn build_phi2_forward(
    ctx: &mut Context,
    w: &Phi2ModelWeights,
    p: &Phi2Params,
    kv: &KvCache,
    inp: &DecodeInputs,
    sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let _ = sinfo;
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(1024);

    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    for il in 0..n_layer {
        let lw = &w.layers[il];

        let attn_norm_output = build_norm(
            ctx,
            inp_l,
            Some(lw.attn_norm),
            Some(lw.attn_norm_b),
            p.attn.norm_eps,
        );

        // separate Q/K/V + rope + Q pre-scale (phi2.cpp:75-95)
        let (q, k, v) = qkv_separate_parts(
            ctx,
            lw.wq,
            lw.wq_b,
            lw.wk,
            lw.wk_b,
            lw.wv,
            lw.wv_b,
            &p.attn,
            attn_norm_output,
            t,
        );
        let (q, k) = rope_qk(ctx, &p.attn, inp.pos, q, k);
        let q = ctx.scale(q, 1.0 / (p.attn.n_embd_head_k as f32).sqrt());

        // build_attn(..., scale = 1.0f, il) — the 1/sqrt lives in the pre-scale
        let cur = attn_kv_cached(
            ctx,
            &mut graph,
            kv,
            il,
            &p.attn,
            inp,
            n_kv,
            q,
            k,
            v,
            1.0,
            0.0,
            None,
            None,
            Some(lw.wo),
            Some(lw.wo_b),
        );

        // FFN on the *normed* attention input (phi2.cpp:108-115)
        let ffn_output = build_ffn_gelu_seq(
            ctx,
            attn_norm_output,
            lw.ffn_up,
            Some(lw.ffn_up_b),
            lw.ffn_down,
            Some(lw.ffn_down_b),
        );

        let cur = ctx.add(cur, ffn_output);
        inp_l = ctx.add(cur, inp_l);
    }

    let cur = build_norm(
        ctx,
        inp_l,
        Some(w.output_norm),
        Some(w.output_norm_b),
        p.attn.norm_eps,
    );
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let mut logits = crate::adapter::lora_mm(ctx, w.output, cur);
    logits = ctx.add(logits, w.output_b);
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

