/// verify against src/models/starcoder2.cpp:59-157
/// `llama_model_starcoder2::graph::graph` — LayerNorm norms with biases, NEOX
/// rope, split Q/K/V, GELU-seq FFN. Numerically this is phi2/llama-shaped with
/// LayerNorm and the standard softmax scale.
#[allow(clippy::too_many_arguments)]
pub fn build_starcoder2_forward(
    ctx: &mut Context,
    w: &StarCoder2ModelWeights,
    p: &StarCoder2Params,
    kv: &KvCache,
    inp: &DecodeInputs,
    sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let _ = sinfo;
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(1024);

    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_sa = inp_l;

        let cur = build_norm(
            ctx,
            inp_l,
            Some(lw.attn_norm),
            Some(lw.attn_norm_b),
            p.attn.norm_eps,
        );
        let (q, k, v) = qkv_separate_parts(
            ctx, lw.wq, lw.wq_b, lw.wk, lw.wk_b, lw.wv, lw.wv_b, &p.attn, cur, t,
        );
        let (q, k) = rope_qk(ctx, &p.attn, inp.pos, q, k);

        let kq_scale = 1.0 / (p.attn.n_embd_head_k as f32).sqrt();
        let cur = attn_kv_cached(
            ctx,
            &mut graph,
            kv,
            il,
            &p.attn,
            inp,
            n_kv,
            q,
            k,
            v,
            kq_scale,
            0.0,
            None,
            None,
            Some(lw.wo),
            lw.wo_b,
        );

        let ffn_inp = ctx.add(cur, inp_sa);
        let cur = build_norm(
            ctx,
            ffn_inp,
            Some(lw.ffn_norm),
            Some(lw.ffn_norm_b),
            p.attn.norm_eps,
        );
        let cur = build_ffn_gelu_seq(
            ctx,
            cur,
            lw.ffn_up,
            Some(lw.ffn_up_b),
            lw.ffn_down,
            Some(lw.ffn_down_b),
        );
        inp_l = ctx.add(cur, ffn_inp);
    }

    let cur = build_norm(
        ctx,
        inp_l,
        Some(w.output_norm),
        Some(w.output_norm_b),
        p.attn.norm_eps,
    );
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let logits = crate::adapter::lora_mm(ctx, w.output, cur);
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

