            qkv_separate_parts(ctx, lw.wq, None, lw.wk, None, lw.wv, None, &p.attn, cur, t);
        let (q, k) = rope_qk(ctx, &p.attn, inp.pos, q, k);

        let kq_scale = 1.0 / (p.attn.n_embd_head_k as f32).sqrt();
