// olmo — src/models/olmo.cpp
// ----------------------------------------------------------------------

pub struct OlmoLayerWeights {
    pub wq: TensorId,
    pub wk: TensorId,
    pub wv: TensorId,
    pub wo: TensorId,
    pub ffn_gate: TensorId,
    pub ffn_down: TensorId,
    pub ffn_up: TensorId,
}

pub struct OlmoModelWeights {
    pub tok_embd: TensorId,
    /// olmo.cpp:21-25 — `output.weight` optional, tied to tok_embd otherwise
    pub output: TensorId,
    pub layers: Vec<OlmoLayerWeights>,
}

pub struct OlmoParams {
    pub attn: AttnParams,
    /// `hparams.f_clamp_kqv` (olmo.cpp:5, optional key, default 0 = off):
    /// build_qkv clamps Q/K/V to ±f_clamp_kqv when > 0
    /// (llama-graph.cpp:1710-1719).
    pub f_clamp_kqv: f32,
}

/// verify against src/models/olmo.cpp:43-142 `llama_model_olmo::graph::graph` — the
/// weightless-norm arch of the batch: `build_norm(cur, NULL, NULL, LLM_NORM)`
/// is a plain `ggml_norm` at every one of the three sites (:65-67, :104-106,
/// :128-130); NORM-mode rope, parallel SILU FFN, sequential residuals.
#[allow(clippy::too_many_arguments)]
pub fn build_olmo_forward(
    ctx: &mut Context,
    w: &OlmoModelWeights,
    p: &OlmoParams,
    kv: &KvCache,
    inp: &DecodeInputs,
    sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let _ = sinfo;
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(1024);

    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_sa = inp_l;

        // olmo.cpp:65-67 — the file has no norm weight/bias at all
        let cur = build_norm(ctx, inp_l, None, None, p.attn.norm_eps);

        let (mut q, mut k, mut v) =
            qkv_separate_parts(ctx, lw.wq, None, lw.wk, None, lw.wv, None, &p.attn, cur, t);
        // build_qkv's f_clamp_kqv branch (llama-graph.cpp:1710-1719), reached
        // only when the file carries `attention.clamp_kqv > 0`
        if p.f_clamp_kqv > 0.0 {
            let lim = p.f_clamp_kqv;
            q = ctx.clamp(q, -lim, lim);
            k = ctx.clamp(k, -lim, lim);
            v = ctx.clamp(v, -lim, lim);
        }
        let (q, k) = rope_qk(ctx, &p.attn, inp.pos, q, k);

        let kq_scale = 1.0 / (p.attn.n_embd_head_k as f32).sqrt();
        let cur = attn_kv_cached(
            ctx,
            &mut graph,
            kv,
            il,
            &p.attn,
            inp,
            n_kv,
            q,
            k,
            v,
            kq_scale,
            0.0,
            None,
            None,
            Some(lw.wo),
            None,
        );

        let ffn_inp = ctx.add(cur, inp_sa);
        // olmo.cpp:104-106 — again weightless
        let cur = build_norm(ctx, ffn_inp, None, None, p.attn.norm_eps);
        let cur = build_ffn_silu_par(
            ctx,
            cur,
            lw.ffn_gate,
            None,
            lw.ffn_up,
            None,
            lw.ffn_down,
            None,
        );
        inp_l = ctx.add(cur, ffn_inp);
    }

    // olmo.cpp:128-130
    let cur = build_norm(ctx, inp_l, None, None, p.attn.norm_eps);
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let logits = crate::adapter::lora_mm(ctx, w.output, cur);
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

