/// verify against src/models/xverse.cpp:41-136 `llama_model_xverse::graph::graph` —
/// RMS norms, NEOX rope, parallel SILU FFN, sequential residuals. The body is
/// the same code as [`build_internlm2_forward`]: internlm2.cpp's graph differs
/// only in `rope_type` (llama-model.cpp:2935 NORM vs :2937 NEOX).
#[allow(clippy::too_many_arguments)]
pub fn build_xverse_forward(
    ctx: &mut Context,
    w: &XverseModelWeights,
    p: &XverseParams,
    kv: &KvCache,
    inp: &DecodeInputs,
    sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let _ = sinfo;
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(1024);

    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_sa = inp_l;

        let cur = build_norm_rms(ctx, inp_l, lw.attn_norm, p.attn.norm_eps);
        let (q, k, v) =
            qkv_separate_parts(ctx, lw.wq, None, lw.wk, None, lw.wv, None, &p.attn, cur, t);
        let (q, k) = rope_qk(ctx, &p.attn, inp.pos, q, k);

        let kq_scale = 1.0 / (p.attn.n_embd_head_k as f32).sqrt();
        let cur = attn_kv_cached(
            ctx,
            &mut graph,
            kv,
            il,
            &p.attn,
            inp,
            n_kv,
            q,
            k,
            v,
            kq_scale,
            0.0,
            None,
            None,
            Some(lw.wo),
            None,
        );

        let ffn_inp = ctx.add(cur, inp_sa);
        let cur = build_norm_rms(ctx, ffn_inp, lw.ffn_norm, p.attn.norm_eps);
        let cur = build_ffn_silu_par(
            ctx,
            cur,
            lw.ffn_gate,
            None,
            lw.ffn_up,
            None,
            lw.ffn_down,
            None,
        );
        inp_l = ctx.add(cur, ffn_inp);
    }

    let cur = build_norm_rms(ctx, inp_l, w.output_norm, p.attn.norm_eps);
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let logits = crate::adapter::lora_mm(ctx, w.output, cur);
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

