/// verify against src/models/falcon.cpp:50-161 `llama_model_falcon::graph::graph` —
/// fused QKV (no bias), NEOX rope, and the two falcon-specific shapes: the FFN
/// consumes the **attention** norm tensor rather than a separate ffn_norm
/// (there is no ffn_norm tensor in a falcon file, :125-130) and the layer's
/// residual is the double add `x + attn(ln(x)) + ffn(ln(x))` (:134-135).
/// `attn_norm_2` (40B) replaces the attention input when the file carries it
/// (:79-88), while the FFN keeps using `attn_norm`.
#[allow(clippy::too_many_arguments)]
pub fn build_falcon_forward(
    ctx: &mut Context,
    w: &FalconModelWeights,
    p: &FalconParams,
    kv: &KvCache,
    inp: &DecodeInputs,
    sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let _ = sinfo;
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(1024);

    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    for il in 0..n_layer {
        let lw = &w.layers[il];

        // falcon.cpp:71-75
        let attn_norm = build_norm(
            ctx,
            inp_l,
            Some(lw.attn_norm),
            Some(lw.attn_norm_b),
            p.attn.norm_eps,
        );

        // falcon.cpp:79-88 — 40B feeds the attention from attn_norm_2
        let cur = match lw.attn_norm_2 {
            Some(w2) => build_norm(ctx, inp_l, Some(w2), lw.attn_norm_2_b, p.attn.norm_eps),
            None => attn_norm,
        };

        let (q, k, v) = qkv_fused(ctx, lw.wqkv, None, &p.attn, cur, t);
        let (q, k) = rope_qk(ctx, &p.attn, inp.pos, q, k);

        let kq_scale = 1.0 / (p.attn.n_embd_head_k as f32).sqrt();
        let cur = attn_kv_cached(
            ctx,
            &mut graph,
            kv,
            il,
            &p.attn,
            inp,
            n_kv,
            q,
            k,
            v,
            kq_scale,
            0.0,
            None,
            None,
            Some(lw.wo),
            None,
        );

        let ffn_inp = cur;
        // falcon.cpp:125-130 — GELU-seq FFN fed by the attention norm
        let cur = build_ffn_gelu_seq(ctx, attn_norm, lw.ffn_up, None, lw.ffn_down, None);
        // falcon.cpp:134-135 — both residuals
        let cur = ctx.add(cur, ffn_inp);
        inp_l = ctx.add(cur, inp_l);
    }

    let cur = build_norm(
        ctx,
        inp_l,
        Some(w.output_norm),
        Some(w.output_norm_b),
        p.attn.norm_eps,
    );
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let logits = crate::adapter::lora_mm(ctx, w.output, cur);
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

// ======================================================================
// arch batch 3 (2026-09-27): the ALiBi family + the cheap no-rope archs —
// baichuan / bloom / mpt / starcoder / refact / plamo / stablelm /
// granite(dense) / minicpm.
//
// The batch's shared mechanism is ALiBi: `attn_kv_cached`'s `max_bias`
// parameter (llama-graph.cpp:2643/:2705 — hparams.f_max_alibi_bias) and the
// KQ mask's kept value `-|p0 - p1|` (llama-kv-cache.cpp:1693-1697, port
// `graph::fill_kq_mask_alibi*`). Every pre-existing call site keeps 0.0; the
// alibi archs (baichuan-13B / bloom / mpt-with-KV / refact) pass their real
// bias and their driver fills the alibi mask.
//
// New helpers beyond the batch-1/2 set:
//   * `build_ffn_gelu_seq_scales` — build_ffn's `act_scales` parameter of the
//     GELU branch (llama-graph.cpp:1866-1868, `ggml_div` after the gelu; mpt's
//     AWQ ScaleActivation)
//   * `qkv_fused_clamp` — build_qkv's fused branch with the f_clamp_kqv
//     pre-split clamp (llama-graph.cpp:1649-1681)
// ======================================================================

/// `build_ffn` LLM_FFN_GELU + LLM_FFN_SEQ with the optional `act_scales`
/// (llama-graph.cpp:1866-1868): `cur = ggml_div(cur, act_scales)` right after
/// the gelu and *before* the down projection — the scales are [n_ff], the
/// gelu output [n_ff, n_tokens]. mpt's AWQ ScaleActivation undo
/// (`ffn_act.scales`, mpt.cpp:52).
#[allow(clippy::too_many_arguments)]
fn build_ffn_gelu_seq_scales(
    ctx: &mut Context,
    cur: TensorId,
    up: TensorId,
    up_b: Option<TensorId>,
    down: TensorId,
    down_b: Option<TensorId>,
    act_scales: Option<TensorId>,
) -> TensorId {
    let mut u = crate::adapter::lora_mm(ctx, up, cur);
    if let Some(b) = up_b {
        u = ctx.add(u, b);
    }
    // LLM_FFN_GELU (llama-graph.cpp:1795-1800) + act_scales (:1866-1868)
    let g = ctx.gelu(u);
    let g = if let Some(s) = act_scales {
        ctx.div(g, s)
    } else {
        g
    };
    let mut out = crate::adapter::lora_mm(ctx, down, g);
    if let Some(b) = down_b {
        out = ctx.add(out, b);
    }
    out
}

/// build_qkv's fused branch (llama-graph.cpp:1649-1681) with mpt's
/// `f_clamp_kqv`: the clamp hits the fused 2D qkv *before* the view_3d split
/// (:1662-1664) — same order as C, unlike `qkv_separate_parts`' post-reshape
/// clamp (numerically identical there, kept for the existing olmo arm).
#[allow(clippy::too_many_arguments)]
fn qkv_fused_clamp(
    lw_qkv: TensorId,
    lw_qkv_b: Option<TensorId>,
    f_clamp_kqv: f32,
    p: &AttnParams,
    ctx: &mut Context,
    cur: TensorId,
    t: i64,
) -> (TensorId, TensorId, TensorId) {
    let mut qkv = crate::adapter::lora_mm(ctx, lw_qkv, cur);
    if let Some(b) = lw_qkv_b {
        qkv = ctx.add(qkv, b);
    }
    if f_clamp_kqv > 0.0 {
        qkv = ctx.clamp(qkv, -f_clamp_kqv, f_clamp_kqv);
    }
    let n_embd_q = p.n_embd_head_k * p.n_head;
    let n_embd_k = p.n_embd_head_k * p.n_head_kv;
    let nb1 = ctx.nb(qkv)[1] as usize;
    let hd_k = p.n_embd_head_k as usize;
    let hd_v = p.n_embd_head_v as usize;
    let q = ctx.view_3d(qkv, p.n_embd_head_k, p.n_head, t, hd_k * 4, nb1, 0);
    let k = ctx.view_3d(
        qkv,
        p.n_embd_head_k,
        p.n_head_kv,
        t,
        hd_k * 4,
        nb1,
        n_embd_q as usize * 4,
    );
    let v = ctx.view_3d(
        qkv,
        p.n_embd_head_v,
        p.n_head_kv,
        t,
        hd_v * 4,
        nb1,
        (n_embd_q + n_embd_k) as usize * 4,
    );
    (q, k, v)
}

