// baichuan — src/models/baichuan.cpp
// ----------------------------------------------------------------------

pub struct BaichuanLayerWeights {
    pub attn_norm: TensorId,
    pub wq: TensorId,
    pub wk: TensorId,
    pub wv: TensorId,
    pub wo: TensorId,
    pub ffn_norm: TensorId,
    pub ffn_gate: TensorId,
    pub ffn_down: TensorId,
    pub ffn_up: TensorId,
}

pub struct BaichuanModelWeights {
    pub tok_embd: TensorId,
    pub output_norm: TensorId,
    /// baichuan.cpp:18-21 — required, never tied
    pub output: TensorId,
    pub layers: Vec<BaichuanLayerWeights>,
}

/// baichuan.cpp:4-15: the 7B (n_layer == 32) ropes and has **no** alibi; the
/// 13B (n_layer == 40) has `f_max_alibi_bias = 8` and **no** rope; any other
/// depth is LLM_TYPE_UNKNOWN — neither rope nor alibi (the graph's switch at
/// baichuan.cpp:58-77).
#[derive(Clone, Copy)]
pub struct BaichuanParams {
    pub attn: AttnParams,
    /// hparams.f_max_alibi_bias — 8.0 on the 13B, 0.0 otherwise
    pub f_max_alibi_bias: f32,
    /// `model.type == LLM_TYPE_7B` gate of the rope calls (baichuan.cpp:58)
    pub use_rope: bool,
}

/// verify against src/models/baichuan.cpp:28-121 `graph::graph` — RMS norms, separate
/// Q/K/V, rope only on the 7B, ALiBi attention on the 13B, SwiGLU FFN.
#[allow(clippy::too_many_arguments)]
pub fn build_baichuan_forward(
    ctx: &mut Context,
    w: &BaichuanModelWeights,
    p: &BaichuanParams,
    kv: &KvCache,
    inp: &DecodeInputs,
    sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let _ = sinfo;
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(1024);

    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_sa = inp_l;

        // build_norm(LLM_NORM_RMS) (baichuan.cpp:48-51)
        let cur = build_norm_rms(ctx, inp_l, lw.attn_norm, p.attn.norm_eps);

        // build_qkv (baichuan.cpp:55-56) + the type switch of :58-77
        let (q, k, v) =
            qkv_separate_parts(ctx, lw.wq, None, lw.wk, None, lw.wv, None, &p.attn, cur, t);
        let (q, k) = if p.use_rope {
            rope_qk(ctx, &p.attn, inp.pos, q, k)
        } else {
            (q, k)
        };

        // build_attn(..., 1/sqrt(n_embd_head), il) with hparams.f_max_alibi_bias
        let kq_scale = 1.0 / (p.attn.n_embd_head_k as f32).sqrt();
        let cur = attn_kv_cached(
            ctx,
            &mut graph,
            kv,
            il,
            &p.attn,
            inp,
            n_kv,
            q,
            k,
            v,
            kq_scale,
            p.f_max_alibi_bias,
            None,
            None,
            Some(lw.wo),
            None,
        );

        // residual (baichuan.cpp:86-88)
        let ffn_inp = ctx.add(cur, inp_sa);

        // ffn_norm + SwiGLU FFN (baichuan.cpp:91-104)
        let cur = build_norm_rms(ctx, ffn_inp, lw.ffn_norm, p.attn.norm_eps);
        let cur = build_ffn_silu_par(
            ctx,
            cur,
            lw.ffn_gate,
            None,
            lw.ffn_up,
            None,
            lw.ffn_down,
            None,
        );
        inp_l = ctx.add(cur, ffn_inp);
    }

    // output_norm + lm_head (baichuan.cpp:110-118)
    let cur = build_norm_rms(ctx, inp_l, w.output_norm, p.attn.norm_eps);
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let logits = crate::adapter::lora_mm(ctx, w.output, cur);
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

