/// verify against src/models/plamo.cpp:39-136 `graph::graph` — RMS norm, separate
/// Q/K/V, NEOX rope, and the plamo residual quirk: the FFN consumes the
/// *normed* attention input (`sa_inp`) and the layer output is
/// `ffn(sa_inp) + attn_out + inpL` (plamo.cpp:68-113, no second norm tensor).
#[allow(clippy::too_many_arguments)]
pub fn build_plamo_forward(
    ctx: &mut Context,
    w: &PlamoModelWeights,
    p: &PlamoParams,
    kv: &KvCache,
    inp: &DecodeInputs,
    sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let _ = sinfo;
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(1024);

    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    for il in 0..n_layer {
        let lw = &w.layers[il];

        // norm → sa_inp (plamo.cpp:52-60)
        let sa_inp = build_norm_rms(ctx, inp_l, lw.attn_norm, p.attn.norm_eps);

        // Q/K/V + rope (plamo.cpp:64-80; the rope n_dims is n_embd_head,
        // equal to n_rot by the graph's assert)
        let (q, k, v) = qkv_separate_parts(
            ctx, lw.wq, None, lw.wk, None, lw.wv, None, &p.attn, sa_inp, t,
        );
        let (q, k) = rope_qk(ctx, &p.attn, inp.pos, q, k);

        let kq_scale = 1.0 / (p.attn.n_embd_head_k as f32).sqrt();
        let sa_out = attn_kv_cached(
            ctx,
            &mut graph,
            kv,
            il,
            &p.attn,
            inp,
            n_kv,
            q,
            k,
            v,
            kq_scale,
            0.0,
            None,
            None,
            Some(lw.wo),
            None,
        );

        // FFN on sa_inp, then both residuals (plamo.cpp:92-110)
        let cur = build_ffn_silu_par(
            ctx,
            sa_inp,
            lw.ffn_gate,
            None,
            lw.ffn_up,
            None,
            lw.ffn_down,
            None,
        );
        let cur = ctx.add(cur, sa_out);
        inp_l = ctx.add(cur, inp_l);
    }

    // output_norm + lm_head (plamo.cpp:116-126)
    let cur = build_norm_rms(ctx, inp_l, w.output_norm, p.attn.norm_eps);
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let logits = crate::adapter::lora_mm(ctx, w.output, cur);
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

