pub struct StablelmParams {
    pub attn: AttnParams,
}

/// verify against src/models/stablelm.cpp:43-172 `graph::graph` — LayerNorm, separate
/// Q/K/V, optional per-head Q/K LayerNorms (over dim0 = head_dim, the 3D
/// tensor shape), NEOX rope, SwiGLU FFN on either the second norm
/// (sequential) or the attention norm (parallel residual).
#[allow(clippy::too_many_arguments)]
pub fn build_stablelm_forward(
    ctx: &mut Context,
    w: &StablelmModelWeights,
    p: &StablelmParams,
    kv: &KvCache,
    inp: &DecodeInputs,
    sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let _ = sinfo;
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(1024);

    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    for il in 0..n_layer {
        let lw = &w.layers[il];

        // attn_norm = LN(inpL)*w+b; inpSA keeps the normed value for the
        // parallel-residual branch (stablelm.cpp:51-61)
        let inp_sa = build_norm(
            ctx,
            inp_l,
            Some(lw.attn_norm),
            Some(lw.attn_norm_b),
            p.attn.norm_eps,
        );

        // Q/K/V + optional per-head norms + rope (stablelm.cpp:64-99)
        let (mut q, mut k, v) = qkv_separate_parts(
            ctx, lw.wq, None, lw.wk, None, lw.wv, None, &p.attn, inp_sa, t,
        );
        if let Some(qn) = lw.attn_q_norm {
            // build_norm on the 3D Qcur: ggml_norm reduces dim0 = n_embd_head,
            // the [n_embd_head_k, n_head] weight broadcasts over dim1
            q = build_norm(ctx, q, Some(qn), None, p.attn.norm_eps);
        }
        if let Some(kn) = lw.attn_k_norm {
            k = build_norm(ctx, k, Some(kn), None, p.attn.norm_eps);
        }
        let (q, k) = rope_qk(ctx, &p.attn, inp.pos, q, k);

        let kq_scale = 1.0 / (p.attn.n_embd_head_k as f32).sqrt();
        let cur = attn_kv_cached(
            ctx,
            &mut graph,
            kv,
            il,
            &p.attn,
            inp,
            n_kv,
            q,
            k,
            v,
            kq_scale,
            0.0,
            None,
            None,
            Some(lw.wo),
            None,
        );

        // ffn_inp = attn_out + inpL (stablelm.cpp:101)
        let ffn_inp = ctx.add(cur, inp_l);

        // ffn_norm present → sequential; absent → parallel residual on inpSA
        // (stablelm.cpp:106-138)
        let cur = if let Some(fn_) = lw.ffn_norm {
            build_norm(ctx, ffn_inp, Some(fn_), lw.ffn_norm_b, p.attn.norm_eps)
        } else {
            inp_sa
        };
        let cur = build_ffn_silu_par(
            ctx,
            cur,
            lw.ffn_gate,
            None,
            lw.ffn_up,
            None,
            lw.ffn_down,
            None,
        );
        inp_l = ctx.add(cur, ffn_inp);
    }

    // output_norm (biased) + lm_head (stablelm.cpp:147-160)
    let cur = build_norm(
        ctx,
        inp_l,
        Some(w.output_norm),
        Some(w.output_norm_b),
        p.attn.norm_eps,
    );
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let logits = crate::adapter::lora_mm(ctx, w.output, cur);
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

// ----------------------------------------------------------------------
// granite (dense) + minicpm — src/models/granite.cpp + src/models/minicpm.cpp
// (`llama_model_minicpm::graph = llama_model_granite::graph`, models.h:1739)
// ----------------------------------------------------------------------

impl GraniteParams {
    /// Dense granite / minicpm assembly (granite.cpp:123-320, no recurrent
    /// layers): every layer attends, `has_rope` follows `hparams.rope_pattern`
    /// (rope_finetuned), and the mamba2 fields are inert (`is_recr` all false
    /// ⇒ `build_mamba2_layer` is never reached).
    pub fn dense(
        attn: AttnParams,
        hp: &crate::hparams::LlamaHparams,
        f_logit_scale: f32,
        f_residual_scale: f32,
        f_embedding_scale: f32,
        f_attention_scale: f32,
    ) -> Self {
        let n_layer = hp.n_layer() as usize;
        fn per<F: Fn(usize) -> u32>(n_layer: usize, f: F) -> Vec<u32> {
            (0..n_layer).map(f).collect()
        }
        GraniteParams {
            attn,
            n_embd: hp.n_embd as i64,
            n_head: per(n_layer, |il| hp.n_head(il)),
            n_head_kv: per(n_layer, |il| hp.n_head_kv(il)),
            n_embd_head_k: per(n_layer, |il| hp.n_embd_head_k(il)),
            n_embd_head_v: per(n_layer, |il| hp.n_embd_head_v(il)),
            is_recr: vec![false; n_layer],
            has_rope: (0..n_layer).map(|il| hp.has_rope(il)).collect(),
            d_conv: 0,
            d_inner: 0,
            d_state: 0,
            n_ssm_head: 0,
            n_group: 0,
            f_logit_scale,
            f_residual_scale,
            f_embedding_scale,
            f_attention_scale,
            n_expert: hp.n_expert as i64,
            n_expert_used: per(n_layer, |il| hp.n_expert_used(il)),
            n_ff_shexp: hp.n_ff_shexp as i64,
            expert_weights_scale: hp.expert_weights_scale,
            n_embd_r: 0,
            n_embd_s: 0,
        }
    }
}

// ======================================================================
// arch batch 4 (2026-09-28) — the MoE family
//
// granite-moe needs no builder of its own: `llama_model_granite_moe::graph`
// is `llama_model_granite::graph` (models.h:1680) and the port's
// `build_granite_forward` already carries that graph's MoE + shared-expert
// branch (`build_granite_ffn`); `GraniteParams::dense` fills the MoE fields
// (n_expert / n_expert_used / n_ff_shexp) off hparams. The archs below each
// get their own 1:1 builder; all of them route through the shared
// `build_moe_ffn_silu` (llama-graph.cpp:1993-2360) with the arch's own
// top-k/normalization constants.
// ======================================================================

/// `build_norm` LLM_NORM_RMS with an optional bias (llama-graph.cpp:1583-1613):
/// rms_norm → `*mw` → `+mb` — phimoe is the only RMS arch of the batch whose
/// loader creates the bias halves.
fn build_norm_rms_b(
    ctx: &mut Context,
    x: TensorId,
    w: TensorId,
    b: Option<TensorId>,
    eps: f32,
) -> TensorId {
    let mut cur = build_norm_rms(ctx, x, w, eps);
    if let Some(b) = b {
        cur = ctx.add(cur, b);
    }
    cur
}

