/// verify against src/models/qwen2moe.cpp:65-194 — RMS attn_norm → QKV + RoPE NEOX →
/// MHA → residual → RMS ffn_norm → **MoE with `norm_w = false`** (the shared
/// expert supplies the missing mass) + the sigmoid-gated shared expert
/// (`silu(x)/x` on the 1-D router output, qwen2moe.cpp:147-165) → residual.
#[allow(clippy::too_many_arguments)]
pub fn build_qwen2moe_forward(
    ctx: &mut Context,
    w: &Qwen2MoeModelWeights,
    p: &Qwen2MoeParams,
    kv: &KvCache,
    inp: &DecodeInputs,
    sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let _ = sinfo;
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(2048);

    // inpL = build_inp_embd (qwen2moe.cpp:74)
    let inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    let mut inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_sa = inp_l;

        // attn_norm (qwen2moe.cpp:87-89)
        let cur = build_norm_rms(ctx, inp_l, lw.attn_norm, p.attn.norm_eps);

        // build_qkv (qwen2moe.cpp:95-96) — fused or separate, both accepted
        // by create_tensor_qkv
        let (q, k, v) = if let Some(wqkv) = lw.wqkv {
            qkv_fused(ctx, wqkv, lw.wqkv_b, &p.attn, cur, t)
        } else {
            qkv_separate_parts(
                ctx,
                lw.wq.expect("wq"),
                lw.wq_b,
                lw.wk.expect("wk"),
                lw.wk_b,
                lw.wv.expect("wv"),
                lw.wv_b,
                &p.attn,
                cur,
                t,
            )
        };
        let (q, k) = rope_qk(ctx, &p.attn, inp.pos, q, k);

        // build_attn kq_scale = 1/sqrt(n_embd_head) (qwen2moe.cpp:114-116)
        let kq_scale = 1.0 / (p.attn.n_embd_head_v as f32).sqrt();
        let cur = attn_kv_cached(
            ctx,
            &mut graph,
            kv,
            il,
            &p.attn,
            inp,
            n_kv,
            q,
            k,
            v,
            kq_scale,
            0.0,
            None,
            None,
            Some(lw.wo),
            None,
        );

        // ffn_inp = attn + inpSA (qwen2moe.cpp:122)
        let ffn_inp = ctx.add(cur, inp_sa);

        // MoE branch (qwen2moe.cpp:126-143): norm_w = false
        let cur = build_norm_rms(ctx, ffn_inp, lw.ffn_norm, p.attn.norm_eps);
        let mut moe_out = build_moe_ffn_silu(
            ctx,
            &mut graph,
            cur,
            lw.ffn_gate_inp,
            None,
            lw.ffn_up_exps,
            None,
            Some(lw.ffn_gate_exps),
            None,
            lw.ffn_down_exps,
            None,
            None,
            p.n_expert,
            p.n_expert_used,
            false,
            p.expert_weights_scale,
            EXPERT_GATING_SOFTMAX,
        );

        // FFN shared expert (qwen2moe.cpp:145-169)
        {
            // cur_gate_inp = shexp_router @ cur — [1, T]
            let cur_gate_inp = crate::adapter::lora_mm(ctx, lw.ffn_gate_inp_shexp, cur);
            // sigmoid, computed as silu(x)/x (qwen2moe.cpp:151)
            let silu_x = ctx.silu(cur_gate_inp);
            let cur_gate = ctx.div(silu_x, cur_gate_inp);
            let cur_ffn = build_ffn_silu_par(
                ctx,
                cur,
                lw.ffn_gate_shexp,
                None,
                lw.ffn_up_shexp,
                None,
                lw.ffn_down_shexp,
                None,
            );
            let ffn_shexp_out = ctx.mul(cur_ffn, cur_gate);
            moe_out = ctx.add(moe_out, ffn_shexp_out);
        }

        inp_l = ctx.add(moe_out, ffn_inp);
    }

    // final norm + lm_head (qwen2moe.cpp:180-191)
    let cur = build_norm_rms(ctx, inp_l, w.output_norm, p.attn.norm_eps);
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let logits = crate::adapter::lora_mm(ctx, w.output, cur);
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

