/// verify against src/models/qwen3moe.cpp:62-179 — the qwen3 attention stack (RMS
/// attn_norm → QKV → **per-head Q/K RMS norm before RoPE**, qwen3moe.cpp:97 /
// :106) with the FFN replaced by **MoE with `norm_w = true`** (the only
/// difference to qwen2moe's routing call, qwen3moe.cpp:136-151) and no shared
/// expert.
#[allow(clippy::too_many_arguments)]
pub fn build_qwen3moe_forward(
    ctx: &mut Context,
    w: &Qwen3MoeModelWeights,
    p: &Qwen3MoeParams,
    kv: &KvCache,
    inp: &DecodeInputs,
    sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let _ = sinfo;
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(2048);
    assert_eq!(
        p.attn.n_embd_head_k, p.attn.n_embd_head_v,
        "qwen3moe.cpp:65"
    );
    assert_eq!(p.attn.n_embd_head_k, p.attn.n_rot, "qwen3moe.cpp:66");

    let inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    let mut inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_sa = inp_l;

        // attn_norm (qwen3moe.cpp:86-89)
        let cur = build_norm_rms(ctx, inp_l, lw.attn_norm, p.attn.norm_eps);

        // build_qkv (qwen3moe.cpp:94-95) — separate q/k/v in real files, the
        // fused tensor stays accepted by the loader
        let (q, k, v) = if let Some(wqkv) = lw.wqkv {
            qkv_fused(ctx, wqkv, lw.wqkv_b, &p.attn, cur, t)
        } else {
            qkv_separate_parts(
                ctx,
                lw.wq.expect("wq"),
                lw.wq_b,
                lw.wk.expect("wk"),
                lw.wk_b,
                lw.wv.expect("wv"),
                lw.wv_b,
                &p.attn,
                cur,
                t,
            )
        };

        // per-head Q/K norm before rope (qwen3moe.cpp:97-113)
        let q = build_norm_rms(ctx, q, lw.attn_q_norm, p.attn.norm_eps);
        let q = ctx.rope_ext(
            q,
            inp.pos,
            None,
            p.attn.n_rot as i32,
            p.attn.rope_mode,
            p.attn.n_ctx_orig,
            p.attn.freq_base,
            p.attn.freq_scale,
            p.attn.ext_factor,
            p.attn.attn_factor,
            p.attn.beta_fast,
            p.attn.beta_slow,
        );
        let k = build_norm_rms(ctx, k, lw.attn_k_norm, p.attn.norm_eps);
        let k = ctx.rope_ext(
            k,
            inp.pos,
            None,
            p.attn.n_rot as i32,
            p.attn.rope_mode,
            p.attn.n_ctx_orig,
            p.attn.freq_base,
            p.attn.freq_scale,
            p.attn.ext_factor,
            p.attn.attn_factor,
            p.attn.beta_fast,
            p.attn.beta_slow,
        );

        let kq_scale = 1.0 / (p.attn.n_embd_head_v as f32).sqrt();
        let cur = attn_kv_cached(
            ctx,
            &mut graph,
            kv,
            il,
            &p.attn,
            inp,
            n_kv,
            q,
            k,
            v,
            kq_scale,
            0.0,
            None,
            None,
            Some(lw.wo),
            None,
        );

        // ffn_inp (qwen3moe.cpp:127)
        let ffn_inp = ctx.add(cur, inp_sa);

        // MoE branch (qwen3moe.cpp:130-153): norm_w = true
        let cur = build_norm_rms(ctx, ffn_inp, lw.ffn_norm, p.attn.norm_eps);
        let moe_out = build_moe_ffn_silu(
            ctx,
            &mut graph,
            cur,
            lw.ffn_gate_inp,
            None,
            lw.ffn_up_exps,
            None,
            Some(lw.ffn_gate_exps),
            None,
            lw.ffn_down_exps,
            None,
            None,
            p.n_expert,
            p.n_expert_used,
            true,
            p.expert_weights_scale,
            EXPERT_GATING_SOFTMAX,
        );
        inp_l = ctx.add(moe_out, ffn_inp);
    }

    // final norm + lm_head (qwen3moe.cpp:165-178)
    let cur = build_norm_rms(ctx, inp_l, w.output_norm, p.attn.norm_eps);
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let logits = crate::adapter::lora_mm(ctx, w.output, cur);
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

