/// verify against src/models/phi3.cpp:67-192 (phimoe's graph) with the MoE branch
/// (phi3.cpp:151-165): biased RMS norms (the only RMS arch of the batch with
/// norm biases), fused-or-separate QKV → RoPE (rope_factors at src[2],
/// phi3.cpp:97 — PARTIAL: real phimoe files carry rope_long/rope_short and
/// the C selects per `get_rope_factors`; the port takes the resolved tensor
/// and the synthetic parity file carries none on either side) → Q pre-scale
/// 1/sqrt(head) with softmax scale 1.0 (phi3-style) → residual → biased RMS
/// ffn_norm → MoE `norm_w = true` → residual → biased output_norm → lm_head
/// + output bias.
#[allow(clippy::too_many_arguments)]
pub fn build_phimoe_forward(
    ctx: &mut Context,
    w: &PhimoeModelWeights,
    p: &PhimoeParams,
    kv: &KvCache,
    inp: &DecodeInputs,
    sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let _ = sinfo;
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(2048);

    let inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    let mut inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let residual_in = inp_l;

        // attn_norm (biased RMS — phi3.cpp:99-103)
        let cur = build_norm_rms_b(
            ctx,
            inp_l,
            lw.attn_norm,
            Some(lw.attn_norm_b),
            p.attn.norm_eps,
        );

        // build_qkv (phi3.cpp:105-106): phimoe files carry separate q/k/v
        // (create_tensor_qkv flags 0), the fused tensor stays accepted
        let (q, k, v) = if let Some(wqkv) = lw.wqkv {
            qkv_fused(ctx, wqkv, lw.wqkv_b, &p.attn, cur, t)
        } else {
            qkv_separate_parts(
                ctx,
                lw.wq.expect("wq"),
                lw.wq_b,
                lw.wk.expect("wk"),
                lw.wk_b,
                lw.wv.expect("wv"),
                lw.wv_b,
                &p.attn,
                cur,
                t,
            )
        };

        // rope with the factors at src[2] (phi3.cpp:107-117)
        let rf = lw.rope_factors;
        let q = ctx.rope_ext(
            q,
            inp.pos,
            rf,
            p.attn.n_rot as i32,
            p.attn.rope_mode,
            p.attn.n_ctx_orig,
            p.attn.freq_base,
            p.attn.freq_scale,
            p.attn.ext_factor,
            p.attn.attn_factor,
            p.attn.beta_fast,
            p.attn.beta_slow,
        );
        let k = ctx.rope_ext(
            k,
            inp.pos,
            rf,
            p.attn.n_rot as i32,
            p.attn.rope_mode,
            p.attn.n_ctx_orig,
            p.attn.freq_base,
            p.attn.freq_scale,
            p.attn.ext_factor,
            p.attn.attn_factor,
            p.attn.beta_fast,
            p.attn.beta_slow,
        );

        // Q pre-scale + softmax scale 1.0 (phi3.cpp:123-128)
        let q = ctx.scale(q, 1.0 / (p.attn.n_embd_head_k as f32).sqrt());
        let cur = attn_kv_cached(
            ctx,
            &mut graph,
            kv,
            il,
            &p.attn,
            inp,
            n_kv,
            q,
            k,
            v,
            1.0,
            0.0,
            None,
            None,
            Some(lw.wo),
            Some(lw.wo_b),
        );

        // residual (phi3.cpp:134-135)
        let residual = ctx.add(cur, residual_in);

        // ffn_norm (phi3.cpp:137-140, biased)
        let cur = build_norm_rms_b(
            ctx,
            residual,
            lw.ffn_norm,
            Some(lw.ffn_norm_b),
            p.attn.norm_eps,
        );

        // MoE branch (phi3.cpp:151-165): SILU, norm_w = true, SOFTMAX
        let moe = build_moe_ffn_silu(
            ctx,
            &mut graph,
            cur,
            lw.ffn_gate_inp,
            None,
            lw.ffn_up_exps,
            None,
            Some(lw.ffn_gate_exps),
            None,
            lw.ffn_down_exps,
            None,
            None,
            p.n_expert,
            p.n_expert_used,
            true,
            p.expert_weights_scale,
            EXPERT_GATING_SOFTMAX,
        );
        inp_l = ctx.add(residual, moe);
    }

    // final biased norm + lm_head + output bias (phi3.cpp:174-189)
    let cur = build_norm_rms_b(
        ctx,
        inp_l,
        w.output_norm,
        Some(w.output_norm_b),
        p.attn.norm_eps,
    );
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let mut logits = crate::adapter::lora_mm(ctx, w.output, cur);
    if let Some(b) = w.output_b {
        logits = ctx.add(logits, b);
    }
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

