/// verify against src/models/seed-oss.cpp:45-151 — RMS attn_norm → QKV (q width
/// `n_head*head_dim`, may differ from n_embd) + RoPE → MHA → residual →
/// **attn_post_norm as the FFN norm** (seed-oss.cpp:113-116) → SwiGLU →
/// residual. No q/k norms in this revision's file shape.
#[allow(clippy::too_many_arguments)]
pub fn build_seed_oss_forward(
    ctx: &mut Context,
    w: &SeedOssModelWeights,
    p: &SeedOssParams,
    kv: &KvCache,
    inp: &DecodeInputs,
    sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let _ = sinfo;
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(1024);

    let inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    let mut inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    let kq_scale = if p.f_attention_scale == 0.0 {
        1.0 / (p.attn.n_embd_head_v as f32).sqrt()
    } else {
        p.f_attention_scale
    };

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_sa = inp_l;

        // attn_norm (seed-oss.cpp:73-76)
        let cur = build_norm_rms(ctx, inp_l, lw.attn_norm, p.attn.norm_eps);

        // build_qkv (seed-oss.cpp:81-82) — the q width is n_qo_dim, so the
        // separate projections are spelled out (qkv_separate_parts reads its
        // widths off AttnParams, which carries the same n_head here)
        let (q, k, v) = if let Some(wqkv) = lw.wqkv {
            qkv_fused(ctx, wqkv, lw.wqkv_b, &p.attn, cur, t)
        } else {
            qkv_separate_parts(
                ctx,
                lw.wq.expect("wq"),
                lw.wq_b,
                lw.wk.expect("wk"),
                lw.wk_b,
                lw.wv.expect("wv"),
                lw.wv_b,
                &p.attn,
                cur,
                t,
            )
        };
        let (q, k) = rope_qk(ctx, &p.attn, inp.pos, q, k);

        let cur = attn_kv_cached(
            ctx,
            &mut graph,
            kv,
            il,
            &p.attn,
            inp,
            n_kv,
            q,
            k,
            v,
            kq_scale,
            0.0,
            None,
            None,
            Some(lw.wo),
            None,
        );

        // ffn_inp (seed-oss.cpp:109)
        let ffn_inp = ctx.add(cur, inp_sa);

        // attn_post_norm as the FFN norm (seed-oss.cpp:113-116)
        let cur = build_norm_rms(ctx, ffn_inp, lw.attn_post_norm, p.attn.norm_eps);
        let out = build_ffn_silu_par(
            ctx,
            cur,
            lw.ffn_gate,
            None,
            lw.ffn_up,
            None,
            lw.ffn_down,
            None,
        );
        inp_l = ctx.add(out, ffn_inp);
    }

    // final norm + lm_head (seed-oss.cpp:137-149)
    let cur = build_norm_rms(ctx, inp_l, w.output_norm, p.attn.norm_eps);
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let logits = crate::adapter::lora_mm(ctx, w.output, cur);
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

