pub struct OpenelmLayerWeights {
    pub attn_norm: TensorId,
    /// fused [q | k | v] heads, per-layer widths (openelm.cpp:34)
    pub wqkv: TensorId,
    /// per-head Q norm ([n_embd_head_k], openelm.cpp:35)
    pub attn_q_norm: TensorId,
    /// per-head K norm ([n_embd_head_k], openelm.cpp:36)
    pub attn_k_norm: TensorId,
    pub wo: TensorId,
    pub ffn_norm: TensorId,
    pub ffn_gate: TensorId,
    pub ffn_down: TensorId,
    pub ffn_up: TensorId,
    /// this layer's geometry (openelm.cpp:67-69)
    pub n_head: i64,
    pub n_head_kv: i64,
    pub n_ff: i64,
}

pub struct OpenelmModelWeights {
    pub tok_embd: TensorId,
    pub output_norm: TensorId,
    pub output: TensorId,
    pub layers: Vec<OpenelmLayerWeights>,
}

#[derive(Clone)]
pub struct OpenelmParams {
    pub attn: AttnParams,
}

/// verify against src/models/openelm.cpp:46-171 — the per-layer-heads arch: each layer
/// fuses `[n_head Q | n_head_kv K | n_head_kv V]` heads into one wqkv
/// (openelm.cpp:82-94, the views are *head-interleaved segments* of the
/// reshaped [n_embd_head, n_head_qkv, T] tensor), applies **per-head RMS Q/K
/// norms** (openelm.cpp:96-104) then RoPE, attends with the layer's own head
/// count, and closes with a plain SwiGLU FFN of the layer's own width.
#[allow(clippy::too_many_arguments)]
pub fn build_openelm_forward(
    ctx: &mut Context,
    w: &OpenelmModelWeights,
    p: &OpenelmParams,
    kv: &KvCache,
    inp: &DecodeInputs,
    sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let _ = sinfo;
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(1024);

    let inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    let mut inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_sa = inp_l;

        // this layer's AttnParams — attn_kv_cached reads the cache view
        // geometry off it (openelm.cpp:67-69)
        let mut a = p.attn.clone();
        a.n_head = lw.n_head;
        a.n_head_kv = lw.n_head_kv;

        // attn_norm (openelm.cpp:75-78)
        let cur = build_norm_rms(ctx, inp_l, lw.attn_norm, p.attn.norm_eps);

        // fused wqkv (openelm.cpp:82-94)
        let n_head_qkv = 2 * lw.n_head_kv + lw.n_head;
        let cur = crate::adapter::lora_mm(ctx, lw.wqkv, cur);
        let cur = ctx.reshape_3d(cur, a.n_embd_head_k, n_head_qkv, t);
        let nb1 = ctx.nb(cur)[1] as usize;
        let nb2 = ctx.nb(cur)[2] as usize;
        let q = ctx.view_3d(cur, a.n_embd_head_k, lw.n_head, t, nb1, nb2, 0);
        let k = ctx.view_3d(
            cur,
            a.n_embd_head_k,
            lw.n_head_kv,
            t,
            nb1,
            nb2,
            nb1 * lw.n_head as usize,
        );
        let v = ctx.view_3d(
            cur,
            a.n_embd_head_v,
            lw.n_head_kv,
            t,
            nb1,
            nb2,
            nb1 * (lw.n_head + lw.n_head_kv) as usize,
        );

        // per-head Q/K norms (openelm.cpp:96-104) — [n_embd_head] weights on
        // the 3D views, one row per head per token
        let q = build_norm_rms(ctx, q, lw.attn_q_norm, p.attn.norm_eps);
        let k = build_norm_rms(ctx, k, lw.attn_k_norm, p.attn.norm_eps);

        // rope (openelm.cpp:106-116)
        let q = ctx.rope_ext(
            q,
            inp.pos,
            None,
            a.n_rot as i32,
            a.rope_mode,
            a.n_ctx_orig,
            a.freq_base,
            a.freq_scale,
            a.ext_factor,
            a.attn_factor,
            a.beta_fast,
            a.beta_slow,
        );
        let k = ctx.rope_ext(
            k,
            inp.pos,
            None,
            a.n_rot as i32,
            a.rope_mode,
            a.n_ctx_orig,
            a.freq_base,
            a.freq_scale,
            a.ext_factor,
            a.attn_factor,
            a.beta_fast,
            a.beta_slow,
        );

        let kq_scale = 1.0 / (a.n_embd_head_v as f32).sqrt();
        let cur = attn_kv_cached(
            ctx,
            &mut graph,
            kv,
            il,
            &a,
            inp,
            n_kv,
            q,
            k,
            v,
            kq_scale,
            0.0,
            None,
            None,
            Some(lw.wo),
            None,
        );

        // ffn_inp (openelm.cpp:130)
        let ffn_inp = ctx.add(inp_sa, cur);

        // ffn_norm + SwiGLU FFN of this layer's width (openelm.cpp:134-147)
        let cur = build_norm_rms(ctx, ffn_inp, lw.ffn_norm, p.attn.norm_eps);
        let out = build_ffn_silu_par(
            ctx,
            cur,
            lw.ffn_gate,
            None,
            lw.ffn_up,
            None,
            lw.ffn_down,
            None,
        );
        inp_l = ctx.add(out, ffn_inp);
    }

    // final norm + lm_head (openelm.cpp:157-168)
    let cur = build_norm_rms(ctx, inp_l, w.output_norm, p.attn.norm_eps);
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let logits = crate::adapter::lora_mm(ctx, w.output, cur);
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

