/// The mamba1 mixer tensors of one layer — the `model.layers[il].ssm_*` reads
/// of `llm_build_mamba_base::build_mamba_layer` (mamba-base.cpp:9-151).
pub struct Mamba1Mixer {
    pub ssm_in: TensorId,
    pub ssm_conv1d: TensorId,
    /// mamba.cpp/jamba.cpp load it required; kept non-optional like the C
    pub ssm_conv1d_b: TensorId,
    /// the x_proj {d_inner, dt_rank + 2*d_state}
    pub ssm_x: TensorId,
    /// the dt_proj weight {dt_rank, d_inner}
    pub ssm_dt: TensorId,
    pub ssm_dt_b: TensorId,
    /// FalconMamba/Jamba RMS-norm trio on dt/B/C (mamba-base.cpp:98-105); the
    /// branch runs when `ssm_dt_b_c_rms || (all three present)`
    pub ssm_dt_norm: Option<TensorId>,
    pub ssm_b_norm: Option<TensorId>,
    pub ssm_c_norm: Option<TensorId>,
    pub ssm_a: TensorId,
    pub ssm_d: TensorId,
    pub ssm_out: TensorId,
}

/// `llm_build_mamba_base::build_mamba_layer` (mamba-base.cpp:9-151), the
/// single-sequence slice (n_seqs == 1): in_proj split x/z → causal 1D conv
/// (+bias, silu) with the conv-state write-back → x_proj (dt|B|C, optional
/// RMS trio) → dt_proj + bias → `ggml_ssm_scan` (per-channel A) → final-state
/// write-back → `y + x*D` → swiglu_split(z, ·) → out_proj.
#[allow(clippy::too_many_arguments)]
fn build_mamba1_mixer(
    ctx: &mut Context,
    graph: &mut Graph,
    d_conv: i64,
    d_inner: i64,
    d_state: i64,
    dt_rank: i64,
    ssm_dt_b_c_rms: bool,
    norm_eps: f32,
    m: &Mamba1Mixer,
    st: &RecurrentState,
    il: usize,
    cur: TensorId,
    t: i64,
) -> TensorId {
    // n_head = d_inner, head_dim = 1 (mamba-base.cpp:24-25)
    let one = ctx.new_i32(0); // ids {n_seqs=1}: single cell → slot 0

    // conv = build_rs(...); reshape_3d(d_conv - 1, d_inner, n_seqs)
    let conv_state = st.conv[il].expect("recurrent conv state");
    let conv = ctx.reshape_3d(conv_state, d_conv - 1, d_inner, 1);

    // {n_embd, 2*d_inner} @ {n_embd, n_tokens} => {2*d_inner, n_tokens}
    let xz = crate::adapter::lora_mm(ctx, m.ssm_in, cur);
    // split the above in two (mamba-base.cpp:48-52)
    let xz_nb = *ctx.nb(xz);
    let x = ctx.view_3d(xz, d_inner, t, 1, xz_nb[1] as usize, xz_nb[2] as usize, 0);
    let z = ctx.view_3d(
        xz,
        d_inner,
        t,
        1,
        xz_nb[1] as usize,
        xz_nb[2] as usize,
        d_inner as usize * 4,
    );

    // conv block: state write-back + ssm_conv + bias + silu (mamba-base.cpp:54-83)
    let x = {
        let x_t = ctx.transpose(x);
        let conv_x = ctx.concat(conv, x_t, 0);
        let cx_nb = *ctx.nb(conv_x);
        let row_count = (d_conv - 1) * d_inner;

        // copy last (d_conv - 1) columns back into the state cache
        // (mamba-base.cpp:60-66, K = 1 → slot 0)
        let last_conv = ctx.view_3d(
            conv_x,
            d_conv - 1,
            d_inner,
            1,
            cx_nb[1] as usize,
            cx_nb[2] as usize,
            t as usize * cx_nb[0] as usize,
        );
        let state_nb = *ctx.nb(conv_state);
        let state_dst = ctx.view_2d(conv_state, row_count, 1, state_nb[1] as usize, 0);
        let cpy = ctx.cpy(last_conv, state_dst);
        graph.build_forward(ctx, cpy);

        // 1D convolution + bias + silu
        let x = ctx.ssm_conv(conv_x, m.ssm_conv1d);
        let x = ctx.add(x, m.ssm_conv1d_b);
        ctx.silu(x)
    };

    // ssm block (mamba-base.cpp:85-145)
    // {d_inner, dt_rank + 2*d_state} @ {d_inner, n_tokens} => {dt_rank + 2*d_state, n_tokens}
    let x_db = crate::adapter::lora_mm(ctx, m.ssm_x, x);
    let x_db_nb = *ctx.nb(x_db);
    let dt = ctx.view_3d(
        x_db,
        dt_rank,
        t,
        1,
        x_db_nb[1] as usize,
        x_db_nb[2] as usize,
        0,
    );
    let b4 = ctx.view_4d(
        x_db,
        d_state,
        1,
        t,
        1,
        (d_state * 4) as usize,
        x_db_nb[1] as usize,
        x_db_nb[2] as usize,
        dt_rank as usize * 4,
    );
    let c4 = ctx.view_4d(
        x_db,
        d_state,
        1,
        t,
        1,
        (d_state * 4) as usize,
        x_db_nb[1] as usize,
        x_db_nb[2] as usize,
        (dt_rank + d_state) as usize * 4,
    );

    // Some Mamba variants (e.g. FalconMamba, Jamba) apply RMS norm on B, C & Dt
    // (mamba-base.cpp:98-105)
    let (dt, b4, c4) = if ssm_dt_b_c_rms
        || (m.ssm_dt_norm.is_some() && m.ssm_b_norm.is_some() && m.ssm_c_norm.is_some())
    {
        let dt = build_norm_rms(ctx, dt, m.ssm_dt_norm.expect("ssm_dt_norm"), norm_eps);
        let b4 = build_norm_rms(ctx, b4, m.ssm_b_norm.expect("ssm_b_norm"), norm_eps);
        let c4 = build_norm_rms(ctx, c4, m.ssm_c_norm.expect("ssm_c_norm"), norm_eps);
        (dt, b4, c4)
    } else {
        (ctx.cont(dt), b4, c4)
    };

    // {dt_rank, d_inner} @ {dt_rank, n_tokens} => {d_inner, n_tokens}
    let dt = crate::adapter::lora_mm(ctx, m.ssm_dt, dt);
    let dt = ctx.add(dt, m.ssm_dt_b);

    // cur = x (pre-reshape); x = reshape_4d(x, head_dim=1, n_head=d_inner, ...)
    let cur = x;
    let x4 = ctx.reshape_4d(x, 1, d_inner, t, 1);
    let x4_nb = *ctx.nb(x4);

    // ggml_ssm_scan over the state cell (mamba-base.cpp:119-128) — A is the
    // per-channel {d_state, d_inner} decay (the granular mamba-1 form, K = 1)
    let ssm_state = st.ssm[il].expect("recurrent ssm state");
    let ssm_view = ctx.reshape_4d(ssm_state, d_state, 1, d_inner, 1);
    let y_ssm = ctx.ssm_scan(ssm_view, x4, dt, m.ssm_a, b4, c4, one, 1);

    // store last states (mamba-base.cpp:130-134): the state part of y_ssm sits
    // after nelements(x) floats (x4->nb[3] * x4->ne[3] in C)
    {
        let d = d_state * d_inner;
        let state_offset = (x4_nb[3] * ctx.ne(x4)[3] as u64) as usize;
        let state_src = ctx.view_3d(
            y_ssm,
            d,
            1,
            1,
            (d * 4) as usize,
            (d * 4) as usize,
            state_offset,
        );
        let st_nb = *ctx.nb(ssm_state);
        let state_dst = ctx.view_2d(ssm_state, d, 1, st_nb[1] as usize, 0);
        let cpy = ctx.cpy(state_src, state_dst);
        graph.build_forward(ctx, cpy);
    }

    // y = view_3d(y_ssm, d_inner, n_seq_tokens, n_seqs, x->nb[2], x->nb[3], 0)
    // (mamba-base.cpp:136) — x is the reshaped 4d tensor here, so nb[2]/nb[3]
    // come from x4
    let y = ctx.view_3d(
        y_ssm,
        d_inner,
        t,
        1,
        x4_nb[2] as usize,
        x4_nb[3] as usize,
        0,
    );
    // y += x * ssm_d ; y = swiglu_split(cont(z), y) (mamba-base.cpp:140-141)
    let xd = ctx.mul(cur, m.ssm_d);
    let y = ctx.add(y, xd);
    let zc = ctx.cont(z);
    let y = ctx.swiglu_split(zc, y);

    // {d_inner, n_embd} @ {d_inner, n_tokens} => {n_embd, n_tokens}
    crate::adapter::lora_mm(ctx, m.ssm_out, y)
}

// ----------------------------------------------------------------------
// mamba / mamba2 (src/models/mamba.cpp::graph, mamba2 reuses it via
// models.h:942 `using graph = llama_model_mamba::graph`)
// ----------------------------------------------------------------------

/// One layer of the pure-recurrent mamba/mamba2 stack: the attn_norm plus the
/// mixer (mamba.cpp:75-110 / mamba2.cpp:60-88).
pub struct MambaLayerWeights {
    pub attn_norm: TensorId,
    pub mixer: MambaLayerMixer,
}

pub enum MambaLayerMixer {
    /// mamba.cpp:77-107 (also jamba's mamba layers)
    Mamba1(Mamba1Mixer),
    /// mamba2.cpp:63-86 (also granite-hybrid / nemotron-h's ssm layers)
    Mamba2(Mamba2Mixer),
}

pub struct MambaModelWeights {
    pub tok_embd: TensorId,
    pub output_norm: TensorId,
    pub output: TensorId,
    pub layers: Vec<MambaLayerWeights>,
}

/// The mamba hparams the graphs read (mamba.cpp:3-12 / mamba2.cpp:3-15).
#[derive(Clone)]
pub struct MambaParams {
    pub d_conv: i64,
    pub d_inner: i64,
    pub d_state: i64,
    /// mamba1: dt_rank; mamba2: n_head (hparams.ssm_dt_rank both ways)
    pub dt_rank: i64,
    /// mamba2 only (hparams.ssm_n_group; 0 for mamba1 — its loader never reads
    /// the group-count key, which is what keeps n_embd_r == (d_conv-1)*d_inner)
    pub n_group: i64,
    /// mamba1's `hparams.ssm_dt_b_c_rms` (mamba.cpp:8)
    pub ssm_dt_b_c_rms: bool,
    pub norm_eps: f32,
    /// hparams.n_embd_r / n_embd_s of the recurrent cells (the driver keys its
    /// `RecurrentState` allocation on these)
    pub n_embd_r: u32,
    pub n_embd_s: u32,
}

/// verify against src/models/mamba.cpp:65-112 `llama_model_mamba::graph::graph` —
/// embedding → per layer (rms attn_norm → mamba1 | mamba2 mixer) → residual →
/// final rms norm → lm_head. mamba2 reaches the same graph through
/// `using graph = llama_model_mamba::graph` (models.h:942) with the
/// `model.arch == LLM_ARCH_MAMBA2` branch (mamba.cpp:87).
///
/// Pure-recurrent arch: no KV cache, no rope, no pos input. The recurrent
/// state is the single-seq cell of `RecurrentState` (llama_memory_recurrent
/// without any attention cache, llama-model.cpp:2547).
pub fn build_mamba_forward(
    ctx: &mut Context,
    w: &MambaModelWeights,
    p: &MambaParams,
    st: &RecurrentState,
    inp: &DecodeInputs,
) -> ForwardResult {
    let t = ctx.ne(inp.tokens)[0];
    let n_layer = w.layers.len();
    let mut graph = Graph::new(2048);
    assert_eq!(st.n_layer(), n_layer, "RecurrentState per layer");

    // {n_embd, n_tokens} (build_inp_embd, mamba.cpp:70)
    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    for il in 0..n_layer {
        let lw = &w.layers[il];
        // build_norm(LLM_NORM_RMS) (mamba.cpp:75)
        let cur = build_norm_rms(ctx, inp_l, lw.attn_norm, p.norm_eps);
        let cur = match &lw.mixer {
            // build_mamba_layer (mamba.cpp:79-81)
            MambaLayerMixer::Mamba1(m) => build_mamba1_mixer(
                ctx,
                &mut graph,
                p.d_conv,
                p.d_inner,
                p.d_state,
                p.dt_rank,
                p.ssm_dt_b_c_rms,
                p.norm_eps,
                m,
                st,
                il,
                cur,
                t,
            ),
            // build_mamba2_layer (mamba.cpp:81-83)
            MambaLayerMixer::Mamba2(m) => build_mamba2_mixer(
                ctx, &mut graph, p.d_conv, p.d_inner, p.d_state, p.dt_rank, p.n_group, p.norm_eps,
                m, st, il, cur, t,
            ),
        };
        // residual (mamba.cpp:97-99); the inp_out_ids get_rows of :94-96 only
        // prunes rows, the values are identical (granite precedent)
        inp_l = ctx.add(cur, inp_l);
    }

    // final rmsnorm + lm_head (mamba.cpp:102-110)
    // res->t_embd = cur (mamba.cpp:128) — before the lm_head
    let embd = build_norm_rms(ctx, inp_l, w.output_norm, p.norm_eps);
    let embd = graph::out_rows(ctx, embd, inp.out_ids);
    let cur = crate::adapter::lora_mm(ctx, w.output, embd);
    graph.build_forward(ctx, cur);
    ForwardResult {
        logits: cur,
        graph,
        embd: Some(embd),
    }
}

// ----------------------------------------------------------------------
// jamba (src/models/jamba.cpp:108-198)
// ----------------------------------------------------------------------

/// One jamba layer: attn_norm + (mamba1 mixer | attention) + ffn_norm + the
/// dense|MoE FFN tensors (jamba.cpp:67-123).
pub struct JambaLayerWeights {
    pub attn_norm: TensorId,
    /// mamba layers only
    pub mamba: Option<Mamba1Mixer>,
    /// attention layers only
    pub wq: Option<TensorId>,
    pub wk: Option<TensorId>,
    pub wv: Option<TensorId>,
    pub wq_b: Option<TensorId>,
    pub wk_b: Option<TensorId>,
    pub wv_b: Option<TensorId>,
    pub wo: Option<TensorId>,
    pub ffn_norm: TensorId,
    /// FFN (no MoE)
    pub ffn_gate: Option<TensorId>,
    pub ffn_down: Option<TensorId>,
    pub ffn_up: Option<TensorId>,
    /// MoE branch (jamba.cpp:115-122 — the file carries gate_inp or not)
    pub ffn_gate_inp: Option<TensorId>,
    pub ffn_gate_exps: Option<TensorId>,
    pub ffn_down_exps: Option<TensorId>,
    pub ffn_up_exps: Option<TensorId>,
}

pub struct JambaModelWeights {
    pub tok_embd: TensorId,
    pub output_norm: TensorId,
    pub output: TensorId,
    pub layers: Vec<JambaLayerWeights>,
}

/// jamba.cpp:3-28 load_arch_hparams + the graph's determinants.
#[derive(Clone)]
pub struct JambaParams {
    /// the attention layers' geometry (uniform in every jamba file; derived
    /// at the first attention layer like granite-hybrid)
    pub attn: AttnParams,
    pub n_embd: i64,
    /// hparams.is_recr(il) = n_head_kv(il) == 0 (jamba.cpp:12-14)
    pub is_recr: Vec<bool>,
    pub d_conv: i64,
    pub d_inner: i64,
    pub d_state: i64,
    pub dt_rank: i64,
    pub norm_eps: f32,
    pub n_expert: i64,
    pub n_expert_used: Vec<u32>,
    /// hparams.expert_weights_scale (default 0.0 → build_moe_ffn skips it)
    pub expert_weights_scale: f32,
    /// hparams.n_embd_r / n_embd_s of the recurrent cells
    pub n_embd_r: u32,
    pub n_embd_s: u32,
}

/// verify against src/models/jamba.cpp:108-198 `graph::graph` — embedding → per layer
/// (rms attn_norm → mamba1 mixer | **rope-less** attention) → residual → rms
/// ffn_norm → dense SwiGLU FFN | MoE(softmax, norm_w = false) → residual →
/// final rms norm → lm_head.
///
/// Notes: the attention layers apply no RoPE ("No RoPE :)", jamba.cpp:133) and
/// scale 1/sqrt(n_embd_head) (jamba.cpp:134). The mamba layers are mamba1 with
/// the dt/B/C RMS trio loaded required (jamba.cpp:89-91), so
/// mamba-base.cpp:99's tensor branch always fires for them.
pub fn build_jamba_forward(
    ctx: &mut Context,
    w: &JambaModelWeights,
    p: &JambaParams,
    st: &RecurrentState,
    kv: &KvCache,
    inp: &DecodeInputs,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(4096);
    assert_eq!(st.n_layer(), n_layer, "RecurrentState per layer");
    let a = &p.attn;

    // {n_embd, n_tokens} (jamba.cpp:116)
    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    for il in 0..n_layer {
        let lw = &w.layers[il];
        // build_norm(LLM_NORM_RMS) (jamba.cpp:121)
        let cur = build_norm_rms(ctx, inp_l, lw.attn_norm, p.norm_eps);

        let cur = if p.is_recr[il] {
            // build_mamba_layer with the RMS trio (jamba.cpp:127-129)
            let m = lw.mamba.as_ref().expect("jamba mamba layer mixer");
            build_mamba1_mixer(
                ctx, &mut graph, p.d_conv, p.d_inner, p.d_state, p.dt_rank, false, p.norm_eps, m,
                st, il, cur, t,
            )
        } else {
            // build_qkv — separate q/k/v (+ optional biases), no rope
            // (jamba.cpp:131-133)
            let mut q = crate::adapter::lora_mm(ctx, lw.wq.expect("wq"), cur);
            let mut k = crate::adapter::lora_mm(ctx, lw.wk.expect("wk"), cur);
            let mut v = crate::adapter::lora_mm(ctx, lw.wv.expect("wv"), cur);
            if let Some(b) = lw.wq_b {
                q = ctx.add(q, b);
            }
            if let Some(b) = lw.wk_b {
                k = ctx.add(k, b);
            }
            if let Some(b) = lw.wv_b {
                v = ctx.add(v, b);
            }
            let q = ctx.reshape_3d(q, a.n_embd_head_k, a.n_head, t);
            let k = ctx.reshape_3d(k, a.n_embd_head_k, a.n_head_kv, t);
            let v = ctx.reshape_3d(v, a.n_embd_head_v, a.n_head_kv, t);

            // build_attn(..., 1.0f/sqrtf(float(n_embd_head)), il) (jamba.cpp:134)
            let kq_scale = 1.0 / (a.n_embd_head_v as f32).sqrt();
            attn_kv_cached(
                ctx,
                &mut graph,
                kv,
                il,
                a,
                inp,
                n_kv,
                q,
                k,
                v,
                kq_scale,
                0.0,
                None,
                None,
                Some(lw.wo.expect("wo")),
                None,
            )
        };

        // ffn_inp = ggml_add(inpL, cur) (jamba.cpp:136-139)
        let ffn_inp = ctx.add(inp_l, cur);
        // ffn_norm (jamba.cpp:141)
        let cur = build_norm_rms(ctx, ffn_inp, lw.ffn_norm, p.norm_eps);

        // feed-forward network (jamba.cpp:143-166)
        let cur = if lw.ffn_gate_inp.is_none() {
            // FFN: LLM_FFN_SILU + LLM_FFN_PAR (jamba.cpp:144-152)
            build_ffn_silu_par(
                ctx,
                cur,
                lw.ffn_gate.unwrap(),
                None,
                lw.ffn_up.unwrap(),
                None,
                lw.ffn_down.unwrap(),
                None,
            )
        } else {
            // MoE: softmax gating, norm_w = false, w_scale = expert_weights_scale
            // (jamba.cpp:154-165)
            build_moe_ffn_silu(
                ctx,
                &mut graph,
                cur,
                lw.ffn_gate_inp.unwrap(),
                None,
                lw.ffn_up_exps.unwrap(),
                None,
                lw.ffn_gate_exps,
                None,
                lw.ffn_down_exps.unwrap(),
                None,
                None,
                p.n_expert,
                p.n_expert_used[il] as i64,
                false,
                p.expert_weights_scale,
                EXPERT_GATING_SOFTMAX,
            )
        };

        // residual (jamba.cpp:168)
        inp_l = ctx.add(ffn_inp, cur);
    }

    // final rmsnorm + lm_head (jamba.cpp:170-181)
    // res->t_embd = cur (jamba.cpp) — before the lm_head
    let embd = build_norm_rms(ctx, inp_l, w.output_norm, p.norm_eps);
    let embd = graph::out_rows(ctx, embd, inp.out_ids);
    let cur = crate::adapter::lora_mm(ctx, w.output, embd);
    graph.build_forward(ctx, cur);
    ForwardResult {
        logits: cur,
        graph,
        embd: Some(embd),
    }
}

