/// One nemotron-h layer: the shared attn_norm plus exactly one of {mamba2
/// mixer, attention, FFN(dense|MoE)} — the loader's is_recr/n_ff split
/// (nemotron-h.cpp:85-139).
pub struct NemotronHLayerWeights {
    pub attn_norm: TensorId,
    /// ssm layers
    pub mamba: Option<Mamba2Mixer>,
    /// attention layers
    pub wq: Option<TensorId>,
    pub wk: Option<TensorId>,
    pub wv: Option<TensorId>,
    pub wq_b: Option<TensorId>,
    pub wk_b: Option<TensorId>,
    pub wv_b: Option<TensorId>,
    pub wo: Option<TensorId>,
    pub wo_b: Option<TensorId>,
    /// dense MLP layers (relu² FFN)
    pub ffn_up: Option<TensorId>,
    pub ffn_up_b: Option<TensorId>,
    pub ffn_down: Option<TensorId>,
    pub ffn_down_b: Option<TensorId>,
    /// MoE layers (nemotron-h.cpp:118-130)
    pub ffn_gate_inp: Option<TensorId>,
    pub ffn_exp_probs_b: Option<TensorId>,
    pub ffn_down_exps: Option<TensorId>,
    pub ffn_up_exps: Option<TensorId>,
    /// optional latent projections (nemotron-h.cpp:122-123)
    pub ffn_latent_down: Option<TensorId>,
    pub ffn_latent_up: Option<TensorId>,
    /// the shared expert (required on MoE layers)
    pub ffn_down_shexp: Option<TensorId>,
    pub ffn_up_shexp: Option<TensorId>,
}

pub struct NemotronHModelWeights {
    pub tok_embd: TensorId,
    pub output_norm: TensorId,
    pub output: TensorId,
    pub layers: Vec<NemotronHLayerWeights>,
}

/// nemotron-h.cpp:5-47 load_arch_hparams + the graph's determinants.
#[derive(Clone)]
pub struct NemotronHParams {
    /// the attention layers' geometry (uniform across nemotron-h files)
    pub attn: AttnParams,
    pub n_embd: i64,
    /// hparams.is_recr(il) = il < n_layer && n_head_kv == 0 && n_ff == 0
    /// (nemotron-h.cpp:14-16)
    pub is_recr: Vec<bool>,
    /// hparams.n_ff(il) per layer — the attention-vs-FFN discriminator
    /// (nemotron-h.cpp:102/216)
    pub n_ff: Vec<i64>,
    pub d_conv: i64,
    pub d_inner: i64,
    pub d_state: i64,
    /// n_head of the mamba2 mixer (hparams.ssm_dt_rank)
    pub n_ssm_head: i64,
    pub n_group: i64,
    pub norm_eps: f32,
    /// hparams.f_attention_scale (0.0 → 1/sqrt(n_embd_head), nemotron-h.cpp:273-274)
    pub f_attention_scale: f32,
    pub n_expert: i64,
    pub n_expert_used: Vec<u32>,
    /// hparams.expert_weights_norm / expert_weights_scale (:27-28)
    pub expert_weights_norm: bool,
    pub expert_weights_scale: f32,
    /// hparams.n_embd_r / n_embd_s of the recurrent cells
    pub n_embd_r: u32,
    pub n_embd_s: u32,
}

/// verify against src/models/nemotron-h.cpp:188-264 `graph::graph` — embedding → per
/// layer (rms attn_norm → mamba2 mixer | rope-less attention | relu²
/// FFN(dense|MoE)) → residual → final rms norm → lm_head. The attention and
/// FFN branches are nemotron-h.cpp:266-280 `build_attention_layer` /
/// :282-340 `build_ffn_layer`.
///
/// Notes:
///   * nemotron-h's attention applies **no rope** and the f_attention_scale
///     override (:271-277).
///   * LLM_FFN_RELU_SQR is `relu(x)` then `sqr(x)` (llama-graph.cpp RELU_SQR
///     arm) — the port composes `clamp(x, 0, +inf)` (= C's relu bit-for-bit on
///     finite inputs; the result is immediately squared, so -0.0/+0.0 agree
///     too) and `mul(x, x)` (= C's `ggml_sqr`), because the ggml crate has no
///     dedicated RELU/SQR ops.
///   * the MTP/NextN head (nemotron-h.cpp:142-181, embeddings_nextn_masked)
///     is not ported — the trunk graph of :196-263 needs none of it.
pub fn build_nemotron_h_forward(
    ctx: &mut Context,
    w: &NemotronHModelWeights,
    p: &NemotronHParams,
    st: &RecurrentState,
    kv: &KvCache,
    inp: &DecodeInputs,
    _sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(4096);
    assert_eq!(st.n_layer(), n_layer, "RecurrentState per layer");
    let a = &p.attn;

    // inpL = build_inp_embd (nemotron-h.cpp:196)
    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_sa = inp_l;

        // build_norm(LLM_NORM_RMS) — every block, even the FFN-only ones
        // (nemotron-h.cpp:210)
        let cur = build_norm_rms(ctx, inp_l, lw.attn_norm, p.norm_eps);

        let cur = if p.is_recr[il] {
            // ssm layer (nemotron-h.cpp:215)
            let m = lw.mamba.as_ref().expect("nemotron-h ssm mixer");
            build_mamba2_mixer(
                ctx,
                &mut graph,
                p.d_conv,
                p.d_inner,
                p.d_state,
                p.n_ssm_head,
                p.n_group,
                p.norm_eps,
                m,
                st,
                il,
                cur,
                t,
            )
        } else if p.n_ff[il] == 0 {
            // attention layer (nemotron-h.cpp:216-218 → build_attention_layer)
            let mut q = crate::adapter::lora_mm(ctx, lw.wq.expect("wq"), cur);
            let mut k = crate::adapter::lora_mm(ctx, lw.wk.expect("wk"), cur);
            let mut v = crate::adapter::lora_mm(ctx, lw.wv.expect("wv"), cur);
            if let Some(b) = lw.wq_b {
                q = ctx.add(q, b);
            }
            if let Some(b) = lw.wk_b {
                k = ctx.add(k, b);
            }
            if let Some(b) = lw.wv_b {
                v = ctx.add(v, b);
            }
            let q = ctx.reshape_3d(q, a.n_embd_head_k, a.n_head, t);
            let k = ctx.reshape_3d(k, a.n_embd_head_k, a.n_head_kv, t);
            let v = ctx.reshape_3d(v, a.n_embd_head_v, a.n_head_kv, t);

            let kq_scale = if p.f_attention_scale == 0.0 {
                1.0 / (a.n_embd_head_v as f32).sqrt()
            } else {
                p.f_attention_scale
            };
            attn_kv_cached(
                ctx,
                &mut graph,
                kv,
                il,
                a,
                inp,
                n_kv,
                q,
                k,
                v,
                kq_scale,
                0.0,
                None,
                None,
                Some(lw.wo.expect("wo")),
                lw.wo_b,
            )
        } else {
            // FFN layer (nemotron-h.cpp:219 → build_ffn_layer)
            build_nemotron_h_ffn(ctx, &mut graph, lw, p, il, cur)
        };

        // add residual (nemotron-h.cpp:229)
        inp_l = ctx.add(cur, inp_sa);
    }

    // final rmsnorm + lm_head (nemotron-h.cpp:245-263); the MTP/NextN seed
    // (res->t_h_nextn) and the embeddings get_rows of :223-253 are not part of
    // the trunk decode. res->t_embd = cur (nemotron-h.cpp:256) — before the
    // lm_head
    let embd = build_norm_rms(ctx, inp_l, w.output_norm, p.norm_eps);
    let embd = graph::out_rows(ctx, embd, inp.out_ids);
    let cur = crate::adapter::lora_mm(ctx, w.output, embd);
    graph.build_forward(ctx, cur);
    ForwardResult {
        logits: cur,
        graph,
        embd: Some(embd),
    }
}

/// build_ffn LLM_FFN_RELU_SQR + LLM_FFN_PAR (llama-graph.cpp:1748-1857's
/// RELU_SQR arm): up (+bias) → relu → sqr → down (+bias). `relu` and `sqr` are
/// composed from clamp/mul — see `build_nemotron_h_forward`'s notes.
fn build_ffn_relu_sqr(
    ctx: &mut Context,
    cur: TensorId,
    up: TensorId,
    up_b: Option<TensorId>,
    down: TensorId,
    down_b: Option<TensorId>,
) -> TensorId {
    let mut u = crate::adapter::lora_mm(ctx, up, cur);
    if let Some(b) = up_b {
        u = ctx.add(u, b);
    }
    // cur = ggml_relu(up); cur = ggml_sqr(cur) (llama-graph.cpp:2273-2278)
    let r = ctx.clamp(u, 0.0, f32::INFINITY);
    let s = ctx.mul(r, r);
    let mut out = crate::adapter::lora_mm(ctx, down, s);
    if let Some(b) = down_b {
        out = ctx.add(out, b);
    }
    out
}

/// nemotron-h.cpp:282-340 `build_ffn_layer` — the dense relu² MLP or the MoE
/// branch (sigmoid gating + router bias + relu² experts + optional latent
/// projections + the relu² shared expert).
fn build_nemotron_h_ffn(
    ctx: &mut Context,
    graph: &mut Graph,
    lw: &NemotronHLayerWeights,
    p: &NemotronHParams,
    il: usize,
    cur: TensorId,
) -> TensorId {
    if lw.ffn_gate_inp.is_none() {
        // dense mlp (nemotron-h.cpp:283-290)
        return build_ffn_relu_sqr(
            ctx,
            cur,
            lw.ffn_up.expect("ffn_up"),
            lw.ffn_up_b,
            lw.ffn_down.expect("ffn_down"),
            lw.ffn_down_b,
        );
    }

    // MoE branch (nemotron-h.cpp:291-333)
    let inp_emb = cur;
    let mut inp_latent = cur;
    if let Some(ld) = lw.ffn_latent_down {
        inp_latent = ctx.mul_mat(ld, cur);
    }

    // router on the *embedding* input (nemotron-h.cpp:299)
    let router_logits = crate::adapter::lora_mm(ctx, lw.ffn_gate_inp.unwrap(), cur);

    let moe_out = build_moe_ffn_relu_sqr(
        ctx,
        graph,
        inp_latent,
        lw.ffn_exp_probs_b,
        lw.ffn_up_exps.expect("ffn_up_exps"),
        lw.ffn_down_exps.expect("ffn_down_exps"),
        p.n_expert,
        p.n_expert_used[il] as i64,
        p.expert_weights_norm,
        p.expert_weights_scale,
        router_logits,
    );

    if let Some(lu) = lw.ffn_latent_up {
        let moe_out = ctx.mul_mat(lu, moe_out);
        return finish_nemotron_h_moe(ctx, lw, inp_emb, moe_out);
    }
    finish_nemotron_h_moe(ctx, lw, inp_emb, moe_out)
}

/// the shared-expert add of nemotron-h.cpp:324-332
fn finish_nemotron_h_moe(
    ctx: &mut Context,
    lw: &NemotronHLayerWeights,
    inp_emb: TensorId,
    moe_out: TensorId,
) -> TensorId {
    let ffn_shexp = build_ffn_relu_sqr(
        ctx,
        inp_emb,
        lw.ffn_up_shexp.expect("ffn_up_shexp"),
        None,
        lw.ffn_down_shexp.expect("ffn_down_shexp"),
        None,
    );
    ctx.add(moe_out, ffn_shexp)
}

/// `build_moe_ffn` for nemotron-h's MoE (llama-graph.cpp:1994-2380
/// instantiated with probs_in = the precomputed router logits, no gate
/// experts, exp_probs_b, LLM_FFN_RELU_SQR, SIGMOID gating): sigmoid probs →
/// selection bias → top-k → weights (norm/scale) → up experts → relu² → down
/// experts → `* weights` → the n_expert_used view aggregate.
#[allow(clippy::too_many_arguments)]
fn build_moe_ffn_relu_sqr(
    ctx: &mut Context,
    graph: &mut Graph,
    cur: TensorId,
    exp_probs_b: Option<TensorId>,
    up_exps: TensorId,
    down_exps: TensorId,
    n_expert: i64,
    n_expert_used: i64,
    norm_w: bool,
    w_scale: f32,
    probs_in: TensorId,
) -> TensorId {
    let n_embd = ctx.ne(cur)[0];
    let n_tokens = ctx.ne(cur)[1];

    // probs_in == the caller's router_logits (llama-graph.cpp:2019-2021);
    // gate_inp_b is NULL for nemotron-h
    let logits = probs_in;
    // LLAMA_EXPERT_GATING_FUNC_TYPE_SIGMOID (nemotron-h.cpp:312)
    let probs = ctx.sigmoid(logits); // [n_expert, n_tokens]

    // selection bias — steers the top-k only (llama-graph.cpp:2063-2067)
    let selection_probs = match exp_probs_b {
        Some(b) => ctx.add(probs, b),
        None => probs,
    };
    let selected = ctx.argsort_top_k(selection_probs, n_expert_used as i32);

    let probs3 = ctx.reshape_3d(probs, 1, n_expert, n_tokens);
    let mut weights = ctx.get_rows(probs3, selected); // [1, k, n_tokens]

    if norm_w {
        let w2 = ctx.reshape_2d(weights, n_expert_used, n_tokens);
        let sum = ctx.sum_rows(w2); // [1, n_tokens]
        let sum = ctx.clamp(sum, 6.103515625e-5, f32::INFINITY);
        let w2 = ctx.div(w2, sum);
        weights = ctx.reshape_3d(w2, 1, n_expert_used, n_tokens);
    }
    if w_scale != 0.0 && w_scale != 1.0 {
        weights = ctx.scale(weights, w_scale);
    }
    graph.build_forward(ctx, weights);

    let cur3 = ctx.reshape_3d(cur, n_embd, 1, n_tokens);
    // up experts, no gate (llama-graph.cpp:2125-2149's gate_exps == NULL arm)
    let up = crate::adapter::lora_mm_id(ctx, up_exps, cur3, selected);
    // LLM_FFN_RELU_SQR without a gate (llama-graph.cpp:2273-2278): relu² of up
    let r = ctx.clamp(up, 0.0, f32::INFINITY);
    let act = ctx.mul(r, r);
    let mut experts = crate::adapter::lora_mm_id(ctx, down_exps, act, selected);
    experts = ctx.mul(experts, weights);
    graph.build_forward(ctx, experts);

    // aggregate the k expert views (llama-graph.cpp:2329-2358)
    let nb1 = ctx.nb(experts)[1] as usize;
    let nb2 = ctx.nb(experts)[2] as usize;
    let mut moe_out = ctx.view_2d(experts, n_embd, n_tokens, nb2, 0);
    graph.build_forward(ctx, moe_out);
    for i in 1..n_expert_used as usize {
        let vi = ctx.view_2d(experts, n_embd, n_tokens, nb2, i * nb1);
        graph.build_forward(ctx, vi);
        moe_out = ctx.add(moe_out, vi);
        graph.build_forward(ctx, moe_out);
    }
    if n_expert_used == 1 {
        moe_out = ctx.cont(moe_out);
    }
    moe_out
}

// ======================================================================
// arch batch 6 (2026-09-24): the DeepSeek MLA family — deepseek2
// (+deepseek2-ocr via the same graph) and the non-MLA v2 base deepseek.
//
// deepseek32 / deepseek4 (the DSA lightning-indexer and dsv4 compressed-kv_b
// sparse variants) are NOT in this section — they need the
// llama_kv_cache_dsa / llama_kv_cache_dsv4 memory kinds.
// ======================================================================

/// Shared per-layer weights of deepseek2 (deepseek2.cpp:98-158) and
/// deepseek2-ocr (deepseek2ocr.cpp:40-73). `wq_b`/`wk_b`/`wv_b` carry the
/// deepseek meanings ATTN_Q_B / ATTN_K_B / ATTN_V_B (NOT qkv biases).
pub struct Deepseek2LayerWeights {
    pub attn_norm: TensorId,
    /// lite variants only (q_lora_rank == 0, deepseek2.cpp:109)
    pub wq: Option<TensorId>,
    /// deepseek2ocr's fused/separate MHA projections (deepseek2ocr.cpp:43)
    pub wqkv: Option<TensorId>,
    pub wqkv_b: Option<TensorId>,
    pub wk: Option<TensorId>,
    pub wv: Option<TensorId>,
    pub wq_a: Option<TensorId>,
    pub attn_q_a_norm: Option<TensorId>,
    pub wq_b: Option<TensorId>,
    /// None for the OCR layers (deepseek2ocr.cpp creates none)
    pub wkv_a_mqa: Option<TensorId>,
    pub attn_kv_a_norm: Option<TensorId>,
    /// deepseek32's DSA lightning-indexer tensors (deepseek32.cpp:109-114)
    pub indexer_k_norm: Option<TensorId>,
    pub indexer_k_norm_b: Option<TensorId>,
    pub indexer_proj: Option<TensorId>,
    pub indexer_attn_k: Option<TensorId>,
    pub indexer_attn_q_b: Option<TensorId>,
    /// {n_embd_head_qk_nope, kv_lora_rank, n_head} — MLA only
    pub wk_b: Option<TensorId>,
    /// {kv_lora_rank, n_embd_head_v_mla, n_head} — MLA only (the `v_mla`
    /// decompression weight of build_attn_mha, llama-graph.cpp:2652/2719)
    pub wv_b: Option<TensorId>,
    /// legacy unsplit {kv_lora_rank, n_head*(qk_nope + v_mla)} — non-MLA only
    pub wkv_b: Option<TensorId>,
    pub wo: TensorId,
    pub ffn_norm: TensorId,
    pub ffn_gate: Option<TensorId>,
    pub ffn_down: Option<TensorId>,
    pub ffn_up: Option<TensorId>,
    pub ffn_gate_inp: Option<TensorId>,
    pub ffn_exp_probs_b: Option<TensorId>,
    pub ffn_gate_up_exps: Option<TensorId>,
    pub ffn_gate_exps: Option<TensorId>,
    pub ffn_up_exps: Option<TensorId>,
    pub ffn_down_exps: Option<TensorId>,
    pub ffn_gate_shexp: Option<TensorId>,
    pub ffn_down_shexp: Option<TensorId>,
    pub ffn_up_shexp: Option<TensorId>,
}

pub struct Deepseek2ModelWeights {
    pub tok_embd: TensorId,
    pub output_norm: TensorId,
    /// tied to tok_embd when the file has no output.weight (deepseek2.cpp:89-92)
    pub output: TensorId,
    pub layers: Vec<Deepseek2LayerWeights>,
}

/// Hyperparameters of the deepseek2 graph beyond [`AttnParams`].
///
/// `attn`'s cache geometry for the MLA path (deepseek2.cpp:589 "MLA with the
/// absorption optimization converts into MQA"): `n_embd_head_k` =
/// hparams.n_embd_head_k() = the GGUF `attention.key_length` (= kv_lora_rank
/// + qk_rope_head_dim), `n_head_kv` = 1. The K cache therefore stores the
/// *compressed* concat(kv_cmpr, k_pe) rows and no V tensor is ever read (the
/// C allocates none, llama-kv-cache.cpp:231 `has_v = !is_mla`).
#[derive(Clone, Copy)]
pub struct Deepseek2Params {
    pub attn: AttnParams,
    pub n_embd: i64,
    /// hparams.n_embd_head_k_mla() (deepseek2.cpp:425 — 192 for V2/V3)
    pub n_embd_head_k_mla: i64,
    /// hparams.n_embd_head_v_mla() (deepseek2.cpp:426 — 128 for V2/V3)
    pub n_embd_head_v_mla: i64,
    /// hparams.n_lora_kv (kv_lora_rank)
    pub kv_lora_rank: i64,
    /// hparams.rope_yarn_log_mul — the mscale term of the pre-scaled kq_scale
    pub rope_yarn_log_mul: f32,
    /// hparams.f_attn_temp_scale — must be 0 (build_inp_attn_scale not ported)
    pub f_attn_temp_scale: f32,
    /// hparams.n_layer_dense_lead — first-k-dense layers (deepseek2.cpp:646)
    pub n_layer_dense_lead: u32,
    pub n_expert: i64,
    pub n_expert_used: i64,
    pub expert_weights_norm: bool,
    pub expert_weights_scale: f32,
    /// llama_expert_gating_func_type as raw value (hparams.expert_gating_func)
    pub expert_gating_func: i32,
    /// deepseek2.cpp:420 — model.arch == LLM_ARCH_DEEPSEEK2OCR branch
    pub is_ocr: bool,
}

/// `build_attn(llm_graph_input_attn_k*, ..., v_mla)` + `build_attn_mha` with
/// the v_mla decompression — the attention core of MLA
/// (llama-graph.cpp:2955-3011 + :2602-2738).
///
/// The K-only cache of `llm_graph_input_attn_k` (llama-graph.cpp:2926-2945):
/// one `cpy_k` set_rows write of the *compressed* rows (no V write at all),
/// `k = mctx->get_k(...)` and `v = view_4d(k, v_cur->ne[0], k->ne[1..3],
/// k->nb[1..3], 0)` — the V read is the first `kv_lora_rank` columns of the
/// K cache (llama-graph.cpp:2988). `v_mla` (wv_b) then "decompresses" the MQA
/// output back to MHA (:2719-2721 non-FA / :2652-2667 FA).
#[allow(clippy::too_many_arguments)]
fn attn_k_cached_mla(
    ctx: &mut Context,
    graph: &mut Graph,
    kv: &KvCache,
    il: usize,
    p: &AttnParams,
    inp: &DecodeInputs,
    n_kv: u32,
    // Qcur [kv_lora_rank + qk_rope, n_head, T] — concat(q_nope_absorbed, q_pe)
    q: TensorId,
    // Kcur [kv_lora_rank + qk_rope, 1, T] — concat(kv_cmpr, k_pe)
    k: TensorId,
    // Vcur [kv_lora_rank, 1, T] — the reshaped kv_cmpr (v_cur->ne[0] source)
    v_cur: TensorId,
    kq_scale: f32,
    // layer.wv_b {kv_lora_rank, n_embd_head_v_mla, n_head}
    v_mla: TensorId,
    // build_attn's wo — None when the caller projects itself after extra
    // gating (bailingmoe3 / kimi pass nullptr, bailingmoe3.cpp:343-350)
    wo: Option<TensorId>,
    // deepseek32's DSA top-k indices (llama-graph.cpp:3024) — Some() composes
    // the top-k KQ mask of build_attn(llm_graph_input_attn_k_dsa*) :3045-3069
    // before the attention; None is the plain deepseek2 path
    top_k: Option<TensorId>,
) -> TensorId {
    let t = ctx.ne(q)[2];

    // store to KV cache — cpy_k (llama-kv-cache.cpp:1318-1346, dims 0/1
    // merged) then build_attn's ggml_build_forward_expand (llama-graph.cpp:2981)
    let nb2 = ctx.nb(k)[2] as usize;
    let k_rows = ctx.view_2d(k, p.n_embd_head_k * p.n_head_kv, t, nb2, 0);
    let k_dst = ctx.set_rows(kv.layers[il].k, k_rows, inp.row_idx);
    graph.build_forward(ctx, k_dst);

    // k = get_k [head_dim, 1, n_kv, 1]; v = view of k (llama-graph.cpp:2986-2988)
    let k_view = kv.get_k(ctx, il, p.n_embd_head_k, p.n_head_kv, n_kv);
    let v_ne0 = ctx.ne(v_cur)[0];
    let (kne, knb) = (*ctx.ne(k_view), *ctx.nb(k_view));
    let v_view = ctx.view_4d(
        k_view,
        v_ne0,
        kne[1],
        kne[2],
        kne[3],
        knb[1] as usize,
        knb[2] as usize,
        knb[3] as usize,
        0,
    );

    // the DSA top-k mask composition (llama-graph.cpp:3045-3069): start from
    // -INFINITY, unmask (write 0.0 at) the top-k rows, add the causal mask
    let kq_mask = match top_k {
        None => inp.kq_mask,
        Some(top_k) => {
            // ggml_fill(kq_mask, -INFINITY) (:3046) — a dup of the input mask
            let all = ctx.fill(inp.kq_mask, f32::NEG_INFINITY);
            // reshape [n_kv, T, 1, 1] -> [1, n_kv, T, 1] (:3050, n_stream 1)
            let mne = *ctx.ne(all);
            let mnb = *ctx.nb(all);
            let all = ctx.view_4d(
                all,
                1,
                mne[0],
                mne[1],
                mne[3],
                mnb[0] as usize,
                mnb[1] as usize,
                mnb[2] as usize,
                0,
            );
            // top_k [n_top_k, T] -> [n_top_k, T, 1, 1] (:3053)
            let tne = *ctx.ne(top_k);
            let tnb = *ctx.nb(top_k);
            let top_k_3d = ctx.view_4d(
                top_k,
                tne[0],
                tne[1],
                tne[3],
                1,
                tnb[1] as usize,
                tnb[2] as usize,
                (tne[3] * tnb[3] as i64) as usize,
                0,
            );
            // zero-filled rows [1, n_top_k, T, 1] (:3057-3058)
            let zeros = ctx.new_tensor_4d(ggml::types::GgmlType::F32, 1, tne[0], tne[1], tne[3]);
            let zeros = ctx.fill(zeros, 0.0);
            // unmask the top-k rows (:3062)
            let mut m = ctx.set_rows(all, zeros, top_k_3d);
            // back to [n_kv, T, 1, 1] (:3066)
            let mne = *ctx.ne(m);
            let mnb = *ctx.nb(m);
            m = ctx.view_4d(
                m,
                mne[1],
                mne[2],
                1,
                mne[3],
                mnb[2] as usize,
                mnb[3] as usize,
                mnb[3] as usize,
                0,
            );
            // combine with the original causal mask (:3069)
            ctx.add(m, inp.kq_mask)
        }
    };

    if p.use_flash_attn {
        // FA branch (llama-graph.cpp:2626-2669). q stays F32, k/v are the F16
        // cache views (C's F32→F16 casts are no-ops on the cache type).
        let q_fa = ctx.permute(q, 0, 2, 1, 3); // [DK, T, H]
        let k_fa = ctx.permute(k_view, 0, 2, 1, 3);
        let v_fa = ctx.permute(v_view, 0, 2, 1, 3);
        let mut cur = ctx.flash_attn_ext(q_fa, k_fa, v_fa, Some(kq_mask), kq_scale, 0.0, 0.0);
        // v_mla as matrix-matrix mul with n_tokens in dim 1 (llama-graph.cpp:2659-2666,
        // the #else branch): permute → mul_mat(wv_b) → permute → cont
        cur = ctx.permute(cur, 0, 2, 1, 3);
        cur = ctx.mul_mat(v_mla, cur);
        cur = ctx.permute(cur, 0, 2, 1, 3);
        cur = ctx.cont(cur);
        let ne = *ctx.ne(cur);
        let cur = ctx.reshape_2d(cur, ne[0] * ne[1], ne[2] * ne[3]);
        // wo projection (llama-graph.cpp:3002 — deepseek2 is not GLM4/JAIS2)
        return match wo {
            Some(w) => crate::adapter::lora_mm(ctx, w, cur),
            None => cur,
        };
    }

    // non-FA (llama-graph.cpp:2670-2727) — same shape flow as attn_kv_cached
    // plus the v_mla decompression between kqv and the permute back
    let q = ctx.permute(q, 0, 2, 1, 3);
    let k_view = ctx.permute(k_view, 0, 2, 1, 3);
    let kq = ctx.mul_mat(k_view, q);
    let kq = ctx.soft_max_ext(kq, Some(kq_mask), kq_scale, 0.0);

    let v_view = ctx.permute(v_view, 0, 2, 1, 3);
    let v_t = ctx.transpose(v_view);
    let v_c = ctx.cont(v_t);
    let kqv = ctx.mul_mat(v_c, kq); // [kv_lora_rank, T, H]

    // "decompress" from MQA back to MHA (llama-graph.cpp:2718-2722)
    let kqv = ctx.mul_mat(v_mla, kqv); // [n_embd_head_v_mla, T, H]
    let kqv = ctx.permute(kqv, 0, 2, 1, 3);
    // ggml_cont_2d over the tensor's own ne (:2727)
    let ne = *ctx.ne(kqv);
    let kqv = ctx.cont_2d(kqv, ne[0] * ne[1], ne[2] * ne[3]);
    match wo {
        Some(w) => crate::adapter::lora_mm(ctx, w, kqv),
        None => kqv,
    }
}

/// build_qkv with reshape=true (llama-graph.cpp:1619-1757) — the fused-wqkv
/// view_3d split or the separate wq/wk/wv path, for deepseek / deepseek2-ocr.
#[allow(clippy::too_many_arguments)]
fn build_qkv_deepseek(
    ctx: &mut Context,
    cur: TensorId,
    wqkv: Option<TensorId>,
    wqkv_b: Option<TensorId>,
    wq: Option<TensorId>,
    wk: Option<TensorId>,
    wv: Option<TensorId>,
    n_embd_head: i64,
    n_head: i64,
    n_head_kv: i64,
) -> (TensorId, TensorId, TensorId) {
    let t = ctx.ne(cur)[1];
    let n_embd_q = n_embd_head * n_head;
    let n_embd_k = n_embd_head * n_head_kv;
    if let Some(wqkv) = wqkv {
        // fused QKV path (llama-graph.cpp:1639-1677)
        let mut qkv = crate::adapter::lora_mm(ctx, wqkv, cur);
        if let Some(b) = wqkv_b {
            qkv = ctx.add(qkv, b);
        }
        let kv_ty = ctx.ty(qkv);
        let rs = |n: i64| kv_ty.row_size(n as usize);
        let nb1 = ctx.nb(qkv)[1] as usize;
        let q = ctx.view_3d(qkv, n_embd_head, n_head, t, rs(n_embd_head), nb1, 0);
        let k = ctx.view_3d(
            qkv,
            n_embd_head,
            n_head_kv,
            t,
            rs(n_embd_head),
            nb1,
            rs(n_embd_q),
        );
        let v = ctx.view_3d(
            qkv,
            n_embd_head,
            n_head_kv,
            t,
            rs(n_embd_head),
            nb1,
            rs(n_embd_q + n_embd_k),
        );
        (q, k, v)
    } else {
        // separate Q/K/V path (llama-graph.cpp:1678-1741); no clamp
        // (f_clamp_kqv == 0), biases none for the deepseek files
        let q = crate::adapter::lora_mm(ctx, wq.expect("wq"), cur);
        let k = crate::adapter::lora_mm(ctx, wk.expect("wk"), cur);
        let v = crate::adapter::lora_mm(ctx, wv.expect("wv"), cur);
        (
            ctx.reshape_3d(q, n_embd_head, n_head, t),
            ctx.reshape_3d(k, n_embd_head, n_head_kv, t),
            ctx.reshape_3d(v, n_embd_head, n_head_kv, t),
        )
    }
}

/// build_moe_ffn for deepseek2 (llama-graph.cpp:1993-2368) — the split
/// gate/up case delegates to the shared `build_moe_ffn_silu`; the fused
/// `ffn_gate_up_exps` variant (llama-model.cpp:3253-3268 loader side,
/// llama-graph.cpp:2168-2186 graph side) is inlined here: one mul_mat_id,
/// then the gate/up halves as views of it.
#[allow(clippy::too_many_arguments)]
fn build_moe_ffn_deepseek2(
    ctx: &mut Context,
    graph: &mut Graph,
    cur: TensorId,
    lw: &Deepseek2LayerWeights,
    p: &Deepseek2Params,
) -> TensorId {
    if lw.ffn_gate_up_exps.is_some() {
        let n_embd = ctx.ne(cur)[0];
        let n_tokens = ctx.ne(cur)[1];
        let n_expert = p.n_expert;
        let n_expert_used = p.n_expert_used;

        // routing (llama-graph.cpp:2021-2163) — same ops as
        // build_moe_ffn_silu, spelled out here because the expert branch
        // below differs
        let logits = crate::adapter::lora_mm(ctx, lw.ffn_gate_inp.expect("ffn_gate_inp"), cur);
        let probs = match p.expert_gating_func {
            EXPERT_GATING_SOFTMAX => ctx.soft_max(logits),
            EXPERT_GATING_SIGMOID => ctx.sigmoid(logits),
            EXPERT_GATING_SOFTMAX_WEIGHT => logits,
            other => unimplemented!("build_moe_ffn: gating op {other}"),
        };
        // e-score bias steers only the top-k (llama-graph.cpp:2062-2067)
        let selection_probs = match lw.ffn_exp_probs_b {
            Some(b) => ctx.add(probs, b),
            None => probs,
        };
        let selected = ctx.argsort_top_k(selection_probs, n_expert_used as i32);
        let probs3 = ctx.reshape_3d(probs, 1, n_expert, n_tokens);
        let mut weights = ctx.get_rows(probs3, selected);
        if p.expert_gating_func == EXPERT_GATING_SOFTMAX_WEIGHT {
            let w2 = ctx.reshape_2d(weights, n_expert_used, n_tokens);
            let w2 = ctx.soft_max(w2);
            weights = ctx.reshape_3d(w2, 1, n_expert_used, n_tokens);
        }
        if p.expert_weights_norm {
            let w2 = ctx.reshape_2d(weights, n_expert_used, n_tokens);
            let sum = ctx.sum_rows(w2);
            let sum = ctx.clamp(sum, 6.103515625e-5, f32::INFINITY);
            let w2 = ctx.div(w2, sum);
            weights = ctx.reshape_3d(w2, 1, n_expert_used, n_tokens);
        }
        if p.expert_weights_scale != 0.0 && p.expert_weights_scale != 1.0 {
            weights = ctx.scale(weights, p.expert_weights_scale);
        }
        graph.build_forward(ctx, weights);

        // merged gate_up path (llama-graph.cpp:2168-2186): one mul_mat_id,
        // then split into gate and up views + swiglu_split (:2255-2259)
        let cur3 = ctx.reshape_3d(cur, n_embd, 1, n_tokens);
        let gate_up = crate::adapter::lora_mm_id(
            ctx,
            lw.ffn_gate_up_exps.expect("ffn_gate_up_exps"),
            cur3,
            selected,
        ); // [2*n_ff, k, n_tokens]
        let nb = *ctx.nb(gate_up);
        let n_ff = ctx.ne(gate_up)[0] / 2;
        let g = ctx.view_3d(
            gate_up,
            n_ff,
            n_expert_used,
            n_tokens,
            nb[1] as usize,
            nb[2] as usize,
            0,
        );
        let u = ctx.view_3d(
            gate_up,
            n_ff,
            n_expert_used,
            n_tokens,
            nb[1] as usize,
            nb[2] as usize,
            (n_ff * nb[0] as i64) as usize,
        );
        let act = ctx.swiglu_split(g, u);
        let mut experts = crate::adapter::lora_mm_id(
            ctx,
            lw.ffn_down_exps.expect("ffn_down_exps"),
            act,
            selected,
        );
        experts = ctx.mul(experts, weights);
        graph.build_forward(ctx, experts);

        // aggregate the k expert views (llama-graph.cpp:2329-2358)
        let nb1 = ctx.nb(experts)[1] as usize;
        let nb2 = ctx.nb(experts)[2] as usize;
        let mut moe_out = ctx.view_2d(experts, n_embd, n_tokens, nb2, 0);
        graph.build_forward(ctx, moe_out);
        for i in 1..n_expert_used as usize {
            let vi = ctx.view_2d(experts, n_embd, n_tokens, nb2, i * nb1);
            graph.build_forward(ctx, vi);
            moe_out = ctx.add(moe_out, vi);
            graph.build_forward(ctx, moe_out);
        }
        if n_expert_used == 1 {
            moe_out = ctx.cont(moe_out);
        }
        moe_out
    } else {
        build_moe_ffn_silu(
            ctx,
            graph,
            cur,
            lw.ffn_gate_inp.expect("ffn_gate_inp"),
            None,
            lw.ffn_up_exps.expect("ffn_up_exps"),
            None,
            lw.ffn_gate_exps,
            None,
            lw.ffn_down_exps.expect("ffn_down_exps"),
            None,
            lw.ffn_exp_probs_b,
            p.n_expert,
            p.n_expert_used,
            p.expert_weights_norm,
            p.expert_weights_scale,
            p.expert_gating_func,
        )
    }
}

/// verify against src/models/deepseek2.cpp:417-713 llama_model_deepseek2::graph::graph —
/// the classic MLA graph (also deepseek2-ocr through `is_ocr`, which shares
/// this graph class, models.h:1335).
///
/// Which attention path a file takes (exactly the C branches):
///   * `is_ocr` (deepseek2.cpp:473-494): plain MHA + NEOX rope at a hard-coded
///     freq_base 10000 — deepseek2-ocr files only;
///   * MLA (deepseek2.cpp:540-592): `hparams.is_mla()` — the absorbed MQA form
///     with the compressed K cache and the wv_b decompression (the DEFAULT for
///     every current deepseek2 GGUF — the converter writes
///     attention.key_length_mla, conversion/deepseek.py:350-353);
///   * non-MLA (deepseek2.cpp:593-634): legacy unsplit wkv_b files — the
///     decompressed MHA form (rope on q's trailing segment via
///     ggml_rope_set_offset, deepseek2.cpp:617).
/// `is_lite` is per-layer (`layer.wq` present, deepseek2.cpp:498) — the q_lora
/// projection chain is skipped and wq projects straight to the MLA head dim.
///
/// Not ported (same treatment as the other arch builders): `inp_out_ids` row
/// pruning (:636-639 — identical values), `build_inp_attn_scale` (:452-455 /
/// :583-587 — mistral-large's f_attn_temp_scale, asserted 0), `build_cvec`
/// (:686) and the MTP graph class (deepseek2.cpp:170-415, speculative path).
#[allow(clippy::too_many_arguments)]
pub fn build_deepseek2_forward(
    ctx: &mut Context,
    w: &Deepseek2ModelWeights,
    p: &Deepseek2Params,
    kv: &KvCache,
    inp: &DecodeInputs,
    _sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let ap = &p.attn;

    // deepseek2.cpp:422-431
    let n_embd_head_k = p.n_embd_head_k_mla;
    let n_embd_head_v = p.n_embd_head_v_mla;
    let n_embd_head_qk_rope = ap.n_rot;
    let n_embd_head_qk_nope = n_embd_head_k - n_embd_head_qk_rope;
    let kv_lora_rank = p.kv_lora_rank;

    // We have to pre-scale kq_scale and attn_factor to make the YaRN RoPE work
    // correctly (deepseek2.cpp:433-443, [TAG_DEEPSEEK2_YARN_LOG_MUL_FIX] —
    // rope_yarn_log_mul was already divided by 0.1 at load, meta.rs)
    assert!(ap.ext_factor >= 0.0);
    let attn_factor_org = ap.attn_factor * (1.0 + 0.1 * (1.0f32 / ap.freq_scale).ln());
    let mscale =
        attn_factor_org * (1.0 + 0.1 * p.rope_yarn_log_mul * (1.0f32 / ap.freq_scale).ln());
    let kq_scale = 1.0 * mscale * mscale / (n_embd_head_k as f32).sqrt();

    // (optional) temperature tuning - used by mistral-large
    // (deepseek2.cpp:451-455): build_inp_attn_scale is not ported — the
    // driver must reject such files (no local deepseek2-family file uses it)
    assert!(
        p.f_attn_temp_scale == 0.0,
        "deepseek2: attention temperature scaling (mistral-large) not ported"
    );

    let mut graph = Graph::new(1024);

    // {n_embd, n_tokens} — build_inp_embd with the lora delta
    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_sa = inp_l;

        // norm (deepseek2.cpp:469)
        let mut cur = build_norm_rms(ctx, inp_l, lw.attn_norm, ap.norm_eps);

        // self_attention
        if p.is_ocr {
            // deepseek2.cpp:473-494
            let n_embed_head = p.n_embd / ap.n_head;
            let ocr_rope_type = 2; // GGML_ROPE_TYPE_NEOX
            assert!(
                n_embed_head == n_embd_head_k && n_embed_head == n_embd_head_v,
                "deepseek2-ocr: n_embd/n_head must equal key/value lengths"
            );

            let (qcur, kcur, vcur) = build_qkv_deepseek(
                ctx,
                cur,
                lw.wqkv,
                lw.wqkv_b,
                lw.wq,
                lw.wk,
                lw.wv,
                n_embed_head,
                ap.n_head,
                ap.n_head,
            );
            // freq_base must be the default (deepseek2.cpp:484) — rope then
            // runs with hard-coded 10000/1/0/1/0/0 (:485-486)
            assert!((ap.freq_base - 10000.0).abs() < 1e-4);
            let qcur = ctx.rope_ext(
                qcur,
                inp.pos,
                None,
                n_embed_head as i32,
                ocr_rope_type,
                0,
                10000.0,
                1.0,
                0.0,
                1.0,
                0.0,
                0.0,
            );
            let kcur = ctx.rope_ext(
                kcur,
                inp.pos,
                None,
                n_embed_head as i32,
                ocr_rope_type,
                0,
                10000.0,
                1.0,
                0.0,
                1.0,
                0.0,
                0.0,
            );

            cur = attn_kv_cached(
                ctx,
                &mut graph,
                kv,
                il,
                ap,
                inp,
                n_kv,
                qcur,
                kcur,
                vcur,
                kq_scale,
                0.0,
                None,
                None,
                Some(lw.wo),
                None,
            );
        } else {
            // deepseek2.cpp:496-634
            let n_head = ap.n_head;

            // is_lite is per-layer: layer.wq present (deepseek2.cpp:498)
            let mut q = if let Some(wq) = lw.wq {
                ctx.mul_mat(wq, cur)
            } else {
                let qa = ctx.mul_mat(lw.wq_a.expect("wq_a"), cur);
                let qa = build_norm_rms(
                    ctx,
                    qa,
                    lw.attn_q_a_norm.expect("attn_q_a_norm"),
                    ap.norm_eps,
                );
                ctx.mul_mat(lw.wq_b.expect("wq_b"), qa)
            };
            // {n_embd_head_k_mla, n_head, n_tokens} (deepseek2.cpp:514)
            q = ctx.reshape_3d(q, n_embd_head_k, n_head, t);

            let kv_cmpr_pe = ctx.mul_mat(lw.wkv_a_mqa.expect("wkv_a_mqa"), cur);

            // split into {kv_lora_rank, n_tokens} (deepseek2.cpp:521-523)
            let kv_cmpr = {
                let rs = ctx
                    .ty(kv_cmpr_pe)
                    .row_size((kv_lora_rank + n_embd_head_qk_rope) as usize);
                ctx.view_2d(kv_cmpr_pe, kv_lora_rank, t, rs, 0)
            };

            // and {n_embd_head_qk_rope, 1, n_tokens} (deepseek2.cpp:527-530)
            let k_pe = {
                let rs = ctx
                    .ty(kv_cmpr_pe)
                    .row_size((kv_lora_rank + n_embd_head_qk_rope) as usize);
                ctx.view_3d(
                    kv_cmpr_pe,
                    n_embd_head_qk_rope,
                    1,
                    t,
                    rs,
                    rs,
                    ctx.ty(kv_cmpr_pe).row_size(kv_lora_rank as usize),
                )
            };
            let k_pe = ctx.rope_ext(
                k_pe,
                inp.pos,
                None,
                ap.n_rot as i32,
                ap.rope_mode,
                ap.n_ctx_orig,
                ap.freq_base,
                ap.freq_scale,
                ap.ext_factor,
                ap.attn_factor,
                ap.beta_fast,
                ap.beta_slow,
            );

            let kv_cmpr = build_norm_rms(
                ctx,
                kv_cmpr,
                lw.attn_kv_a_norm.expect("attn_kv_a_norm"),
                ap.norm_eps,
            );

            if lw.wk_b.is_some() {
                // MLA — absorbed MQA (deepseek2.cpp:540-592)
                // split into {n_embd_head_qk_nope, n_head, n_tokens} (:542-543)
                let (qnb1, qnb2) = (ctx.nb(q)[1] as usize, ctx.nb(q)[2] as usize);
                let q_nope = ctx.view_3d(q, n_embd_head_qk_nope, n_head, t, qnb1, qnb2, 0);
                // and {n_embd_head_qk_rope, n_head, n_tokens} (:547-548)
                let q_pe = ctx.view_3d(
                    q,
                    n_embd_head_qk_rope,
                    n_head,
                    t,
                    qnb1,
                    qnb2,
                    ctx.ty(q).row_size(n_embd_head_qk_nope as usize),
                );
                let q_pe = ctx.rope_ext(
                    q_pe,
                    inp.pos,
                    None,
                    ap.n_rot as i32,
                    ap.rope_mode,
                    ap.n_ctx_orig,
                    ap.freq_base,
                    ap.freq_scale,
                    ap.ext_factor,
                    ap.attn_factor,
                    ap.beta_fast,
                    ap.beta_slow,
                );

                // {n_embd_head_qk_nope, n_tokens, n_head} (:556)
                let q_nope = ctx.permute(q_nope, 0, 2, 1, 3);
                // wk_b {nope, kv_lora_rank, n_head} x {nope, T, n_head} (:560)
                let q_nope_absorbed = ctx.mul_mat(lw.wk_b.expect("wk_b"), q_nope);
                // {kv_lora_rank, n_head, n_tokens} (:564)
                let q_nope_absorbed = ctx.permute(q_nope_absorbed, 0, 2, 1, 3);

                // {qk_rope + kv_lora_rank, n_head, n_tokens}; note: rope must
                // go first for in-place context shifting in build_rope_shift
                // (:569)
                let qcur = ctx.concat(q_nope_absorbed, q_pe, 0);

                let kv_cmpr3 = ctx.reshape_3d(kv_cmpr, kv_lora_rank, 1, t);
                // {qk_rope + kv_lora_rank, 1, n_tokens} (:576)
                let kcur = ctx.concat(kv_cmpr3, k_pe, 0);

                // note: MLA with the absorption optimization converts into MQA
                // (ie: GQA with 1 group) (:589-592)
                cur = attn_k_cached_mla(
                    ctx,
                    &mut graph,
                    kv,
                    il,
                    ap,
                    inp,
                    n_kv,
                    qcur,
                    kcur,
                    kv_cmpr3,
                    kq_scale,
                    lw.wv_b.expect("wv_b"),
                    Some(lw.wo),
                    None,
                );
            } else {
                // legacy non-MLA — decompressed MHA (deepseek2.cpp:593-634)
                let kvb = ctx.mul_mat(lw.wkv_b.expect("wkv_b"), kv_cmpr);
                let kv_ty = ctx.ty(kvb);
                let rs_kv = |n: i64| kv_ty.row_size(n as usize);
                // {n_embd_head_qk_nope, n_head, n_tokens} (:598-601)
                let k_nope = ctx.view_3d(
                    kvb,
                    n_embd_head_qk_nope,
                    n_head,
                    t,
                    rs_kv(n_embd_head_qk_nope + n_embd_head_v),
                    rs_kv(n_embd_head_qk_nope + n_embd_head_v) * n_head as usize,
                    0,
                );
                // and {n_embd_head_v, n_head, n_tokens} (:605-608)
                let vcur = ctx.view_3d(
                    kvb,
                    n_embd_head_v,
                    n_head,
                    t,
                    rs_kv(n_embd_head_qk_nope + n_embd_head_v),
                    rs_kv(n_embd_head_qk_nope + n_embd_head_v) * n_head as usize,
                    rs_kv(n_embd_head_qk_nope),
                );
                let vcur = ctx.cont(vcur);

                // RoPE is applied to the trailing dims only (:615-617)
                let qcur = ctx.rope_ext(
                    q,
                    inp.pos,
                    None,
                    ap.n_rot as i32,
                    ap.rope_mode,
                    ap.n_ctx_orig,
                    ap.freq_base,
                    ap.freq_scale,
                    ap.ext_factor,
                    ap.attn_factor,
                    ap.beta_fast,
                    ap.beta_slow,
                );
                let qcur = ctx.rope_set_offset(qcur, n_embd_head_qk_nope as i32);

                // Kcur = concat(k_nope, repeat_4d(k_pe, ...)) (:620-621)
                let k_pe_rep = ctx.repeat_4d(k_pe, n_embd_head_qk_rope, n_head, t, 1);
                let kcur = ctx.concat(k_nope, k_pe_rep, 0);

                // note: MLA without the absorption optimization converts into
                // MHA (ie: GQA with full n_head groups) (:630-633)
                cur = attn_kv_cached(
                    ctx,
                    &mut graph,
                    kv,
                    il,
                    ap,
                    inp,
                    n_kv,
                    qcur,
                    kcur,
                    vcur,
                    kq_scale,
                    0.0,
                    None,
                    None,
                    Some(lw.wo),
                    None,
                );
            }
        }

        // residual + ffn_norm (deepseek2.cpp:640-644; the il == n_layer-1
        // get_rows pruning of :636-639 is skipped — identical values)
        let ffn_inp = ctx.add(cur, inp_sa);
        let mut cur = build_norm_rms(ctx, ffn_inp, lw.ffn_norm, ap.norm_eps);

        if (il as u32) < p.n_layer_dense_lead {
            // first-k-dense layers (deepseek2.cpp:646-652)
            cur = build_ffn_silu_par(
                ctx,
                cur,
                lw.ffn_gate.expect("ffn_gate (dense-lead layer)"),
                None,
                lw.ffn_up.expect("ffn_up (dense-lead layer)"),
                None,
                lw.ffn_down.expect("ffn_down (dense-lead layer)"),
                None,
            );
        } else {
            // MoE branch (deepseek2.cpp:654-683)
            let moe_out = build_moe_ffn_deepseek2(ctx, &mut graph, cur, lw, p);
            // FFN shared expert (:671-681)
            let ffn_shexp = build_ffn_silu_par(
                ctx,
                cur,
                lw.ffn_gate_shexp.expect("ffn_gate_shexp"),
                None,
                lw.ffn_up_shexp.expect("ffn_up_shexp"),
                None,
                lw.ffn_down_shexp.expect("ffn_down_shexp"),
                None,
            );
            cur = ctx.add(moe_out, ffn_shexp);
        }
        // residual; build_cvec not ported (deepseek2.cpp:684-686)
        inp_l = ctx.add(cur, ffn_inp);
    }
    let cur = inp_l;

    let cur = build_norm_rms(ctx, cur, w.output_norm, ap.norm_eps);
    // res->t_h_nextn / t_embd (deepseek2.cpp:696-704) — the unmasked-nextn
    // get_rows of :699-701 belongs to the MTP context, not reached here
    // lm_head (:707 — plain mul_mat, not build_lora_mm)
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let logits = ctx.mul_mat(w.output, cur);

    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

/// verify against src/models/deepseek.cpp:74-194 llama_model_deepseek::graph::graph —
/// the non-MLA v2 base: plain MHA attention (build_qkv + NORM rope) with the
/// dense-lead/shared-expert MoE body. `kq_scale` falls back to
/// 1/sqrt(n_embd_head) unless hparams.f_attention_scale is set (deepseek.cpp:91).
pub struct DeepseekParams {
    pub attn: AttnParams,
    /// hparams.f_attention_scale (deepseek.cpp:92) — 0.0 → 1/sqrt(head_dim)
    pub f_attention_scale: f32,
    pub n_layer_dense_lead: u32,
    pub n_expert: i64,
    pub n_expert_used: i64,
    /// deepseek.cpp:152 — norm_w is false, gating is SOFTMAX, no e-score bias
    pub expert_weights_scale: f32,
}

pub struct DeepseekLayerWeights {
    pub attn_norm: TensorId,
    pub wqkv: Option<TensorId>,
    pub wqkv_b: Option<TensorId>,
    pub wq: Option<TensorId>,
    pub wk: Option<TensorId>,
    pub wv: Option<TensorId>,
    pub wo: TensorId,
    pub ffn_norm: TensorId,
    pub ffn_gate: Option<TensorId>,
    pub ffn_down: Option<TensorId>,
    pub ffn_up: Option<TensorId>,
    pub ffn_gate_inp: Option<TensorId>,
    pub ffn_gate_exps: Option<TensorId>,
    pub ffn_down_exps: Option<TensorId>,
    pub ffn_up_exps: Option<TensorId>,
    pub ffn_gate_shexp: Option<TensorId>,
    pub ffn_down_shexp: Option<TensorId>,
    pub ffn_up_shexp: Option<TensorId>,
}

pub struct DeepseekModelWeights {
    pub tok_embd: TensorId,
    pub output_norm: TensorId,
    pub output: TensorId,
    pub layers: Vec<DeepseekLayerWeights>,
}

#[allow(clippy::too_many_arguments)]
pub fn build_deepseek_forward(
    ctx: &mut Context,
    w: &DeepseekModelWeights,
    p: &DeepseekParams,
    kv: &KvCache,
    inp: &DecodeInputs,
    _sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let n_layer = w.layers.len();
    let ap = &p.attn;

    // deepseek.cpp:76-79
    let n_embd_head = ap.n_embd_head_v;
    assert_eq!(n_embd_head, ap.n_embd_head_k);
    assert_eq!(n_embd_head, ap.n_rot);

    let kq_scale = if p.f_attention_scale == 0.0 {
        1.0 / (n_embd_head as f32).sqrt()
    } else {
        p.f_attention_scale
    };

    let mut graph = Graph::new(1024);
    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_sa = inp_l;

        let mut cur = build_norm_rms(ctx, inp_l, lw.attn_norm, ap.norm_eps);

        // self-attention (deepseek.cpp:104-125) — rope factors absent
        let (qcur, kcur, vcur) = build_qkv_deepseek(
            ctx,
            cur,
            lw.wqkv,
            lw.wqkv_b,
            lw.wq,
            lw.wk,
            lw.wv,
            n_embd_head,
            ap.n_head,
            ap.n_head_kv,
        );
        let qcur = ctx.rope_ext(
            qcur,
            inp.pos,
            None,
            ap.n_rot as i32,
            ap.rope_mode,
            ap.n_ctx_orig,
            ap.freq_base,
            ap.freq_scale,
            ap.ext_factor,
            ap.attn_factor,
            ap.beta_fast,
            ap.beta_slow,
        );
        let kcur = ctx.rope_ext(
            kcur,
            inp.pos,
            None,
            ap.n_rot as i32,
            ap.rope_mode,
            ap.n_ctx_orig,
            ap.freq_base,
            ap.freq_scale,
            ap.ext_factor,
            ap.attn_factor,
            ap.beta_fast,
            ap.beta_slow,
        );

        cur = attn_kv_cached(
            ctx,
            &mut graph,
            kv,
            il,
            ap,
            inp,
            n_kv,
            qcur,
            kcur,
            vcur,
            kq_scale,
            0.0,
            None,
            None,
            Some(lw.wo),
            None,
        );

        let ffn_inp = ctx.add(cur, inp_sa);
        let mut cur = build_norm_rms(ctx, ffn_inp, lw.ffn_norm, ap.norm_eps);

        if (il as u32) < p.n_layer_dense_lead {
            cur = build_ffn_silu_par(
                ctx,
                cur,
                lw.ffn_gate.expect("ffn_gate (dense-lead layer)"),
                None,
                lw.ffn_up.expect("ffn_up (dense-lead layer)"),
                None,
                lw.ffn_down.expect("ffn_down (dense-lead layer)"),
                None,
            );
        } else {
            // MoE branch (deepseek.cpp:145-155) — norm_w false, SOFTMAX
            // gating, no exp_probs_b, w_scale = expert_weights_scale
            let moe_out = build_moe_ffn_silu(
                ctx,
                &mut graph,
                cur,
                lw.ffn_gate_inp.expect("ffn_gate_inp"),
                None,
                lw.ffn_up_exps.expect("ffn_up_exps"),
                None,
                lw.ffn_gate_exps,
                None,
                lw.ffn_down_exps.expect("ffn_down_exps"),
                None,
                None,
                p.n_expert,
                p.n_expert_used,
                false,
                p.expert_weights_scale,
                EXPERT_GATING_SOFTMAX,
            );
            // FFN shared expert (deepseek.cpp:158-169)
            let ffn_shexp = build_ffn_silu_par(
                ctx,
                cur,
                lw.ffn_gate_shexp.expect("ffn_gate_shexp"),
                None,
                lw.ffn_up_shexp.expect("ffn_up_shexp"),
                None,
                lw.ffn_down_shexp.expect("ffn_down_shexp"),
                None,
            );
            cur = ctx.add(moe_out, ffn_shexp);
        }
        inp_l = ctx.add(cur, ffn_inp);
    }
    let cur = inp_l;
    let cur = build_norm_rms(ctx, cur, w.output_norm, ap.norm_eps);
    // lm_head — build_lora_mm (deepseek.cpp:188)
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let logits = crate::adapter::lora_mm(ctx, w.output, cur);

    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

/// deepseek32 (DeepSeek V3.2, src/models/deepseek32.cpp:162-484) — the MLA
/// graph of deepseek2 plus the **DSA lightning indexer**: per layer an
/// indexer q/k pair (NEOX rope), the Hadamard rotation via the lid cache's
/// `k_rot` input, indexer weights (pre-scaled), the fused
/// `ggml_lightning_indexer` score, a top-k over it, and the top-k-composed
/// KQ mask of `build_attn(llm_graph_input_attn_k_dsa*)`
/// (llama-graph.cpp:3013-3087). The MoE body is deepseek2's.
#[derive(Clone, Copy)]
pub struct Deepseek32Params {
    /// the deepseek2 MLA parameters (n_embd_head_{k,v}_mla, kv_lora_rank,
    /// rope_yarn_log_mul, MoE switches...)
    pub ds2: Deepseek2Params,
    /// hparams.indexer_n_head
    pub indexer_n_head: i64,
    /// hparams.indexer_head_size
    pub indexer_head_size: i64,
    /// hparams.indexer_top_k
    pub indexer_top_k: i64,
    /// f_norm_eps (1e-6, deepseek32.cpp:9) — the indexer k LAYER-norm eps
    /// (build_norm LLM_NORM with indexer_k_norm/b, deepseek32.cpp:241)
    pub f_norm_eps: f32,
}

/// build_norm LLM_NORM (llama-graph.cpp:1524-1582): layer_norm then mul by
/// the weight (add the bias). deepseek32's indexer_k_norm is the only user
/// in this batch.
fn build_norm_layer(
    ctx: &mut Context,
    x: TensorId,
    w: TensorId,
    b: Option<TensorId>,
    eps: f32,
) -> TensorId {
    let mut cur = ctx.norm(x, eps);
    cur = ctx.mul(cur, w);
    if let Some(b) = b {
        cur = ctx.add(cur, b);
    }
    cur
}

// ======================================================================
// arch batch 6b (2026-09-24): nemotron (dense) / grok / chameleon / deci /
// jais / falcon-h1 / plamo2.
//
// Reused from earlier batches: `build_norm` (LLM_NORM), `build_norm_rms`,
// `build_ffn_silu_par`, `build_ffn_gelu_par`, `build_ffn_relu_sqr`,
// `qkv_fused`/`qkv_separate_parts`/`rope_qk`, `attn_kv_cached`,
// `build_mamba2_mixer` (falcon-h1's `llm_build_mamba_base::build_mamba2_layer`
// call, mamba-base.cpp:153-302) and the ALiBi max_bias parameter of
// `attn_kv_cached` (batch 3 — jais reads its bias from the GGUF KV).
// New local helpers: `attn_kv_cached_grok` (the arch-specific kq tanh of
// llama-graph.cpp:2682-2689), `build_moe_ffn_gelu` (grok's GELU experts) and
// the swiglu/view compositions noted inline (chameleon's `ggml_set_1d`,
// plamo2's `ggml_swiglu` — no new ggml ops needed, see the notes).
// ======================================================================

// ----------------------------------------------------------------------
// nemotron dense (src/models/nemotron.cpp:50-150)
// ----------------------------------------------------------------------

/// Per-layer weights (nemotron.cpp:22-43 load_arch_tensors).
#[derive(Clone, Copy)]
pub struct NemotronLayerWeights {
    pub attn_norm: TensorId,
    pub attn_norm_b: TensorId,
    pub wqkv: Option<TensorId>,
    pub wqkv_b: Option<TensorId>,
    pub wq: Option<TensorId>,
    pub wq_b: Option<TensorId>,
    pub wk: Option<TensorId>,
    pub wk_b: Option<TensorId>,
    pub wv: Option<TensorId>,
    pub wv_b: Option<TensorId>,
    pub wo: TensorId,
    /// optional bias tensors (nemotron.cpp:31-32)
    pub wo_b: Option<TensorId>,
    pub ffn_norm: TensorId,
    pub ffn_norm_b: TensorId,
    pub ffn_up: TensorId,
    pub ffn_up_b: Option<TensorId>,
    pub ffn_down: TensorId,
    pub ffn_down_b: Option<TensorId>,
}

pub struct NemotronModelWeights {
    pub tok_embd: TensorId,
    pub output_norm: TensorId,
    pub output_norm_b: TensorId,
    /// output.weight is required — no tied head (nemotron.cpp:20)
    pub output: TensorId,
    pub layers: Vec<NemotronLayerWeights>,
}

#[derive(Clone, Copy)]
pub struct NemotronParams {
    /// `attn.norm_eps` carries hparams.f_norm_eps (the LayerNorm eps,
    /// nemotron.cpp:4) — the driver sets it like the gpt2 family
    pub attn: AttnParams,
}

/// verify against src/models/nemotron.cpp:50-150 `graph::graph` — LayerNorm+bias
/// pre-norms, GQA attention with NEOX rope, the relu² up/down MLP (no gate)
/// and the biased final LayerNorm over a required untied lm_head.
pub fn build_nemotron_forward(
    ctx: &mut Context,
    w: &NemotronModelWeights,
    p: &NemotronParams,
    kv: &KvCache,
    inp: &DecodeInputs,
    _sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(2048);
    let a = &p.attn;
    assert_eq!(
        a.n_embd_head_v, a.n_embd_head_k,
        "nemotron: head_v == head_k"
    );

    // inpL = build_inp_embd (nemotron.cpp:59)
    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_sa = inp_l;

        // build_norm(inpL, attn_norm, attn_norm_b, LLM_NORM, il)
        // (nemotron.cpp:72-75)
        let cur = build_norm(
            ctx,
            inp_l,
            Some(lw.attn_norm),
            Some(lw.attn_norm_b),
            a.norm_eps,
        );

        // self-attention (nemotron.cpp:79-103): build_qkv + rope + build_attn
        // with kq_scale = 1/sqrt(n_embd_head)
        let (q, k, v) = if let Some(wqkv) = lw.wqkv {
            qkv_fused(ctx, wqkv, lw.wqkv_b, a, cur, t)
        } else {
            qkv_separate_parts(
                ctx,
                lw.wq.expect("nemotron wq"),
                lw.wq_b,
                lw.wk.expect("nemotron wk"),
                lw.wk_b,
                lw.wv.expect("nemotron wv"),
                lw.wv_b,
                a,
                cur,
                t,
            )
        };
        let (q, k) = rope_qk(ctx, a, inp.pos, q, k);
        let cur = attn_kv_cached(
            ctx,
            &mut graph,
            kv,
            il,
            a,
            inp,
            n_kv,
            q,
            k,
            v,
            1.0 / (a.n_embd_head_v as f32).sqrt(), // nemotron.cpp:102
            0.0,
            None,
            None,
            Some(lw.wo),
            lw.wo_b,
        );

        // ffn_inp = ggml_add(cur, inpSA) (nemotron.cpp:104-109; the
        // inp_out_ids get_rows of :104-107 only prunes rows)
        let ffn_inp = ctx.add(cur, inp_sa);

        // build_norm(ffn_inp, ffn_norm, ffn_norm_b, LLM_NORM, il)
        // (nemotron.cpp:112-115)
        let cur = build_norm(
            ctx,
            ffn_inp,
            Some(lw.ffn_norm),
            Some(lw.ffn_norm_b),
            a.norm_eps,
        );

        // build_ffn(..., ffn_up, ffn_up_b, NULL, ffn_down, ffn_down_b,
        // LLM_FFN_RELU_SQR, LLM_FFN_SEQ) (nemotron.cpp:118-123)
        let cur = build_ffn_relu_sqr(ctx, cur, lw.ffn_up, lw.ffn_up_b, lw.ffn_down, lw.ffn_down_b);

        let cur = ctx.add(cur, ffn_inp);
        inp_l = cur;
    }

    // build_norm(cur, output_norm, output_norm_b, LLM_NORM, -1)
    // (nemotron.cpp:136-138)
    let cur = build_norm(
        ctx,
        inp_l,
        Some(w.output_norm),
        Some(w.output_norm_b),
        a.norm_eps,
    );
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let logits = crate::adapter::lora_mm(ctx, w.output, cur);
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

// ----------------------------------------------------------------------
// grok (src/models/grok.cpp:86-223)
// ----------------------------------------------------------------------

/// Per-layer weights (grok.cpp:54-79 load_arch_tensors).
#[derive(Clone, Copy)]
pub struct GrokLayerWeights {
    pub attn_norm: TensorId,
    pub wqkv: Option<TensorId>,
    pub wqkv_b: Option<TensorId>,
    pub wq: Option<TensorId>,
    pub wq_b: Option<TensorId>,
    pub wk: Option<TensorId>,
    pub wk_b: Option<TensorId>,
    pub wv: Option<TensorId>,
    pub wv_b: Option<TensorId>,
    pub wo: TensorId,
    /// post-attention RMS norm (grok.cpp:62 — the norm sits between the
    /// attention output and the residual add)
    pub attn_out_norm: TensorId,
    pub ffn_norm: TensorId,
    /// optional dense branch (grok.cpp:66-68)
    pub ffn_gate: Option<TensorId>,
    pub ffn_down: Option<TensorId>,
    pub ffn_up: Option<TensorId>,
    /// MoE (grok.cpp:70-73) — gate_exps optional (silu-style experts without
    /// it), down/up required
    pub ffn_gate_inp: TensorId,
    pub ffn_gate_exps: Option<TensorId>,
    pub ffn_down_exps: TensorId,
    pub ffn_up_exps: TensorId,
    /// grok.cpp:75-78 — `layer_output_norm` if present, else `post_ffw_norm`
    pub ffn_post_norm: TensorId,
}

pub struct GrokModelWeights {
    pub tok_embd: TensorId,
    pub output_norm: TensorId,
    pub output: TensorId,
    pub layers: Vec<GrokLayerWeights>,
}

/// grok.cpp:3-33 (the scale/softcap keys with their old-GGUF defaults) + the
/// MoE knobs the graph's build_moe_ffn call needs.
#[derive(Clone, Copy)]
pub struct GrokParams {
    pub attn: AttnParams,
    pub n_expert: i64,
    pub n_expert_used: i64,
    /// hparams.f_logit_scale (grok.cpp:6, output.scale(cur, f_logit_scale))
    pub f_logit_scale: f32,
    /// hparams.f_embedding_scale — applied by the shared build_inp_embd
    /// (llama-graph.cpp:2433-2437); grok defaults it to sqrt(6144)
    pub f_embedding_scale: f32,
    /// hparams.f_final_logit_softcapping — 0.0 for grok-1 (grok.cpp:12)
    pub f_final_logit_softcapping: f32,
    /// the GROK kq softcap pair of llama-graph.cpp:2682-2689:
    /// kq = cap * tanh(kq * f_attn_out_scale / cap)
    pub f_attn_out_scale: f32,
    pub f_attn_logit_softcapping: f32,
}

/// `build_attn`'s GROK non-FA branch — the shared `attn_kv_cached` with the
/// arch-specific kq transform of llama-graph.cpp:2682-2689 spliced between
/// the kq matmul and the softmax:
/// `kq = cap * tanh(kq * f_attn_out_scale / cap)` (note: applied ONLY in the
/// non-FA branch — the FA call passes logit_softcap = 0 because grok never
/// sets `hparams.attn_soft_cap`, llama-graph.cpp:2643-2644, so the reference
/// itself computes different numbers in the two modes).
#[allow(clippy::too_many_arguments)]
fn attn_kv_cached_grok(
    ctx: &mut Context,
    graph: &mut Graph,
    kv: &KvCache,
    il: usize,
    p: &AttnParams,
    inp: &DecodeInputs,
    n_kv: u32,
    q: TensorId,
    k: TensorId,
    v: TensorId,
    kq_scale: f32,
    gp: &GrokParams,
    wo: TensorId,
) -> TensorId {
    let t = ctx.ne(q)[2];
    debug_assert!(!kv.layer_is_swa(il));

    // the set_rows scatter + cache views — identical to attn_kv_cached
    // (llama-kv-cache.cpp:1318/1353)
    let k_rows = {
        let nb2 = ctx.nb(k)[2] as usize;
        ctx.view_2d(k, p.n_embd_head_k * p.n_head_kv, t, nb2, 0)
    };
    let v_rows = {
        let nb2 = ctx.nb(v)[2] as usize;
        ctx.view_2d(v, p.n_embd_head_v * p.n_head_kv, t, nb2, 0)
    };
    let k_dst = ctx.set_rows(kv.layers[il].k, k_rows, inp.row_idx);
    let v_dst = ctx.set_rows(kv.layers[il].v, v_rows, inp.row_idx);
    graph.build_forward(ctx, k_dst);
    graph.build_forward(ctx, v_dst);

    let k_view = kv.get_k(ctx, il, p.n_embd_head_k, p.n_head_kv, n_kv);
    let v_view = kv.get_v(ctx, il, p.n_embd_head_v, p.n_head_kv, n_kv);

    if p.use_flash_attn {
        // FA branch: no softcap at all (attn_soft_cap is false for grok,
        // llama-graph.cpp:2643-2644)
        let kqv = graph::flash_attn_core_sinks(
            ctx,
            q,
            k_view,
            v_view,
            inp.kq_mask,
            None,
            kq_scale,
            0.0,
            0.0,
        );
        return crate::adapter::lora_mm(ctx, wo, kqv);
    }

    let q = ctx.permute(q, 0, 2, 1, 3);
    let k_view = ctx.permute(k_view, 0, 2, 1, 3);

    let mut kq = ctx.mul_mat(k_view, q);
    // if (arch == LLM_ARCH_GROK) (llama-graph.cpp:2682-2689):
    //   kq = 30 * tanh(kq * f_attn_out_scale / 30)
    kq = ctx.scale(kq, gp.f_attn_out_scale / gp.f_attn_logit_softcapping);
    kq = ctx.tanh(kq);
    kq = ctx.scale(kq, gp.f_attn_logit_softcapping);

    kq = ctx.soft_max_ext(kq, Some(inp.kq_mask), kq_scale, 0.0);

    let v_view = ctx.permute(v_view, 0, 2, 1, 3);
    let v_t = ctx.transpose(v_view);
    let v_c = ctx.cont(v_t);
    let kqv = ctx.mul_mat(v_c, kq);
    let kqv = ctx.permute(kqv, 0, 2, 1, 3);
    let kqv = ctx.cont(kqv);
    let kqv = ctx.reshape_2d(kqv, p.n_embd_head_v * p.n_head, t);
    crate::adapter::lora_mm(ctx, wo, kqv)
}

/// grok's build_moe_ffn (llama-graph.cpp:1994-2380 instantiated as
/// LLM_FFN_GELU / norm_w = true / SOFTMAX gating / no exp_probs_b —
/// grok.cpp:158-168): geglu_split (or plain gelu without gate_exps) experts
/// with the normalized selection weights.
#[allow(clippy::too_many_arguments)]
fn build_moe_ffn_gelu(
    ctx: &mut Context,
    graph: &mut Graph,
    cur: TensorId,
    gate_inp: TensorId,
    up_exps: TensorId,
    gate_exps: Option<TensorId>,
    down_exps: TensorId,
    n_expert: i64,
    n_expert_used: i64,
    w_scale: f32,
) -> TensorId {
    let n_embd = ctx.ne(cur)[0];
    let n_tokens = ctx.ne(cur)[1];

    // SOFTMAX gating (grok.cpp:167)
    let logits = crate::adapter::lora_mm(ctx, gate_inp, cur);
    let probs = ctx.soft_max(logits);

    let selected = ctx.argsort_top_k(probs, n_expert_used as i32);

    let probs3 = ctx.reshape_3d(probs, 1, n_expert, n_tokens);
    let mut weights = ctx.get_rows(probs3, selected); // [1, k, n_tokens]

    // norm_w = true (grok.cpp:165)
    let w2 = ctx.reshape_2d(weights, n_expert_used, n_tokens);
    let sum = ctx.sum_rows(w2); // [1, n_tokens]
    let sum = ctx.clamp(sum, 6.103515625e-5, f32::INFINITY);
    let w2 = ctx.div(w2, sum);
    weights = ctx.reshape_3d(w2, 1, n_expert_used, n_tokens);
    if w_scale != 0.0 && w_scale != 1.0 {
        weights = ctx.scale(weights, w_scale);
    }
    graph.build_forward(ctx, weights);

    let cur3 = ctx.reshape_3d(cur, n_embd, 1, n_tokens);
    let up = crate::adapter::lora_mm_id(ctx, up_exps, cur3, selected);
    // LLM_FFN_GELU with/without the gate (llama-graph.cpp:2256-2270)
    let act = match gate_exps {
        Some(ge) => {
            let g = crate::adapter::lora_mm_id(ctx, ge, cur3, selected);
            ctx.geglu_split(g, up)
        }
        None => ctx.gelu(up),
    };
    let mut experts = crate::adapter::lora_mm_id(ctx, down_exps, act, selected);
    experts = ctx.mul(experts, weights);
    graph.build_forward(ctx, experts);

    // aggregate the k expert views (llama-graph.cpp:2329-2358)
    let nb1 = ctx.nb(experts)[1] as usize;
    let nb2 = ctx.nb(experts)[2] as usize;
    let mut moe_out = ctx.view_2d(experts, n_embd, n_tokens, nb2, 0);
    graph.build_forward(ctx, moe_out);
    for i in 1..n_expert_used as usize {
        let vi = ctx.view_2d(experts, n_embd, n_tokens, nb2, i * nb1);
        graph.build_forward(ctx, vi);
        moe_out = ctx.add(moe_out, vi);
        graph.build_forward(ctx, moe_out);
    }
    if n_expert_used == 1 {
        moe_out = ctx.cont(moe_out);
    }
    moe_out
}

/// verify against src/models/grok.cpp:86-223 `graph::graph` — RMS pre-norm, attention
/// with the grok kq softcap and a *post-attention* RMS norm before the
/// residual add, GELU MoE (norm_w) with the optional dense-branch
/// `(dense + moe) * sqrt(2)/2` mix, `ffn_post_norm` after the FFN and the
/// `f_logit_scale`-scaled lm_head (final softcap only when non-zero).
pub fn build_grok_forward(
    ctx: &mut Context,
    w: &GrokModelWeights,
    p: &GrokParams,
    kv: &KvCache,
    inp: &DecodeInputs,
    _sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(4096);
    let a = &p.attn;
    assert_eq!(a.n_embd_head_v, a.n_embd_head_k, "grok: head_v == head_k");
    assert_eq!(a.n_embd_head_v, a.n_rot, "grok: n_embd_head == n_rot");

    // inpL = build_inp_embd (grok.cpp:95) — the shared build_inp_embd applies
    // hparams.f_embedding_scale (llama-graph.cpp:2433-2437), which grok's
    // hparams default to 78.38 = sqrt(6144) (grok.cpp:7) even though grok.cpp
    // itself never mentions it
    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);
    if p.f_embedding_scale != 0.0 {
        inp_l = ctx.scale(inp_l, p.f_embedding_scale);
    }

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_sa = inp_l;

        // build_norm(inpL, attn_norm, NULL, LLM_NORM_RMS) (grok.cpp:108-110)
        let cur = build_norm_rms(ctx, inp_l, lw.attn_norm, a.norm_eps);

        // self-attention (grok.cpp:113-137): build_qkv + rope + build_attn
        // (kq_scale = 1.0f, the scaling lives in the GROK softcap branch)
        let (q, k, v) = if let Some(wqkv) = lw.wqkv {
            qkv_fused(ctx, wqkv, lw.wqkv_b, a, cur, t)
        } else {
            qkv_separate_parts(
                ctx,
                lw.wq.expect("grok wq"),
                lw.wq_b,
                lw.wk.expect("grok wk"),
                lw.wk_b,
                lw.wv.expect("grok wv"),
                lw.wv_b,
                a,
                cur,
                t,
            )
        };
        let (q, k) = rope_qk(ctx, a, inp.pos, q, k);
        let cur = attn_kv_cached_grok(
            ctx, &mut graph, kv, il, a, inp, n_kv, q, k, v, 1.0, p, lw.wo,
        );

        // attn_out_norm BEFORE the residual add (grok.cpp:143-148)
        let cur = build_norm_rms(ctx, cur, lw.attn_out_norm, a.norm_eps);
        let ffn_inp = ctx.add(cur, inp_sa);

        // MoE branch (grok.cpp:151-168)
        let cur = build_norm_rms(ctx, ffn_inp, lw.ffn_norm, a.norm_eps);
        let moe_out = build_moe_ffn_gelu(
            ctx,
            &mut graph,
            cur,
            lw.ffn_gate_inp,
            lw.ffn_up_exps,
            lw.ffn_gate_exps,
            lw.ffn_down_exps,
            p.n_expert,
            p.n_expert_used,
            0.0, // hparams.expert_weights_scale (default 0 → skip)
        );

        // optional dense "MoE + FFN" mix (grok.cpp:171-184)
        let cur = if let (Some(up), Some(gate), Some(down)) = (lw.ffn_up, lw.ffn_gate, lw.ffn_down)
        {
            let ffn_out = build_ffn_gelu_par(ctx, cur, up, gate, down);
            // ggml_scale(ctx0, ggml_add(ctx0, ffn_out, moe_out), sqrt(2)/2)
            // (grok.cpp:180 — std::sqrt(2)/2, double precision)
            let mixed = ctx.add(ffn_out, moe_out);
            ctx.scale(mixed, (2.0f64).sqrt() as f32 / 2.0)
        } else {
            moe_out
        };

        // ffn_post_norm (grok.cpp:185-188) then the residual
        let cur = build_norm_rms(ctx, cur, lw.ffn_post_norm, a.norm_eps);
        inp_l = ctx.add(cur, ffn_inp);
    }

    // final norm + lm_head + logit scale (grok.cpp:199-218)
    // res->t_embd = cur (grok.cpp:206) — before the lm_head
    let embd = build_norm_rms(ctx, inp_l, w.output_norm, a.norm_eps);
    let embd = graph::out_rows(ctx, embd, inp.out_ids);
    let mut cur = crate::adapter::lora_mm(ctx, w.output, embd);
    cur = ctx.scale(cur, p.f_logit_scale);
    // final logit soft-capping (grok.cpp:214-218) — 0.0 skips it (grok-1)
    if p.f_final_logit_softcapping != 0.0 {
        cur = ctx.scale(cur, 1.0 / p.f_final_logit_softcapping);
        cur = ctx.tanh(cur);
        cur = ctx.scale(cur, p.f_final_logit_softcapping);
    }
    graph.build_forward(ctx, cur);
    ForwardResult {
        logits: cur,
        graph,
        embd: Some(embd),
    }
}

