/// Per-layer weights (chameleon.cpp:29-46 load_arch_tensors).
#[derive(Clone, Copy)]
pub struct ChameleonLayerWeights {
    pub attn_norm: TensorId,
    /// full-width q/k LayerNorm weights + optional biases (chameleon.cpp:33-36)
    pub attn_q_norm: TensorId,
    pub attn_q_norm_b: Option<TensorId>,
    pub attn_k_norm: TensorId,
    pub attn_k_norm_b: Option<TensorId>,
    pub wqkv: Option<TensorId>,
    pub wqkv_b: Option<TensorId>,
    pub wq: Option<TensorId>,
    pub wq_b: Option<TensorId>,
    pub wk: Option<TensorId>,
    pub wk_b: Option<TensorId>,
    pub wv: Option<TensorId>,
    pub wv_b: Option<TensorId>,
    pub wo: TensorId,
    pub ffn_norm: TensorId,
    pub ffn_gate: TensorId,
    pub ffn_down: TensorId,
    pub ffn_up: TensorId,
}

pub struct ChameleonModelWeights {
    pub tok_embd: TensorId,
    pub output_norm: TensorId,
    pub output: TensorId,
    pub layers: Vec<ChameleonLayerWeights>,
}

#[derive(Clone, Copy)]
pub struct ChameleonParams {
    pub attn: AttnParams,
    /// hparams.swin_norm (chameleon.cpp:7) — the Swin-style post-norm layout
    pub swin_norm: bool,
    /// hparams.f_norm_eps — 1e-5, "eps for qk-norm, torch default"
    /// (chameleon.cpp:6); `attn.norm_eps` carries the RMS eps
    pub f_norm_eps_qk: f32,
}

/// verify against src/models/chameleon.cpp:53-204 `graph::graph` — SwiGLU with
/// full-width q/k LayerNorms before the rope (Swin-norm layout optional),
/// and the image-token logit suppression of :187-198 that clamps the
/// vocab range [4, 8196) of the output row to -FLT_MAX.
///
/// The C composes it as `ggml_set_1d(lm_head, clamp(new_tensor_1d(8192),
/// -FLT_MAX, -FLT_MAX), 4 * es)` (chameleon.cpp:194-198). The port's ggml
/// crate has no GGML_OP_SET builder, so the patch is composed from the two
/// 1-d views around the replaced segment + `ggml_concat` — pure copies of
/// the same elements, byte-identical to the C kernel
/// (ggml_compute_forward_set_f32, ops.cpp:4769: memcpy of src0 then one
/// `ggml_vec_cpy_f32` row at `offset`; img_logits is 1-D so exactly one
/// 8192-wide row is replaced). The C's `il == n_layer-1` inp_out_ids
/// pruning (:127-130) runs before the set_1d, so the replaced row is the
/// pruned tensor's row 0 — i.e. the LAST token's logits, which is what
/// every caller reads; the composition below reproduces that on the
/// unpruned [n_vocab, T] tensor. `ggml_set_1d` remains the one op an
/// integrator could add to make the graph op-for-op identical.
pub fn build_chameleon_forward(
    ctx: &mut Context,
    w: &ChameleonModelWeights,
    p: &ChameleonParams,
    kv: &KvCache,
    inp: &DecodeInputs,
    _sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(2048);
    let a = &p.attn;
    assert_eq!(
        a.n_embd_head_v, a.n_embd_head_k,
        "chameleon: head_v == head_k"
    );
    assert_eq!(a.n_embd_head_v, a.n_rot, "chameleon: n_embd_head == n_rot");

    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_sa = inp_l;

        // swin_norm: no pre-norm — the raw residual feeds the attention
        // (chameleon.cpp:75-82)
        let cur = if p.swin_norm {
            inp_l
        } else {
            build_norm_rms(ctx, inp_l, lw.attn_norm, a.norm_eps)
        };

        // self-attention (chameleon.cpp:85-125): build_qkv → full-width
        // q/k LayerNorms → rope → build_attn
        let (mut q, mut k, v) = if let Some(wqkv) = lw.wqkv {
            qkv_fused(ctx, wqkv, lw.wqkv_b, a, cur, t)
        } else {
            qkv_separate_parts(
                ctx,
                lw.wq.expect("chameleon wq"),
                lw.wq_b,
                lw.wk.expect("chameleon wk"),
                lw.wk_b,
                lw.wv.expect("chameleon wv"),
                lw.wv_b,
                a,
                cur,
                t,
            )
        };
        // build_norm(Qcur, attn_q_norm, attn_q_norm_b, LLM_NORM)
        // (chameleon.cpp:90-104) — before the rope
        q = build_norm(
            ctx,
            q,
            Some(lw.attn_q_norm),
            lw.attn_q_norm_b,
            p.f_norm_eps_qk,
        );
        k = build_norm(
            ctx,
            k,
            Some(lw.attn_k_norm),
            lw.attn_k_norm_b,
            p.f_norm_eps_qk,
        );
        let (q, k) = rope_qk(ctx, a, inp.pos, q, k);
        let cur = attn_kv_cached(
            ctx,
            &mut graph,
            kv,
            il,
            a,
            inp,
            n_kv,
            q,
            k,
            v,
            1.0 / (a.n_embd_head_v as f32).sqrt(), // chameleon.cpp:124
            0.0,
            None,
            None,
            Some(lw.wo),
            None,
        );

        // swin_norm: the attention output is normed post-hoc instead
        // (chameleon.cpp:132-136)
        let cur = if p.swin_norm {
            build_norm_rms(ctx, cur, lw.attn_norm, a.norm_eps)
        } else {
            cur
        };

        let ffn_inp = ctx.add(cur, inp_sa);

        // FFN (chameleon.cpp:141-162): SwiGLU PAR with the ffn_norm before
        // (!swin) or after (swin) the MLP
        let cur = if !p.swin_norm {
            build_norm_rms(ctx, ffn_inp, lw.ffn_norm, a.norm_eps)
        } else {
            ffn_inp
        };
        let cur = build_ffn_silu_par(
            ctx,
            cur,
            lw.ffn_gate,
            None,
            lw.ffn_up,
            None,
            lw.ffn_down,
            None,
        );
        let cur = if p.swin_norm {
            build_norm_rms(ctx, cur, lw.ffn_norm, a.norm_eps)
        } else {
            cur
        };
        inp_l = ctx.add(cur, ffn_inp);
    }

    // final norm + lm_head (chameleon.cpp:174-185)
    // res->t_embd = cur (chameleon.cpp:181) — before the lm_head
    let embd = build_norm_rms(ctx, inp_l, w.output_norm, a.norm_eps);
    let embd = graph::out_rows(ctx, embd, inp.out_ids);
    let cur = crate::adapter::lora_mm(ctx, w.output, embd);

    // image-token logit suppression (chameleon.cpp:187-198)
    const IMG_TOKEN_END_IDX: i64 = 8196;
    const IMG_TOKEN_START_IDX: i64 = 4;
    let num_img_tokens = IMG_TOKEN_END_IDX - IMG_TOKEN_START_IDX;
    // img_logits = clamp(new_tensor_1d(F32, 8192), -FLT_MAX, -FLT_MAX) —
    // the uninitialized contents are irrelevant: clamp(x, m, m) == m
    let img_logits = ctx.new_tensor_1d(GgmlType::F32, num_img_tokens);
    let img_logits = ctx.clamp(img_logits, f32::MIN, f32::MIN);
    // set_1d(cur, img_logits, 4 * element_size) composed from the untouched
    // 1-d views + the constant segment (see the builder's notes). The C's
    // `il == n_layer-1` inp_out_ids pruning runs BEFORE the set_1d
    // (chameleon.cpp:127-130 vs :198), so the patch lands on the row that
    // survives the prune — the LAST token's row (at generation steps the
    // single row, exactly the C); the rows before it stay raw.
    let n_vocab = ctx.ne(cur)[0];
    let t_rows = ctx.ne(cur)[1];
    let last_row = n_vocab * (t_rows - 1);
    assert!(
        n_vocab > IMG_TOKEN_END_IDX,
        "chameleon: logits too small for the img range"
    );
    let pre = ctx.view_1d(cur, last_row + IMG_TOKEN_START_IDX, 0);
    let post = ctx.view_1d(
        cur,
        n_vocab - IMG_TOKEN_END_IDX,
        ((last_row + IMG_TOKEN_END_IDX) * 4) as usize,
    );
    let patched = ctx.concat(pre, img_logits, 0);
    let patched = ctx.concat(patched, post, 0);
    let logits = ctx.reshape_2d(patched, n_vocab, t_rows);

    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(embd),
    }
}

// ----------------------------------------------------------------------
// deci (src/models/deci.cpp:80-191)
// ----------------------------------------------------------------------

/// Per-layer weights (deci.cpp:28-73 load_arch_tensors) — which members a
/// layer carries depends on its per-layer n_head / n_head_kv / n_ff:
///   * n_head_kv > 0        — attention (attn_norm + qkv + wo)
///   * n_head > 0, kv == 0  — "linear attention" (attn_norm + wo only)
///   * n_head == 0          — attention-free (neither)
///   * n_ff == 0            — FFN-free (no ffn_norm/MLP at all)
#[derive(Clone, Copy)]
pub struct DeciLayerWeights {
    pub attn_norm: Option<TensorId>,
    pub wqkv: Option<TensorId>,
    pub wqkv_b: Option<TensorId>,
    pub wq: Option<TensorId>,
    pub wq_b: Option<TensorId>,
    pub wk: Option<TensorId>,
    pub wk_b: Option<TensorId>,
    pub wv: Option<TensorId>,
    pub wv_b: Option<TensorId>,
    pub wo: Option<TensorId>,
    pub wo_b: Option<TensorId>,
    /// get_rope_factors (llama-model.cpp:2259-2272): the layer's rope_freqs,
    /// else rope_long/rope_short by n_ctx_seq vs n_ctx_orig_yarn (resolved
    /// by the driver like phimoe)
    pub rope_factors: Option<TensorId>,
    pub ffn_norm: Option<TensorId>,
    pub ffn_gate: Option<TensorId>,
    pub ffn_gate_b: Option<TensorId>,
    pub ffn_down: Option<TensorId>,
    pub ffn_down_b: Option<TensorId>,
    pub ffn_up: Option<TensorId>,
    pub ffn_up_b: Option<TensorId>,
}

pub struct DeciModelWeights {
    pub tok_embd: TensorId,
    pub output_norm: TensorId,
    pub output: TensorId,
    pub layers: Vec<DeciLayerWeights>,
}

/// deci.cpp:3-12 (RMS eps) + the per-layer geometry arrays.
#[derive(Clone)]
pub struct DeciParams {
    /// rope + the global head dims + f_norm_rms_eps; n_head/n_head_kv are
    /// overridden per layer below (head dims are global, llama-model.cpp)
    pub attn: AttnParams,
    pub n_head: Vec<u32>,
    pub n_head_kv: Vec<u32>,
    /// hparams.n_ff(il) — 0 marks an FFN-free layer
    pub n_ff: Vec<i64>,
    /// 0.0 → 1/sqrt(n_embd_head) (deci.cpp:96-97)
    pub f_attention_scale: f32,
}

/// verify against src/models/deci.cpp:80-191 `graph::graph` — the per-layer attention
/// kinds of DeciLM (attention / linear-attention / attention-free) with
/// per-layer head counts, rope factors from get_rope_factors and the
/// FFN-free layers.
///
/// Notable literal details:
///   * the linear-attention layer projects through `wo` without its bias
///     (deci.cpp:117 — `build_lora_mm(wo, cur)` only, the loaded wo_b is
///     never read);
///   * an FFN-free layer `continue`s past `inpL = cur` (deci.cpp:146-149),
///     so its attention output is DISCARDED and the residual passes through
///     unchanged — ported as-is;
///   * the attention-free layer's FFN takes `cur` itself as ffn_inp (no
///     residual add, deci.cpp:150-155).
pub fn build_deci_forward(
    ctx: &mut Context,
    w: &DeciModelWeights,
    p: &DeciParams,
    kv: &KvCache,
    inp: &DecodeInputs,
    _sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(2048);
    let a = &p.attn;
    assert_eq!(a.n_embd_head_v, a.n_embd_head_k, "deci: head_v == head_k");
    assert_eq!(a.n_embd_head_v, a.n_rot, "deci: n_embd_head == n_rot");

    // kq_scale (deci.cpp:96-97)
    let kq_scale = if p.f_attention_scale == 0.0 {
        1.0 / (a.n_embd_head_v as f32).sqrt()
    } else {
        p.f_attention_scale
    };

    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_sa = inp_l;
        let n_head = p.n_head[il] as i64;
        let n_head_kv = p.n_head_kv[il] as i64;
        let n_ff = p.n_ff[il];

        let cur = if n_head == 0 {
            // attention-free layer of Llama-3_1-Nemotron-51B (deci.cpp:107-110)
            inp_l
        } else {
            // build_norm(inpL, attn_norm, NULL, LLM_NORM_RMS) (deci.cpp:112)
            build_norm_rms(
                ctx,
                inp_l,
                lw.attn_norm.expect("deci attn_norm"),
                a.norm_eps,
            )
        };

        let cur = if n_head > 0 && n_head_kv == 0 {
            // "linear attention" of Llama-3_1-Nemotron-51B (deci.cpp:115-119)
            crate::adapter::lora_mm(ctx, lw.wo.expect("deci wo"), cur)
        } else if n_head > 0 {
            // self-attention (deci.cpp:119-141): build_qkv + rope(factors) +
            // build_attn with the per-layer head counts
            let mut al = *a;
            al.n_head = n_head;
            al.n_head_kv = n_head_kv;
            let (q, k, v) = if let Some(wqkv) = lw.wqkv {
                qkv_fused(ctx, wqkv, lw.wqkv_b, &al, cur, t)
            } else {
                qkv_separate_parts(
                    ctx,
                    lw.wq.expect("deci wq"),
                    lw.wq_b,
                    lw.wk.expect("deci wk"),
                    lw.wk_b,
                    lw.wv.expect("deci wv"),
                    lw.wv_b,
                    &al,
                    cur,
                    t,
                )
            };
            let r = |ctx: &mut Context, x: TensorId| {
                ctx.rope_ext(
                    x,
                    inp.pos,
                    lw.rope_factors,
                    a.n_rot as i32,
                    a.rope_mode,
                    a.n_ctx_orig,
                    a.freq_base,
                    a.freq_scale,
                    a.ext_factor,
                    a.attn_factor,
                    a.beta_fast,
                    a.beta_slow,
                )
            };
            let q = r(ctx, q);
            let k = r(ctx, k);
            attn_kv_cached(
                ctx,
                &mut graph,
                kv,
                il,
                &al,
                inp,
                n_kv,
                q,
                k,
                v,
                kq_scale,
                0.0,
                None,
                None,
                Some(lw.wo.expect("deci wo")),
                lw.wo_b,
            )
        } else {
            cur
        };

        // FFN-free layer of Llama-3_1-Nemotron-Ultra-253B (deci.cpp:146-149):
        // `continue` skips the loop tail, so inpL keeps the residual — the
        // attention output of an FFN-free layer is dropped (as in C)
        if n_ff == 0 {
            continue;
        }

        // modified to support the attention-free layer (deci.cpp:150-155)
        let ffn_inp = if n_head > 0 {
            ctx.add(cur, inp_sa)
        } else {
            cur
        };

        // feed-forward network (deci.cpp:156-166)
        let cur = build_norm_rms(
            ctx,
            ffn_inp,
            lw.ffn_norm.expect("deci ffn_norm"),
            a.norm_eps,
        );
        let cur = build_ffn_silu_par(
            ctx,
            cur,
            lw.ffn_gate.expect("deci ffn_gate"),
            lw.ffn_gate_b,
            lw.ffn_up.expect("deci ffn_up"),
            lw.ffn_up_b,
            lw.ffn_down.expect("deci ffn_down"),
            lw.ffn_down_b,
        );
        inp_l = ctx.add(cur, ffn_inp);
    }

    // final norm + lm_head (deci.cpp:177-188)
    let cur = build_norm_rms(ctx, inp_l, w.output_norm, a.norm_eps);
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let logits = crate::adapter::lora_mm(ctx, w.output, cur);
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

// ----------------------------------------------------------------------
// jais (src/models/jais.cpp:55-132)
// ----------------------------------------------------------------------

/// Per-layer weights (jais.cpp:25-48 load_arch_tensors) — everything is
/// required, including the fused qkv bias and every FFN bias.
#[derive(Clone, Copy)]
pub struct JaisLayerWeights {
    pub attn_norm: TensorId,
    pub attn_norm_b: TensorId,
    pub wqkv: TensorId,
    pub wqkv_b: TensorId,
    pub wo: TensorId,
    pub wo_b: TensorId,
    pub ffn_norm: TensorId,
    pub ffn_norm_b: TensorId,
    pub ffn_gate: TensorId,
    pub ffn_gate_b: TensorId,
    pub ffn_down: TensorId,
    pub ffn_down_b: TensorId,
    pub ffn_up: TensorId,
    pub ffn_up_b: TensorId,
}

pub struct JaisModelWeights {
    pub tok_embd: TensorId,
    pub output_norm: TensorId,
    pub output_norm_b: TensorId,
    pub output: TensorId,
    pub layers: Vec<JaisLayerWeights>,
}

#[derive(Clone, Copy)]
pub struct JaisParams {
    /// `attn.norm_eps` carries hparams.f_norm_eps (the LayerNorm eps,
    /// jais.cpp:4); rope never runs (rope_type NONE)
    pub attn: AttnParams,
    /// hparams.f_max_alibi_bias — read from the GGUF KV (jais.cpp:5); > 0
    /// selects the ALiBi KQ-mask fill + the per-head softmax slopes
    pub f_max_alibi_bias: f32,
}

/// verify against src/models/jais.cpp:55-132 `graph::graph` — LayerNorm+bias norms,
/// the fused qkv with its required bias, NO rope (ALiBi instead: the bias
/// rides the kq mask/softmax `max_bias`, batch 3's mechanism) and a
/// fully-biased SwiGLU FFN.
///
/// The kq scale is `1.0f/float(n_embd_head)` — NOT 1/sqrt (jais.cpp:83).
pub fn build_jais_forward(
    ctx: &mut Context,
    w: &JaisModelWeights,
    p: &JaisParams,
    kv: &KvCache,
    inp: &DecodeInputs,
    _sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(2048);
    let a = &p.attn;
    assert_eq!(a.n_embd_head_v, a.n_embd_head_k, "jais: head_v == head_k");

    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    for il in 0..n_layer {
        let lw = &w.layers[il];

        // build_norm(inpL, attn_norm, attn_norm_b, LLM_NORM) (jais.cpp:70-74)
        let cur = build_norm(
            ctx,
            inp_l,
            Some(lw.attn_norm),
            Some(lw.attn_norm_b),
            a.norm_eps,
        );

        // self-attention (jais.cpp:76-84): fused qkv + bias, no rope, the
        // ALiBi max_bias and kq_scale = 1/n_embd_head
        let (q, k, v) = qkv_fused(ctx, lw.wqkv, Some(lw.wqkv_b), a, cur, t);
        let cur = attn_kv_cached(
            ctx,
            &mut graph,
            kv,
            il,
            a,
            inp,
            n_kv,
            q,
            k,
            v,
            1.0 / a.n_embd_head_v as f32, // jais.cpp:83 — 1/n_embd_head
            p.f_max_alibi_bias,           // llama-graph.cpp:2705
            None,
            None,
            Some(lw.wo),
            Some(lw.wo_b),
        );

        let ffn_inp = ctx.add(cur, inp_l);

        // FF (jais.cpp:93-108)
        let cur = build_norm(
            ctx,
            ffn_inp,
            Some(lw.ffn_norm),
            Some(lw.ffn_norm_b),
            a.norm_eps,
        );
        let cur = build_ffn_silu_par(
            ctx,
            cur,
            lw.ffn_gate,
            Some(lw.ffn_gate_b),
            lw.ffn_up,
            Some(lw.ffn_up_b),
            lw.ffn_down,
            Some(lw.ffn_down_b),
        );
        inp_l = ctx.add(cur, ffn_inp);
    }

    // build_norm(inpL, output_norm, output_norm_b, LLM_NORM, -1)
    // (jais.cpp:118-121)
    let cur = build_norm(
        ctx,
        inp_l,
        Some(w.output_norm),
        Some(w.output_norm_b),
        a.norm_eps,
    );
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let logits = crate::adapter::lora_mm(ctx, w.output, cur);
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

