// falcon-h1 (src/models/falcon-h1.cpp:112-209) — llm_build_mamba_base hybrid
// ----------------------------------------------------------------------

/// Per-layer weights (falcon-h1.cpp:68-105 load_arch_tensors) — every layer
/// carries the mamba2 mixer AND attention tensors; `wo_b` is loaded but the
/// graph passes NULL for it (falcon-h1.cpp:153).
#[derive(Clone, Copy)]
pub struct FalconH1LayerWeights {
    pub attn_norm: TensorId,
    // mamba2 mixer (mamba-base.cpp build_mamba2_layer)
    pub ssm_in: TensorId,
    pub ssm_conv1d: TensorId,
    pub ssm_conv1d_b: Option<TensorId>,
    pub ssm_dt_b: TensorId,
    pub ssm_a: TensorId,
    pub ssm_d: TensorId,
    pub ssm_norm: Option<TensorId>,
    pub ssm_out: TensorId,
    // attention
    pub wqkv: Option<TensorId>,
    pub wqkv_b: Option<TensorId>,
    pub wq: Option<TensorId>,
    pub wq_b: Option<TensorId>,
    pub wk: Option<TensorId>,
    pub wk_b: Option<TensorId>,
    pub wv: Option<TensorId>,
    pub wv_b: Option<TensorId>,
    pub wo: TensorId,
    pub ffn_norm: TensorId,
    pub ffn_gate: TensorId,
    pub ffn_gate_b: Option<TensorId>,
    pub ffn_down: TensorId,
    pub ffn_down_b: Option<TensorId>,
    pub ffn_up: TensorId,
    pub ffn_up_b: Option<TensorId>,
}

pub struct FalconH1ModelWeights {
    pub tok_embd: TensorId,
    pub output_norm: TensorId,
    pub output: TensorId,
    pub layers: Vec<FalconH1LayerWeights>,
}

#[derive(Clone)]
pub struct FalconH1Params {
    pub attn: AttnParams,
    pub n_embd: i64,
    /// mamba2 (hparams.ssm_*)
    pub d_conv: i64,
    pub d_inner: i64,
    pub d_state: i64,
    /// ssm_dt_rank — the mamba2 head count (falcon-h1.cpp:45)
    pub n_ssm_head: i64,
    pub n_group: i64,
    pub norm_eps: f32,
    /// 0.0 → 1/sqrt(n_embd_head) (falcon-h1.cpp:127-128)
    pub f_attention_scale: f32,
    /// hparams.n_embd_r / n_embd_s of the recurrent cells
    pub n_embd_r: u32,
    pub n_embd_s: u32,
}

/// verify against src/models/falcon-h1.cpp:112-209 `graph::graph` — the
/// `llm_build_mamba_base` hybrid where EVERY layer runs attention AND the
/// mamba2 mixer: `attn_norm → (attention ∥ re-norm + mamba2) →
/// cur = attn + ssm; inpSA = cur + inpSA → ffn_norm → SwiGLU → residual`.
///
/// The mamba2 mixer is the shared [`build_mamba2_mixer`] (mamba-base.cpp:
/// 153-302, the single-sequence K = 1 slice); the attention input and the
/// mamba input are TWO separate norms of the same `inpL` with the same
/// `attn_norm` weight (falcon-h1.cpp:135 and :157).
pub fn build_falcon_h1_forward(
    ctx: &mut Context,
    w: &FalconH1ModelWeights,
    p: &FalconH1Params,
    st: &RecurrentState,
    kv: &KvCache,
    inp: &DecodeInputs,
    _sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(4096);
    let a = &p.attn;
    assert_eq!(st.n_layer(), n_layer, "RecurrentState per layer");

    // kq_scale (falcon-h1.cpp:127-128)
    let kq_scale = if p.f_attention_scale == 0.0 {
        1.0 / (a.n_embd_head_v as f32).sqrt()
    } else {
        p.f_attention_scale
    };

    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_sa = inp_l;

        // cur = build_norm(inpL, attn_norm, NULL, LLM_NORM_RMS) — the
        // attention input (falcon-h1.cpp:135)
        let cur = build_norm_rms(ctx, inp_l, lw.attn_norm, p.norm_eps);

        // self-attention (falcon-h1.cpp:138-155): build_qkv + rope + attn
        // (wo_b is NOT passed — :153)
        let (q, k, v) = if let Some(wqkv) = lw.wqkv {
            qkv_fused(ctx, wqkv, lw.wqkv_b, a, cur, t)
        } else {
            qkv_separate_parts(
                ctx,
                lw.wq.expect("falcon-h1 wq"),
                lw.wq_b,
                lw.wk.expect("falcon-h1 wk"),
                lw.wk_b,
                lw.wv.expect("falcon-h1 wv"),
                lw.wv_b,
                a,
                cur,
                t,
            )
        };
        let r = |ctx: &mut Context, x: TensorId| {
            ctx.rope_ext(
                x,
                inp.pos,
                None,
                a.n_rot as i32,
                a.rope_mode,
                a.n_ctx_orig,
                a.freq_base,
                a.freq_scale,
                a.ext_factor,
                a.attn_factor,
                a.beta_fast,
                a.beta_slow,
            )
        };
        let q = r(ctx, q);
        let k = r(ctx, k);
        let attn_out = attn_kv_cached(
            ctx,
            &mut graph,
            kv,
            il,
            a,
            inp,
            n_kv,
            q,
            k,
            v,
            kq_scale,
            0.0,
            None,
            None,
            Some(lw.wo),
            None, // falcon-h1.cpp:153 — wo_b stays NULL
        );

        // cur = build_norm(inpL, attn_norm, NULL, LLM_NORM_RMS) — the mamba
        // input, a SECOND norm of the same residual (falcon-h1.cpp:157)
        let cur = build_norm_rms(ctx, inp_l, lw.attn_norm, p.norm_eps);
        let mixer = Mamba2Mixer {
            ssm_in: lw.ssm_in,
            ssm_conv1d: lw.ssm_conv1d,
            ssm_conv1d_b: lw.ssm_conv1d_b,
            ssm_dt_b: lw.ssm_dt_b,
            ssm_a: lw.ssm_a,
            ssm_d: lw.ssm_d,
            ssm_norm: lw.ssm_norm,
            ssm_out: lw.ssm_out,
        };
        let ssm_out = build_mamba2_mixer(
            ctx,
            &mut graph,
            p.d_conv,
            p.d_inner,
            p.d_state,
            p.n_ssm_head,
            p.n_group,
            p.norm_eps,
            &mixer,
            st,
            il,
            cur,
            t,
        );

        // Aggregation (falcon-h1.cpp:164-166): cur = attn + ssm;
        // inpSA = cur + inpSA (the double residual)
        let cur = ctx.add(attn_out, ssm_out);
        let inp_sa = ctx.add(cur, inp_sa);

        // feed-forward network (falcon-h1.cpp:173-187)
        let ffn_inp = inp_sa;
        let cur = build_norm_rms(ctx, ffn_inp, lw.ffn_norm, p.norm_eps);
        let cur = build_ffn_silu_par(
            ctx,
            cur,
            lw.ffn_gate,
            lw.ffn_gate_b,
            lw.ffn_up,
            lw.ffn_up_b,
            lw.ffn_down,
            lw.ffn_down_b,
        );
        inp_l = ctx.add(cur, ffn_inp);
    }

    // final norm + lm_head (falcon-h1.cpp:195-206)
    let cur = build_norm_rms(ctx, inp_l, w.output_norm, p.norm_eps);
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let logits = crate::adapter::lora_mm(ctx, w.output, cur);
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

// ----------------------------------------------------------------------
// plamo2 (src/models/plamo2.cpp:110-426) — llm_build_mamba_base hybrid with
// the PLaMo-2 mamba1-style x_proj mixer + full-attention layers
// ----------------------------------------------------------------------

/// Per-layer weights (plamo2.cpp:59-103 load_arch_tensors).
#[derive(Clone, Copy)]
pub struct Plamo2LayerWeights {
    pub attn_norm: TensorId,
    // mamba branch (plamo2.cpp:66-80)
    pub ssm_in: Option<TensorId>,
    pub ssm_conv1d: Option<TensorId>,
    pub ssm_x: Option<TensorId>,
    pub ssm_dt: Option<TensorId>,
    pub ssm_dt_b: Option<TensorId>,
    pub ssm_a: Option<TensorId>,
    pub ssm_d: Option<TensorId>,
    pub ssm_out: Option<TensorId>,
    pub ssm_dt_norm: Option<TensorId>,
    pub ssm_b_norm: Option<TensorId>,
    pub ssm_c_norm: Option<TensorId>,
    // attention branch (plamo2.cpp:81-94) — the q/k norms are full-width
    // {qk_dim, n_head} / {qk_dim, n_head_kv}
    pub wqkv: Option<TensorId>,
    pub attn_q_norm: Option<TensorId>,
    pub attn_k_norm: Option<TensorId>,
    pub wo: Option<TensorId>,
    // shared tail (plamo2.cpp:97-102)
    pub attn_post_norm: TensorId,
    pub ffn_norm: TensorId,
    pub ffn_down: TensorId,
    /// {n_embd, 2*n_ff} — the SWIGLU halves live in one tensor
    pub ffn_up: TensorId,
    pub ffn_post_norm: TensorId,
}

pub struct Plamo2ModelWeights {
    pub tok_embd: TensorId,
    pub output_norm: TensorId,
    pub output: TensorId,
    pub layers: Vec<Plamo2LayerWeights>,
}

#[derive(Clone)]
pub struct Plamo2Params {
    /// the attention layers' geometry + rope (derived at the first attention
    /// layer like the other hybrids; n_embd_head_v may differ from head_k)
    pub attn: AttnParams,
    pub n_embd: i64,
    pub is_recr: Vec<bool>,
    /// mamba (hparams.ssm_*; n_heads = ssm_dt_rank, plamo2.cpp:270)
    pub d_conv: i64,
    pub d_inner: i64,
    pub d_state: i64,
    pub n_heads: i64,
    /// asserted 0 by the mixer (plamo2.cpp:281)
    pub n_group: i64,
    pub norm_eps: f32,
    /// std::max(64, int(n_embd / 16)) (plamo2.cpp:43/:344)
    pub dt_dim: i64,
    /// hparams.n_embd_r / n_embd_s of the recurrent cells
    pub n_embd_r: u32,
    pub n_embd_s: u32,
}

/// verify against src/models/plamo2.cpp:110-201 `graph::graph` — per layer:
/// `attn_norm → (mamba | attention) → attn_post_norm → +residual → ffn_norm
/// → SWIGLU FFN → ffn_post_norm → +residual`; final RMS norm + lm_head.
///
/// The FFN's `LLM_FFN_SWIGLU + LLM_FFN_SEQ` (plamo2.cpp:164-168) is
/// `ggml_swiglu(up)` — the single-tensor GLU that splits each row in half.
/// The port's ggml crate has no single-tensor `swiglu` builder, so it is
/// composed as `swiglu_split` over the two half-views — bit-identical by
/// construction: the C kernel with src1 == NULL computes
/// `ggml_vec_swiglu_f32(nc = ne0/2, dst, src0_row, src0_row + nc)`
/// (ops.cpp:2992-2996), the same elements the views expose.
pub fn build_plamo2_forward(
    ctx: &mut Context,
    w: &Plamo2ModelWeights,
    p: &Plamo2Params,
    st: &RecurrentState,
    kv: &KvCache,
    inp: &DecodeInputs,
    _sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(4096);
    assert_eq!(st.n_layer(), n_layer, "RecurrentState per layer");

    let mut cur = ctx.get_rows(w.tok_embd, inp.tokens);
    cur = crate::adapter::lora_embd(ctx, w.tok_embd, cur, inp.tokens);

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let residual = cur;

        // pre_mixer_norm (plamo2.cpp:132)
        cur = build_norm_rms(ctx, cur, lw.attn_norm, p.norm_eps);

        cur = if p.is_recr[il] {
            build_plamo2_mamba_layer(ctx, &mut graph, p, lw, st, il, cur, t)
        } else {
            build_plamo2_attn_layer(ctx, &mut graph, p, lw, kv, inp, n_kv, cur, t, il)
        };

        // post_mixer_norm + residual (plamo2.cpp:150-157)
        cur = build_norm_rms(ctx, cur, lw.attn_post_norm, p.norm_eps);
        cur = ctx.add(cur, residual);
        let residual = cur;

        // pre-ffn norm (plamo2.cpp:159-161)
        cur = build_norm_rms(ctx, cur, lw.ffn_norm, p.norm_eps);

        // LLM_FFN_SWIGLU + LLM_FFN_SEQ, gate == NULL (plamo2.cpp:163-169):
        // up → ggml_swiglu → down
        let up = crate::adapter::lora_mm(ctx, lw.ffn_up, cur); // {2*n_ff, T}
        let n_ff = ctx.ne(up)[0] / 2;
        let nb1 = ctx.nb(up)[1] as usize;
        let first = ctx.view_2d(up, n_ff, t, nb1, 0);
        let second = ctx.view_2d(up, n_ff, t, nb1, (n_ff * 4) as usize);
        let act = ctx.swiglu_split(first, second);
        cur = crate::adapter::lora_mm(ctx, lw.ffn_down, act);

        // post ffn norm + residual (plamo2.cpp:171-177)
        cur = build_norm_rms(ctx, cur, lw.ffn_post_norm, p.norm_eps);
        cur = ctx.add(cur, residual);
    }

    // final norm + lm_head (plamo2.cpp:183-198)
    let cur = build_norm_rms(ctx, cur, w.output_norm, p.norm_eps);
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let logits = crate::adapter::lora_mm(ctx, w.output, cur);
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

/// plamo2.cpp:203-256 `build_plamo2_attn_layer` — fused qkv with per-width
/// segments (Q/K at qk_dim, V at v_dim), full-width q/k RMS norms, rope
/// after each norm, attention at kq_scale = 1/sqrt(n_embd_head_v).
#[allow(clippy::too_many_arguments)]
fn build_plamo2_attn_layer(
    ctx: &mut Context,
    graph: &mut Graph,
    p: &Plamo2Params,
    lw: &Plamo2LayerWeights,
    kv: &KvCache,
    inp: &DecodeInputs,
    n_kv: u32,
    cur: TensorId,
    t: i64,
    il: usize,
) -> TensorId {
    let a = &p.attn;

    // PLaMo-2 uses combined QKV tensor (plamo2.cpp:211)
    let qkv = crate::adapter::lora_mm(ctx, lw.wqkv.expect("plamo2 wqkv"), cur);

    // split QKV tensor into Q, K, V (plamo2.cpp:214-230) — Q/K at qk_dim,
    // V at v_dim (the segments follow n_embd_head_k for q and k)
    let n_embd_head_q = a.n_embd_head_k;
    let n_embd_head_k = a.n_embd_head_k;
    let n_embd_head_v = a.n_embd_head_v;
    let q_offset = 0i64;
    let k_offset = n_embd_head_q * a.n_head;
    let v_offset = k_offset + n_embd_head_k * a.n_head_kv;
    let nb1 = ctx.nb(qkv)[1] as usize;
    let mut q = ctx.view_3d(
        qkv,
        n_embd_head_q,
        a.n_head,
        t,
        (n_embd_head_q * 4) as usize,
        nb1,
        (q_offset * 4) as usize,
    );
    let mut k = ctx.view_3d(
        qkv,
        n_embd_head_k,
        a.n_head_kv,
        t,
        (n_embd_head_k * 4) as usize,
        nb1,
        (k_offset * 4) as usize,
    );
    let v = ctx.view_3d(
        qkv,
        n_embd_head_v,
        a.n_head_kv,
        t,
        (n_embd_head_v * 4) as usize,
        nb1,
        (v_offset * 4) as usize,
    );

    // build_norm(LLM_NORM_RMS) on the full-width q/k, rope after each
    // (plamo2.cpp:236-246)
    q = build_norm_rms(
        ctx,
        q,
        lw.attn_q_norm.expect("plamo2 attn_q_norm"),
        p.norm_eps,
    );
    q = ctx.rope_ext(
        q,
        inp.pos,
        None,
        a.n_rot as i32,
        a.rope_mode,
        a.n_ctx_orig,
        a.freq_base,
        a.freq_scale,
        a.ext_factor,
        a.attn_factor,
        a.beta_fast,
        a.beta_slow,
    );
    k = build_norm_rms(
        ctx,
        k,
        lw.attn_k_norm.expect("plamo2 attn_k_norm"),
        p.norm_eps,
    );
    k = ctx.rope_ext(
        k,
        inp.pos,
        None,
        a.n_rot as i32,
        a.rope_mode,
        a.n_ctx_orig,
        a.freq_base,
        a.freq_scale,
        a.ext_factor,
        a.attn_factor,
        a.beta_fast,
        a.beta_slow,
    );

    // build_attn(..., 1.0f / sqrtf(float(n_embd_head_v))) (plamo2.cpp:248-250)
    attn_kv_cached(
        ctx,
        graph,
        kv,
        il,
        a,
        inp,
        n_kv,
        q,
        k,
        v,
        1.0 / (n_embd_head_v as f32).sqrt(),
        0.0,
        None,
        None,
        Some(lw.wo.expect("plamo2 wo")),
        None,
    )
}

/// plamo2.cpp:258-426 `build_plamo2_mamba_layer` — the PLaMo-2 mixer (the
/// single-sequence K = 1 slice): per-head z/x split of the in_proj, a
/// bias-less causal 1D conv, the mamba1-style bcdt x-projection with RMS
/// norms on dt/B/C, the dt head projection, `ggml_ssm_scan`, `+ x*D`, the
/// swiglu gate with z and the out projection.
#[allow(clippy::too_many_arguments)]
fn build_plamo2_mamba_layer(
    ctx: &mut Context,
    graph: &mut Graph,
    p: &Plamo2Params,
    lw: &Plamo2LayerWeights,
    st: &RecurrentState,
    il: usize,
    cur: TensorId,
    t: i64,
) -> TensorId {
    let d_conv = p.d_conv;
    let d_inner = p.d_inner;
    let d_state = p.d_state;
    let n_heads = p.n_heads;
    let head_dim = d_inner / n_heads;
    let n_group = p.n_group;
    assert_eq!(
        n_group, 0,
        "plamo2: GGML_ASSERT(n_group == 0) (plamo2.cpp:281)"
    );
    let dt_dim = p.dt_dim;
    let one = ctx.new_i32(0); // ids {n_seqs = 1}: single cell → slot 0

    let conv_state = st.conv[il].expect("plamo2 recurrent conv state");
    let ssm_state = st.ssm[il].expect("plamo2 recurrent ssm state");

    // conv = build_rs(...) reshaped {d_conv-1, d_inner + 2*n_group*d_state,
    // n_seqs} (plamo2.cpp:286-287; n_group == 0)
    let conv = ctx.reshape_3d(conv_state, d_conv - 1, d_inner, 1);

    // in_proj: {n_embd, 2*d_inner} @ {n_embd, n_seq_tokens, n_seqs}
    // (plamo2.cpp:289-298) — the C reshapes cur to {n_embd, T, 1} first;
    // lora_mm on the 2-d cur produces the same {2*d_inner, T} rows
    let cur3 = ctx.reshape_3d(cur, p.n_embd, t, 1);
    let zx = crate::adapter::lora_mm(ctx, lw.ssm_in.expect("plamo2 ssm_in"), cur3);
    // permute + cont_4d to the per-head layout {head_dim*2, n_heads, T, 1}
    let zx = ctx.permute(zx, 0, 2, 1, 3);
    let zx = ctx.cont_4d(zx, head_dim * 2, n_heads, t, 1);
    let zx_nb = *ctx.nb(zx);

    // split into z and x — per head: [z(head_dim) | x(head_dim)]
    // (plamo2.cpp:300-310)
    let x = ctx.view_4d(
        zx,
        head_dim,
        n_heads,
        t,
        1,
        zx_nb[1] as usize,
        zx_nb[2] as usize,
        zx_nb[3] as usize,
        (head_dim * 4) as usize,
    );
    let x = ctx.cont_3d(x, head_dim * n_heads, t, 1);
    let z = ctx.view_4d(
        zx,
        head_dim,
        n_heads,
        t,
        1,
        zx_nb[1] as usize,
        zx_nb[2] as usize,
        zx_nb[3] as usize,
        0,
    );

    // conv1d (plamo2.cpp:312-335) — NO bias for plamo2's conv
    let x = {
        let x_t = ctx.transpose(x);
        let conv_x = ctx.concat(conv, x_t, 0);
        let cx_nb = *ctx.nb(conv_x);
        // copy last (d_conv - 1) columns back into the state cache (K = 1 →
        // slot 0; n_group == 0 so the row count is (d_conv-1) * d_inner)
        let last_conv = ctx.view_3d(
            conv_x,
            d_conv - 1,
            d_inner,
            1,
            cx_nb[1] as usize,
            cx_nb[2] as usize,
            t as usize * cx_nb[0] as usize,
        );
        let dst = ctx.view_1d(conv_state, (d_conv - 1) * d_inner, 0);
        let cpy = ctx.cpy(last_conv, dst);
        graph.build_forward(ctx, cpy);

        let x = ctx.ssm_conv(conv_x, lw.ssm_conv1d.expect("plamo2 ssm_conv1d"));
        ctx.silu(x)
    };

    // SSM (plamo2.cpp:337-419)
    // bcdt_proj: {d_inner, dt_rank + 2*d_state} @ x (plamo2.cpp:339-341)
    let x_bcdt = crate::adapter::lora_mm(ctx, lw.ssm_x.expect("plamo2 ssm_x"), x);
    let xb_nb = *ctx.nb(x_bcdt);

    // split into dt, B, C (plamo2.cpp:343-349)
    let b3 = ctx.view_3d(
        x_bcdt,
        d_state,
        t,
        1,
        xb_nb[1] as usize,
        xb_nb[2] as usize,
        0,
    );
    let c3 = ctx.view_3d(
        x_bcdt,
        d_state,
        t,
        1,
        xb_nb[1] as usize,
        xb_nb[2] as usize,
        (d_state * 4) as usize,
    );
    let dt3 = ctx.view_3d(
        x_bcdt,
        dt_dim,
        t,
        1,
        xb_nb[1] as usize,
        xb_nb[2] as usize,
        (2 * d_state * 4) as usize,
    );

    // Apply RMS norm to dt, B, C (PLaMo-2 specific) (plamo2.cpp:354-357)
    let b3 = build_norm_rms(
        ctx,
        b3,
        lw.ssm_b_norm.expect("plamo2 ssm_b_norm"),
        p.norm_eps,
    );
    let c3 = build_norm_rms(
        ctx,
        c3,
        lw.ssm_c_norm.expect("plamo2 ssm_c_norm"),
        p.norm_eps,
    );
    let dt3 = build_norm_rms(
        ctx,
        dt3,
        lw.ssm_dt_norm.expect("plamo2 ssm_dt_norm"),
        p.norm_eps,
    );

    // dt_proj + bias (plamo2.cpp:362-364)
    let dt = crate::adapter::lora_mm(ctx, lw.ssm_dt.expect("plamo2 ssm_dt"), dt3);
    let dt = ctx.add(dt, lw.ssm_dt_b.expect("plamo2 ssm_dt_b"));

    // A {1, n_heads} (plamo2.cpp:367)
    let a_t = ctx.reshape_2d(lw.ssm_a.expect("plamo2 ssm_a"), 1, n_heads);

    // the 4-d views of x/B/C for the scan (plamo2.cpp:370-374)
    let x4 = ctx.view_4d(
        x,
        head_dim,
        n_heads,
        t,
        1,
        (head_dim * 4) as usize,
        (head_dim * n_heads * 4) as usize,
        (head_dim * n_heads * t * 4) as usize,
        0,
    );
    let b_nb = *ctx.nb(b3);
    let c_nb = *ctx.nb(c3);
    let b4 = ctx.view_4d(
        b3,
        d_state,
        1,
        t,
        1,
        (d_state * b_nb[0] as i64) as usize,
        b_nb[1] as usize,
        b_nb[2] as usize,
        0,
    );
    let c4 = ctx.view_4d(
        c3,
        d_state,
        1,
        t,
        1,
        (d_state * c_nb[0] as i64) as usize,
        c_nb[1] as usize,
        c_nb[2] as usize,
        0,
    );

    // ggml_ssm_scan with the states (K = 1) (plamo2.cpp:379-388)
    let ssm_view = ctx.reshape_4d(ssm_state, d_state, head_dim, n_heads, 1);
    let y_ssm = ctx.ssm_scan(ssm_view, x4, dt, a_t, b4, c4, one, 1);

    // store last states (plamo2.cpp:391-398; slot 0 of the single cell)
    {
        let n = n_heads * head_dim * d_state;
        let src = ctx.view_1d(y_ssm, n, (n_heads * head_dim * t * 4) as usize);
        let dst = ctx.view_1d(ssm_state, n, 0);
        let cpy = ctx.cpy(src, dst);
        graph.build_forward(ctx, cpy);
    }

    // y view (plamo2.cpp:401-404)
    let y = ctx.view_4d(
        y_ssm,
        head_dim,
        n_heads,
        t,
        1,
        (head_dim * 4) as usize,
        (head_dim * n_heads * 4) as usize,
        (head_dim * n_heads * t * 4) as usize,
        0,
    );

    // Add D parameter and apply gating with z (plamo2.cpp:406-413)
    let d_t = ctx.reshape_2d(lw.ssm_d.expect("plamo2 ssm_d"), 1, n_heads);
    let xd = ctx.mul(x4, d_t);
    let y = ctx.add(y, xd);
    // z must be contiguous for the GLU (ggml_glu_impl)
    let zc = ctx.cont(z);
    let y = ctx.swiglu_split(zc, y);

    // out_proj (plamo2.cpp:415-418): collapse dims 0/1 then {d_inner, n_embd}
    let y_nb = *ctx.nb(y);
    let y3 = ctx.view_3d(
        y,
        head_dim * n_heads,
        t,
        1,
        y_nb[2] as usize,
        y_nb[3] as usize,
        0,
    );
    let cur = crate::adapter::lora_mm(ctx, lw.ssm_out.expect("plamo2 ssm_out"), y3);

    // {n_embd, n_seq_tokens, n_seqs} => {n_embd, n_tokens} (plamo2.cpp:421)
    ctx.reshape_2d(cur, p.n_embd, t)
}

/// verify against src/models/deepseek32.cpp:162-484 llama_model_deepseek32::graph::graph.
/// Reuses [`Deepseek2ModelWeights`] (the deepseek32 loader fills the same
/// tensors plus the indexer five); `kv` must be the `KvCache::new_dsa` pair —
/// `kv.lid` holds the indexer key rows and `kv.lid_step` the per-step inputs
/// (`row_idx` / F16 `kq_mask` / the Hadamard `k_rot`).
///
/// Not ported (same treatment as deepseek2): `inp_out_ids` pruning (:405-408),
/// `build_cvec` (:458), the MTP graph class (:486-726) and the
/// `!cparams.fused_lid` unfused indexer path (:283-317) — the reference's
/// default has `fused_lid = true` (llama-context.cpp:238-239), so the port
/// implements exactly that branch via the `LightningIndexer` op.
#[allow(clippy::too_many_arguments)]
pub fn build_deepseek32_forward(
    ctx: &mut Context,
    w: &Deepseek2ModelWeights,
    p: &Deepseek32Params,
    kv: &KvCache,
    inp: &DecodeInputs,
    _sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let ap = &p.ds2.attn;

    // deepseek32.cpp:164-194 — identical pre-scaled kq_scale to deepseek2
    let is_mla = true; // GGML_ASSERT(is_mla) at :165
    let n_embd_head_k = p.ds2.n_embd_head_k_mla;
    let n_embd_head_qk_rope = ap.n_rot;
    let n_embd_head_qk_nope = n_embd_head_k - n_embd_head_qk_rope;
    let kv_lora_rank = p.ds2.kv_lora_rank;

    // the indexer head layout is [rope | nope] (:179-180)
    assert!(
        ap.n_rot <= p.indexer_head_size,
        "deepseek32: n_rot <= indexer_head_size"
    );

    assert!(ap.ext_factor >= 0.0);
    let attn_factor_org = ap.attn_factor * (1.0 + 0.1 * (1.0f32 / ap.freq_scale).ln());
    let mscale =
        attn_factor_org * (1.0 + 0.1 * p.ds2.rope_yarn_log_mul * (1.0f32 / ap.freq_scale).ln());
    let kq_scale = 1.0 * mscale * mscale / (n_embd_head_k as f32).sqrt();

    assert!(p.ds2.f_attn_temp_scale == 0.0);
    let _ = is_mla;

    let lid = kv.lid.as_ref().expect("deepseek32 needs the dsa lid cache");
    let lid_step = kv
        .lid_step
        .expect("deepseek32 needs the lid step inputs (KvCache::lid_step)");
    let n_kv_lid = kv.n_kv_lid();

    let mut graph = Graph::new(1024);
    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_sa = inp_l;
        let mut cur = build_norm_rms(ctx, inp_l, lw.attn_norm, ap.norm_eps);

        // self_attention (deepseek32.cpp:217-402)
        let n_head = ap.n_head;
        let n_indexer_head = p.indexer_n_head;
        let n_embd_indexer_head = p.indexer_head_size;

        let mut qr = ctx.mul_mat(lw.wq_a.expect("wq_a"), cur);
        qr = build_norm_rms(
            ctx,
            qr,
            lw.attn_q_a_norm.expect("attn_q_a_norm"),
            ap.norm_eps,
        );

        // lightning indexer (deepseek32.cpp:226-323)
        let top_k = {
            let mut indexer_q = ctx.mul_mat(lw.indexer_attn_q_b.expect("indexer_attn_q_b"), qr);
            // {n_embd_indexer_head, n_indexer_head, n_tokens} (:232-235, NEOX)
            indexer_q = ctx.reshape_3d(indexer_q, n_embd_indexer_head, n_indexer_head, t);
            indexer_q = ctx.rope_ext(
                indexer_q,
                inp.pos,
                None,
                ap.n_rot as i32,
                2, /* NEOX */
                ap.n_ctx_orig,
                ap.freq_base,
                ap.freq_scale,
                ap.ext_factor,
                ap.attn_factor,
                ap.beta_fast,
                ap.beta_slow,
            );

            let mut indexer_k = ctx.mul_mat(lw.indexer_attn_k.expect("indexer_attn_k"), cur);
            // build_norm LLM_NORM with weight+bias (:241, eps = f_norm_eps)
            indexer_k = build_norm_layer(
                ctx,
                indexer_k,
                lw.indexer_k_norm.expect("indexer_k_norm"),
                lw.indexer_k_norm_b,
                p.f_norm_eps,
            );
            // {n_embd_indexer_head, 1, n_tokens} (:245-248, NEOX)
            indexer_k = ctx.reshape_3d(indexer_k, n_embd_indexer_head, 1, t);
            indexer_k = ctx.rope_ext(
                indexer_k,
                inp.pos,
                None,
                ap.n_rot as i32,
                2, /* NEOX */
                ap.n_ctx_orig,
                ap.freq_base,
                ap.freq_scale,
                ap.ext_factor,
                ap.attn_factor,
                ap.beta_fast,
                ap.beta_slow,
            );

            // perform Hadamard transform on indexer q and k (:252-255)
            indexer_q = ctx.mul_mat(lid_step.k_rot, indexer_q);
            indexer_k = ctx.mul_mat(lid_step.k_rot, indexer_k);

            // store indexer keys to KV cache (:258-260)
            let nb2 = ctx.nb(indexer_k)[2] as usize;
            let k_rows = ctx.view_2d(indexer_k, n_embd_indexer_head, t, nb2, 0);
            let k_dst = ctx.set_rows(lid.layers[il], k_rows, lid_step.row_idx);
            graph.build_forward(ctx, k_dst);

            // prepare indexer weights (:263-264)
            let mut indexer_weights = ctx.mul_mat(lw.indexer_proj.expect("indexer_proj"), cur);

            // get cached indexer keys (:267)
            let indexer_k = kv.get_k_lid(ctx, il, n_kv_lid);

            // pre-scale weights to avoid scaling operations on huge
            // indexer_score tensor (:275)
            indexer_weights = ctx.scale(
                indexer_weights,
                1.0 / (n_embd_indexer_head as f32 * n_indexer_head as f32).sqrt(),
            );

            // fused lightning indexer (:279-282) — cparams.fused_lid default
            // true (llama-context.cpp:238); the F16 lid mask is the one
            // `lid_step.kq_mask` carries
            let indexer_score =
                ctx.lightning_indexer(indexer_q, indexer_k, indexer_weights, lid_step.kq_mask);

            // get indices of top k indexer scores (:319-322). This is the C's
            // dedicated GGML_OP_TOP_K (std::partial_sort heap-select + a
            // [0]<->[1] swap, ops.cpp:8550-8604) — its *tie* behavior decides
            // which rows the DSA mask unmasks, so the port reproduces the
            // exact heap mechanics (compute.rs forward_top_k).
            let n_top_k = (ctx.ne(indexer_score)[0]).min(p.indexer_top_k);
            let top_k = ctx.top_k(indexer_score, n_top_k as i32);
            ctx.cont(top_k)
        };

        let q = ctx.mul_mat(lw.wq_b.expect("wq_b"), qr);

        // split into {n_embd_head_qk_nope, n_head, n_tokens} (:329-332)
        let (qnb1, qnb2) = {
            let rs = ctx.ty(q).row_size(n_embd_head_k as usize);
            (rs, rs * n_head as usize)
        };
        let q_nope = ctx.view_3d(q, n_embd_head_qk_nope, n_head, t, qnb1, qnb2, 0);
        let q_pe = ctx.view_3d(
            q,
            n_embd_head_qk_rope,
            n_head,
            t,
            qnb1,
            qnb2,
            ctx.ty(q).row_size(n_embd_head_qk_nope as usize),
        );

        let kv_cmpr_pe = ctx.mul_mat(lw.wkv_a_mqa.expect("wkv_a_mqa"), cur);
        let kv_cmpr = {
            let rs = ctx
                .ty(kv_cmpr_pe)
                .row_size((kv_lora_rank + n_embd_head_qk_rope) as usize);
            ctx.view_2d(kv_cmpr_pe, kv_lora_rank, t, rs, 0)
        };
        let k_pe = {
            let rs = ctx
                .ty(kv_cmpr_pe)
                .row_size((kv_lora_rank + n_embd_head_qk_rope) as usize);
            ctx.view_3d(
                kv_cmpr_pe,
                n_embd_head_qk_rope,
                1,
                t,
                rs,
                rs,
                ctx.ty(kv_cmpr_pe).row_size(kv_lora_rank as usize),
            )
        };
        let q_pe = ctx.rope_ext(
            q_pe,
            inp.pos,
            None,
            ap.n_rot as i32,
            ap.rope_mode,
            ap.n_ctx_orig,
            ap.freq_base,
            ap.freq_scale,
            ap.ext_factor,
            ap.attn_factor,
            ap.beta_fast,
            ap.beta_slow,
        );
        let k_pe = ctx.rope_ext(
            k_pe,
            inp.pos,
            None,
            ap.n_rot as i32,
            ap.rope_mode,
            ap.n_ctx_orig,
            ap.freq_base,
            ap.freq_scale,
            ap.ext_factor,
            ap.attn_factor,
            ap.beta_fast,
            ap.beta_slow,
        );
        let kv_cmpr = build_norm_rms(
            ctx,
            kv_cmpr,
            lw.attn_kv_a_norm.expect("attn_kv_a_norm"),
            ap.norm_eps,
        );

        // MLA attention (deepseek32.cpp:367-401) — same absorbed-MQA flow as
        // deepseek2 with the top_k-composed mask
        let q_nope = ctx.permute(q_nope, 0, 2, 1, 3);
        let q_nope_absorbed = ctx.mul_mat(lw.wk_b.expect("wk_b"), q_nope);
        let q_nope_absorbed = ctx.permute(q_nope_absorbed, 0, 2, 1, 3);
        let qcur = ctx.concat(q_nope_absorbed, q_pe, 0);
        let kv_cmpr3 = ctx.reshape_3d(kv_cmpr, kv_lora_rank, 1, t);
        let kcur = ctx.concat(kv_cmpr3, k_pe, 0);

        cur = attn_k_cached_mla(
            ctx,
            &mut graph,
            kv,
            il,
            ap,
            inp,
            n_kv,
            qcur,
            kcur,
            kv_cmpr3,
            kq_scale,
            lw.wv_b.expect("wv_b"),
            Some(lw.wo),
            Some(top_k),
        );

        // FFN body — identical to deepseek2 (deepseek32.cpp:405-462)
        let ffn_inp = ctx.add(cur, inp_sa);
        let mut cur = build_norm_rms(ctx, ffn_inp, lw.ffn_norm, ap.norm_eps);

        if (il as u32) < p.ds2.n_layer_dense_lead {
            cur = build_ffn_silu_par(
                ctx,
                cur,
                lw.ffn_gate.expect("ffn_gate (dense-lead layer)"),
                None,
                lw.ffn_up.expect("ffn_up (dense-lead layer)"),
                None,
                lw.ffn_down.expect("ffn_down (dense-lead layer)"),
                None,
            );
        } else {
            let moe_out = build_moe_ffn_deepseek2(ctx, &mut graph, cur, lw, &p.ds2);
            let ffn_shexp = build_ffn_silu_par(
                ctx,
                cur,
                lw.ffn_gate_shexp.expect("ffn_gate_shexp"),
                None,
                lw.ffn_up_shexp.expect("ffn_up_shexp"),
                None,
                lw.ffn_down_shexp.expect("ffn_down_shexp"),
                None,
            );
            cur = ctx.add(moe_out, ffn_shexp);
        }
        inp_l = ctx.add(cur, ffn_inp);
    }
    let cur = inp_l;
    let cur = build_norm_rms(ctx, cur, w.output_norm, ap.norm_eps);
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let logits = ctx.mul_mat(w.output, cur);

    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

// ===========================================================================
// arch batch 7 (deepseek4): hyper-connections + the compressed DSV4 cache —
// verify against src/models/deepseek4.cpp. The cparams defaults make the reference run
// the FUSED hyper-connection ops (`fused_dsv4_hc_pre/comb/post = true`,
// llama-context.cpp:240-242) and the fused lightning indexer
// (`fused_lid = true`, :237), so the port wires the fused builders; the
// unfused Sinkhorn fallback (:317-352) is not ported (see the notes at
// build_deepseek4_forward). The MTP graph (deepseek4.cpp:1363-1502) is not
// ported either (speculative-only, like deepseek2/32's).
// ===========================================================================

/// deepseek4 per-layer weights (deepseek4.cpp:109-181 — the trunk set)
pub struct Deepseek4LayerWeights {
    pub attn_norm: TensorId,
    pub attn_sinks: TensorId,
    pub wq_a: TensorId,
    pub attn_q_a_norm: TensorId,
    pub wq_b: TensorId,
    /// `attn_kv` — the single-head key/value projection {n_embd, n_embd_head}
    pub wkv: TensorId,
    pub attn_kv_norm: TensorId,
    pub wo_a: TensorId,
    pub wo_b: TensorId,

    pub hc_attn_fn: TensorId,
    pub hc_attn_base: TensorId,
    pub hc_attn_scale: TensorId,
    pub hc_ffn_fn: TensorId,
    pub hc_ffn_base: TensorId,
    pub hc_ffn_scale: TensorId,

    // per-ratio compressors (deepseek4.cpp:132-154); all None at ratio 0
    pub attn_comp_wkv: Option<TensorId>,
    pub attn_comp_wgate: Option<TensorId>,
    pub attn_comp_ape: Option<TensorId>,
    pub attn_comp_norm: Option<TensorId>,
    pub indexer_proj: Option<TensorId>,
    pub indexer_attn_q_b: Option<TensorId>,
    pub indexer_comp_wkv: Option<TensorId>,
    pub indexer_comp_wgate: Option<TensorId>,
    pub indexer_comp_ape: Option<TensorId>,
    pub indexer_comp_norm: Option<TensorId>,

    pub ffn_norm: TensorId,
    pub ffn_gate_inp: TensorId,
    pub ffn_gate_tid2eid: Option<TensorId>,
    pub ffn_exp_probs_b: Option<TensorId>,
    pub ffn_exp_probs_b_vl: Option<TensorId>,
    pub ffn_gate_exps: TensorId,
    pub ffn_down_exps: TensorId,
    pub ffn_up_exps: TensorId,
    pub ffn_gate_shexp: TensorId,
    pub ffn_down_shexp: TensorId,
    pub ffn_up_shexp: TensorId,
}

pub struct Deepseek4ModelWeights {
    pub tok_embd: TensorId,
    pub output_norm: TensorId,
    pub output: TensorId,
    pub hc_head_fn: TensorId,
    pub hc_head_base: TensorId,
    pub hc_head_scale: TensorId,
    pub layers: Vec<Deepseek4LayerWeights>,
}

/// deepseek4 hyperparameters beyond [`AttnParams`]
#[derive(Clone)]
pub struct Deepseek4Params {
    pub attn: AttnParams,
    pub n_embd: i64,
    /// hparams.dsv4_hc_mult (asserted == 4, deepseek4.cpp:367)
    pub hc_mult: i64,
    pub hc_eps: f32,
    pub hc_sinkhorn_iters: i32,
    pub o_group_count: i64,
    pub o_lora_rank: i64,
    pub compress_rope_base: f32,
    pub indexer_n_head: i64,
    pub indexer_head_size: i64,
    pub indexer_top_k: i64,
    pub n_expert: i64,
    pub n_expert_used: i64,
    pub expert_weights_norm: bool,
    pub expert_weights_scale: f32,
    /// hparams.swiglu_clamp_exp / shexp (per layer)
    pub swiglu_clamp_exp: Vec<f32>,
    pub swiglu_clamp_shexp: Vec<f32>,
    /// hparams.dsv4_compress_ratios
    pub ratios: Vec<u32>,
    pub hash_layer_count: u32,
    /// hparams.n_swa — the raw-SWA window of build_csa_lid_attention's n_kv_max
    pub n_swa: u32,
    /// f_attn_temp_scale must be 0 (build_inp_attn_scale not ported, same as
    /// deepseek2)
    pub f_attn_temp_scale: f32,
}

/// `dsv4_rope_attn_factor` (deepseek4.cpp:11-17): the compress-rope YaRN
/// attn factor — 1.0 without extrapolation, else 1/(1 + 0.1*ln(1/freq_scale)).
fn dsv4_rope_attn_factor(freq_scale: f32, ext_factor: f32) -> f32 {
    if ext_factor == 0.0 {
        return 1.0;
    }
    1.0 / (1.0 + 0.1 * (1.0f32 / freq_scale).ln())
}

/// the local `dsv4_elem_offset`/`dsv4_view_1d`/`dsv4_view_2d` helpers
/// (deepseek4.cpp:192-207): byte offsets in whole rows of `t`'s type
fn dsv4_elem_offset(ctx: &Context, t: TensorId, i0: i64) -> usize {
    ctx.ty(t).row_size(i0 as usize)
}

/// `dsv4_append_zero_row` (deepseek4.cpp:209-215): a zero (or -inf) copy of
/// row 0 appended after `t` — the first overlap block's missing previous half.
fn dsv4_append_zero_row(ctx: &mut Context, t: TensorId, neg_inf: bool) -> TensorId {
    let ne0 = ctx.ne(t)[0];
    let row = ctx.view_1d(t, ne0, 0);
    let row = if neg_inf {
        ctx.scale_bias(row, 0.0, f32::NEG_INFINITY)
    } else {
        ctx.scale(row, 0.0)
    };
    let row = ctx.reshape_2d(row, ne0, 1);
    ctx.concat(t, row, 1)
}

/// `build_hc_pre(x, weights, il)` — the fused stream mix
/// (deepseek4.cpp:290-315; the fused branch is the cparams default).
fn dsv4_hc_pre_stream(ctx: &mut Context, x: TensorId, weights: TensorId) -> TensorId {
    ctx.dsv4_hc_pre(x, weights)
}

/// `llama_mul_mat_hadamard` (llama-impl.h:57-73): reshape to n-wide rows,
/// mul_mat by the (involutary) Hadamard, reshape back.
fn mul_mat_hadamard(ctx: &mut Context, cur: TensorId, rot: TensorId) -> TensorId {
    let n = ctx.ne(rot)[0];
    let nelem = ctx.ne(cur).iter().product::<i64>();
    let res = if !ggml::ops::is_contiguous_ctx(ctx, cur) {
        ctx.cont_2d(cur, n, nelem / n)
    } else {
        ctx.reshape_2d(cur, n, nelem / n)
    };
    let res = ctx.mul_mat(rot, res);
    // llama-impl.h:70 — ggml_mul_mat_set_hint(GGML_HINT_SRC0_IS_HADAMARD):
    // the CPU kernel computes the fast Walsh-Hadamard transform, whose
    // accumulation order differs from the gemm dot
    ctx.mul_mat_set_hint_hadamard(res);
    let (ne0, ne1, ne2, ne3) = {
        let ne = *ctx.ne(cur);
        (ne[0], ne[1], ne[2], ne[3])
    };
    ctx.reshape_4d(res, ne0, ne1, ne2, ne3)
}

/// `dsv4_hc_affine` (deepseek4.cpp:280-288): x*scale + base
fn dsv4_hc_affine(ctx: &mut Context, x: TensorId, scale: TensorId, base: TensorId) -> TensorId {
    let x = ctx.mul(x, scale);
    ctx.add(x, base)
}

/// `llama_model_deepseek4::graph::build_hc_pre(x, hc_fn, hc_scale, hc_base,
/// &post, &comb, il)` (deepseek4.cpp:354-410) — the layer's hyper-connection
/// pre gate / post gate / comb matrix. Returns (cur, post, comb).
fn build_hc_pre_dsv4(
    ctx: &mut Context,
    x: TensorId,
    hc_fn: TensorId,
    hc_scale: TensorId,
    hc_base: TensorId,
    p: &Deepseek4Params,
    il: i32,
) -> (TensorId, TensorId, TensorId) {
    let hc = p.hc_mult;
    let hc_dim = hc * p.n_embd;
    let nt = ctx.ne(x)[2];
    let eps = p.hc_eps;

    assert_eq!(hc, 4, "deepseek4: hc == 4 (deepseek4.cpp:367)");
    assert_eq!(ctx.ne(hc_fn)[1], (2 + hc) * hc);

    let flat = ctx.reshape_2d(x, hc_dim, nt);
    let flat_norm = ctx.rms_norm(flat, p.attn.norm_eps);
    let mixes = ctx.mul_mat(hc_fn, flat_norm);
    ctx.set_name(mixes, &format!("hc_mixes-{il}"));

    // dsv4_view_1d / dsv4_view_2d (deepseek4.cpp:375-387)
    let scale_pre = ctx.view_1d(hc_scale, 1, dsv4_elem_offset(ctx, hc_scale, 0));
    let scale_post = ctx.view_1d(hc_scale, 1, dsv4_elem_offset(ctx, hc_scale, 1));

    let base_pre = ctx.view_1d(hc_base, hc, dsv4_elem_offset(ctx, hc_base, 0));
    let base_post = ctx.view_1d(hc_base, hc, dsv4_elem_offset(ctx, hc_base, hc));

    let (nb1, off_pre) = (ctx.nb(mixes)[1] as usize, 0usize);
    let pre = ctx.view_2d(mixes, hc, nt, nb1, off_pre);
    let pre = dsv4_hc_affine(ctx, pre, scale_pre, base_pre);
    let pre = ctx.sigmoid(pre);
    let pre = ctx.scale_bias(pre, 1.0, eps);
    ctx.set_name(pre, &format!("hc_pre-{il}"));

    let off_post = dsv4_elem_offset(ctx, mixes, hc);
    let post = ctx.view_2d(mixes, hc, nt, nb1, off_post);
    let post = dsv4_hc_affine(ctx, post, scale_post, base_post);
    let post = ctx.sigmoid(post);
    let post = ctx.scale(post, 2.0);
    ctx.set_name(post, &format!("hc_post-{il}"));

    // the fused comb (deepseek4.cpp:393-396 — cparams.fused_dsv4_hc_comb)
    let comb = ctx.dsv4_hc_comb(mixes, hc_scale, hc_base, eps, p.hc_sinkhorn_iters);
    ctx.set_name(comb, &format!("hc_comb-{il}"));

    let result = dsv4_hc_pre_stream(ctx, x, pre);
    (result, post, comb)
}

/// `build_hc_post` (deepseek4.cpp:412-447; fused branch :421-424)
fn build_hc_post_dsv4(
    ctx: &mut Context,
    x: TensorId,
    residual: TensorId,
    post: TensorId,
    comb: TensorId,
) -> TensorId {
    ctx.dsv4_hc_post(x, residual, post, Some(comb))
}

/// `build_hc_head` (deepseek4.cpp:449-469) — the model-level output mixer
fn build_hc_head_dsv4(
    ctx: &mut Context,
    x: TensorId,
    hc_fn: TensorId,
    hc_scale: TensorId,
    hc_base: TensorId,
    p: &Deepseek4Params,
) -> TensorId {
    let il = -1i32;
    let hc = p.hc_mult;
    let hc_dim = hc * p.n_embd;
    let nt = ctx.ne(x)[2];

    let flat = ctx.reshape_2d(x, hc_dim, nt);
    let flat_norm = ctx.rms_norm(flat, p.attn.norm_eps);
    let mixes = ctx.mul_mat(hc_fn, flat_norm);
    ctx.set_name(mixes, "hc_head_mixes");

    let pre = dsv4_hc_affine(ctx, mixes, hc_scale, hc_base);
    let pre = ctx.sigmoid(pre);
    let pre = ctx.scale_bias(pre, 1.0, p.hc_eps);
    ctx.set_name(pre, "hc_head_pre");

    dsv4_hc_pre_stream(ctx, x, pre)
}

/// `build_overlap_compressed_kv_from_state` (deepseek4.cpp:518-589) — the
/// ratio-4 (CSA and lid) compressor: gather two overlapping windows per block
/// (prev = column-half 0 of the gathered rows, cur = half 1), softmax-pool
/// them into one n_embd_head row, RMS-norm and rope at the block's
/// source_start position.
#[allow(clippy::too_many_arguments)]
fn build_overlap_compressed_kv_from_state(
    ctx: &mut Context,
    kv_state: TensorId,
    score_state: TensorId,
    state_read_idxs: TensorId,
    comp_pos: TensorId,
    norm: TensorId,
    ratio: i64,
    n_embd_head: i64,
    p: &Deepseek4Params,
) -> TensorId {
    let ap = &p.attn;
    let n_embd_head_rope = ap.n_rot;
    let n_embd_head_nope = n_embd_head - n_embd_head_rope;
    let n_blocks = ctx.ne(comp_pos)[0];

    assert!(n_blocks > 0);
    assert_eq!(ctx.ne(state_read_idxs)[0], 2 * ratio * n_blocks);
    assert!(n_embd_head >= n_embd_head_rope);

    // deepseek4.cpp:539-540 — the graph-appended zero/-inf row the first
    // block's previous half gathers from
    let kv_state = dsv4_append_zero_row(ctx, kv_state, false);
    let score_state = dsv4_append_zero_row(ctx, score_state, true);

    let n_read = ratio * n_blocks;

    let kv_rows = ctx.get_rows(kv_state, state_read_idxs);
    let score_rows = ctx.get_rows(score_state, state_read_idxs);

    // the two halves: rows [0, n_read) column-half 0 (prev window) and rows
    // [n_read, 2*n_read) column-half 1 (cur window) — deepseek4.cpp:547-565
    let kv_rows_ty = ctx.ty(kv_rows);
    let rs_head = kv_rows_ty.row_size(n_embd_head as usize);
    let nb1 = ctx.nb(kv_rows)[1] as usize;
    let kv_prev_v = ctx.view_2d(kv_rows, n_embd_head, n_read, nb1, 0);
    let kv_prev = ctx.cont(kv_prev_v);
    let kv_prev = ctx.reshape_3d(kv_prev, n_embd_head, ratio, n_blocks);
    let score_prev_v = ctx.view_2d(score_rows, n_embd_head, n_read, nb1, 0);
    let score_prev = ctx.cont(score_prev_v);
    let score_prev = ctx.reshape_3d(score_prev, n_embd_head, ratio, n_blocks);

    let cur_off = (n_read * nb1 as i64) as usize + rs_head;
    let kv_cur_v = ctx.view_2d(kv_rows, n_embd_head, n_read, nb1, cur_off);
    let kv_cur = ctx.cont(kv_cur_v);
    let kv_cur = ctx.reshape_3d(kv_cur, n_embd_head, ratio, n_blocks);
    let score_cur_v = ctx.view_2d(score_rows, n_embd_head, n_read, nb1, cur_off);
    let score_cur = ctx.cont(score_cur_v);
    let score_cur = ctx.reshape_3d(score_cur, n_embd_head, ratio, n_blocks);

    let values = ctx.concat(kv_prev, kv_cur, 1);
    let scores = ctx.concat(score_prev, score_cur, 1);

    let values_p = ctx.permute(values, 1, 0, 2, 3);
    let values = ctx.cont(values_p);
    let scores_p = ctx.permute(scores, 1, 0, 2, 3);
    let scores = ctx.cont(scores_p);

    let weights = ctx.soft_max(scores);
    let mut comp = ctx.mul(values, weights);
    comp = ctx.sum_rows(comp);
    let comp_p = ctx.permute(comp, 1, 0, 2, 3);
    comp = ctx.cont(comp_p);

    // build_norm LLM_NORM_RMS (deepseek4.cpp:506/:579)
    comp = build_norm_rms(ctx, comp, norm, ap.norm_eps);

    // the compress rope (deepseek4.cpp:509-513/:582-586)
    let attn_factor = dsv4_rope_attn_factor(ap.freq_scale, ap.ext_factor);
    comp = ctx.rope_ext(
        comp,
        comp_pos,
        None,
        n_embd_head_rope as i32,
        ap.rope_mode,
        ap.n_ctx_orig,
        p.compress_rope_base,
        ap.freq_scale,
        ap.ext_factor,
        attn_factor,
        ap.beta_fast,
        ap.beta_slow,
    );
    ctx.rope_set_offset(comp, n_embd_head_nope as i32)
}

/// `build_hca_compressed_kv_from_state` (deepseek4.cpp:471-516) — the
/// ratio-128 compressor: one non-overlapping window per block.
#[allow(clippy::too_many_arguments)]
fn build_hca_compressed_kv_from_state(
    ctx: &mut Context,
    kv_state: TensorId,
    score_state: TensorId,
    state_read_idxs: TensorId,
    comp_pos: TensorId,
    norm: TensorId,
    n_embd_head: i64,
    p: &Deepseek4Params,
) -> TensorId {
    let ap = &p.attn;
    let n_embd_head_rope = ap.n_rot;
    let n_embd_head_nope = n_embd_head - n_embd_head_rope;
    let n_blocks = ctx.ne(comp_pos)[0];
    let ratio = 128i64;

    assert!(n_blocks > 0);
    assert_eq!(ctx.ne(state_read_idxs)[0], ratio * n_blocks);
    assert!(n_embd_head >= n_embd_head_rope);

    let kv = ctx.get_rows(kv_state, state_read_idxs);
    let kv = ctx.reshape_3d(kv, n_embd_head, ratio, n_blocks);
    let score = ctx.get_rows(score_state, state_read_idxs);
    let score = ctx.reshape_3d(score, n_embd_head, ratio, n_blocks);

    let values_p = ctx.permute(kv, 1, 0, 2, 3);
    let values = ctx.cont(values_p);
    let scores_p = ctx.permute(score, 1, 0, 2, 3);
    let scores = ctx.cont(scores_p);

    let weights = ctx.soft_max(scores);
    let mut comp = ctx.mul(values, weights);
    comp = ctx.sum_rows(comp);
    let comp_p = ctx.permute(comp, 1, 0, 2, 3);
    comp = ctx.cont(comp_p);

    comp = build_norm_rms(ctx, comp, norm, ap.norm_eps);

    let attn_factor = dsv4_rope_attn_factor(ap.freq_scale, ap.ext_factor);
    comp = ctx.rope_ext(
        comp,
        comp_pos,
        None,
        n_embd_head_rope as i32,
        ap.rope_mode,
        ap.n_ctx_orig,
        p.compress_rope_base,
        ap.freq_scale,
        ap.ext_factor,
        attn_factor,
        ap.beta_fast,
        ap.beta_slow,
    );
    ctx.rope_set_offset(comp, n_embd_head_nope as i32)
}

/// `build_lid_top_k` (deepseek4.cpp:591-677) — the lightning indexer over the
/// lid comp cache; returns the top-k row indices [n_top_k, T].
#[allow(clippy::too_many_arguments)]
fn build_lid_top_k_dsv4(
    ctx: &mut Context,
    lw: &Deepseek4LayerWeights,
    dsv4: &crate::kv_cache::Dsv4Cache,
    step: &crate::kv_cache::Dsv4Step,
    qr: TensorId,
    cur: TensorId,
    inp_pos: TensorId,
    p: &Deepseek4Params,
    il: usize,
) -> TensorId {
    let ap = &p.attn;
    let n_embd_indexer_head = p.indexer_head_size;
    let n_embd_indexer_head_nope = n_embd_indexer_head - ap.n_rot;
    let n_indexer_head = p.indexer_n_head;
    let nt = ctx.ne(cur)[1];
    let lid = &step.lid;

    let attn_factor = dsv4_rope_attn_factor(ap.freq_scale, ap.ext_factor);

    let mut indexer_q =
        crate::adapter::lora_mm(ctx, lw.indexer_attn_q_b.expect("indexer_attn_q_b"), qr);
    indexer_q = ctx.reshape_3d(indexer_q, n_embd_indexer_head, n_indexer_head, nt);
    indexer_q = ctx.rope_ext(
        indexer_q,
        inp_pos,
        None,
        ap.n_rot as i32,
        ap.rope_mode,
        ap.n_ctx_orig,
        p.compress_rope_base,
        ap.freq_scale,
        ap.ext_factor,
        attn_factor,
        ap.beta_fast,
        ap.beta_slow,
    );
    indexer_q = ctx.rope_set_offset(indexer_q, n_embd_indexer_head_nope as i32);

    indexer_q = mul_mat_hadamard(ctx, indexer_q, lid.k_rot.expect("lid k_rot"));

    let mut indexer_weights =
        crate::adapter::lora_mm(ctx, lw.indexer_proj.expect("indexer_proj"), cur);
    indexer_weights = ctx.scale(
        indexer_weights,
        1.0 / (n_embd_indexer_head as f32 * n_indexer_head as f32).sqrt(),
    );

    // the cached indexer keys, viewed to the lid mask width (:632-635)
    let mut indexer_k = dsv4.lid.get_k(ctx, il, step.plan_lid().n_kv);
    let n_lid = ctx.ne(lid.kq_mask)[0];
    assert!(n_lid > 0);
    {
        let kne = *ctx.ne(indexer_k);
        let knb = *ctx.nb(indexer_k);
        indexer_k = ctx.view_4d(
            indexer_k,
            kne[0],
            kne[1],
            n_lid as i64,
            kne[3],
            knb[1] as usize,
            knb[2] as usize,
            knb[3] as usize,
            0,
        );
    }

    // the fused lightning indexer (deepseek4.cpp:647-649 — cparams.fused_lid)
    let indexer_score = ctx.lightning_indexer(indexer_q, indexer_k, indexer_weights, lid.kq_mask);

    // deepseek4.cpp:672-674 — top_k over the masked score
    let n_top_k = (ctx.ne(indexer_score)[0]).min(p.indexer_top_k);
    let top_k = ctx.top_k(indexer_score, n_top_k as i32);
    ctx.cont(top_k)
}

/// `build_top_k_mask` (deepseek4.cpp:679-706) — zero the top-k rows of an
/// all--inf mask, then add the visible mask (intersection semantics).
fn build_top_k_mask_dsv4(
    ctx: &mut Context,
    kq_mask: TensorId,
    top_k: TensorId,
    use_fa: bool,
) -> TensorId {
    let kq_mask_all = ctx.fill(kq_mask, f32::NEG_INFINITY);
    // [n_kv, T, 1, 1] -> [1, n_kv, T, 1] (:688-689)
    let mne = *ctx.ne(kq_mask_all);
    let mnb = *ctx.nb(kq_mask_all);
    let all = ctx.view_4d(
        kq_mask_all,
        1,
        mne[0],
        mne[1],
        mne[3],
        mnb[0] as usize,
        mnb[1] as usize,
        mnb[2] as usize,
        0,
    );

    // top_k [n_top_k, T] -> [n_top_k, T, 1, 1] (:691-692)
    let tne = *ctx.ne(top_k);
    let tnb = *ctx.nb(top_k);
    let top_k_3d = ctx.view_4d(
        top_k,
        tne[0],
        tne[1],
        tne[3],
        1,
        tnb[1] as usize,
        tnb[2] as usize,
        (tne[3] * tnb[3] as i64) as usize,
        0,
    );

    // zero-filled rows (:694-695) — F16 under flash attention like the mask
    let zeros_ty = if use_fa { GgmlType::F16 } else { GgmlType::F32 };
    let zeros = ctx.new_tensor_4d(zeros_ty, 1, tne[0], tne[1], tne[3]);
    let zeros = ctx.fill(zeros, 0.0);

    let m = ctx.set_rows(all, zeros, top_k_3d);
    // back to [n_kv, T, 1, 1] (:698-700)
    let mne = *ctx.ne(m);
    let mnb = *ctx.nb(m);
    let m = ctx.view_4d(
        m,
        mne[1],
        mne[2],
        1,
        mne[3],
        mnb[2] as usize,
        mnb[3] as usize,
        mnb[3] as usize,
        0,
    );

    ctx.add(m, kq_mask)
}

/// build_attn_mha for the DSV4 attention (llama-graph.cpp:2602-2738 with
/// v == k, sinks, no v_mla, no softcap): q [H, n_head, T] F32,
/// k_all [H, 1, n_kv_all, 1] F16, kq_mask [n_kv_all, T], sinks [n_head].
/// Returns the flattened [H*n_head, T] attention output.
fn attn_dsv4(
    ctx: &mut Context,
    q: TensorId,
    k_all: TensorId,
    kq_mask: TensorId,
    sinks: TensorId,
    kq_scale: f32,
    use_fa: bool,
    il: usize,
) -> TensorId {
    let t = ctx.ne(q)[2];
    let n_embd_head_v = ctx.ne(k_all)[0];
    let n_head = ctx.ne(q)[1];

    if use_fa {
        // llama-graph.cpp:2626-2669 + the sinks of :2646-2647
        let kqv = graph::flash_attn_core_sinks(
            ctx,
            q,
            k_all,
            k_all,
            kq_mask,
            Some(sinks),
            kq_scale,
            0.0,
            0.0,
        );
        ctx.set_name(kqv, "kqv_out");
        let _ = il;
        return kqv;
    }

    // non-FA (llama-graph.cpp:2670-2733)
    let q = ctx.permute(q, 0, 2, 1, 3);
    let k_view = ctx.permute(k_all, 0, 2, 1, 3);
    let mut kq = ctx.mul_mat(k_view, q);
    kq = ctx.soft_max_ext(kq, Some(kq_mask), kq_scale, 0.0);
    ctx.soft_max_add_sinks(kq, Some(sinks));

    let v_view = ctx.permute(k_all, 0, 2, 1, 3);
    let v_t = ctx.transpose(v_view);
    let v_c = ctx.cont(v_t);
    let kqv = ctx.mul_mat(v_c, kq); // [head_dim, T, heads]

    let kqv = ctx.permute(kqv, 0, 2, 1, 3);
    ctx.cont_2d(kqv, n_embd_head_v * n_head, t)
}

/// verify against src/models/deepseek4.cpp:1223-1360 `graph::graph` — the deepseek4
/// trunk: per-token hyper-connected residual streams (4 streams by default),
/// the MLA-style single-head kv projection whose K cache is the iswa raw pair,
/// and the per-layer compressors (ratio 0: raw SWA only; 4: CSA overlap
/// compression + the lightning-indexer top-k mask; 128: HCA block
/// compression), all sharing the batch-6 MLA core's cache-write conventions.
///
/// Not ported (C positions):
///   * the MTP/nextn graph class is ported separately as
///     [`build_deepseek4_mtp_forward`] (deepseek4.cpp:1363-1502 — the MTP
///     draft context's graph, not this trunk one);
///   * the *unfused* hyper-connection fallbacks — build_hc_pre's per-stream
///     mul/add chain (:307-314), build_hc_sinkhorn (:317-352) and build_hc_post's
///     concat loop (:427-446): the cparams defaults fuse all three
///     (llama-context.cpp:240-242) and the reference server never disables
///     them;
///   * `embeddings_layer_inp` (:1240-1244) — the per-layer input tap the
///     server's embedding mode would consume (the `embeddings_nextn` tap of
///     :1338-1342 IS wired: `nextn_unmasked`);
///   * `build_cvec` (:1325) — same no-op treatment as the other archs;
///   * `exp_probs_b_vl` (:1287-1289) — vision-only routing bias, absent from
///     text files.
///
/// def4d406a: upstream renamed the free function `dsv4_hc_mean` into the
/// member `llama_model_deepseek4::graph::build_hc_mean` (deepseek4.cpp:269-277
/// / :1240 / :1329) — a pure move onto ctx0/the class, the port's inline
/// hc-mean (the `hc_head`/`1.0/hc` scale path below) is unchanged.
pub fn build_deepseek4_forward(
    ctx: &mut Context,
    w: &Deepseek4ModelWeights,
    p: &Deepseek4Params,
    kv: &KvCache,
    inp: &DecodeInputs,
    _sinfo: SlotInfo,
    _n_kv: u32,
    n_tokens: usize,
    nextn_unmasked: bool,
) -> ForwardResult {
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let ap = &p.attn;
    let hc = p.hc_mult;

    assert!(
        p.f_attn_temp_scale == 0.0,
        "deepseek4: attention temperature scaling not ported"
    );

    let dsv4 = kv
        .dsv4
        .as_ref()
        .expect("deepseek4 needs the dsv4 cache (KvCache::dsv4)");
    let step = kv
        .dsv4_step
        .as_ref()
        .expect("deepseek4 needs the dsv4 step inputs (KvCache::dsv4_step)");
    let raw_step = kv
        .swa_step
        .expect("deepseek4 raw layers need the iswa swa step inputs");
    let n_kv_raw = kv.n_kv_swa();

    let n_embd_head = ap.n_embd_head_k;
    let n_groups = p.o_group_count;
    let n_heads_group = ap.n_head / n_groups;
    let o_lora_rank = p.o_lora_rank;
    let o_group_dim = n_heads_group * n_embd_head;

    assert_eq!(n_embd_head, ap.n_embd_head_v);
    assert_eq!(ap.n_head % n_groups, 0);

    let mut graph = Graph::new(1024);

    // build_inp_embd (deepseek4.cpp:1227)
    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    // hc_init (:1235-1236): repeat the embedding into the hc streams
    let inp_l = ctx.reshape_3d(inp_l, p.n_embd, 1, t);
    let mut inp_l = ctx.repeat_4d(inp_l, p.n_embd, hc, t, 1);

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_sa = inp_l;

        // the per-layer rope parameters (deepseek4.cpp:903-910)
        let use_compress_rope = p.ratios[il] != 0;
        let freq_base_l = if use_compress_rope {
            p.compress_rope_base
        } else {
            ap.freq_base
        };
        let freq_scale_l = if use_compress_rope {
            ap.freq_scale
        } else {
            1.0
        };
        let ext_factor_l = if use_compress_rope {
            ap.ext_factor
        } else {
            0.0
        };
        let attn_factor_l = dsv4_rope_attn_factor(freq_scale_l, ext_factor_l);
        let beta_fast_l = if use_compress_rope { ap.beta_fast } else { 0.0 };
        let beta_slow_l = if use_compress_rope { ap.beta_slow } else { 0.0 };
        let n_ctx_orig_l = if use_compress_rope { ap.n_ctx_orig } else { 0 };
        let rope_l = |ctx: &mut Context, x: TensorId| -> TensorId {
            let x = ctx.rope_ext(
                x,
                inp.pos,
                None,
                ap.n_rot as i32,
                ap.rope_mode,
                n_ctx_orig_l,
                freq_base_l,
                freq_scale_l,
                ext_factor_l,
                attn_factor_l,
                beta_fast_l,
                beta_slow_l,
            );
            ctx.rope_set_offset(x, (n_embd_head - ap.n_rot) as i32)
        };

        // hc_attn_pre (:1250-1255)
        let (mut cur, post, comb) = build_hc_pre_dsv4(
            ctx,
            inp_l,
            lw.hc_attn_fn,
            lw.hc_attn_scale,
            lw.hc_attn_base,
            p,
            il as i32,
        );
        cur = build_norm_rms(ctx, cur, lw.attn_norm, ap.norm_eps);

        // ---- build_attention_impl (deepseek4.cpp:879-1221) ----
        let nt = t;

        // qr/q/kv (:912-936)
        let mut qr = crate::adapter::lora_mm(ctx, lw.wq_a, cur);
        ctx.set_name(qr, &format!("qr-{il}"));
        qr = build_norm_rms(ctx, qr, lw.attn_q_a_norm, ap.norm_eps);
        ctx.set_name(qr, &format!("qr_norm-{il}"));

        let mut q = crate::adapter::lora_mm(ctx, lw.wq_b, qr);
        q = ctx.reshape_3d(q, n_embd_head, ap.n_head, nt);
        // per-head RMS norm without weight (:920)
        q = ctx.rms_norm(q, ap.norm_eps);
        ctx.set_name(q, &format!("q_norm-{il}"));
        q = rope_l(ctx, q);
        ctx.set_name(q, &format!("q-{il}"));

        let mut kvt = crate::adapter::lora_mm(ctx, lw.wkv, cur);
        kvt = build_norm_rms(ctx, kvt, lw.attn_kv_norm, ap.norm_eps);
        ctx.set_name(kvt, &format!("kv_norm-{il}"));
        kvt = ctx.reshape_3d(kvt, n_embd_head, 1, nt);
        kvt = rope_l(ctx, kvt);
        ctx.set_name(kvt, &format!("kv-{il}"));

        let ratio = p.ratios[il];

        // the raw cache's Hadamard rotation input (`self_k_rot` of
        // llm_graph_input_dsv4_raw — attn_rot_k of the raw iswa cache,
        // llama-kv-cache.cpp:321-332, on when n_embd_head_k == indexer_head_size)
        let raw_rot: Option<TensorId> = step.raw_k_rot;

        // the hadamard on q/kv before the cache write (:726-729/:782-785/:836-839)
        let (q, kvt, hadamard_raw) = match raw_rot {
            Some(rot) => (
                mul_mat_hadamard(ctx, q, rot),
                mul_mat_hadamard(ctx, kvt, rot),
                true,
            ),
            None => (q, kvt, false),
        };

        // the raw cache write + read (cpy_k through the swa cache's row idxs)
        {
            let nb2 = ctx.nb(kvt)[2] as usize;
            let kvt_rows = ctx.view_2d(kvt, n_embd_head, nt, nb2, 0);
            let dst = ctx.set_rows(kv.layers[il].k, kvt_rows, raw_step.row_idx);
            graph.build_forward(ctx, dst);
        }
        let raw_k = kv.get_k(ctx, il, n_embd_head, 1, n_kv_raw);
        let raw_mask = raw_step.kq_mask;

        // ---- the CSA compressor + lid twin (deepseek4.cpp:960-1098) ----
        if ratio == crate::kv_cache::DSV4_CSA_RATIO {
            let csa = &step.csa;
            let lid = &step.lid;

            let mut csa_state_kv =
                crate::adapter::lora_mm(ctx, lw.attn_comp_wkv.expect("attn_comp_wkv"), cur);
            let mut csa_state_score =
                crate::adapter::lora_mm(ctx, lw.attn_comp_wgate.expect("attn_comp_wgate"), cur);
            {
                let ape_rows =
                    ctx.get_rows(lw.attn_comp_ape.expect("attn_comp_ape"), csa.state_pos);
                csa_state_score = ctx.add(csa_state_score, ape_rows);
            }

            // dsv4_build_state_restore with empty restore idxs = the live plane
            let csa_base_kv = dsv4.csa_state.get_kv_all(il);
            let csa_base_score = dsv4.csa_state.get_score_all(il);
            let csa_source_kv = ctx.concat(csa_base_kv, csa_state_kv, 1);
            let csa_source_score = ctx.concat(csa_base_score, csa_state_score, 1);

            let mut kv_comp_csa = build_overlap_compressed_kv_from_state(
                ctx,
                csa_source_kv,
                csa_source_score,
                csa.state_read_idxs,
                csa.state_write_pos,
                lw.attn_comp_norm.expect("attn_comp_norm"),
                crate::kv_cache::DSV4_CSA_RATIO as i64,
                n_embd_head,
                p,
            );
            if let Some(rot) = csa.k_rot {
                kv_comp_csa = mul_mat_hadamard(ctx, kv_comp_csa, rot);
            }
            {
                let w = dsv4.csa.cpy_k(ctx, kv_comp_csa, csa.state_write_idxs, il);
                graph.build_forward(ctx, w);
            }

            // the persist pass — the current ubatch's fresh states become the
            // next step's state plane (:1019-1028)
            {
                let pk = ctx.get_rows(csa_state_kv, csa.state_persist_src_idxs);
                let ps = ctx.get_rows(csa_state_score, csa.state_persist_src_idxs);
                let w1 = dsv4
                    .csa_state
                    .cpy_kv(ctx, pk, csa.state_persist_dst_idxs, il);
                let w2 = dsv4
                    .csa_state
                    .cpy_score(ctx, ps, csa.state_persist_dst_idxs, il);
                graph.build_forward(ctx, w1);
                graph.build_forward(ctx, w2);
            }

            // the lid twin (:1030-1097)
            let mut lid_state_kv =
                crate::adapter::lora_mm(ctx, lw.indexer_comp_wkv.expect("indexer_comp_wkv"), cur);
            let mut lid_state_score = crate::adapter::lora_mm(
                ctx,
                lw.indexer_comp_wgate.expect("indexer_comp_wgate"),
                cur,
            );
            {
                let ape_rows = ctx.get_rows(
                    lw.indexer_comp_ape.expect("indexer_comp_ape"),
                    lid.state_pos,
                );
                lid_state_score = ctx.add(lid_state_score, ape_rows);
            }

            let lid_base_kv = dsv4.lid_state.get_kv_all(il);
            let lid_base_score = dsv4.lid_state.get_score_all(il);
            let lid_source_kv = ctx.concat(lid_base_kv, lid_state_kv, 1);
            let lid_source_score = ctx.concat(lid_base_score, lid_state_score, 1);

            let mut kv_comp_lid = build_overlap_compressed_kv_from_state(
                ctx,
                lid_source_kv,
                lid_source_score,
                lid.state_read_idxs,
                lid.state_write_pos,
                lw.indexer_comp_norm.expect("indexer_comp_norm"),
                crate::kv_cache::DSV4_CSA_RATIO as i64,
                p.indexer_head_size,
                p,
            );
            if let Some(rot) = lid.k_rot {
                kv_comp_lid = mul_mat_hadamard(ctx, kv_comp_lid, rot);
            }
            {
                let w = dsv4.lid.cpy_k(ctx, kv_comp_lid, lid.state_write_idxs, il);
                graph.build_forward(ctx, w);
            }
            {
                let pk = ctx.get_rows(lid_state_kv, lid.state_persist_src_idxs);
                let ps = ctx.get_rows(lid_state_score, lid.state_persist_src_idxs);
                let w1 = dsv4
                    .lid_state
                    .cpy_kv(ctx, pk, lid.state_persist_dst_idxs, il);
                let w2 = dsv4
                    .lid_state
                    .cpy_score(ctx, ps, lid.state_persist_dst_idxs, il);
                graph.build_forward(ctx, w1);
                graph.build_forward(ctx, w2);
            }
        }

        // ---- the HCA compressor (deepseek4.cpp:1100-1179) ----
        if ratio == crate::kv_cache::DSV4_HCA_RATIO {
            let hca = &step.hca;

            let mut hca_state_kv =
                crate::adapter::lora_mm(ctx, lw.attn_comp_wkv.expect("attn_comp_wkv"), cur);
            let mut hca_state_score =
                crate::adapter::lora_mm(ctx, lw.attn_comp_wgate.expect("attn_comp_wgate"), cur);
            {
                let ape_rows =
                    ctx.get_rows(lw.attn_comp_ape.expect("attn_comp_ape"), hca.state_pos);
                hca_state_score = ctx.add(hca_state_score, ape_rows);
            }

            let hca_base_kv = dsv4.hca_state.get_kv_all(il);
            let hca_base_score = dsv4.hca_state.get_score_all(il);
            let hca_source_kv = ctx.concat(hca_base_kv, hca_state_kv, 1);
            let hca_source_score = ctx.concat(hca_base_score, hca_state_score, 1);

            let mut kv_comp_hca = build_hca_compressed_kv_from_state(
                ctx,
                hca_source_kv,
                hca_source_score,
                hca.state_read_idxs,
                hca.state_write_pos,
                lw.attn_comp_norm.expect("attn_comp_norm"),
                n_embd_head,
                p,
            );
            if let Some(rot) = hca.k_rot {
                kv_comp_hca = mul_mat_hadamard(ctx, kv_comp_hca, rot);
            }
            {
                let w = dsv4.hca.cpy_k(ctx, kv_comp_hca, hca.state_write_idxs, il);
                graph.build_forward(ctx, w);
            }

            // the HCA persist pass (:1169-1178)
            {
                let pk = ctx.get_rows(hca_state_kv, hca.state_persist_src_idxs);
                let ps = ctx.get_rows(hca_state_score, hca.state_persist_src_idxs);
                let w1 = dsv4
                    .hca_state
                    .cpy_kv(ctx, pk, hca.state_persist_dst_idxs, il);
                let w2 = dsv4
                    .hca_state
                    .cpy_score(ctx, ps, hca.state_persist_dst_idxs, il);
                graph.build_forward(ctx, w1);
                graph.build_forward(ctx, w2);
            }
        }

        // ---- the attention branches (deepseek4.cpp:1189-1202) ----
        let kq_scale = 1.0 / (n_embd_head as f32).sqrt();
        let mut out = if ratio == crate::kv_cache::DSV4_CSA_RATIO {
            // build_csa_lid_attention (deepseek4.cpp:708-768)
            let top_k = build_lid_top_k_dsv4(ctx, lw, dsv4, step, qr, cur, inp.pos, p, il);

            let n_csa = ctx.ne(step.csa.kq_mask)[0];
            let mut csa_k = dsv4.csa.get_k(ctx, il, step.plan_csa().n_kv);
            {
                let kne = *ctx.ne(csa_k);
                let knb = *ctx.nb(csa_k);
                csa_k = ctx.view_4d(
                    csa_k,
                    kne[0],
                    kne[1],
                    n_csa,
                    kne[3],
                    knb[1] as usize,
                    knb[2] as usize,
                    knb[3] as usize,
                    0,
                );
            }

            let k_all = ctx.concat(raw_k, csa_k, 2);
            let csa_mask = build_top_k_mask_dsv4(ctx, step.csa.kq_mask, top_k, ap.use_flash_attn);
            let kq_mask = ctx.concat(raw_mask, csa_mask, 0);
            // n_kv_max (deepseek4.cpp:760) only feeds ggml_flash_attn_ext's
            // scheduling hint — not ported (numerically irrelevant)

            let o = attn_dsv4(
                ctx,
                q,
                k_all,
                kq_mask,
                lw.attn_sinks,
                kq_scale,
                ap.use_flash_attn,
                il,
            );
            if hadamard_raw {
                // out is [H*n_head, T]; the C hadamards the [H, n_head, T]
                // form then the caller reshapes — same element order
                let o3 = ctx.reshape_3d(o, n_embd_head, ap.n_head, nt);
                let o3 = mul_mat_hadamard(ctx, o3, step.raw_k_rot.unwrap());
                ctx.cont_2d(o3, n_embd_head * ap.n_head, nt)
            } else {
                o
            }
        } else if ratio == crate::kv_cache::DSV4_HCA_RATIO {
            // build_hca_attention (deepseek4.cpp:770-823)
            let n_hca = ctx.ne(step.hca.kq_mask)[0];
            let mut hca_k = dsv4.hca.get_k(ctx, il, step.plan_hca().n_kv);
            {
                let kne = *ctx.ne(hca_k);
                let knb = *ctx.nb(hca_k);
                hca_k = ctx.view_4d(
                    hca_k,
                    kne[0],
                    kne[1],
                    n_hca,
                    kne[3],
                    knb[1] as usize,
                    knb[2] as usize,
                    knb[3] as usize,
                    0,
                );
            }

            let k_all = ctx.concat(raw_k, hca_k, 2);
            let kq_mask = ctx.concat(raw_mask, step.hca.kq_mask, 0);

            let o = attn_dsv4(
                ctx,
                q,
                k_all,
                kq_mask,
                lw.attn_sinks,
                kq_scale,
                ap.use_flash_attn,
                il,
            );
            if hadamard_raw {
                let o3 = ctx.reshape_3d(o, n_embd_head, ap.n_head, nt);
                let o3 = mul_mat_hadamard(ctx, o3, step.raw_k_rot.unwrap());
                ctx.cont_2d(o3, n_embd_head * ap.n_head, nt)
            } else {
                o
            }
        } else {
            // build_raw_attention (deepseek4.cpp:825-859) — plain SWA window
            let o = attn_dsv4(
                ctx,
                q,
                raw_k,
                raw_mask,
                lw.attn_sinks,
                kq_scale,
                ap.use_flash_attn,
                il,
            );
            if hadamard_raw {
                let o3 = ctx.reshape_3d(o, n_embd_head, ap.n_head, nt);
                let o3 = mul_mat_hadamard(ctx, o3, step.raw_k_rot.unwrap());
                ctx.cont_2d(o3, n_embd_head * ap.n_head, nt)
            } else {
                o
            }
        };

        // attn_derope (:1204-1208) — ggml_rope_ext_back, the inverse rotation
        out = ctx.reshape_3d(out, n_embd_head, ap.n_head, nt);
        {
            let x = ctx.rope_ext_back(
                out,
                inp.pos,
                None,
                ap.n_rot as i32,
                ap.rope_mode,
                n_ctx_orig_l,
                freq_base_l,
                freq_scale_l,
                ext_factor_l,
                attn_factor_l,
                beta_fast_l,
                beta_slow_l,
            );
            out = ctx.rope_set_offset(x, (n_embd_head - ap.n_rot) as i32);
        }

        // the o_group/o_lora output projection (:1210-1218)
        out = ctx.reshape_3d(out, o_group_dim, n_groups, nt);
        out = ctx.permute(out, 0, 2, 1, 3);
        let mut oa = ctx.mul_mat(lw.wo_a, out);
        oa = ctx.permute(oa, 0, 2, 1, 3);
        oa = ctx.cont_2d(oa, o_lora_rank * n_groups, nt);
        let out = crate::adapter::lora_mm(ctx, lw.wo_b, oa);

        // hc_attn_post (:1262)
        inp_l = build_hc_post_dsv4(ctx, out, inp_sa, post, comb);

        // ---- the FFN half (:1265-1326) ----
        let residual = inp_l;
        let (mut cur, post, comb) = build_hc_pre_dsv4(
            ctx,
            inp_l,
            lw.hc_ffn_fn,
            lw.hc_ffn_scale,
            lw.hc_ffn_base,
            p,
            il as i32,
        );
        cur = build_norm_rms(ctx, cur, lw.ffn_norm, ap.norm_eps);

        // hash layers read the expert ids straight from the token ids
        // (deepseek4.cpp:1281-1293); text input never switches to the vl bias
        let selected_experts = if (il as u32) < p.hash_layer_count {
            Some(ctx.get_rows(lw.ffn_gate_tid2eid.expect("ffn_gate_tid2eid"), inp.tokens))
        } else {
            None
        };
        let exp_probs_b = if selected_experts.is_some() {
            None
        } else {
            lw.ffn_exp_probs_b
        };

        let moe_out = build_moe_ffn_dsv4(
            ctx,
            &mut graph,
            cur,
            lw.ffn_gate_inp,
            lw.ffn_up_exps,
            lw.ffn_gate_exps,
            lw.ffn_down_exps,
            exp_probs_b,
            selected_experts,
            p,
            il,
        );
        let ffn_shexp = build_ffn_shexp_dsv4(ctx, cur, lw, p, il);
        cur = ctx.add(moe_out, ffn_shexp);

        // hc_ffn_post (:1324)
        inp_l = build_hc_post_dsv4(ctx, cur, residual, post, comb);
    }

    // ---- the output head (deepseek4.cpp:1330-1357) ----
    // (inp_out_ids gathers the identity here — n_outputs == n_tokens)
    //
    // `cparams.embeddings_nextn` (deepseek4.cpp:1338-1342): the MTP target
    // tap mounts `t_h_nextn` on the *flat pre-head* streams — the full rows
    // when unmasked, the gathered output rows when masked (the port never
    // prunes, so both are the same `flat` tensor). Returned through the
    // ForwardResult `embd` slot in the tap's stead of `t_embd` — the only
    // consumer of `t_embd` on a nextn context is the tap itself.
    let flat = ctx.reshape_2d(inp_l, p.n_embd * hc, t);
    let t_nextn = if nextn_unmasked { Some(flat) } else { None };

    let cur = build_hc_head_dsv4(ctx, inp_l, w.hc_head_fn, w.hc_head_scale, w.hc_head_base, p);
    let cur = build_norm_rms(ctx, cur, w.output_norm, ap.norm_eps);
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let logits = ctx.mul_mat(w.output, cur);

    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(match t_nextn {
            Some(h) => h,
            None => cur,
        }),
    }
}

/// `build_ffn` SILU+PAR with the shexp clamp (llama-graph.cpp:1828-1843 —
/// the DEEPSEEK4 branch uses `ggml_swiglu_clamp` directly).
fn build_ffn_shexp_dsv4(
    ctx: &mut Context,
    cur: TensorId,
    lw: &Deepseek4LayerWeights,
    p: &Deepseek4Params,
    il: usize,
) -> TensorId {
    let gate = crate::adapter::lora_mm(ctx, lw.ffn_gate_shexp, cur);
    let up = crate::adapter::lora_mm(ctx, lw.ffn_up_shexp, cur);
    // llama-graph.cpp:1829-1842: limit > 1e-6 selects ggml_swiglu_clamp for
    // DEEPSEEK4 (the arch check), else the plain swiglu_split
    let limit = p.swiglu_clamp_shexp[il];
    let prod = if limit > 1e-6 {
        ctx.swiglu_clamp(gate, up, limit)
    } else {
        ctx.swiglu_split(gate, up)
    };
    crate::adapter::lora_mm(ctx, lw.ffn_down_shexp, prod)
}

/// `build_moe_ffn` with the SQRT_SOFTPLUS gating, the hash-layer
/// selected-experts input and the swiglu_clamp expert FFN
/// (llama-graph.cpp:1993-2368 — the DEEPSEEK4 branches at :2026-2029/:2053
/// and :2225-2233; deepseek4.cpp:1295-1311's call).
#[allow(clippy::too_many_arguments)]
fn build_moe_ffn_dsv4(
    ctx: &mut Context,
    graph: &mut Graph,
    cur: TensorId,
    gate_inp: TensorId,
    up_exps: TensorId,
    gate_exps: TensorId,
    down_exps: TensorId,
    exp_probs_b: Option<TensorId>,
    selected_experts_in: Option<TensorId>,
    p: &Deepseek4Params,
    il: usize,
) -> TensorId {
    let n_embd = ctx.ne(cur)[0];
    let n_tokens = ctx.ne(cur)[1];
    let n_expert = p.n_expert;
    let n_expert_used = p.n_expert_used;

    // routing (llama-graph.cpp:2021-2057)
    let logits = crate::adapter::lora_mm(ctx, gate_inp, cur);
    // SQRT_SOFTPLUS (:2053): probs = sqrt(softplus(logits)) — logits stay F32
    let sp = ctx.softplus(logits);
    let probs = ctx.sqrt(sp);

    // e-score bias steers only the top-k (:2062-2067)
    let selection_probs = match exp_probs_b {
        Some(b) => ctx.add(probs, b),
        None => probs,
    };
    let selected = match selected_experts_in {
        Some(sel) => sel,
        None => ctx.argsort_top_k(selection_probs, n_expert_used as i32),
    };

    let probs3 = ctx.reshape_3d(probs, 1, n_expert, n_tokens);
    let mut weights = ctx.get_rows(probs3, selected);
    if p.expert_weights_norm {
        let w2 = ctx.reshape_2d(weights, n_expert_used, n_tokens);
        let sum = ctx.sum_rows(w2);
        let sum = ctx.clamp(sum, 6.103515625e-5, f32::INFINITY);
        let w2 = ctx.div(w2, sum);
        weights = ctx.reshape_3d(w2, 1, n_expert_used, n_tokens);
    }
    if p.expert_weights_scale != 0.0 && p.expert_weights_scale != 1.0 {
        weights = ctx.scale(weights, p.expert_weights_scale);
    }
    graph.build_forward(ctx, weights);

    // experts (llama-graph.cpp:2190-2234 — the separate gate/up path)
    let cur3 = ctx.reshape_3d(cur, n_embd, 1, n_tokens);
    let up = crate::adapter::lora_mm_id(ctx, up_exps, cur3, selected);
    let gate = crate::adapter::lora_mm_id(ctx, gate_exps, cur3, selected);

    // the clamp'd swiglu (llama-graph.cpp:2225-2233 — DEEPSEEK4 branch)
    let limit = p.swiglu_clamp_exp[il];
    let act = if limit > 1e-6 {
        ctx.swiglu_clamp(gate, up, limit)
    } else {
        ctx.swiglu_split(gate, up)
    };

    let mut experts = crate::adapter::lora_mm_id(ctx, down_exps, act, selected);
    experts = ctx.mul(experts, weights);
    graph.build_forward(ctx, experts);

    // aggregate the k expert views (llama-graph.cpp:2329-2358)
    let nb1 = ctx.nb(experts)[1] as usize;
    let nb2 = ctx.nb(experts)[2] as usize;
    let mut moe_out = ctx.view_2d(experts, n_embd, n_tokens, nb2, 0);
    graph.build_forward(ctx, moe_out);
    for i in 1..n_expert_used as usize {
        let vi = ctx.view_2d(experts, n_embd, n_tokens, nb2, i * nb1);
        graph.build_forward(ctx, vi);
        moe_out = ctx.add(moe_out, vi);
        graph.build_forward(ctx, moe_out);
    }
    if n_expert_used == 1 {
        moe_out = ctx.cont(moe_out);
    }
    moe_out
}

// ===========================================================================
// MTP/NextN draft graphs — the `graph_mtp` class of the deepseek family
// (LLM_GRAPH_TYPE_DECODER_MTP, llama-graph.h:41). Built only by the MTP
// draft context (`cparams.ctx_type == LLAMA_CONTEXT_TYPE_MTP`,
// llama-context.cpp:28-33) that `--spec-type mtp` creates over the target
// model; the trunk graphs never reach these. The KV cache the draft context
// carries is the filtered one of llama-model.cpp:2665-2679 (deepseek2) /
// :2319-2345 (deepseek32) / :2465-2507 (deepseek4) — only the nextn layer's
// rows — so these builders address `kv.layers[0]` of a 1-layer cache.
// ===========================================================================

/// `llama_layer::nextn` restricted to the members the deepseek MTP blocks
/// read (deepseek2.cpp:152-158 / deepseek4.cpp:174-181 — all optional in the
/// loader, asserted present by the graph).
#[derive(Debug, Clone, Copy)]
pub struct DeepseekMtpNextn {
    /// `{2*n_embd, n_embd}` (NEXTN_EH_PROJ)
    pub eh_proj: TensorId,
    /// `{n_embd}` (NEXTN_ENORM)
    pub enorm: TensorId,
    /// `{n_embd}` (NEXTN_HNORM)
    pub hnorm: TensorId,
    /// optional `{n_embd, n_vocab}` (NEXTN_EMBED_TOKENS)
    pub embed_tokens: Option<TensorId>,
    /// optional `{n_embd, n_vocab}` (NEXTN_SHARED_HEAD_HEAD)
    pub shared_head_head: Option<TensorId>,
    /// optional `{n_embd}` (NEXTN_SHARED_HEAD_NORM)
    pub shared_head_norm: Option<TensorId>,
}

/// Weights of the deepseek2/deepseek32 MTP block: the layer at index
/// `n_layer` carries a full MLA trunk tensor set plus the `nextn.*` head
/// (deepseek2.cpp:94-160 loads both for `i >= n_layer`).
pub struct Deepseek2MtpWeights {
    pub tok_embd: TensorId,
    pub output_norm: TensorId,
    pub output: TensorId,
    pub nextn: DeepseekMtpNextn,
    /// the MTP layer (`model.layers[n_layer]`) — its trunk-shaped tensors
    pub layer: Deepseek2LayerWeights,
}

/// the hidden-state input of the MTP graph — `llm_graph_input_embd_h::h`
/// (llama-graph.h:143-158), filled from the *previous* position's target
/// `h_nextn` row by the draft-mtp driver (speculative.cpp:1526-1547)
pub type MtpHInput = TensorId;

/// verify against src/models/deepseek2.cpp:170-415
/// `llama_model_deepseek2::graph_mtp::graph_mtp` — the single-block MTP head:
/// eh_proj(concat(enorm(embd), hnorm(h))) → one MLA attention + MoE/shexp FFN
/// over it → shared_head_norm → the LM head. `h_in` is the F32
/// `[n_embd, n_tokens]` hidden-state input; the returned `ForwardResult`'s
/// `embd` slot carries `res->t_h_nextn` (the post-block norm — the C's graph
/// sets `t_h_nextn` and never `t_embd`, deepseek2.cpp:392-393).
///
/// The `inp_out_ids` row pruning of :395-397 is skipped like everywhere in
/// the port — the graph computes every row and the driver gathers by output
/// flags (identical values).
///
/// deepseek32's `graph_mtp` (deepseek32.cpp:495-725) is the same graph with
/// `il = n_layer + nextn_layer_offset` (asserted 0 — deepseek32.cpp:501-504)
/// and the MoE `_s` scale args (not ported anywhere, same as the trunk);
/// [`build_deepseek32_mtp_forward`] is its thin wrapper.
pub fn build_deepseek2_mtp_forward(
    ctx: &mut Context,
    w: &Deepseek2MtpWeights,
    p: &Deepseek2Params,
    kv: &KvCache,
    inp: &DecodeInputs,
    h_in: MtpHInput,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    // deepseek2.cpp:172-175 — "GLM4 MTP" GGML_ASSERTs (the C's strings; the
    // class was written for the shared MLA MTP shape). n_layer_nextn == 1
    // and is_mla are properties of the MTP context's model — asserted where
    // the MTP weights are assembled (`DecodeContext::new_mtp` /
    // `common_speculative_impl_draft_mtp`).
    assert!(
        p.f_attn_temp_scale == 0.0,
        "GLM4 MTP does not support attention temperature scaling (deepseek2.cpp:175)"
    );

    let mut graph = Graph::new(1024);
    let (logits, h_nextn) = build_deepseek_mla_mtp_body(
        ctx, &mut graph, w, p, &p.attn, kv, inp, h_in, n_kv, n_tokens,
    );

    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(h_nextn),
    }
}

/// verify against src/models/deepseek32.cpp:495-725
/// `llama_model_deepseek32::graph_mtp::graph_mtp` — see
/// [`build_deepseek2_mtp_forward`]; the differences are the
/// `nextn_layer_offset` derivation of `il` (:501-504 — 0 for the single
/// block these archs support) and the MoE scale args (not ported, trunk
/// convention).
pub fn build_deepseek32_mtp_forward(
    ctx: &mut Context,
    w: &Deepseek2MtpWeights,
    p: &Deepseek32Params,
    kv: &KvCache,
    inp: &DecodeInputs,
    h_in: MtpHInput,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    // deepseek32.cpp:497-510 — n_layer_nextn == 1 / is_mla (assembled-model
    // asserts) and nextn_layer_offset == 0 (:501-504, the single block)

    let mut graph = Graph::new(1024);
    let (logits, h_nextn) = build_deepseek_mla_mtp_body(
        ctx,
        &mut graph,
        w,
        &p.ds2,
        &p.ds2.attn,
        kv,
        inp,
        h_in,
        n_kv,
        n_tokens,
    );

    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(h_nextn),
    }
}

/// the shared body of the deepseek2/deepseek32 `graph_mtp` constructors —
/// the two C graphs are line-for-line the same attention/FFN/head chain
/// (deepseek2.cpp:215-415 ≡ deepseek32.cpp:529-725); returns
/// `(res->t_logits, res->t_h_nextn)`.
#[allow(clippy::too_many_arguments)]
fn build_deepseek_mla_mtp_body(
    ctx: &mut Context,
    graph: &mut Graph,
    w: &Deepseek2MtpWeights,
    p: &Deepseek2Params,
    ap: &AttnParams,
    kv: &KvCache,
    inp: &DecodeInputs,
    h_in: MtpHInput,
    n_kv: u32,
    n_tokens: usize,
) -> (TensorId, TensorId) {
    let t = n_tokens as i64;
    let lw = &w.layer;

    // deepseek2.cpp:172-185 — "GLM4 MTP" asserts (the messages are the C's)
    assert!(p.kv_lora_rank >= 0);
    assert!(
        lw.wq_a.is_some(),
        "MTP block missing wq_a (GLM4 MTP requires MLA)"
    );
    assert!(lw.attn_q_a_norm.is_some());
    assert!(lw.wq_b.is_some());
    assert!(lw.wkv_a_mqa.is_some());
    assert!(lw.attn_kv_a_norm.is_some());
    assert!(lw.wk_b.is_some());
    let has_split_exps = lw.ffn_up_exps.is_some() && lw.ffn_gate_exps.is_some();
    let has_fused_exps = lw.ffn_gate_up_exps.is_some();
    assert!(
        has_split_exps || has_fused_exps,
        "MTP block missing expert tensors"
    );
    assert!(lw.ffn_gate_inp.is_some());

    // deepseek2.cpp:187-193
    let n_embd_head_k_mla = p.n_embd_head_k_mla;
    let n_embd_head_qk_rope = ap.n_rot;
    let n_embd_head_qk_nope = n_embd_head_k_mla - n_embd_head_qk_rope;
    let kv_lora_rank = p.kv_lora_rank;
    assert!(n_embd_head_qk_nope >= 1);

    // the YaRN pre-scaled kq_scale (deepseek2.cpp:305-314 — the same formula
    // as the trunk graph, [TAG_DEEPSEEK2_YARN_LOG_MUL_FIX])
    assert!(ap.ext_factor >= 0.0);
    let attn_factor_org = ap.attn_factor * (1.0 + 0.1 * (1.0f32 / ap.freq_scale).ln());
    let mscale =
        attn_factor_org * (1.0 + 0.1 * p.rope_yarn_log_mul * (1.0f32 / ap.freq_scale).ln());
    let kq_scale = 1.0 * mscale * mscale / (n_embd_head_k_mla as f32).sqrt();

    // llm_graph_input_embd_h (deepseek2.cpp:215-241): tokens → the embedding
    // table (nextn.embed_tokens when present, else the model's — :223-232);
    // `h` is the driver-provided hidden-state input (:235-239). The `embd`
    // fallback input (:220/:230) is the mtmd path — never taken with tokens.
    let tok_embd_w = w.nextn.embed_tokens.unwrap_or(w.tok_embd);
    let tok_embd = ctx.get_rows(tok_embd_w, inp.tokens);
    let h_embd = h_in;

    // hnorm / enorm (:248-252)
    let h_norm = build_norm_rms(ctx, h_embd, w.nextn.hnorm, ap.norm_eps);
    let e_norm = build_norm_rms(ctx, tok_embd, w.nextn.enorm, ap.norm_eps);

    // eh_proj over the concatenated norms (:254-257)
    let concat = ctx.concat(e_norm, h_norm, 0);
    let inp_sa = crate::adapter::lora_mm(ctx, w.nextn.eh_proj, concat);

    // self-attention — the MLA construction of the trunk graph
    // (deepseek2.cpp:262-349)
    let cur = build_norm_rms(ctx, inp_sa, lw.attn_norm, ap.norm_eps);

    let q = ctx.mul_mat(lw.wq_a.expect("wq_a"), cur);
    let q = build_norm_rms(
        ctx,
        q,
        lw.attn_q_a_norm.expect("attn_q_a_norm"),
        ap.norm_eps,
    );
    let q = ctx.mul_mat(lw.wq_b.expect("wq_b"), q);

    // split into {n_embd_head_qk_nope, n_head, n_tokens} (:274-278)
    let n_head = ap.n_head;
    let (qnb1, qnb2) = (ctx.nb(q)[1] as usize, ctx.nb(q)[2] as usize);
    let q_nope = ctx.view_3d(q, n_embd_head_qk_nope, n_head, t, qnb1, qnb2, 0);
    // and {n_embd_head_qk_rope, n_head, n_tokens} (:280-285)
    let q_pe = ctx.view_3d(
        q,
        n_embd_head_qk_rope,
        n_head,
        t,
        qnb1,
        qnb2,
        ctx.ty(q).row_size(n_embd_head_qk_nope as usize),
    );

    let kv_cmpr_pe = ctx.mul_mat(lw.wkv_a_mqa.expect("wkv_a_mqa"), cur);

    // {kv_lora_rank, n_tokens} (:290-292)
    let kv_cmpr = {
        let rs = ctx
            .ty(kv_cmpr_pe)
            .row_size((kv_lora_rank + n_embd_head_qk_rope) as usize);
        ctx.view_2d(kv_cmpr_pe, kv_lora_rank, t, rs, 0)
    };
    // {n_embd_head_qk_rope, 1, n_tokens} (:295-300)
    let k_pe = {
        let rs = ctx
            .ty(kv_cmpr_pe)
            .row_size((kv_lora_rank + n_embd_head_qk_rope) as usize);
        ctx.view_3d(
            kv_cmpr_pe,
            n_embd_head_qk_rope,
            1,
            t,
            rs,
            rs,
            ctx.ty(kv_cmpr_pe).row_size(kv_lora_rank as usize),
        )
    };

    let kv_cmpr = build_norm_rms(
        ctx,
        kv_cmpr,
        lw.attn_kv_a_norm.expect("attn_kv_a_norm"),
        ap.norm_eps,
    );

    // rope Q/K (:316-324)
    let q_pe = ctx.rope_ext(
        q_pe,
        inp.pos,
        None,
        ap.n_rot as i32,
        ap.rope_mode,
        ap.n_ctx_orig,
        ap.freq_base,
        ap.freq_scale,
        ap.ext_factor,
        ap.attn_factor,
        ap.beta_fast,
        ap.beta_slow,
    );
    let k_pe = ctx.rope_ext(
        k_pe,
        inp.pos,
        None,
        ap.n_rot as i32,
        ap.rope_mode,
        ap.n_ctx_orig,
        ap.freq_base,
        ap.freq_scale,
        ap.ext_factor,
        ap.attn_factor,
        ap.beta_fast,
        ap.beta_slow,
    );

    // the absorbed MQA form (:326-345) — wk_b over the permuted nope segment,
    // Qcur = concat(absorbed, q_pe), Kcur = concat(kv_cmpr, k_pe)
    let q_nope = ctx.permute(q_nope, 0, 2, 1, 3);
    let q_nope_absorbed = ctx.mul_mat(lw.wk_b.expect("wk_b"), q_nope);
    let q_nope_absorbed = ctx.permute(q_nope_absorbed, 0, 2, 1, 3);

    let qcur = ctx.concat(q_nope_absorbed, q_pe, 0);
    let kv_cmpr3 = ctx.reshape_3d(kv_cmpr, kv_lora_rank, 1, t);
    let kcur = ctx.concat(kv_cmpr3, k_pe, 0);

    // build_attn(inp_attn_k, wo, ..., v_mla = wv_b) (:347-349) — the draft
    // context's 1-layer K-only cache is `kv.layers[0]`
    let cur = attn_k_cached_mla(
        ctx,
        graph,
        kv,
        0,
        ap,
        inp,
        n_kv,
        qcur,
        kcur,
        kv_cmpr3,
        kq_scale,
        lw.wv_b.expect("wv_b"),
        Some(lw.wo),
        None,
    );

    // FFN — MoE + shared expert over eh_proj's output (:352-384)
    let ffn_inp = ctx.add(cur, inp_sa);
    let cur = build_norm_rms(ctx, ffn_inp, lw.ffn_norm, ap.norm_eps);

    let moe_out = build_moe_ffn_deepseek2(ctx, graph, cur, lw, p);
    let ffn_shexp = build_ffn_silu_par(
        ctx,
        cur,
        lw.ffn_gate_shexp.expect("ffn_gate_shexp"),
        None,
        lw.ffn_up_shexp.expect("ffn_up_shexp"),
        None,
        lw.ffn_down_shexp.expect("ffn_down_shexp"),
        None,
    );
    let cur = ctx.add(moe_out, ffn_shexp);
    let cur = ctx.add(cur, ffn_inp);

    // the shared head — nextn.shared_head_norm/head when the file carries
    // them, else the model's output norm/lm head (:386-410)
    let head_norm_w = w.nextn.shared_head_norm.unwrap_or(w.output_norm);
    let h_nextn = build_norm_rms(ctx, cur, head_norm_w, ap.norm_eps);
    let head_w = w.nextn.shared_head_head.unwrap_or(w.output);

    // build_lora_mm(head_w, ...) (:410 — lora_mm, unlike the trunk's plain
    // mul_mat lm head) over the :395-397 get_rows-pruned rows
    let h_nextn_out = graph::out_rows(ctx, h_nextn, inp.out_ids);
    let logits = crate::adapter::lora_mm(ctx, head_w, h_nextn_out);

    (logits, h_nextn)
}

/// Weights of the deepseek4 MTP block (deepseek4.cpp:174-181 nextn set +
/// the layer's full trunk set).
pub struct Deepseek4MtpWeights {
    pub tok_embd: TensorId,
    pub output_norm: TensorId,
    pub output: TensorId,
    pub hc_head_fn: TensorId,
    pub hc_head_base: TensorId,
    pub hc_head_scale: TensorId,
    pub nextn: DeepseekMtpNextn,
    /// the MTP layer (`model.layers[n_layer]`)
    pub layer: Deepseek4LayerWeights,
}

/// verify against src/models/deepseek4.cpp:1363-1502
/// `llama_model_deepseek4::graph_mtp::graph_mtp` — the hyper-connection MTP
/// block: eh_proj over [repeat(enorm(embd)); hnorm(h)] streams → one
/// hc-pre/attn/hc-post + hc-pre/MoE/hc-post round → the flattened streams
/// are `t_h_nextn` (the next step's h input) → hc_head → shared head norm →
/// the LM head.
///
/// The attention is `build_attention(model, llm_graph_input_attn_k_iswa*,
/// ...)` — the `inp_mtp` arm of build_attention_impl (deepseek4.cpp:1182-
/// 1188): the plain iswa raw cache with the sinks and the Hadamard `k_rot`
/// of the swa side (llama-graph.cpp:3177-3233), *not* the compressed dsv4
/// caches. `kv` is the MTP context's 1-layer `KvCache::new_swa` pair
/// (llama-model.cpp:2469-2489); the MTP layer is a SWA layer, so the swa
/// side's row_idx/mask carry it. `k_rot` is that cache's
/// `build_input_k_rot` input (llama-kv-cache.cpp:1437-1455 — on because
/// deepseek4's key_length == indexer_head_size).
///
/// The `inp_out_ids` pruning of :1480 and `build_cvec` (:1476) are skipped
/// (unpruned rows / the no-op the other builders drop).
pub fn build_deepseek4_mtp_forward(
    ctx: &mut Context,
    w: &Deepseek4MtpWeights,
    p: &Deepseek4Params,
    kv: &KvCache,
    inp: &DecodeInputs,
    h_in: MtpHInput,
    k_rot: Option<TensorId>,
    n_tokens: usize,
) -> ForwardResult {
    let t = n_tokens as i64;
    let ap = &p.attn;
    let hc = p.hc_mult;
    let lw = &w.layer;

    // deepseek4.cpp:1365-1370 — single block, offset 0; token input required
    // (the embd-only mtmd path is not taken)
    assert!(
        hc == 4,
        "deepseek4 MTP: hc_mult == 4 (deepseek4.cpp:1372-1373)"
    );
    assert!(
        kv.has_swa(),
        "deepseek4 MTP needs the iswa pair (llama-model.cpp:2474)"
    );
    let step = kv.swa_step.as_ref().expect("deepseek4 MTP swa step inputs");
    let n_kv = kv.n_kv_swa();

    let n_embd_head = ap.n_embd_head_k;
    let n_groups = p.o_group_count;
    let n_heads_group = ap.n_head / n_groups;
    let o_lora_rank = p.o_lora_rank;
    let o_group_dim = n_heads_group * n_embd_head;

    assert_eq!(n_embd_head, ap.n_embd_head_v);
    assert_eq!(ap.n_head % n_groups, 0);

    // the MTP layer is raw (ratio 0 — GGML_ASSERT(inp_dsv4 || ratio == 0),
    // deepseek4.cpp:938-939), so its rope is the global one
    // (use_compress_rope == false, :903-910)
    let use_compress_rope = false;
    let freq_base_l = if use_compress_rope {
        p.compress_rope_base
    } else {
        ap.freq_base
    };
    let freq_scale_l = if use_compress_rope {
        ap.freq_scale
    } else {
        1.0
    };
    let ext_factor_l = if use_compress_rope {
        ap.ext_factor
    } else {
        0.0
    };
    let attn_factor_l = dsv4_rope_attn_factor(freq_scale_l, ext_factor_l);
    let beta_fast_l = if use_compress_rope { ap.beta_fast } else { 0.0 };
    let beta_slow_l = if use_compress_rope { ap.beta_slow } else { 0.0 };
    let n_ctx_orig_l = if use_compress_rope { ap.n_ctx_orig } else { 0 };
    let rope_l = |ctx: &mut Context, x: TensorId| -> TensorId {
        let x = ctx.rope_ext(
            x,
            inp.pos,
            None,
            ap.n_rot as i32,
            ap.rope_mode,
            n_ctx_orig_l,
            freq_base_l,
            freq_scale_l,
            ext_factor_l,
            attn_factor_l,
            beta_fast_l,
            beta_slow_l,
        );
        ctx.rope_set_offset(x, (n_embd_head - ap.n_rot) as i32)
    };

    let mut graph = Graph::new(1024);

    // llm_graph_input_embd_h at n_embd_out width (deepseek4.cpp:1382-1401)
    let tok_embd_w = w.nextn.embed_tokens.unwrap_or(w.tok_embd);
    let tok_embd = ctx.get_rows(tok_embd_w, inp.tokens);

    // h_state: the hidden input reshaped into the hc streams (:1398)
    let h_state = ctx.reshape_3d(h_in, p.n_embd, hc, t);

    // hnorm over the streams; enorm over the embedding broadcast to them
    // (:1407-1413)
    let h_norm = build_norm_rms(ctx, h_state, w.nextn.hnorm, ap.norm_eps);
    let e_norm = build_norm_rms(ctx, tok_embd, w.nextn.enorm, ap.norm_eps);
    let e_norm = ctx.reshape_3d(e_norm, p.n_embd, 1, t);
    let e_norm = ctx.repeat_4d(e_norm, p.n_embd, hc, t, 1);

    // eh_proj over the stacked norms (:1415-1418)
    let concat = ctx.concat(e_norm, h_norm, 0);
    let inp_l = crate::adapter::lora_mm(ctx, w.nextn.eh_proj, concat);

    // the attention half (:1421-1438)
    let residual = inp_l;
    let (cur, post, comb) = build_hc_pre_dsv4(
        ctx,
        inp_l,
        lw.hc_attn_fn,
        lw.hc_attn_scale,
        lw.hc_attn_base,
        p,
        -1,
    );
    let cur = build_norm_rms(ctx, cur, lw.attn_norm, ap.norm_eps);

    // ---- build_attention_impl's inp_mtp path (deepseek4.cpp:912-936 +
    // :1182-1188, the iswa build_attn of llama-graph.cpp:3177-3233) ----
    let nt = t;
    let mut qr = crate::adapter::lora_mm(ctx, lw.wq_a, cur);
    qr = build_norm_rms(ctx, qr, lw.attn_q_a_norm, ap.norm_eps);
    let mut q = crate::adapter::lora_mm(ctx, lw.wq_b, qr);
    q = ctx.reshape_3d(q, n_embd_head, ap.n_head, nt);
    q = ctx.rms_norm(q, ap.norm_eps); // :920 — per-head RMS norm, no weight
    q = rope_l(ctx, q);

    let mut kvt = crate::adapter::lora_mm(ctx, lw.wkv, cur);
    kvt = build_norm_rms(ctx, kvt, lw.attn_kv_norm, ap.norm_eps);
    kvt = ctx.reshape_3d(kvt, n_embd_head, 1, nt);
    kvt = rope_l(ctx, kvt);

    // llama-graph.cpp:3181-3189 — the swa side's k_rot Hadamards q and the
    // cached k before the write, and the attention output after
    let kq_scale = 1.0 / (n_embd_head as f32).sqrt(); // :1187
    let out = {
        let (q, kvt) = match k_rot {
            Some(rot) => (
                mul_mat_hadamard(ctx, q, rot),
                mul_mat_hadamard(ctx, kvt, rot),
            ),
            None => (q, kvt),
        };
        graph.build_forward(ctx, q);

        // cpy_k of the compressed rows through the swa cache's row idxs
        // (:3194-3199) — kv.layers[0] is the MTP layer of the 1-layer pair
        let nb2 = ctx.nb(kvt)[2] as usize;
        let kvt_rows = ctx.view_2d(kvt, n_embd_head, nt, nb2, 0);
        let dst = ctx.set_rows(kv.layers[0].k, kvt_rows, step.row_idx);
        graph.build_forward(ctx, dst);

        // MLA-style: the cached K is used as V (:3209-3217)
        let k_all = kv.get_k(ctx, 0, n_embd_head, 1, n_kv);
        let out = attn_dsv4(
            ctx,
            q,
            k_all,
            step.kq_mask,
            lw.attn_sinks,
            kq_scale,
            ap.use_flash_attn,
            0,
        );

        // llama-graph.cpp:3225 — un-rotate the output
        match k_rot {
            Some(rot) => mul_mat_hadamard(ctx, out, rot),
            None => out,
        }
    };

    // attn_derope (:1204-1208)
    let out = ctx.reshape_3d(out, n_embd_head, ap.n_head, nt);
    let out = {
        let x = ctx.rope_ext_back(
            out,
            inp.pos,
            None,
            ap.n_rot as i32,
            ap.rope_mode,
            n_ctx_orig_l,
            freq_base_l,
            freq_scale_l,
            ext_factor_l,
            attn_factor_l,
            beta_fast_l,
            beta_slow_l,
        );
        ctx.rope_set_offset(x, (n_embd_head - ap.n_rot) as i32)
    };

    // the o_group/o_lora output projection (:1210-1218)
    let out = ctx.reshape_3d(out, o_group_dim, n_groups, nt);
    let out = ctx.permute(out, 0, 2, 1, 3);
    let mut oa = ctx.mul_mat(lw.wo_a, out);
    oa = ctx.permute(oa, 0, 2, 1, 3);
    let oa = ctx.cont_2d(oa, o_lora_rank * n_groups, nt);
    let out = crate::adapter::lora_mm(ctx, lw.wo_b, oa);

    let inp_l = build_hc_post_dsv4(ctx, out, residual, post, comb);

    // the FFN half (:1440-1477)
    let residual = inp_l;
    let (cur, post, comb) = build_hc_pre_dsv4(
        ctx,
        inp_l,
        lw.hc_ffn_fn,
        lw.hc_ffn_scale,
        lw.hc_ffn_base,
        p,
        -1,
    );
    let cur = build_norm_rms(ctx, cur, lw.ffn_norm, ap.norm_eps);

    // GGML_ASSERT(il >= dsv4_hash_layer_count) (:1451) — the MTP layer is
    // past every hash layer; the tid2eid table is never read
    let moe_out = build_moe_ffn_dsv4(
        ctx,
        &mut graph,
        cur,
        lw.ffn_gate_inp,
        lw.ffn_up_exps,
        lw.ffn_gate_exps,
        lw.ffn_down_exps,
        lw.ffn_exp_probs_b,
        None,
        p,
        0,
    );
    let ffn_shexp = build_ffn_shexp_dsv4(ctx, cur, lw, p, 0);
    let cur = ctx.add(moe_out, ffn_shexp);

    let inp_l = build_hc_post_dsv4(ctx, cur, residual, post, comb);
    // build_cvec (:1476) — the no-op the trunk builder drops too

    // the flat streams are t_h_nextn (:1479-1482)
    let h_nextn = ctx.reshape_2d(inp_l, p.n_embd * hc, t);

    // hc_head over the streams (:1484-1487)
    let inp_l = ctx.reshape_3d(h_nextn, p.n_embd, hc, t);
    let cur = build_hc_head_dsv4(ctx, inp_l, w.hc_head_fn, w.hc_head_scale, w.hc_head_base, p);

    // the shared head (:1489-1497)
    let head_norm_w = w.nextn.shared_head_norm.unwrap_or(w.output_norm);
    let cur = build_norm_rms(ctx, cur, head_norm_w, ap.norm_eps);
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let logits = ctx.mul_mat(w.nextn.shared_head_head.unwrap_or(w.output), cur);

    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(h_nextn),
    }
}

// ======================================================================
// arch batch 8 (2026-09-30): the MoE long-tail family — hunyuan-moe /
// dots1 / bailingmoe / bailingmoe2 / glm4-moe / minimax-m2 / cohere2moe /
// exaone-moe. All are `build_moe_ffn` compositions over the shared helpers
// (`build_moe_ffn_silu` / `build_moe_ffn_silu_gu` below); the per-arch
// differences are the top-k rule knobs (norm_w / w_scale / gating func /
// exp_probs_b), the shared-expert variant, the dense-lead split and where
// the Q/K norms sit relative to rope.
// ======================================================================

// ----------------------------------------------------------------------
// hunyuan-moe — src/models/hunyuan-moe.cpp:52-187
// ----------------------------------------------------------------------

pub struct HunyuanMoeLayerWeights {
    pub attn_norm: TensorId,
    pub wqkv: Option<TensorId>,
    pub wqkv_b: Option<TensorId>,
    pub wq: Option<TensorId>,
    pub wk: Option<TensorId>,
    pub wv: Option<TensorId>,
    pub wq_b: Option<TensorId>,
    pub wk_b: Option<TensorId>,
    pub wv_b: Option<TensorId>,
    pub wo: TensorId,
    /// per-head [n_embd_head_k] Q/K norms — applied *after* rope here
    /// (hunyuan-moe.cpp:110-118), the reverse order of dots1/qwen3
    pub attn_k_norm: TensorId,
    pub attn_q_norm: TensorId,
    pub ffn_norm: TensorId,
    pub ffn_gate_inp: TensorId,
    pub ffn_gate_exps: TensorId,
    pub ffn_down_exps: TensorId,
    pub ffn_up_exps: TensorId,
    /// the shared expert doubles as a plain dense MLP
    /// (hunyuan-moe.cpp:138-144 — build_ffn, no gate on the router)
    pub ffn_gate_shexp: TensorId,
    pub ffn_down_shexp: TensorId,
    pub ffn_up_shexp: TensorId,
}

pub struct HunyuanMoeModelWeights {
    pub tok_embd: TensorId,
    pub output_norm: TensorId,
    pub output: TensorId,
    pub layers: Vec<HunyuanMoeLayerWeights>,
}

#[derive(Clone)]
pub struct HunyuanMoeParams {
    pub attn: AttnParams,
    pub n_expert: i64,
    pub n_expert_used: i64,
    /// hparams.expert_weights_scale (hunyuan-moe.cpp:156)
    pub expert_weights_scale: f32,
}

/// verify against src/models/hunyuan-moe.cpp:56-187 — RMS attn_norm → QKV → **rope both
/// Q and K first, then the per-head RMS Q/K norms** (hunyuan-moe.cpp:94-118,
/// the opposite order of qwen3/dots1) → MHA (kq_scale 1/sqrt(head)) →
/// residual → RMS ffn_norm → MoE (`norm_w = true`, softmax gating) **plus the
/// shared expert as a plain SwiGLU MLP** (hunyuan-moe.cpp:137-161 — the only
/// arch of the batch that adds both branches ungated) → residual.
#[allow(clippy::too_many_arguments)]
pub fn build_hunyuan_moe_forward(
    ctx: &mut Context,
    w: &HunyuanMoeModelWeights,
    p: &HunyuanMoeParams,
    kv: &KvCache,
    inp: &DecodeInputs,
    sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let _ = sinfo;
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(2048);
    assert_eq!(
        p.attn.n_embd_head_k, p.attn.n_embd_head_v,
        "hunyuan-moe.cpp:59"
    );
    assert_eq!(p.attn.n_embd_head_k, p.attn.n_rot, "hunyuan-moe.cpp:60");

    let inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    let mut inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_sa = inp_l;

        // attn_norm (hunyuan-moe.cpp:80-83)
        let cur = build_norm_rms(ctx, inp_l, lw.attn_norm, p.attn.norm_eps);

        // build_qkv (hunyuan-moe.cpp:91-92)
        let (q, k, v) = if let Some(wqkv) = lw.wqkv {
            qkv_fused(ctx, wqkv, lw.wqkv_b, &p.attn, cur, t)
        } else {
            qkv_separate_parts(
                ctx,
                lw.wq.expect("wq"),
                lw.wq_b,
                lw.wk.expect("wk"),
                lw.wk_b,
                lw.wv.expect("wv"),
                lw.wv_b,
                &p.attn,
                cur,
                t,
            )
        };

        // rope first (hunyuan-moe.cpp:94-108)…
        let (q, k) = rope_qk(ctx, &p.attn, inp.pos, q, k);
        // …then the per-head RMS norms on the roped tensors
        // (hunyuan-moe.cpp:110-118)
        let k = build_norm_rms(ctx, k, lw.attn_k_norm, p.attn.norm_eps);
        let q = build_norm_rms(ctx, q, lw.attn_q_norm, p.attn.norm_eps);

        // kq_scale = 1/sqrt(n_embd_head) (hunyuan-moe.cpp:72/:120-122)
        let kq_scale = 1.0 / (p.attn.n_embd_head_v as f32).sqrt();
        let cur = attn_kv_cached(
            ctx,
            &mut graph,
            kv,
            il,
            &p.attn,
            inp,
            n_kv,
            q,
            k,
            v,
            kq_scale,
            0.0,
            None,
            None,
            Some(lw.wo),
            None,
        );

        // ffn_inp (hunyuan-moe.cpp:129)
        let ffn_inp = ctx.add(cur, inp_sa);

        // shared expert as a plain MLP (hunyuan-moe.cpp:137-144)
        let cur = build_norm_rms(ctx, ffn_inp, lw.ffn_norm, p.attn.norm_eps);
        let cur_mlp = build_ffn_silu_par(
            ctx,
            cur,
            lw.ffn_gate_shexp,
            None,
            lw.ffn_up_shexp,
            None,
            lw.ffn_down_shexp,
            None,
        );

        // MoE branch (hunyuan-moe.cpp:146-159): norm_topk_prob = true, softmax
        let cur_moe = build_moe_ffn_silu(
            ctx,
            &mut graph,
            cur,
            lw.ffn_gate_inp,
            None,
            lw.ffn_up_exps,
            None,
            Some(lw.ffn_gate_exps),
            None,
            lw.ffn_down_exps,
            None,
            None,
            p.n_expert,
            p.n_expert_used,
            true,
            p.expert_weights_scale,
            EXPERT_GATING_SOFTMAX,
        );

        // ffn_out = cur_moe + cur_mlp (hunyuan-moe.cpp:161-164)
        let ffn_out = ctx.add(cur_moe, cur_mlp);
        inp_l = ctx.add(ffn_out, ffn_inp);
    }

    // final norm + lm_head (hunyuan-moe.cpp:174-184)
    let cur = build_norm_rms(ctx, inp_l, w.output_norm, p.attn.norm_eps);
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let logits = crate::adapter::lora_mm(ctx, w.output, cur);
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

// ----------------------------------------------------------------------
// dots1 — src/models/dots1.cpp:70-193
// ----------------------------------------------------------------------

pub struct Dots1LayerWeights {
    pub attn_norm: TensorId,
    pub wqkv: Option<TensorId>,
    pub wqkv_b: Option<TensorId>,
    pub wq: Option<TensorId>,
    pub wk: Option<TensorId>,
    pub wv: Option<TensorId>,
    pub wq_b: Option<TensorId>,
    pub wk_b: Option<TensorId>,
    pub wv_b: Option<TensorId>,
    pub wo: TensorId,
    pub attn_k_norm: TensorId,
    pub attn_q_norm: TensorId,
    pub ffn_norm: TensorId,
    /// dense-lead layers only
    pub ffn_gate: Option<TensorId>,
    pub ffn_down: Option<TensorId>,
    pub ffn_up: Option<TensorId>,
    /// MoE layers only
    pub ffn_gate_inp: Option<TensorId>,
    /// optional router selection bias (dots1.cpp:48 NOT_REQUIRED)
    pub ffn_exp_probs_b: Option<TensorId>,
    pub ffn_gate_exps: Option<TensorId>,
    pub ffn_down_exps: Option<TensorId>,
    pub ffn_up_exps: Option<TensorId>,
    /// n_expert_shared side-by-side shared experts, width n_ff_exp *
    /// n_expert_shared (dots1.cpp:62-65)
    pub ffn_gate_shexp: Option<TensorId>,
    pub ffn_down_shexp: Option<TensorId>,
    pub ffn_up_shexp: Option<TensorId>,
}

pub struct Dots1ModelWeights {
    pub tok_embd: TensorId,
    pub output_norm: TensorId,
    pub output: TensorId,
    pub layers: Vec<Dots1LayerWeights>,
}

#[derive(Clone)]
pub struct Dots1Params {
    pub attn: AttnParams,
    pub n_expert: i64,
    pub n_expert_used: i64,
    /// hparams.n_layer_dense_lead (optional, default 0)
    pub n_layer_dense_lead: u32,
    /// hparams.expert_weights_norm (optional, default false)
    pub expert_weights_norm: bool,
    pub expert_weights_scale: f32,
    /// hparams.expert_gating_func (optional; real dots1 GGUFs carry it)
    pub expert_gating_func: i32,
}

/// verify against src/models/dots1.cpp:74-193 — RMS attn_norm → QKV → **per-head RMS
/// Q/K norms before rope** (dots1.cpp:106-116) → MHA → residual → RMS
/// ffn_norm → dense SwiGLU on the lead layers, else MoE (gating func and
/// norm_w straight from hparams, optional exp_probs_b steering the top-k)
/// **plus an ungated shared expert** of width n_ff_exp * n_expert_shared →
/// residual.
#[allow(clippy::too_many_arguments)]
pub fn build_dots1_forward(
    ctx: &mut Context,
    w: &Dots1ModelWeights,
    p: &Dots1Params,
    kv: &KvCache,
    inp: &DecodeInputs,
    sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let _ = sinfo;
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(2048);
    assert_eq!(p.attn.n_embd_head_k, p.attn.n_embd_head_v, "dots1.cpp:78");
    assert_eq!(p.attn.n_embd_head_k, p.attn.n_rot, "dots1.cpp:79");

    let inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    let mut inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_sa = inp_l;

        // attn_norm (dots1.cpp:97)
        let cur = build_norm_rms(ctx, inp_l, lw.attn_norm, p.attn.norm_eps);

        // build_qkv + the norm-before-rope order (dots1.cpp:103-116)
        let (q, k, v) = if let Some(wqkv) = lw.wqkv {
            qkv_fused(ctx, wqkv, lw.wqkv_b, &p.attn, cur, t)
        } else {
            qkv_separate_parts(
                ctx,
                lw.wq.expect("wq"),
                lw.wq_b,
                lw.wk.expect("wk"),
                lw.wk_b,
                lw.wv.expect("wv"),
                lw.wv_b,
                &p.attn,
                cur,
                t,
            )
        };
        let q = build_norm_rms(ctx, q, lw.attn_q_norm, p.attn.norm_eps);
        let q = ctx.rope_ext(
            q,
            inp.pos,
            None,
            p.attn.n_rot as i32,
            p.attn.rope_mode,
            p.attn.n_ctx_orig,
            p.attn.freq_base,
            p.attn.freq_scale,
            p.attn.ext_factor,
            p.attn.attn_factor,
            p.attn.beta_fast,
            p.attn.beta_slow,
        );
        let k = build_norm_rms(ctx, k, lw.attn_k_norm, p.attn.norm_eps);
        let k = ctx.rope_ext(
            k,
            inp.pos,
            None,
            p.attn.n_rot as i32,
            p.attn.rope_mode,
            p.attn.n_ctx_orig,
            p.attn.freq_base,
            p.attn.freq_scale,
            p.attn.ext_factor,
            p.attn.attn_factor,
            p.attn.beta_fast,
            p.attn.beta_slow,
        );

        // kq_scale = 1/sqrt(n_embd_head) (dots1.cpp:124)
        let kq_scale = 1.0 / (p.attn.n_embd_head_v as f32).sqrt();
        let cur = attn_kv_cached(
            ctx,
            &mut graph,
            kv,
            il,
            &p.attn,
            inp,
            n_kv,
            q,
            k,
            v,
            kq_scale,
            0.0,
            None,
            None,
            Some(lw.wo),
            None,
        );

        // ffn_inp (dots1.cpp:130)
        let ffn_inp = ctx.add(cur, inp_sa);

        let cur = build_norm_rms(ctx, ffn_inp, lw.ffn_norm, p.attn.norm_eps);
        let out = if (il as u32) < p.n_layer_dense_lead {
            // dense lead (dots1.cpp:137-143)
            build_ffn_silu_par(
                ctx,
                cur,
                lw.ffn_gate.expect("ffn_gate"),
                None,
                lw.ffn_up.expect("ffn_up"),
                None,
                lw.ffn_down.expect("ffn_down"),
                None,
            )
        } else {
            // MoE + shared expert (dots1.cpp:144-170)
            let moe_out = build_moe_ffn_silu(
                ctx,
                &mut graph,
                cur,
                lw.ffn_gate_inp.expect("ffn_gate_inp"),
                None,
                lw.ffn_up_exps.expect("ffn_up_exps"),
                None,
                lw.ffn_gate_exps,
                None,
                lw.ffn_down_exps.expect("ffn_down_exps"),
                None,
                lw.ffn_exp_probs_b,
                p.n_expert,
                p.n_expert_used,
                p.expert_weights_norm,
                p.expert_weights_scale,
                p.expert_gating_func,
            );
            let ffn_shexp = build_ffn_silu_par(
                ctx,
                cur,
                lw.ffn_gate_shexp.expect("ffn_gate_shexp"),
                None,
                lw.ffn_up_shexp.expect("ffn_up_shexp"),
                None,
                lw.ffn_down_shexp.expect("ffn_down_shexp"),
                None,
            );
            ctx.add(moe_out, ffn_shexp)
        };
        inp_l = ctx.add(out, ffn_inp);
    }

    // final norm + lm_head (dots1.cpp:181-190)
    let cur = build_norm_rms(ctx, inp_l, w.output_norm, p.attn.norm_eps);
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let logits = crate::adapter::lora_mm(ctx, w.output, cur);
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

