/// verify against src/models/bailingmoe.cpp:62-180 — the plain MoE stack of the batch:
/// RMS attn_norm → QKV (head width from `n_rot` in the loader,
/// bailingmoe.cpp:35) → rope Q/K (no q/k norms) → MHA with **kq_scale =
/// 1/sqrt(n_rot)** (bailingmoe.cpp:111) → residual → RMS ffn_norm → MoE
/// (softmax gating, norm_w from hparams) + ungated shared expert → residual.
/// `n_layer_dense_lead` is read by the hparams loader (bailingmoe.cpp:5) but
/// every layer carries the MoE tensors (bailingmoe.cpp:39-54).
#[allow(clippy::too_many_arguments)]
pub fn build_bailingmoe_forward(
    ctx: &mut Context,
    w: &BailingmoeModelWeights,
    p: &BailingmoeParams,
    kv: &KvCache,
    inp: &DecodeInputs,
    sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let _ = sinfo;
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(2048);

    let inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    let mut inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_sa = inp_l;

        // attn_norm (bailingmoe.cpp:79-82)
        let cur = build_norm_rms(ctx, inp_l, lw.attn_norm, p.attn.norm_eps);

        // build_qkv (bailingmoe.cpp:90-91) + rope both (bailingmoe.cpp:93-103)
        let (q, k, v) = if let Some(wqkv) = lw.wqkv {
            qkv_fused(ctx, wqkv, lw.wqkv_b, &p.attn, cur, t)
        } else {
            qkv_separate_parts(
                ctx,
                lw.wq.expect("wq"),
                lw.wq_b,
                lw.wk.expect("wk"),
                lw.wk_b,
                lw.wv.expect("wv"),
                lw.wv_b,
                &p.attn,
                cur,
                t,
            )
        };
        let (q, k) = rope_qk(ctx, &p.attn, inp.pos, q, k);

        // kq_scale = 1/sqrt(n_rot) (bailingmoe.cpp:111)
        let kq_scale = 1.0 / (p.attn.n_rot as f32).sqrt();
        let cur = attn_kv_cached(
            ctx,
            &mut graph,
            kv,
            il,
            &p.attn,
            inp,
            n_kv,
            q,
            k,
            v,
            kq_scale,
            0.0,
            None,
            None,
            Some(lw.wo),
            None,
        );

        // ffn_inp (bailingmoe.cpp:119)
        let ffn_inp = ctx.add(cur, inp_sa);

        // MoE + shared expert (bailingmoe.cpp:122-153)
        let cur = build_norm_rms(ctx, ffn_inp, lw.ffn_norm, p.attn.norm_eps);
        let moe_out = build_moe_ffn_silu(
            ctx,
            &mut graph,
            cur,
            lw.ffn_gate_inp,
            None,
            lw.ffn_up_exps,
            None,
            Some(lw.ffn_gate_exps),
            None,
            lw.ffn_down_exps,
            None,
            None,
            p.n_expert,
            p.n_expert_used,
            p.expert_weights_norm,
            p.expert_weights_scale,
            EXPERT_GATING_SOFTMAX,
        );
        let ffn_shexp = build_ffn_silu_par(
            ctx,
            cur,
            lw.ffn_gate_shexp,
            None,
            lw.ffn_up_shexp,
            None,
            lw.ffn_down_shexp,
            None,
        );
        let cur = ctx.add(moe_out, ffn_shexp);
        inp_l = ctx.add(cur, ffn_inp);
    }

    // final norm + lm_head (bailingmoe.cpp:164-178)
    let cur = build_norm_rms(ctx, inp_l, w.output_norm, p.attn.norm_eps);
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let logits = crate::adapter::lora_mm(ctx, w.output, cur);
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

