/// qwen3next hparams + the GDN geometry (qwen3next.cpp:4-29).
#[derive(Clone)]
pub struct Qwen3NextParams {
    pub attn: AttnParams,
    pub n_embd: i64,
    /// per-layer attention geometry (the full-attention layers only read it)
    pub n_head: Vec<u32>,
    pub n_head_kv: Vec<u32>,
    pub n_embd_head_k: Vec<u32>,
    pub n_embd_head_v: Vec<u32>,
    pub n_rot: Vec<u32>,
    pub is_recr: Vec<bool>,
    /// hparams.f_attention_scale; 0.0 → 1/sqrt(n_embd_head) (qwen3next.cpp:292)
    pub f_attention_scale: f32,
    /// gated delta net (hparams.ssm_*)
    pub ssm_d_conv: i64,
    pub ssm_d_inner: i64,
    pub ssm_d_state: i64,
    pub ssm_dt_rank: i64,
    pub ssm_n_group: i64,
    /// hparams.n_embd_r() / n_embd_s() — the recurrent state cell sizes
    pub n_embd_r: u32,
    pub n_embd_s: u32,
    pub n_expert: i64,
    pub n_expert_used: i64,
    pub expert_weights_scale: f32,
}

/// verify against src/models/qwen3next.cpp:138-223 `graph::graph` — per layer:
/// rms attn_norm → (gated delta net | gated full attention) → residual →
/// rms attn_post_norm → MoE (+ the sigmoid-gated shared expert) → residual →
/// final norm → lm_head. The GDN runs the fused operator exactly like
/// qwen35's (delta-net-base.cpp `build_delta_net_fused`).
///
/// PARTIAL (reported): the MTP/nextn blocks are skipped (`graph_mtp`,
/// qwen3next.cpp:628-822 — extra decoder blocks; the port loads trunk-only
/// files, the deepseek convention); single sequence, K = 1 recurrent state
/// (`cparams.n_rs_seq == 0` — the TAG_RECURRENT_ROLLBACK_SPLITS branches of
/// build_conv_state / build_recurrent_attn, delta-net-base.cpp:497-522/:546-606,
/// stay unported).
pub fn build_qwen3next_forward(
    ctx: &mut Context,
    w: &Qwen3NextModelWeights,
    p: &Qwen3NextParams,
    st: &RecurrentState,
    kv: &KvCache,
    inp: &DecodeInputs,
    _sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(8192);
    assert_eq!(
        p.is_recr.len(),
        n_layer,
        "Qwen3NextParams::is_recr per layer"
    );
    assert_eq!(st.n_layer(), n_layer, "RecurrentState per layer");

    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_sa = inp_l;

        let cur = build_norm_rms(ctx, inp_l, lw.attn_norm, p.attn.norm_eps);

        let cur = if p.is_recr[il] {
            build_qwen3next_gdn_layer(ctx, &mut graph, p, lw, st, il, cur, t)
        } else {
            build_qwen3next_attn_layer(ctx, &mut graph, p, lw, kv, inp, n_kv, il, cur, t)
        };

        // residual → attn_post_norm (qwen3next.cpp:177-185)
        let ffn_residual = ctx.add(cur, inp_sa);
        let normed = build_norm_rms(ctx, ffn_residual, lw.attn_post_norm, p.attn.norm_eps);

        // MoE + the gated shared expert (qwen3next.cpp:188 / build_layer_ffn :565-625)
        let cur = build_qwen3next_ffn(ctx, &mut graph, normed, lw, p, il);
        inp_l = ctx.add(cur, ffn_residual);
    }

    // final norm + lm_head (qwen3next.cpp:203-222; the t_h_nextn tap and the
    // inp_out_ids get_rows reduce rows only — the port's decode picks its own)
    let cur = build_norm_rms(ctx, inp_l, w.output_norm, p.attn.norm_eps);
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let logits = crate::adapter::lora_mm(ctx, w.output, cur);
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

/// qwen3next.cpp:236-312 `build_layer_attn` — the every-4th full-attention
/// block: Q projection twice as wide (query + gate per head), per-head q/k
/// RMS norms, plain NEOX rope, kv-cache MHA (no wo), `sigmoid(gate)` multiply,
/// then wo.
#[allow(clippy::too_many_arguments)]
fn build_qwen3next_attn_layer(
    ctx: &mut Context,
    graph: &mut Graph,
    p: &Qwen3NextParams,
    lw: &Qwen3NextLayerWeights,
    kv: &KvCache,
    inp: &DecodeInputs,
    n_kv: u32,
    il: usize,
    cur: TensorId,
    t: i64,
) -> TensorId {
    let a = &p.attn;
    let n_embd_head = p.n_embd_head_v[il] as i64;
    assert_eq!(
        n_embd_head, p.n_embd_head_k[il] as i64,
        "qwen3next: k/v head dims differ"
    );
    let n_head = p.n_head[il] as i64;
    let n_head_kv = p.n_head_kv[il] as i64;

    // build_qkv(..., reshape = false) with the separate Q/K/V path — the Q
    // projection carries the gate (qwen3next.cpp:247-251)
    let q_full = crate::adapter::lora_mm(ctx, lw.wq.expect("wq"), cur);
    let k = crate::adapter::lora_mm(ctx, lw.wk.expect("wk"), cur);
    let v = crate::adapter::lora_mm(ctx, lw.wv.expect("wv"), cur);

    // Qcur / gate views over the [2*n_embd_head, n_head, T, 1] reshape
    // (qwen3next.cpp:256-267)
    let q_nb1 = ctx.nb(q_full)[1] as usize;
    let q_head_stride = (n_embd_head * 2 * 4) as usize;
    let q = ctx.view_4d(
        q_full,
        n_embd_head,
        n_head,
        t,
        1,
        q_head_stride,
        q_nb1,
        q_nb1 * n_head as usize,
        0,
    );
    let gate = ctx.view_4d(
        q_full,
        n_embd_head,
        n_head,
        t,
        1,
        q_head_stride,
        q_nb1,
        q_nb1 * n_head as usize,
        (n_embd_head * 4) as usize,
    );

    let k = ctx.reshape_3d(k, n_embd_head, n_head_kv, t);
    let v = ctx.reshape_3d(v, n_embd_head, n_head_kv, t);

    let q = build_norm_rms(ctx, q, lw.attn_q_norm.expect("attn_q_norm"), a.norm_eps);
    let k = build_norm_rms(ctx, k, lw.attn_k_norm.expect("attn_k_norm"), a.norm_eps);

    // plain RoPE (NEOX — qwen3next is in the NEOX rope list, llama-model.cpp:3070)
    let rope = |ctx: &mut Context, x: TensorId| {
        ctx.rope_ext(
            x,
            inp.pos,
            None,
            p.n_rot[il] as i32,
            a.rope_mode,
            a.n_ctx_orig,
            a.freq_base,
            a.freq_scale,
            a.ext_factor,
            a.attn_factor,
            a.beta_fast,
            a.beta_slow,
        )
    };
    let q = rope(ctx, q);
    let k = rope(ctx, k);

    let kq_scale = if p.f_attention_scale == 0.0 {
        1.0 / (n_embd_head as f32).sqrt()
    } else {
        p.f_attention_scale
    };
    // build_attn with wo == nullptr (qwen3next.cpp:294-296)
    let cur = attn_kv_cached(
        ctx, graph, kv, il, a, inp, n_kv, q, k, v, kq_scale, 0.0, None, None, None, None,
    );

    // cur = attn_out * sigmoid(gate); cur = wo @ cur (qwen3next.cpp:300-308)
    let gate = ctx.cont(gate);
    let gate = ctx.reshape_2d(gate, n_embd_head * n_head, t);
    let gate_sigmoid = ctx.sigmoid(gate);
    let cur = ctx.mul(cur, gate_sigmoid);
    crate::adapter::lora_mm(ctx, lw.wo.expect("wo"), cur)
}

/// qwen3next.cpp:314-393 `build_qkvz` — the input projections of the GDN
/// layer: the optimized (wqkv + wqkv_gate) pair or the legacy single
/// `ssm_in` fused QKVZ tensor, split into qkv_mixed [conv_dim, T, S] + z.
fn build_qwen3next_qkvz(
    ctx: &mut Context,
    lw: &Qwen3NextLayerWeights,
    cur: TensorId,
    il: usize,
    t: i64,
    head_k_dim: i64,
    head_v_dim: i64,
    num_k_heads: i64,
    num_v_heads: i64,
) -> (TensorId, TensorId) {
    if let Some(wqkv) = lw.wqkv {
        // optimized path (qwen3next.cpp:325-334)
        let qkv_mixed = crate::adapter::lora_mm(ctx, wqkv, cur);
        let qkv_mixed = ctx.reshape_3d(qkv_mixed, ctx.ne(qkv_mixed)[0], t, 1);
        let z = crate::adapter::lora_mm(ctx, lw.wqkv_gate.expect("wqkv_gate"), cur);
        (qkv_mixed, z)
    } else {
        // legacy path (qwen3next.cpp:336-392)
        let mixed_qkvz = crate::adapter::lora_mm(ctx, lw.ssm_in.expect("ssm_in (legacy)"), cur);
        let qkvz_new_dim = 2 * head_k_dim + 2 * head_v_dim * (num_v_heads / num_k_heads);
        let mixed = ctx.reshape_4d(mixed_qkvz, qkvz_new_dim, num_k_heads, t, 1);
        let (nb1, nb2, nb3) = {
            let nb = *ctx.nb(mixed);
            (nb[1] as usize, nb[2] as usize, nb[3] as usize)
        };
        let es = 4usize;
        let query = ctx.view_4d(mixed, head_k_dim, num_k_heads, t, 1, nb1, nb2, nb3, 0);
        let key = ctx.view_4d(
            mixed,
            head_k_dim,
            num_k_heads,
            t,
            1,
            nb1,
            nb2,
            nb3,
            head_k_dim as usize * es,
        );
        let v_width = head_v_dim * num_v_heads / num_k_heads;
        let value = ctx.view_4d(
            mixed,
            v_width,
            num_k_heads,
            t,
            1,
            nb1,
            nb2,
            nb3,
            (2 * head_k_dim) as usize * es,
        );
        let z = ctx.view_4d(
            mixed,
            v_width,
            num_k_heads,
            t,
            1,
            nb1,
            nb2,
            nb3,
            (2 * head_k_dim + v_width) as usize * es,
        );
        let z = ctx.cont(z);

        // flatten the head dims and concat q|k|v (qwen3next.cpp:374-389)
        let query_flat = ctx.cont_3d(query, head_k_dim * num_k_heads, t, 1);
        let key_flat = ctx.cont_3d(key, head_k_dim * num_k_heads, t, 1);
        let value_flat = ctx.cont_3d(value, head_v_dim * num_v_heads, t, 1);
        let qkv_mixed = ctx.concat(query_flat, key_flat, 0);
        let qkv_mixed = ctx.concat(qkv_mixed, value_flat, 0);
        let _ = il;
        (qkv_mixed, z)
    }
}

/// qwen3next.cpp:395-563 `build_layer_attn_linear` — the gated delta net
/// linear attention layer (the beta|alpha packed projection, the packed conv
/// state + causal 1D conv, the head-repeat when H_v != H_k, the fused GDN op
/// and the gated RMS norm).
#[allow(clippy::too_many_arguments)]
fn build_qwen3next_gdn_layer(
    ctx: &mut Context,
    graph: &mut Graph,
    p: &Qwen3NextParams,
    lw: &Qwen3NextLayerWeights,
    st: &RecurrentState,
    il: usize,
    cur: TensorId,
    t: i64,
) -> TensorId {
    let d_inner = p.ssm_d_inner;
    let head_k_dim = p.ssm_d_state;
    let num_k_heads = p.ssm_n_group;
    let num_v_heads = p.ssm_dt_rank;
    let head_v_dim = d_inner / num_v_heads;

    // ---- input projections (build_qkvz, qwen3next.cpp:414-416) ----
    let (qkv_mixed, z) = build_qwen3next_qkvz(
        ctx,
        lw,
        cur,
        il,
        t,
        head_k_dim,
        head_v_dim,
        num_k_heads,
        num_v_heads,
    );

    // ---- the packed beta|alpha projection (qwen3next.cpp:418-456) ----
    let mixed_ba = crate::adapter::lora_mm(ctx, lw.ssm_beta_alpha.expect("ssm_beta_alpha"), cur);
    let ba_new_dim = 2 * num_v_heads / num_k_heads;
    let mixed_ba = ctx.reshape_4d(mixed_ba, ba_new_dim, num_k_heads, t, 1);
    let (nb1, nb2, nb3) = {
        let nb = *ctx.nb(mixed_ba);
        (nb[1] as usize, nb[2] as usize, nb[3] as usize)
    };
    let b_w = num_v_heads / num_k_heads;
    let b = ctx.view_4d(mixed_ba, b_w, num_k_heads, t, 1, nb1, nb2, nb3, 0);
    let a = ctx.view_4d(
        mixed_ba,
        b_w,
        num_k_heads,
        t,
        1,
        nb1,
        nb2,
        nb3,
        b_w as usize * 4,
    );
    let b = ctx.cont(b);
    let beta = ctx.sigmoid(b);
    let alpha = ctx.cont_3d(a, num_v_heads, t, 1);
    let alpha_biased = ctx.add(alpha, lw.ssm_dt_b.expect("ssm_dt"));
    let alpha_softplus = ctx.softplus(alpha_biased);
    // -A_log.exp() * softplus (qwen3next.cpp:452)
    let gate = ctx.mul(alpha_softplus, lw.ssm_a.expect("ssm_a"));
    let beta = ctx.reshape_4d(beta, 1, num_v_heads, t, 1);
    let gate = ctx.reshape_4d(gate, 1, num_v_heads, t, 1);

    // ---- conv state + causal 1D conv (build_conv_state, delta-net-base.cpp:449-525
    //      — the n_rs_seq == 0 arm) ----
    let conv_kernel = lw.ssm_conv1d.expect("ssm_conv1d");
    let conv_kernel_size = ctx.ne(conv_kernel)[0];
    let conv_channels = d_inner + 2 * p.ssm_n_group * head_k_dim;

    let conv_state = st.conv[il].expect("qwen3next recurrent conv state");
    let conv = ctx.reshape_3d(conv_state, conv_kernel_size - 1, conv_channels, 1);
    let qkv_t = ctx.transpose(qkv_mixed);
    let conv_input = ctx.concat(conv, qkv_t, 0);
    {
        // write the last (kernel - 1) columns back into the state cell
        // (delta-net-base.cpp:479-496, the single-snapshot arm)
        let ci_ne0 = ctx.ne(conv_input)[0];
        let ci_nb = *ctx.nb(conv_input);
        let snap = ctx.view_3d(
            conv_input,
            conv_kernel_size - 1,
            conv_channels,
            1,
            ci_nb[1] as usize,
            ci_nb[2] as usize,
            ((ci_ne0 - (conv_kernel_size - 1)) * 4) as usize,
        );
        let st_nb = *ctx.nb(conv_state);
        let row_count = (conv_kernel_size - 1) * conv_channels;
        let dst = ctx.view_2d(conv_state, row_count, 1, st_nb[1] as usize, 0);
        let cpy = ctx.cpy(snap, dst);
        graph.build_forward(ctx, cpy);
    }
    let conv_out = ctx.ssm_conv(conv_input, conv_kernel);
    let conv_out = ctx.silu(conv_out);

    // ---- split Q/K/V out of the convolved stream (qwen3next.cpp:480-504) ----
    let qkv_dim = head_k_dim * num_k_heads * 2 + head_v_dim * num_v_heads;
    let nb1_qkv = GgmlType::F32.row_size(qkv_dim as usize);
    let rs_k = GgmlType::F32.row_size(head_k_dim as usize);
    let rs_v = GgmlType::F32.row_size(head_v_dim as usize);
    let mut q_conv = ctx.view_4d(
        conv_out,
        head_k_dim,
        num_k_heads,
        t,
        1,
        rs_k,
        nb1_qkv,
        nb1_qkv * t as usize,
        0,
    );
    let mut k_conv = ctx.view_4d(
        conv_out,
        head_k_dim,
        num_k_heads,
        t,
        1,
        rs_k,
        nb1_qkv,
        nb1_qkv * t as usize,
        (head_k_dim * num_k_heads * 4) as usize,
    );
    let v_conv = ctx.view_4d(
        conv_out,
        head_v_dim,
        num_v_heads,
        t,
        1,
        rs_v,
        nb1_qkv,
        nb1_qkv * t as usize,
        GgmlType::F32.row_size((2 * head_k_dim * num_k_heads) as usize),
    );

    // L2 (rms, no weight) norm of q/k (qwen3next.cpp:509-510)
    let eps_over_n = p.attn.norm_eps / head_k_dim as f32;
    q_conv = build_gdn_l2_norm(ctx, q_conv, eps_over_n);
    k_conv = build_gdn_l2_norm(ctx, k_conv, eps_over_n);

    // head repeat when H_v != H_k (qwen3next.cpp:518-537): reshape to insert a
    // singleton, repeat_4d over it, reshape back — repeat-interleave
    if num_k_heads != num_v_heads {
        assert_eq!(num_v_heads % num_k_heads, 0, "qwen3next: H_v % H_k");
        let repeat_factor = num_v_heads / num_k_heads;
        let q_r = ctx.reshape_4d(q_conv, head_k_dim, 1, num_k_heads, t);
        let k_r = ctx.reshape_4d(k_conv, head_k_dim, 1, num_k_heads, t);
        let q_r = ctx.repeat_4d(q_r, head_k_dim, repeat_factor, num_k_heads, t);
        let k_r = ctx.repeat_4d(k_r, head_k_dim, repeat_factor, num_k_heads, t);
        q_conv = ctx.reshape_4d(q_r, head_k_dim, num_k_heads * repeat_factor, t, 1);
        k_conv = ctx.reshape_4d(k_r, head_k_dim, num_k_heads * repeat_factor, t, 1);
    }

    // ---- the fused GDN op + the state write-back
    //      (build_recurrent_attn !keep, delta-net-base.cpp:546-560) ----
    let ssm_state = st.ssm[il].expect("qwen3next recurrent ssm state");
    let state = ctx.reshape_4d(ssm_state, head_v_dim, head_v_dim, num_v_heads, 1);
    let gdn_out = ctx.gated_delta_net(q_conv, k_conv, v_conv, gate, beta, state, 1);
    let out = ctx.view_4d(
        gdn_out,
        head_v_dim,
        num_v_heads,
        t,
        1,
        (head_v_dim * 4) as usize,
        (head_v_dim * num_v_heads * 4) as usize,
        (head_v_dim * num_v_heads * t * 4) as usize,
        0,
    );
    {
        let snap = ctx.view_4d(
            gdn_out,
            head_v_dim,
            head_v_dim,
            num_v_heads,
            1,
            (head_v_dim * 4) as usize,
            (head_v_dim * head_v_dim * 4) as usize,
            (head_v_dim * head_v_dim * num_v_heads * 4) as usize,
            (head_v_dim * num_v_heads * t * 4) as usize,
        );
        let st_nb = *ctx.nb(ssm_state);
        let dst = ctx.view_2d(ssm_state, p.n_embd_s as i64, 1, st_nb[1] as usize, 0);
        let cpy = ctx.cpy(snap, dst);
        graph.build_forward(ctx, cpy);
    }

    // ---- gated normalization + output projection (qwen3next.cpp:546-562) ----
    let z2 = ctx.reshape_4d(z, head_v_dim, num_v_heads, t, 1);
    let normed = build_norm_rms(ctx, out, lw.ssm_norm.expect("ssm_norm"), p.attn.norm_eps);
    let z_silu = ctx.silu(z2);
    let attn_out = ctx.mul(normed, z_silu);
    let final_out = ctx.reshape_3d(attn_out, head_v_dim * num_v_heads, t, 1);
    let cur = crate::adapter::lora_mm(ctx, lw.ssm_out.expect("ssm_out"), final_out);
    ctx.reshape_2d(cur, p.n_embd, t)
}

/// qwen3next.cpp:565-625 `build_layer_ffn` — softmax MoE (norm_w = true, the
/// routed_scaling_factor) plus the shared expert gated by its own
/// `sigmoid(ffn_gate_inp_shexp @ x)`.
#[allow(clippy::too_many_arguments)]
fn build_qwen3next_ffn(
    ctx: &mut Context,
    graph: &mut Graph,
    cur: TensorId,
    lw: &Qwen3NextLayerWeights,
    p: &Qwen3NextParams,
    il: usize,
) -> TensorId {
    let _ = il;
    // routed experts (qwen3next.cpp:569-583) — the fused gate_up variant
    // (create_tensor_gate_up_exps) spelled out like deepseek2's, else the
    // shared build_moe_ffn_silu over the separate gate/up tensors
    let moe_out = if let Some(gate_up) = lw.ffn_gate_up_exps {
        let n_embd = ctx.ne(cur)[0];
        let n_tokens = ctx.ne(cur)[1];
        let (n_expert, n_expert_used) = (p.n_expert, p.n_expert_used);
        let logits = crate::adapter::lora_mm(ctx, lw.ffn_gate_inp, cur);
        let probs = ctx.soft_max(logits); // LLAMA_EXPERT_GATING_FUNC_TYPE_SOFTMAX
        let selected = ctx.argsort_top_k(probs, n_expert_used as i32);
        let probs3 = ctx.reshape_3d(probs, 1, n_expert, n_tokens);
        let mut weights = ctx.get_rows(probs3, selected);
        // norm_w = true (qwen3next.cpp:578)
        let w2 = ctx.reshape_2d(weights, n_expert_used, n_tokens);
        let sum = ctx.sum_rows(w2);
        let sum = ctx.clamp(sum, 6.103515625e-5, f32::INFINITY);
        let w2 = ctx.div(w2, sum);
        weights = ctx.reshape_3d(w2, 1, n_expert_used, n_tokens);
        if p.expert_weights_scale != 0.0 && p.expert_weights_scale != 1.0 {
            weights = ctx.scale(weights, p.expert_weights_scale);
        }
        graph.build_forward(ctx, weights);

        // merged gate_up experts (llama-graph.cpp:2168-2186): one mul_mat_id,
        // split views, swiglu_split
        let cur3 = ctx.reshape_3d(cur, n_embd, 1, n_tokens);
        let gate_up = crate::adapter::lora_mm_id(ctx, gate_up, cur3, selected);
        let nb = *ctx.nb(gate_up);
        let n_ff = ctx.ne(gate_up)[0] / 2;
        let g = ctx.view_3d(
            gate_up,
            n_ff,
            n_expert_used,
            n_tokens,
            nb[1] as usize,
            nb[2] as usize,
            0,
        );
        let up = ctx.view_3d(
            gate_up,
            n_ff,
            n_expert_used,
            n_tokens,
            nb[1] as usize,
            nb[2] as usize,
            n_ff as usize * 4,
        );
        let act = ctx.swiglu_split(g, up);
        let mut experts = crate::adapter::lora_mm_id(ctx, lw.ffn_down_exps, act, selected);
        experts = ctx.mul(experts, weights);
        graph.build_forward(ctx, experts);
        // aggregate the k expert slabs (llama-graph.cpp:2329-2358): each view
        // is [n_embd, n_tokens] strided by nb2, not a 1-row view
        let nb1 = ctx.nb(experts)[1] as usize;
        let nb2 = ctx.nb(experts)[2] as usize;
        let mut acc = ctx.view_2d(experts, n_embd, n_tokens, nb2, 0);
        for e in 1..n_expert_used {
            let v = ctx.view_2d(experts, n_embd, n_tokens, nb2, (e as usize) * nb1);
            acc = ctx.add(acc, v);
        }
        acc
    } else {
        build_moe_ffn_silu(
            ctx,
            graph,
            cur,
            lw.ffn_gate_inp,
            None,
            lw.ffn_up_exps.expect("ffn_up_exps"),
            None,
            lw.ffn_gate_exps,
            None,
            lw.ffn_down_exps,
            None,
            None, // no exp_probs_b in qwen3next
            p.n_expert,
            p.n_expert_used,
            true, // norm_w (qwen3next.cpp:578)
            p.expert_weights_scale,
            EXPERT_GATING_SOFTMAX,
        )
    };

    // the shared expert + its own sigmoid gate (qwen3next.cpp:587-610)
    if let (Some(up), Some(gate), Some(down)) =
        (lw.ffn_up_shexp, lw.ffn_gate_shexp, lw.ffn_down_shexp)
    {
        let ffn_shexp = build_ffn_silu_par(ctx, cur, gate, None, up, None, down, None);
        let shared_gate =
            crate::adapter::lora_mm(ctx, lw.ffn_gate_inp_shexp.expect("ffn_gate_inp_shexp"), cur);
        let shared_gate = ctx.sigmoid(shared_gate);
        let shexp_gated = ctx.mul(ffn_shexp, shared_gate);
        ctx.add(moe_out, shexp_gated)
    } else {
        moe_out
    }
}

// ----------------------------------------------------------------------
// kimi-linear — verify against src/models/kimi-linear.cpp (KDA delta net + no-rope MLA
// + MoE with shared experts)
// ----------------------------------------------------------------------

pub struct KimiLinearLayerWeights {
    pub attn_norm: TensorId,
    /// KDA layers — the per-stream conv kernels. GGUF stores 4D
    /// [d_conv, 1, d_inner, 1] (or 3D after quantization), the graph reshapes
    /// to [d_conv, d_inner] (kimi-linear.cpp:59-72)
    pub ssm_q_conv: Option<TensorId>,
    pub ssm_k_conv: Option<TensorId>,
    pub ssm_v_conv: Option<TensorId>,
    /// KDA q/k/v projections (create_tensor_qkv with d_inner widths — the
    /// fused attn_qkv preferred, kimi-linear.cpp:76)
    pub wqkv: Option<TensorId>,
    pub wq: Option<TensorId>,
    pub wk: Option<TensorId>,
    pub wv: Option<TensorId>,
    /// f_a [n_embd, head_dim] / f_b [head_dim, d_inner] — the decay's two
    /// stages (kimi-linear.cpp:80-81)
    pub ssm_f_a: Option<TensorId>,
    pub ssm_f_b: Option<TensorId>,
    /// beta [n_embd, n_head] (kimi-linear.cpp:84)
    pub ssm_beta: Option<TensorId>,
    /// SSM_A_NOSCAN [1, n_head] — -exp(A_log) was applied at conversion
    /// (kimi-linear.cpp:87-90)
    pub ssm_a: Option<TensorId>,
    /// SSM_DT "bias" {d_inner} (kimi-linear.cpp:93)
    pub ssm_dt_b: Option<TensorId>,
    /// g_a [n_embd, head_dim] / g_b [head_dim, d_inner] — the output gate
    /// (kimi-linear.cpp:96-97)
    pub ssm_g_a: Option<TensorId>,
    pub ssm_g_b: Option<TensorId>,
    /// FusedRMSNormGated weight {head_dim} (kimi-linear.cpp:100)
    pub ssm_o_norm: Option<TensorId>,
    /// MLA layers: optional q compression (kimi-linear.cpp:112-121)
    pub wq_a: Option<TensorId>,
    pub attn_q_a_norm: Option<TensorId>,
    pub wq_b: Option<TensorId>,
    pub wq_mla: Option<TensorId>,
    pub wkv_a_mqa: Option<TensorId>,
    pub attn_kv_a_norm: Option<TensorId>,
    /// the split MLA KV cache variant (wk_b/wv_b, kimi-linear.cpp:130-133)
    pub wk_b: Option<TensorId>,
    pub wv_b: Option<TensorId>,
    /// the legacy unsplit wkv_b (MLA KV cache disabled, kimi-linear.cpp:128-129)
    pub wkv_b: Option<TensorId>,
    pub wo: TensorId,
    pub ffn_norm: TensorId,
    // dense lead FFN
    pub ffn_gate: Option<TensorId>,
    pub ffn_down: Option<TensorId>,
    pub ffn_up: Option<TensorId>,
    // MoE
    pub ffn_gate_inp: Option<TensorId>,
    pub ffn_gate_exps: Option<TensorId>,
    pub ffn_down_exps: Option<TensorId>,
    pub ffn_up_exps: Option<TensorId>,
    /// FFN_EXP_PROBS_B {n_expert} — REQUIRED on the MoE layers (kimi-linear.cpp:164)
    pub ffn_exp_probs_b: Option<TensorId>,
    pub ffn_gate_shexp: Option<TensorId>,
    pub ffn_down_shexp: Option<TensorId>,
    pub ffn_up_shexp: Option<TensorId>,
}

pub struct KimiLinearModelWeights {
    pub tok_embd: TensorId,
    pub output_norm: TensorId,
    pub output: TensorId,
    pub layers: Vec<KimiLinearLayerWeights>,
}

/// kimi-linear hparams + geometry (kimi-linear.cpp:4-32 / 254-276).
#[derive(Clone)]
pub struct KimiLinearParams {
    /// the MLA layers' cache geometry: the split-wk_b files cache
    /// [kv_lora_rank + qk_rope] per the single MQA head (head_count_kv = 1),
    /// the legacy wkv_b files cache [qk_head_dim * n_head] rows. n_embd_head_k
    /// / n_head_kv / n_embd_head_v here describe whatever the file carries.
    pub attn: AttnParams,
    pub n_embd: i64,
    pub n_head: i64,
    /// per-layer is_recr (n_head_kv == 0 marks KDA, kimi-linear.cpp:18)
    pub is_recr: Vec<bool>,
    /// hparams.n_embd_head_kda (kda.head_dim)
    pub n_embd_head_kda: i64,
    pub ssm_d_conv: i64,
    /// hparams.n_embd_head_k_mla (attention.key_length_mla — qk_head_dim)
    pub n_embd_head_k_mla: i64,
    pub n_embd_head_v_mla: i64,
    pub n_lora_kv: i64,
    /// hparams.n_rot == qk_rope_head_dim (kimi-linear.cpp:273)
    pub n_embd_head_qk_rope: i64,
    /// hparams.n_embd_r() / n_embd_s()
    pub n_embd_r: u32,
    pub n_embd_s: u32,
    pub n_layer_dense_lead: u32,
    pub n_expert: i64,
    pub n_expert_used: i64,
    pub expert_weights_scale: f32,
    /// llama_expert_gating_func_type as raw value (REQUIRED key)
    pub expert_gating_func: i32,
}

/// kimi-linear.cpp:175-232 `causal_conv1d` — the KDA per-stream causal
/// convolution. `qkv` picks the stream (0 = Q, 1 = K, 2 = V); the state cell
/// packs the three streams' [(d_conv-1) × d_inner] taps as
/// `conv_step + channel*(d_conv-1) + qkv*conv_state_size` per sequence.
#[allow(clippy::too_many_arguments)]
fn kimi_causal_conv1d(
    ctx: &mut Context,
    graph: &mut Graph,
    conv_state_all: TensorId,
    conv_states_all: TensorId,
    qkv: i64,
    x: TensorId,
    proj_w: Option<TensorId>,
    conv_w: TensorId,
    d_conv: i64,
    head_dim: i64,
    n_head: i64,
    n_seq_tokens: i64,
    n_seqs: i64,
    n_tokens: i64,
) -> TensorId {
    let d_inner = head_dim * n_head;
    let conv_state_size = (d_conv - 1) * d_inner;
    let n_embd_r_total = 3 * conv_state_size; // Q + K + V (kimi-linear.cpp:178)

    // the Q/K/V slice of the state cell, viewed [d_conv-1, d_inner, n_seqs]
    // (kimi-linear.cpp:190-193)
    let conv_state_x = ctx.view_3d(
        conv_state_all,
        d_conv - 1,
        d_inner,
        n_seqs,
        ((d_conv - 1) * 4) as usize,
        (n_embd_r_total * 4) as usize,
        (qkv * conv_state_size * 4) as usize,
    );

    // step 1: the projection, then [d_inner, n_seq_tokens, n_seqs]
    // (kimi-linear.cpp:198-201)
    let x_proj = match proj_w {
        Some(w) => ctx.mul_mat(w, x),
        None => x,
    };
    let x_3d = ctx.reshape_3d(x_proj, d_inner, n_seq_tokens, n_seqs);

    // concat state + current input (kimi-linear.cpp:204)
    let x_t = ctx.transpose(x_3d);
    let conv_x = ctx.concat(conv_state_x, x_t, 0);

    // save the last (d_conv-1) columns back (kimi-linear.cpp:207-215)
    {
        let cx_nb = *ctx.nb(conv_x);
        let last_conv_x = ctx.view_3d(
            conv_x,
            d_conv - 1,
            d_inner,
            n_seqs,
            cx_nb[1] as usize,
            cx_nb[2] as usize,
            (n_seq_tokens * cx_nb[0] as i64) as usize,
        );
        // single-seq/kv_head == 0: the offset (kv_head * n_embd_r_total +
        // qkv * conv_state_size) * esize reduces to the qkv slice
        let dst = ctx.view_3d(
            conv_states_all,
            d_conv - 1,
            d_inner,
            n_seqs,
            ((d_conv - 1) * 4) as usize,
            (n_embd_r_total * 4) as usize,
            (qkv * conv_state_size * 4) as usize,
        );
        let cpy = ctx.cpy(last_conv_x, dst);
        graph.build_forward(ctx, cpy);
    }

    // GGUF [d_conv, 1, d_inner, 1] → [d_conv, d_inner] (kimi-linear.cpp:222)
    let conv_weight = ctx.reshape_2d(conv_w, d_conv, d_inner);

    // conv + silu, back to [head_dim, n_head, T, S] (kimi-linear.cpp:226-231)
    let xcur = ctx.ssm_conv(conv_x, conv_weight);
    let xcur = ctx.reshape_2d(xcur, d_inner, n_tokens);
    let xcur = ctx.silu(xcur);
    ctx.reshape_4d(xcur, head_dim, n_head, n_seq_tokens, n_seqs)
}

/// verify against src/models/kimi-linear.cpp:234-562 `graph::graph` — per layer:
/// rms attn_norm → (KDA layer | no-rope MLA layer) → residual → rms ffn_norm
/// → (dense FFN | MoE + shared experts) → residual → final norm → lm_head.
///
/// * Kimi MLA applies NO RoPE (rotary_emb = None, kimi-linear.cpp:242/405).
/// * The KDA decay `g1 = softplus(f_b(f_a(x)) + dt_bias) * (-exp(A_log))` is
///   negative; the fused GDN op consumes it per key dim (the kda branch of
///   the kernel, gdn.rs).
/// * The o_norm gate is sigmoid (not SiLU — kimi-linear.cpp:373-374).
///
/// PARTIAL (reported): single sequence, K = 1 recurrent state
/// (`cparams.n_rs_seq == 0`); the MHA fallback of the legacy unsplit-wkv_b
/// files is ported (attn_kv_cached with the broadcast k_pe repeat).
pub fn build_kimi_linear_forward(
    ctx: &mut Context,
    w: &KimiLinearModelWeights,
    p: &KimiLinearParams,
    st: &RecurrentState,
    kv: &KvCache,
    inp: &DecodeInputs,
    _sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(8192);
    assert_eq!(
        p.is_recr.len(),
        n_layer,
        "KimiLinearParams::is_recr per layer"
    );
    assert_eq!(st.n_layer(), n_layer, "RecurrentState per layer");

    let n_head = p.n_head;
    let head_dim = p.n_embd_head_kda;
    let d_conv = p.ssm_d_conv;
    let d_inner = n_head * head_dim;
    let n_seqs = 1i64;
    let n_seq_tokens = t;

    // MLA dims (kimi-linear.cpp:268-276)
    let n_embd_head_k_mla = p.n_embd_head_k_mla;
    let n_embd_head_v_mla = p.n_embd_head_v_mla;
    let kv_lora_rank = p.n_lora_kv;
    let n_embd_head_qk_rope = p.n_embd_head_qk_rope;
    let n_embd_head_qk_nope = n_embd_head_k_mla - n_embd_head_qk_rope;
    let kq_scale_mla = 1.0f32 / (n_embd_head_k_mla as f32).sqrt();

    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_sa = inp_l;

        let cur = build_norm_rms(ctx, inp_l, lw.attn_norm, p.attn.norm_eps);

        let cur = if p.is_recr[il] {
            // === KDA layer (kimi-linear.cpp:289-384) ===
            let conv_states_all = st.conv[il].expect("kimi conv state");
            let ssm_states_all = st.ssm[il].expect("kimi ssm state");

            // the fused wqkv split, if the file carries one
            // (kimi-linear.cpp:300-308)
            let (q_in, k_in, v_in): (TensorId, TensorId, TensorId) = if let Some(wqkv) = lw.wqkv {
                let qkv = ctx.mul_mat(wqkv, cur);
                let nb1 = ctx.nb(qkv)[1] as usize;
                let q_v = ctx.view_2d(qkv, d_inner, t, nb1, 0);
                let k_v = ctx.view_2d(qkv, d_inner, t, nb1, (d_inner * 4) as usize);
                let v_v = ctx.view_2d(qkv, d_inner, t, nb1, (2 * d_inner * 4) as usize);
                let q = ctx.cont(q_v);
                let k = ctx.cont(k_v);
                let v = ctx.cont(v_v);
                (q, k, v)
            } else {
                (cur, cur, cur)
            };
            let (q_w, k_w, v_w) = if lw.wqkv.is_some() {
                (None, None, None)
            } else {
                (lw.wq, lw.wk, lw.wv)
            };

            // the three causal conv streams (kimi-linear.cpp:309-311)
            let mut qcur = kimi_causal_conv1d(
                ctx,
                &mut graph,
                conv_states_all,
                conv_states_all,
                0,
                q_in,
                q_w,
                lw.ssm_q_conv.expect("ssm_q_conv"),
                d_conv,
                head_dim,
                n_head,
                n_seq_tokens,
                n_seqs,
                t,
            );
            let mut kcur = kimi_causal_conv1d(
                ctx,
                &mut graph,
                conv_states_all,
                conv_states_all,
                1,
                k_in,
                k_w,
                lw.ssm_k_conv.expect("ssm_k_conv"),
                d_conv,
                head_dim,
                n_head,
                n_seq_tokens,
                n_seqs,
                t,
            );
            let vcur = kimi_causal_conv1d(
                ctx,
                &mut graph,
                conv_states_all,
                conv_states_all,
                2,
                v_in,
                v_w,
                lw.ssm_v_conv.expect("ssm_v_conv"),
                d_conv,
                head_dim,
                n_head,
                n_seq_tokens,
                n_seqs,
                t,
            );

            // g1 = softplus(f_b(f_a(x)) + dt_bias) * A (kimi-linear.cpp:314-327)
            let f_a = ctx.mul_mat(lw.ssm_f_a.expect("ssm_f_a"), cur);
            let mut g1 = ctx.mul_mat(lw.ssm_f_b.expect("ssm_f_b"), f_a);
            g1 = ctx.add(g1, lw.ssm_dt_b.expect("ssm_dt"));
            g1 = ctx.softplus(g1);
            g1 = ctx.reshape_3d(g1, head_dim, n_head, t);
            let a = ctx.reshape_3d(lw.ssm_a.expect("ssm_a"), 1, n_head, 1);
            let gate = ctx.mul(g1, a);
            let gate = ctx.reshape_4d(gate, head_dim, n_head, n_seq_tokens, n_seqs);

            // beta (kimi-linear.cpp:330-334)
            let beta = ctx.mul_mat(lw.ssm_beta.expect("ssm_beta"), cur);
            let beta = ctx.reshape_4d(beta, 1, n_head, n_seq_tokens, n_seqs);
            let beta = ctx.sigmoid(beta);

            // the state cell viewed [head_dim, head_dim, n_head, n_seqs]
            // (kimi-linear.cpp:341-343)
            let state = ctx.reshape_4d(ssm_states_all, head_dim, head_dim, n_head, n_seqs);

            // L2 norms (kimi-linear.cpp:348-349)
            let eps_over_n = p.attn.norm_eps / head_dim as f32;
            qcur = build_gdn_l2_norm(ctx, qcur, eps_over_n);
            kcur = build_gdn_l2_norm(ctx, kcur, eps_over_n);

            // the fused KDA GDN (build_delta_net_fused, K = 1) + write-back
            // (kimi-linear.cpp:352-363)
            let gdn_out = ctx.gated_delta_net(qcur, kcur, vcur, gate, beta, state, 1);
            let out_view = ctx.view_4d(
                gdn_out,
                head_dim,
                n_head,
                t,
                n_seqs,
                (head_dim * 4) as usize,
                (head_dim * n_head * 4) as usize,
                (head_dim * n_head * t * 4) as usize,
                0,
            );
            let output = ctx.cont(out_view);
            {
                let snap = ctx.view_4d(
                    gdn_out,
                    head_dim,
                    head_dim,
                    n_head,
                    n_seqs,
                    (head_dim * 4) as usize,
                    (head_dim * head_dim * 4) as usize,
                    (head_dim * head_dim * n_head * 4) as usize,
                    (head_dim * n_head * t * 4) as usize,
                );
                let st_nb = *ctx.nb(ssm_states_all);
                let dst = ctx.view_2d(ssm_states_all, p.n_embd_s as i64, 1, st_nb[1] as usize, 0);
                let cpy = ctx.cpy(snap, dst);
                graph.build_forward(ctx, cpy);
            }

            // the output gate g2 = g_b(g_a(x)) + sigmoid gating
            // (kimi-linear.cpp:366-379)
            let cur_2d = ctx.reshape_2d(cur, p.n_embd, t);
            let g_a = ctx.mul_mat(lw.ssm_g_a.expect("ssm_g_a"), cur_2d);
            let g2 = ctx.mul_mat(lw.ssm_g_b.expect("ssm_g_b"), g_a);
            let g2 = ctx.reshape_3d(g2, head_dim, n_head, t);

            let out = ctx.reshape_3d(output, head_dim, n_head, t);
            let normed = build_norm_rms(
                ctx,
                out,
                lw.ssm_o_norm.expect("ssm_o_norm"),
                p.attn.norm_eps,
            );
            let g2_sig = ctx.sigmoid(g2);
            let gated = ctx.mul(normed, g2_sig);

            // o_proj (kimi-linear.cpp:382-383)
            let gated = ctx.cont_2d(gated, d_inner, t);
            ctx.mul_mat(lw.wo, gated)
        } else {
            // === MLA layer without RoPE (kimi-linear.cpp:387-484) ===
            let qcur = ctx.mul_mat(lw.wq_mla.expect("wq"), cur);

            // kv compression (kimi-linear.cpp:396-408)
            let kv_cmpr_pe = ctx.mul_mat(lw.wkv_a_mqa.expect("wkv_a_mqa"), cur);
            let rs_row = GgmlType::F32.row_size((kv_lora_rank + n_embd_head_qk_rope) as usize);
            let kv_cmpr = ctx.view_2d(kv_cmpr_pe, kv_lora_rank, t, rs_row, 0);
            let k_pe = ctx.view_3d(
                kv_cmpr_pe,
                n_embd_head_qk_rope,
                1,
                t,
                rs_row,
                rs_row,
                GgmlType::F32.row_size(kv_lora_rank as usize),
            );
            let kv_cmpr = build_norm_rms(
                ctx,
                kv_cmpr,
                lw.attn_kv_a_norm.expect("attn_kv_a_norm"),
                p.attn.norm_eps,
            );

            if lw.wk_b.is_some() && lw.wv_b.is_some() {
                // the split MLA KV cache path (kimi-linear.cpp:410-452)
                let rs_head = GgmlType::F32.row_size(n_embd_head_k_mla as usize);
                let q_nope = ctx.view_3d(
                    qcur,
                    n_embd_head_qk_nope,
                    n_head,
                    t,
                    rs_head,
                    rs_head * n_head as usize,
                    0,
                );
                let q_pe = ctx.view_3d(
                    qcur,
                    n_embd_head_qk_rope,
                    n_head,
                    t,
                    rs_head,
                    rs_head * n_head as usize,
                    (n_embd_head_qk_nope * 4) as usize,
                );
                let q_nope = ctx.permute(q_nope, 0, 2, 1, 3);
                let q_nope_absorbed = ctx.mul_mat(lw.wk_b.expect("wk_b"), q_nope);
                let q_nope_absorbed = ctx.permute(q_nope_absorbed, 0, 2, 1, 3);

                // {qk_nope_absorbed | q_pe} — nope first (kimi-linear.cpp:437)
                let q_all = ctx.concat(q_nope_absorbed, q_pe, 0);

                let kv_3d = ctx.reshape_3d(kv_cmpr, kv_lora_rank, 1, t);
                let k_all = ctx.concat(kv_3d, k_pe, 0);

                attn_k_cached_mla(
                    ctx,
                    &mut graph,
                    kv,
                    il,
                    &p.attn,
                    inp,
                    n_kv,
                    q_all,
                    k_all,
                    kv_3d,
                    kq_scale_mla,
                    lw.wv_b.expect("wv_b"),
                    // kimi passes layer.wo into build_attn (kimi-linear.cpp:451)
                    Some(lw.wo),
                    None,
                )
            } else {
                // the legacy unsplit-wkv_b MHA fallback (kimi-linear.cpp:453-483)
                let q3 = ctx.reshape_3d(qcur, n_embd_head_k_mla, n_head, t);
                let kv_dec = ctx.mul_mat(lw.wkv_b.expect("wkv_b"), kv_cmpr);
                let kv_per_head = n_embd_head_qk_nope + n_embd_head_v_mla;
                let rs_ph = GgmlType::F32.row_size(kv_per_head as usize);
                let k_nope = ctx.view_3d(
                    kv_dec,
                    n_embd_head_qk_nope,
                    n_head,
                    t,
                    rs_ph,
                    rs_ph * n_head as usize,
                    0,
                );
                let vcur = ctx.view_3d(
                    kv_dec,
                    n_embd_head_v_mla,
                    n_head,
                    t,
                    rs_ph,
                    rs_ph * n_head as usize,
                    (n_embd_head_qk_nope * 4) as usize,
                );
                let vcur = ctx.cont(vcur);

                // broadcast k_pe to all heads (kimi-linear.cpp:475-477 —
                // ggml_repeat onto a throwaway [rope, n_head, T] target)
                let k_pe_rep = ctx.repeat_4d(k_pe, n_embd_head_qk_rope, n_head, t, 1);
                // K = [k_pe | k_nope] — rope part first in the legacy layout
                // (kimi-linear.cpp:477)
                let k_all = ctx.concat(k_pe_rep, k_nope, 0);

                attn_kv_cached(
                    ctx,
                    &mut graph,
                    kv,
                    il,
                    &p.attn,
                    inp,
                    n_kv,
                    q3,
                    k_all,
                    vcur,
                    kq_scale_mla,
                    0.0,
                    None,
                    None,
                    Some(lw.wo),
                    None,
                )
            }
        };

        // residual (kimi-linear.cpp:488-494)
        let ffn_inp = ctx.add(cur, inp_sa);

        // FFN (kimi-linear.cpp:498-538)
        let normed = build_norm_rms(ctx, ffn_inp, lw.ffn_norm, p.attn.norm_eps);
        let out = if (il as u32) < p.n_layer_dense_lead {
            // dense FFN
            build_ffn_silu_par(
                ctx,
                normed,
                lw.ffn_gate.expect("ffn_gate"),
                None,
                lw.ffn_up.expect("ffn_up"),
                None,
                lw.ffn_down.expect("ffn_down"),
                None,
            )
        } else {
            // MoE + shared experts (kimi-linear.cpp:512-537)
            let moe_out = build_moe_ffn_silu(
                ctx,
                &mut graph,
                normed,
                lw.ffn_gate_inp.expect("ffn_gate_inp"),
                None,
                lw.ffn_up_exps.expect("ffn_up_exps"),
                None,
                lw.ffn_gate_exps,
                None,
                lw.ffn_down_exps.expect("ffn_down_exps"),
                None,
                lw.ffn_exp_probs_b,
                p.n_expert,
                p.n_expert_used,
                true, // moe_renormalize = true (kimi-linear.cpp:520)
                p.expert_weights_scale,
                p.expert_gating_func,
            );
            match (lw.ffn_up_shexp, lw.ffn_gate_shexp, lw.ffn_down_shexp) {
                (Some(up), Some(gate), Some(down)) => {
                    let shexp = build_ffn_silu_par(ctx, normed, gate, None, up, None, down, None);
                    ctx.add(moe_out, shexp)
                }
                _ => moe_out,
            }
        };

        // residual (kimi-linear.cpp:540)
        inp_l = ctx.add(out, ffn_inp);
    }

    // final norm + lm_head (kimi-linear.cpp:548-561)
    let cur = build_norm_rms(ctx, inp_l, w.output_norm, p.attn.norm_eps);
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let logits = ctx.mul_mat(w.output, cur);
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

// ----------------------------------------------------------------------
// bailingmoe3 — verify against src/models/bailingmoe3.cpp (KDA delta net with the safe
// gate + MLA with the output gate + swiglu_clamp FFNs)
// ----------------------------------------------------------------------

pub struct BailingMoe3LayerWeights {
    pub attn_norm: TensorId,
    /// KDA layers — 4D [d_conv, 1, d_inner, 1] conv kernels (bailingmoe3.cpp:82-84)
    pub ssm_q_conv: Option<TensorId>,
    pub ssm_k_conv: Option<TensorId>,
    pub ssm_v_conv: Option<TensorId>,
    /// KDA q/k/v (create_tensor_qkv — fused or separate, bailingmoe3.cpp:86)
    pub wqkv: Option<TensorId>,
    pub wq: Option<TensorId>,
    pub wk: Option<TensorId>,
    pub wv: Option<TensorId>,
    /// f_a [n_embd, d_inner] — the safe gate's single stage (bailingmoe3.cpp:87)
    pub ssm_f_a: Option<TensorId>,
    /// beta [n_embd, n_head] (bailingmoe3.cpp:88)
    pub ssm_beta: Option<TensorId>,
    /// SSM_A_NOSCAN [1, n_head] (bailingmoe3.cpp:89)
    pub ssm_a: Option<TensorId>,
    /// SSM_DT "bias" {d_inner} (bailingmoe3.cpp:90)
    pub ssm_dt_b: Option<TensorId>,
    /// g_a [n_embd, d_inner] — the output gate (bailingmoe3.cpp:91)
    pub ssm_g_a: Option<TensorId>,
    /// FusedRMSNormGated weight {head_dim} (bailingmoe3.cpp:92)
    pub ssm_o_norm: Option<TensorId>,
    /// MLA layers: the optional q compression (bailingmoe3.cpp:95-101)
    pub wq_a: Option<TensorId>,
    pub attn_q_a_norm: Option<TensorId>,
    pub wq_b: Option<TensorId>,
    pub wq_mla: Option<TensorId>,
    pub wkv_a_mqa: Option<TensorId>,
    pub attn_kv_a_norm: Option<TensorId>,
    pub wk_b: Option<TensorId>,
    pub wv_b: Option<TensorId>,
    /// ATTN_GATE [n_embd, n_head] — the attention output gate
    /// (bailingmoe3.cpp:106)
    pub wqkv_gate: Option<TensorId>,
    pub wo: TensorId,
    pub ffn_norm: TensorId,
    // dense lead FFN
    pub ffn_gate: Option<TensorId>,
    pub ffn_down: Option<TensorId>,
    pub ffn_up: Option<TensorId>,
    // MoE
    pub ffn_gate_inp: Option<TensorId>,
    pub ffn_gate_exps: Option<TensorId>,
    pub ffn_down_exps: Option<TensorId>,
    pub ffn_up_exps: Option<TensorId>,
    /// FFN_EXP_PROBS_B {n_expert} — REQUIRED on the MoE layers (bailingmoe3.cpp:117)
    pub ffn_exp_probs_b: Option<TensorId>,
    pub ffn_gate_shexp: Option<TensorId>,
    pub ffn_down_shexp: Option<TensorId>,
    pub ffn_up_shexp: Option<TensorId>,
}

pub struct BailingMoe3ModelWeights {
    pub tok_embd: TensorId,
    pub output_norm: TensorId,
    /// bailingmoe3.cpp:52-55 — optional, tied to tok_embd when absent
    pub output: TensorId,
    /// trunk layers only — the MTP/nextn blocks are extra blocks the main
    /// pass never executes (bailingmoe3.cpp:127-158; the qwen35 convention)
    pub layers: Vec<BailingMoe3LayerWeights>,
}

/// bailingmoe3 hparams + geometry (bailingmoe3.cpp:6-44 / 230-245).
#[derive(Clone)]
pub struct BailingMoe3Params {
    /// the MLA layers' cache geometry: [kv_lora_rank + qk_rope] per the
    /// single MQA head (head_count_kv = 1 on the attention layers)
    pub attn: AttnParams,
    pub n_embd: i64,
    pub n_head: i64,
    /// per-layer is_recr (n_head_kv == 0 marks KDA, bailingmoe3.cpp:36)
    pub is_recr: Vec<bool>,
    pub n_embd_head_kda: i64,
    pub ssm_d_conv: i64,
    /// hparams.kda_gate_lower_bound (< 0, REQUIRED)
    pub kda_gate_lower_bound: f32,
    /// hparams.n_embd_head_k_mla (qk_head_dim)
    pub n_embd_head_k_mla: i64,
    pub n_embd_head_v_mla: i64,
    pub n_lora_kv: i64,
    /// hparams.n_lora_q (optional; 0 → the direct wq path)
    pub n_lora_q: i64,
    /// hparams.n_rot == qk_rope_head_dim
    pub n_embd_head_qk_rope: i64,
    /// hparams.rope_sections (bailingmoe3.cpp:18, def4d406a) — VL files
    /// carry M-RoPE sections; [0;4] keeps the plain rope
    pub rope_sections: [i32; 4],
    /// hparams.n_embd_r() / n_embd_s()
    pub n_embd_r: u32,
    pub n_embd_s: u32,
    pub n_layer_dense_lead: u32,
    pub n_expert: i64,
    pub n_expert_used: i64,
    pub expert_weights_norm: bool,
    pub expert_weights_scale: f32,
    pub expert_gating_func: i32,
    /// hparams.swiglu_clamp_exp / swiglu_clamp_shexp per layer (0 = no clamp)
    pub swiglu_clamp_exp: Vec<f32>,
    pub swiglu_clamp_shexp: Vec<f32>,
}

/// bailingmoe3.cpp:168-216 `bailingmoe3_causal_conv1d` — the KDA per-stream
/// causal convolution with the rollback-snapshot loop (the port runs the
/// n_rs_seq == 0 arm: exactly one snapshot, slot 0).
#[allow(clippy::too_many_arguments)]
fn bailingmoe3_causal_conv1d(
    ctx: &mut Context,
    graph: &mut Graph,
    conv_states_all: TensorId,
    qkv: i64,
    x: TensorId,
    proj_w: TensorId,
    conv_w: TensorId,
    d_conv: i64,
    head_dim: i64,
    n_head: i64,
    n_seq_tokens: i64,
    n_seqs: i64,
    n_tokens: i64,
) -> TensorId {
    let d_inner = head_dim * n_head;
    let conv_state_size = (d_conv - 1) * d_inner;
    let total_state_size = 3 * conv_state_size; // bailingmoe3.cpp:188

    // the Q/K/V slice of the state cell (bailingmoe3.cpp:190-193)
    let conv_state = ctx.view_3d(
        conv_states_all,
        d_conv - 1,
        d_inner,
        n_seqs,
        ((d_conv - 1) * 4) as usize,
        (total_state_size * 4) as usize,
        (qkv * conv_state_size * 4) as usize,
    );

    let x_proj = ctx.mul_mat(proj_w, x);
    let x_proj = ctx.reshape_3d(x_proj, d_inner, n_seq_tokens, n_seqs);
    let x_t = ctx.transpose(x_proj);
    let conv_x = ctx.concat(conv_state, x_t, 0);

    // n_written = min(n_seq_tokens, K = n_rs_seq + 1 = 1) → the single
    // slot-0 snapshot (bailingmoe3.cpp:199-210)
    {
        let (cx_ne, cx_nb) = (*ctx.ne(conv_x), *ctx.nb(conv_x));
        let conv_snap = ctx.view_3d(
            conv_x,
            d_conv - 1,
            d_inner,
            n_seqs,
            cx_nb[1] as usize,
            cx_nb[2] as usize,
            ((cx_ne[0] - (d_conv - 1)) * cx_nb[0] as i64) as usize,
        );
        // ((slot * mem_size + cache_head) * total + qkv * cs) * esize with
        // slot = cache_head = 0 — the qkv slice
        let dst = ctx.view_3d(
            conv_states_all,
            d_conv - 1,
            d_inner,
            n_seqs,
            ((d_conv - 1) * 4) as usize,
            (total_state_size * 4) as usize,
            (qkv * conv_state_size * 4) as usize,
        );
        let cpy = ctx.cpy(conv_snap, dst);
        graph.build_forward(ctx, cpy);
    }

    // conv + silu (bailingmoe3.cpp:212-215)
    let conv_weight = ctx.reshape_2d(conv_w, d_conv, d_inner);
    let out = ctx.ssm_conv(conv_x, conv_weight);
    let out = ctx.reshape_2d(out, d_inner, n_tokens);
    let out = ctx.silu(out);
    ctx.reshape_4d(out, head_dim, n_head, n_seq_tokens, n_seqs)
}

/// verify against src/models/bailingmoe3.cpp:218-410 `graph::graph` — per layer:
/// rms attn_norm → (KDA layer | gated MLA layer) → residual → rms ffn_norm →
/// (dense FFN | MoE + shared expert, the swiglu_clamp limits where set) →
/// residual → final norm → lm_head.
///
/// * the KDA "safe gate": `gate = kda_gate_lower_bound * sigmoid(a * (f_a·x
///   + dt_bias))` — a bounded negative decay (bailingmoe3.cpp:272-278).
/// * the MLA layers rope only the q_pe/k_pe tails (NEOX) and gate the
///   attention output with `sigmoid(attn_gate · attn_input)`
///   (bailingmoe3.cpp:329-349).
/// * the swiglu_clamp limits ride the shared build_ffn / build_moe_ffn
///   (llama-graph.cpp:1822-1846 / :2210-2240 — bailingmoe3 takes the
///   generic clamp branch, not the fused ggml_swiglu_clamp one).
///
/// PARTIAL (reported): single sequence, K = 1 recurrent state
/// (`cparams.n_rs_seq == 0`); the MTP/nextn blocks are skipped (`graph_mtp`,
/// bailingmoe3.cpp:412-540 — extra decoder blocks).
pub fn build_bailingmoe3_forward(
    ctx: &mut Context,
    w: &BailingMoe3ModelWeights,
    p: &BailingMoe3Params,
    st: &RecurrentState,
    kv: &KvCache,
    inp: &DecodeInputs,
    _sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(8192);
    assert_eq!(
        p.is_recr.len(),
        n_layer,
        "BailingMoe3Params::is_recr per layer"
    );
    assert_eq!(st.n_layer(), n_layer, "RecurrentState per layer");

    let n_head = p.n_head;
    let head_dim = p.n_embd_head_kda;
    let d_inner = n_head * head_dim;
    let d_conv = p.ssm_d_conv;
    let n_seqs = 1i64;
    let n_seq_tokens = t;

    let qk_head_dim = p.n_embd_head_k_mla;
    let v_head_dim = p.n_embd_head_v_mla;
    let qk_rope_head_dim = p.n_embd_head_qk_rope;
    let qk_nope_head_dim = qk_head_dim - qk_rope_head_dim;
    let kv_lora_rank = p.n_lora_kv;
    let kq_scale = 1.0f32 / (qk_head_dim as f32).sqrt();

    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_sa = inp_l;

        let cur = build_norm_rms(ctx, inp_l, lw.attn_norm, p.attn.norm_eps);

        let cur = if p.is_recr[il] {
            // === KDA layer (bailingmoe3.cpp:255-299) ===
            let conv_states_all = st.conv[il].expect("bailingmoe3 conv state");
            let states_all = st.ssm[il].expect("bailingmoe3 ssm state");

            // the three conv streams (bailingmoe3.cpp:262-270) — the C
            // passes layer.wq/wk/wv directly (a fused attn_qkv file would
            // hand ggml_mul_mat a nullptr and crash the reference, so the
            // separate tensors are the only usable layout)
            let q_conv = bailingmoe3_causal_conv1d(
                ctx,
                &mut graph,
                conv_states_all,
                0,
                cur,
                lw.wq.expect("wq"),
                lw.ssm_q_conv.expect("ssm_q_conv"),
                d_conv,
                head_dim,
                n_head,
                n_seq_tokens,
                n_seqs,
                t,
            );
            let k_conv = bailingmoe3_causal_conv1d(
                ctx,
                &mut graph,
                conv_states_all,
                1,
                cur,
                lw.wk.expect("wk"),
                lw.ssm_k_conv.expect("ssm_k_conv"),
                d_conv,
                head_dim,
                n_head,
                n_seq_tokens,
                n_seqs,
                t,
            );
            let v_conv = bailingmoe3_causal_conv1d(
                ctx,
                &mut graph,
                conv_states_all,
                2,
                cur,
                lw.wv.expect("wv"),
                lw.ssm_v_conv.expect("ssm_v_conv"),
                d_conv,
                head_dim,
                n_head,
                n_seq_tokens,
                n_seqs,
                t,
            );

            // the safe gate (bailingmoe3.cpp:272-278)
            let mut gate = ctx.mul_mat(lw.ssm_f_a.expect("ssm_f_a"), cur);
            gate = ctx.add(gate, lw.ssm_dt_b.expect("ssm_dt"));
            gate = ctx.reshape_3d(gate, head_dim, n_head, t);
            let a = ctx.reshape_3d(lw.ssm_a.expect("ssm_a"), 1, n_head, 1);
            gate = ctx.mul(gate, a);
            gate = ctx.sigmoid(gate);
            gate = ctx.scale(gate, p.kda_gate_lower_bound);
            let gate = ctx.reshape_4d(gate, head_dim, n_head, n_seq_tokens, n_seqs);

            // beta (bailingmoe3.cpp:280-281)
            let beta = ctx.mul_mat(lw.ssm_beta.expect("ssm_beta"), cur);
            let beta = ctx.reshape_4d(beta, 1, n_head, n_seq_tokens, n_seqs);
            let beta = ctx.sigmoid(beta);

            // L2 norms (bailingmoe3.cpp:283-284)
            let eps_over_n = p.attn.norm_eps / head_dim as f32;
            let q_conv = build_gdn_l2_norm(ctx, q_conv, eps_over_n);
            let k_conv = build_gdn_l2_norm(ctx, k_conv, eps_over_n);

            // the state cell viewed [head_dim, head_dim, n_head, n_seqs]
            // (bailingmoe3.cpp:286-288)
            let state = ctx.reshape_4d(states_all, head_dim, head_dim, n_head, n_seqs);

            // the fused KDA GDN (K = 1) + the state write-back
            // (build_recurrent_attn !keep, delta-net-base.cpp:546-560)
            let gdn_out = ctx.gated_delta_net(q_conv, k_conv, v_conv, gate, beta, state, 1);
            let output = ctx.view_4d(
                gdn_out,
                head_dim,
                n_head,
                t,
                n_seqs,
                (head_dim * 4) as usize,
                (head_dim * n_head * 4) as usize,
                (head_dim * n_head * t * 4) as usize,
                0,
            );
            {
                let snap = ctx.view_4d(
                    gdn_out,
                    head_dim,
                    head_dim,
                    n_head,
                    n_seqs,
                    (head_dim * 4) as usize,
                    (head_dim * head_dim * 4) as usize,
                    (head_dim * head_dim * n_head * 4) as usize,
                    (head_dim * n_head * t * 4) as usize,
                );
                let st_nb = *ctx.nb(states_all);
                let dst = ctx.view_2d(states_all, p.n_embd_s as i64, 1, st_nb[1] as usize, 0);
                let cpy = ctx.cpy(snap, dst);
                graph.build_forward(ctx, cpy);
            }
            let output = ctx.cont(output);

            // the output gate (bailingmoe3.cpp:293-298)
            let out_gate = ctx.mul_mat(lw.ssm_g_a.expect("ssm_g_a"), cur);
            let out_gate = ctx.reshape_3d(out_gate, head_dim, n_head, t);
            let output = ctx.reshape_3d(output, head_dim, n_head, t);
            let output = build_norm_rms(
                ctx,
                output,
                lw.ssm_o_norm.expect("ssm_o_norm"),
                p.attn.norm_eps,
            );
            let og_sig = ctx.sigmoid(out_gate);
            let output = ctx.mul(output, og_sig);
            let out_c = ctx.cont_2d(output, d_inner, t);
            ctx.mul_mat(lw.wo, out_c)
        } else {
            // === the gated MLA layer (bailingmoe3.cpp:300-352) ===
            let attn_input = cur;
            let q_all = if let (Some(wq_a), Some(q_a_norm), Some(wq_b)) =
                (lw.wq_a, lw.attn_q_a_norm, lw.wq_b)
            {
                let q_a = ctx.mul_mat(wq_a, cur);
                let q_a = build_norm_rms(ctx, q_a, q_a_norm, p.attn.norm_eps);
                ctx.mul_mat(wq_b, q_a)
            } else {
                ctx.mul_mat(lw.wq_mla.expect("wq"), cur)
            };

            let rs_head = GgmlType::F32.row_size(qk_head_dim as usize);
            let q_nope = ctx.view_3d(
                q_all,
                qk_nope_head_dim,
                n_head,
                t,
                rs_head,
                rs_head * n_head as usize,
                0,
            );
            let q_pe = ctx.view_3d(
                q_all,
                qk_rope_head_dim,
                n_head,
                t,
                rs_head,
                rs_head * n_head as usize,
                (qk_nope_head_dim * 4) as usize,
            );

            let kv_all = ctx.mul_mat(lw.wkv_a_mqa.expect("wkv_a_mqa"), cur);
            let rs_row = GgmlType::F32.row_size((kv_lora_rank + qk_rope_head_dim) as usize);
            let kv_c = ctx.view_2d(kv_all, kv_lora_rank, t, rs_row, 0);
            let k_pe = ctx.view_3d(
                kv_all,
                qk_rope_head_dim,
                1,
                t,
                rs_row,
                rs_row,
                GgmlType::F32.row_size(kv_lora_rank as usize),
            );

            // rope only the q_pe/k_pe tails (bailingmoe3.cpp:329-332; the
            // M-RoPE branch of :334-341, def4d406a — VL files carry sections)
            let use_mrope = p.rope_sections[0] > 0 && p.rope_sections[1] > 0;
            let sections = p.rope_sections;
            let rope = |ctx: &mut Context, x: TensorId| {
                if use_mrope {
                    ctx.rope_multi(
                        x,
                        inp.pos,
                        None,
                        p.attn.n_rot as i32,
                        sections,
                        p.attn.rope_mode,
                        p.attn.n_ctx_orig,
                        p.attn.freq_base,
                        p.attn.freq_scale,
                        p.attn.ext_factor,
                        p.attn.attn_factor,
                        p.attn.beta_fast,
                        p.attn.beta_slow,
                    )
                } else {
                    ctx.rope_ext(
                        x,
                        inp.pos,
                        None,
                        p.attn.n_rot as i32,
                        p.attn.rope_mode,
                        p.attn.n_ctx_orig,
                        p.attn.freq_base,
                        p.attn.freq_scale,
                        p.attn.ext_factor,
                        p.attn.attn_factor,
                        p.attn.beta_fast,
                        p.attn.beta_slow,
                    )
                }
            };
            let q_pe = rope(ctx, q_pe);
            let k_pe = rope(ctx, k_pe);
            let kv_n = build_norm_rms(
                ctx,
                kv_c,
                lw.attn_kv_a_norm.expect("attn_kv_a_norm"),
                p.attn.norm_eps,
            );

            // absorb wk_b into q_nope (bailingmoe3.cpp:335-339)
            let q_nope = ctx.permute(q_nope, 0, 2, 1, 3);
            let q_nope = ctx.mul_mat(lw.wk_b.expect("wk_b"), q_nope);
            let q_nope = ctx.permute(q_nope, 0, 2, 1, 3);
            let q = ctx.concat(q_nope, q_pe, 0);

            let kv_3d = ctx.reshape_3d(kv_n, kv_lora_rank, 1, t);
            let k = ctx.concat(kv_3d, k_pe, 0);

            let cur = attn_k_cached_mla(
                ctx,
                &mut graph,
                kv,
                il,
                &p.attn,
                inp,
                n_kv,
                q,
                k,
                kv_3d,
                kq_scale,
                lw.wv_b.expect("wv_b"),
                // build_attn's wo == nullptr — the o_proj runs after the
                // sigmoid attention gate (bailingmoe3.cpp:343→350)
                None,
                None,
            );

            // the attention output gate (bailingmoe3.cpp:346-350)
            let attn_gate = ctx.mul_mat(lw.wqkv_gate.expect("wqkv_gate"), attn_input);
            let attn_gate = ctx.reshape_3d(attn_gate, 1, n_head, t);
            let attn_gate = ctx.sigmoid(attn_gate);
            let cur = ctx.reshape_3d(cur, v_head_dim, n_head, t);
            let cur = ctx.mul(cur, attn_gate);
            let cur_c = ctx.cont_2d(cur, v_head_dim * n_head, t);
            ctx.mul_mat(lw.wo, cur_c)
        };

        // residual (bailingmoe3.cpp:359)
        let ffn_inp = ctx.add(cur, inp_sa);
        let normed = build_norm_rms(ctx, ffn_inp, lw.ffn_norm, p.attn.norm_eps);

        let out = if (il as u32) < p.n_layer_dense_lead {
            // dense FFN with the shexp clamp limit (build_ffn's SILU+PAR arm,
            // llama-graph.cpp:1822-1846 — bailingmoe3 takes the generic
            // clamp branch)
            let limit = p.swiglu_clamp_shexp.get(il).copied().unwrap_or(0.0);
            let up = crate::adapter::lora_mm(ctx, lw.ffn_up.expect("ffn_up"), normed);
            let gate = crate::adapter::lora_mm(ctx, lw.ffn_gate.expect("ffn_gate"), normed);
            let act = silu_par_clamped(ctx, gate, up, limit);
            crate::adapter::lora_mm(ctx, lw.ffn_down.expect("ffn_down"), act)
        } else {
            // MoE + shared expert (bailingmoe3.cpp:369-386), both under their
            // swiglu_clamp limits
            let limit = p.swiglu_clamp_exp.get(il).copied().unwrap_or(0.0);
            let moe = build_bailingmoe3_moe(ctx, &mut graph, normed, lw, p, limit);
            let sh_limit = p.swiglu_clamp_shexp.get(il).copied().unwrap_or(0.0);
            let up = crate::adapter::lora_mm(ctx, lw.ffn_up_shexp.expect("ffn_up_shexp"), normed);
            let gate =
                crate::adapter::lora_mm(ctx, lw.ffn_gate_shexp.expect("ffn_gate_shexp"), normed);
            let shexp = silu_par_clamped(ctx, gate, up, sh_limit);
            let shexp =
                crate::adapter::lora_mm(ctx, lw.ffn_down_shexp.expect("ffn_down_shexp"), shexp);
            ctx.add(moe, shexp)
        };

        // residual (bailingmoe3.cpp:389)
        inp_l = ctx.add(out, ffn_inp);
    }

    // final norm + lm_head (bailingmoe3.cpp:395-409; the t_h_nextn tap and
    // the inp_out_ids get_rows reduce rows only)
    let cur = build_norm_rms(ctx, inp_l, w.output_norm, p.attn.norm_eps);
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let logits = ctx.mul_mat(w.output, cur);
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

/// `silu(gate) * up` with the generic swiglu_clamp limit
/// (llama-graph.cpp:1822-1846 / :2210-2240 — the non-fused branch:
/// `up = clamp(up, -limit, limit); act = clamp(silu(gate), -inf, limit)`;
/// `limit <= 1e-6` skips the clamps).
fn silu_par_clamped(ctx: &mut Context, gate: TensorId, up: TensorId, limit: f32) -> TensorId {
    const EPS: f32 = 1e-6;
    if !(limit > EPS) {
        let act = ctx.silu(gate);
        return ctx.mul(act, up);
    }
    let up = ctx.clamp(up, -limit, limit);
    let act = ctx.silu(gate);
    let act = ctx.clamp(act, f32::NEG_INFINITY, limit);
    ctx.mul(act, up)
}

/// build_moe_ffn with the bailingmoe3 knobs — spelled out (the deepseek2
/// style) because the swiglu_clamp_exp limit replaces the silu×up step
/// between the expert matmuls (llama-graph.cpp:2210-2240).
#[allow(clippy::too_many_arguments)]
fn build_bailingmoe3_moe(
    ctx: &mut Context,
    graph: &mut Graph,
    cur: TensorId,
    lw: &BailingMoe3LayerWeights,
    p: &BailingMoe3Params,
    limit: f32,
) -> TensorId {
    let n_embd = ctx.ne(cur)[0];
    let n_tokens = ctx.ne(cur)[1];
    let (n_expert, n_expert_used) = (p.n_expert, p.n_expert_used);

    // routing (llama-graph.cpp:2021-2163)
    let logits = crate::adapter::lora_mm(ctx, lw.ffn_gate_inp.expect("ffn_gate_inp"), cur);
    let probs = match p.expert_gating_func {
        EXPERT_GATING_SOFTMAX => ctx.soft_max(logits),
        EXPERT_GATING_SIGMOID => ctx.sigmoid(logits),
        EXPERT_GATING_SOFTMAX_WEIGHT => logits,
        other => unimplemented!("bailingmoe3: gating op {other}"),
    };
    // the e-score bias steers the top-k only (llama-graph.cpp:2062-2067)
    let selection_probs = match lw.ffn_exp_probs_b {
        Some(b) => ctx.add(probs, b),
        None => probs,
    };
    let selected = ctx.argsort_top_k(selection_probs, n_expert_used as i32);
    let probs3 = ctx.reshape_3d(probs, 1, n_expert, n_tokens);
    let mut weights = ctx.get_rows(probs3, selected);
    if p.expert_gating_func == EXPERT_GATING_SOFTMAX_WEIGHT {
        let w2 = ctx.reshape_2d(weights, n_expert_used, n_tokens);
        let w2 = ctx.soft_max(w2);
        weights = ctx.reshape_3d(w2, 1, n_expert_used, n_tokens);
    }
    if p.expert_weights_norm {
        let w2 = ctx.reshape_2d(weights, n_expert_used, n_tokens);
        let sum = ctx.sum_rows(w2);
        let sum = ctx.clamp(sum, 6.103515625e-5, f32::INFINITY);
        let w2 = ctx.div(w2, sum);
        weights = ctx.reshape_3d(w2, 1, n_expert_used, n_tokens);
    }
    if p.expert_weights_scale != 0.0 && p.expert_weights_scale != 1.0 {
        weights = ctx.scale(weights, p.expert_weights_scale);
    }
    graph.build_forward(ctx, weights);

    // experts (llama-graph.cpp:2168-2245) — gate/up/down per selected expert,
    // the swiglu_clamp limit replacing the plain silu×up when set
    let cur3 = ctx.reshape_3d(cur, n_embd, 1, n_tokens);
    let up = crate::adapter::lora_mm_id(ctx, lw.ffn_up_exps.expect("ffn_up_exps"), cur3, selected);
    let gate = crate::adapter::lora_mm_id(
        ctx,
        lw.ffn_gate_exps.expect("ffn_gate_exps"),
        cur3,
        selected,
    );
    let act = silu_par_clamped(ctx, gate, up, limit);
    let mut experts =
        crate::adapter::lora_mm_id(ctx, lw.ffn_down_exps.expect("ffn_down_exps"), act, selected);
    experts = ctx.mul(experts, weights);
    graph.build_forward(ctx, experts);

    // aggregate the k expert slabs (llama-graph.cpp:2329-2358): each view is
    // [n_embd, n_tokens] strided by nb2, not a 1-row view
    let nb1 = ctx.nb(experts)[1] as usize;
    let nb2 = ctx.nb(experts)[2] as usize;
    let mut acc = ctx.view_2d(experts, n_embd, n_tokens, nb2, 0);
    for e in 1..n_expert_used {
        let v = ctx.view_2d(experts, n_embd, n_tokens, nb2, (e as usize) * nb1);
        acc = ctx.add(acc, v);
    }
    acc
}

