// smallthinker — verify against src/models/smallthinker.cpp:66-189
// ----------------------------------------------------------------------

pub struct SmallthinkerLayerWeights {
    pub attn_norm: TensorId,
    /// `create_tensor_qkv` (smallthinker.cpp:49): the fused attn_qkv when the
    /// file carries it, else the separate wq/wk/wv
    pub wqkv: Option<TensorId>,
    pub wqkv_b: Option<TensorId>,
    pub wq: Option<TensorId>,
    pub wq_b: Option<TensorId>,
    pub wk: Option<TensorId>,
    pub wk_b: Option<TensorId>,
    pub wv: Option<TensorId>,
    pub wv_b: Option<TensorId>,
    pub wo: TensorId,
    pub wo_b: Option<TensorId>,
    pub ffn_norm: TensorId,
    /// the router feeds from the RAW inpL, its logits ride probs_in
    pub ffn_gate_inp: TensorId,
    pub ffn_gate_exps: TensorId,
    pub ffn_down_exps: TensorId,
    pub ffn_up_exps: TensorId,
}

pub struct SmallthinkerModelWeights {
    pub tok_embd: TensorId,
    pub output_norm: TensorId,
    /// smallthinker.cpp:36-42 — tied to tok_embd when absent from the file
    pub output: TensorId,
    pub layers: Vec<SmallthinkerLayerWeights>,
}

#[derive(Clone)]
pub struct SmallthinkerParams {
    pub attn: AttnParams,
    /// hparams.n_no_rope_layer_step — == n_layer means "rope every layer"
    /// (the no-SWA file shape, smallthinker.cpp:16)
    pub n_no_rope_layer_step: u32,
    pub n_layer: usize,
    /// hparams.is_swa (the pattern-4 dense-first template of the SWA files)
    pub is_swa: Vec<bool>,
    /// model.get_rope_freq_base/scale (llama-model.cpp:2251-2257): the SWA
    /// layers read the *_train_swa copies
    pub freq_base_swa: f32,
    pub freq_scale_swa: f32,
    pub n_expert: i64,
    pub n_expert_used: i64,
    pub expert_weights_scale: f32,
    /// REQUIRED in effect (NONE aborts the reference's build_moe_ffn)
    pub expert_gating_func: i32,
}

/// verify against src/models/smallthinker.cpp:74-189 `graph<iswa>::graph` — the qwen2
/// skeleton with the MoE router **before** the attention norm: `probs` is
/// computed from the raw `inpL` (smallthinker.cpp:109) and handed to the MoE
/// as `probs_in`, so the FFN never multiplies the input by the router again.
/// The rope skip `n_no_rope_layer_step == n_layer || il % step != 0`
/// (smallthinker.cpp:106-107) collapses to "every layer" for the no-SWA
/// files; the SWA files' every-4th layers rope with the *_swa frequencies
/// and attend through their own (iswa) cache — `attn_kv_cached` selects it.
pub fn build_smallthinker_forward(
    ctx: &mut Context,
    w: &SmallthinkerModelWeights,
    p: &SmallthinkerParams,
    kv: &KvCache,
    inp: &DecodeInputs,
    _sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(2048);

    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_sa = inp_l;

        // per-layer rope frequencies (smallthinker.cpp:100-101 — the SWA
        // layers read the *_swa copies)
        let (freq_base_l, freq_scale_l) = if p.is_swa[il] {
            (p.freq_base_swa, p.freq_scale_swa)
        } else {
            (p.attn.freq_base, p.attn.freq_scale)
        };
        let rope = |ctx: &mut Context, x: TensorId| {
            ctx.rope_ext(
                x,
                inp.pos,
                None,
                p.attn.n_rot as i32,
                p.attn.rope_mode,
                p.attn.n_ctx_orig,
                freq_base_l,
                freq_scale_l,
                p.attn.ext_factor,
                p.attn.attn_factor,
                p.attn.beta_fast,
                p.attn.beta_slow,
            )
        };

        // the router eats the RAW inpL — probs [n_expert, n_tokens]
        // (smallthinker.cpp:109)
        let probs = crate::adapter::lora_mm(ctx, lw.ffn_gate_inp, inp_l);

        // norm
        let cur = build_norm_rms(ctx, inp_l, lw.attn_norm, p.attn.norm_eps);

        // self-attention (smallthinker.cpp:117-135)
        let (mut q, mut k, v) = if let Some(wqkv) = lw.wqkv {
            qkv_fused(ctx, wqkv, lw.wqkv_b, &p.attn, cur, t)
        } else {
            qkv_separate_parts(
                ctx,
                lw.wq.expect("smallthinker wq"),
                lw.wq_b,
                lw.wk.expect("smallthinker wk"),
                lw.wk_b,
                lw.wv.expect("smallthinker wv"),
                lw.wv_b,
                &p.attn,
                cur,
                t,
            )
        };
        // use_rope (smallthinker.cpp:106-107) — the SWA template still ropes
        // every layer (n_no_rope_layer_step keeps its file default 4)
        let use_rope =
            p.n_no_rope_layer_step as usize == n_layer || il % p.n_no_rope_layer_step as usize != 0;
        if use_rope {
            q = rope(ctx, q);
            k = rope(ctx, k);
        }

        let kq_scale = 1.0 / (p.attn.n_embd_head_v as f32).sqrt();
        let cur = attn_kv_cached(
            ctx,
            &mut graph,
            kv,
            il,
            &p.attn,
            inp,
            n_kv,
            q,
            k,
            v,
            kq_scale,
            0.0,
            None,
            None,
            Some(lw.wo),
            lw.wo_b,
        );

        let ffn_inp = ctx.add(cur, inp_sa);

        // MoE branch (smallthinker.cpp:144-162) — probs_in + ReGLU
        let cur = build_norm_rms(ctx, ffn_inp, lw.ffn_norm, p.attn.norm_eps);
        let ffn_out = build_moe_ffn_relu_probs(
            ctx,
            &mut graph,
            cur,
            lw.ffn_up_exps,
            lw.ffn_gate_exps,
            lw.ffn_down_exps,
            p.n_expert,
            p.n_expert_used,
            p.expert_weights_scale,
            p.expert_gating_func,
            probs,
        );
        let cur = ctx.add(ffn_out, ffn_inp);

        inp_l = cur;
    }

    let cur = build_norm_rms(ctx, inp_l, w.output_norm, p.attn.norm_eps);
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let logits = crate::adapter::lora_mm(ctx, w.output, cur);
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

/// build_moe_ffn with `probs_in != nullptr` + `LLM_FFN_RELU` — the
/// smallthinker composition (smallthinker.cpp:148-159 → llama-graph.cpp:
/// 1993-2363). The routing skips the gate_inp mulmat (probs_in replaces the
/// logits), the selected weights keep `norm_w = true` and the optional
/// expert_weights_scale, and the expert activation is `ggml_reglu_split`
/// (llama-graph.cpp:2285-2289 → ggml.c:3019).
#[allow(clippy::too_many_arguments)]
fn build_moe_ffn_relu_probs(
    ctx: &mut Context,
    graph: &mut Graph,
    cur: TensorId,
    up_exps: TensorId,
    gate_exps: TensorId,
    down_exps: TensorId,
    n_expert: i64,
    n_expert_used: i64,
    w_scale: f32,
    gating_op: i32,
    probs_in: TensorId,
) -> TensorId {
    let n_embd = ctx.ne(cur)[0];
    let n_tokens = ctx.ne(cur)[1];

    // probs_in replaces the logits (llama-graph.cpp:2026-2031)
    let logits = probs_in;
    let probs = match gating_op {
        EXPERT_GATING_SOFTMAX => ctx.soft_max(logits),
        EXPERT_GATING_SIGMOID => ctx.sigmoid(logits),
        EXPERT_GATING_SOFTMAX_WEIGHT => logits,
        other => unimplemented!("build_moe_ffn_relu_probs: gating op {other}"),
    };
    let selected = ctx.argsort_top_k(probs, n_expert_used as i32);

    let probs3 = ctx.reshape_3d(probs, 1, n_expert, n_tokens);
    let mut weights = ctx.get_rows(probs3, selected);
    if gating_op == EXPERT_GATING_SOFTMAX_WEIGHT {
        let w2 = ctx.reshape_2d(weights, n_expert_used, n_tokens);
        let w2 = ctx.soft_max(w2);
        weights = ctx.reshape_3d(w2, 1, n_expert_used, n_tokens);
    }
    // norm_w = true (smallthinker.cpp:158)
    {
        let w2 = ctx.reshape_2d(weights, n_expert_used, n_tokens);
        let sum = ctx.sum_rows(w2);
        let sum = ctx.clamp(sum, 6.103515625e-5, f32::INFINITY);
        let w2 = ctx.div(w2, sum);
        weights = ctx.reshape_3d(w2, 1, n_expert_used, n_tokens);
    }
    if w_scale != 0.0 && w_scale != 1.0 {
        weights = ctx.scale(weights, w_scale);
    }
    graph.build_forward(ctx, weights);

    let cur3 = ctx.reshape_3d(cur, n_embd, 1, n_tokens);
    // separate gate/up experts (smallthinker.cpp:59-62 — no fused tensor)
    let up = crate::adapter::lora_mm_id(ctx, up_exps, cur3, selected);
    let gate = crate::adapter::lora_mm_id(ctx, gate_exps, cur3, selected);
    // LLM_FFN_RELU with a gate (llama-graph.cpp:2285-2289)
    let act = ctx.reglu_split(gate, up);
    let mut experts = crate::adapter::lora_mm_id(ctx, down_exps, act, selected);
    experts = ctx.mul(experts, weights);
    graph.build_forward(ctx, experts);

    // aggregate the k expert slabs (llama-graph.cpp:2329-2358)
    let nb1 = ctx.nb(experts)[1] as usize;
    let nb2 = ctx.nb(experts)[2] as usize;
    let mut moe_out = ctx.view_2d(experts, n_embd, n_tokens, nb2, 0);
    graph.build_forward(ctx, moe_out);
    for i in 1..n_expert_used as usize {
        let vi = ctx.view_2d(experts, n_embd, n_tokens, nb2, i * nb1);
        graph.build_forward(ctx, vi);
        moe_out = ctx.add(moe_out, vi);
        graph.build_forward(ctx, moe_out);
    }
    if n_expert_used == 1 {
        moe_out = ctx.cont(moe_out);
    }
    moe_out
}

