pub struct LladaMoeLayerWeights {
    pub attn_norm: TensorId,
    pub wqkv: Option<TensorId>,
    pub wqkv_b: Option<TensorId>,
    pub wq: Option<TensorId>,
    pub wq_b: Option<TensorId>,
    pub wk: Option<TensorId>,
    pub wk_b: Option<TensorId>,
    pub wv: Option<TensorId>,
    pub wv_b: Option<TensorId>,
    pub wo: TensorId,
    pub wo_b: Option<TensorId>,
    /// per-head q/k norms BEFORE rope (llada-moe.cpp:87-91)
    pub attn_q_norm: TensorId,
    pub attn_k_norm: TensorId,
    pub ffn_norm: TensorId,
    pub ffn_gate_inp: TensorId,
    pub ffn_gate_exps: TensorId,
    pub ffn_down_exps: TensorId,
    pub ffn_up_exps: TensorId,
}

pub struct LladaMoeModelWeights {
    pub tok_embd: TensorId,
    pub output_norm: TensorId,
    /// llada-moe.cpp:23 — required, never tied
    pub output: TensorId,
    pub layers: Vec<LladaMoeLayerWeights>,
}

#[derive(Clone)]
pub struct LladaMoeParams {
    pub attn: AttnParams,
    pub n_expert: i64,
    pub n_expert_used: i64,
}

/// verify against src/models/llada-moe.cpp:54-163 — the LLaMA skeleton with
/// `build_attn_inp_no_cache` instead of a KV cache (llada-moe.cpp:68): the
/// KQ mask spans the *ubatch* only ([n_tokens, n_tokens],
/// llm_graph_input_attn_no_cache::set_input, llama-graph.cpp:409-468), filled
/// **non-causally** (`hparams.causal_attn = false`, llada-moe.cpp:8 — every
/// same-sequence pair stays 0). A decode step therefore attends the single
/// token of its ubatch — the reference server generates through this path,
/// and the port mirrors it exactly (the driver still owns a real KV cache
/// like the C's `llama_kv_cache`; the graph just never reads it).
///
/// The FA mode takes the F32→F16 cast branch of build_attn_mha
/// (llama-graph.cpp:2635-2641: no-cache k/v are F32, so `ggml_cast` runs
/// before `ggml_flash_attn_ext`).
pub fn build_llada_moe_forward(
    ctx: &mut Context,
    w: &LladaMoeModelWeights,
    p: &LladaMoeParams,
    _kv: &KvCache,
    inp: &DecodeInputs,
    _sinfo: SlotInfo,
    _n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(2048);

    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    // build_attn_inp_no_cache (llada-moe.cpp:68 → llama-graph.cpp:2740-2773):
    // one [n_tokens, n_tokens] mask; FA requires F16 (llama-graph.cpp:38-39).
    // Non-causal single sequence → every pair visible (0.0).
    let mask_ty = if p.attn.use_flash_attn {
        GgmlType::F16
    } else {
        GgmlType::F32
    };
    let kq_mask = ctx.new_tensor_2d(mask_ty, t, t);
    ctx.arena_resize_tensor(kq_mask);
    ctx.data_bytes_mut(kq_mask).unwrap().fill(0);

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_sa = inp_l;

        let cur = build_norm_rms(ctx, inp_l, lw.attn_norm, p.attn.norm_eps);

        // self-attention (llada-moe.cpp:82-112): qkv, per-head norms, rope
        let (mut q, mut k, v) = if let Some(wqkv) = lw.wqkv {
            qkv_fused(ctx, wqkv, lw.wqkv_b, &p.attn, cur, t)
        } else {
            qkv_separate_parts(
                ctx,
                lw.wq.expect("llada-moe wq"),
                lw.wq_b,
                lw.wk.expect("llada-moe wk"),
                lw.wk_b,
                lw.wv.expect("llada-moe wv"),
                lw.wv_b,
                &p.attn,
                cur,
                t,
            )
        };
        // per-head q/k norms BEFORE rope (llada-moe.cpp:87-91)
        q = build_norm_rms(ctx, q, lw.attn_q_norm, p.attn.norm_eps);
        k = build_norm_rms(ctx, k, lw.attn_k_norm, p.attn.norm_eps);
        q = rope_qk0(ctx, &p.attn, inp.pos, q);
        k = rope_qk0(ctx, &p.attn, inp.pos, k);

        // build_attn over the no-cache input — both FA branches of
        // build_attn_mha with n_kv = n_tokens (llama-graph.cpp:2607-2733)
        let kq_scale = 1.0 / (p.attn.n_embd_head_v as f32).sqrt();
        let cur = attn_no_cache_fa(
            ctx,
            q,
            k,
            v,
            kq_mask,
            kq_scale,
            p.attn.use_flash_attn,
            Some(lw.wo),
            lw.wo_b,
        );

        let ffn_inp = ctx.add(cur, inp_sa);

        // MoE branch (llada-moe.cpp:120-137) — plain softmax SILU MoE,
        // norm_w = false, no scale, no probs_in
        let cur = build_norm_rms(ctx, ffn_inp, lw.ffn_norm, p.attn.norm_eps);
        let moe = build_moe_ffn_silu_gu(
            ctx,
            &mut graph,
            cur,
            lw.ffn_gate_inp,
            None,
            Some(lw.ffn_up_exps),
            Some(lw.ffn_gate_exps),
            lw.ffn_down_exps,
            p.n_expert,
            p.n_expert_used,
            false,
            0.0,
            EXPERT_GATING_SOFTMAX,
            false,
        );
        let cur = ctx.add(moe, ffn_inp);

        inp_l = cur;
    }

    let cur = build_norm_rms(ctx, inp_l, w.output_norm, p.attn.norm_eps);
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let logits = crate::adapter::lora_mm(ctx, w.output, cur);
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

/// The `ggml_rope_ext(..., nullptr, ...)` call llada-moe spells inline
/// (llada-moe.cpp:93-103) — same shape as [`rope_qk`] for one tensor.
fn rope_qk0(ctx: &mut Context, p: &AttnParams, pos: TensorId, x: TensorId) -> TensorId {
    ctx.rope_ext(
        x,
        pos,
        None,
        p.n_rot as i32,
        p.rope_mode,
        p.n_ctx_orig,
        p.freq_base,
        p.freq_scale,
        p.ext_factor,
        p.attn_factor,
        p.beta_fast,
        p.beta_slow,
    )
}

/// `build_attn` over `build_attn_inp_no_cache` with **both** FA branches
/// (llama-graph.cpp:2607-2733 + the wo tail :2801-2817). The non-FA branch is
/// [`attn_no_cache`]; the FA branch permutes, casts the F32 k/v to F16
/// (llama-graph.cpp:2635-2641 — the no-cache tensors are F32, unlike the
/// F16 cache views) and runs ggml_flash_attn_ext with the F16 mask.
#[allow(clippy::too_many_arguments)]
fn attn_no_cache_fa(
    ctx: &mut Context,
    q: TensorId,
    k: TensorId,
    v: TensorId,
    kq_mask: TensorId,
    kq_scale: f32,
    use_flash_attn: bool,
    wo: Option<TensorId>,
    wo_b: Option<TensorId>,
) -> TensorId {
    if use_flash_attn {
        let q_fa = ctx.permute(q, 0, 2, 1, 3); // [DK, T, H]
        let k_fa = ctx.permute(k, 0, 2, 1, 3); // [DK, T, H_kv]
        let v_fa = ctx.permute(v, 0, 2, 1, 3); // [DV, T, H_kv]
                                               // the F32→F16 casts of the no-cache path (llama-graph.cpp:2635-2641)
        let k_fa = ctx.cast(k_fa, GgmlType::F16);
        let v_fa = ctx.cast(v_fa, GgmlType::F16);
        let cur =
            ctx.flash_attn_ext_sinks(q_fa, k_fa, v_fa, Some(kq_mask), None, kq_scale, 0.0, 0.0);
        let ne = *ctx.ne(cur);
        let kqv = ctx.reshape_2d(cur, ne[0] * ne[1], ne[2] * ne[3]);
        return match wo {
            Some(wo) => {
                let mut cur = crate::adapter::lora_mm(ctx, wo, kqv);
                if let Some(b) = wo_b {
                    cur = ctx.add(cur, b);
                }
                cur
            }
            None => kqv,
        };
    }
    attn_no_cache(ctx, q, k, v, None, kq_mask, kq_scale, wo, wo_b)
}

