/// verify against src/models/minimax-01.cpp:192-484 `graph::graph` — every-8th-full
/// hybrid: the softmax layers are plain GQA + rope through the (filtered) KV
/// cache, the lightning layers run the linear-attention recurrence
/// (minimax-01.cpp:277-420):
///
///   * the `llm_graph_input_la` inputs (minimax-01.cpp:67-190) are computed
///     per step from the ubatch positions — the slopes
///     `start·ratio^h` with `start = 2^(-2^(-(log2(n_head)-3)))`
///     (:98-104), `q_decay[i,h] = -slope_h·(pos_rel+1)` (:106-124),
///     `k_decay[i,h] = -slope_h·(T-1-pos_rel)` (:126-144) and the
///     `diag_decay[j,i,h] = -slope_h·(pos_j-pos_i) | -inf` matrix (:146-172);
///   * the decays are `exp(scale(·, slope_scale))` with the per-layer
///     `slope_scale = 1 - il/(n_layer-1) + 1e-5` (:288) — the
///     GGML_UNARY_OP_EXP op this batch ported;
///   * the recurrent state is the n_embd_head_la² × n_head matrix per layer
///     (`hparams.n_embd_s()`, llama-hparams.cpp:249-253): read as `kv_old`
///     [d, d, H, 1], decayed (`kv_old · exp(-slope·T)`), updated with
///     `k_decay^T · v` and written back through cpy (:390-394).
///
/// PARTIAL (reported): single sequence, n_seqs = 1 (the equal-seqs ubatch
/// split of llm_graph_input_la stays unported); the zero-width conv cell the
/// C builds at :283-286 (`n_embd_r() == 0` for this arch — the "TODO
/// unneeded" comment) contributes nothing and is skipped.
pub fn build_minimax01_forward(
    ctx: &mut Context,
    w: &Minimax01ModelWeights,
    p: &Minimax01Params,
    st: &RecurrentState,
    kv: &KvCache,
    inp: &DecodeInputs,
    _sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let n_head = p.n_head;
    let hd = p.n_embd_head_la;
    let mut graph = Graph::new(8192);
    assert_eq!(
        p.attn.n_embd_head_k, p.attn.n_embd_head_v,
        "minimax-01.cpp:195"
    );

    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    // ---- llm_graph_input_la::set_input (minimax-01.cpp:71-172), single seq ----
    let pos: Vec<i32> = ctx.i32s(inp.pos).unwrap().to_vec();
    let p0 = pos.iter().copied().min().unwrap(); // :80-91 (n_seqs_unq = 1)
                                                 // :98-104 — slopes[h] = start * ratio^h, start = 2^(-2^(-(log2(n_head)-3)))
    let slopes: Vec<f32> = {
        let start = (2.0f32).powf(-(2.0f32).powf(-((n_head as f32).log2() - 3.0)));
        let ratio = start;
        (0..n_head).map(|h| start * ratio.powi(h as i32)).collect()
    };
    let q_decay = ctx.new_tensor_4d(GgmlType::F32, 1, n_head, t, 1); // [1, H, T, 1]
    let k_decay = ctx.new_tensor_4d(GgmlType::F32, 1, n_head, t, 1);
    let diag_decay = ctx.new_tensor_4d(GgmlType::F32, t, t, n_head, 1); // [T, T, H, 1]
    for tids in [q_decay, k_decay, diag_decay] {
        ctx.arena_resize_tensor(tids);
    }
    {
        let pos_rel: Vec<i32> = pos.iter().map(|&p_i| p_i - p0).collect();
        {
            let qd: &mut [f32] = bytemuck::cast_slice_mut(ctx.data_bytes_mut(q_decay).unwrap());
            for (i, &pr) in pos_rel.iter().enumerate() {
                for h in 0..n_head as usize {
                    // :120 — data[i*n_head + h] = -slope*(pos_rel + 1)
                    qd[i * n_head as usize + h] = -slopes[h] * (pr + 1) as f32;
                }
            }
        }
        {
            let kd: &mut [f32] = bytemuck::cast_slice_mut(ctx.data_bytes_mut(k_decay).unwrap());
            for (i, &pr) in pos_rel.iter().enumerate() {
                for h in 0..n_head as usize {
                    // :140 — data[i*n_head + h] = -slope*(T - pos_rel - 1)
                    kd[i * n_head as usize + h] = -slopes[h] * (t as f32 - pr as f32 - 1.0);
                }
            }
        }
        // :146-171 — data[h*T*T + j*T + i], -slope*index above the diagonal,
        // -INFINITY below (index = pos_rel_j - pos_rel_i < 0)
        let dd: &mut [f32] = bytemuck::cast_slice_mut(ctx.data_bytes_mut(diag_decay).unwrap());
        for h in 0..n_head as usize {
            for (j, &pr_j) in pos_rel.iter().enumerate() {
                for (i, &pr_i) in pos_rel.iter().enumerate() {
                    let index = pr_j - pr_i;
                    let v = if index >= 0 {
                        -slopes[h] * index as f32
                    } else {
                        f32::NEG_INFINITY
                    };
                    dd[h * (t * t) as usize + j * t as usize + i] = v;
                }
            }
        }
    }
    // inp_slopes (:220-222) — [n_head] F32, the per-layer slope_rate base
    let slopes_t = ctx.new_tensor_1d(GgmlType::F32, n_head);
    ctx.arena_resize_tensor(slopes_t);
    ctx.with_f32_mut(slopes_t, |d| d.copy_from_slice(&slopes))
        .unwrap();

    for il in 0..n_layer {
        let lw = &w.layers[il];

        let cur = build_norm_rms(ctx, inp_l, lw.attn_norm, p.attn.norm_eps);
        let residual = cur;

        let cur = if !p.is_recr[il] {
            // ---- softmax attention layer (minimax-01.cpp:252-276) ----
            let (q, k, v) = if let Some(wqkv) = lw.wqkv {
                qkv_fused(ctx, wqkv, lw.wqkv_b, &p.attn, cur, t)
            } else {
                qkv_separate_parts(
                    ctx,
                    lw.wq.expect("minimax-01 wq"),
                    lw.wq_b,
                    lw.wk.expect("minimax-01 wk"),
                    lw.wk_b,
                    lw.wv.expect("minimax-01 wv"),
                    lw.wv_b,
                    &p.attn,
                    cur,
                    t,
                )
            };
            let q = rope_qk0(ctx, &p.attn, inp.pos, q);
            let k = rope_qk0(ctx, &p.attn, inp.pos, k);
            let kq_scale = 1.0 / (p.attn.n_embd_head_v as f32).sqrt();
            attn_kv_cached(
                ctx,
                &mut graph,
                kv,
                il,
                &p.attn,
                inp,
                n_kv,
                q,
                k,
                v,
                kq_scale,
                0.0,
                None,
                None,
                Some(lw.wo),
                lw.wo_b,
            )
        } else {
            // ---- lightning attention layer (minimax-01.cpp:277-420) ----
            // :288 — slope_scale = 1 - il/(n_layer-1) + 1e-5
            let slope_scale = 1.0 - 1.0 * il as f32 / (n_layer as f32 - 1.0) + 1e-5;
            let slope_rate = ctx.scale(slopes_t, slope_scale);

            // QKVcur = silu(wqkv @ cur) reshaped [3d, H, T, 1] (:294-300)
            let qkv_c = crate::adapter::lora_mm(ctx, lw.wqkv_la.expect("minimax-01 wqkv"), cur);
            let qkv_c = ctx.silu(qkv_c);
            let qkv_c = ctx.reshape_4d(qkv_c, hd * 3, n_head, t, 1);
            let (nb1, nb2) = (ctx.nb(qkv_c)[1] as usize, ctx.nb(qkv_c)[2] as usize);
            let qcur = ctx.view_4d(qkv_c, hd, n_head, t, 1, nb1, nb2, 0, 0);
            let kcur = ctx.view_4d(qkv_c, hd, n_head, t, 1, nb1, nb2, 0, hd as usize * 4);
            let vcur = ctx.view_4d(qkv_c, hd, n_head, t, 1, nb1, nb2, 0, 2 * hd as usize * 4);

            // the la recurrent state (:311-315): kv_old [d, d, H, 1]
            let state = st.ssm[il].expect("minimax-01 la state cell");
            let kv_old = ctx.reshape_4d(state, hd, hd, n_head, 1);

            // the decays (:326-331) — ggml_exp(scale(decay_exp, slope_scale))
            let q_scaled = ctx.scale(q_decay, slope_scale);
            let q_dec = ctx.exp(q_scaled);
            let k_scaled = ctx.scale(k_decay, slope_scale);
            let k_dec = ctx.exp(k_scaled);
            let diag_scaled = ctx.scale(diag_decay, slope_scale);
            let diag_dec = ctx.exp(diag_scaled);

            let q_s = ctx.mul(qcur, q_dec); // :333
            let q_s_trans = ctx.permute(q_s, 0, 2, 1, 3); // [d, T, H, 1]
            let qkv_none_diag = ctx.mul_mat(kv_old, q_s_trans); // [T, d, H, 1]

            let q_trans = ctx.permute(qcur, 0, 2, 1, 3); // [d, T, H, 1]
            let k_trans = ctx.permute(kcur, 0, 2, 1, 3);
            let qk = ctx.mul_mat(k_trans, q_trans); // [T, T, H, 1]
            let qk = ctx.mul(qk, diag_dec);

            // v_trans = cont(permute(Vcur, 1, 2, 0, 3)) → [T, d, H, 1]
            let v_perm = ctx.permute(vcur, 1, 2, 0, 3);
            let v_trans = ctx.cont(v_perm);
            let qkv_diag = ctx.mul_mat(v_trans, qk); // [T, d, H, 1]

            let qkv = ctx.add(qkv_none_diag, qkv_diag);
            graph.build_forward(ctx, qkv);

            // the new state (:365-387)
            let slopes_neg = ctx.scale(slope_rate, -1.0 * t as f32);
            let block_decay = ctx.exp(slopes_neg); // [H]
            let block_decay_3d = ctx.reshape_3d(block_decay, 1, 1, n_head);
            let kv_old_s = ctx.mul(kv_old, block_decay_3d);
            let k_after_decay = ctx.mul(kcur, k_dec);
            let kad_perm = ctx.permute(k_after_decay, 1, 2, 0, 3);
            let k_after_decay_trans = ctx.cont(kad_perm);
            let kv_cur = ctx.mul_mat(k_after_decay_trans, v_trans); // [d, d, H, 1]
            let kv_new = ctx.add(kv_old_s, kv_cur);

            // store new KV (:391-394) — the single-sequence cell at offset 0
            // (the C's kv_head * n_embd_s addressing)
            let dst = ctx.view_1d(state, p.n_embd_s as i64, 0);
            let cpy = ctx.cpy(kv_new, dst);
            graph.build_forward(ctx, cpy);

            // :396-419 — permute to [d, H, T, 1], flatten [d*H, T], the RMS
            // norm with attn_norm_2, the sigmoid output gate, wo
            let qkv_perm = ctx.permute(qkv, 0, 2, 1, 3);
            let qkv = ctx.cont(qkv_perm);
            let ne = *ctx.ne(qkv);
            let qkv = ctx.reshape_4d(qkv, ne[0] * ne[1], ne[2], 1, ne[3]);
            let qkv_norm = build_norm_rms(
                ctx,
                qkv,
                lw.attn_norm_2.expect("minimax-01 attn_norm_2"),
                p.attn.norm_eps,
            );
            let g = crate::adapter::lora_mm(ctx, lw.wg.expect("minimax-01 wg"), cur);
            let g = ctx.sigmoid(g);
            let cur = ctx.mul(g, qkv_norm);
            let cur = crate::adapter::lora_mm(ctx, lw.wo, cur);
            ctx.reshape_2d(cur, p.n_embd, t)
        };

        // the residual-scale pair (:428-431 / :455-459)
        let residual = ctx.scale(residual, p.f_residual_scale);
        let ffn_inp = ctx.add(cur, residual);

        // MoE branch (:435-453) — softmax SILU + norm_w = true. The graph
        // passes `layer.ffn_exp_probs_b` but the loader never creates it
        // (minimax-01.cpp:56-59 has no FFN_EXP_PROBS_B create_tensor), so the
        // bias arm of build_moe_ffn (llama-graph.cpp:2062-2067) is unreachable
        let cur = build_norm_rms(ctx, ffn_inp, lw.ffn_norm, p.attn.norm_eps);
        let residual = cur;
        let moe = build_moe_ffn_silu_gu(
            ctx,
            &mut graph,
            cur,
            lw.ffn_gate_inp,
            None,
            Some(lw.ffn_up_exps),
            lw.ffn_gate_exps,
            lw.ffn_down_exps,
            p.n_expert,
            p.n_expert_used,
            true,
            p.expert_weights_scale,
            EXPERT_GATING_SOFTMAX,
            false,
        );
        let residual = ctx.scale(residual, p.f_residual_scale);
        let cur = ctx.add(moe, residual);
        inp_l = cur;
    }

    let cur = build_norm_rms(ctx, inp_l, w.output_norm, p.attn.norm_eps);
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let logits = crate::adapter::lora_mm(ctx, w.output, cur);
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

