/// verify against src/models/granite-switch.cpp:221-329 `graph::graph` — the granite
/// skeleton where every projection carries a per-token switched LoRA delta:
///
///   * the substitution happens at the embedding lookup: `sub_tokens` indexes
///     tok_embd directly (:251, llm_graph_input_switch::set_input :151-185 —
///     an adapter's activate token is replaced by its substitute id);
///   * the adapter index is recovered **in-graph** by a single causal head at
///     layer R (:263-287): Q[0]=1, K[0]=±gain, V[0]=slot — the softmax lets
///     the latest visible adapter token dominate, and clamp+round+cast turns
///     the readback into the I32 `adapter_ids` the mul_mat_id deltas eat;
///   * every trunk layer adds `B[ids]·(A[ids]·x)` to its q/k/v/o and
///     gate/up/down projections (`build_switched_lora_delta`,
///     :193-208 — reshape to [n_in, 1, T] + two mul_mat_id).
///
/// The port computes the switch inputs inside the builder from `inp.tokens`
/// (the C's set_input does it from the ubatch — same values, single sequence).
pub fn build_graniteswitch_forward(
    ctx: &mut Context,
    w: &GraniteSwitchModelWeights,
    p: &GraniteSwitchParams,
    kv: &KvCache,
    inp: &DecodeInputs,
    _sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let r = p.router_layer;
    let hd = p.attn.n_embd_head_k;
    let mut graph = Graph::new(8192);

    // ---- llm_graph_input_switch::set_input (granite-switch.cpp:151-185) ----
    let tokens: Vec<i32> = ctx.i32s(inp.tokens).unwrap().to_vec();
    let mut sub = vec![0i32; n_tokens];
    let mut ksig = vec![0f32; n_tokens];
    let mut vval = vec![0f32; n_tokens];
    let qsig = vec![1.0f32; n_tokens]; // :161 — constant 1.0
    for (i, &tok) in tokens.iter().enumerate() {
        // K dim-0 is +gain for an adapter token, -gain otherwise (:163-173)
        let slot = w
            .token_to_slot
            .iter()
            .find(|(k, _)| *k == tok)
            .map(|(_, v)| *v);
        let subst = w
            .token_to_substitute
            .iter()
            .find(|(k, _)| *k == tok)
            .map(|(_, v)| *v);
        match (slot, subst) {
            (Some(s), Some(subst)) => {
                ksig[i] = p.router_gain;
                vval[i] = s as f32;
                sub[i] = subst;
            }
            _ => {
                ksig[i] = -p.router_gain;
                vval[i] = 0.0;
                sub[i] = tok;
            }
        }
    }
    let mut mk_i32 = |v: &[i32], ctx: &mut Context| -> TensorId {
        let tid = ctx.new_tensor_1d(GgmlType::I32, v.len() as i64);
        ctx.arena_resize_tensor(tid);
        ctx.with_i32_mut(tid, |d| d.copy_from_slice(v)).unwrap();
        tid
    };
    let mut mk_f32 = |v: &[f32], ctx: &mut Context| -> TensorId {
        let tid = ctx.new_tensor_1d(GgmlType::F32, v.len() as i64);
        ctx.arena_resize_tensor(tid);
        ctx.with_f32_mut(tid, |d| d.copy_from_slice(v)).unwrap();
        tid
    };
    let sub_tokens = mk_i32(&sub, ctx);
    let router_ksig = mk_f32(&ksig, ctx);
    let router_vval = mk_f32(&vval, ctx);
    let router_q = mk_f32(&qsig, ctx);

    // embed the substituted ids directly (:251 — build_inp_embd would embed
    // the raw tokens); the granite embedding scale rides build_inp_embd
    // (llama-graph.cpp:2446-2452)
    let mut inp_l = ctx.get_rows(w.tok_embd, sub_tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, sub_tokens);
    if p.f_embedding_scale != 0.0 {
        inp_l = ctx.scale(inp_l, p.f_embedding_scale);
    }

    // the router lanes (:267-273): reshape to [1, 1, T] and right-pad dim 0
    // to the head width — only row 0 carries signal, the rest is zero-padded
    let router_lane = |ctx: &mut Context, sig: TensorId| -> TensorId {
        let lane = ctx.reshape_3d(sig, 1, 1, t);
        ctx.pad(lane, (hd - 1) as i32, 0, 0, 0)
    };
    let qr = router_lane(ctx, router_q);
    let kr = router_lane(ctx, router_ksig);
    let vr = router_lane(ctx, router_vval);

    // the single-head attention at layer R (:275-277) — kq_scale 1.0,
    // no wo (the concatenated head IS the readback). The router layer's
    // geometry (1 kv head) differs from attn.n_head_kv, so the scatter and
    // the views spell the trunk helper's body out with n_head_kv = 1
    // (build_attn_mha, llama-graph.cpp:2607-2733)
    let router_out = {
        let row_idx = inp.row_idx;
        let k_rows = {
            let nb2 = ctx.nb(kr)[2] as usize;
            ctx.view_2d(kr, hd, t, nb2, 0)
        };
        let v_rows = {
            let nb2 = ctx.nb(vr)[2] as usize;
            ctx.view_2d(vr, hd, t, nb2, 0)
        };
        let k_dst = ctx.set_rows(kv.layers[r].k, k_rows, row_idx);
        let v_dst = ctx.set_rows(kv.layers[r].v, v_rows, row_idx);
        graph.build_forward(ctx, k_dst);
        graph.build_forward(ctx, v_dst);
        let k_view = kv.get_k(ctx, r, hd, 1, n_kv);
        let v_view = kv.get_v(ctx, r, hd, 1, n_kv);
        let out = if p.attn.use_flash_attn {
            graph::flash_attn_core_sinks(ctx, qr, k_view, v_view, inp.kq_mask, None, 1.0, 0.0, 0.0)
        } else {
            let q_p = ctx.permute(qr, 0, 2, 1, 3);
            let k_p = ctx.permute(k_view, 0, 2, 1, 3);
            let kq = ctx.mul_mat(k_p, q_p);
            let kq = ctx.soft_max_ext(kq, Some(inp.kq_mask), 1.0, 0.0);
            let v_p = ctx.permute(v_view, 0, 2, 1, 3);
            let v_t = ctx.transpose(v_p);
            let v_c = ctx.cont(v_t);
            let kqv = ctx.mul_mat(v_c, kq);
            let kqv = ctx.permute(kqv, 0, 2, 1, 3);
            let kqv = ctx.cont(kqv);
            let ne = *ctx.ne(kqv);
            ctx.reshape_2d(kqv, ne[0] * ne[1], ne[2] * ne[3])
        };
        out
    };

    // row 0 of router_out is the attended slot; clamp+round → I32 ids (:281-287)
    let nb1 = ctx.nb(router_out)[1] as usize;
    let slot_v = ctx.view_2d(router_out, 1, t, nb1, 0);
    let slot_f = ctx.cont(slot_v);
    let slot_f = ctx.reshape_1d(slot_f, t);
    let slot_f = ctx.clamp(slot_f, 0.0, p.n_adapters as f32);
    let slot_f = ctx.round(slot_f);
    let adapter_ids = ctx.cast(slot_f, GgmlType::I32);

    // build_switched_lora_delta (granite-switch.cpp:193-208)
    let switched_lora_delta = |ctx: &mut Context,
                               lora_a: TensorId,
                               lora_b: TensorId,
                               cur: TensorId,
                               ids: TensorId|
     -> TensorId {
        let n_in = ctx.ne(cur)[0];
        let n_tok = ctx.ne(cur)[1];
        let x = ctx.reshape_3d(cur, n_in, 1, n_tok);
        let ids2 = ctx.reshape_2d(ids, 1, n_tok);
        let a = ctx.mul_mat_id(lora_a, x, ids2); // {n_rank, 1, T}
        let d = ctx.mul_mat_id(lora_b, a, ids2); // {n_out, 1, T}
        ctx.reshape_2d(d, ctx.ne(d)[0], n_tok)
    };
    // build_switched_lora_mm (:210-219) — base + delta
    let switched_lora_mm = |ctx: &mut Context,
                            w_: TensorId,
                            lora_a: TensorId,
                            lora_b: TensorId,
                            cur: TensorId,
                            ids: TensorId|
     -> TensorId {
        let base = ctx.mul_mat(w_, cur);
        let delta = switched_lora_delta(ctx, lora_a, lora_b, cur, ids);
        ctx.add(base, delta)
    };

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let sl = &lw.sl;
        let inp_sa = inp_l;

        let cur = build_norm_rms(ctx, inp_l, lw.attn_norm, p.attn.norm_eps);

        // build_attention_layer (:331-390)
        let qkv = ctx.mul_mat(lw.wqkv, cur);
        let n_head = p.n_head[il];
        let n_head_kv = p.n_head_kv[il];
        let n_embd_q = hd * n_head;
        let n_embd_kv = hd * n_head_kv;
        let nb1 = ctx.nb(qkv)[1] as usize;
        // slice fused qkv into Q/K/V, made contiguous so LoRA deltas add
        let qv = ctx.view_2d(qkv, n_embd_q, t, nb1, 0);
        let mut qcur = ctx.cont(qv);
        let kv_view = ctx.view_2d(qkv, n_embd_kv, t, nb1, n_embd_q as usize * 4);
        let mut kcur = ctx.cont(kv_view);
        let vv = ctx.view_2d(qkv, n_embd_kv, t, nb1, (n_embd_q + n_embd_kv) as usize * 4);
        let mut vcur = ctx.cont(vv);

        let dq = switched_lora_delta(ctx, sl.a_q, sl.b_q, cur, adapter_ids);
        qcur = ctx.add(qcur, dq);
        let dk = switched_lora_delta(ctx, sl.a_k, sl.b_k, cur, adapter_ids);
        kcur = ctx.add(kcur, dk);
        let dv = switched_lora_delta(ctx, sl.a_v, sl.b_v, cur, adapter_ids);
        vcur = ctx.add(vcur, dv);

        let qcur = ctx.reshape_3d(qcur, hd, n_head, t);
        let kcur = ctx.reshape_3d(kcur, hd, n_head_kv, t);
        let vcur = ctx.reshape_3d(vcur, hd, n_head_kv, t);

        // rope on the finetuned layers only (:365-373 — no rope factors, the
        // file never loads them)
        let (qcur, kcur) = if p.has_rope[il] {
            (
                rope_qk0(ctx, &p.attn, inp.pos, qcur),
                rope_qk0(ctx, &p.attn, inp.pos, kcur),
            )
        } else {
            (qcur, kcur)
        };

        // kq_scale (:378-379)
        let kq_scale = if p.f_attention_scale == 0.0 {
            1.0 / (hd as f32).sqrt()
        } else {
            p.f_attention_scale
        };

        // wo = nullptr so build_attn returns concatenated heads; o-proj is
        // switched below (:382-387)
        let attn = attn_kv_cached(
            ctx, &mut graph, kv, il, &p.attn, inp, n_kv, qcur, kcur, vcur, kq_scale, 0.0, None,
            None, None, None,
        );
        let cur = switched_lora_mm(ctx, lw.wo, sl.a_o, sl.b_o, attn, adapter_ids);

        // build_layer_ffn (:392-427)
        let cur = if p.f_residual_scale != 0.0 {
            ctx.scale(cur, p.f_residual_scale)
        } else {
            cur
        };
        let ffn_inp = ctx.add(cur, inp_sa);

        let cur = build_norm_rms(ctx, ffn_inp, lw.ffn_norm, p.attn.norm_eps);

        let g = switched_lora_mm(ctx, lw.ffn_gate, sl.a_gate, sl.b_gate, cur, adapter_ids);
        let u = switched_lora_mm(ctx, lw.ffn_up, sl.a_up, sl.b_up, cur, adapter_ids);
        let g = ctx.silu(g);
        let gu = ctx.mul(g, u);
        let cur = switched_lora_mm(ctx, lw.ffn_down, sl.a_down, sl.b_down, gu, adapter_ids);

        let cur = if p.f_residual_scale != 0.0 {
            ctx.scale(cur, p.f_residual_scale)
        } else {
            cur
        };
        let cur = ctx.add(cur, ffn_inp);

        inp_l = cur;
    }

    let cur = build_norm_rms(ctx, inp_l, w.output_norm, p.attn.norm_eps);
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let logits = crate::adapter::lora_mm(ctx, w.output, cur);
    // the granite logit scale (:324)
    let logits = ctx.scale(logits, 1.0 / p.f_logit_scale);
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

