// ----------------------------------------------------------------------
// apertus — verify against src/models/apertus.cpp (per-head q/k RMS norm + rope with
// longrope factors + the xIELU FFN activation)
// ----------------------------------------------------------------------

pub struct ApertusLayerWeights {
    pub attn_norm: TensorId,
    /// LONGROPE files: rope_factors_long/short per layer; plain files keep
    /// the model-level rope_freqs name (apertus.cpp:31-36) — both optional
    pub rope_long: Option<TensorId>,
    pub rope_short: Option<TensorId>,
    pub rope_freqs: Option<TensorId>,
    pub wqkv: Option<TensorId>,
    pub wq: Option<TensorId>,
    pub wk: Option<TensorId>,
    pub wv: Option<TensorId>,
    pub wo: TensorId,
    /// optional ATTN_OUT bias (apertus.cpp:42)
    pub wo_b: Option<TensorId>,
    pub attn_q_norm: TensorId,
    pub attn_q_norm_b: Option<TensorId>,
    pub attn_k_norm: TensorId,
    pub attn_k_norm_b: Option<TensorId>,
    pub ffn_norm: TensorId,
    pub ffn_down: TensorId,
    pub ffn_up: TensorId,
}

pub struct ApertusModelWeights {
    pub tok_embd: TensorId,
    pub output_norm: TensorId,
    /// apertus.cpp:24 — output.weight REQUIRED (no tied fallback)
    pub output: TensorId,
    pub layers: Vec<ApertusLayerWeights>,
}

/// apertus hparams beyond [`AttnParams`] (apertus.cpp:3-15).
#[derive(Clone)]
pub struct ApertusParams {
    pub attn: AttnParams,
    /// per-layer xIELU constants (hparams.xielu_*)
    pub xielu_alpha_n: Vec<f32>,
    pub xielu_alpha_p: Vec<f32>,
    pub xielu_beta: Vec<f32>,
    pub xielu_eps: Vec<f32>,
    /// hparams.f_attention_scale; 0.0 → 1/sqrt(n_embd_head) (apertus.cpp:74-75)
    pub f_attention_scale: f32,
    /// model.get_rope_factors picks long/short when the file is LONGROPE
    /// (apertus.cpp:87); the plain path passes nullptr
    pub use_longrope_factors: bool,
}

/// verify against src/models/apertus.cpp:60-170 `graph::graph` — per layer: rms
/// attn_norm → qkv (fused or separate) → per-head q/k RMS norms → rope →
/// MHA over the unified cache (optional wo bias) → residual → rms ffn_norm →
/// up → **xielu** → down → residual → final norm → lm_head.
pub fn build_apertus_forward(
    ctx: &mut Context,
    w: &ApertusModelWeights,
    p: &ApertusParams,
    kv: &KvCache,
    inp: &DecodeInputs,
    sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(8192);
    let a = &p.attn;
    let n_embd_head = a.n_embd_head_k;
    assert_eq!(
        n_embd_head, a.n_embd_head_v,
        "apertus: k/v head dims differ"
    );
    assert_eq!(n_embd_head, a.n_rot, "apertus.cpp:64 — head_dim == n_rot");

    let kq_scale = if p.f_attention_scale == 0.0 {
        1.0 / (n_embd_head as f32).sqrt()
    } else {
        p.f_attention_scale
    };

    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_sa = inp_l;

        // attn_norm (apertus.cpp:82)
        let cur = build_norm_rms(ctx, inp_l, lw.attn_norm, a.norm_eps);

        // self-attention (apertus.cpp:86-113)
        let cur = {
            // rope factors (apertus.cpp:87): LONGROPE files pick long/short by
            // context length — the plain path (our synthetic files) has none
            let rope_factors = if p.use_longrope_factors {
                lw.rope_long.or(lw.rope_short)
            } else {
                lw.rope_freqs
            };

            // build_qkv — the fused wqkv or the separate trio (apertus.cpp:90)
            let (mut qcur, mut kcur, vcur) = match lw.wqkv {
                Some(wqkv) => {
                    // the fused view split (llama-graph.cpp:1639-1677)
                    let qkv = crate::adapter::lora_mm(ctx, wqkv, cur);
                    let nb1 = ctx.nb(qkv)[1] as usize;
                    let hd = n_embd_head as usize * 4;
                    let nq = (a.n_embd_head_k * a.n_head) as usize;
                    let nk = (a.n_embd_head_k * a.n_head_kv) as usize;
                    let q = ctx.view_3d(qkv, n_embd_head, a.n_head, t, hd, nb1, 0);
                    // the C's offsets are ggml_row_size(qkv, n_embd_q/k) —
                    // BYTES (llama-graph.cpp:1676-1682)
                    let k = ctx.view_3d(qkv, n_embd_head, a.n_head_kv, t, hd, nb1, nq * 4);
                    let v =
                        ctx.view_3d(qkv, a.n_embd_head_v, a.n_head_kv, t, hd, nb1, (nq + nk) * 4);
                    (q, k, v)
                }
                None => {
                    let q = crate::adapter::lora_mm(ctx, lw.wq.expect("apertus wq"), cur);
                    let k = crate::adapter::lora_mm(ctx, lw.wk.expect("apertus wk"), cur);
                    let v = crate::adapter::lora_mm(ctx, lw.wv.expect("apertus wv"), cur);
                    let q = ctx.reshape_3d(q, n_embd_head, a.n_head, t);
                    let k = ctx.reshape_3d(k, n_embd_head, a.n_head_kv, t);
                    let v = ctx.reshape_3d(v, a.n_embd_head_v, a.n_head_kv, t);
                    (q, k, v)
                }
            };

            // per-head q/k RMS norms before rope (apertus.cpp:93-96)
            qcur = build_norm_rms(ctx, qcur, lw.attn_q_norm, a.norm_eps);
            kcur = build_norm_rms(ctx, kcur, lw.attn_k_norm, a.norm_eps);

            // rope (apertus.cpp:99-103)
            let r = |ctx: &mut Context, x: TensorId| {
                ctx.rope_ext(
                    x,
                    inp.pos,
                    rope_factors,
                    a.n_rot as i32,
                    a.rope_mode,
                    a.n_ctx_orig,
                    a.freq_base,
                    a.freq_scale,
                    a.ext_factor,
                    a.attn_factor,
                    a.beta_fast,
                    a.beta_slow,
                )
            };
            let qcur = r(ctx, qcur);
            let kcur = r(ctx, kcur);

            attn_kv_cached(
                ctx,
                &mut graph,
                kv,
                il,
                a,
                inp,
                n_kv,
                qcur,
                kcur,
                vcur,
                kq_scale,
                0.0,
                None,
                None,
                Some(lw.wo),
                lw.wo_b,
            )
        };
        let _ = sinfo;

        let ffn_inp = ctx.add(cur, inp_sa);

        // xIELU FFN (apertus.cpp:124-144)
        let cur = build_norm_rms(ctx, ffn_inp, lw.ffn_norm, a.norm_eps);
        let up = crate::adapter::lora_mm(ctx, lw.ffn_up, cur);
        // ggml_xielu with the per-layer constants (apertus.cpp:138)
        let act = ctx.xielu(
            up,
            p.xielu_alpha_n[il],
            p.xielu_alpha_p[il],
            p.xielu_beta[il],
            p.xielu_eps[il],
        );
        let cur = crate::adapter::lora_mm(ctx, lw.ffn_down, act);

        inp_l = ctx.add(cur, ffn_inp);
    }

    let cur = build_norm_rms(ctx, inp_l, w.output_norm, a.norm_eps);
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let logits = crate::adapter::lora_mm(ctx, w.output, cur);
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

// ----------------------------------------------------------------------
// grovemoe — verify against src/models/grovemoe.cpp (softmax-gated MoE over the
// experts AND a second "chunk expert" MoE scaled by expert_group_scale)
// ----------------------------------------------------------------------

pub struct GrovemoeLayerWeights {
    pub attn_norm: TensorId,
    pub wqkv: Option<TensorId>,
    pub wq: Option<TensorId>,
    pub wk: Option<TensorId>,
    pub wv: Option<TensorId>,
    pub wo: TensorId,
    pub attn_k_norm: TensorId,
    pub attn_q_norm: TensorId,
    pub ffn_norm: TensorId,
    pub ffn_gate_inp: TensorId,
    pub ffn_gate_exps: TensorId,
    pub ffn_down_exps: TensorId,
    pub ffn_up_exps: TensorId,
    /// the chunk-expert MoE (FFN_*_CHEXPS, grovemoe.cpp:57-59)
    pub ffn_gate_chexps: TensorId,
    pub ffn_down_chexps: TensorId,
    pub ffn_up_chexps: TensorId,
}

pub struct GrovemoeModelWeights {
    pub tok_embd: TensorId,
    pub output_norm: TensorId,
    /// tied to tok_embd when the file has no output.weight (grovemoe.cpp:23-27)
    pub output: TensorId,
    pub layers: Vec<GrovemoeLayerWeights>,
}

/// grovemoe hparams beyond [`AttnParams`] (grovemoe.cpp:3-14).
#[derive(Clone)]
pub struct GrovemoeParams {
    pub attn: AttnParams,
    pub n_embd: i64,
    /// hparams.expert_group_scale
    pub expert_group_scale: f32,
    /// hparams.n_group_experts — n_chunk_expert = n_expert / n_group_experts
    pub n_group_experts: i64,
    /// hparams.n_ff_chexp (0 → n_embd_head_k, grovemoe.cpp:50)
    pub n_ff_chexp: i64,
    pub n_embd_head_k: i64,
    pub n_expert: i64,
    pub n_expert_used: i64,
    pub expert_weights_scale: f32,
}

/// `build_moe_ffn`'s `probs_in` parameter (llama-graph.cpp:1993-2115): the
/// router **logits** computed by the caller (grovemoe banks them once and
/// feeds the same tensor to both MoE calls, grovemoe.cpp:133-164). This
/// variant of [`build_moe_ffn_silu`] replaces the `gate_inp` mul_mat with the
/// precomputed logits. The grovemoe specifics of the shared helper ride
/// along (llama-graph.cpp:2076-2119):
///   * the top-k **selection** uses `sigmoid(logits)` while the weights keep
///     the SOFTMAX probs (:2076-2078);
///   * the chunk-expert call (`n_expert != n_expert_all`) divides the
///     selected global ids by n_group_experts to index the chunk space and
///     gathers the weights from the FULL probs tensor (:2113-2118).
#[allow(clippy::too_many_arguments)]
fn build_moe_ffn_silu_probs(
    ctx: &mut Context,
    graph: &mut Graph,
    cur: TensorId,
    logits: TensorId,
    up_exps: TensorId,
    gate_exps: TensorId,
    down_exps: TensorId,
    // the expert count THIS call addresses (the chunk count for the chunk MoE)
    n_expert: i64,
    // the model's full expert count (hparams.n_expert — the probs rows)
    n_expert_all: i64,
    // hparams.n_group_experts — the chunk divisor of the selection
    n_group_experts: i64,
    n_expert_used: i64,
    norm_w: bool,
    w_scale: f32,
    gating_op: i32,
    // the router selection bias (llama-graph.cpp:2063-2067) — added to the
    // POST-gating probs and steering ONLY the top-k selection; the expert
    // weights keep the unbiased probs. The five bias-carrying batch-15 archs
    // (afmoe/hy-v3/mimo2/step35/hy-v4) previously folded it into the logits
    // pre-gating — sigmoid(l+b) vs sigmoid(l)+b — which perturbed the weights
    // (~2e-3 rel) and drifted every downstream node (the mimo2/step35 iswa
    // kq ~3e-3 divergence, PARITY.md batch 15).
    exp_probs_b: Option<TensorId>,
) -> TensorId {
    let n_embd = ctx.ne(cur)[0];
    let n_tokens = ctx.ne(cur)[1];

    // the gating function over the caller's logits (llama-graph.cpp:2042-2061)
    let probs = match gating_op {
        EXPERT_GATING_SOFTMAX => ctx.soft_max(logits),
        EXPERT_GATING_SIGMOID => ctx.sigmoid(logits),
        EXPERT_GATING_SOFTMAX_WEIGHT => logits,
        other => unimplemented!("build_moe_ffn_silu_probs: gating op {other}"),
    };

    // the top-k selection: probs + the selection bias (llama-graph.cpp:2063-
    // 2067 `selection_probs = ggml_add(ctx0, probs, exp_probs_b)`); without a
    // bias the GROVEMOE form (:2080-2082 `selection_probs = ggml_sigmoid(ctx0,
    // logits)`) — for the plain softmax callers both are strictly monotone in
    // the logits per column, so the top-k ids are the same either way
    let selection = match exp_probs_b {
        Some(b) => ctx.add(probs, b),
        None => ctx.sigmoid(logits),
    };
    let mut selected = ctx.argsort_top_k(selection, n_expert_used as i32);

    // the chunk call maps the global ids into the chunk index space
    // (llama-graph.cpp:2113-2118)
    let probs = if n_expert != n_expert_all {
        let f_sel = ctx.cast(selected, GgmlType::F32);
        let f_sel = ctx.scale(f_sel, 1.0 / n_group_experts as f32);
        selected = ctx.cast(f_sel, GgmlType::I32);
        // the weights gather from the FULL probs rows
        ctx.reshape_3d(probs, 1, n_expert_all, n_tokens)
    } else {
        ctx.reshape_3d(probs, 1, n_expert, n_tokens)
    };

    let mut weights = ctx.get_rows(probs, selected); // [1, k, n_tokens]

    if gating_op == EXPERT_GATING_SOFTMAX_WEIGHT {
        let w2 = ctx.reshape_2d(weights, n_expert_used, n_tokens);
        let w2 = ctx.soft_max(w2);
        weights = ctx.reshape_3d(w2, 1, n_expert_used, n_tokens);
    }
    if norm_w {
        let w2 = ctx.reshape_2d(weights, n_expert_used, n_tokens);
        let sum = ctx.sum_rows(w2); // [1, n_tokens]
        let sum = ctx.clamp(sum, 6.103515625e-5, f32::INFINITY);
        let w2 = ctx.div(w2, sum);
        weights = ctx.reshape_3d(w2, 1, n_expert_used, n_tokens);
    }
    if w_scale != 0.0 && w_scale != 1.0 {
        weights = ctx.scale(weights, w_scale);
    }
    graph.build_forward(ctx, weights);

    let cur3 = ctx.reshape_3d(cur, n_embd, 1, n_tokens);
    let up = crate::adapter::lora_mm_id(ctx, up_exps, cur3, selected);
    let gate = crate::adapter::lora_mm_id(ctx, gate_exps, cur3, selected);
    let act = ctx.swiglu_split(gate, up);
    let experts = crate::adapter::lora_mm_id(ctx, down_exps, act, selected);
    let experts = ctx.mul(experts, weights);
    graph.build_forward(ctx, experts);

    let nb1 = ctx.nb(experts)[1] as usize;
    let nb2 = ctx.nb(experts)[2] as usize;
    let mut moe_out = ctx.view_2d(experts, n_embd, n_tokens, nb2, 0);
    graph.build_forward(ctx, moe_out);
    for i in 1..n_expert_used as usize {
        let vi = ctx.view_2d(experts, n_embd, n_tokens, nb2, i * nb1);
        graph.build_forward(ctx, vi);
        moe_out = ctx.add(moe_out, vi);
        graph.build_forward(ctx, moe_out);
    }
    if n_expert_used == 1 {
        moe_out = ctx.cont(moe_out);
    }
    moe_out
}

/// verify against src/models/grovemoe.cpp:67-193 `graph::graph` — per layer: rms
/// attn_norm → qkv → per-head q/k RMS norms → rope → MHA → residual → rms
/// ffn_norm → **two** softmax MoEs over the same router logits (the experts
/// and the chunk experts, the second scaled by `expert_group_scale`) →
/// residual → final norm → lm_head.
pub fn build_grovemoe_forward(
    ctx: &mut Context,
    w: &GrovemoeModelWeights,
    p: &GrovemoeParams,
    kv: &KvCache,
    inp: &DecodeInputs,
    sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(8192);
    let a = &p.attn;
    let n_embd_head = a.n_embd_head_v;
    assert_eq!(
        n_embd_head, a.n_embd_head_k,
        "grovemoe: k/v head dims differ"
    );
    assert_eq!(n_embd_head, a.n_rot, "grovemoe.cpp:73 — head_dim == n_rot");
    let n_chunk_expert = p.n_expert / p.n_group_experts;

    let kq_scale = 1.0f32 / (n_embd_head as f32).sqrt();

    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_sa = inp_l;

        let cur = build_norm_rms(ctx, inp_l, lw.attn_norm, a.norm_eps);

        // q/k normed then roped (grovemoe.cpp:96-113)
        let (qcur, kcur, vcur) = match lw.wqkv {
            Some(wqkv) => {
                let qkv = crate::adapter::lora_mm(ctx, wqkv, cur);
                let nb1 = ctx.nb(qkv)[1] as usize;
                let hd = n_embd_head as usize * 4;
                let nq = (a.n_embd_head_k * a.n_head) as usize;
                let nk = (a.n_embd_head_k * a.n_head_kv) as usize;
                let q = ctx.view_3d(qkv, n_embd_head, a.n_head, t, hd, nb1, 0);
                // the C's offsets are ggml_row_size(qkv, n_embd_q/k) — BYTES
                // (llama-graph.cpp:1676-1682)
                let k = ctx.view_3d(qkv, n_embd_head, a.n_head_kv, t, hd, nb1, nq * 4);
                let v = ctx.view_3d(qkv, a.n_embd_head_v, a.n_head_kv, t, hd, nb1, (nq + nk) * 4);
                (q, k, v)
            }
            None => {
                let q = crate::adapter::lora_mm(ctx, lw.wq.expect("grovemoe wq"), cur);
                let k = crate::adapter::lora_mm(ctx, lw.wk.expect("grovemoe wk"), cur);
                let v = crate::adapter::lora_mm(ctx, lw.wv.expect("grovemoe wv"), cur);
                let q = ctx.reshape_3d(q, n_embd_head, a.n_head, t);
                let k = ctx.reshape_3d(k, n_embd_head, a.n_head_kv, t);
                let v = ctx.reshape_3d(v, a.n_embd_head_v, a.n_head_kv, t);
                (q, k, v)
            }
        };
        // norm FIRST, rope after (grovemoe.cpp:100-110)
        let qcur = build_norm_rms(ctx, qcur, lw.attn_q_norm, a.norm_eps);
        let kcur = build_norm_rms(ctx, kcur, lw.attn_k_norm, a.norm_eps);
        let (qcur, kcur) = rope_qk(ctx, a, inp.pos, qcur, kcur);

        let cur = attn_kv_cached(
            ctx,
            &mut graph,
            kv,
            il,
            a,
            inp,
            n_kv,
            qcur,
            kcur,
            vcur,
            kq_scale,
            0.0,
            None,
            None,
            Some(lw.wo),
            None,
        );
        let _ = sinfo;

        let ffn_inp = ctx.add(cur, inp_sa);

        let cur = build_norm_rms(ctx, ffn_inp, lw.ffn_norm, a.norm_eps);

        // the shared router logits (grovemoe.cpp:133)
        let probs = crate::adapter::lora_mm(ctx, lw.ffn_gate_inp, cur);

        // the expert MoE (grovemoe.cpp:136-150)
        let moe_out = build_moe_ffn_silu_probs(
            ctx,
            &mut graph,
            cur,
            probs,
            lw.ffn_up_exps,
            lw.ffn_gate_exps,
            lw.ffn_down_exps,
            p.n_expert,
            p.n_expert,
            p.n_group_experts,
            p.n_expert_used,
            true, // norm_w (grovemoe.cpp:144)
            p.expert_weights_scale,
            EXPERT_GATING_SOFTMAX,
            None, // grovemoe carries no exp_probs_b (grovemoe.cpp:142)
        );
        // the chunk-expert MoE over the SAME logits (grovemoe.cpp:153-164) —
        // its INPUT is the first MoE's output (`cur = moe_out` at :150);
        // n_expert_used > n_chunk_expert ? n_chunk_expert : n_expert_used
        let used_chunk = if p.n_expert_used > n_chunk_expert {
            n_chunk_expert
        } else {
            p.n_expert_used
        };
        let moe2 = build_moe_ffn_silu_probs(
            ctx,
            &mut graph,
            moe_out, // grovemoe.cpp:150 — the expert MoE's output
            probs,
            lw.ffn_up_chexps,
            lw.ffn_gate_chexps,
            lw.ffn_down_chexps,
            n_chunk_expert,
            p.n_expert,
            p.n_group_experts,
            used_chunk,
            true,
            p.expert_weights_scale,
            EXPERT_GATING_SOFTMAX,
            None, // grovemoe carries no exp_probs_b (grovemoe.cpp:158)
        );

        // cur = moe + scale(moe2, expert_group_scale) (grovemoe.cpp:167)
        let moe2 = ctx.scale(moe2, p.expert_group_scale);
        let cur = ctx.add(moe_out, moe2);

        inp_l = ctx.add(cur, ffn_inp);
    }

    let cur = build_norm_rms(ctx, inp_l, w.output_norm, a.norm_eps);
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let logits = crate::adapter::lora_mm(ctx, w.output, cur);
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

// ----------------------------------------------------------------------
// qwen35moe — verify against src/models/qwen35moe.cpp (the qwen3next graph with the
// IMRoPE sections, the attn_post_norm MoE FFN and the t_h_nextn tap)
// ----------------------------------------------------------------------

pub struct Qwen35MoeLayerWeights {
    pub attn_norm: TensorId,
    pub attn_post_norm: TensorId,
    /// full-attention layers (create_tensor_qkv, qwen35moe.cpp:74)
    pub wq: Option<TensorId>,
    pub wk: Option<TensorId>,
    pub wv: Option<TensorId>,
    pub wo: Option<TensorId>,
    pub attn_q_norm: Option<TensorId>,
    pub attn_k_norm: Option<TensorId>,
    /// GDN layers: `attn_qkv` + `attn_gate` (qwen35moe.cpp:83-84 — both
    /// NOT_REQUIRED in C; the split pair is the shipped layout)
    pub wqkv: Option<TensorId>,
    pub wqkv_gate: Option<TensorId>,
    pub ssm_conv1d: Option<TensorId>,
    /// SSM_DT "bias" {ssm_dt_rank}
    pub ssm_dt_b: Option<TensorId>,
    /// SSM_A_NOSCAN {ssm_dt_rank}
    pub ssm_a: Option<TensorId>,
    /// SSM_BETA {n_embd, n_v_heads} — separate from alpha (unlike qwen3next's
    /// packed beta|alpha, qwen35moe.cpp:88-89)
    pub ssm_beta: Option<TensorId>,
    pub ssm_alpha: Option<TensorId>,
    pub ssm_norm: Option<TensorId>,
    pub ssm_out: Option<TensorId>,
    // MoE router + experts (fused gate_up preferred)
    pub ffn_gate_inp: TensorId,
    pub ffn_gate_up_exps: Option<TensorId>,
    pub ffn_gate_exps: Option<TensorId>,
    pub ffn_up_exps: Option<TensorId>,
    pub ffn_down_exps: TensorId,
    // shared expert + its gate
    pub ffn_gate_inp_shexp: Option<TensorId>,
    pub ffn_gate_shexp: Option<TensorId>,
    pub ffn_up_shexp: Option<TensorId>,
    pub ffn_down_shexp: Option<TensorId>,
}

pub struct Qwen35MoeModelWeights {
    pub tok_embd: TensorId,
    pub output_norm: TensorId,
    /// tied to tok_embd when the file has no output.weight (qwen35moe.cpp:47-52)
    pub output: TensorId,
    /// trunk layers only — the MTP/nextn blocks load as extra decoder blocks
    /// the main pass never executes (qwen35moe.cpp:141-146)
    pub layers: Vec<Qwen35MoeLayerWeights>,
}

/// qwen35moe hparams + the GDN geometry (qwen35moe.cpp:4-34).
#[derive(Clone)]
pub struct Qwen35MoeParams {
    pub attn: AttnParams,
    pub n_embd: i64,
    pub n_head: Vec<u32>,
    pub n_head_kv: Vec<u32>,
    pub n_embd_head_k: Vec<u32>,
    pub n_embd_head_v: Vec<u32>,
    pub n_rot: Vec<u32>,
    pub is_recr: Vec<bool>,
    /// hparams.rope_sections — IMROPE (qwen35moe.cpp:163)
    pub rope_sections: [i32; 4],
    pub f_attention_scale: f32,
    pub ssm_d_conv: i64,
    pub ssm_d_inner: i64,
    pub ssm_d_state: i64,
    pub ssm_dt_rank: i64,
    pub ssm_n_group: i64,
    pub n_embd_r: u32,
    pub n_embd_s: u32,
    pub n_expert: i64,
    pub n_expert_used: i64,
    pub expert_weights_scale: f32,
}

/// verify against src/models/qwen35moe.cpp:156-249 `graph::graph` — per layer:
/// rms attn_norm → (gated delta net | gated IMRoPE full attention) → residual
/// → rms attn_post_norm → MoE (+ the sigmoid-gated shared expert) → residual →
/// final norm (t_h_nextn) → lm_head.
///
/// PARTIAL (reported): the MTP/nextn blocks are skipped (`graph_mtp`,
/// qwen35moe.cpp:550-741 — extra decoder blocks; the port loads them
/// NOT_REQUIRED); single sequence, K = 1 recurrent state
/// (`cparams.n_rs_seq == 0` — the rollback-snapshot arms of
/// delta-net-base.cpp stay unported, the batch-9 convention).
pub fn build_qwen35moe_forward(
    ctx: &mut Context,
    w: &Qwen35MoeModelWeights,
    p: &Qwen35MoeParams,
    st: &RecurrentState,
    kv: &KvCache,
    inp: &DecodeInputs,
    sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(8192);
    assert_eq!(
        p.is_recr.len(),
        n_layer,
        "Qwen35MoeParams::is_recr per layer"
    );
    assert_eq!(st.n_layer(), n_layer, "RecurrentState per layer");
    let _ = sinfo;

    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_sa = inp_l;

        let cur = build_norm_rms(ctx, inp_l, lw.attn_norm, p.attn.norm_eps);

        let cur = if p.is_recr[il] {
            // linear attention layer (qwen35moe.cpp:359-492)
            build_qwen35moe_gdn_layer(ctx, &mut graph, p, lw, st, il, cur, t)
        } else {
            // full attention layer (qwen35moe.cpp:278-357)
            build_qwen35moe_attn_layer(ctx, &mut graph, p, lw, kv, inp, n_kv, il, cur, t)
        };

        // residual → attn_post_norm (qwen35moe.cpp:203-211)
        let ffn_residual = ctx.add(cur, inp_sa);
        let normed = build_norm_rms(ctx, ffn_residual, lw.attn_post_norm, p.attn.norm_eps);

        // MoE + the gated shared expert (qwen35moe.cpp:214 / :494-548)
        let cur = build_qwen35moe_ffn(ctx, &mut graph, normed, lw, p);
        inp_l = ctx.add(cur, ffn_residual);
    }

    // final norm (t_h_nextn, qwen35moe.cpp:230-234) + lm_head
    let cur = build_norm_rms(ctx, inp_l, w.output_norm, p.attn.norm_eps);
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let logits = crate::adapter::lora_mm(ctx, w.output, cur);
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

/// qwen35moe.cpp:278-357 `build_layer_attn` — the every-4th full-attention
/// block: single Q projection twice as wide (query + gate per head), per-head
/// q/k RMS norms, **IMRoPE** (`ggml_rope_multi` with the sections), MHA over
/// the cache (no wo), `sigmoid(gate)` multiply, then wo.
#[allow(clippy::too_many_arguments)]
fn build_qwen35moe_attn_layer(
    ctx: &mut Context,
    graph: &mut Graph,
    p: &Qwen35MoeParams,
    lw: &Qwen35MoeLayerWeights,
    kv: &KvCache,
    inp: &DecodeInputs,
    n_kv: u32,
    il: usize,
    cur: TensorId,
    t: i64,
) -> TensorId {
    let a = &p.attn;
    let n_embd_head = p.n_embd_head_v[il] as i64;
    assert_eq!(
        n_embd_head, p.n_embd_head_k[il] as i64,
        "qwen35moe: k/v head dims differ"
    );
    let n_head = p.n_head[il] as i64;
    let n_head_kv = p.n_head_kv[il] as i64;
    let n_rot = p.n_rot[il] as i64;

    // the single Q projection carries the gate (qwen35moe.cpp:289-297)
    let q_full = crate::adapter::lora_mm(ctx, lw.wq.expect("wq"), cur);
    let k = crate::adapter::lora_mm(ctx, lw.wk.expect("wk"), cur);
    let v = crate::adapter::lora_mm(ctx, lw.wv.expect("wv"), cur);

    let nb1 = ctx.nb(q_full)[1] as usize;
    let stride = (n_embd_head * 2 * 4) as usize;
    let q = ctx.view_3d(
        q_full,
        n_embd_head,
        n_head,
        t,
        stride,
        stride * n_head as usize,
        0,
    );
    let gate = ctx.view_3d(
        q_full,
        n_embd_head,
        n_head,
        t,
        stride,
        stride * n_head as usize,
        (n_embd_head * 4) as usize,
    );
    let gate = ctx.cont_2d(gate, n_embd_head * n_head, t);

    // Q norm, K norm (qwen35moe.cpp:299-311)
    let q = build_norm_rms(ctx, q, lw.attn_q_norm.expect("attn_q_norm"), a.norm_eps);
    let k = ctx.reshape_3d(k, n_embd_head, n_head_kv, t);
    let k = build_norm_rms(ctx, k, lw.attn_k_norm.expect("attn_k_norm"), a.norm_eps);
    let v = ctx.reshape_3d(v, n_embd_head, n_head_kv, t);

    // IMRoPE (qwen35moe.cpp:323-333)
    let rope = |ctx: &mut Context, x: TensorId| {
        ctx.rope_multi(
            x,
            inp.pos,
            None,
            n_rot as i32,
            p.rope_sections,
            a.rope_mode,
            a.n_ctx_orig,
            a.freq_base,
            a.freq_scale,
            a.ext_factor,
            a.attn_factor,
            a.beta_fast,
            a.beta_slow,
        )
    };
    let q = rope(ctx, q);
    let k = rope(ctx, k);

    let kq_scale = if p.f_attention_scale == 0.0 {
        1.0 / (n_embd_head as f32).sqrt()
    } else {
        p.f_attention_scale
    };

    // build_attn with wo == nullptr (qwen35moe.cpp:342-345)
    let cur = attn_kv_cached(
        ctx, graph, kv, il, a, inp, n_kv, q, k, v, kq_scale, 0.0, None, None, None, None,
    );

    // attn gate, then wo (qwen35moe.cpp:347-354)
    let gate_sigmoid = ctx.sigmoid(gate);
    let cur = ctx.mul(cur, gate_sigmoid);
    crate::adapter::lora_mm(ctx, lw.wo.expect("wo"), cur)
}

/// qwen35moe.cpp:359-492 `build_layer_attn_linear` — the gated delta net with
/// the **separate** beta/alpha projections (qwen3next packs them) and the
/// silu output gate of `build_norm_gated` (:267-276).
#[allow(clippy::too_many_arguments)]
fn build_qwen35moe_gdn_layer(
    ctx: &mut Context,
    graph: &mut Graph,
    p: &Qwen35MoeParams,
    lw: &Qwen35MoeLayerWeights,
    st: &RecurrentState,
    il: usize,
    cur: TensorId,
    t: i64,
) -> TensorId {
    let d_inner = p.ssm_d_inner;
    let head_k_dim = p.ssm_d_state;
    let num_k_heads = p.ssm_n_group;
    let num_v_heads = p.ssm_dt_rank;
    let head_v_dim = d_inner / num_v_heads; // qwen35moe.cpp:370

    // build_qkvz (qwen35moe.cpp:251-265): the fused wqkv + the z gate
    let qkv_mixed = crate::adapter::lora_mm(ctx, lw.wqkv.expect("wqkv"), cur);
    let qkv_mixed = ctx.reshape_3d(qkv_mixed, ctx.ne(qkv_mixed)[0], t, 1);
    let z = crate::adapter::lora_mm(ctx, lw.wqkv_gate.expect("wqkv_gate"), cur);

    // beta: [n_embd, n_v] sigmoid (qwen35moe.cpp:382-389)
    let beta = crate::adapter::lora_mm(ctx, lw.ssm_beta.expect("ssm_beta"), cur);
    let beta = ctx.reshape_4d(beta, 1, num_v_heads, t, 1);
    let beta = ctx.sigmoid(beta);

    // gate = softplus(alpha + dt) * A (qwen35moe.cpp:391-402)
    let alpha = crate::adapter::lora_mm(ctx, lw.ssm_alpha.expect("ssm_alpha"), cur);
    let alpha = ctx.reshape_3d(alpha, num_v_heads, t, 1);
    let alpha_biased = ctx.add(alpha, lw.ssm_dt_b.expect("ssm_dt"));
    let alpha_softplus = ctx.softplus(alpha_biased);
    let gate = ctx.mul(alpha_softplus, lw.ssm_a.expect("ssm_a")); // -A_log.exp()*softplus
    let gate = ctx.reshape_4d(gate, 1, num_v_heads, t, 1);

    // conv state + causal conv (build_conv_state, delta-net-base.cpp:449-525 —
    // the n_rs_seq == 0 arm)
    let conv_kernel = lw.ssm_conv1d.expect("ssm_conv1d");
    let conv_kernel_size = ctx.ne(conv_kernel)[0];
    let conv_channels = d_inner + 2 * p.ssm_n_group * head_k_dim; // qwen35moe.cpp:407

    let conv_state = st.conv[il].expect("qwen35moe recurrent conv state");
    let conv = ctx.reshape_3d(conv_state, conv_kernel_size - 1, conv_channels, 1);
    let qkv_t = ctx.transpose(qkv_mixed);
    let conv_input = ctx.concat(conv, qkv_t, 0);
    {
        let ci_ne0 = ctx.ne(conv_input)[0];
        let ci_nb = *ctx.nb(conv_input);
        let snap = ctx.view_3d(
            conv_input,
            conv_kernel_size - 1,
            conv_channels,
            1,
            ci_nb[1] as usize,
            ci_nb[2] as usize,
            ((ci_ne0 - (conv_kernel_size - 1)) * 4) as usize,
        );
        let st_nb = *ctx.nb(conv_state);
        let row_count = (conv_kernel_size - 1) * conv_channels;
        let dst = ctx.view_2d(conv_state, row_count, 1, st_nb[1] as usize, 0);
        let cpy = ctx.cpy(snap, dst);
        graph.build_forward(ctx, cpy);
    }
    let conv_out = ctx.ssm_conv(conv_input, conv_kernel);
    let conv_out = ctx.silu(conv_out);

    // Q/K/V views over the convolved stream (qwen35moe.cpp:428-448)
    let qkv_dim = head_k_dim * num_k_heads * 2 + head_v_dim * num_v_heads;
    let nb1_qkv = GgmlType::F32.row_size(qkv_dim as usize);
    let rs_k = GgmlType::F32.row_size(head_k_dim as usize);
    let rs_v = GgmlType::F32.row_size(head_v_dim as usize);
    let mut q_conv = ctx.view_4d(
        conv_out,
        head_k_dim,
        num_k_heads,
        t,
        1,
        rs_k,
        nb1_qkv,
        nb1_qkv * t as usize,
        0,
    );
    let mut k_conv = ctx.view_4d(
        conv_out,
        head_k_dim,
        num_k_heads,
        t,
        1,
        rs_k,
        nb1_qkv,
        nb1_qkv * t as usize,
        (head_k_dim * num_k_heads * 4) as usize,
    );
    let v_conv = ctx.view_4d(
        conv_out,
        head_v_dim,
        num_v_heads,
        t,
        1,
        rs_v,
        nb1_qkv,
        nb1_qkv * t as usize,
        GgmlType::F32.row_size((2 * head_k_dim * num_k_heads) as usize),
    );

    // L2 norms (qwen35moe.cpp:453-454)
    let eps_over_n = p.attn.norm_eps / head_k_dim as f32;
    q_conv = build_gdn_l2_norm(ctx, q_conv, eps_over_n);
    k_conv = build_gdn_l2_norm(ctx, k_conv, eps_over_n);

    // head repeat when H_v != H_k — unneeded with the fused GDN
    // (qwen35moe.cpp:460-466; the port runs the fused op, so the branch is
    // dead — the port implements only the default cparams path)

    // fused GDN + write-back (build_recurrent_attn !keep, delta-net-base.cpp:546-560)
    let ssm_state = st.ssm[il].expect("qwen35moe recurrent ssm state");
    let state = ctx.reshape_4d(ssm_state, head_v_dim, head_v_dim, num_v_heads, 1);
    let gdn_out = ctx.gated_delta_net(q_conv, k_conv, v_conv, gate, beta, state, 1);
    let out = ctx.view_4d(
        gdn_out,
        head_v_dim,
        num_v_heads,
        t,
        1,
        (head_v_dim * 4) as usize,
        (head_v_dim * num_v_heads * 4) as usize,
        (head_v_dim * num_v_heads * t * 4) as usize,
        0,
    );
    {
        let snap = ctx.view_4d(
            gdn_out,
            head_v_dim,
            head_v_dim,
            num_v_heads,
            1,
            (head_v_dim * 4) as usize,
            (head_v_dim * head_v_dim * 4) as usize,
            (head_v_dim * head_v_dim * num_v_heads * 4) as usize,
            (head_v_dim * num_v_heads * t * 4) as usize,
        );
        let st_nb = *ctx.nb(ssm_state);
        let dst = ctx.view_2d(ssm_state, p.n_embd_s as i64, 1, st_nb[1] as usize, 0);
        let cpy = ctx.cpy(snap, dst);
        graph.build_forward(ctx, cpy);
    }

    // gated normalization (SILU gate, qwen35moe.cpp:267-276 / :478) + out proj
    let z2 = ctx.reshape_4d(z, head_v_dim, num_v_heads, t, 1);
    let normed = build_norm_rms(ctx, out, lw.ssm_norm.expect("ssm_norm"), p.attn.norm_eps);
    let z_silu = ctx.silu(z2);
    let attn_out = ctx.mul(normed, z_silu);
    let final_out = ctx.reshape_3d(attn_out, head_v_dim * num_v_heads, t, 1);
    let cur = crate::adapter::lora_mm(ctx, lw.ssm_out.expect("ssm_out"), final_out);
    ctx.reshape_2d(cur, p.n_embd, t)
}

/// qwen35moe.cpp:494-548 `build_layer_ffn` — softmax MoE (norm_w = true) plus
/// the shared expert gated by `sigmoid(ffn_gate_inp_shexp @ x)`.
fn build_qwen35moe_ffn(
    ctx: &mut Context,
    graph: &mut Graph,
    cur: TensorId,
    lw: &Qwen35MoeLayerWeights,
    p: &Qwen35MoeParams,
) -> TensorId {
    let moe_out = if let Some(gate_up) = lw.ffn_gate_up_exps {
        // the fused gate_up_exps variant (create_tensor_gate_up_exps,
        // llama-graph.cpp:2168-2186)
        let n_embd = ctx.ne(cur)[0];
        let n_tokens = ctx.ne(cur)[1];
        let (n_expert, n_expert_used) = (p.n_expert, p.n_expert_used);
        let logits = crate::adapter::lora_mm(ctx, lw.ffn_gate_inp, cur);
        let probs = ctx.soft_max(logits);
        let selected = ctx.argsort_top_k(probs, n_expert_used as i32);
        let probs3 = ctx.reshape_3d(probs, 1, n_expert, n_tokens);
        let mut weights = ctx.get_rows(probs3, selected);
        let w2 = ctx.reshape_2d(weights, n_expert_used, n_tokens);
        let sum = ctx.sum_rows(w2);
        let sum = ctx.clamp(sum, 6.103515625e-5, f32::INFINITY);
        let w2 = ctx.div(w2, sum);
        weights = ctx.reshape_3d(w2, 1, n_expert_used, n_tokens);
        if p.expert_weights_scale != 0.0 && p.expert_weights_scale != 1.0 {
            weights = ctx.scale(weights, p.expert_weights_scale);
        }
        graph.build_forward(ctx, weights);
        let cur3 = ctx.reshape_3d(cur, n_embd, 1, n_tokens);
        let gate_up = crate::adapter::lora_mm_id(ctx, gate_up, cur3, selected);
        let nb = *ctx.nb(gate_up);
        let n_ff = ctx.ne(gate_up)[0] / 2;
        let g = ctx.view_3d(
            gate_up,
            n_ff,
            n_expert_used,
            n_tokens,
            nb[1] as usize,
            nb[2] as usize,
            0,
        );
        let up = ctx.view_3d(
            gate_up,
            n_ff,
            n_expert_used,
            n_tokens,
            nb[1] as usize,
            nb[2] as usize,
            n_ff as usize * 4,
        );
        let act = ctx.swiglu_split(g, up);
        let mut experts = crate::adapter::lora_mm_id(ctx, lw.ffn_down_exps, act, selected);
        experts = ctx.mul(experts, weights);
        graph.build_forward(ctx, experts);
        let nb1 = ctx.nb(experts)[1] as usize;
        let nb2 = ctx.nb(experts)[2] as usize;
        let mut acc = ctx.view_2d(experts, n_embd, n_tokens, nb2, 0);
        for e in 1..n_expert_used {
            let v = ctx.view_2d(experts, n_embd, n_tokens, nb2, (e as usize) * nb1);
            acc = ctx.add(acc, v);
        }
        acc
    } else {
        build_moe_ffn_silu(
            ctx,
            graph,
            cur,
            lw.ffn_gate_inp,
            None,
            lw.ffn_up_exps.expect("ffn_up_exps"),
            None,
            lw.ffn_gate_exps,
            None,
            lw.ffn_down_exps,
            None,
            None,
            p.n_expert,
            p.n_expert_used,
            true, // norm_w (qwen35moe.cpp:507)
            p.expert_weights_scale,
            EXPERT_GATING_SOFTMAX,
        )
    };

    if let (Some(up), Some(gate), Some(down)) =
        (lw.ffn_up_shexp, lw.ffn_gate_shexp, lw.ffn_down_shexp)
    {
        let ffn_shexp = build_ffn_silu_par(ctx, cur, gate, None, up, None, down, None);
        let shared_gate =
            crate::adapter::lora_mm(ctx, lw.ffn_gate_inp_shexp.expect("ffn_gate_inp_shexp"), cur);
        let shared_gate = ctx.sigmoid(shared_gate);
        let shexp_gated = ctx.mul(ffn_shexp, shared_gate);
        ctx.add(moe_out, shexp_gated)
    } else {
        moe_out
    }
}

