pub struct Jais2LayerWeights {
    pub attn_norm: TensorId,
    pub attn_norm_b: TensorId,
    pub wqkv: Option<TensorId>,
    pub wqkv_b: Option<TensorId>,
    pub wq: Option<TensorId>,
    pub wq_b: Option<TensorId>,
    pub wk: Option<TensorId>,
    pub wk_b: Option<TensorId>,
    pub wv: Option<TensorId>,
    pub wv_b: Option<TensorId>,
    pub wo: TensorId,
    pub wo_b: TensorId,
    pub ffn_norm: TensorId,
    pub ffn_norm_b: TensorId,
    /// Jais-2 uses a simple MLP with biases (jais2.cpp:40-44)
    pub ffn_up: TensorId,
    pub ffn_up_b: TensorId,
    pub ffn_down: TensorId,
    pub ffn_down_b: TensorId,
}

pub struct Jais2ModelWeights {
    pub tok_embd: TensorId,
    pub output_norm: TensorId,
    pub output_norm_b: TensorId,
    /// jais2.cpp:21-24 — optional head with the tok_embd fallback
    pub output: TensorId,
    pub layers: Vec<Jais2LayerWeights>,
}

pub struct Jais2Params {
    pub attn: AttnParams,
}

/// verify against src/models/jais2.cpp:54-155 `llama_model_jais2::graph::graph` —
/// LayerNorm (not RMSNorm) with biases everywhere, separate Q/K/V + RoPE,
/// `1/sqrt(n_embd_head)` attention scale, relu² MLP (no gate) with up/down
/// biases. Same pieces as nemotron's LN layout plus the rope and the MLP
/// biases.
#[allow(clippy::too_many_arguments)]
pub fn build_jais2_forward(
    ctx: &mut Context,
    w: &Jais2ModelWeights,
    p: &Jais2Params,
    kv: &KvCache,
    inp: &DecodeInputs,
    _sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let a = &p.attn;
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(2048);
    // jais2.cpp:56-58
    assert_eq!(a.n_embd_head_v, a.n_embd_head_k, "jais2: head_v == head_k");
    assert_eq!(a.n_embd_head_k, a.n_rot, "jais2: head == n_rot");

    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_sa = inp_l;

        // pre-attention LayerNorm (jais2.cpp:75-79)
        let cur = build_norm(
            ctx,
            inp_l,
            Some(lw.attn_norm),
            Some(lw.attn_norm_b),
            a.norm_eps,
        );

        // build_qkv + rope (jais2.cpp:83-100)
        let (q, k, v) = if let Some(wqkv) = lw.wqkv {
            qkv_fused(ctx, wqkv, lw.wqkv_b, a, cur, t)
        } else {
            qkv_separate_parts(
                ctx,
                lw.wq.expect("jais2 wq"),
                lw.wq_b,
                lw.wk.expect("jais2 wk"),
                lw.wk_b,
                lw.wv.expect("jais2 wv"),
                lw.wv_b,
                a,
                cur,
                t,
            )
        };
        let (q, k) = rope_qk(ctx, a, inp.pos, q, k);
        let cur = attn_kv_cached(
            ctx,
            &mut graph,
            kv,
            il,
            a,
            inp,
            n_kv,
            q,
            k,
            v,
            1.0 / (a.n_embd_head_v as f32).sqrt(), // jais2.cpp:104
            0.0,
            None,
            None,
            Some(lw.wo),
            Some(lw.wo_b),
        );

        let ffn_inp = ctx.add(cur, inp_sa);
        // pre-FFN LayerNorm (jais2.cpp:117-121)
        let cur = build_norm(
            ctx,
            ffn_inp,
            Some(lw.ffn_norm),
            Some(lw.ffn_norm_b),
            a.norm_eps,
        );
        // up → relu2 → down, both with biases (jais2.cpp:123-131)
        let cur = build_ffn_relu_sqr(
            ctx,
            cur,
            lw.ffn_up,
            Some(lw.ffn_up_b),
            lw.ffn_down,
            Some(lw.ffn_down_b),
        );
        // build_cvec (jais2.cpp:135) — not ported (no-op)
        inp_l = ctx.add(cur, ffn_inp);
    }

    // final LayerNorm (jais2.cpp:140-144)
    let cur = build_norm(
        ctx,
        inp_l,
        Some(w.output_norm),
        Some(w.output_norm_b),
        a.norm_eps,
    );
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let logits = crate::adapter::lora_mm(ctx, w.output, cur);
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

