/// verify against src/models/dream.cpp:52-138 `llama_model_dream::graph::graph` —
/// "copied from qwen2" over `build_attn_inp_no_cache` (:68): the diffusion
/// attention attends the tokens of its own ubatch through the all-visible
/// [n_tokens, n_tokens] mask, exactly like llada-moe's. The pinned reference
/// creates no memory for DREAM (llama-model.cpp:2289-2295) so every
/// generation driver refuses it — verified in-port (batch-10 protocol).
#[allow(clippy::too_many_arguments)]
pub fn build_dream_forward(
    ctx: &mut Context,
    w: &DreamModelWeights,
    p: &DreamParams,
    _kv: &KvCache,
    inp: &DecodeInputs,
    _sinfo: SlotInfo,
    _n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let a = &p.attn;
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(2048);
    // dream.cpp:57-58
    assert_eq!(a.n_embd_head_v, a.n_embd_head_k, "dream: head_v == head_k");
    assert_eq!(a.n_embd_head_k, a.n_rot, "dream: head == n_rot");

    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    // build_attn_inp_no_cache (dream.cpp:68): the [t, t] all-visible mask;
    // F16 under FA (llama-graph.cpp:2748)
    let mask_ty = if a.use_flash_attn {
        GgmlType::F16
    } else {
        GgmlType::F32
    };
    let kq_mask = ctx.new_tensor_2d(mask_ty, t, t);
    ctx.arena_resize_tensor(kq_mask);
    ctx.data_bytes_mut(kq_mask).unwrap().fill(0);

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_sa = inp_l;

        let cur = build_norm_rms(ctx, inp_l, lw.attn_norm, a.norm_eps);

        let (q, k, v) = if let Some(wqkv) = lw.wqkv {
            qkv_fused(ctx, wqkv, lw.wqkv_b, a, cur, t)
        } else {
            qkv_separate_parts(
                ctx,
                lw.wq.expect("dream wq"),
                lw.wq_b,
                lw.wk.expect("dream wk"),
                lw.wk_b,
                lw.wv.expect("dream wv"),
                lw.wv_b,
                a,
                cur,
                t,
            )
        };
        let (q, k) = rope_qk(ctx, a, inp.pos, q, k);

        let kq_scale = 1.0 / (a.n_embd_head_v as f32).sqrt(); // dream.cpp:96
        let cur = attn_no_cache_fa(
            ctx,
            q,
            k,
            v,
            kq_mask,
            kq_scale,
            a.use_flash_attn,
            Some(lw.wo),
            lw.wo_b,
        );

        let ffn_inp = ctx.add(cur, inp_sa);
        let cur = build_norm_rms(ctx, ffn_inp, lw.ffn_norm, a.norm_eps);
        let cur = build_ffn_silu_par(
            ctx,
            cur,
            lw.ffn_gate,
            None,
            lw.ffn_up,
            None,
            lw.ffn_down,
            None,
        );
        // build_cvec (dream.cpp:118) — not ported (no-op)
        inp_l = ctx.add(cur, ffn_inp);
    }

    let cur = build_norm_rms(ctx, inp_l, w.output_norm, a.norm_eps);
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let mut logits = crate::adapter::lora_mm(ctx, w.output, cur);
    if let Some(b) = w.output_b {
        logits = ctx.add(logits, b);
    }
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

