pub struct EurobertLayerWeights {
    pub attn_norm: TensorId,
    pub wqkv: Option<TensorId>,
    pub wqkv_b: Option<TensorId>,
    pub wq: Option<TensorId>,
    pub wq_b: Option<TensorId>,
    pub wk: Option<TensorId>,
    pub wk_b: Option<TensorId>,
    pub wv: Option<TensorId>,
    pub wv_b: Option<TensorId>,
    pub wo: TensorId,
    /// eurobert.cpp:82 passes model.layers[il].wo_b (nullptr — never created)
    pub wo_b: Option<TensorId>,
    pub ffn_norm: TensorId,
    pub ffn_gate: TensorId,
    pub ffn_down: TensorId,
    pub ffn_up: TensorId,
}

pub struct EurobertModelWeights {
    pub tok_embd: TensorId,
    /// the encoder's final RMS norm (eurobert.cpp:16) — no output head, the
    /// graph only assigns res->t_embd (:121)
    pub output_norm: TensorId,
    pub layers: Vec<EurobertLayerWeights>,
}

/// The rope facts `ggml_rope_ext` needs (eurobert.cpp:65-75) — the
/// EncoderParams the bert/t5 builders take has no rope fields, so the
/// eurobert arm carries them separately.
#[derive(Clone, Copy)]
pub struct EurobertRope {
    pub n_rot: i32,
    pub rope_mode: i32,
    pub n_ctx_orig: i32,
    pub freq_base: f32,
    pub freq_scale: f32,
    pub ext_factor: f32,
    pub attn_factor: f32,
    pub beta_fast: f32,
    pub beta_slow: f32,
}

/// verify against src/models/eurobert.cpp:38-124 `llama_model_eurobert::graph::graph` —
/// the bert-shaped encoder loop with RMS norms, rope'd Q/K (NEOX, the arch's
/// rope-type table entry) and a gated SwiGLU FFN; `res->t_embd` only (no
/// logits, no output head). Like bert, the non-FA branch of build_attn_mha
/// is used (the port's encoder baseline; the reference dump is generated
/// `--fa off`).
pub fn build_eurobert_forward(
    ctx: &mut Context,
    w: &EurobertModelWeights,
    p: &EncoderParams,
    rope: &EurobertRope,
    inp: &EncodeInputs,
    n_tokens: usize,
) -> EncodeResult {
    let t = n_tokens as i64;
    let n_head = p.n_head;
    let n_head_kv = p.n_head_kv;
    let n_embd_head = p.n_embd_head;
    let eps = p.f_norm_rms_eps;
    let mut graph = Graph::new(1024);
    // eurobert.cpp:41 — head_v == head_k (single n_embd_head like bert)
    let _ = n_embd_head;

    // inpL = build_inp_embd(model.tok_embd) (eurobert.cpp:47-48)
    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);

    let mut layer_outs = Vec::with_capacity(w.layers.len());
    let n_layer = w.layers.len();
    for il in 0..n_layer {
        let lw = &w.layers[il];

        // build_norm(inpL, attn_norm, NULL, LLM_NORM_RMS, il) (eurobert.cpp:57-59)
        let cur = build_norm_rms(ctx, inp_l, lw.attn_norm, eps);

        // build_qkv + rope (eurobert.cpp:62-75); create_tensor_qkv loads the
        // full-width q ([n_embd, n_embd], eurobert.cpp:23)
        let (q, k, v) = if let Some(wqkv) = lw.wqkv {
            qkv_fused_plain(ctx, wqkv, lw.wqkv_b, n_embd_head, n_head, n_head_kv, cur, t)
        } else {
            let mut q = crate::adapter::lora_mm(ctx, lw.wq.expect("eurobert wq"), cur);
            if let Some(b) = lw.wq_b {
                q = ctx.add(q, b);
            }
            let mut k = crate::adapter::lora_mm(ctx, lw.wk.expect("eurobert wk"), cur);
            if let Some(b) = lw.wk_b {
                k = ctx.add(k, b);
            }
            let mut v = crate::adapter::lora_mm(ctx, lw.wv.expect("eurobert wv"), cur);
            if let Some(b) = lw.wv_b {
                v = ctx.add(v, b);
            }
            let q = ctx.reshape_3d(q, n_embd_head, n_head, t);
            let k = ctx.reshape_3d(k, n_embd_head, n_head_kv, t);
            let v = ctx.reshape_3d(v, n_embd_head, n_head_kv, t);
            (q, k, v)
        };
        let r = |ctx: &mut Context, x: TensorId| {
            ctx.rope_ext(
                x,
                inp.pos.expect("eurobert: build_inp_pos"),
                None,
                rope.n_rot,
                rope.rope_mode,
                rope.n_ctx_orig,
                rope.freq_base,
                rope.freq_scale,
                rope.ext_factor,
                rope.attn_factor,
                rope.beta_fast,
                rope.beta_slow,
            )
        };
        let q = r(ctx, q);
        let k = r(ctx, k);

        // build_attn with kq_scale = 1/sqrt(n_embd_head) (eurobert.cpp:81-84)
        let kq_scale = 1.0 / (n_embd_head as f32).sqrt();
        let mut cur = attn_no_cache(
            ctx,
            q,
            k,
            v,
            None,
            inp.kq_mask,
            kq_scale,
            Some(lw.wo),
            lw.wo_b,
        );

        // last-layer output-row selection (eurobert.cpp:87-90)
        if il == n_layer - 1 {
            cur = ctx.get_rows(cur, inp.out_ids);
            inp_l = ctx.get_rows(inp_l, inp.out_ids);
        }

        let cur = ctx.add(cur, inp_l);
        let ffn_inp = cur;

        let cur = build_norm_rms(ctx, ffn_inp, lw.ffn_norm, eps);
        // gated SwiGLU parallel FFN (eurobert.cpp:102-107)
        let cur = build_ffn_silu_par(
            ctx,
            cur,
            lw.ffn_gate,
            None,
            lw.ffn_up,
            None,
            lw.ffn_down,
            None,
        );
        inp_l = ctx.add(cur, ffn_inp);
        layer_outs.push(inp_l);
    }

    // the final RMS norm is res->t_embd (eurobert.cpp:116-123)
    let embd = build_norm_rms(ctx, inp_l, w.output_norm, eps);
    graph.build_forward(ctx, embd);
    EncodeResult {
        embd,
        layer_outs,
        graph,
    }
}

/// `build_qkv`'s fused branch for the encoder path (no AttnParams — the
/// encoder's q width is the full n_embd, eurobert.cpp:23, so the q/k/v split
/// uses n_embd_head like the AttnParams path would).
#[allow(clippy::too_many_arguments)]
fn qkv_fused_plain(
    ctx: &mut Context,
    lw_qkv: TensorId,
    lw_qkv_b: Option<TensorId>,
    n_embd_head: i64,
    n_head: i64,
    n_head_kv: i64,
    cur: TensorId,
    t: i64,
) -> (TensorId, TensorId, TensorId) {
    let mut qkv = crate::adapter::lora_mm(ctx, lw_qkv, cur);
    if let Some(b) = lw_qkv_b {
        qkv = ctx.add(qkv, b);
    }
    let n_embd_q = n_embd_head * n_head;
    let n_embd_k = n_embd_head * n_head_kv;
    let nb1 = ctx.nb(qkv)[1] as usize;
    let hd = n_embd_head as usize;
    let q = ctx.view_3d(qkv, n_embd_head, n_head, t, hd * 4, nb1, 0);
    let k = ctx.view_3d(
        qkv,
        n_embd_head,
        n_head_kv,
        t,
        hd * 4,
        nb1,
        n_embd_q as usize * 4,
    );
    let v = ctx.view_3d(
        qkv,
        n_embd_head,
        n_head_kv,
        t,
        hd * 4,
        nb1,
        (n_embd_q + n_embd_k) as usize * 4,
    );
    (q, k, v)
}

