/// verify against src/models/hrm-text.cpp:88-213 `llama_model_hrm_text::graph` —
/// `build_stack` (hrm-text.cpp:93-166) runs lps pre-norm decoder layers with
/// the **weightless** RMS norms (build_norm(cur, nullptr, …), the qwen3next
/// sigmoid-gated attention over the slot's own cache row) and closes with the
/// parameterless stack norm (:162). The main graph threads zH/zL: each stack
/// consumes `zH + zL` (the [n_embd] low state broadcasting over tokens,
/// :183-196) and the final zH feeds the lm_head through `res->t_embd`.
/// `res->t_layer_inp`-style debug taps don't exist here; `build_cvec` (:158)
/// is the shared no-op (control vectors not ported).
#[allow(clippy::too_many_arguments)]
pub fn build_hrm_text_forward(
    ctx: &mut Context,
    w: &HrmTextModelWeights,
    p: &HrmTextParams,
    kv: &KvCache,
    inp: &DecodeInputs,
    _sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let a = &p.attn;
    let t = n_tokens as i64;
    let lps = p.n_layers_per_stack;
    let mut graph = Graph::new(4096);
    // hrm-text.cpp:97 — 1/sqrt(n_embd_head_k) (no attention.scale read)
    let kq_scale = 1.0 / (a.n_embd_head_k as f32).sqrt();

    // one stack invocation: lps pre-norm decoder layers, then the
    // parameterless final norm (hrm-text.cpp:93-166)
    fn build_stack(
        ctx: &mut Context,
        graph: &mut Graph,
        kv: &KvCache,
        inp: &DecodeInputs,
        a: &AttnParams,
        w: &HrmTextModelWeights,
        kq_scale: f32,
        cur0: TensorId,
        slot_base: usize,
        lps: usize,
        n_kv: u32,
        t: i64,
    ) -> TensorId {
        let mut cur = cur0;
        for il in 0..lps {
            let s = slot_base + il;
            let lw = &w.layers[s];

            let inp_sa = cur;

            // build_norm(cur, nullptr, nullptr, LLM_NORM_RMS, s) (hrm-text.cpp:107)
            cur = ctx.rms_norm(cur, a.norm_eps);

            // sigmoid-gated self-attention (hrm-text.cpp:110-138)
            {
                // gate = build_lora_mm(layer.wqkv_gate, cur) (:112)
                let gate = crate::adapter::lora_mm(ctx, lw.wqkv_gate, cur);

                // build_qkv + rope (:115-123)
                let (q, k, v) = if let Some(wqkv) = lw.wqkv {
                    qkv_fused(ctx, wqkv, lw.wqkv_b, a, cur, t)
                } else {
                    qkv_separate_parts(
                        ctx,
                        lw.wq.expect("hrm-text wq"),
                        lw.wq_b,
                        lw.wk.expect("hrm-text wk"),
                        lw.wk_b,
                        lw.wv.expect("hrm-text wv"),
                        lw.wv_b,
                        a,
                        cur,
                        t,
                    )
                };
                let r = |ctx: &mut Context, x: TensorId| {
                    ctx.rope_ext(
                        x,
                        inp.pos,
                        None,
                        a.n_rot as i32,
                        a.rope_mode,
                        a.n_ctx_orig,
                        a.freq_base,
                        a.freq_scale,
                        a.ext_factor,
                        a.attn_factor,
                        a.beta_fast,
                        a.beta_slow,
                    )
                };
                let q = r(ctx, q);
                let k = r(ctx, k);

                // build_attn with the o_proj deferred until after the gate
                // (:125-127 — wo/wo_b both nullptr there)
                cur = attn_kv_cached(
                    ctx, graph, kv, s, a, inp, n_kv, q, k, v, kq_scale, 0.0, None, None, None, None,
                );

                // cur = cur * sigmoid(gate) (:130-134)
                let gate = ctx.sigmoid(gate);
                cur = ctx.mul(cur, gate);

                // the deferred o_proj (:136)
                cur = crate::adapter::lora_mm(ctx, lw.wo, cur);
            }

            cur = ctx.add(cur, inp_sa); // attn_add (:140)

            let inp_sa = cur;
            cur = ctx.rms_norm(cur, a.norm_eps); // ffn_norm, weightless (:144)
            cur = build_ffn_silu_par(
                ctx,
                cur,
                lw.ffn_gate,
                None,
                lw.ffn_up,
                None,
                lw.ffn_down,
                None,
            );
            cur = ctx.add(cur, inp_sa); // ffn_add (:155-156)
                                        // build_cvec (hrm-text.cpp:158) — not ported (no-op)
        }

        // the parameterless stack norm (:162)
        ctx.rms_norm(cur, a.norm_eps)
    }

    // zH = build_inp_embd(model.tok_embd) — scaled by f_embedding_scale
    // inside the shared build_inp_embd (hrm-text.cpp:174)
    let mut z_h = ctx.get_rows(w.tok_embd, inp.tokens);
    z_h = crate::adapter::lora_embd(ctx, w.tok_embd, z_h, inp.tokens);
    if p.f_embedding_scale != 0.0 {
        z_h = ctx.scale(z_h, p.f_embedding_scale);
    }

    // the learned low-cycle state is [n_embd]; binary ops broadcast it over
    // [n_embd, n_tokens] (hrm-text.cpp:182-183)
    let mut z_l = w.hrm_z_l_init;

    // the alternating low/high stack passes (hrm-text.cpp:185-196)
    for h in 0..p.n_h_cycles {
        for l in 0..p.n_l_cycles {
            let slot_base = (h * (p.n_l_cycles + 1) + l) * lps;
            let zin = ctx.add(z_h, z_l);
            z_l = build_stack(
                ctx, &mut graph, kv, inp, a, w, kq_scale, zin, slot_base, lps, n_kv, t,
            );
        }
        let slot_base = (h * (p.n_l_cycles + 1) + p.n_l_cycles) * lps;
        let zin = ctx.add(z_h, z_l);
        z_h = build_stack(
            ctx, &mut graph, kv, inp, a, w, kq_scale, zin, slot_base, lps, n_kv, t,
        );
    }

    // result_norm + the lm_head (hrm-text.cpp:198-210; the weightless final
    // norm already ran inside the last stack)
    let cur = z_h;
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let logits = crate::adapter::lora_mm(ctx, w.output, cur);
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

