pub struct LagunaLayerWeights {
    pub attn_norm: TensorId,
    pub wqkv: Option<TensorId>,
    pub wqkv_b: Option<TensorId>,
    pub wq: Option<TensorId>,
    pub wq_b: Option<TensorId>,
    pub wk: Option<TensorId>,
    pub wk_b: Option<TensorId>,
    pub wv: Option<TensorId>,
    pub wv_b: Option<TensorId>,
    pub wo: TensorId,
    /// laguna.cpp:258 passes layer.wo_s (nullptr — never created)
    pub wo_b: Option<TensorId>,
    pub attn_q_norm: TensorId,
    pub attn_k_norm: TensorId,
    /// `attn_gate.weight` [n_embd, n_gate_out] — the softplus output gate;
    /// the width picks the per-head (XS.2) vs per-element (M.1) layout
    /// (laguna.cpp:99-122)
    pub wqkv_gate: TensorId,
    pub ffn_norm: TensorId,
    // ---- dense layers (il < n_layer_dense_lead): the plain SwiGLU FFN ----
    pub ffn_gate: Option<TensorId>,
    pub ffn_up: Option<TensorId>,
    pub ffn_down: Option<TensorId>,
    // ---- MoE layers: the sigmoid router + the always-on shared expert ----
    pub ffn_gate_inp: Option<TensorId>,
    /// `ffn_exp_probs.bias` [n_expert] — the score-correction bias that
    /// steers the top-k only (laguna.cpp:129)
    pub ffn_exp_probs_b: Option<TensorId>,
    pub ffn_gate_exps: Option<TensorId>,
    pub ffn_up_exps: Option<TensorId>,
    pub ffn_down_exps: Option<TensorId>,
    pub ffn_gate_shexp: Option<TensorId>,
    pub ffn_up_shexp: Option<TensorId>,
    pub ffn_down_shexp: Option<TensorId>,
}

pub struct LagunaModelWeights {
    pub tok_embd: TensorId,
    pub output_norm: TensorId,
    /// laguna.cpp:71-75 — optional head with the tok_embd tie fallback
    pub output: TensorId,
    pub layers: Vec<LagunaLayerWeights>,
}

pub struct LagunaParams {
    /// layer-0 geometry (n_head/n_head_kv overridden per layer below)
    pub attn: AttnParams,
    /// hparams.n_head(il) — Laguna varies the head count between the full and
    /// the SWA layers (laguna.cpp:85)
    pub n_head: Vec<i64>,
    /// hparams.n_head_kv(il) — uniform in every file, carried per layer like
    /// the C reads it (laguna.cpp:86)
    pub n_head_kv: Vec<i64>,
    /// hparams.is_swa(il) — only meaningful when `has_swa` (XS.2's period-4
    /// dense-first pattern; M.1 has no sliding window at all)
    pub is_swa: Vec<bool>,
    pub has_swa: bool,
    /// hparams.n_rot_swa — the SWA layers' rope width (laguna.cpp:48)
    pub n_rot_swa: i32,
    /// hparams.rope_freq_base_train_swa / rope_freq_scale_train_swa — the
    /// SWA layers run plain rope (laguna.cpp:46-47)
    pub freq_base_swa: f32,
    pub freq_scale_swa: f32,
    /// hparams.n_ctx_train — the SWA layers' n_ctx_orig (laguna.cpp:191)
    pub n_ctx_train: i32,
    pub n_layer_dense_lead: u32,
    pub n_expert: i64,
    pub n_expert_used: i64,
    /// hparams.expert_gating_func (SIGMOID unless the file says otherwise,
    /// laguna.cpp:51-55)
    pub expert_gating_func: i32,
    pub expert_weights_norm: bool,
    pub expert_weights_scale: f32,
}

/// verify against src/models/laguna.cpp:152-331 `llama_model_laguna::graph` — the
/// pre-norm MoE body with: the **softplus** attention output gate computed
/// from the pre-attention hidden state (:209, g_proj on the same input as
/// q/k/v), the QK RMSNorms at head_dim level before rope (:213-214), the
/// per-layer-type RoPE (SWA layers: plain rope — ext/beta zeroed, attn_factor
/// forced 1.0, n_ctx_orig = n_ctx_train — full layers: the cparams YaRN
/// values, :179-191), the o_proj **after** the gate (:258), the sigmoid-routed
/// MoE with the score-correction bias (:277-289) summed with the always-on
/// shared expert (:292-300), and no post-attn / post-ffn norms. The gate
/// width decides per-head ([1, n_head] broadcast over head_dim, :249-252) vs
/// per-element (:254) multiplication.
#[allow(clippy::too_many_arguments)]
pub fn build_laguna_forward(
    ctx: &mut Context,
    w: &LagunaModelWeights,
    p: &LagunaParams,
    kv: &KvCache,
    inp: &DecodeInputs,
    _sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let base = &p.attn;
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(8192);
    // laguna.cpp:153-154
    assert_eq!(
        base.n_embd_head_v, base.n_embd_head_k,
        "laguna: head_v == head_k"
    );
    // laguna.cpp:153,170 — n_embd_head = n_embd_head_v() == n_embd_head_k()
    let n_embd_head = base.n_embd_head_v;
    let kq_scale = 1.0 / (n_embd_head as f32).sqrt(); // laguna.cpp:170

    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);
    // no MuP embedding scale (laguna.cpp:159-160)

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let is_swa_il = p.has_swa && p.is_swa[il];
        let n_head_il = p.n_head[il];
        let n_head_kv_il = p.n_head_kv[il];

        // this layer's AttnParams — the per-layer head counts
        // (create_tensor_qkv sized wq/wo off them, laguna.cpp:85-94)
        let mut a = base.clone();
        a.n_head = n_head_il;
        a.n_head_kv = n_head_kv_il;

        // per-layer-type RoPE config (laguna.cpp:179-191): SWA layers run
        // plain rope (no YaRN), achieved by zeroing the YaRN ext/beta params
        // and forcing attn_factor 1.0 there
        let (n_rot_l, freq_base_l, freq_scale_l, n_ctx_orig_l) = if is_swa_il {
            (
                p.n_rot_swa,
                p.freq_base_swa,
                p.freq_scale_swa,
                p.n_ctx_train,
            )
        } else {
            (
                base.n_rot as i32,
                base.freq_base,
                base.freq_scale,
                base.n_ctx_orig,
            )
        };
        let (ext_factor_l, attn_factor_l, beta_fast_l, beta_slow_l) = if is_swa_il {
            (0.0, 1.0, 0.0, 0.0)
        } else {
            (
                base.ext_factor,
                base.attn_factor,
                base.beta_fast,
                base.beta_slow,
            )
        };

        let inp_sa = inp_l;

        // pre-norm (laguna.cpp:196)
        let attn_inp = build_norm_rms(ctx, inp_l, lw.attn_norm, base.norm_eps);

        // self-attention (laguna.cpp:200-260)
        let cur = {
            let (mut q, mut k, v) = if let Some(wqkv) = lw.wqkv {
                qkv_fused(ctx, wqkv, lw.wqkv_b, &a, attn_inp, t)
            } else {
                qkv_separate_parts(
                    ctx,
                    lw.wq.expect("laguna wq"),
                    lw.wq_b,
                    lw.wk.expect("laguna wk"),
                    lw.wk_b,
                    lw.wv.expect("laguna wv"),
                    lw.wv_b,
                    &a,
                    attn_inp,
                    t,
                )
            };

            // g_proj on the *pre-attention* hidden state (laguna.cpp:201-210)
            let gate = crate::adapter::lora_mm(ctx, lw.wqkv_gate, attn_inp);

            // QK RMSNorm at head_dim level, Qwen3 style (laguna.cpp:213-214)
            q = build_norm_rms(ctx, q, lw.attn_q_norm, base.norm_eps);
            k = build_norm_rms(ctx, k, lw.attn_k_norm, base.norm_eps);

            let r = |ctx: &mut Context, x: TensorId| {
                ctx.rope_ext(
                    x,
                    inp.pos,
                    None,
                    n_rot_l,
                    base.rope_mode,
                    n_ctx_orig_l,
                    freq_base_l,
                    freq_scale_l,
                    ext_factor_l,
                    attn_factor_l,
                    beta_fast_l,
                    beta_slow_l,
                )
            };
            let q = r(ctx, q);
            let k = r(ctx, k);

            // build_attn with the o_proj deferred until after the gating
            // (laguna.cpp:227-233); the iswa pair routes through
            // attn_kv_cached's per-layer cache selection
            let mut cur = attn_kv_cached(
                ctx, &mut graph, kv, il, &a, inp, n_kv, q, k, v, kq_scale, 0.0, None, None, None,
                None,
            );

            // softplus output gate (laguna.cpp:244); the width picked at load
            // time mirrors here — per-head reshape vs the direct mul (:248-255)
            let gate = ctx.softplus(gate);
            if ctx.ne(lw.wqkv_gate)[1] == n_head_il {
                cur = ctx.reshape_3d(cur, n_embd_head, n_head_il, t);
                let gate = ctx.reshape_3d(gate, 1, n_head_il, t);
                cur = ctx.mul(cur, gate);
                cur = ctx.reshape_2d(cur, n_embd_head * n_head_il, t);
            } else {
                cur = ctx.mul(cur, gate);
            }

            // the deferred o_proj (laguna.cpp:258)
            crate::adapter::lora_mm(ctx, lw.wo, cur)
        };

        // the il == n_layer-1 inp_out_ids get_rows only selects output rows —
        // the port computes every row and the caller picks (the qwen3 note)

        let ffn_inp = ctx.add(cur, inp_sa);

        // pre-norm only, no post-attn norm (laguna.cpp:271)
        let cur = build_norm_rms(ctx, ffn_inp, lw.ffn_norm, base.norm_eps);

        let cur = if il >= p.n_layer_dense_lead as usize {
            // sigmoid routing + score-correction bias + sum-norm + the
            // optional routed_scaling_factor — all inside build_moe_ffn
            // (laguna.cpp:277-289)
            let moe_out = build_moe_ffn_silu(
                ctx,
                &mut graph,
                cur,
                lw.ffn_gate_inp.expect("laguna moe layer"),
                None,
                lw.ffn_up_exps.expect("laguna moe layer"),
                None,
                Some(lw.ffn_gate_exps.expect("laguna moe layer")),
                None,
                lw.ffn_down_exps.expect("laguna moe layer"),
                None,
                lw.ffn_exp_probs_b,
                p.n_expert,
                p.n_expert_used,
                p.expert_weights_norm,
                p.expert_weights_scale,
                p.expert_gating_func,
            );
            // the always-on shared expert, summed in parallel (laguna.cpp:292-298)
            let ffn_shexp = build_ffn_silu_par(
                ctx,
                cur,
                lw.ffn_gate_shexp.expect("laguna moe layer"),
                None,
                lw.ffn_up_shexp.expect("laguna moe layer"),
                None,
                lw.ffn_down_shexp.expect("laguna moe layer"),
                None,
            );
            ctx.add(moe_out, ffn_shexp)
        } else {
            // dense FFN for the leading n_layer_dense_lead layers
            // (laguna.cpp:304-309)
            build_ffn_silu_par(
                ctx,
                cur,
                lw.ffn_gate.expect("laguna dense layer"),
                None,
                lw.ffn_up.expect("laguna dense layer"),
                None,
                lw.ffn_down.expect("laguna dense layer"),
                None,
            )
        };

        // no post-ffn norm; build_cvec (laguna.cpp:315) — not ported (no-op)
        inp_l = ctx.add(cur, ffn_inp);
    }

    let cur = build_norm_rms(ctx, inp_l, w.output_norm, base.norm_eps);
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let logits = crate::adapter::lora_mm(ctx, w.output, cur);
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

