// bitnet — src/models/bitnet.cpp:51-170 (b1.58: the sub-norms after attention
// and inside the FFN, weight-scale LoRA tensors, tok_embd as the tied head)
// ----------------------------------------------------------------------

pub struct BitnetLayerWeights {
    pub attn_norm: TensorId,
    pub attn_sub_norm: TensorId,
    pub wq: TensorId,
    pub wq_s: Option<TensorId>,
    pub wk: TensorId,
    pub wk_s: Option<TensorId>,
    pub wv: TensorId,
    pub wv_s: Option<TensorId>,
    pub wo: TensorId,
    pub wo_s: Option<TensorId>,
    pub wo_b: Option<TensorId>,
    pub ffn_norm: TensorId,
    pub ffn_sub_norm: TensorId,
    pub ffn_gate: TensorId,
    pub ffn_gate_s: Option<TensorId>,
    pub ffn_down: TensorId,
    pub ffn_down_s: Option<TensorId>,
    pub ffn_up: TensorId,
    pub ffn_up_s: Option<TensorId>,
}

pub struct BitnetModelWeights {
    pub tok_embd: TensorId,
    pub output_norm: TensorId,
    pub layers: Vec<BitnetLayerWeights>,
}

#[derive(Clone)]
pub struct BitnetParams {
    pub attn: AttnParams,
    pub norm_rms_eps: f32,
}

/// verify against src/models/bitnet.cpp:51-170 — build_attn with wo == NULL then
/// attn_sub_norm + lora_mm(wo, wo_s) (:97-110); the FFN is up+gate (silu par)
/// → ffn_sub_norm {n_ff} → lora_mm(down) (:127-141); the lm_head is
/// build_lora_mm(model.tok_embd, cur) — the model has NO output tensor
/// (:163-164, "FIXME: do not use model.tok_embd directly").
pub fn build_bitnet_forward(
    ctx: &mut Context,
    w: &BitnetModelWeights,
    p: &BitnetParams,
    kv: &KvCache,
    inp: &DecodeInputs,
    _sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(2048);

    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    let mut inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_sa = inp_l;

        let cur = build_norm_rms(ctx, inp_l, lw.attn_norm, p.norm_rms_eps);

        // self-attention (bitnet.cpp:77-111) — build_qkv's separate path with
        // the per-tensor weight scales (build_lora_mm(wq, cur, wq_s), no
        // biases in bitnet files)
        let q = crate::adapter::lora_mm_s(ctx, lw.wq, cur, lw.wq_s);
        let k = crate::adapter::lora_mm_s(ctx, lw.wk, cur, lw.wk_s);
        let v = crate::adapter::lora_mm_s(ctx, lw.wv, cur, lw.wv_s);
        let q = ctx.reshape_3d(q, p.attn.n_embd_head_k, p.attn.n_head, t);
        let k = ctx.reshape_3d(k, p.attn.n_embd_head_k, p.attn.n_head_kv, t);
        let v = ctx.reshape_3d(v, p.attn.n_embd_head_v, p.attn.n_head_kv, t);
        let (q, k) = rope_qk(ctx, &p.attn, inp.pos, q, k);

        let kq_scale = 1.0 / (p.attn.n_embd_head_v as f32).sqrt();
        // build_attn(..., NULL, NULL, NULL, ...) — the wo projection is NOT
        // part of build_attn here (bitnet.cpp:97-99)
        let cur = attn_kv_cached(
            ctx, &mut graph, kv, il, &p.attn, inp, n_kv, q, k, v, kq_scale, 0.0, None, None, None,
            None,
        );

        let cur = build_norm_rms(ctx, cur, lw.attn_sub_norm, p.norm_rms_eps);
        let mut cur = crate::adapter::lora_mm_s(ctx, lw.wo, cur, lw.wo_s);
        if let Some(b) = lw.wo_b {
            cur = ctx.add(cur, b);
        }

        let ffn_inp = ctx.add(cur, inp_sa);

        // feed-forward forward (bitnet.cpp:121-141): up/gate in parallel, then
        // the {n_ff} sub-norm, then down
        let cur = build_norm_rms(ctx, ffn_inp, lw.ffn_norm, p.norm_rms_eps);
        let up = crate::adapter::lora_mm_s(ctx, lw.ffn_up, cur, lw.ffn_up_s);
        let gate = crate::adapter::lora_mm_s(ctx, lw.ffn_gate, cur, lw.ffn_gate_s);
        let gate_silu = ctx.silu(gate);
        let prod = ctx.mul(gate_silu, up);
        let cur = build_norm_rms(ctx, prod, lw.ffn_sub_norm, p.norm_rms_eps);
        let cur = crate::adapter::lora_mm_s(ctx, lw.ffn_down, cur, lw.ffn_down_s);

        let cur = ctx.add(cur, ffn_inp);
        inp_l = cur;
    }

    let cur = build_norm_rms(ctx, inp_l, w.output_norm, p.norm_rms_eps);
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    // lm_head = tok_embd (bitnet.cpp:163-164)
    let logits = crate::adapter::lora_mm(ctx, w.tok_embd, cur);
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

