pub struct DbrxLayerWeights {
    /// {n_embd, n_embd + 2*n_embd_gqa} (dbrx.cpp:31)
    pub wqkv: TensorId,
    pub wo: TensorId,
    pub attn_norm: TensorId,
    /// LLM_NORM between attention and the MoE (dbrx.cpp:34)
    pub attn_out_norm: TensorId,
    pub ffn_gate_inp: TensorId,
    pub ffn_gate_exps: TensorId,
    pub ffn_down_exps: TensorId,
    pub ffn_up_exps: TensorId,
}

pub struct DbrxModelWeights {
    pub tok_embd: TensorId,
    pub output_norm: TensorId,
    pub output: TensorId,
    pub layers: Vec<DbrxLayerWeights>,
}

#[derive(Clone)]
pub struct DbrxParams {
    pub attn: AttnParams,
    /// hparams.f_norm_eps (LLM_NORM, dbrx.cpp:4)
    pub norm_ln_eps: f32,
    /// hparams.f_clamp_kqv (REQUIRED, dbrx.cpp:5)
    pub clamp_kqv: f32,
    pub n_expert: i64,
    pub n_expert_used: i64,
    pub expert_weights_scale: f32,
}

/// verify against src/models/dbrx.cpp:47-154 — the clamped fused QKV, plain rope, the
/// attn_out_norm LayerNorm over the residual sum, then the softmax-gated MoE
/// (norm_w = true) on the normed input.
pub fn build_dbrx_forward(
    ctx: &mut Context,
    w: &DbrxModelWeights,
    p: &DbrxParams,
    kv: &KvCache,
    inp: &DecodeInputs,
    _sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(2048);
    assert_eq!(p.attn.n_embd_head_k, p.attn.n_rot, "dbrx.cpp:51");

    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    let mut inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_sa = inp_l;

        let cur = build_norm(ctx, inp_l, Some(lw.attn_norm), None, p.norm_ln_eps);

        // self-attention (dbrx.cpp:74-98) — qkv_fused_clamped: the fused
        // mul_mat then ggml_clamp on the whole tensor before the view split
        let (q, k, v) = qkv_fused_clamp(lw.wqkv, None, p.clamp_kqv, &p.attn, ctx, cur, t);
        let (q, k) = rope_qk(ctx, &p.attn, inp.pos, q, k);

        let kq_scale = 1.0 / (p.attn.n_embd_head_v as f32).sqrt();
        let cur = attn_kv_cached(
            ctx,
            &mut graph,
            kv,
            il,
            &p.attn,
            inp,
            n_kv,
            q,
            k,
            v,
            kq_scale,
            0.0,
            None,
            None,
            Some(lw.wo),
            None,
        );

        let ffn_inp = ctx.add(cur, inp_sa);

        // MoE branch (dbrx.cpp:108-129): attn_out_norm (LLM_NORM) over the
        // residual sum, softmax gating, norm_w = true
        let cur = build_norm(ctx, ffn_inp, Some(lw.attn_out_norm), None, p.norm_ln_eps);
        let cur = build_moe_ffn_silu_gu(
            ctx,
            &mut graph,
            cur,
            lw.ffn_gate_inp,
            None,
            Some(lw.ffn_up_exps),
            Some(lw.ffn_gate_exps),
            lw.ffn_down_exps,
            p.n_expert,
            p.n_expert_used,
            true, // norm_w (dbrx.cpp:122)
            p.expert_weights_scale,
            EXPERT_GATING_SOFTMAX,
            false,
        );

        let cur = ctx.add(cur, ffn_inp);
        inp_l = cur;
    }

    let cur = build_norm(ctx, inp_l, Some(w.output_norm), None, p.norm_ln_eps);
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let logits = crate::adapter::lora_mm(ctx, w.output, cur);
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

