// qwen3vl / qwen3vlmoe — src/models/qwen3vl.cpp:60-197 and
// src/models/qwen3vlmoe.cpp:64-190 (the LM side of Qwen3-VL: IMRoPE after
// the Q/K norms, the deepstack residual injection from the padded token
// embedding table)
// ----------------------------------------------------------------------

pub struct Qwen3VlLayerWeights {
    pub attn_norm: TensorId,
    pub wqkv: Option<TensorId>,
    pub wqkv_b: Option<TensorId>,
    pub wq: Option<TensorId>,
    pub wk: Option<TensorId>,
    pub wv: Option<TensorId>,
    pub wq_b: Option<TensorId>,
    pub wk_b: Option<TensorId>,
    pub wv_b: Option<TensorId>,
    pub wo: TensorId,
    pub wo_b: Option<TensorId>,
    pub attn_k_norm: TensorId,
    pub attn_q_norm: TensorId,
    pub ffn_norm: TensorId,
    /// dense variant
    pub ffn_gate: Option<TensorId>,
    pub ffn_down: Option<TensorId>,
    pub ffn_up: Option<TensorId>,
    /// MoE variant
    pub ffn_gate_inp: Option<TensorId>,
    pub ffn_gate_exps: Option<TensorId>,
    pub ffn_down_exps: Option<TensorId>,
    pub ffn_up_exps: Option<TensorId>,
}

pub struct Qwen3VlModelWeights {
    pub tok_embd: TensorId,
    pub output_norm: TensorId,
    pub output: TensorId,
    pub layers: Vec<Qwen3VlLayerWeights>,
}

#[derive(Clone)]
pub struct Qwen3VlParams {
    pub attn: AttnParams,
    pub norm_rms_eps: f32,
    /// hparams.rope_sections (REQUIRED)
    pub rope_sections: [i32; 4],
    /// hparams.n_deepstack_layers (optional, 0 default)
    pub n_deepstack_layers: usize,
    /// the MoE variant's counts (0/None on the dense files)
    pub n_expert: i64,
    pub n_expert_used: i64,
    pub expert_weights_scale: f32,
}

/// verify against src/models/qwen3vl.cpp:60-197 / qwen3vlmoe.cpp:64-190 — one builder
/// for both: the dense arm (qwen3vl.cpp:140-146) vs the softmax-gated MoE arm
/// (qwen3vlmoe.cpp:144-157), keyed on ffn_gate_inp like the C's two graphs
/// key on their loaders. The deepstack injection (:153-157 / :164-168) adds
/// the (il+1)-th n_embd block of the **padded** input embedding — a token
/// batch pads n_deepstack_layers*n_embd zero rows (build_inp_embd,
/// llama-graph.cpp:2408-2411), so text-only deepstack adds zeros exactly like
/// the reference.
#[allow(clippy::too_many_arguments)]
pub fn build_qwen3vl_forward(
    ctx: &mut Context,
    w: &Qwen3VlModelWeights,
    p: &Qwen3VlParams,
    kv: &KvCache,
    inp: &DecodeInputs,
    _sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let sections = p.rope_sections;
    let n_embd = ctx.ne(w.tok_embd)[0];
    let mut graph = Graph::new(2048);
    assert_eq!(p.attn.n_embd_head_k, p.attn.n_rot, "qwen3vl.cpp:67");

    let tok_rows = ctx.get_rows(w.tok_embd, inp.tokens);
    let tok_rows = crate::adapter::lora_embd(ctx, w.tok_embd, tok_rows, inp.tokens);

    // res->t_inp_embd — the [n_embd_inp, T] padded embedding (llama-graph.cpp
    // :2408-2411): ggml_pad the token rows with n_ds*n_embd zero rows so the
    // deepstack views exist; inpL is the first n_embd rows (:2427-2429)
    let (t_inp_embd, mut inp_l) = if p.n_deepstack_layers > 0 {
        let padded = ctx.pad(
            tok_rows,
            (p.n_deepstack_layers as i32) * n_embd as i32,
            0,
            0,
            0,
        );
        let nb = ctx.nb(padded)[1] as usize;
        let head = ctx.view_2d(padded, n_embd, t, nb, 0);
        (padded, head)
    } else {
        (tok_rows, tok_rows)
    };

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_sa = inp_l;

        let cur = build_norm_rms(ctx, inp_l, lw.attn_norm, p.norm_rms_eps);

        // self-attention (qwen3vl.cpp:93-124)
        let (q, k, v) = if let Some(wqkv) = lw.wqkv {
            qkv_fused(ctx, wqkv, lw.wqkv_b, &p.attn, cur, t)
        } else {
            qkv_separate_parts(
                ctx,
                lw.wq.expect("wq"),
                lw.wq_b,
                lw.wk.expect("wk"),
                lw.wk_b,
                lw.wv.expect("wv"),
                lw.wv_b,
                &p.attn,
                cur,
                t,
            )
        };
        // q/k RMS norms then IMRoPE (qwen3vl.cpp:99-119)
        let q = build_norm_rms(ctx, q, lw.attn_q_norm, p.norm_rms_eps);
        let k = build_norm_rms(ctx, k, lw.attn_k_norm, p.norm_rms_eps);
        let rope = |ctx: &mut Context, x: TensorId| {
            ctx.rope_multi(
                x,
                inp.pos,
                None,
                p.attn.n_rot as i32,
                sections,
                p.attn.rope_mode,
                p.attn.n_ctx_orig,
                p.attn.freq_base,
                p.attn.freq_scale,
                p.attn.ext_factor,
                p.attn.attn_factor,
                p.attn.beta_fast,
                p.attn.beta_slow,
            )
        };
        let (q, k) = (rope(ctx, q), rope(ctx, k));

        let kq_scale = 1.0 / (p.attn.n_embd_head_v as f32).sqrt();
        let cur = attn_kv_cached(
            ctx,
            &mut graph,
            kv,
            il,
            &p.attn,
            inp,
            n_kv,
            q,
            k,
            v,
            kq_scale,
            0.0,
            None,
            None,
            Some(lw.wo),
            lw.wo_b,
        );

        let ffn_inp = ctx.add(cur, inp_sa);
        let cur = build_norm_rms(ctx, ffn_inp, lw.ffn_norm, p.norm_rms_eps);
        let cur = if let Some(gate_inp) = lw.ffn_gate_inp {
            // MoE branch (qwen3vlmoe.cpp:144-157) — softmax gating, norm_w
            build_moe_ffn_silu_gu(
                ctx,
                &mut graph,
                cur,
                gate_inp,
                None,
                lw.ffn_up_exps,
                lw.ffn_gate_exps,
                lw.ffn_down_exps.expect("ffn_down_exps"),
                p.n_expert,
                p.n_expert_used,
                true,
                p.expert_weights_scale,
                EXPERT_GATING_SOFTMAX,
                false,
            )
        } else {
            build_ffn_silu_par(
                ctx,
                cur,
                lw.ffn_gate.expect("ffn_gate"),
                None,
                lw.ffn_up.expect("ffn_up"),
                None,
                lw.ffn_down.expect("ffn_down"),
                None,
            )
        };
        let mut cur = ctx.add(cur, ffn_inp);

        // deepstack (qwen3vl.cpp:153-157) — view the (il+1)-th n_embd block
        // of the padded input embedding and add it
        if il < p.n_deepstack_layers {
            let nb = ctx.nb(t_inp_embd)[1] as usize;
            let ds = ctx.view_2d(t_inp_embd, n_embd, t, nb, ((il + 1) * n_embd as usize) * 4);
            cur = ctx.add(cur, ds);
        }
        inp_l = cur;
    }

    let cur = build_norm_rms(ctx, inp_l, w.output_norm, p.norm_rms_eps);
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let logits = crate::adapter::lora_mm(ctx, w.output, cur);
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

// ----------------------------------------------------------------------
// glm-dsa — src/models/glm-dsa.cpp:196-530 (GLM-4.5/5: the DSA trunk — MLA
// absorption over the K-only lid cache, the lightning indexer with the
// shared-indexer layers reusing the previous top-k, the sigmoid-gated MoE
// with the wide shared expert) + graph_mtp (:539-769)
// ----------------------------------------------------------------------

/// glm-dsa per-layer weights — the deepseek2 MLA set plus the DSA indexer
/// five and the GLM shared-expert widths.
pub struct GlmDsaLayerWeights {
    pub attn_norm: TensorId,
    pub attn_q_a_norm: TensorId,
    pub attn_kv_a_norm: TensorId,
    pub wq_a: TensorId,
    pub wq_b: TensorId,
    pub wkv_a_mqa: TensorId,
    /// {n_embd_head_qk_nope, kv_lora_rank, n_head} (glm-dsa.cpp:136 — always
    /// the split wk_b, no legacy unsplit wkv_b)
    pub wk_b: TensorId,
    /// {kv_lora_rank, n_embd_head_v_mla, n_head}
    pub wv_b: TensorId,
    pub wo: TensorId,
    pub ffn_norm: TensorId,
    // DSA indexer (glm-dsa.cpp:144-148, all TENSOR_NOT_REQUIRED)
    pub indexer_k_norm: Option<TensorId>,
    pub indexer_k_norm_b: Option<TensorId>,
    pub indexer_proj: Option<TensorId>,
    pub indexer_attn_k: Option<TensorId>,
    pub indexer_attn_q_b: Option<TensorId>,
    // dense-lead layers
    pub ffn_gate: Option<TensorId>,
    pub ffn_down: Option<TensorId>,
    pub ffn_up: Option<TensorId>,
    // MoE layers
    pub ffn_gate_inp: Option<TensorId>,
    pub ffn_exp_probs_b: Option<TensorId>,
    pub ffn_gate_exps: Option<TensorId>,
    pub ffn_down_exps: Option<TensorId>,
    pub ffn_up_exps: Option<TensorId>,
    /// {n_embd, n_ff_exp * n_expert_shared} (glm-dsa.cpp:170-172)
    pub ffn_gate_shexp: Option<TensorId>,
    pub ffn_down_shexp: Option<TensorId>,
    pub ffn_up_shexp: Option<TensorId>,
}

pub struct GlmDsaModelWeights {
    pub tok_embd: TensorId,
    pub output_norm: TensorId,
    /// tied to tok_embd when the file has no output.weight (glm-dsa.cpp:114-117)
    pub output: TensorId,
    pub layers: Vec<GlmDsaLayerWeights>,
}

#[derive(Clone)]
pub struct GlmDsaParams {
    pub attn: AttnParams,
    pub n_embd: i64,
    pub n_embd_head_k_mla: i64,
    pub n_embd_head_v_mla: i64,
    pub kv_lora_rank: i64,
    pub rope_yarn_log_mul: f32,
    pub n_layer_dense_lead: u32,
    pub n_expert: i64,
    pub n_expert_used: i64,
    /// hparams.n_expert_shared — the shared expert is n_ff_exp * n_expert_
    /// shared wide (glm-dsa.cpp:170-172)
    pub n_expert_shared: i64,
    pub expert_weights_norm: bool,
    pub expert_weights_scale: f32,
    /// NONE defaults to SIGMOID (glm-dsa.cpp:54-57)
    pub expert_gating_func: i32,
    // DSA indexer (glm-dsa.cpp:49-51)
    pub indexer_n_head: i64,
    pub indexer_head_size: i64,
    pub indexer_top_k: i64,
    /// hparams.f_norm_eps — the indexer k LAYER-norm eps (read from
    /// f_norm_eps like deepseek32's fixed 1e-6; glm-dsa reads no LN eps, so
    /// the synthetic files pin 1e-6 and the field carries it)
    pub f_norm_eps: f32,
    /// hparams.is_indexer_full(il) (glm-dsa.cpp:59-66)
    pub is_indexer_full: Vec<bool>,
}

/// verify against src/models/glm-dsa.cpp:196-530 — the deepseek32 graph with:
///   * the shared-indexer layers (is_indexer_full == false) reusing the
///     previous full layer's top_k (:243-245, :362-367);
///   * the sigmoid-by-default MoE + the wide shared expert (:467-498);
///   * the plain `ggml_mul_mat(model.output, ...)` lm_head (:524 — no
///     build_lora_mm scale path);
///   * `res->t_h_nextn` mounted on the post-norm hidden state (:512-514) —
///     the port's ForwardResult::embd.
///
/// The MTP/nextn embeddings plumbing (`embeddings_nextn`, :449/:516-518) is
/// the driver-side tap the other DSA archs already carry; the graph here
/// keeps the masked-row fold (`graph::out_rows`).
#[allow(clippy::too_many_arguments)]
pub fn build_glm_dsa_forward(
    ctx: &mut Context,
    w: &GlmDsaModelWeights,
    p: &GlmDsaParams,
    kv: &KvCache,
    inp: &DecodeInputs,
    _sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let ap = &p.attn;

    let n_embd_head_k = p.n_embd_head_k_mla;
    let n_embd_head_qk_rope = ap.n_rot;
    let n_embd_head_qk_nope = n_embd_head_k - n_embd_head_qk_rope;
    let kv_lora_rank = p.kv_lora_rank;
    let n_indexer_head = p.indexer_n_head;
    let n_embd_indexer_head = p.indexer_head_size;

    // the indexer head layout is [rope | nope] (glm-dsa.cpp:213-214)
    assert!(
        ap.n_rot <= n_embd_indexer_head,
        "glm-dsa: n_rot <= indexer_head_size"
    );

    // the YaRN pre-scaled kq_scale (glm-dsa.cpp:218-228 — the deepseek2
    // formula, [TAG_DEEPSEEK2_YARN_LOG_MUL_FIX])
    assert!(ap.ext_factor >= 0.0);
    let attn_factor_org = ap.attn_factor * (1.0 + 0.1 * (1.0f32 / ap.freq_scale).ln());
    let mscale =
        attn_factor_org * (1.0 + 0.1 * p.rope_yarn_log_mul * (1.0f32 / ap.freq_scale).ln());
    let kq_scale = 1.0 * mscale * mscale / (n_embd_head_k as f32).sqrt();

    let lid = kv.lid.as_ref().expect("glm-dsa needs the dsa lid cache");
    let lid_step = kv
        .lid_step
        .expect("glm-dsa needs the lid step inputs (KvCache::lid_step)");
    let n_kv_lid = kv.n_kv_lid();

    let mut graph = Graph::new(1024);
    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    // Difference vs Deepseek 3.2: shared indexer layers reuse the top_k from
    // the previous full indexer layers (glm-dsa.cpp:243-245)
    let mut prev_top_k: Option<TensorId> = None;

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_sa = inp_l;
        let mut cur = build_norm_rms(ctx, inp_l, lw.attn_norm, ap.norm_eps);

        // self_attention (glm-dsa.cpp:253-446)
        let n_head = ap.n_head;

        let mut qr = ctx.mul_mat(lw.wq_a, cur);
        qr = build_norm_rms(ctx, qr, lw.attn_q_a_norm, ap.norm_eps);

        // lightning indexer (glm-dsa.cpp:261-367) — the deepseek32
        // construction, but only on the "full" layers
        let top_k = if p.is_indexer_full[il] {
            let mut indexer_q = ctx.mul_mat(lw.indexer_attn_q_b.expect("indexer_attn_q_b"), qr);
            // {n_embd_indexer_head, n_indexer_head, n_tokens} (:268-273, NORM)
            indexer_q = ctx.reshape_3d(indexer_q, n_embd_indexer_head, n_indexer_head, t);
            indexer_q = ctx.rope_ext(
                indexer_q,
                inp.pos,
                None,
                ap.n_rot as i32,
                0, /* LLAMA_ROPE_TYPE_NORM */
                ap.n_ctx_orig,
                ap.freq_base,
                ap.freq_scale,
                ap.ext_factor,
                ap.attn_factor,
                ap.beta_fast,
                ap.beta_slow,
            );

            let mut indexer_k = ctx.mul_mat(lw.indexer_attn_k.expect("indexer_attn_k"), cur);
            indexer_k = build_norm_layer(
                ctx,
                indexer_k,
                lw.indexer_k_norm.expect("indexer_k_norm"),
                lw.indexer_k_norm_b,
                p.f_norm_eps,
            );
            // {n_embd_indexer_head, 1, n_tokens} (:282-286, NORM)
            indexer_k = ctx.reshape_3d(indexer_k, n_embd_indexer_head, 1, t);
            indexer_k = ctx.rope_ext(
                indexer_k,
                inp.pos,
                None,
                ap.n_rot as i32,
                0, /* LLAMA_ROPE_TYPE_NORM */
                ap.n_ctx_orig,
                ap.freq_base,
                ap.freq_scale,
                ap.ext_factor,
                ap.attn_factor,
                ap.beta_fast,
                ap.beta_slow,
            );

            // Hadamard transform (glm-dsa.cpp:289-293)
            indexer_q = ctx.mul_mat(lid_step.k_rot, indexer_q);
            indexer_k = ctx.mul_mat(lid_step.k_rot, indexer_k);

            // store indexer keys to the lid cache (:295-298)
            let nb2 = ctx.nb(indexer_k)[2] as usize;
            let k_rows = ctx.view_2d(indexer_k, n_embd_indexer_head, t, nb2, 0);
            let k_dst = ctx.set_rows(lid.layers[il], k_rows, lid_step.row_idx);
            graph.build_forward(ctx, k_dst);

            // prepare indexer weights (:300-302)
            let mut indexer_weights = ctx.mul_mat(lw.indexer_proj.expect("indexer_proj"), cur);

            // get cached indexer keys (:304-305)
            let indexer_k = kv.get_k_lid(ctx, il, n_kv_lid);

            // pre-scale weights (:312-314)
            indexer_weights = ctx.scale(
                indexer_weights,
                1.0 / (n_embd_indexer_head as f32 * n_indexer_head as f32).sqrt(),
            );

            // the fused lightning indexer (cparams.fused_lid default true,
            // llama-context.cpp:238) — the reference's default path
            let indexer_score =
                ctx.lightning_indexer(indexer_q, indexer_k, indexer_weights, lid_step.kq_mask);

            // get indices of top k indexer scores (:357-361)
            let n_top_k = (ctx.ne(indexer_score)[0]).min(p.indexer_top_k);
            let top_k_raw = ctx.top_k(indexer_score, n_top_k as i32);
            let top_k = ctx.cont(top_k_raw);
            prev_top_k = Some(top_k);
            top_k
        } else {
            // "shared" indexer layer — reuse the previous full layer's top-k
            // (glm-dsa.cpp:362-367)
            prev_top_k.expect("shared indexer layer must follow a previous full indexer layer")
        };

        let q = ctx.mul_mat(lw.wq_b, qr);

        // split into {n_embd_head_qk_nope, n_head, n_tokens} (:369-382)
        let (qnb1, qnb2) = {
            let rs = ctx.ty(q).row_size(n_embd_head_k as usize);
            (rs, rs * n_head as usize)
        };
        let q_nope = ctx.view_3d(q, n_embd_head_qk_nope, n_head, t, qnb1, qnb2, 0);
        let q_pe = ctx.view_3d(
            q,
            n_embd_head_qk_rope,
            n_head,
            t,
            qnb1,
            qnb2,
            ctx.ty(q).row_size(n_embd_head_qk_nope as usize),
        );

        let kv_cmpr_pe = ctx.mul_mat(lw.wkv_a_mqa, cur);
        let kv_cmpr = {
            let rs = ctx
                .ty(kv_cmpr_pe)
                .row_size((kv_lora_rank + n_embd_head_qk_rope) as usize);
            ctx.view_2d(kv_cmpr_pe, kv_lora_rank, t, rs, 0)
        };
        let k_pe = {
            let rs = ctx
                .ty(kv_cmpr_pe)
                .row_size((kv_lora_rank + n_embd_head_qk_rope) as usize);
            ctx.view_3d(
                kv_cmpr_pe,
                n_embd_head_qk_rope,
                1,
                t,
                rs,
                rs,
                ctx.ty(kv_cmpr_pe).row_size(kv_lora_rank as usize),
            )
        };
        let q_pe = ctx.rope_ext(
            q_pe,
            inp.pos,
            None,
            ap.n_rot as i32,
            ap.rope_mode,
            ap.n_ctx_orig,
            ap.freq_base,
            ap.freq_scale,
            ap.ext_factor,
            ap.attn_factor,
            ap.beta_fast,
            ap.beta_slow,
        );
        let k_pe = ctx.rope_ext(
            k_pe,
            inp.pos,
            None,
            ap.n_rot as i32,
            ap.rope_mode,
            ap.n_ctx_orig,
            ap.freq_base,
            ap.freq_scale,
            ap.ext_factor,
            ap.attn_factor,
            ap.beta_fast,
            ap.beta_slow,
        );
        let kv_cmpr = build_norm_rms(ctx, kv_cmpr, lw.attn_kv_a_norm, ap.norm_eps);

        // MLA attention (glm-dsa.cpp:411-445) — the absorbed MQA flow with the
        // top_k-composed mask
        let q_nope = ctx.permute(q_nope, 0, 2, 1, 3);
        let q_nope_absorbed = ctx.mul_mat(lw.wk_b, q_nope);
        let q_nope_absorbed = ctx.permute(q_nope_absorbed, 0, 2, 1, 3);
        let qcur = ctx.concat(q_nope_absorbed, q_pe, 0);
        let kv_cmpr3 = ctx.reshape_3d(kv_cmpr, kv_lora_rank, 1, t);
        let kcur = ctx.concat(kv_cmpr3, k_pe, 0);

        cur = attn_k_cached_mla(
            ctx,
            &mut graph,
            kv,
            il,
            ap,
            inp,
            n_kv,
            qcur,
            kcur,
            kv_cmpr3,
            kq_scale,
            lw.wv_b,
            Some(lw.wo),
            Some(top_k),
        );

        let ffn_inp = ctx.add(cur, inp_sa);
        let mut cur = build_norm_rms(ctx, ffn_inp, lw.ffn_norm, ap.norm_eps);

        if (il as u32) < p.n_layer_dense_lead {
            // dense-lead layers (glm-dsa.cpp:459-465)
            cur = build_ffn_silu_par(
                ctx,
                cur,
                lw.ffn_gate.expect("ffn_gate (dense-lead layer)"),
                None,
                lw.ffn_up.expect("ffn_up (dense-lead layer)"),
                None,
                lw.ffn_down.expect("ffn_down (dense-lead layer)"),
                None,
            );
        } else {
            // MoE + shared expert (glm-dsa.cpp:466-498) — sigmoid by default,
            // the wide shared expert
            let moe_out = build_moe_ffn_deepseek2_like(
                ctx,
                &mut graph,
                cur,
                lw.ffn_gate_inp.expect("ffn_gate_inp"),
                lw.ffn_exp_probs_b,
                lw.ffn_gate_exps,
                lw.ffn_up_exps,
                lw.ffn_down_exps.expect("ffn_down_exps"),
                p.n_expert,
                p.n_expert_used,
                p.expert_weights_norm,
                p.expert_weights_scale,
                p.expert_gating_func,
            );
            let ffn_shexp = build_ffn_silu_par(
                ctx,
                cur,
                lw.ffn_gate_shexp.expect("ffn_gate_shexp"),
                None,
                lw.ffn_up_shexp.expect("ffn_up_shexp"),
                None,
                lw.ffn_down_shexp.expect("ffn_down_shexp"),
                None,
            );
            cur = ctx.add(moe_out, ffn_shexp);
        }
        inp_l = ctx.add(cur, ffn_inp);
    }
    let cur = inp_l;

    // the post-norm hidden state also feeds the NextN/MTP draft head
    // (glm-dsa.cpp:510-514 — res->t_h_nextn on the normed state)
    let normed = build_norm_rms(ctx, cur, w.output_norm, ap.norm_eps);
    let cur = graph::out_rows(ctx, normed, inp.out_ids);

    // lm_head (glm-dsa.cpp:523-524) — plain ggml_mul_mat, no lora scale
    let logits = ctx.mul_mat(w.output, cur);

    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(normed),
    }
}

/// `build_moe_ffn` for glm-dsa (llama-graph.cpp:1993-2368) — the deepseek2
/// variant with the `ffn_exp_probs_b` router bias and the parameterized
/// gating function; the split gate/up form (glm-dsa files carry no fused
/// gate_up tensor).
#[allow(clippy::too_many_arguments)]
fn build_moe_ffn_deepseek2_like(
    ctx: &mut Context,
    graph: &mut Graph,
    cur: TensorId,
    gate_inp: TensorId,
    exp_probs_b: Option<TensorId>,
    gate_exps: Option<TensorId>,
    up_exps: Option<TensorId>,
    down_exps: TensorId,
    n_expert: i64,
    n_expert_used: i64,
    norm_w: bool,
    w_scale: f32,
    gating_op: i32,
) -> TensorId {
    // routing (llama-graph.cpp:2017-2118): the activation runs on the raw
    // logits; the experts-selection bias is added to the *activated* probs
    // only (the weights keep the unbiased probs — "leave probs unbiased as
    // it's later used to get expert weights", :2075-2080)
    let logits = crate::adapter::lora_mm(ctx, gate_inp, cur);
    let probs = match gating_op {
        EXPERT_GATING_SOFTMAX => ctx.soft_max(logits),
        EXPERT_GATING_SIGMOID => ctx.sigmoid(logits),
        other => unimplemented!("glm-dsa moe: gating op {other}"),
    };
    let selection_probs = match exp_probs_b {
        Some(b) => ctx.add(probs, b),
        None => probs,
    };
    let selected = ctx.argsort_top_k(selection_probs, n_expert_used as i32);

    let n_embd = ctx.ne(cur)[0];
    let n_tokens = ctx.ne(cur)[1];
    let probs3 = ctx.reshape_3d(probs, 1, n_expert, n_tokens);
    let mut weights = ctx.get_rows(probs3, selected);
    if norm_w {
        let w2 = ctx.reshape_2d(weights, n_expert_used, n_tokens);
        let sum = ctx.sum_rows(w2);
        let sum = ctx.clamp(sum, 6.103515625e-5, f32::INFINITY);
        let w2 = ctx.div(w2, sum);
        weights = ctx.reshape_3d(w2, 1, n_expert_used, n_tokens);
    }
    if w_scale != 0.0 && w_scale != 1.0 {
        weights = ctx.scale(weights, w_scale);
    }
    graph.build_forward(ctx, weights);

    let cur3 = ctx.reshape_3d(cur, n_embd, 1, n_tokens);
    let up = crate::adapter::lora_mm_id(ctx, up_exps.expect("up_exps"), cur3, selected);
    let gate = crate::adapter::lora_mm_id(ctx, gate_exps.expect("gate_exps"), cur3, selected);
    let act = ctx.swiglu_split(gate, up);
    let mut experts = crate::adapter::lora_mm_id(ctx, down_exps, act, selected);
    experts = ctx.mul(experts, weights);
    graph.build_forward(ctx, experts);

    // aggregate (llama-graph.cpp:2329-2358)
    let nb1 = ctx.nb(experts)[1] as usize;
    let nb2 = ctx.nb(experts)[2] as usize;
    let mut moe_out = ctx.view_2d(experts, n_embd, n_tokens, nb2, 0);
    graph.build_forward(ctx, moe_out);
    for i in 1..n_expert_used as usize {
        let vi = ctx.view_2d(experts, n_embd, n_tokens, nb2, i * nb1);
        graph.build_forward(ctx, vi);
        moe_out = ctx.add(moe_out, vi);
        graph.build_forward(ctx, moe_out);
    }
    if n_expert_used == 1 {
        moe_out = ctx.cont(moe_out);
    }
    moe_out
}

/// Weights of the glm-dsa MTP block: the layer at index `n_layer` carries a
/// full MLA trunk tensor set plus the `nextn.*` head (glm-dsa.cpp:176-185).
pub struct GlmDsaMtpWeights {
    pub tok_embd: TensorId,
    pub output_norm: TensorId,
    pub output: TensorId,
    pub nextn: DeepseekMtpNextn,
    /// the MTP layer (`model.layers[n_layer]`) — its trunk-shaped tensors
    pub layer: GlmDsaLayerWeights,
}

/// verify against src/models/glm-dsa.cpp:539-769 `graph_mtp` — the deepseek2-style MLA
/// MTP head over the glm-dsa block: eh_proj(concat(enorm(embd), hnorm(h))) →
/// attn_norm → dense MLA attention (build_attn_inp_k, no DSA indexer — "The
/// DSA indexer is not used at runtime (same as the trunk graph)", :538) →
/// ffn_norm → sigmoid MoE + shared expert → shared_head_norm (fallback
/// output_norm) → shared LM head. The attention/MLA chain is line-for-line
/// `build_deepseek_mla_mtp_body`'s (deepseek2.cpp:215-415 ≡ glm-dsa.cpp:622-
/// 705); the FFN differs only in the gating/norm parameters, which ride the
/// layer weights here.
#[allow(clippy::too_many_arguments)]
pub fn build_glm_dsa_mtp_forward(
    ctx: &mut Context,
    w: &GlmDsaMtpWeights,
    p: &GlmDsaParams,
    kv: &KvCache,
    inp: &DecodeInputs,
    h_in: MtpHInput,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let t = n_tokens as i64;
    let ap = &p.attn;
    let lw = &w.layer;

    // glm-dsa.cpp:541-543 — the assembled-model asserts (n_layer_nextn > 0,
    // == 1, is_mla) hold by construction of the MTP context
    let n_embd_head_k_mla = p.n_embd_head_k_mla;
    let n_embd_head_qk_rope = ap.n_rot;
    let n_embd_head_qk_nope = n_embd_head_k_mla - n_embd_head_qk_rope;
    let kv_lora_rank = p.kv_lora_rank;
    assert!(n_embd_head_qk_nope >= 1);

    // the YaRN pre-scaled kq_scale (:564-570 — the trunk formula, EXACTLY)
    assert!(ap.ext_factor >= 0.0);
    let attn_factor_org = ap.attn_factor * (1.0 + 0.1 * (1.0f32 / ap.freq_scale).ln());
    let mscale =
        attn_factor_org * (1.0 + 0.1 * p.rope_yarn_log_mul * (1.0f32 / ap.freq_scale).ln());
    let kq_scale = 1.0 * mscale * mscale / (n_embd_head_k_mla as f32).sqrt();

    let mut graph = Graph::new(1024);

    // llm_graph_input_embd_h (glm-dsa.cpp:573-597)
    let tok_embd_w = w.nextn.embed_tokens.unwrap_or(w.tok_embd);
    let tok_embd = ctx.get_rows(tok_embd_w, inp.tokens);
    let h_embd = h_in;

    // hnorm / enorm (:605-609)
    let h_norm = build_norm_rms(ctx, h_embd, w.nextn.hnorm, ap.norm_eps);
    let e_norm = build_norm_rms(ctx, tok_embd, w.nextn.enorm, ap.norm_eps);

    // eh_proj over the concatenated norms (:611-614)
    let concat = ctx.concat(e_norm, h_norm, 0);
    let inp_sa = crate::adapter::lora_mm(ctx, w.nextn.eh_proj, concat);

    // self-attention: dense MLA, same construction as the deepseek2 trunk
    // (glm-dsa.cpp:622-705)
    let cur = build_norm_rms(ctx, inp_sa, lw.attn_norm, ap.norm_eps);

    let q = ctx.mul_mat(lw.wq_a, cur);
    let q = build_norm_rms(ctx, q, lw.attn_q_a_norm, ap.norm_eps);
    let q = ctx.mul_mat(lw.wq_b, q);

    let n_head = ap.n_head;
    let (qnb1, qnb2) = (ctx.nb(q)[1] as usize, ctx.nb(q)[2] as usize);
    let q_nope = ctx.view_3d(q, n_embd_head_qk_nope, n_head, t, qnb1, qnb2, 0);
    let q_pe = ctx.view_3d(
        q,
        n_embd_head_qk_rope,
        n_head,
        t,
        qnb1,
        qnb2,
        ctx.ty(q).row_size(n_embd_head_qk_nope as usize),
    );

    let kv_cmpr_pe = ctx.mul_mat(lw.wkv_a_mqa, cur);
    let kv_cmpr = {
        let rs = ctx
            .ty(kv_cmpr_pe)
            .row_size((kv_lora_rank + n_embd_head_qk_rope) as usize);
        ctx.view_2d(kv_cmpr_pe, kv_lora_rank, t, rs, 0)
    };
    let k_pe = {
        let rs = ctx
            .ty(kv_cmpr_pe)
            .row_size((kv_lora_rank + n_embd_head_qk_rope) as usize);
        ctx.view_3d(
            kv_cmpr_pe,
            n_embd_head_qk_rope,
            1,
            t,
            rs,
            rs,
            ctx.ty(kv_cmpr_pe).row_size(kv_lora_rank as usize),
        )
    };

    let kv_cmpr = build_norm_rms(ctx, kv_cmpr, lw.attn_kv_a_norm, ap.norm_eps);

    let q_pe = ctx.rope_ext(
        q_pe,
        inp.pos,
        None,
        ap.n_rot as i32,
        ap.rope_mode,
        ap.n_ctx_orig,
        ap.freq_base,
        ap.freq_scale,
        ap.ext_factor,
        ap.attn_factor,
        ap.beta_fast,
        ap.beta_slow,
    );
    let k_pe = ctx.rope_ext(
        k_pe,
        inp.pos,
        None,
        ap.n_rot as i32,
        ap.rope_mode,
        ap.n_ctx_orig,
        ap.freq_base,
        ap.freq_scale,
        ap.ext_factor,
        ap.attn_factor,
        ap.beta_fast,
        ap.beta_slow,
    );

    let q_nope = ctx.permute(q_nope, 0, 2, 1, 3);
    let q_nope_absorbed = ctx.mul_mat(lw.wk_b, q_nope);
    let q_nope_absorbed = ctx.permute(q_nope_absorbed, 0, 2, 1, 3);
    let qcur = ctx.concat(q_nope_absorbed, q_pe, 0);
    let kv_cmpr3 = ctx.reshape_3d(kv_cmpr, kv_lora_rank, 1, t);
    let kcur = ctx.concat(kv_cmpr3, k_pe, 0);

    // build_attn(inp_attn_k, wo, ..., v_mla = wv_b) (:701-704)
    let cur = attn_k_cached_mla(
        ctx,
        &mut graph,
        kv,
        0,
        ap,
        inp,
        n_kv,
        qcur,
        kcur,
        kv_cmpr3,
        kq_scale,
        lw.wv_b,
        Some(lw.wo),
        None,
    );

    // MoE FFN with shared expert (glm-dsa.cpp:707-742)
    let ffn_inp = ctx.add(cur, inp_sa);
    let cur = build_norm_rms(ctx, ffn_inp, lw.ffn_norm, ap.norm_eps);

    let moe_out = build_moe_ffn_deepseek2_like(
        ctx,
        &mut graph,
        cur,
        lw.ffn_gate_inp.expect("ffn_gate_inp"),
        lw.ffn_exp_probs_b,
        lw.ffn_gate_exps,
        lw.ffn_up_exps,
        lw.ffn_down_exps.expect("ffn_down_exps"),
        p.n_expert,
        p.n_expert_used,
        p.expert_weights_norm,
        p.expert_weights_scale,
        p.expert_gating_func,
    );
    let ffn_shexp = build_ffn_silu_par(
        ctx,
        cur,
        lw.ffn_gate_shexp.expect("ffn_gate_shexp"),
        None,
        lw.ffn_up_shexp.expect("ffn_up_shexp"),
        None,
        lw.ffn_down_shexp.expect("ffn_down_shexp"),
        None,
    );
    let cur = ctx.add(moe_out, ffn_shexp);
    let cur = ctx.add(cur, ffn_inp);

    // shared_head_norm applied after the decoder block (glm-dsa.cpp:747-753)
    // — nextn.shared_head_norm when the file carries it, else output_norm
    let head_norm_w = w.nextn.shared_head_norm.unwrap_or(w.output_norm);
    let h_nextn = build_norm_rms(ctx, cur, head_norm_w, ap.norm_eps);
    let head_w = w.nextn.shared_head_head.unwrap_or(w.output);

    // get_rows(out_ids) then the shared LM head (:758-764 — build_lora_mm)
    let h_nextn_out = graph::out_rows(ctx, h_nextn, inp.out_ids);
    let logits = crate::adapter::lora_mm(ctx, head_w, h_nextn_out);

    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(h_nextn),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use ggml::compute::graph_compute;

    /// Seeded LCG weight generator (same style as context.rs toy tests).
    struct Rng(u32);
    impl Rng {
        fn next(&mut self) -> f32 {
            self.0 = self.0.wrapping_mul(1103515245).wrapping_add(12345);
            ((self.0 >> 8) as f32 / 16777216.0) * 0.2 - 0.1
        }
    }

    /// Mini decode driver mirroring DecodeContext::decode but generic over
    /// the builder fn, so each arch struct can drive its own forward graph
    /// with kv-cache reuse across steps.
    struct Harness {
        gctx: Context,
        kv: KvCache,
        watermark: usize,
        /// GGML_OP_FLASH_ATTN_EXT nodes in the graph built by the last `decode`
        /// (FA-wiring assertion; always 0 on the non-FA path)
        last_fa_nodes: usize,
    }

    impl Harness {
        fn new(gctx: Context, kv: KvCache, watermark: usize) -> Self {
            Harness {
                gctx,
                kv,
                watermark,
                last_fa_nodes: 0,
            }
        }

        /// Decode `tokens`; returns last-token logits [n_vocab].
        fn decode<W>(
            &mut self,
            w: &W,
            attn: &AttnParams,
            tokens: &[i32],
            pos: &[i32],
            build: impl FnOnce(
                &mut Context,
                &W,
                &AttnParams,
                &KvCache,
                &DecodeInputs,
                SlotInfo,
                u32,
                usize,
            ) -> ForwardResult,
        ) -> Vec<f32> {
            let n = tokens.len();
            let sinfo = self.kv.find_slot(n as u32).expect("kv full");
            // apply_ubatch first, then the (256-padded) get_n_kv — the same
            // order as DecodeContext::step_inputs, so the mask lanes line up
            // with the cache rows this batch wrote
            self.kv.assign(sinfo, pos, 0);
            let n_kv = self.kv.n_kv();

            self.gctx.reset_graph_to(self.watermark);
            let tokens_t = self.gctx.new_tensor_1d(GgmlType::I32, n as i64);
            let pos_t = self.gctx.new_tensor_1d(GgmlType::I32, n as i64);
            // FA requires an F16 mask (llama-graph.cpp:38-39), same rule as
            // DecodeContext::decode
            let mask_ty = if attn.use_flash_attn {
                GgmlType::F16
            } else {
                GgmlType::F32
            };
            let kq_mask = self.gctx.new_tensor_2d(mask_ty, n_kv as i64, n as i64);
            let row_idx = self.gctx.new_tensor_1d(GgmlType::I64, n as i64);
            for tid in [tokens_t, pos_t, kq_mask, row_idx] {
                self.gctx.arena_resize_tensor(tid);
            }
            self.gctx
                .with_i32_mut(tokens_t, |p| p.copy_from_slice(tokens))
                .unwrap();
            self.gctx
                .with_i32_mut(pos_t, |p| p.copy_from_slice(pos))
                .unwrap();
            {
                let idxs: Vec<i64> = (sinfo.s0 as i64..=sinfo.s1 as i64).collect();
                self.gctx
                    .data_bytes_mut(row_idx)
                    .unwrap()
                    .copy_from_slice(bytemuck::cast_slice(&idxs));
            }
            {
                // causal mask over cache slots (append-only invariant: slot i
                // holds position i). Tensor is [n_kv, n_tokens], element
                // (kv s, query t) at s + t*n_kv — same as DecodeContext::decode
                // (graph::fill_causal_mask / _f16). Padded (empty) cells carry
                // pos = -1 → masked -inf.
                let kv_pos: Vec<i32> = self.kv.cells[..n_kv as usize]
                    .iter()
                    .map(|c| c.pos)
                    .collect();
                let mask_bytes = self.gctx.data_bytes_mut(kq_mask).unwrap();
                if mask_ty == GgmlType::F16 {
                    let mask: &mut [half::f16] = bytemuck::cast_slice_mut(mask_bytes);
                    crate::graph::fill_causal_mask_f16(mask, &kv_pos, pos);
                } else {
                    let mask: &mut [f32] = bytemuck::cast_slice_mut(mask_bytes);
                    crate::graph::fill_causal_mask(mask, &kv_pos, pos);
                }
            }
            let inputs = DecodeInputs {
                tokens: tokens_t,
                pos: pos_t,
                kq_mask,
                row_idx,
                out_ids: None,
            };

            let result = build(&mut self.gctx, w, attn, &self.kv, &inputs, sinfo, n_kv, n);
            let logits = result.logits;
            let mut gf = result.graph;
            self.last_fa_nodes = gf
                .nodes
                .iter()
                .filter(|&&id| self.gctx.op(id) == ggml::tensor::GgmlOp::FlashAttnExt)
                .count();
            graph_compute(&mut self.gctx, &mut gf, 1);
            // (assign already happened before the graph build, step_inputs order)

            let ne = self.gctx.ne(logits);
            let n_vocab = ne[0] as usize;
            let all: Vec<f32> = self
                .gctx
                .data_bytes(logits)
                .unwrap()
                .chunks_exact(4)
                .map(|c| f32::from_le_bytes(c.try_into().unwrap()))
                .collect();
            all[n_vocab * (n - 1)..n_vocab * n].to_vec()
        }
    }

    fn f32s(g: &Context, id: TensorId) -> Vec<f32> {
        g.data_bytes(id)
            .unwrap()
            .chunks_exact(4)
            .map(|c| f32::from_le_bytes(c.try_into().unwrap()))
            .collect()
    }

    fn mk2(g: &mut Context, rng: &mut Rng, n0: i64, n1: i64) -> TensorId {
        let id = g.new_tensor_2d(GgmlType::F32, n0, n1);
        g.arena_resize_tensor(id);
        g.with_f32_mut(id, |p| {
            for v in p.iter_mut() {
                *v = rng.next();
            }
        })
        .unwrap();
        id
    }

    fn mkv(g: &mut Context, rng: &mut Rng, n0: i64) -> TensorId {
        mk2(g, rng, n0, 1)
    }

    // ---------------- naive reference helpers ----------------

    /// w is [n0, n1] col-major ggml layout: element (i,j) at i + j*n0.
    fn dot(w: &[f32], x: &[f32], n0: usize) -> Vec<f32> {
        let n1 = w.len() / n0.max(1);
        (0..n1)
            .map(|j| (0..n0).map(|i| w[i + j * n0] * x[i]).sum())
            .collect()
    }

    fn rms(x: &[f32], w: &[f32], eps: f32, one_plus_w: bool) -> Vec<f32> {
        let sum: f32 = x.iter().map(|v| v * v).sum();
        let sc = 1.0 / (sum / x.len() as f32 + eps).sqrt();
        x.iter()
            .zip(w.iter())
            .map(|(v, wv)| v * sc * if one_plus_w { 1.0 + wv } else { *wv })
            .collect()
    }

    /// NEOX rope with optional partial rotation (n_rot <= hd): pairs
    /// (j, j + n_rot/2) for j in 0..n_rot/2; channels >= n_rot pass through.
    fn rope_neox(v: &mut [f32], pos: i32, n_heads: usize, hd: usize, n_rot: usize, base: f32) {
        for h in 0..n_heads {
            let b = h * hd;
            for j in 0..n_rot / 2 {
                let f = 1.0f32 / base.powf(2.0 * j as f32 / n_rot as f32);
                let theta = pos as f32 * f;
                let (c, s) = (theta.cos(), theta.sin());
                let x0 = v[b + j];
                let x1 = v[b + j + n_rot / 2];
                v[b + j] = x0 * c - x1 * s;
                v[b + j + n_rot / 2] = x0 * s + x1 * c;
            }
        }
    }

    /// Round-trip through f16 like the KV cache stores k/v — the naive
    /// reference must model the cache quantization or near-zero logits show
    /// ~2e-4 absolute diffs (denominator-clamped rel err blows up).
    fn f16rt(v: &mut Vec<f32>) {
        for x in v.iter_mut() {
            *x = half::f16::from_f32(*x).to_f32();
        }
    }

    /// scalar f32→f16→f32 round-trip (the mul_mat kernel quantizes the f32
    /// src1 row to the F16 cache's vec_dot type — compute.rs:454-458)
    fn f16q(x: f32) -> f32 {
        half::f16::from_f32(x).to_f32()
    }

    #[allow(clippy::too_many_arguments)]
    fn softmax_attn(
        qs: &[Vec<f32>],
        ks: &[Vec<f32>],
        vs: &[Vec<f32>],
        t: usize,
        n_head: usize,
        n_head_kv: usize,
        hd: usize,
        q_pre_scale: f32,
        softmax_scale: f32,
        // attn logit softcap (llama-graph.cpp:2691-2698): None for
        // llama/qwen2/phi3/gemma3, Some(cap) for gemma2.
        attn_softcap: Option<f32>,
    ) -> Vec<f32> {
        let mut acc = vec![0f32; hd * n_head];
        for h in 0..n_head {
            let kvh = h / (n_head / n_head_kv);
            // kq: f16(k) · f16(q * pre_scale) (kernel rounds the f32 q row)
            let mut sw = Vec::new();
            for s in 0..=t {
                let mut d = 0f32;
                for i in 0..hd {
                    d += ks[s][kvh * hd + i] * f16q(qs[t][h * hd + i] * q_pre_scale);
                }
                // softcap: scale(1/cap) → tanh → scale(cap), same order as C
                if let Some(cap) = attn_softcap {
                    d = (d * (1.0 / cap)).tanh() * cap;
                }
                sw.push(ggml::ops::ggml_expf(d * softmax_scale));
            }
            let sum: f32 = sw.iter().sum();
            // kqv: f16(v) · f16(weight) — softmax weights are the f32 src1
            // row of the second mul_mat and get rounded too
            for i in 0..hd {
                let mut o = 0f32;
                for (s, w) in sw.iter().enumerate() {
                    o += f16q(w / sum) * vs[s][kvh * hd + i];
                }
                acc[h * hd + i] = o;
            }
        }
        acc
    }

    fn rel_err(got: &[f32], want: &[f32]) -> f32 {
        got.iter()
            .zip(want)
            .map(|(a, b)| (a - b).abs() / b.abs().max(1e-3))
            .fold(0f32, f32::max)
    }

    fn argmax(v: &[f32]) -> i32 {
        v.iter()
            .enumerate()
            .max_by(|a, b| a.1.total_cmp(b.1))
            .unwrap()
            .0 as i32
    }

    fn base_attn(freq_base: f32, n_rot: i64) -> AttnParams {
        AttnParams {
            n_head: 4,
            n_head_kv: 2,
            n_embd_head_k: 16,
            n_embd_head_v: 16,
            n_rot,
            rope_mode: 2, // NEOX
            n_ctx_orig: 512,
            freq_base,
            freq_scale: 1.0,
            ext_factor: 0.0,
            attn_factor: 1.0,
            beta_fast: 32.0,
            beta_slow: 1.0,
            norm_eps: 1e-6,
            use_flash_attn: false,
        }
    }

    /// FA wiring smoke across all four builders: each toy model is built twice
    /// with the same RNG seed (identical weights) and decoded with
    /// `use_flash_attn` off / on. Asserts
    ///   * the FA branch emits exactly one GGML_OP_FLASH_ATTN_EXT per layer
    ///     (0 on the non-FA path — guards against a silent no-op wiring),
    ///   * FA logits stay finite and agree with the non-FA graph (the only
    ///     difference is the f16-Q quantisation of the non-FA mul_mat; the
    ///     qwen2 toy FA test in context.rs measured 5.0e-6 for that).
    #[test]
    fn toy_flash_attn_smoke_all_archs() {
        let (n_embd, n_head, n_head_kv, nd) = (32i64, 4i64, 2i64, 8i64);
        let (n_ff, n_vocab, n_layer) = (48i64, 64i64, 1usize);
        let mk_attn = |use_flash_attn: bool, freq_base: f32| AttnParams {
            n_head,
            n_head_kv,
            n_embd_head_k: nd,
            n_embd_head_v: nd,
            n_rot: nd,
            rope_mode: 2,
            n_ctx_orig: 512,
            freq_base,
            freq_scale: 1.0,
            ext_factor: 0.0,
            attn_factor: 1.0,
            beta_fast: 32.0,
            beta_slow: 1.0,
            norm_eps: 1e-6,
            use_flash_attn,
        };
        let maxabs = |a: &[f32], b: &[f32]| {
            a.iter()
                .zip(b)
                .map(|(x, y)| (x - y).abs())
                .fold(0f32, f32::max)
        };
        let check = |name: &str, off: (Vec<f32>, usize), on: (Vec<f32>, usize)| {
            let (lg_off, fa_off) = off;
            let (lg_on, fa_on) = on;
            assert_eq!(
                fa_off, 0,
                "{name}: non-FA graph must have no FlashAttnExt node"
            );
            assert_eq!(
                fa_on, n_layer,
                "{name}: FA graph must have one FlashAttnExt node per layer"
            );
            assert!(
                lg_on.iter().all(|v| v.is_finite()),
                "{name}: FA logits not finite"
            );
            let e = maxabs(&lg_on, &lg_off);
            println!("{name} FA vs non-FA: max abs {e:.3e}");
            assert!(e < 1e-3, "{name}: FA vs non-FA diverged: {e:.3e}");
        };
        let toks = [3i32, 7];
        let pos = [0i32, 1];

        // ---------------- llama ----------------
        let run_llama = |use_fa: bool| -> (Vec<f32>, usize) {
            let mut gctx = Context::new();
            let mut rng = Rng(77);
            let tok_embd = mk2(&mut gctx, &mut rng, n_embd, n_vocab);
            let output = mk2(&mut gctx, &mut rng, n_embd, n_vocab);
            let output_norm = mkv(&mut gctx, &mut rng, n_embd);
            let n_gqa = nd * n_head_kv;
            let layers: Vec<LlamaLayerWeights> = (0..n_layer)
                .map(|_| LlamaLayerWeights {
                    attn_norm: mkv(&mut gctx, &mut rng, n_embd),
                    wq: mk2(&mut gctx, &mut rng, n_embd, n_embd),
                    wk: mk2(&mut gctx, &mut rng, n_embd, n_gqa),
                    wv: mk2(&mut gctx, &mut rng, n_embd, n_gqa),
                    wo: mk2(&mut gctx, &mut rng, n_embd, n_embd),
                    wq_b: None,
                    wk_b: None,
                    wv_b: None,
                    wo_b: None,
                    ffn_norm: mkv(&mut gctx, &mut rng, n_embd),
                    ffn_gate: mk2(&mut gctx, &mut rng, n_embd, n_ff),
                    ffn_down: mk2(&mut gctx, &mut rng, n_ff, n_embd),
                    ffn_up: mk2(&mut gctx, &mut rng, n_embd, n_ff),
                    ffn_gate_b: None,
                    ffn_down_b: None,
                    ffn_up_b: None,
                })
                .collect();
            let weights = LlamaModelWeights {
                tok_embd,
                output_norm,
                output,
                output_b: None,
                layers,
            };
            let attn = mk_attn(use_fa, 10000.0);
            let kv = KvCache::new(&mut gctx, n_layer, n_gqa, n_gqa, 32);
            let watermark = gctx.mark();
            let mut h = Harness::new(gctx, kv, watermark);
            let lg = h.decode(&weights, &attn, &toks, &pos, build_llama_forward);
            (lg, h.last_fa_nodes)
        };
        check("llama", run_llama(false), run_llama(true));

        // ------- gemma2 (attn_soft_cap → FA logit_softcap) / gemma3 ---------
        let run_gemma = |gemma3: bool, use_fa: bool| -> (Vec<f32>, usize) {
            let mut gctx = Context::new();
            let mut rng = Rng(if gemma3 { 80 } else { 78 });
            let tok_embd = mk2(&mut gctx, &mut rng, n_embd, n_vocab);
            let output_norm = mkv(&mut gctx, &mut rng, n_embd);
            let n_gqa = nd * n_head_kv;
            let layers: Vec<GemmaLayerWeights> = (0..n_layer)
                .map(|_| GemmaLayerWeights {
                    attn_norm: mkv(&mut gctx, &mut rng, n_embd),
                    wq: mk2(&mut gctx, &mut rng, n_embd, n_embd),
                    wk: mk2(&mut gctx, &mut rng, n_embd, n_gqa),
                    wv: mk2(&mut gctx, &mut rng, n_embd, n_gqa),
                    wo: mk2(&mut gctx, &mut rng, n_embd, n_embd),
                    attn_post_norm: mkv(&mut gctx, &mut rng, n_embd),
                    ffn_norm: mkv(&mut gctx, &mut rng, n_embd),
                    ffn_gate: mk2(&mut gctx, &mut rng, n_embd, n_ff),
                    ffn_down: mk2(&mut gctx, &mut rng, n_ff, n_embd),
                    ffn_up: mk2(&mut gctx, &mut rng, n_embd, n_ff),
                    ffn_post_norm: mkv(&mut gctx, &mut rng, n_embd),
                    // gemma3 only (gemma3.cpp:131/139, before rope)
                    attn_q_norm: if gemma3 {
                        Some(mkv(&mut gctx, &mut rng, nd))
                    } else {
                        None
                    },
                    attn_k_norm: if gemma3 {
                        Some(mkv(&mut gctx, &mut rng, nd))
                    } else {
                        None
                    },
                })
                .collect();
            let weights = GemmaModelWeights {
                tok_embd,
                output_norm,
                output: tok_embd,
                layers,
            };
            let attn = mk_attn(use_fa, if gemma3 { 1000000.0 } else { 10000.0 });
            let gp = GemmaParams {
                attn,
                attention_scale: 1.0 / (nd as f32).sqrt(),
                attn_logit_softcapping: 50.0,
                final_logit_softcapping: 30.0,
                attn_soft_cap: !gemma3, // gemma2.cpp:7 (FA logit_softcap)
                final_softcap_unguarded: !gemma3, // gemma2.cpp:167-169
            };
            let kv = KvCache::new(&mut gctx, n_layer, n_gqa, n_gqa, 32);
            let watermark = gctx.mark();
            let mut h = Harness::new(gctx, kv, watermark);
            let build = |ctx: &mut Context,
                         w: &GemmaModelWeights,
                         ap: &AttnParams,
                         kv: &KvCache,
                         inp: &DecodeInputs,
                         s: SlotInfo,
                         nk: u32,
                         nt: usize| {
                let gp = GemmaParams { attn: *ap, ..gp };
                if gemma3 {
                    build_gemma3_forward(ctx, w, &gp, kv, inp, s, nk, nt)
                } else {
                    build_gemma2_forward(ctx, w, &gp, kv, inp, s, nk, nt)
                }
            };
            let lg = h.decode(&weights, &attn, &toks, &pos, build);
            (lg, h.last_fa_nodes)
        };
        check("gemma2", run_gemma(false, false), run_gemma(false, true));
        check("gemma3", run_gemma(true, false), run_gemma(true, true));

        // ---------------- phi3 ----------------
        let run_phi3 = |use_fa: bool| -> (Vec<f32>, usize) {
            let mut gctx = Context::new();
            let mut rng = Rng(79);
            let tok_embd = mk2(&mut gctx, &mut rng, n_embd, n_vocab);
            let output = mk2(&mut gctx, &mut rng, n_embd, n_vocab);
            let output_norm = mkv(&mut gctx, &mut rng, n_embd);
            let n_gqa = nd * n_head_kv;
            let layers: Vec<Phi3LayerWeights> = (0..n_layer)
                .map(|_| Phi3LayerWeights {
                    attn_norm: mkv(&mut gctx, &mut rng, n_embd),
                    wqkv: mk2(&mut gctx, &mut rng, n_embd, nd * n_head + 2 * n_gqa),
                    wqkv_b: None,
                    wo: mk2(&mut gctx, &mut rng, n_embd, n_embd),
                    wo_b: None,
                    ffn_norm: mkv(&mut gctx, &mut rng, n_embd),
                    ffn_down: mk2(&mut gctx, &mut rng, n_ff, n_embd),
                    ffn_up: mk2(&mut gctx, &mut rng, n_embd, 2 * n_ff),
                })
                .collect();
            let weights = Phi3ModelWeights {
                tok_embd,
                output_norm,
                output,
                output_b: None,
                layers,
            };
            let attn = mk_attn(use_fa, 10000.0);
            let kv = KvCache::new(&mut gctx, n_layer, n_gqa, n_gqa, 32);
            let watermark = gctx.mark();
            let mut h = Harness::new(gctx, kv, watermark);
            let lg = h.decode(&weights, &attn, &toks, &pos, build_phi3_forward);
            (lg, h.last_fa_nodes)
        };
        check("phi3", run_phi3(false), run_phi3(true));

        // ---------------- qwen3 (per-head q/k norms before rope) -------------
        let run_qwen3 = |use_fa: bool| -> (Vec<f32>, usize) {
            let mut gctx = Context::new();
            let mut rng = Rng(81);
            let tok_embd = mk2(&mut gctx, &mut rng, n_embd, n_vocab);
            let output_norm = mkv(&mut gctx, &mut rng, n_embd);
            let n_gqa = nd * n_head_kv;
            let layers: Vec<Qwen3LayerWeights> = (0..n_layer)
                .map(|_| Qwen3LayerWeights {
                    attn_norm: mkv(&mut gctx, &mut rng, n_embd),
                    wq: mk2(&mut gctx, &mut rng, n_embd, nd * n_head),
                    wk: mk2(&mut gctx, &mut rng, n_embd, n_gqa),
                    wv: mk2(&mut gctx, &mut rng, n_embd, n_gqa),
                    wq_b: None,
                    wk_b: None,
                    wv_b: None,
                    wo: mk2(&mut gctx, &mut rng, nd * n_head, n_embd),
                    attn_q_norm: mkv(&mut gctx, &mut rng, nd),
                    attn_k_norm: mkv(&mut gctx, &mut rng, nd),
                    ffn_norm: mkv(&mut gctx, &mut rng, n_embd),
                    ffn_gate: mk2(&mut gctx, &mut rng, n_embd, n_ff),
                    ffn_down: mk2(&mut gctx, &mut rng, n_ff, n_embd),
                    ffn_up: mk2(&mut gctx, &mut rng, n_embd, n_ff),
                })
                .collect();
            // tied lm head, like Qwen3-Embedding (qwen3.cpp:24-26)
            let weights = Qwen3ModelWeights {
                tok_embd,
                output_norm,
                output: tok_embd,
                layers,
            };
            let attn = mk_attn(use_fa, 1000000.0);
            let kv = KvCache::new(&mut gctx, n_layer, n_gqa, n_gqa, 32);
            let watermark = gctx.mark();
            let mut h = Harness::new(gctx, kv, watermark);
            let lg = h.decode(&weights, &attn, &toks, &pos, build_qwen3_forward);
            (lg, h.last_fa_nodes)
        };
        check("qwen3", run_qwen3(false), run_qwen3(true));
    }

    // ================================================================
    // llama
    // ================================================================

    #[test]
    fn toy_llama_matches_naive() {
        let n_embd = 64usize;
        let (n_head, n_head_kv, nd) = (4usize, 2usize, 16usize);
        let n_ff = 96usize;
        let n_vocab = 100usize;
        let n_layer = 2usize;
        let eps = 1e-6f32;
        let freq_base = 1000000.0f32;

        let mut gctx = Context::new();
        let mut rng = Rng(2024);
        let tok_embd = mk2(&mut gctx, &mut rng, n_embd as i64, n_vocab as i64);
        let output = mk2(&mut gctx, &mut rng, n_embd as i64, n_vocab as i64);
        let output_norm = mkv(&mut gctx, &mut rng, n_embd as i64);
        let output_b = mkv(&mut gctx, &mut rng, n_vocab as i64);
        struct LW {
            attn_norm: TensorId,
            wq: TensorId,
            wk: TensorId,
            wv: TensorId,
            wo: TensorId,
            ffn_norm: TensorId,
            ffn_gate: TensorId,
            ffn_down: TensorId,
            ffn_up: TensorId,
        }
        let lws: Vec<LW> = (0..n_layer)
            .map(|_| LW {
                attn_norm: mkv(&mut gctx, &mut rng, n_embd as i64),
                wq: mk2(&mut gctx, &mut rng, n_embd as i64, n_embd as i64),
                wk: mk2(&mut gctx, &mut rng, n_embd as i64, (nd * n_head_kv) as i64),
                wv: mk2(&mut gctx, &mut rng, n_embd as i64, (nd * n_head_kv) as i64),
                wo: mk2(&mut gctx, &mut rng, n_embd as i64, n_embd as i64),
                ffn_norm: mkv(&mut gctx, &mut rng, n_embd as i64),
                ffn_gate: mk2(&mut gctx, &mut rng, n_embd as i64, n_ff as i64),
                ffn_down: mk2(&mut gctx, &mut rng, n_ff as i64, n_embd as i64),
                ffn_up: mk2(&mut gctx, &mut rng, n_embd as i64, n_ff as i64),
            })
            .collect();
        // snapshot weights before any graph building mutates the arena
        let embd_table = f32s(&gctx, tok_embd);
        let out_w = f32s(&gctx, output);
        let out_norm_v = f32s(&gctx, output_norm);
        let out_bias = f32s(&gctx, output_b);
        let lws_data: Vec<(
            Vec<f32>,
            Vec<f32>,
            Vec<f32>,
            Vec<f32>,
            Vec<f32>,
            Vec<f32>,
            Vec<f32>,
            Vec<f32>,
            Vec<f32>,
        )> = lws
            .iter()
            .map(|l| {
                (
                    f32s(&gctx, l.attn_norm),
                    f32s(&gctx, l.wq),
                    f32s(&gctx, l.wk),
                    f32s(&gctx, l.wv),
                    f32s(&gctx, l.wo),
                    f32s(&gctx, l.ffn_norm),
                    f32s(&gctx, l.ffn_gate),
                    f32s(&gctx, l.ffn_down),
                    f32s(&gctx, l.ffn_up),
                )
            })
            .collect();

        let weights = LlamaModelWeights {
            tok_embd,
            output_norm,
            output,
            output_b: Some(output_b),
            layers: lws
                .iter()
                .map(|l| LlamaLayerWeights {
                    attn_norm: l.attn_norm,
                    wq: l.wq,
                    wk: l.wk,
                    wv: l.wv,
                    wo: l.wo,
                    wq_b: None,
                    wk_b: None,
                    wv_b: None,
                    wo_b: None,
                    ffn_norm: l.ffn_norm,
                    ffn_gate: l.ffn_gate,
                    ffn_down: l.ffn_down,
                    ffn_up: l.ffn_up,
                    ffn_gate_b: None,
                    ffn_down_b: None,
                    ffn_up_b: None,
                })
                .collect(),
        };
        let attn = base_attn(freq_base, nd as i64);
        let mut gctx2 = gctx; // move into harness
        let kv = KvCache::new(
            &mut gctx2,
            n_layer,
            (nd * n_head_kv) as i64,
            (nd * n_head_kv) as i64,
            64,
        );
        let watermark = gctx2.mark();
        let mut h = Harness::new(gctx2, kv, watermark);

        // naive: full forward over tokens, last-token logits
        let naive = |toks: &[i32]| -> Vec<f32> {
            let mut x: Vec<Vec<f32>> = toks
                .iter()
                .map(|&t| embd_table[t as usize * n_embd..][..n_embd].to_vec())
                .collect();
            let scale = 1.0f32 / (nd as f32).sqrt();
            for li in 0..n_layer {
                let (an, wqv, wkv, wvv, wov, fnv, gv, dv, uv) = {
                    let r = &lws_data[li];
                    (&r.0, &r.1, &r.2, &r.3, &r.4, &r.5, &r.6, &r.7, &r.8)
                };
                let mut qs = Vec::new();
                let mut ks = Vec::new();
                let mut vs = Vec::new();
                for (t, xt) in x.iter().enumerate() {
                    let xn = rms(xt, an, eps, false);
                    let mut q = dot(wqv, &xn, n_embd);
                    let mut k = dot(wkv, &xn, n_embd);
                    let mut v = dot(wvv, &xn, n_embd);
                    rope_neox(&mut q, t as i32, n_head, nd, nd, freq_base);
                    rope_neox(&mut k, t as i32, n_head_kv, nd, nd, freq_base);
                    f16rt(&mut k);
                    f16rt(&mut v);
                    qs.push(q);
                    ks.push(k);
                    vs.push(v);
                }
                let mut outs = Vec::new();
                for (t, xt) in x.iter().enumerate() {
                    let acc =
                        softmax_attn(&qs, &ks, &vs, t, n_head, n_head_kv, nd, 1.0, scale, None);
                    let a = dot(wov, &acc, n_embd);
                    let res: Vec<f32> = xt.iter().zip(&a).map(|(p, q)| p + q).collect();
                    let xn = rms(&res, fnv, eps, false);
                    let g = dot(gv, &xn, n_embd);
                    let u = dot(uv, &xn, n_embd);
                    let mut prod = vec![0f32; n_ff];
                    for i in 0..n_ff {
                        prod[i] = ggml::ops::ggml_silu_f32(g[i]) * u[i];
                    }
                    let d = dot(dv, &prod, n_ff);
                    outs.push(d.iter().zip(&res).map(|(p, q)| p + q).collect());
                }
                x = outs;
            }
            let last = x.last().unwrap();
            let xn = rms(last, &out_norm_v, eps, false);
            let mut logits = dot(&out_w, &xn, n_embd);
            for (l, b) in logits.iter_mut().zip(&out_bias) {
                *l += b;
            }
            logits
        };

        let mut all: Vec<i32> = vec![5, 9, 42];
        let got = h.decode(&weights, &attn, &all, &[0, 1, 2], build_llama_forward);
        let err = rel_err(&got, &naive(&all));
        assert!(err < 2e-2, "llama prefill mismatch: {err:.4}");
        println!("llama prefill rel err {err:.5}");

        for p in 3..6 {
            let tok = argmax(&got);
            all.push(tok);
            let got2 = h.decode(&weights, &attn, &[tok], &[p], build_llama_forward);
            let want = naive(&all);
            // decode convention verbatim from toy_qwen2: max(|b|,1.0) denominator, 5e-2
            let err = got2
                .iter()
                .zip(&want)
                .map(|(a, b)| (a - b).abs() / b.abs().max(1.0))
                .fold(0f32, f32::max);
            assert!(err < 5e-2, "llama decode pos {p} mismatch: {err:.4}");
            println!("llama decode pos={p} rel err {err:.5}");
        }
    }

    // ================================================================
    // qwen3 (per-head q/k norms before rope, tied lm head)
    // ================================================================

    /// qwen3 vs naive. Structurally it is the llama graph plus the per-head
    /// RMS norm on Q/K *before* rope (qwen3.cpp:88/97); the naive applies
    /// `rms` per head with the [n_embd_head_k] weight, which is what the
    /// graph's broadcast over [n_embd_head, heads, T] evaluates
    /// (build_norm llama-graph.cpp:1604). Normalizing after rope instead is
    /// not equivalent, so a swap fails this test. The lm head is tied to
    /// tok_embd like the Qwen3-Embedding file (qwen3.cpp:24-26).
    #[test]
    fn toy_qwen3_matches_naive() {
        let n_embd = 64usize;
        let (n_head, n_head_kv, nd) = (4usize, 2usize, 16usize);
        let n_ff = 96usize;
        let n_vocab = 100usize;
        let n_layer = 2usize;
        let eps = 1e-6f32;
        let freq_base = 1000000.0f32;

        let mut gctx = Context::new();
        let mut rng = Rng(2025);
        let tok_embd = mk2(&mut gctx, &mut rng, n_embd as i64, n_vocab as i64);
        let output_norm = mkv(&mut gctx, &mut rng, n_embd as i64);
        struct LW {
            attn_norm: TensorId,
            wq: TensorId,
            wk: TensorId,
            wv: TensorId,
            wo: TensorId,
            q_norm: TensorId,
            k_norm: TensorId,
            ffn_norm: TensorId,
            ffn_gate: TensorId,
            ffn_down: TensorId,
            ffn_up: TensorId,
        }
        let lws: Vec<LW> = (0..n_layer)
            .map(|_| LW {
                attn_norm: mkv(&mut gctx, &mut rng, n_embd as i64),
                wq: mk2(&mut gctx, &mut rng, n_embd as i64, (nd * n_head) as i64),
                wk: mk2(&mut gctx, &mut rng, n_embd as i64, (nd * n_head_kv) as i64),
                wv: mk2(&mut gctx, &mut rng, n_embd as i64, (nd * n_head_kv) as i64),
                wo: mk2(&mut gctx, &mut rng, (nd * n_head) as i64, n_embd as i64),
                q_norm: mkv(&mut gctx, &mut rng, nd as i64),
                k_norm: mkv(&mut gctx, &mut rng, nd as i64),
                ffn_norm: mkv(&mut gctx, &mut rng, n_embd as i64),
                ffn_gate: mk2(&mut gctx, &mut rng, n_embd as i64, n_ff as i64),
                ffn_down: mk2(&mut gctx, &mut rng, n_ff as i64, n_embd as i64),
                ffn_up: mk2(&mut gctx, &mut rng, n_embd as i64, n_ff as i64),
            })
            .collect();
        let embd_table = f32s(&gctx, tok_embd);
        let out_w = embd_table.clone(); // tied
        let out_norm_v = f32s(&gctx, output_norm);
        #[allow(clippy::type_complexity)]
        let lws_data: Vec<(
            Vec<f32>,
            Vec<f32>,
            Vec<f32>,
            Vec<f32>,
            Vec<f32>,
            Vec<f32>,
            Vec<f32>,
            Vec<f32>,
            Vec<f32>,
            Vec<f32>,
            Vec<f32>,
        )> = lws
            .iter()
            .map(|l| {
                (
                    f32s(&gctx, l.attn_norm),
                    f32s(&gctx, l.wq),
                    f32s(&gctx, l.wk),
                    f32s(&gctx, l.wv),
                    f32s(&gctx, l.wo),
                    f32s(&gctx, l.q_norm),
                    f32s(&gctx, l.k_norm),
                    f32s(&gctx, l.ffn_norm),
                    f32s(&gctx, l.ffn_gate),
                    f32s(&gctx, l.ffn_down),
                    f32s(&gctx, l.ffn_up),
                )
            })
            .collect();

        let weights = Qwen3ModelWeights {
            tok_embd,
            output_norm,
            output: tok_embd,
            layers: lws
                .iter()
                .map(|l| Qwen3LayerWeights {
                    attn_norm: l.attn_norm,
                    wq: l.wq,
                    wk: l.wk,
                    wv: l.wv,
                    wq_b: None,
                    wk_b: None,
                    wv_b: None,
                    wo: l.wo,
                    attn_q_norm: l.q_norm,
                    attn_k_norm: l.k_norm,
                    ffn_norm: l.ffn_norm,
                    ffn_gate: l.ffn_gate,
                    ffn_down: l.ffn_down,
                    ffn_up: l.ffn_up,
                })
                .collect(),
        };
        let attn = base_attn(freq_base, nd as i64);
        let mut gctx2 = gctx;
        let kv = KvCache::new(
            &mut gctx2,
            n_layer,
            (nd * n_head_kv) as i64,
            (nd * n_head_kv) as i64,
            64,
        );
        let watermark = gctx2.mark();
        let mut h = Harness::new(gctx2, kv, watermark);

        let naive = |toks: &[i32]| -> Vec<f32> {
            let mut x: Vec<Vec<f32>> = toks
                .iter()
                .map(|&t| embd_table[t as usize * n_embd..][..n_embd].to_vec())
                .collect();
            let scale = 1.0f32 / (nd as f32).sqrt();
            for li in 0..n_layer {
                let (an, wqv, wkv, wvv, wov, qn, kn, fnv, gv, dv, uv) = {
                    let r = &lws_data[li];
                    (
                        &r.0, &r.1, &r.2, &r.3, &r.4, &r.5, &r.6, &r.7, &r.8, &r.9, &r.10,
                    )
                };
                let mut qs = Vec::new();
                let mut ks = Vec::new();
                let mut vs = Vec::new();
                for (t, xt) in x.iter().enumerate() {
                    let xn = rms(xt, an, eps, false);
                    let mut q = dot(wqv, &xn, n_embd);
                    let mut k = dot(wkv, &xn, n_embd);
                    let mut v = dot(wvv, &xn, n_embd);
                    // per-head norms BEFORE rope (qwen3.cpp:88/97)
                    for hh in 0..n_head {
                        let seg = rms(&q[hh * nd..(hh + 1) * nd], qn, eps, false);
                        q[hh * nd..(hh + 1) * nd].copy_from_slice(&seg);
                    }
                    for hh in 0..n_head_kv {
                        let seg = rms(&k[hh * nd..(hh + 1) * nd], kn, eps, false);
                        k[hh * nd..(hh + 1) * nd].copy_from_slice(&seg);
                    }
                    // n_rot == head_dim (qwen3.cpp:57)
                    rope_neox(&mut q, t as i32, n_head, nd, nd, freq_base);
                    rope_neox(&mut k, t as i32, n_head_kv, nd, nd, freq_base);
                    f16rt(&mut k);
                    f16rt(&mut v);
                    qs.push(q);
                    ks.push(k);
                    vs.push(v);
                }
                let mut outs = Vec::new();
                for (t, xt) in x.iter().enumerate() {
                    let acc =
                        softmax_attn(&qs, &ks, &vs, t, n_head, n_head_kv, nd, 1.0, scale, None);
                    let a = dot(wov, &acc, n_embd);
                    let res: Vec<f32> = xt.iter().zip(&a).map(|(p, q)| p + q).collect();
                    let xn = rms(&res, fnv, eps, false);
                    let g = dot(gv, &xn, n_embd);
                    let u = dot(uv, &xn, n_embd);
                    let mut prod = vec![0f32; n_ff];
                    for i in 0..n_ff {
                        prod[i] = ggml::ops::ggml_silu_f32(g[i]) * u[i];
                    }
                    let d = dot(dv, &prod, n_ff);
                    outs.push(d.iter().zip(&res).map(|(p, q)| p + q).collect());
                }
                x = outs;
            }
            let last = x.last().unwrap();
            let xn = rms(last, &out_norm_v, eps, false);
            dot(&out_w, &xn, n_embd)
        };

        let mut all: Vec<i32> = vec![5, 9, 42];
        let got = h.decode(&weights, &attn, &all, &[0, 1, 2], build_qwen3_forward);
        let err = rel_err(&got, &naive(&all));
        assert!(err < 2e-2, "qwen3 prefill mismatch: {err:.4}");
        println!("qwen3 prefill rel err {err:.5}");

        for p in 3..6 {
            let tok = argmax(&got);
            all.push(tok);
            let got2 = h.decode(&weights, &attn, &[tok], &[p], build_qwen3_forward);
            let want = naive(&all);
            let err = got2
                .iter()
                .zip(&want)
                .map(|(a, b)| (a - b).abs() / b.abs().max(1.0))
                .fold(0f32, f32::max);
            assert!(err < 5e-2, "qwen3 decode pos {p} mismatch: {err:.4}");
            println!("qwen3 decode pos={p} rel err {err:.5}");
        }
    }

    // ================================================================
    // gemma2 / gemma3 (shared naive with flags)
    // ================================================================

    struct GLW {
        attn_norm: TensorId,
        wq: TensorId,
        wk: TensorId,
        wv: TensorId,
        wo: TensorId,
        attn_post_norm: TensorId,
        ffn_norm: TensorId,
        ffn_gate: TensorId,
        ffn_down: TensorId,
        ffn_up: TensorId,
        ffn_post_norm: TensorId,
        attn_q_norm: Option<TensorId>,
        attn_k_norm: Option<TensorId>,
    }

    /// gemma2: q/k norms None. gemma3: q/k norms present + n_rot < head_dim
    /// to exercise partial rope rotation.
    fn run_gemma_toy(gemma3: bool) {
        let n_embd = 64usize;
        let (n_head, n_head_kv, nd) = (4usize, 2usize, 16usize);
        let n_rot = if gemma3 { 8 } else { nd };
        let n_ff = 96usize;
        let n_vocab = 100usize;
        let n_layer = 2usize;
        let eps = 1e-6f32;
        let freq_base = 1000000.0f32;
        let attention_scale = 1.0f32 / (nd as f32).sqrt();
        // real gemma2 hyperparameters (gemma2.cpp:7 attn_soft_cap = true; caps
        // 50/30 in every shipped gemma2 config). gemma3 never sets
        // attn_soft_cap and guards the final cap (gemma3.cpp:210). Exercising
        // non-zero caps on both arches is the point of this test.
        let (attn_cap, final_cap) = (50.0f32, 30.0f32);
        let gemma_attn_cap = if gemma3 { None } else { Some(attn_cap) };

        let mut gctx = Context::new();
        let mut rng = Rng(if gemma3 { 7777 } else { 4242 });
        let tok_embd = mk2(&mut gctx, &mut rng, n_embd as i64, n_vocab as i64);
        let output_norm = mkv(&mut gctx, &mut rng, n_embd as i64);
        let lws: Vec<GLW> = (0..n_layer)
            .map(|_| GLW {
                attn_norm: mkv(&mut gctx, &mut rng, n_embd as i64),
                wq: mk2(&mut gctx, &mut rng, n_embd as i64, n_embd as i64),
                wk: mk2(&mut gctx, &mut rng, n_embd as i64, (nd * n_head_kv) as i64),
                wv: mk2(&mut gctx, &mut rng, n_embd as i64, (nd * n_head_kv) as i64),
                wo: mk2(&mut gctx, &mut rng, n_embd as i64, n_embd as i64),
                attn_post_norm: mkv(&mut gctx, &mut rng, n_embd as i64),
                ffn_norm: mkv(&mut gctx, &mut rng, n_embd as i64),
                ffn_gate: mk2(&mut gctx, &mut rng, n_embd as i64, n_ff as i64),
                ffn_down: mk2(&mut gctx, &mut rng, n_ff as i64, n_embd as i64),
                ffn_up: mk2(&mut gctx, &mut rng, n_embd as i64, n_ff as i64),
                ffn_post_norm: mkv(&mut gctx, &mut rng, n_embd as i64),
                attn_q_norm: if gemma3 {
                    Some(mkv(&mut gctx, &mut rng, nd as i64))
                } else {
                    None
                },
                attn_k_norm: if gemma3 {
                    Some(mkv(&mut gctx, &mut rng, nd as i64))
                } else {
                    None
                },
            })
            .collect();

        let embd_table = f32s(&gctx, tok_embd);
        let out_norm_v = f32s(&gctx, output_norm);
        struct GD {
            attn_norm: Vec<f32>,
            wq: Vec<f32>,
            wk: Vec<f32>,
            wv: Vec<f32>,
            wo: Vec<f32>,
            post: Vec<f32>,
            ffn_norm: Vec<f32>,
            gate: Vec<f32>,
            down: Vec<f32>,
            up: Vec<f32>,
            ffn_post: Vec<f32>,
            qn: Option<Vec<f32>>,
            kn: Option<Vec<f32>>,
        }
        let lws_data: Vec<GD> = lws
            .iter()
            .map(|l| GD {
                attn_norm: f32s(&gctx, l.attn_norm),
                wq: f32s(&gctx, l.wq),
                wk: f32s(&gctx, l.wk),
                wv: f32s(&gctx, l.wv),
                wo: f32s(&gctx, l.wo),
                post: f32s(&gctx, l.attn_post_norm),
                ffn_norm: f32s(&gctx, l.ffn_norm),
                gate: f32s(&gctx, l.ffn_gate),
                down: f32s(&gctx, l.ffn_down),
                up: f32s(&gctx, l.ffn_up),
                ffn_post: f32s(&gctx, l.ffn_post_norm),
                qn: l.attn_q_norm.map(|t| f32s(&gctx, t)),
                kn: l.attn_k_norm.map(|t| f32s(&gctx, t)),
            })
            .collect();

        let weights = GemmaModelWeights {
            tok_embd,
            output_norm,
            output: tok_embd, // gemma2 ties the head to tok_embd (gemma2.cpp:37)
            layers: lws
                .iter()
                .map(|l| GemmaLayerWeights {
                    attn_norm: l.attn_norm,
                    wq: l.wq,
                    wk: l.wk,
                    wv: l.wv,
                    wo: l.wo,
                    attn_post_norm: l.attn_post_norm,
                    ffn_norm: l.ffn_norm,
                    ffn_gate: l.ffn_gate,
                    ffn_down: l.ffn_down,
                    ffn_up: l.ffn_up,
                    ffn_post_norm: l.ffn_post_norm,
                    attn_q_norm: l.attn_q_norm,
                    attn_k_norm: l.attn_k_norm,
                })
                .collect(),
        };
        let gparams = GemmaParams {
            attn: base_attn(freq_base, n_rot as i64),
            attention_scale,
            attn_logit_softcapping: attn_cap,
            final_logit_softcapping: final_cap,
            attn_soft_cap: !gemma3,           // gemma2.cpp:7
            final_softcap_unguarded: !gemma3, // gemma2.cpp:167-169 has no guard
        };
        let mut gctx2 = gctx;
        let kv = KvCache::new(
            &mut gctx2,
            n_layer,
            (nd * n_head_kv) as i64,
            (nd * n_head_kv) as i64,
            64,
        );
        let watermark = gctx2.mark();
        let mut h = Harness::new(gctx2, kv, watermark);

        // naive gemma forward: (1+w) norms, post-norm residuals, GELU FFN,
        // embd scaled by sqrt(n_embd), Q pre-scaled, gemma3 q/k head norms
        let naive = |toks: &[i32]| -> Vec<f32> {
            let escale = (n_embd as f32).sqrt();
            let mut x: Vec<Vec<f32>> = toks
                .iter()
                .map(|&t| {
                    embd_table[t as usize * n_embd..][..n_embd]
                        .iter()
                        .map(|v| v * escale)
                        .collect()
                })
                .collect();
            for li in 0..n_layer {
                let d = &lws_data[li];
                let mut qs = Vec::new();
                let mut ks = Vec::new();
                let mut vs = Vec::new();
                for (t, xt) in x.iter().enumerate() {
                    let xn = rms(xt, &d.attn_norm, eps, false);
                    let mut q = dot(&d.wq, &xn, n_embd);
                    let mut k = dot(&d.wk, &xn, n_embd);
                    let mut v = dot(&d.wv, &xn, n_embd);
                    if let Some(qn) = &d.qn {
                        // per-head norm (gemma3): rms over each head then (1+w)
                        for hh in 0..n_head {
                            let b = hh * nd;
                            let head: Vec<f32> = rms(&q[b..b + nd], qn, eps, false);
                            q[b..b + nd].copy_from_slice(&head);
                        }
                    }
                    if let Some(kn) = &d.kn {
                        for hh in 0..n_head_kv {
                            let b = hh * nd;
                            let head: Vec<f32> = rms(&k[b..b + nd], kn, eps, false);
                            k[b..b + nd].copy_from_slice(&head);
                        }
                    }
                    rope_neox(&mut q, t as i32, n_head, nd, n_rot, freq_base);
                    rope_neox(&mut k, t as i32, n_head_kv, nd, n_rot, freq_base);
                    f16rt(&mut k);
                    f16rt(&mut v);
                    qs.push(q);
                    ks.push(k);
                    vs.push(v);
                }
                let mut out_x = Vec::new();
                for (t, xt) in x.iter().enumerate() {
                    let acc = softmax_attn(
                        &qs,
                        &ks,
                        &vs,
                        t,
                        n_head,
                        n_head_kv,
                        nd,
                        attention_scale,
                        1.0,
                        gemma_attn_cap,
                    );
                    let a = dot(&d.wo, &acc, n_embd);
                    let a = rms(&a, &d.post, eps, false); // attn_post_norm
                    let sa: Vec<f32> = xt.iter().zip(&a).map(|(p, q)| p + q).collect();
                    let xn = rms(&sa, &d.ffn_norm, eps, false);
                    let g = dot(&d.gate, &xn, n_embd);
                    let u = dot(&d.up, &xn, n_embd);
                    let mut prod = vec![0f32; n_ff];
                    for i in 0..n_ff {
                        // gelu: the op reads the f16 table (vec.h:987), NOT the
                        // polynomial — verify against ops.rs ggml_vec_gelu_f32
                        prod[i] = ggml::ops::ggml_vec_gelu_f32(g[i]) * u[i];
                    }
                    let dwn = dot(&d.down, &prod, n_ff);
                    let dwn = rms(&dwn, &d.ffn_post, eps, false); // ffn_post_norm
                    out_x.push(dwn.iter().zip(&sa).map(|(p, q)| p + q).collect());
                }
                x = out_x;
            }
            let last = x.last().unwrap();
            let xn = rms(last, &out_norm_v, eps, false);
            let mut lg = dot(&embd_table, &xn, n_embd);
            // final logit softcap (gemma2.cpp:167-169 unguarded,
            // gemma3.cpp:210-214 guarded): scale(1/cap) → tanh → scale(cap)
            if !gemma3 || final_cap != 0.0 {
                for v in lg.iter_mut() {
                    *v = (*v * (1.0 / final_cap)).tanh() * final_cap;
                }
            }
            lg
        };

        let build = if gemma3 {
            build_gemma3_forward
        } else {
            build_gemma2_forward
        };
        // adapt the &AttnParams harness signature to the &GemmaParams builder
        let build = |ctx: &mut Context,
                     w: &GemmaModelWeights,
                     ap: &AttnParams,
                     kv: &KvCache,
                     inp: &DecodeInputs,
                     s: SlotInfo,
                     nk: u32,
                     nt: usize| {
            let gp = GemmaParams {
                attn: *ap,
                ..gparams
            };
            build(ctx, w, &gp, kv, inp, s, nk, nt)
        };
        let mut all: Vec<i32> = vec![5, 9, 42];
        let got = h.decode(&weights, &gparams.attn, &all, &[0, 1, 2], build);
        let want0 = naive(&all);
        let err = rel_err(&got, &want0);
        let arch = if gemma3 { "gemma3" } else { "gemma2" };
        assert!(err < 2e-2, "{arch} prefill mismatch: {err:.4}");
        println!("{arch} prefill rel err {err:.5}");

        for p in 3..6 {
            let tok = argmax(&got);
            all.push(tok);
            let got2 = h.decode(&weights, &gparams.attn, &[tok], &[p], build);
            let want = naive(&all);
            // decode convention verbatim from toy_qwen2: max(|b|,1.0) denominator, 5e-2
            let err = got2
                .iter()
                .zip(&want)
                .map(|(a, b)| (a - b).abs() / b.abs().max(1.0))
                .fold(0f32, f32::max);
            assert!(err < 5e-2, "{arch} decode pos {p} mismatch: {err:.4}");
            println!("{arch} decode pos={p} rel err {err:.5}");
        }
    }

    #[test]
    fn toy_gemma2_matches_naive() {
        run_gemma_toy(false);
    }

    #[test]
    fn toy_gemma3_matches_naive() {
        run_gemma_toy(true);
    }

    // ================================================================
    // phi3
    // ================================================================

    #[test]
    fn toy_phi3_matches_naive() {
        let n_embd = 64usize;
        let (n_head, n_head_kv, nd) = (4usize, 2usize, 16usize);
        let n_embd_gqa = nd * n_head_kv;
        let nq = nd * n_head;
        let n_ff = 96usize;
        let n_vocab = 100usize;
        let n_layer = 2usize;
        let eps = 1e-6f32;
        let freq_base = 10000.0f32; // phi3-mini uses 10k

        let mut gctx = Context::new();
        let mut rng = Rng(3131);
        let tok_embd = mk2(&mut gctx, &mut rng, n_embd as i64, n_vocab as i64);
        let output = mk2(&mut gctx, &mut rng, n_embd as i64, n_vocab as i64);
        let output_norm = mkv(&mut gctx, &mut rng, n_embd as i64);
        let output_b = mkv(&mut gctx, &mut rng, n_vocab as i64);
        struct PW {
            attn_norm: TensorId,
            wqkv: TensorId,
            wqkv_b: TensorId,
            wo: TensorId,
            ffn_norm: TensorId,
            ffn_down: TensorId,
            ffn_up: TensorId,
        }
        let lws: Vec<PW> = (0..n_layer)
            .map(|_| PW {
                attn_norm: mkv(&mut gctx, &mut rng, n_embd as i64),
                wqkv: mk2(
                    &mut gctx,
                    &mut rng,
                    n_embd as i64,
                    (nq + 2 * n_embd_gqa) as i64,
                ),
                wqkv_b: mkv(&mut gctx, &mut rng, (nq + 2 * n_embd_gqa) as i64),
                wo: mk2(&mut gctx, &mut rng, n_embd as i64, n_embd as i64),
                ffn_norm: mkv(&mut gctx, &mut rng, n_embd as i64),
                ffn_down: mk2(&mut gctx, &mut rng, n_ff as i64, n_embd as i64),
                ffn_up: mk2(&mut gctx, &mut rng, n_embd as i64, (2 * n_ff) as i64),
            })
            .collect();

        let embd_table = f32s(&gctx, tok_embd);
        let out_w = f32s(&gctx, output);
        let out_norm_v = f32s(&gctx, output_norm);
        let out_bias = f32s(&gctx, output_b);
        struct PD {
            attn_norm: Vec<f32>,
            wqkv: Vec<f32>,
            wqkv_b: Vec<f32>,
            wo: Vec<f32>,
            ffn_norm: Vec<f32>,
            ffn_down: Vec<f32>,
            ffn_up: Vec<f32>,
        }
        let lws_data: Vec<PD> = lws
            .iter()
            .map(|l| PD {
                attn_norm: f32s(&gctx, l.attn_norm),
                wqkv: f32s(&gctx, l.wqkv),
                wqkv_b: f32s(&gctx, l.wqkv_b),
                wo: f32s(&gctx, l.wo),
                ffn_norm: f32s(&gctx, l.ffn_norm),
                ffn_down: f32s(&gctx, l.ffn_down),
                ffn_up: f32s(&gctx, l.ffn_up),
            })
            .collect();

        let weights = Phi3ModelWeights {
            tok_embd,
            output_norm,
            output,
            output_b: Some(output_b),
            layers: lws
                .iter()
                .map(|l| Phi3LayerWeights {
                    attn_norm: l.attn_norm,
                    wqkv: l.wqkv,
                    wqkv_b: Some(l.wqkv_b),
                    wo: l.wo,
                    wo_b: None,
                    ffn_norm: l.ffn_norm,
                    ffn_down: l.ffn_down,
                    ffn_up: l.ffn_up,
                })
                .collect(),
        };
        let attn = base_attn(freq_base, nd as i64);
        let mut gctx2 = gctx;
        let kv = KvCache::new(
            &mut gctx2,
            n_layer,
            n_embd_gqa as i64,
            n_embd_gqa as i64,
            64,
        );
        let watermark = gctx2.mark();
        let mut h = Harness::new(gctx2, kv, watermark);

        let naive = |toks: &[i32]| -> Vec<f32> {
            let mut x: Vec<Vec<f32>> = toks
                .iter()
                .map(|&t| embd_table[t as usize * n_embd..][..n_embd].to_vec())
                .collect();
            let q_pre_scale = 1.0f32 / (nd as f32).sqrt();
            for li in 0..n_layer {
                let d = &lws_data[li];
                let mut qs = Vec::new();
                let mut ks = Vec::new();
                let mut vs = Vec::new();
                for (t, xt) in x.iter().enumerate() {
                    let xn = rms(xt, &d.attn_norm, eps, false);
                    // fused qkv: one matvec then segment [q | k | v] (+ bias)
                    let qkv = dot(&d.wqkv, &xn, n_embd);
                    let qkv: Vec<f32> = qkv.iter().zip(&d.wqkv_b).map(|(v, b)| v + b).collect();
                    let mut q = qkv[0..nq].to_vec();
                    let mut k = qkv[nq..nq + n_embd_gqa].to_vec();
                    let mut v = qkv[nq + n_embd_gqa..].to_vec();
                    rope_neox(&mut q, t as i32, n_head, nd, nd, freq_base);
                    rope_neox(&mut k, t as i32, n_head_kv, nd, nd, freq_base);
                    f16rt(&mut k);
                    f16rt(&mut v);
                    qs.push(q);
                    ks.push(k);
                    vs.push(v);
                }
                let mut outs = Vec::new();
                for (t, xt) in x.iter().enumerate() {
                    let acc = softmax_attn(
                        &qs,
                        &ks,
                        &vs,
                        t,
                        n_head,
                        n_head_kv,
                        nd,
                        q_pre_scale,
                        1.0,
                        None,
                    );
                    let a = dot(&d.wo, &acc, n_embd);
                    let res: Vec<f32> = xt.iter().zip(&a).map(|(p, q)| p + q).collect();
                    let xn = rms(&res, &d.ffn_norm, eps, false);
                    // ffn_up emits 2*n_ff: first half gate, second half up
                    // (verify against ops.cpp:3176 vec_swiglu)
                    let up2 = dot(&d.ffn_up, &xn, n_embd);
                    let mut prod = vec![0f32; n_ff];
                    for i in 0..n_ff {
                        prod[i] = ggml::ops::ggml_silu_f32(up2[i]) * up2[n_ff + i];
                    }
                    let dwn = dot(&d.ffn_down, &prod, n_ff);
                    outs.push(res.iter().zip(&dwn).map(|(p, q)| p + q).collect());
                }
                x = outs;
            }
            let last = x.last().unwrap();
            let xn = rms(last, &out_norm_v, eps, false);
            let mut logits = dot(&out_w, &xn, n_embd);
            for (l, b) in logits.iter_mut().zip(&out_bias) {
                *l += b;
            }
            logits
        };

        let mut all: Vec<i32> = vec![5, 9, 42];
        let got = h.decode(&weights, &attn, &all, &[0, 1, 2], build_phi3_forward);
        let err = rel_err(&got, &naive(&all));
        assert!(err < 2e-2, "phi3 prefill mismatch: {err:.4}");
        println!("phi3 prefill rel err {err:.5}");

        for p in 3..6 {
            let tok = argmax(&got);
            all.push(tok);
            let got2 = h.decode(&weights, &attn, &[tok], &[p], build_phi3_forward);
            let want = naive(&all);
            // decode convention verbatim from toy_qwen2: max(|b|,1.0) denominator, 5e-2
            let err = got2
                .iter()
                .zip(&want)
                .map(|(a, b)| (a - b).abs() / b.abs().max(1.0))
                .fold(0f32, f32::max);
            assert!(err < 5e-2, "phi3 decode pos {p} mismatch: {err:.4}");
            println!("phi3 decode pos={p} rel err {err:.5}");
        }
    }

    // ==================================================================
    // gpt-oss (MoE + sinks + swiglu_oai) — toy model vs naive forward
    // ==================================================================

    /// Toy gpt-oss decode: `build_gpt_oss_forward` (non-FA + softmax sinks,
    /// softmax-after-top-k routing, per-expert biases, swiglu_oai) against a
    /// plain-loop reference. Also pins the graph structure: at least one
    /// MUL_MAT_ID, ADD_ID, GLU and a SOFT_MAX node carrying a src[2] sink.
    #[test]
    // ==============================================================
    // MoE helper (build_moe_ffn_silu) — per-token invariance + naive compare
    // ==============================================================

    /// The granite/lfm2 MoE must be bit-identical per token regardless of the
    /// batch width (T=2 vs two T=1 calls) — the C graph is per-column. Also
    /// checks the value against a naive loop (softmax gating + norm_w).
    #[test]
    fn moe_ffn_silu_per_token_invariance() {
        use ggml::compute::graph_compute;

        const N_EMBD: usize = 8;
        const N_FF: usize = 6;
        const N_EXP: usize = 3;
        const K: usize = 2;
        const T: usize = 2;

        #[allow(clippy::type_complexity)]
        fn build(tt: usize) -> (Context, Vec<Vec<f32>>, Vec<f32>) {
            let mut gctx = Context::new();
            let mut rng = Rng(0xabcd_1234);
            let mut mk = |g: &mut Context, rng: &mut Rng, ne: [i64; 4]| {
                let id = g.new_tensor(GgmlType::F32, ne);
                g.arena_resize_tensor(id);
                g.with_f32_mut(id, |p| {
                    for v in p.iter_mut() {
                        *v = rng.next();
                    }
                })
                .unwrap();
                id
            };
            let cur = mk(&mut gctx, &mut rng, [N_EMBD as i64, tt as i64, 1, 1]);
            let gate_inp = mk(&mut gctx, &mut rng, [N_EMBD as i64, N_EXP as i64, 1, 1]);
            let up = mk(
                &mut gctx,
                &mut rng,
                [N_EMBD as i64, N_FF as i64, N_EXP as i64, 1],
            );
            let gate = mk(
                &mut gctx,
                &mut rng,
                [N_EMBD as i64, N_FF as i64, N_EXP as i64, 1],
            );
            let down = mk(
                &mut gctx,
                &mut rng,
                [N_FF as i64, N_EMBD as i64, N_EXP as i64, 1],
            );
            let snap: Vec<Vec<f32>> = [cur, gate_inp, up, gate, down]
                .iter()
                .map(|&id| {
                    gctx.data_bytes(id)
                        .unwrap()
                        .chunks_exact(4)
                        .map(|c| f32::from_le_bytes(c.try_into().unwrap()))
                        .collect()
                })
                .collect();
            let mut g = Graph::new(64);
            let out = build_moe_ffn_silu(
                &mut gctx,
                &mut g,
                cur,
                gate_inp,
                None,
                up,
                None,
                Some(gate),
                None,
                down,
                None,
                None,
                N_EXP as i64,
                K as i64,
                true,
                0.0,
                EXPERT_GATING_SOFTMAX,
            );
            g.build_forward(&gctx, out);
            graph_compute(&mut gctx, &mut g, 1);
            let got: Vec<f32> = gctx
                .data_bytes(out)
                .unwrap()
                .chunks_exact(4)
                .map(|c| f32::from_le_bytes(c.try_into().unwrap()))
                .collect();
            (gctx, snap, got)
        }

        let (_c2, snap, got2) = build(T);
        let (_c1, _s1, got1) = build(1);
        let snap = &snap;
        let got2 = &got2;
        let _ = got1;

        // naive: softmax gating, top-k (both experts of 3 → k=2), norm_w
        let dot = |w: &[f32], x: &[f32], n0: usize| -> Vec<f32> {
            let n1 = w.len() / n0;
            (0..n1)
                .map(|j| (0..n0).map(|i| w[i + j * n0] * x[i]).sum::<f32>())
                .collect()
        };
        let silu = |x: f32| x / (1.0 + (-x).exp());
        let n_tok = T;
        let mut want = vec![0f32; N_EMBD * n_tok];
        for t in 0..n_tok {
            let xt: Vec<f32> = (0..N_EMBD).map(|i| snap[0][i + t * N_EMBD]).collect();
            let logits = dot(&snap[1], &xt, N_EMBD); // [N_EXP]
            let mx = logits.iter().cloned().fold(f32::NEG_INFINITY, f32::max);
            let exps: Vec<f32> = logits.iter().map(|v| (v - mx).exp()).collect();
            let sum: f32 = exps.iter().sum();
            let probs: Vec<f32> = exps.iter().map(|v| v / sum).collect();
            // top-K by probability (descending), deterministic tie-break by id
            let mut ord: Vec<usize> = (0..N_EXP).collect();
            ord.sort_by(|&a, &b| probs[b].partial_cmp(&probs[a]).unwrap().then(a.cmp(&b)));
            let sel = &ord[..K];
            let wsum: f32 = sel.iter().map(|&e| probs[e]).sum();
            for &e in sel {
                let wgt = probs[e] / wsum;
                // expert FFN: gate_exps[e] [N_EMBD, N_FF], up_exps[e]
                let ge: Vec<f32> = (0..N_EMBD * N_FF)
                    .map(|i| snap[3][i % N_EMBD + (i / N_EMBD) * N_EMBD + e * N_EMBD * N_FF])
                    .collect();
                let ue: Vec<f32> = (0..N_EMBD * N_FF)
                    .map(|i| snap[2][i % N_EMBD + (i / N_EMBD) * N_EMBD + e * N_EMBD * N_FF])
                    .collect();
                let g = dot(&ge, &xt, N_EMBD);
                let u = dot(&ue, &xt, N_EMBD);
                let prod: Vec<f32> = g.iter().zip(&u).map(|(a, b)| silu(*a) * b).collect();
                let mut de: Vec<f32> = vec![0f32; N_FF * N_EMBD];
                for i in 0..N_FF * N_EMBD {
                    de[i] = snap[4][(i % N_FF) + (i / N_FF) * N_FF + e * N_FF * N_EMBD];
                }
                let d = dot(&de, &prod, N_FF);
                for i in 0..N_EMBD {
                    want[i + t * N_EMBD] += wgt * d[i];
                }
            }
        }
        let e = got2
            .iter()
            .zip(&want)
            .map(|(a, b)| (a - b).abs())
            .fold(0f32, f32::max);
        println!("moe T=2 vs naive: max abs err {e:.3e}");
        println!("moe got  {:?}", &got2[..N_EMBD]);
        println!("moe want {:?}", &want[..N_EMBD]);
        assert!(e < 1e-5, "moe ffn mismatch: {e:.3e}");
    }

    /// Replicate the mamba2 conv prepend with toy-shaped tensors and dump
    /// conv_x (the granite `concat(state, transpose(xbc), 0)` pattern).
    #[test]
    fn conv_prepend_concat_probe() {
        use ggml::compute::graph_compute;
        const N_EMBD: usize = 8;
        const T: usize = 4;
        const D_CONV: usize = 4;
        const D_INNER: usize = 3072;
        const D_STATE: usize = 128;
        const N_SSM_HEAD: usize = 48;
        const N_GROUP: usize = 1;
        const CONV_DIM: usize = D_INNER + 2 * N_GROUP * D_STATE;
        const D_IN_PROJ: usize = 2 * D_INNER + 2 * N_GROUP * D_STATE + N_SSM_HEAD;

        let mut ctx = Context::new();
        let mut rng = Rng(0x5151_2323);
        let mut mk = |g: &mut Context, rng: &mut Rng, ne: [i64; 4]| {
            let id = g.new_tensor(GgmlType::F32, ne);
            g.arena_resize_tensor(id);
            g.with_f32_mut(id, |p| {
                for v in p.iter_mut() {
                    *v = rng.next();
                }
            })
            .unwrap();
            id
        };
        let ssm_in = mk(&mut ctx, &mut rng, [N_EMBD as i64, D_IN_PROJ as i64, 1, 1]);
        let cur = mk(&mut ctx, &mut rng, [N_EMBD as i64, T as i64, 1, 1]);
        let conv_state = mk(
            &mut ctx,
            &mut rng,
            [(D_CONV as i64 - 1) * CONV_DIM as i64, 1, 1, 1],
        );

        let zx = ctx.mul_mat(ssm_in, cur);
        let zx = ctx.reshape_3d(zx, D_IN_PROJ as i64, T as i64, 1);
        let nb = *ctx.nb(zx);
        let xbc = ctx.view_3d(
            zx,
            CONV_DIM as i64,
            T as i64,
            1,
            nb[1] as usize,
            nb[2] as usize,
            D_INNER * 4,
        );
        let xbc_t = ctx.transpose(xbc);
        let conv = ctx.reshape_3d(conv_state, D_CONV as i64 - 1, CONV_DIM as i64, 1);
        let conv_x = ctx.concat(conv, xbc_t, 0);

        let mut g = Graph::new(16);
        g.build_forward(&ctx, conv_x);
        graph_compute(&mut ctx, &mut g, 1);

        let ne = *ctx.ne(conv_x);
        let got = ctx.f32s(conv_x).unwrap().to_vec();
        let zxv = ctx.f32s(zx).unwrap();
        let stv = ctx.f32s(conv_state).unwrap();
        let ne0 = ne[0] as usize;
        let mut worst = 0f32;
        for c in 0..CONV_DIM {
            for r in 0..ne0 {
                let want = if r < D_CONV - 1 {
                    stv[r + c * (D_CONV - 1)]
                } else {
                    let tt = r - (D_CONV - 1);
                    // xbc(c, tt) = zx[D_INNER + c + tt*D_IN_PROJ]
                    zxv[D_INNER + c + tt * D_IN_PROJ]
                };
                worst = worst.max((got[r + c * ne0] - want).abs());
            }
        }
        println!("conv prepend concat: ne={ne:?} worst abs err {worst:.3e}");
        assert!(worst < 1e-6, "conv prepend concat wrong: {worst}");
    }

    // ==============================================================
    // lfm2moe toy: graph vs naive (shortconv mixer + gated attention + MoE)
    // ==============================================================

    /// Toy lfm2 driven through `DecodeContext` + `ForwardWeights::Lfm2`:
    /// layer 0 = shortconv mixer, layer 1 = gated attention (q/k rms norm +
    /// NEOX rope), dense FFN on both (n_layer_dense_lead = n_layer), so the
    /// naive reference below stays readable. The shortconv conv state is the
    /// rolling window shared with the graph; every row is compared against the
    /// naive for a prefill batch and for step-by-step decoding.
    #[test]
    fn toy_lfm2_matches_naive() {
        use crate::context::{DecodeContext, ForwardWeights};

        const N_EMBD: usize = 8;
        const N_FF: usize = 16;
        const N_VOCAB: usize = 20;
        const N_HEAD: usize = 2;
        const N_HEAD_KV: usize = 1;
        const HD: usize = 4;
        const L_CACHE: usize = 3;
        const D_CONV: usize = L_CACHE - 1;
        const N_EMBD_R: usize = N_EMBD * (L_CACHE - 1);
        const EPS: f32 = 1e-6;
        const FREQ_BASE: f32 = 10000.0;

        fn dot(w: &[f32], x: &[f32], n0: usize) -> Vec<f32> {
            let n1 = w.len() / n0.max(1);
            (0..n1)
                .map(|j| (0..n0).map(|i| w[i + j * n0] * x[i]).sum::<f32>())
                .collect()
        }
        fn rms(x: &[f32], w: &[f32]) -> Vec<f32> {
            let sum: f32 = x.iter().map(|v| v * v).sum();
            let sc = 1.0 / (sum / x.len() as f32 + EPS).sqrt();
            x.iter().zip(w).map(|(v, wv)| v * sc * wv).collect()
        }
        fn silu(x: f32) -> f32 {
            1.0 / (1.0 + (-x).exp()) * x
        }
        fn rope_neox(v: &mut [f32], pos: i32, n_heads: usize, hd: usize) {
            for h in 0..n_heads {
                let b = h * hd;
                for j in 0..hd / 2 {
                    let f = 1.0f32 / FREQ_BASE.powf(2.0 * j as f32 / hd as f32);
                    let theta = pos as f32 * f;
                    let (c, s) = (theta.cos(), theta.sin());
                    let x0 = v[b + j];
                    let x1 = v[b + j + hd / 2];
                    v[b + j] = x0 * c - x1 * s;
                    v[b + j + hd / 2] = x0 * s + x1 * c;
                }
            }
        }

        struct Naive {
            conv: Vec<f32>, // [n_embd_r] rolling shortconv window
            k: Vec<Vec<f32>>,
            v: Vec<Vec<f32>>,
        }

        /// naive forward for one token (lfm2.cpp:159-228 shortconv block,
        /// :118-157 attention block, :270-277 dense FFN).
        /// `s` = weights in the order built below.
        fn naive_step(s: &[Vec<f32>], ns: &mut Naive, tok: i32, pos: i32) -> Vec<f32> {
            let mut cur: Vec<f32> = s[0][tok as usize * N_EMBD..][..N_EMBD].to_vec();
            // ---- layer 0: shortconv
            let prev = cur.clone();
            let xn = rms(&cur, &s[3]);
            let bcx = dot(&s[4], &xn, N_EMBD); // [3*n_embd]
            let bb: Vec<f32> = bcx[..N_EMBD].to_vec();
            let cc: Vec<f32> = bcx[N_EMBD..2 * N_EMBD].to_vec();
            let xx: Vec<f32> = bcx[2 * N_EMBD..].to_vec();
            let bx: Vec<f32> = bb.iter().zip(&xx).map(|(a, b)| a * b).collect();
            // window = [state (d_conv rows) ; bx] with row = channel-major:
            // element (row r, channel c) at r*N_EMBD + c
            let mut win = vec![0f32; (D_CONV + 1) * N_EMBD];
            for c in 0..N_EMBD {
                for r in 0..D_CONV {
                    win[r * N_EMBD + c] = ns.conv[r + c * D_CONV];
                }
                win[D_CONV * N_EMBD + c] = bx[c];
            }
            // new state = the last d_conv rows
            for c in 0..N_EMBD {
                for r in 0..D_CONV {
                    ns.conv[r + c * D_CONV] = win[(r + 1) * N_EMBD + c];
                }
            }
            // ssm_conv: kernel l_cache wide (d_conv history + current)
            let mut conv_out = vec![0f32; N_EMBD];
            for c in 0..N_EMBD {
                let mut acc = 0f32;
                for i0 in 0..L_CACHE {
                    acc += win[i0 * N_EMBD + c] * s[5][i0 + c * L_CACHE];
                }
                conv_out[c] = acc;
            }
            let y: Vec<f32> = cc.iter().zip(&conv_out).map(|(a, b)| a * b).collect();
            let mixer = dot(&s[6], &y, N_EMBD);
            cur = prev.iter().zip(&mixer).map(|(a, b)| a + b).collect();
            // ---- layer 0 dense FFN
            let xn = rms(&cur, &s[7]);
            let g = dot(&s[8], &xn, N_EMBD);
            let u = dot(&s[9], &xn, N_EMBD);
            let prod: Vec<f32> = g.iter().zip(&u).map(|(a, b)| silu(*a) * b).collect();
            let d = dot(&s[10], &prod, N_FF);
            cur = cur.iter().zip(&d).map(|(a, b)| a + b).collect();
            // ---- layer 1: attention (q/k rms norm + rope)
            let prev = cur.clone();
            let xn = rms(&cur, &s[11]);
            let mut q = dot(&s[12], &xn, N_EMBD);
            let mut k = dot(&s[13], &xn, N_EMBD);
            let v = dot(&s[14], &xn, N_EMBD);
            // q/k norms are per head (n_embd_head weights, repeated by head)
            for h in 0..N_HEAD {
                let seg: Vec<f32> = q[h * HD..(h + 1) * HD].to_vec();
                let n = rms(&seg, &s[15]);
                q[h * HD..(h + 1) * HD].copy_from_slice(&n);
            }
            for h in 0..N_HEAD_KV {
                let seg: Vec<f32> = k[h * HD..(h + 1) * HD].to_vec();
                let n = rms(&seg, &s[16]);
                k[h * HD..(h + 1) * HD].copy_from_slice(&n);
            }
            rope_neox(&mut q, pos, N_HEAD, HD);
            rope_neox(&mut k, pos, N_HEAD_KV, HD);
            ns.k.push(k);
            ns.v.push(v);
            let n = ns.k.len();
            let scale = 1.0 / (HD as f32).sqrt();
            let mut acc = vec![0f32; N_HEAD * HD];
            for h in 0..N_HEAD {
                let kvh = h / (N_HEAD / N_HEAD_KV);
                let mut sw = Vec::with_capacity(n);
                for s2 in 0..n {
                    let mut dd = 0f32;
                    for i in 0..HD {
                        dd += ns.k[s2][kvh * HD + i] * q[h * HD + i];
                    }
                    sw.push((dd * scale).exp());
                }
                let sum: f32 = sw.iter().sum();
                for i in 0..HD {
                    let mut o = 0f32;
                    for (s2, w2) in sw.iter().enumerate() {
                        o += w2 / sum * ns.v[s2][kvh * HD + i];
                    }
                    acc[h * HD + i] = o;
                }
            }
            let a = dot(&s[17], &acc, N_HEAD * HD);
            cur = prev.iter().zip(&a).map(|(p, q2)| p + q2).collect();
            // ---- layer 1 dense FFN
            let xn = rms(&cur, &s[18]);
            let g = dot(&s[19], &xn, N_EMBD);
            let u = dot(&s[20], &xn, N_EMBD);
            let prod: Vec<f32> = g.iter().zip(&u).map(|(a, b)| silu(*a) * b).collect();
            let d = dot(&s[21], &prod, N_FF);
            cur = cur.iter().zip(&d).map(|(a, b)| a + b).collect();
            // ---- token_embd_norm + tied head
            let xn = rms(&cur, &s[2]);
            dot(&s[1], &xn, N_EMBD)
        }

        #[allow(clippy::type_complexity)]
        fn build_toy() -> (DecodeContext, Vec<Vec<f32>>) {
            let mut gctx = Context::new();
            let mut rng = Rng(0x7f7f_1212);
            let mut mk = |g: &mut Context, rng: &mut Rng, ne: [i64; 4]| {
                let id = g.new_tensor(GgmlType::F32, ne);
                g.arena_resize_tensor(id);
                g.with_f32_mut(id, |p| {
                    for v in p.iter_mut() {
                        *v = rng.next();
                    }
                })
                .unwrap();
                id
            };
            let tok_embd = mk(&mut gctx, &mut rng, [N_EMBD as i64, N_VOCAB as i64, 1, 1]);
            let output = mk(&mut gctx, &mut rng, [N_EMBD as i64, N_VOCAB as i64, 1, 1]);
            let output_norm = mk(&mut gctx, &mut rng, [N_EMBD as i64, 1, 1, 1]);
            // layer 0: shortconv + dense
            let l0_attn_norm = mk(&mut gctx, &mut rng, [N_EMBD as i64, 1, 1, 1]);
            let l0_conv = mk(&mut gctx, &mut rng, [L_CACHE as i64, N_EMBD as i64, 1, 1]);
            let l0_in = mk(
                &mut gctx,
                &mut rng,
                [N_EMBD as i64, 3 * N_EMBD as i64, 1, 1],
            );
            let l0_out = mk(&mut gctx, &mut rng, [N_EMBD as i64, N_EMBD as i64, 1, 1]);
            let l0_ffn_norm = mk(&mut gctx, &mut rng, [N_EMBD as i64, 1, 1, 1]);
            let l0_gate = mk(&mut gctx, &mut rng, [N_EMBD as i64, N_FF as i64, 1, 1]);
            let l0_up = mk(&mut gctx, &mut rng, [N_EMBD as i64, N_FF as i64, 1, 1]);
            let l0_down = mk(&mut gctx, &mut rng, [N_FF as i64, N_EMBD as i64, 1, 1]);
            // layer 1: attention + dense
            let l1_attn_norm = mk(&mut gctx, &mut rng, [N_EMBD as i64, 1, 1, 1]);
            let l1_wq = mk(
                &mut gctx,
                &mut rng,
                [N_EMBD as i64, (N_HEAD * HD) as i64, 1, 1],
            );
            let l1_wk = mk(
                &mut gctx,
                &mut rng,
                [N_EMBD as i64, (N_HEAD_KV * HD) as i64, 1, 1],
            );
            let l1_wv = mk(
                &mut gctx,
                &mut rng,
                [N_EMBD as i64, (N_HEAD_KV * HD) as i64, 1, 1],
            );
            let l1_wo = mk(
                &mut gctx,
                &mut rng,
                [(N_HEAD * HD) as i64, N_EMBD as i64, 1, 1],
            );
            let l1_qn = mk(&mut gctx, &mut rng, [HD as i64, 1, 1, 1]);
            let l1_kn = mk(&mut gctx, &mut rng, [HD as i64, 1, 1, 1]);
            let l1_ffn_norm = mk(&mut gctx, &mut rng, [N_EMBD as i64, 1, 1, 1]);
            let l1_gate = mk(&mut gctx, &mut rng, [N_EMBD as i64, N_FF as i64, 1, 1]);
            let l1_up = mk(&mut gctx, &mut rng, [N_EMBD as i64, N_FF as i64, 1, 1]);
            let l1_down = mk(&mut gctx, &mut rng, [N_FF as i64, N_EMBD as i64, 1, 1]);

            let attn = AttnParams {
                n_head: N_HEAD as i64,
                n_head_kv: N_HEAD_KV as i64,
                n_embd_head_k: HD as i64,
                n_embd_head_v: HD as i64,
                n_rot: HD as i64,
                rope_mode: 2,
                n_ctx_orig: 64,
                freq_base: FREQ_BASE,
                freq_scale: 1.0,
                ext_factor: 0.0,
                attn_factor: 1.0,
                beta_fast: 32.0,
                beta_slow: 1.0,
                norm_eps: EPS,
                use_flash_attn: false,
            };
            let p = Lfm2Params {
                attn,
                n_embd: N_EMBD as i64,
                n_head: vec![N_HEAD as u32, N_HEAD as u32],
                n_head_kv: vec![0, N_HEAD_KV as u32],
                n_embd_head_k: vec![HD as u32, HD as u32],
                n_embd_head_v: vec![HD as u32, HD as u32],
                is_recr: vec![true, false],
                n_shortconv_l_cache: L_CACHE as i64,
                n_layer_dense_lead: 2,
                n_expert: 0,
                n_expert_used: vec![0, 0],
                n_ff_exp: 0,
                expert_weights_scale: 0.0,
                expert_gating_func: EXPERT_GATING_SOFTMAX,
                causal_attn: true,
                n_embd_r: N_EMBD_R as u32,
            };
            let w = Lfm2ModelWeights {
                tok_embd,
                output_norm,
                output,
                layers: vec![
                    Lfm2LayerWeights {
                        attn_norm: l0_attn_norm,
                        shortconv_conv: Some(l0_conv),
                        shortconv_in_proj: Some(l0_in),
                        shortconv_out_proj: Some(l0_out),
                        wq: None,
                        wk: None,
                        wv: None,
                        wo: None,
                        attn_q_norm: None,
                        attn_k_norm: None,
                        wq_b: None,
                        wk_b: None,
                        wv_b: None,
                        ffn_norm: l0_ffn_norm,
                        ffn_gate: Some(l0_gate),
                        ffn_down: Some(l0_down),
                        ffn_up: Some(l0_up),
                        ffn_gate_inp: None,
                        ffn_gate_exps: None,
                        ffn_down_exps: None,
                        ffn_up_exps: None,
                        ffn_exp_probs_b: None,
                    },
                    Lfm2LayerWeights {
                        attn_norm: l1_attn_norm,
                        shortconv_conv: None,
                        shortconv_in_proj: None,
                        shortconv_out_proj: None,
                        wq: Some(l1_wq),
                        wk: Some(l1_wk),
                        wv: Some(l1_wv),
                        wo: Some(l1_wo),
                        attn_q_norm: Some(l1_qn),
                        attn_k_norm: Some(l1_kn),
                        wq_b: None,
                        wk_b: None,
                        wv_b: None,
                        ffn_norm: l1_ffn_norm,
                        ffn_gate: Some(l1_gate),
                        ffn_down: Some(l1_down),
                        ffn_up: Some(l1_up),
                        ffn_gate_inp: None,
                        ffn_gate_exps: None,
                        ffn_down_exps: None,
                        ffn_up_exps: None,
                        ffn_exp_probs_b: None,
                    },
                ],
            };
            // order must match naive_step's `s[i]` (l0_in before l0_conv!)
            let ids = [
                tok_embd,
                output,
                output_norm,
                l0_attn_norm,
                l0_in,
                l0_conv,
                l0_out,
                l0_ffn_norm,
                l0_gate,
                l0_up,
                l0_down,
                l1_attn_norm,
                l1_wq,
                l1_wk,
                l1_wv,
                l1_qn,
                l1_kn,
                l1_wo,
                l1_ffn_norm,
                l1_gate,
                l1_up,
                l1_down,
            ];
            let snap: Vec<Vec<f32>> = ids
                .iter()
                .map(|&id| {
                    gctx.data_bytes(id)
                        .unwrap()
                        .chunks_exact(4)
                        .map(|c| f32::from_le_bytes(c.try_into().unwrap()))
                        .collect()
                })
                .collect();
            let dctx = DecodeContext::new_with(gctx, ForwardWeights::Lfm2(w, p), attn, 64, 4, 16);
            (dctx, snap)
        }

        let ids = [3i32, 7, 1, 15, 9];

        // (a) prefill batch: every row vs the naive
        let (mut dctx, snap) = build_toy();
        let all = dctx
            .decode_all(&ids, &(0..ids.len() as i32).collect::<Vec<_>>())
            .unwrap();
        let nv = dctx.n_vocab();
        let mut ns = Naive {
            conv: vec![0.0; N_EMBD_R],
            k: Vec::new(),
            v: Vec::new(),
        };
        for (r, &t) in ids.iter().enumerate() {
            let want = naive_step(&snap, &mut ns, t, r as i32);
            let row = &all[r * nv..(r + 1) * nv];
            let e = row
                .iter()
                .zip(&want)
                .map(|(a, b)| (a - b).abs())
                .fold(0f32, f32::max);
            println!("toy lfm2 batch row{r}: max abs err {e:.3e}");
            assert!(e < 1e-4, "toy lfm2 batch row {r} mismatch: {e:.3e}");
        }

        // (b) step by step (shortconv state + kv carry)
        let (mut dctx1, snap1) = build_toy();
        let mut ns1 = Naive {
            conv: vec![0.0; N_EMBD_R],
            k: Vec::new(),
            v: Vec::new(),
        };
        for (i, &t) in ids.iter().enumerate() {
            let got = dctx1.decode(&[t], &[i as i32]).unwrap().to_vec();
            let want = naive_step(&snap1, &mut ns1, t, i as i32);
            let e = got
                .iter()
                .zip(&want)
                .map(|(a, b)| (a - b).abs())
                .fold(0f32, f32::max);
            assert!(e < 1e-4, "toy lfm2 step {i} mismatch: {e:.3e}");
        }
        assert_eq!(dctx1.kv.used_cells(), ids.len() as u32);
        println!("toy lfm2 step-by-step: all {} tokens ok", ids.len());
    }

    // ==============================================================
    // granite-hybrid toy: graph vs naive (mamba2 mixer + attention)
    // (method verbatim from toy_gpt_oss_matches_naive / context.rs toy_qwen2_matches_naive)
    // ==============================================================

    /// Toy granite-hybrid model driven through `DecodeContext` +
    /// `ForwardWeights::Granite` (which also exercises the recurrent-state
    /// allocation in context.rs): layer 0 is a mamba2 mixer, layer 1 attention,
    /// dense FFN (n_expert = 0), no rope, every granite scale 0. The naive
    /// reference keeps the same conv/ssm recurrent state and KV history, so it
    /// validates the graph both as one prefill batch and step by step.
    #[test]
    fn toy_granite_matches_naive() {
        use crate::context::{DecodeContext, ForwardWeights};

        const N_EMBD: usize = 8;
        const N_FF: usize = 16;
        const N_VOCAB: usize = 20;
        const N_HEAD: usize = 2;
        const N_HEAD_KV: usize = 1;
        const HD: usize = 4;
        const D_CONV: usize = 4;
        const D_INNER: usize = 3072;
        const D_STATE: usize = 128;
        const N_SSM_HEAD: usize = 48;
        const N_GROUP: usize = 1;
        const EPS: f32 = 1e-6;
        const CONV_DIM: usize = D_INNER + 2 * N_GROUP * D_STATE;
        const N_EMBD_R: usize = (D_CONV - 1) * CONV_DIM;
        const N_EMBD_S: usize = D_STATE * D_INNER;
        const D_IN_PROJ: usize = 2 * D_INNER + 2 * N_GROUP * D_STATE + N_SSM_HEAD;

        struct NaiveState {
            conv: Vec<f32>, // [n_embd_r]
            ssm: Vec<f32>,  // [n_embd_s]
            k: Vec<Vec<f32>>,
            v: Vec<Vec<f32>>,
        }
        impl NaiveState {
            fn new() -> Self {
                NaiveState {
                    conv: vec![0.0; N_EMBD_R],
                    ssm: vec![0.0; N_EMBD_S],
                    k: Vec::new(),
                    v: Vec::new(),
                }
            }
        }

        fn dot(w: &[f32], x: &[f32], n0: usize) -> Vec<f32> {
            let n1 = w.len() / n0.max(1);
            (0..n1)
                .map(|j| (0..n0).map(|i| w[i + j * n0] * x[i]).sum::<f32>())
                .collect()
        }
        fn rms(x: &[f32], w: &[f32]) -> Vec<f32> {
            let sum: f32 = x.iter().map(|v| v * v).sum();
            let sc = 1.0 / (sum / x.len() as f32 + EPS).sqrt();
            x.iter().zip(w).map(|(v, wv)| v * sc * wv).collect()
        }
        fn silu(x: f32) -> f32 {
            1.0 / (1.0 + (-x).exp()) * x
        }
        fn softplus(x: f32) -> f32 {
            if x > 20.0 {
                x
            } else {
                (1.0 + x.exp()).ln()
            }
        }

        /// naive forward for one token, updating the recurrent state and KV
        /// history exactly as the C graph does (mamba-base.cpp:153 /
        /// granite-hybrid.cpp:200-302).
        /// `s` = weight snapshot in the order below.
        fn naive_step(s: &[Vec<f32>], ns: &mut NaiveState, tok: i32) -> Vec<f32> {
            let mut x: Vec<f32> = s[0][tok as usize * N_EMBD..][..N_EMBD].to_vec();

            // ---- layer 0: mamba2 mixer
            let xn = rms(&x, &s[3]);
            let zx = dot(&s[4], &xn, N_EMBD); // [d_in_proj]
            let z: Vec<f32> = zx[..D_INNER].to_vec();
            let xbc: Vec<f32> = zx[D_INNER..D_INNER + CONV_DIM].to_vec();
            let dt_raw: Vec<f32> = zx[2 * D_INNER + 2 * N_GROUP * D_STATE..][..N_SSM_HEAD].to_vec();
            // conv_x = [state (d_conv-1 rows) ; xbc as one row] (row = channel-major
            // window: element (row r, channel c) at r*conv_dim + c)
            let mut win = vec![0f32; D_CONV * CONV_DIM];
            for c in 0..CONV_DIM {
                for r in 0..D_CONV - 1 {
                    win[r * CONV_DIM + c] = ns.conv[r + c * (D_CONV - 1)];
                }
                win[(D_CONV - 1) * CONV_DIM + c] = xbc[c];
            }
            // new state = the last (d_conv-1) rows
            for c in 0..CONV_DIM {
                for r in 0..D_CONV - 1 {
                    ns.conv[r + c * (D_CONV - 1)] = win[(r + 1) * CONV_DIM + c];
                }
            }
            // ggml_ssm_conv (one output token) + bias + silu
            let mut xc = vec![0f32; CONV_DIM];
            for c in 0..CONV_DIM {
                let mut acc = 0f32;
                for i0 in 0..D_CONV {
                    acc += win[i0 * CONV_DIM + c] * s[5][i0 + c * D_CONV];
                }
                xc[c] = silu(acc + s[6][c]);
            }
            let xv: Vec<f32> = xc[..D_INNER].to_vec();
            let bv: Vec<f32> = xc[D_INNER..D_INNER + N_GROUP * D_STATE].to_vec();
            let cv: Vec<f32> = xc[D_INNER + N_GROUP * D_STATE..][..N_GROUP * D_STATE].to_vec();
            // ssm_scan (mamba2 branch, one token)
            let head_dim = D_INNER / N_SSM_HEAD;
            let mut y = vec![0f32; D_INNER];
            for h in 0..N_SSM_HEAD {
                let dt_sp = softplus(dt_raw[h] + s[7][h]);
                let da = (dt_sp * s[8][h]).exp();
                let g = h / (N_SSM_HEAD / N_GROUP);
                for d in 0..head_dim {
                    let ii = d + h * head_dim;
                    let x_dt = xv[ii] * dt_sp;
                    let mut sumf = 0f32;
                    for st in 0..D_STATE {
                        let i = st + ii * D_STATE;
                        let ig = st + g * D_STATE;
                        let state = ns.ssm[i] * da + bv[ig] * x_dt;
                        sumf += state * cv[ig];
                        ns.ssm[i] = state;
                    }
                    y[ii] = sumf;
                }
            }
            // y += x*D ; swiglu_split(cont(z), y) ; grouped rms ; out_proj
            let mut act = vec![0f32; D_INNER];
            for i in 0..D_INNER {
                let yv = y[i] + xv[i] * s[9][i / head_dim];
                act[i] = silu(z[i]) * yv;
            }
            let actn = rms(&act, &s[10]);
            let mixer = dot(&s[11], &actn, D_INNER);
            x = x.iter().zip(&mixer).map(|(a, b)| a + b).collect();

            // ---- layer 0 dense FFN
            let xn = rms(&x, &s[12]);
            let g = dot(&s[13], &xn, N_EMBD);
            let u = dot(&s[14], &xn, N_EMBD);
            let prod: Vec<f32> = g.iter().zip(&u).map(|(a, b)| silu(*a) * b).collect();
            let d = dot(&s[15], &prod, N_FF);
            x = x.iter().zip(&d).map(|(a, b)| a + b).collect();

            // ---- layer 1: attention (no rope)
            let xn = rms(&x, &s[16]);
            let q = dot(&s[17], &xn, N_EMBD);
            let k = dot(&s[18], &xn, N_EMBD);
            let v = dot(&s[19], &xn, N_EMBD);
            ns.k.push(k);
            ns.v.push(v);
            let n = ns.k.len();
            let scale = 1.0 / (HD as f32).sqrt();
            let mut acc = vec![0f32; N_HEAD * HD];
            for h in 0..N_HEAD {
                let kvh = h / (N_HEAD / N_HEAD_KV);
                let mut sw = Vec::with_capacity(n);
                for s2 in 0..n {
                    let mut dd = 0f32;
                    for i in 0..HD {
                        dd += ns.k[s2][kvh * HD + i] * q[h * HD + i];
                    }
                    sw.push((dd * scale).exp());
                }
                let sum: f32 = sw.iter().sum();
                for i in 0..HD {
                    let mut o = 0f32;
                    for (s2, w2) in sw.iter().enumerate() {
                        o += w2 / sum * ns.v[s2][kvh * HD + i];
                    }
                    acc[h * HD + i] = o;
                }
            }
            let a = dot(&s[20], &acc, N_HEAD * HD);
            x = x.iter().zip(&a).map(|(p2, q2)| p2 + q2).collect();

            // ---- layer 1 dense FFN
            let xn = rms(&x, &s[21]);
            let g = dot(&s[22], &xn, N_EMBD);
            let u = dot(&s[23], &xn, N_EMBD);
            let prod: Vec<f32> = g.iter().zip(&u).map(|(a, b)| silu(*a) * b).collect();
            let d = dot(&s[24], &prod, N_FF);
            x = x.iter().zip(&d).map(|(a, b)| a + b).collect();

            // final norm + lm_head
            let xn = rms(&x, &s[2]);
            dot(&s[1], &xn, N_EMBD)
        }

        /// build a fresh toy model (weights + params + context) and return
        /// (DecodeContext, weight snapshot for the naive loop)
        fn build_toy() -> (DecodeContext, Vec<Vec<f32>>) {
            let mut gctx = Context::new();
            let mut rng = Rng(0x1234_5678);
            let mk2 = |g: &mut Context, rng: &mut Rng, n0: i64, n1: i64| -> TensorId {
                let id = g.new_tensor_2d(GgmlType::F32, n0, n1);
                g.arena_resize_tensor(id);
                g.with_f32_mut(id, |p| {
                    for v in p.iter_mut() {
                        *v = rng.next();
                    }
                })
                .unwrap();
                id
            };
            let tok_embd = mk2(&mut gctx, &mut rng, N_EMBD as i64, N_VOCAB as i64);
            let output = mk2(&mut gctx, &mut rng, N_EMBD as i64, N_VOCAB as i64);
            let output_norm = mk2(&mut gctx, &mut rng, N_EMBD as i64, 1);
            // layer 0 (mamba2)
            let l0_attn_norm = mk2(&mut gctx, &mut rng, N_EMBD as i64, 1);
            let l0_ssm_in = mk2(&mut gctx, &mut rng, N_EMBD as i64, D_IN_PROJ as i64);
            let l0_conv = mk2(&mut gctx, &mut rng, D_CONV as i64, CONV_DIM as i64);
            let l0_conv_b = mk2(&mut gctx, &mut rng, CONV_DIM as i64, 1);
            let l0_dt_b = mk2(&mut gctx, &mut rng, N_SSM_HEAD as i64, 1);
            let l0_a = mk2(&mut gctx, &mut rng, 1, N_SSM_HEAD as i64);
            let l0_d = mk2(&mut gctx, &mut rng, 1, N_SSM_HEAD as i64);
            let l0_ssm_norm = mk2(&mut gctx, &mut rng, D_INNER as i64, 1);
            let l0_ssm_out = mk2(&mut gctx, &mut rng, D_INNER as i64, N_EMBD as i64);
            let l0_ffn_norm = mk2(&mut gctx, &mut rng, N_EMBD as i64, 1);
            let l0_gate = mk2(&mut gctx, &mut rng, N_EMBD as i64, N_FF as i64);
            let l0_up = mk2(&mut gctx, &mut rng, N_EMBD as i64, N_FF as i64);
            let l0_down = mk2(&mut gctx, &mut rng, N_FF as i64, N_EMBD as i64);
            // layer 1 (attention)
            let l1_attn_norm = mk2(&mut gctx, &mut rng, N_EMBD as i64, 1);
            let l1_wq = mk2(&mut gctx, &mut rng, N_EMBD as i64, (N_HEAD * HD) as i64);
            let l1_wk = mk2(&mut gctx, &mut rng, N_EMBD as i64, (N_HEAD_KV * HD) as i64);
            let l1_wv = mk2(&mut gctx, &mut rng, N_EMBD as i64, (N_HEAD_KV * HD) as i64);
            let l1_wo = mk2(&mut gctx, &mut rng, (N_HEAD * HD) as i64, N_EMBD as i64);
            let l1_ffn_norm = mk2(&mut gctx, &mut rng, N_EMBD as i64, 1);
            let l1_gate = mk2(&mut gctx, &mut rng, N_EMBD as i64, N_FF as i64);
            let l1_up = mk2(&mut gctx, &mut rng, N_EMBD as i64, N_FF as i64);
            let l1_down = mk2(&mut gctx, &mut rng, N_FF as i64, N_EMBD as i64);

            let attn = AttnParams {
                n_head: N_HEAD as i64,
                n_head_kv: N_HEAD_KV as i64,
                n_embd_head_k: HD as i64,
                n_embd_head_v: HD as i64,
                n_rot: HD as i64,
                rope_mode: 2,
                n_ctx_orig: 64,
                freq_base: 10000.0,
                freq_scale: 1.0,
                ext_factor: 0.0,
                attn_factor: 1.0,
                beta_fast: 32.0,
                beta_slow: 1.0,
                norm_eps: EPS,
                use_flash_attn: false,
            };
            let p = GraniteParams {
                attn,
                n_embd: N_EMBD as i64,
                n_head: vec![N_HEAD as u32, N_HEAD as u32],
                n_head_kv: vec![0, N_HEAD_KV as u32],
                n_embd_head_k: vec![HD as u32, HD as u32],
                n_embd_head_v: vec![HD as u32, HD as u32],
                is_recr: vec![true, false],
                has_rope: vec![false, false],
                d_conv: D_CONV as i64,
                d_inner: D_INNER as i64,
                d_state: D_STATE as i64,
                n_ssm_head: N_SSM_HEAD as i64,
                n_group: N_GROUP as i64,
                f_logit_scale: 0.0,
                f_residual_scale: 0.0,
                f_embedding_scale: 0.0,
                f_attention_scale: 0.0,
                n_expert: 0,
                n_expert_used: vec![0, 0],
                n_ff_shexp: 0,
                expert_weights_scale: 0.0,
                n_embd_r: N_EMBD_R as u32,
                n_embd_s: N_EMBD_S as u32,
            };
            let w = GraniteModelWeights {
                tok_embd,
                output_norm,
                output,
                layers: vec![
                    GraniteLayerWeights {
                        attn_norm: l0_attn_norm,
                        ssm_in: Some(l0_ssm_in),
                        ssm_conv1d: Some(l0_conv),
                        ssm_conv1d_b: Some(l0_conv_b),
                        ssm_dt_b: Some(l0_dt_b),
                        ssm_a: Some(l0_a),
                        ssm_d: Some(l0_d),
                        ssm_norm: Some(l0_ssm_norm),
                        ssm_out: Some(l0_ssm_out),
                        wq: None,
                        wk: None,
                        wv: None,
                        wo: None,
                        wo_b: None,
                        rope_freqs: None,
                        ffn_norm: l0_ffn_norm,
                        ffn_gate: Some(l0_gate),
                        ffn_down: Some(l0_down),
                        ffn_up: Some(l0_up),
                        ffn_gate_b: None,
                        ffn_down_b: None,
                        ffn_up_b: None,
                        ffn_gate_inp: None,
                        ffn_gate_exps: None,
                        ffn_down_exps: None,
                        ffn_up_exps: None,
                        ffn_gate_shexp: None,
                        ffn_down_shexp: None,
                        ffn_up_shexp: None,
                    },
                    GraniteLayerWeights {
                        attn_norm: l1_attn_norm,
                        ssm_in: None,
                        ssm_conv1d: None,
                        ssm_conv1d_b: None,
                        ssm_dt_b: None,
                        ssm_a: None,
                        ssm_d: None,
                        ssm_norm: None,
                        ssm_out: None,
                        wq: Some(l1_wq),
                        wk: Some(l1_wk),
                        wv: Some(l1_wv),
                        wo: Some(l1_wo),
                        wo_b: None,
                        rope_freqs: None,
                        ffn_norm: l1_ffn_norm,
                        ffn_gate: Some(l1_gate),
                        ffn_down: Some(l1_down),
                        ffn_up: Some(l1_up),
                        ffn_gate_b: None,
                        ffn_down_b: None,
                        ffn_up_b: None,
                        ffn_gate_inp: None,
                        ffn_gate_exps: None,
                        ffn_down_exps: None,
                        ffn_up_exps: None,
                        ffn_gate_shexp: None,
                        ffn_down_shexp: None,
                        ffn_up_shexp: None,
                    },
                ],
            };
            let ids = [
                tok_embd,
                output,
                output_norm,
                l0_attn_norm,
                l0_ssm_in,
                l0_conv,
                l0_conv_b,
                l0_dt_b,
                l0_a,
                l0_d,
                l0_ssm_norm,
                l0_ssm_out,
                l0_ffn_norm,
                l0_gate,
                l0_up,
                l0_down,
                l1_attn_norm,
                l1_wq,
                l1_wk,
                l1_wv,
                l1_wo,
                l1_ffn_norm,
                l1_gate,
                l1_up,
                l1_down,
            ];
            let snap: Vec<Vec<f32>> = ids
                .iter()
                .map(|&id| {
                    gctx.data_bytes(id)
                        .unwrap()
                        .chunks_exact(4)
                        .map(|c| f32::from_le_bytes(c.try_into().unwrap()))
                        .collect()
                })
                .collect();
            let dctx =
                DecodeContext::new_with(gctx, ForwardWeights::Granite(w, p), attn, 64, 8, 16);
            (dctx, snap)
        }

        let ids = [3i32, 7, 1, 15];

        // ---- (a) one prefill batch of 4 tokens
        let (mut dctx, snap) = build_toy();
        let got = dctx.decode(&ids, &[0, 1, 2, 3]).unwrap().to_vec();
        let mut ns = NaiveState::new();
        let mut want = Vec::new();
        for &t in &ids {
            want = naive_step(&snap, &mut ns, t);
        }
        let e = got
            .iter()
            .zip(&want)
            .map(|(a, b)| (a - b).abs())
            .fold(0f32, f32::max);
        println!("toy granite batch: max abs err {e:.3e}");
        assert!(e < 1e-4, "toy granite batch mismatch: {e:.3e}");

        // per-row check of the same batch (decode_all): every row must match the
        // naive prefix, not just the last one
        {
            let (mut dctx_all, snap_all) = build_toy();
            let all = dctx_all.decode_all(&ids, &[0, 1, 2, 3]).unwrap();
            let nv = dctx_all.n_vocab();
            let mut ns_all = NaiveState::new();
            for (r, &t) in ids.iter().enumerate() {
                let w = naive_step(&snap_all, &mut ns_all, t);
                let row = &all[r * nv..(r + 1) * nv];
                let er = row
                    .iter()
                    .zip(&w)
                    .map(|(a, b)| (a - b).abs())
                    .fold(0f32, f32::max);
                println!("toy granite batch row{r}: max abs err {er:.3e}");
                assert!(er < 1e-4, "toy granite batch row {r} mismatch: {er:.3e}");
            }
        }

        // ---- (b) the same tokens fed one by one (recurrent state + kv reuse)
        let (mut dctx1, snap1) = build_toy();
        let mut ns1 = NaiveState::new();
        let mut cur = Vec::new();
        for (i, &t) in ids.iter().enumerate() {
            cur = dctx1.decode(&[t], &[i as i32]).unwrap().to_vec();
            let want = naive_step(&snap1, &mut ns1, t);
            let e = cur
                .iter()
                .zip(&want)
                .map(|(a, b)| (a - b).abs())
                .fold(0f32, f32::max);
            assert!(e < 1e-4, "toy granite step {i} mismatch: {e:.3e}");
        }
        println!("toy granite step-by-step: max abs err (last step) ok");

        // ---- (c) two more steps: the state must carry over
        let mut naive_last = cur.clone();
        for (k, &t) in [9i32, 2].iter().enumerate() {
            let p2 = (ids.len() + k) as i32;
            let got = dctx1.decode(&[t], &[p2]).unwrap().to_vec();
            let want = naive_step(&snap1, &mut ns1, t);
            let e = got
                .iter()
                .zip(&want)
                .map(|(a, b)| (a - b).abs())
                .fold(0f32, f32::max);
            println!("toy granite extra step {k}: max abs err {e:.3e}");
            assert!(e < 1e-4, "toy granite extra step {k} mismatch: {e:.3e}");
            naive_last = want;
        }
        assert_eq!(naive_last.len(), N_VOCAB);
        assert_eq!(dctx1.kv.used_cells(), 6);
    }

    fn toy_gpt_oss_matches_naive() {
        use ggml::compute::graph_compute;

        let n_embd = 32usize;
        let n_head = 4usize;
        let n_head_kv = 2usize;
        let nd = 8usize; // head_dim == n_rot
        let n_ff = 16usize; // expert FFN width
        let n_expert = 6usize;
        let k_used = 2usize;
        let n_vocab = 20usize;
        let n_layer = 2usize;
        let eps = 1e-6f32;
        let alpha = 1.702f32;
        let limit = 7.0f32;

        let mut gctx = Context::new();
        let mut rng_state = 4242u32;
        let mut rnd = move || {
            rng_state = rng_state.wrapping_mul(1103515245).wrapping_add(12345);
            ((rng_state >> 8) as f32 / 16777216.0) * 0.2 - 0.1
        };
        let mut mk = |g: &mut Context, ne: &[i64]| -> TensorId {
            let id = match ne.len() {
                1 => g.new_tensor_1d(GgmlType::F32, ne[0]),
                2 => g.new_tensor_2d(GgmlType::F32, ne[0], ne[1]),
                3 => g.new_tensor_3d(GgmlType::F32, ne[0], ne[1], ne[2]),
                _ => unreachable!(),
            };
            g.arena_resize_tensor(id);
            let n: i64 = ne.iter().product();
            g.with_f32_mut(id, |p| {
                for v in p.iter_mut().take(n as usize) {
                    *v = rnd();
                }
            })
            .unwrap();
            id
        };
        let f32s = |g: &Context, id: TensorId| -> Vec<f32> {
            g.data_bytes(id)
                .unwrap()
                .chunks_exact(4)
                .map(|c| f32::from_le_bytes(c.try_into().unwrap()))
                .collect()
        };

        let tok_embd = mk(&mut gctx, &[n_embd as i64, n_vocab as i64]);
        let output = mk(&mut gctx, &[n_embd as i64, n_vocab as i64]);
        let output_norm = mk(&mut gctx, &[n_embd as i64]);
        let mut lw = Vec::new();
        for _ in 0..n_layer {
            lw.push(GptOssLayerWeights {
                attn_norm: mk(&mut gctx, &[n_embd as i64]),
                attn_post_norm: mk(&mut gctx, &[n_embd as i64]),
                wq: mk(&mut gctx, &[n_embd as i64, (nd * n_head) as i64]),
                wk: mk(&mut gctx, &[n_embd as i64, (nd * n_head_kv) as i64]),
                wv: mk(&mut gctx, &[n_embd as i64, (nd * n_head_kv) as i64]),
                // Some biases exercise the gpt-oss q/k/v bias path (the real
                // GGUFs carry attn_q/attn_v biases)
                wq_b: Some(mk(&mut gctx, &[(nd * n_head) as i64])),
                wk_b: Some(mk(&mut gctx, &[(nd * n_head_kv) as i64])),
                wv_b: Some(mk(&mut gctx, &[(nd * n_head_kv) as i64])),
                wo: mk(&mut gctx, &[(nd * n_head) as i64, n_embd as i64]),
                wo_b: mk(&mut gctx, &[n_embd as i64]),
                attn_sinks: mk(&mut gctx, &[n_head as i64]),
                ffn_gate_inp: {
                    // widen the router margins: with tiny random weights the
                    // top-k choice sits within the attention-path rounding band
                    // and a flip would mask real graph errors (discrete argmax)
                    let id = mk(&mut gctx, &[n_embd as i64, n_expert as i64]);
                    gctx.with_f32_mut(id, |p| {
                        for v in p.iter_mut() {
                            *v *= 8.0;
                        }
                    })
                    .unwrap();
                    id
                },
                ffn_gate_inp_b: mk(&mut gctx, &[n_expert as i64]),
                ffn_up_exps: mk(&mut gctx, &[n_embd as i64, n_ff as i64, n_expert as i64]),
                ffn_up_exps_b: mk(&mut gctx, &[n_ff as i64, n_expert as i64]),
                ffn_gate_exps: mk(&mut gctx, &[n_embd as i64, n_ff as i64, n_expert as i64]),
                ffn_gate_exps_b: mk(&mut gctx, &[n_ff as i64, n_expert as i64]),
                ffn_down_exps: mk(&mut gctx, &[n_ff as i64, n_embd as i64, n_expert as i64]),
                ffn_down_exps_b: mk(&mut gctx, &[n_embd as i64, n_expert as i64]),
            });
        }
        let w = GptOssModelWeights {
            tok_embd,
            output_norm,
            output,
            output_b: None,
            layers: lw.clone(),
        };
        let attn = AttnParams {
            n_head: n_head as i64,
            n_head_kv: n_head_kv as i64,
            n_embd_head_k: nd as i64,
            n_embd_head_v: nd as i64,
            n_rot: nd as i64,
            rope_mode: 2, // NEOX
            n_ctx_orig: 4096,
            freq_base: 150000.0,
            freq_scale: 1.0 / 32.0,
            ext_factor: 0.0,
            attn_factor: 1.0,
            beta_fast: 32.0,
            beta_slow: 1.0,
            norm_eps: eps,
            use_flash_attn: false,
        };
        let gp = GptOssParams {
            n_expert: n_expert as i64,
            n_expert_used: vec![k_used as u32; n_layer],
            swiglu_oai_alpha: alpha,
            swiglu_oai_limit: limit,
            expert_weights_scale: 1.0,
            is_swa: vec![false; n_layer],
            rope_freq_base_swa: 150000.0,
            rope_freq_scale_swa: 1.0 / 32.0,
        };

        // ---- snapshot weights for the naive reference -----------------
        struct Ws {
            tok_embd: Vec<f32>,
            output: Vec<f32>,
            output_norm: Vec<f32>,
            layers: Vec<[Vec<f32>; 18]>,
        }
        let ws = Ws {
            tok_embd: f32s(&gctx, tok_embd),
            output: f32s(&gctx, output),
            output_norm: f32s(&gctx, output_norm),
            layers: lw
                .iter()
                .map(|l| {
                    [
                        f32s(&gctx, l.attn_norm),
                        f32s(&gctx, l.attn_post_norm),
                        f32s(&gctx, l.wq),
                        f32s(&gctx, l.wk),
                        f32s(&gctx, l.wv),
                        f32s(&gctx, l.wo),
                        f32s(&gctx, l.wo_b),
                        f32s(&gctx, l.attn_sinks),
                        f32s(&gctx, l.ffn_gate_inp),
                        f32s(&gctx, l.ffn_gate_inp_b),
                        f32s(&gctx, l.ffn_up_exps),
                        f32s(&gctx, l.ffn_up_exps_b),
                        f32s(&gctx, l.ffn_gate_exps),
                        f32s(&gctx, l.ffn_gate_exps_b),
                        f32s(&gctx, l.ffn_down_exps),
                        f32s(&gctx, l.wq_b.unwrap()),
                        f32s(&gctx, l.wk_b.unwrap()),
                        f32s(&gctx, l.wv_b.unwrap()),
                    ]
                })
                .collect(),
        };
        let down_b: Vec<Vec<f32>> = lw.iter().map(|l| f32s(&gctx, l.ffn_down_exps_b)).collect();

        // ---- naive full forward: last-token logits --------------------
        let dot = |wv: &[f32], x: &[f32], n0: usize| -> Vec<f32> {
            let n1 = wv.len() / n0;
            (0..n1)
                .map(|j| (0..n0).map(|i| wv[i + j * n0] * x[i]).sum::<f32>())
                .collect()
        };
        let rms = |x: &[f32], wv: &[f32]| -> Vec<f32> {
            let sum: f32 = x.iter().map(|v| v * v).sum();
            let sc = 1.0 / (sum / x.len() as f32 + eps).sqrt();
            x.iter().zip(wv).map(|(v, wv)| v * sc * wv).collect()
        };
        let naive = |toks: &[i32]| -> Vec<f32> {
            let mut x: Vec<Vec<f32>> = toks
                .iter()
                .map(|&t| ws.tok_embd[t as usize * n_embd..][..n_embd].to_vec())
                .collect();
            for li in 0..n_layer {
                let l = &ws.layers[li];
                let (wq, wk, wv, wo) = (&l[2], &l[3], &l[4], &l[5]);
                let _ = (wq, wk, wv, wo);
                // attention
                let mut qs = Vec::new();
                let mut ks = Vec::new();
                let mut vs = Vec::new();
                for (t, xt) in x.iter().enumerate() {
                    let xn = rms(xt, &l[0]);
                    let mut q = dot(wq, &xn, n_embd);
                    let mut k = dot(wk, &xn, n_embd);
                    let mut v = dot(wv, &xn, n_embd);
                    for (x, b) in q.iter_mut().zip(&l[15]) {
                        *x += b;
                    }
                    for (x, b) in k.iter_mut().zip(&l[16]) {
                        *x += b;
                    }
                    for (x, b) in v.iter_mut().zip(&l[17]) {
                        *x += b;
                    }
                    let mut rope = |buf: &mut Vec<f32>, heads: usize| {
                        for h in 0..heads {
                            let b = h * nd;
                            for i in 0..nd / 2 {
                                let fi = 1.0f32 / 150000.0f32.powf(2.0 * i as f32 / nd as f32);
                                let th = t as f32 * (1.0 / 32.0) * fi;
                                let (c, s2) = (th.cos(), th.sin());
                                let x0 = buf[b + i];
                                let x1 = buf[b + i + nd / 2];
                                buf[b + i] = x0 * c - x1 * s2;
                                buf[b + i + nd / 2] = x0 * s2 + x1 * c;
                            }
                        }
                    };
                    rope(&mut q, n_head);
                    rope(&mut k, n_head_kv);
                    qs.push(q);
                    ks.push(k);
                    vs.push(v);
                }
                let scale = 1.0 / (nd as f32).sqrt();
                let mut attn_out = Vec::new();
                for (t, xt) in x.iter().enumerate() {
                    let mut acc = vec![0f32; nd * n_head];
                    for h in 0..n_head {
                        let kvh = h / (n_head / n_head_kv);
                        // node: softmax with the attention sink in max + sum
                        let mut lg = Vec::new();
                        for s2 in 0..=t {
                            let d: f32 = (0..nd)
                                .map(|i| ks[s2][kvh * nd + i] * qs[t][h * nd + i])
                                .sum();
                            lg.push(d * scale);
                        }
                        let sk = l[7][h];
                        let max = lg.iter().cloned().fold(f32::NEG_INFINITY, f32::max).max(sk);
                        let mut sum: f64 = lg.iter().map(|v| ((v - max).exp()) as f64).sum();
                        sum += (sk - max).exp() as f64;
                        for i in 0..nd {
                            let mut o = 0f32;
                            for (s2, v) in lg.iter().enumerate() {
                                o += ((v - max).exp() as f64 / sum) as f32 * vs[s2][kvh * nd + i];
                            }
                            acc[h * nd + i] = o;
                        }
                    }
                    let a = dot(wo, &acc, nd * n_head);
                    let res: Vec<f32> = xt.iter().zip(&a).map(|(p, q)| p + q).collect();
                    attn_out.push(
                        res.iter()
                            .zip(&l[6])
                            .map(|(p, b)| p + b)
                            .collect::<Vec<f32>>(),
                    );
                }
                // attn residual + post norm + MoE
                let mut outs = Vec::new();
                for (t, _xt) in x.iter().enumerate() {
                    // attn_out[t] already carries the attention residual +
                    // wo_b (`inpSA + attn + wo_b`), verify against openai-moe.cpp:115-122
                    let res: Vec<f32> = attn_out[t].clone();
                    let xn = rms(&res, &l[1]);
                    // router: raw logits -> top-k -> softmax over the k
                    let mut logits = dot(&l[8], &xn, n_embd);
                    for (e, b) in l[9].iter().enumerate() {
                        logits[e] += b;
                    }
                    let mut order: Vec<usize> = (0..n_expert).collect();
                    order.sort_by(|&a, &b| logits[b].total_cmp(&logits[a]).then(a.cmp(&b)));
                    let sel = &order[..k_used];
                    let mx = sel
                        .iter()
                        .map(|&e| logits[e])
                        .fold(f32::NEG_INFINITY, f32::max);
                    let exps: Vec<f64> =
                        sel.iter().map(|&e| (logits[e] - mx).exp() as f64).collect();
                    let ssum: f64 = exps.iter().sum();
                    let mut moe = vec![0f32; n_embd];
                    for (slot, &e) in sel.iter().enumerate() {
                        let wgt = (exps[slot] / ssum) as f32;
                        let gate: Vec<f32> = (0..n_ff)
                            .map(|r| {
                                let row = &l[12][r * n_embd + e * n_ff * n_embd..][..n_embd];
                                row.iter().zip(&xn).map(|(a, b)| a * b).sum::<f32>()
                                    + l[13][r + e * n_ff]
                            })
                            .collect();
                        let up: Vec<f32> = (0..n_ff)
                            .map(|r| {
                                let row = &l[10][r * n_embd + e * n_ff * n_embd..][..n_embd];
                                row.iter().zip(&xn).map(|(a, b)| a * b).sum::<f32>()
                                    + l[11][r + e * n_ff]
                            })
                            .collect();
                        let act: Vec<f32> = (0..n_ff)
                            .map(|r| {
                                let g = gate[r].min(limit);
                                let u = up[r].clamp(-limit, limit);
                                g / (1.0 + (alpha * (-g)).exp()) * (u + 1.0)
                            })
                            .collect();
                        for c in 0..n_embd {
                            let row = &l[14][c * n_ff + e * n_ff * n_embd..][..n_ff];
                            let d: f32 = row.iter().zip(&act).map(|(a, b)| a * b).sum::<f32>()
                                + down_b[li][c + e * n_embd];
                            moe[c] += d * wgt;
                        }
                    }
                    outs.push(
                        res.iter()
                            .zip(&moe)
                            .map(|(a, b)| a + b)
                            .collect::<Vec<f32>>(),
                    );
                }
                x = outs;
            }
            let last = x.last().unwrap();
            dot(&ws.output, &rms(last, &ws.output_norm), n_embd)
        };

        // ---- graph decode (mirrors the RealHarness protocol) ----------
        let size = 32u32;
        let mut kv = KvCache::new(
            &mut gctx,
            n_layer,
            (nd * n_head_kv) as i64,
            (nd * n_head_kv) as i64,
            size,
        );
        let watermark = gctx.mark();
        let mut decode = |tokens: &[i32], pos: &[i32]| -> (Vec<f32>, usize) {
            let n = tokens.len();
            let sinfo = kv.find_slot(n as u32).expect("kv full");
            // assign first, then the (256-padded) n_kv — step_inputs order
            kv.assign(sinfo, pos, 0);
            let n_kv = kv.n_kv();
            gctx.reset_graph_to(watermark);
            let tokens_t = gctx.new_tensor_1d(GgmlType::I32, n as i64);
            let pos_t = gctx.new_tensor_1d(GgmlType::I32, n as i64);
            let kq_mask = gctx.new_tensor_2d(GgmlType::F32, n_kv as i64, n as i64);
            let row_idx = gctx.new_tensor_1d(GgmlType::I64, n as i64);
            for tid in [tokens_t, pos_t, kq_mask, row_idx] {
                gctx.arena_resize_tensor(tid);
            }
            gctx.with_i32_mut(tokens_t, |p| p.copy_from_slice(tokens))
                .unwrap();
            gctx.with_i32_mut(pos_t, |p| p.copy_from_slice(pos))
                .unwrap();
            {
                let idxs: Vec<i64> = (sinfo.s0 as i64..=sinfo.s1 as i64).collect();
                gctx.data_bytes_mut(row_idx)
                    .unwrap()
                    .copy_from_slice(bytemuck::cast_slice(&idxs));
            }
            {
                let mask: &mut [f32] =
                    bytemuck::cast_slice_mut(gctx.data_bytes_mut(kq_mask).unwrap());
                mask.fill(f32::NEG_INFINITY);
                // empty (padded) cells keep pos = -1 → stay masked below
                let kv_pos: Vec<i32> = kv.cells[..n_kv as usize].iter().map(|c| c.pos).collect();
                for (iq, &qp) in pos.iter().enumerate() {
                    for (ik, &kp) in kv_pos.iter().enumerate() {
                        if 0 <= kp && kp <= qp {
                            mask[iq * n_kv as usize + ik] = 0.0;
                        }
                    }
                }
            }
            let inputs = DecodeInputs {
                tokens: tokens_t,
                pos: pos_t,
                kq_mask,
                row_idx,
                out_ids: None,
            };
            let res =
                build_gpt_oss_forward(&mut gctx, &w, &attn, &gp, &kv, &inputs, sinfo, n_kv, n);
            let logits = res.logits;
            let mut gf = res.graph;
            let n_softmax_with_sinks = gf
                .nodes
                .iter()
                .filter(|&&id| {
                    gctx.op(id) == ggml::tensor::GgmlOp::SoftMax && gctx.src(id)[2].is_some()
                })
                .count();
            let n_mul_mat_id = gf
                .nodes
                .iter()
                .filter(|&&id| gctx.op(id) == ggml::tensor::GgmlOp::MulMatId)
                .count();
            let n_add_id = gf
                .nodes
                .iter()
                .filter(|&&id| gctx.op(id) == ggml::tensor::GgmlOp::AddId)
                .count();
            let n_glu = gf
                .nodes
                .iter()
                .filter(|&&id| gctx.op(id) == ggml::tensor::GgmlOp::Glu)
                .count();
            assert_eq!(n_mul_mat_id, 3 * n_layer, "3 mul_mat_id per MoE layer");
            assert_eq!(n_add_id, 3 * n_layer, "gate/up/down expert biases");
            assert_eq!(n_glu, n_layer, "one swiglu_oai per layer");
            assert_eq!(
                n_softmax_with_sinks, n_layer,
                "one softmax per layer must carry the attention sink (src[2])"
            );
            graph_compute(&mut gctx, &mut gf, 4);
            // (assign already happened before the graph build, step_inputs order)
            let n_vocab = gctx.ne(logits)[0] as usize;
            let all: Vec<f32> = gctx
                .data_bytes(logits)
                .unwrap()
                .chunks_exact(4)
                .map(|c| f32::from_le_bytes(c.try_into().unwrap()))
                .collect();
            (all[n_vocab * (n - 1)..n_vocab * n].to_vec(), n_mul_mat_id)
        };

        let ids = [3i32, 5, 7];
        let (got, n_mmi) = decode(&ids, &[0, 1, 2]);
        assert!(n_mmi > 0);
        let want = naive(&ids);
        let rel = got
            .iter()
            .zip(&want)
            .map(|(a, b)| (a - b).abs() / b.abs().max(1e-3))
            .fold(0f32, f32::max);
        println!("toy gpt-oss prefill: max rel err {rel:.3e}");
        println!("got ={got:?}");
        println!("want={want:?}");
        assert!(rel < 2e-2, "toy gpt-oss prefill diverged: {rel:.4}");
        let argmax = |v: &[f32]| {
            v.iter()
                .enumerate()
                .max_by(|a, b| a.1.total_cmp(b.1))
                .unwrap()
                .0 as i32
        };
        assert_eq!(argmax(&got), argmax(&want), "argmax mismatch");

        // two greedy steps: graph (cached) vs naive full recompute
        let mut all: Vec<i32> = ids.to_vec();
        let mut cur = got;
        for p in 3..5 {
            let tok = argmax(&cur);
            all.push(tok);
            let naive_lg = naive(&all);
            let (got_lg, _) = decode(&[tok], &[p]);
            let rel = got_lg
                .iter()
                .zip(&naive_lg)
                .map(|(a, b)| (a - b).abs() / b.abs().max(1e-3))
                .fold(0f32, f32::max);
            println!("toy gpt-oss decode pos={p}: max rel err {rel:.3e}");
            assert!(rel < 5e-2, "toy gpt-oss decode pos {p} diverged: {rel:.4}");
            cur = got_lg;
        }
        assert_eq!(kv.used_cells(), 5);
    }
    // ======================================================================
    // gemma4 / qwen35 toys — full DecodeContext (real dispatch path)
    // ======================================================================

    /// Simple causal attention over the *f16* KV cache with a per-layer
    /// geometry, kq scale 1.0 and q pre-scale 1.0 (gemma4). `vs` may be
    /// pre-normed V rows (the V=K layers norm V without a weight).
    #[allow(clippy::too_many_arguments)]
    fn gemma4_attn_naive(
        qs: &[Vec<f32>],
        ks: &[Vec<f32>],
        vs: &[Vec<f32>],
        t: usize,
        n_head: usize,
        n_head_kv: usize,
        hd: usize,
    ) -> Vec<f32> {
        let mut acc = vec![0f32; hd * n_head];
        for h in 0..n_head {
            let kvh = h / (n_head / n_head_kv);
            let mut sw = Vec::new();
            for s in 0..=t {
                let mut d = 0f32;
                for i in 0..hd {
                    d += ks[s][kvh * hd + i] * f16q(qs[t][h * hd + i]);
                }
                // gemma4: kq_scale = f_attention_scale = 1.0
                sw.push(ggml::ops::ggml_expf(d));
            }
            let sum: f32 = sw.iter().sum();
            for i in 0..hd {
                let mut o = 0f32;
                for (s, w) in sw.iter().enumerate() {
                    o += f16q(w / sum) * vs[s][kvh * hd + i];
                }
                acc[h * hd + i] = o;
            }
        }
        acc
    }

    /// Toy gemma4: 2 layers — layer 0 is an SWA layer (hd 16, 8 kv heads scaled
    /// down to 2) and layer 1 a full-attention layer (hd 32, 1 kv head) that
    /// also has no `wv` (V = K, like blk.5 of the real 12B file) — plus
    /// per-layer `rope_freqs`, `layer_output_scale`, GELU-parallel FFN and the
    /// final logit softcap. Checked against a naive full forward (f16 KV cache
    /// modelled exactly).
    #[test]
    fn toy_gemma4_matches_naive() {
        use crate::context::{DecodeContext, ForwardWeights};

        let n_embd = 64usize;
        let n_head = 4usize;
        let n_vocab = 40usize;
        let n_ff = 96usize;
        let eps = 1e-6f32;
        // per layer: (is_swa, hd, n_head_kv, n_rot, freq_base)
        let geo = [
            (true, 16usize, 2usize, 16i32, 10000f32),
            (false, 32usize, 1usize, 32i32, 1000000f32),
        ];
        let softcap = 30.0f32;

        let mut gctx = Context::new();
        let mut rng = Rng(4242);
        let mut mk = |g: &mut Context, rng: &mut Rng, n0: i64, n1: i64| -> TensorId {
            let id = g.new_tensor_2d(GgmlType::F32, n0, n1);
            g.arena_resize_tensor(id);
            g.with_f32_mut(id, |p| {
                for v in p.iter_mut() {
                    *v = rng.next();
                }
            })
            .unwrap();
            id
        };
        let f32s = |g: &Context, id: TensorId| -> Vec<f32> {
            g.data_bytes(id)
                .unwrap()
                .chunks_exact(4)
                .map(|c| f32::from_le_bytes(c.try_into().unwrap()))
                .collect()
        };

        let tok_embd = mk(&mut gctx, &mut rng, n_embd as i64, n_vocab as i64);
        let output = mk(&mut gctx, &mut rng, n_embd as i64, n_vocab as i64);
        let output_norm = mk(&mut gctx, &mut rng, n_embd as i64, 1);
        // one shared rope_freqs (the real file stores a single global tensor)
        let rope_freqs = mk(&mut gctx, &mut rng, geo[1].3 as i64 / 2, 1);

        let mut layers = Vec::new();
        let mut ws = Vec::new();
        for (li, &(is_swa, hd, kvh, n_rot, _)) in geo.iter().enumerate() {
            let _ = is_swa;
            let an = mk(&mut gctx, &mut rng, n_embd as i64, 1);
            let apn = mk(&mut gctx, &mut rng, n_embd as i64, 1);
            let qn = mk(&mut gctx, &mut rng, hd as i64, 1);
            let kn = mk(&mut gctx, &mut rng, hd as i64, 1);
            let wq = mk(&mut gctx, &mut rng, n_embd as i64, (hd * n_head) as i64);
            let wk = mk(&mut gctx, &mut rng, n_embd as i64, (hd * kvh) as i64);
            let wv = if li == 0 {
                Some(mk(&mut gctx, &mut rng, n_embd as i64, (hd * kvh) as i64))
            } else {
                None
            };
            let wo = mk(&mut gctx, &mut rng, (hd * n_head) as i64, n_embd as i64);
            let out_scale = mk(&mut gctx, &mut rng, 1, 1);
            let ffn_norm = mk(&mut gctx, &mut rng, n_embd as i64, 1);
            let ffn_post_norm = mk(&mut gctx, &mut rng, n_embd as i64, 1);
            let ffn_gate = mk(&mut gctx, &mut rng, n_embd as i64, n_ff as i64);
            let ffn_up = mk(&mut gctx, &mut rng, n_embd as i64, n_ff as i64);
            let ffn_down = mk(&mut gctx, &mut rng, n_ff as i64, n_embd as i64);
            layers.push(Gemma4LayerWeights {
                attn_norm: an,
                attn_post_norm: apn,
                attn_q_norm: qn,
                attn_k_norm: Some(kn),
                wqkv: None,
                wq: Some(wq),
                wk: Some(wk),
                wv,
                wo,
                rope_freqs: if is_swa { None } else { Some(rope_freqs) },
                out_scale: Some(out_scale),
                ffn_norm,
                ffn_gate,
                ffn_up,
                ffn_down,
                ffn_post_norm,
                ffn_gate_inp: None,
                ffn_gate_inp_s: None,
                ffn_pre_norm_2: None,
                ffn_post_norm_1: None,
                ffn_post_norm_2: None,
                ffn_gate_up_exps: None,
                ffn_gate_exps: None,
                ffn_up_exps: None,
                ffn_down_exps: None,
                ffn_down_exps_s: None,
                per_layer_inp_gate: None,
                per_layer_proj: None,
                per_layer_post_norm: None,
            });
            ws.push((
                an,
                apn,
                qn,
                kn,
                wq,
                wk,
                wv,
                wo,
                out_scale,
                ffn_norm,
                ffn_post_norm,
                ffn_gate,
                ffn_up,
                ffn_down,
            ));
        }

        let params = Gemma4Params {
            attn: AttnParams {
                n_head: n_head as i64,
                n_head_kv: geo[0].2 as i64,
                n_embd_head_k: geo[0].1 as i64,
                n_embd_head_v: geo[0].1 as i64,
                n_rot: geo[0].3 as i64,
                rope_mode: 2, // NEOX
                n_ctx_orig: 512,
                freq_base: geo[1].4,
                freq_scale: 1.0,
                ext_factor: 0.0,
                attn_factor: 1.0,
                beta_fast: 32.0,
                beta_slow: 1.0,
                norm_eps: eps,
                use_flash_attn: false,
            },
            n_embd: n_embd as i64,
            n_head: vec![n_head as u32; 2],
            n_head_kv: geo.iter().map(|g| g.2 as u32).collect(),
            n_embd_head_k: geo.iter().map(|g| g.1 as u32).collect(),
            n_embd_head_v: geo.iter().map(|g| g.1 as u32).collect(),
            n_rot: geo.iter().map(|g| g.3 as u32).collect(),
            is_swa: geo.iter().map(|g| g.0).collect(),
            rope_freq_base_swa: geo[0].4,
            rope_freq_scale_swa: 1.0,
            f_attention_scale: 1.0,
            f_final_logit_softcapping: softcap,
            n_embd_per_layer: 0,
            n_expert: 0,
            n_expert_used: vec![0; 2],
            n_ff_exp: vec![0; 2],
        };
        let gwe = Gemma4ModelWeights {
            tok_embd,
            output_norm,
            output,
            per_layer_tok_embd: None,
            per_layer_model_proj: None,
            per_layer_proj_norm: None,
            layers,
        };

        // kv rows per layer: hd * kvh
        let attn = params.attn;
        let mut dctx = DecodeContext::new_with(
            gctx,
            ForwardWeights::Gemma4(gwe, params.clone()),
            attn,
            64,
            1,
            16,
        );
        let ids = [5i32, 9, 32, 7];
        let got: Vec<f32> = dctx.decode(&ids, &[0, 1, 2, 3]).unwrap().to_vec();

        // ---- naive ----
        let mk1 = |v: Vec<f32>| v;
        let emb = f32s(&dctx.gctx, tok_embd);
        let o_norm = mk1(f32s(&dctx.gctx, output_norm));
        let o_w = f32s(&dctx.gctx, output);
        let rf = f32s(&dctx.gctx, rope_freqs);
        let sqrt_n = (n_embd as f32).sqrt();
        let mut x: Vec<Vec<f32>> = ids
            .iter()
            .map(|&tk| {
                emb[tk as usize * n_embd..][..n_embd]
                    .iter()
                    .map(|v| v * sqrt_n)
                    .collect()
            })
            .collect();

        for (li, &(is_swa, hd, kvh, n_rot, fbase)) in geo.iter().enumerate() {
            let (
                an,
                apn,
                qn,
                kn,
                wq,
                wk,
                wv,
                wo,
                out_scale,
                ffn_norm,
                ffn_post_norm,
                ffn_gate,
                ffn_up,
                ffn_down,
            ) = &ws[li];
            let an_v = f32s(&dctx.gctx, *an);
            let apn_v = f32s(&dctx.gctx, *apn);
            let qn_v = f32s(&dctx.gctx, *qn);
            let kn_v = f32s(&dctx.gctx, *kn);
            let wq_v = f32s(&dctx.gctx, *wq);
            let wk_v = f32s(&dctx.gctx, *wk);
            let wv_v = wv.map(|t| f32s(&dctx.gctx, t));
            let wo_v = f32s(&dctx.gctx, *wo);
            let os_v = f32s(&dctx.gctx, *out_scale);
            let fn_v = f32s(&dctx.gctx, *ffn_norm);
            let fpn_v = f32s(&dctx.gctx, *ffn_post_norm);
            let fg_v = f32s(&dctx.gctx, *ffn_gate);
            let fu_v = f32s(&dctx.gctx, *ffn_up);
            let fd_v = f32s(&dctx.gctx, *ffn_down);
            let attn_in = x.clone();

            let mut qs = Vec::new();
            let mut ks = Vec::new();
            let mut vs = Vec::new();
            for (ti, xt) in x.iter().enumerate() {
                let xn = rms(xt, &an_v, eps, false);
                let mut q = dot(&wq_v, &xn, n_embd);
                let mut k = dot(&wk_v, &xn, n_embd);
                let v_raw = wv_v
                    .as_ref()
                    .map(|w| dot(w, &xn, n_embd))
                    .unwrap_or_else(|| k.clone());
                // per-head weighted q/k rms norms
                for h in 0..n_head {
                    let seg = rms(&q[h * hd..(h + 1) * hd].to_vec(), &qn_v, eps, false);
                    q[h * hd..(h + 1) * hd].copy_from_slice(&seg);
                }
                for h in 0..kvh {
                    let seg = rms(&k[h * hd..(h + 1) * hd].to_vec(), &kn_v, eps, false);
                    k[h * hd..(h + 1) * hd].copy_from_slice(&seg);
                }
                // V: plain rms_norm (no weight) per head, from the raw projection
                let mut v = v_raw;
                for h in 0..kvh {
                    let seg = rms(
                        &v[h * hd..(h + 1) * hd].to_vec(),
                        &vec![1.0; hd],
                        eps,
                        false,
                    );
                    v[h * hd..(h + 1) * hd].copy_from_slice(&seg);
                }
                // rope: q/k only; full layers carry freq factors
                let ff: Vec<f32> = if is_swa {
                    vec![1.0; n_rot as usize / 2]
                } else {
                    rf.clone()
                };
                let rope = |buf: &mut Vec<f32>, heads: usize| {
                    for h in 0..heads {
                        let b = h * hd;
                        for j in 0..(n_rot as usize) / 2 {
                            let theta_scale = fbase.powf(-2.0 / n_rot as f32);
                            let mut theta = ti as f32;
                            for _ in 0..j {
                                theta *= theta_scale;
                            }
                            let theta = theta / ff[j];
                            let (c, s) = (theta.cos(), theta.sin());
                            let x0 = buf[b + j];
                            let x1 = buf[b + j + (n_rot as usize) / 2];
                            buf[b + j] = x0 * c - x1 * s;
                            buf[b + j + (n_rot as usize) / 2] = x0 * s + x1 * c;
                        }
                    }
                };
                rope(&mut q, n_head);
                rope(&mut k, kvh);
                f16rt(&mut k);
                f16rt(&mut v);
                qs.push(q);
                ks.push(k);
                vs.push(v);
            }

            let mut out = Vec::new();
            for ti in 0..x.len() {
                let acc = gemma4_attn_naive(&qs, &ks, &vs, ti, n_head, kvh, hd);
                let a = dot(&wo_v, &acc, hd * n_head);
                // attn_post_norm is applied to the attention output, then the
                // residual is added (gemma4.cpp:222-226)
                let a_norm = rms(&a, &apn_v, eps, false);
                let sa: Vec<f32> = attn_in[ti]
                    .iter()
                    .zip(&a_norm)
                    .map(|(p, q)| p + q)
                    .collect();
                // GELU-parallel FFN
                let xn = rms(&sa, &fn_v, eps, false);
                let g = dot(&fg_v, &xn, n_embd);
                let u = dot(&fu_v, &xn, n_embd);
                let mut act = vec![0f32; n_ff];
                for i in 0..n_ff {
                    act[i] = ggml::ops::ggml_vec_gelu_f32(g[i]) * u[i];
                }
                let ffn_out = dot(&fd_v, &act, n_ff);
                let t2 = rms(&ffn_out, &fpn_v, eps, false);
                let mut cur: Vec<f32> = t2.iter().zip(&sa).map(|(p, q)| p + q).collect();
                for v in cur.iter_mut() {
                    *v *= os_v[0];
                }
                out.push(cur);
            }
            x = out;
        }

        let last = &x[x.len() - 1];
        let xn = rms(last, &o_norm, eps, false);
        let mut want = dot(&o_w, &xn, n_embd);
        for v in want.iter_mut() {
            *v = (*v * (1.0 / softcap)).tanh() * softcap;
        }

        let rel = got
            .iter()
            .zip(&want)
            .map(|(a, b)| (a - b).abs() / b.abs().max(1e-2))
            .fold(0f32, f32::max);
        println!("toy gemma4: max rel err {rel:.4}");
        assert!(rel < 2e-2, "toy gemma4 mismatch: {rel:.4}");

        // one more decode step: the kv cache path must keep matching
        let mut all = ids.to_vec();
        let mut cur = got;
        for p in 4..6 {
            let tk = argmax(&cur);
            all.push(tk);
            let lg = dctx.decode(&[tk], &[p]).unwrap().to_vec();
            cur = lg;
        }
        assert_eq!(dctx.kv.used_cells(), 6);
    }

    /// Toy qwen35: 4 layers, 3 of them gated delta net and the last the full
    /// attention block (q-split + gate + IMROPE). Checked against a naive
    /// forward implementing the conv state, the per-token delta rule, the gated
    /// norm and the MRoPE sector walk.
    #[test]
    fn toy_qwen35_matches_naive() {
        use crate::context::{DecodeContext, ForwardWeights};

        let n_embd = 32usize;
        let n_head = 4usize;
        let n_head_kv = 2usize;
        let hd = 8usize;
        let n_rot = 8i32;
        let sections = [2i32, 2, 2, 0];
        let n_vocab = 30usize;
        let n_ff = 48usize;
        let eps = 1e-6f32;
        // gated delta net geometry
        let head_k_dim = 8usize;
        let n_group = 2usize; // k heads
        let num_v_heads = 4usize; // v heads (dt rank)
        let head_v_dim = 8usize;
        let d_inner = head_v_dim * num_v_heads; // 32
        let d_conv = 4usize;
        let conv_channels = d_inner + 2 * n_group * head_k_dim; // 64
        let qkv_dim = head_k_dim * n_group * 2 + head_v_dim * num_v_heads; // 64
        let value_dim = head_v_dim * num_v_heads; // 32
        let n_embd_s = head_v_dim * head_v_dim * num_v_heads; // 256
        let n_embd_r = (d_conv - 1) * conv_channels; // 192
        let n_layers = 4usize;
        // 3 gated delta net layers + 1 full-attention layer (full_attention_interval = 4)
        let is_recr: Vec<bool> = (0..n_layers).map(|il| (il + 1) % 4 != 0).collect();

        let mut gctx = Context::new();
        let mut rng = Rng(777);
        let mut mk = |g: &mut Context, rng: &mut Rng, n0: i64, n1: i64| -> TensorId {
            let id = g.new_tensor_2d(GgmlType::F32, n0, n1);
            g.arena_resize_tensor(id);
            g.with_f32_mut(id, |p| {
                for v in p.iter_mut() {
                    *v = rng.next();
                }
            })
            .unwrap();
            id
        };
        let f32s = |g: &Context, id: TensorId| -> Vec<f32> {
            g.data_bytes(id)
                .unwrap()
                .chunks_exact(4)
                .map(|c| f32::from_le_bytes(c.try_into().unwrap()))
                .collect()
        };

        let tok_embd = mk(&mut gctx, &mut rng, n_embd as i64, n_vocab as i64);
        let output = mk(&mut gctx, &mut rng, n_embd as i64, n_vocab as i64);
        let output_norm = mk(&mut gctx, &mut rng, n_embd as i64, 1);

        #[allow(clippy::type_complexity)]
        let mut recr_w: Vec<[TensorId; 10]> = Vec::new();
        let attn_w: Vec<()> = Vec::new();
        let mut layers = Vec::new();
        for il in 0..n_layers {
            let an = mk(&mut gctx, &mut rng, n_embd as i64, 1);
            let apn = mk(&mut gctx, &mut rng, n_embd as i64, 1);
            let ffn_gate = mk(&mut gctx, &mut rng, n_embd as i64, n_ff as i64);
            let ffn_up = mk(&mut gctx, &mut rng, n_embd as i64, n_ff as i64);
            let ffn_down = mk(&mut gctx, &mut rng, n_ff as i64, n_embd as i64);
            if is_recr[il] {
                let wqkv = mk(&mut gctx, &mut rng, n_embd as i64, qkv_dim as i64);
                let gate = mk(&mut gctx, &mut rng, n_embd as i64, value_dim as i64);
                let conv = mk(&mut gctx, &mut rng, d_conv as i64, conv_channels as i64);
                let dt_b = mk(&mut gctx, &mut rng, num_v_heads as i64, 1);
                let a = mk(&mut gctx, &mut rng, num_v_heads as i64, 1);
                let beta = mk(&mut gctx, &mut rng, n_embd as i64, num_v_heads as i64);
                let alpha = mk(&mut gctx, &mut rng, n_embd as i64, num_v_heads as i64);
                let norm = mk(&mut gctx, &mut rng, head_v_dim as i64, 1);
                let out = mk(&mut gctx, &mut rng, value_dim as i64, n_embd as i64);
                layers.push(Qwen35LayerWeights {
                    attn_norm: an,
                    attn_post_norm: apn,
                    wq: None,
                    wk: None,
                    wv: None,
                    wo: None,
                    attn_q_norm: None,
                    attn_k_norm: None,
                    wqkv: Some(wqkv),
                    wqkv_gate: Some(gate),
                    ssm_conv1d: Some(conv),
                    ssm_dt_b: Some(dt_b),
                    ssm_a: Some(a),
                    ssm_beta: Some(beta),
                    ssm_alpha: Some(alpha),
                    ssm_norm: Some(norm),
                    ssm_out: Some(out),
                    ffn_gate,
                    ffn_up,
                    ffn_down,
                });
                recr_w.push([an, apn, wqkv, gate, conv, dt_b, a, beta, alpha, out]);
            } else {
                let wq = mk(&mut gctx, &mut rng, n_embd as i64, (hd * n_head * 2) as i64);
                let wk = mk(&mut gctx, &mut rng, n_embd as i64, (hd * n_head_kv) as i64);
                let wv = mk(&mut gctx, &mut rng, n_embd as i64, (hd * n_head_kv) as i64);
                let wo = mk(&mut gctx, &mut rng, (hd * n_head) as i64, n_embd as i64);
                let qn = mk(&mut gctx, &mut rng, hd as i64, 1);
                let kn = mk(&mut gctx, &mut rng, hd as i64, 1);
                layers.push(Qwen35LayerWeights {
                    attn_norm: an,
                    attn_post_norm: apn,
                    wq: Some(wq),
                    wk: Some(wk),
                    wv: Some(wv),
                    wo: Some(wo),
                    attn_q_norm: Some(qn),
                    attn_k_norm: Some(kn),
                    wqkv: None,
                    wqkv_gate: None,
                    ssm_conv1d: None,
                    ssm_dt_b: None,
                    ssm_a: None,
                    ssm_beta: None,
                    ssm_alpha: None,
                    ssm_norm: None,
                    ssm_out: None,
                    ffn_gate,
                    ffn_up,
                    ffn_down,
                });
                let _ = attn_w;
            }
        }

        let params = Qwen35Params {
            attn: AttnParams {
                n_head: n_head as i64,
                n_head_kv: n_head_kv as i64,
                n_embd_head_k: hd as i64,
                n_embd_head_v: hd as i64,
                n_rot: n_rot as i64,
                rope_mode: ggml::ops::GGML_ROPE_TYPE_IMROPE,
                n_ctx_orig: 512,
                freq_base: 1000000.0,
                freq_scale: 1.0,
                ext_factor: 0.0,
                attn_factor: 1.0,
                beta_fast: 32.0,
                beta_slow: 1.0,
                norm_eps: eps,
                use_flash_attn: false,
            },
            n_embd: n_embd as i64,
            n_head: vec![n_head as u32; n_layers],
            n_head_kv: vec![n_head_kv as u32; n_layers],
            n_embd_head_k: vec![hd as u32; n_layers],
            n_embd_head_v: vec![hd as u32; n_layers],
            n_rot: vec![n_rot as u32; n_layers],
            is_recr: is_recr.clone(),
            rope_sections: sections,
            f_attention_scale: 0.0,
            ssm_d_conv: d_conv as i64,
            ssm_d_inner: d_inner as i64,
            ssm_d_state: head_k_dim as i64,
            ssm_dt_rank: num_v_heads as i64,
            ssm_n_group: n_group as i64,
            n_embd_r: n_embd_r as u32,
            n_embd_s: n_embd_s as u32,
        };
        let qw = Qwen35ModelWeights {
            tok_embd,
            output_norm,
            output,
            cls_out: None,
            cls_out_b: None,
            layers: layers.clone(),
        };

        let mut dctx = DecodeContext::new_with(
            gctx,
            ForwardWeights::Qwen35(qw, params.clone()),
            params.attn,
            64,
            1,
            16,
        );
        let ids = [5i32, 9, 22];
        let got: Vec<f32> = dctx.decode(&ids, &[0, 1, 2]).unwrap().to_vec();

        // ---- naive ----
        let emb = f32s(&dctx.gctx, tok_embd);
        let o_norm = f32s(&dctx.gctx, output_norm);
        let o_w = f32s(&dctx.gctx, output);
        let mut x: Vec<Vec<f32>> = ids
            .iter()
            .map(|&tk| emb[tk as usize * n_embd..][..n_embd].to_vec())
            .collect();

        // recurrent cells
        let mut conv_state = vec![0f32; n_embd_r];
        let mut ssm_state = vec![0f32; n_embd_s];
        let mut ri = 0usize;

        for (li, &is_r) in is_recr.iter().enumerate() {
            let lw = &layers[li];
            let an_v = f32s(&dctx.gctx, lw.attn_norm);
            let apn_v = f32s(&dctx.gctx, lw.attn_post_norm);
            let fg_v = f32s(&dctx.gctx, lw.ffn_gate);
            let fu_v = f32s(&dctx.gctx, lw.ffn_up);
            let fd_v = f32s(&dctx.gctx, lw.ffn_down);
            let inp_sa = x.clone();
            let xn: Vec<Vec<f32>> = x.iter().map(|t| rms(t, &an_v, eps, false)).collect();

            let mixer: Vec<Vec<f32>> = if is_r {
                let [_, _, wqkv, gate_w, conv_w, dt_b, a_w, beta_w, alpha_w, out_w] = recr_w[ri];
                let wqkv_v = f32s(&dctx.gctx, wqkv);
                let gate_v = f32s(&dctx.gctx, gate_w);
                let conv_v = f32s(&dctx.gctx, conv_w);
                let dt_b_v = f32s(&dctx.gctx, dt_b);
                let a_v = f32s(&dctx.gctx, a_w);
                let beta_v = f32s(&dctx.gctx, beta_w);
                let alpha_v = f32s(&dctx.gctx, alpha_w);
                let out_v = f32s(&dctx.gctx, out_w);
                ri += 1;
                // 1) projections
                let mut qkv_mixed: Vec<Vec<f32>> = Vec::new();
                let mut zs: Vec<Vec<f32>> = Vec::new();
                let mut betas = Vec::new();
                let mut gates = Vec::new();
                for t in 0..x.len() {
                    qkv_mixed.push(dot(&wqkv_v, &xn[t], n_embd));
                    zs.push(dot(&gate_v, &xn[t], n_embd));
                    let b = dot(&beta_v, &xn[t], n_embd);
                    let al = dot(&alpha_v, &xn[t], n_embd);
                    // sigmoid(beta), softplus(alpha + dt_b) * ssm_a
                    betas.push(
                        b.iter()
                            .map(|v| 1.0 / (1.0 + (-v).exp()))
                            .collect::<Vec<f32>>(),
                    );
                    gates.push(
                        al.iter()
                            .zip(&dt_b_v)
                            .zip(&a_v)
                            .map(|((&av, &db), &aa)| {
                                let sp = {
                                    let v = av + db;
                                    if v > 20.0 {
                                        v
                                    } else {
                                        (1.0 + v.exp()).ln()
                                    }
                                };
                                sp * aa
                            })
                            .collect::<Vec<f32>>(),
                    );
                }
                // 2) conv: prepend the state, run the causal conv, silu.
                // conv_input is [d_conv-1 + T, conv_channels] in ggml layout:
                // element (r, c) at r + c*(d_conv-1+T); rows < d_conv-1 come
                // from the state ([d_conv-1, conv_channels] → (i,c) at
                // i + c*(d_conv-1)), the rest from the transposed qkv_mixed
                // ((t, c) at t + c*T).
                let nrows = d_conv - 1 + x.len();
                let ci = |r: usize, c: usize| -> f32 {
                    if r < d_conv - 1 {
                        conv_state[r + c * (d_conv - 1)]
                    } else {
                        qkv_mixed[r - (d_conv - 1)][c]
                    }
                };
                // conv_out is [conv_channels, T]: element (c, t) at c + t*conv_channels
                let mut conv_out = vec![0f32; conv_channels * x.len()];
                for t in 0..x.len() {
                    for c in 0..conv_channels {
                        let mut acc = 0f32;
                        for k in 0..d_conv {
                            acc = ci(t + k, c).mul_add(conv_v[k + c * d_conv], acc);
                        }
                        conv_out[c + t * conv_channels] = acc;
                    }
                }
                // state cell = the last (d_conv-1) rows of conv_input
                let mut new_state = conv_state.clone();
                for i in 0..(d_conv - 1) {
                    for c in 0..conv_channels {
                        new_state[i + c * (d_conv - 1)] = ci(x.len() + i, c);
                    }
                }
                conv_state = new_state;
                let _ = nrows;
                for v in conv_out.iter_mut() {
                    *v = *v / (1.0 + (-*v).exp());
                }
                // 3) split q/k/v and l2-normalize q/k
                let l2 = |seg: &[f32]| -> Vec<f32> {
                    let n = seg.len() as f32;
                    let sum: f32 = seg.iter().map(|v| v * v).sum();
                    let sc = 1.0 / (sum / n + eps / n).sqrt() / n.sqrt();
                    seg.iter().map(|v| v * sc).collect()
                };
                let mut outs = Vec::new();
                // state as [hd_v, hd_v, n_v_heads] with S[i][j] at i + j*hd_v + h*...
                let mut st = ssm_state.clone();
                for t in 0..x.len() {
                    let row = &conv_out[t * conv_channels..(t + 1) * conv_channels];
                    let qs: Vec<Vec<f32>> = (0..n_group)
                        .map(|h| l2(&row[h * head_k_dim..(h + 1) * head_k_dim]))
                        .collect();
                    let ks: Vec<Vec<f32>> = (0..n_group)
                        .map(|h| l2(&row[head_k_dim * n_group + h * head_k_dim..][..head_k_dim]))
                        .collect();
                    let vs: Vec<Vec<f32>> = (0..num_v_heads)
                        .map(|h| {
                            row[2 * head_k_dim * n_group + h * head_v_dim..][..head_v_dim].to_vec()
                        })
                        .collect();
                    let mut o = vec![0f32; value_dim];
                    for hv in 0..num_v_heads {
                        let hk = hv % n_group;
                        let base = hv * head_v_dim * head_v_dim;
                        let g = gates[t][hv].exp();
                        for i in 0..head_v_dim * head_v_dim {
                            st[base + i] *= g;
                        }
                        let mut d = vec![0f32; head_v_dim];
                        for j in 0..head_v_dim {
                            let mut sum = 0f32;
                            for i in 0..head_k_dim {
                                sum += st[base + i + j * head_v_dim] * ks[hk][i];
                            }
                            d[j] = (vs[hv][j] - sum) * betas[t][hv];
                        }
                        for j in 0..head_v_dim {
                            for i in 0..head_k_dim {
                                st[base + i + j * head_v_dim] += ks[hk][i] * d[j];
                            }
                        }
                        let scale = 1.0 / (head_k_dim as f32).sqrt();
                        for j in 0..head_v_dim {
                            let mut sum = 0f32;
                            for i in 0..head_k_dim {
                                sum += st[base + i + j * head_v_dim] * qs[hk][i];
                            }
                            o[hv * head_v_dim + j] = sum * scale;
                        }
                    }
                    outs.push(o);
                }
                ssm_state = st;
                let _ = (gate_v, out_v);
                // 4) gated rms norm + output projection
                let norm_w = f32s(&dctx.gctx, lw.ssm_norm.unwrap());
                let out_w_v = f32s(&dctx.gctx, lw.ssm_out.unwrap());
                let mut res = Vec::new();
                for t in 0..x.len() {
                    let mut acc = vec![0f32; value_dim];
                    for hv in 0..num_v_heads {
                        let seg = &outs[t][hv * head_v_dim..(hv + 1) * head_v_dim];
                        let nrm = rms(seg, &norm_w, eps, false);
                        let gate_t = zs[t][hv * head_v_dim..(hv + 1) * head_v_dim]
                            .iter()
                            .map(|&v| v / (1.0 + (-v).exp()))
                            .collect::<Vec<f32>>();
                        for j in 0..head_v_dim {
                            acc[hv * head_v_dim + j] = nrm[j] * gate_t[j];
                        }
                    }
                    res.push(dot(&out_w_v, &acc, value_dim));
                }
                res
            } else {
                // full attention block
                let wq = f32s(&dctx.gctx, lw.wq.unwrap());
                let wk = f32s(&dctx.gctx, lw.wk.unwrap());
                let wv = f32s(&dctx.gctx, lw.wv.unwrap());
                let wo = f32s(&dctx.gctx, lw.wo.unwrap());
                let qn = f32s(&dctx.gctx, lw.attn_q_norm.unwrap());
                let kn = f32s(&dctx.gctx, lw.attn_k_norm.unwrap());
                let mut qs = Vec::new();
                let mut ks = Vec::new();
                let mut vs = Vec::new();
                let mut gates = Vec::new();
                for t in 0..x.len() {
                    let q_full = dot(&wq, &xn[t], n_embd); // [hd*2*n_head]
                    let mut q = Vec::new();
                    let mut gate = Vec::new();
                    for h in 0..n_head {
                        q.extend_from_slice(&q_full[h * hd * 2..h * hd * 2 + hd]);
                        gate.extend_from_slice(&q_full[h * hd * 2 + hd..(h + 1) * hd * 2]);
                    }
                    let mut k = dot(&wk, &xn[t], n_embd);
                    let mut v = dot(&wv, &xn[t], n_embd);
                    for h in 0..n_head {
                        let seg = rms(&q[h * hd..(h + 1) * hd].to_vec(), &qn, eps, false);
                        q[h * hd..(h + 1) * hd].copy_from_slice(&seg);
                    }
                    for h in 0..n_head_kv {
                        let seg = rms(&k[h * hd..(h + 1) * hd].to_vec(), &kn, eps, false);
                        k[h * hd..(h + 1) * hd].copy_from_slice(&seg);
                    }
                    // IMROPE sector walk (ops.cpp:6027-6036)
                    let rope = |buf: &mut Vec<f32>, heads: usize| {
                        let sect_dims: i32 = sections.iter().sum();
                        let sec_w = sections[0] + sections[1];
                        let theta_scale = 1000000f32.powf(-2.0 / n_rot as f32);
                        for h in 0..heads {
                            let b = h * hd;
                            for j in 0..(n_rot as usize) / 2 {
                                // text input: all four position ids (t/h/w/e) are
                                // equal, so the IMROPE sector walk (which only
                                // picks *which* base to use) is a no-op and every
                                // pair advances by the same theta_scale
                                let _ = (sect_dims, sec_w);
                                let mut theta = t as f32;
                                for _ in 0..j {
                                    theta *= theta_scale;
                                }
                                let (c, s) = (theta.cos(), theta.sin());
                                let x0 = buf[b + j];
                                let x1 = buf[b + j + (n_rot as usize) / 2];
                                buf[b + j] = x0 * c - x1 * s;
                                buf[b + j + (n_rot as usize) / 2] = x0 * s + x1 * c;
                            }
                        }
                    };
                    rope(&mut q, n_head);
                    rope(&mut k, n_head_kv);
                    f16rt(&mut k);
                    f16rt(&mut v);
                    qs.push(q);
                    ks.push(k);
                    vs.push(v);
                    gates.push(gate);
                }
                let scale = 1.0 / (hd as f32).sqrt();
                let mut res = Vec::new();
                for t in 0..x.len() {
                    let acc =
                        softmax_attn(&qs, &ks, &vs, t, n_head, n_head_kv, hd, 1.0, scale, None);
                    let gated: Vec<f32> = acc
                        .iter()
                        .zip(&gates[t])
                        .map(|(&a, &g)| a * (1.0 / (1.0 + (-g).exp())))
                        .collect();
                    res.push(dot(&wo, &gated, hd * n_head));
                }
                res
            };

            // residual + post norm + FFN + residual
            x = inp_sa
                .iter()
                .zip(&mixer)
                .map(|(a, b)| {
                    let ffn_res: Vec<f32> = a.iter().zip(b).map(|(p, q)| p + q).collect();
                    let nrm = rms(&ffn_res, &apn_v, eps, false);
                    let g = dot(&fg_v, &nrm, n_embd);
                    let u = dot(&fu_v, &nrm, n_embd);
                    let mut act = vec![0f32; n_ff];
                    for i in 0..n_ff {
                        let sg = 1.0 / (1.0 + (-g[i]).exp());
                        act[i] = g[i] * sg * u[i];
                    }
                    let d = dot(&fd_v, &act, n_ff);
                    ffn_res.iter().zip(&d).map(|(p, q)| p + q).collect()
                })
                .collect();
        }

        let last = &x[x.len() - 1];
        let xn = rms(last, &o_norm, eps, false);
        let want = dot(&o_w, &xn, n_embd);

        let rel = got
            .iter()
            .zip(&want)
            .map(|(a, b)| (a - b).abs() / b.abs().max(1e-2))
            .fold(0f32, f32::max);
        let maxabs = got
            .iter()
            .zip(&want)
            .map(|(a, b)| (a - b).abs())
            .fold(0f32, f32::max);
        println!("toy qwen35: max rel err {rel:.4} (max abs {maxabs:.3e})");
        assert!(rel < 2e-2, "toy qwen35 mismatch: {rel:.4}");

        // a second decode step exercises the recurrent state + kv reuse
        let tk = argmax(&got);
        let lg = dctx.decode(&[tk], &[3]).unwrap().to_vec();
        assert!(lg.iter().all(|v| v.is_finite()));
        assert_eq!(dctx.kv.used_cells(), 4);
    }
}

// ======================================================================
// arch batch 14 (2026-10) — the RWKV family: rwkv6 / rwkv6qwen2 (the
// rwkv6-base helpers) + rwkv7 / arwkv7 (the rwkv7-base helpers)
//
// Pure-recurrent archs (llm_arch_is_recurrent, llama-arch.cpp:1061-1073):
// no attention, no KV cache, no rope — the memory is `llama_memory_recurrent`
// alone (llama-model.cpp:2538-2548), whose two cells per layer map onto this
// port's `RecurrentState` exactly:
//   * the conv cell (`r_l`, hparams.n_embd_r = token_shift_count * n_embd,
//     llama-hparams.cpp:208-213) — the RWKV token-shift state;
//   * the SSM cell (`s_l`, hparams.n_embd_s = n_embd * wkv_head_size,
//     llama-hparams.cpp:236-240) — the WKV state.
//
// The three fused reference kernels live in the port's ggml (crates/ggml/
// src/wkv.rs, bit-exact against the reference build — parity/wkv_ref.bin):
//   * GGML_OP_RWKV_WKV6  (ggml.c:5873, kernel ops.cpp:10413-10603)
//   * GGML_OP_GATED_LINEAR_ATTN (ggml.c:5916, kernel ops.cpp:10623-11418)
//   * GGML_OP_RWKV_WKV7  (ggml.c:5959, kernel ops.cpp:11422-11617)
// The time-mix builders call them directly (the packed dst's output rows
// and new state come out as views, the state cpy'd back into the cell —
// rwkv6-base.cpp:139-147 / rwkv7-base.cpp:107-113); the former per-token
// composed stand-ins (mul+add rounding) were removed once the fused ops
// landed. All the surrounding graph structure (token shift, time/channel
// mix, state write-back) is 1:1 with the C.
//
// PARTIAL (single-sequence driver model, like every recurrent arch here):
//   * n_seqs == 1, K == 1 (no rollback snapshots, `cparams.n_rs_seq == 0`);
//     `build_rs`'s s_copy indirection degenerates to the cell (the mamba
//     precedent, graph_arch.rs:1144-1205).
//   * `build_inp_out_ids`' last-layer gather only prunes rows (values
//     identical) — skipped like every ported arch.
// ======================================================================

/// One rwkv6/rwkv6qwen2 layer's tensors (rwkv6.cpp:46-86 / rwkv6qwen2.cpp:
/// 46-77). The `Option`s are exactly the members the C leaves nullptr on the
/// arch that does not load them (or TENSOR_NOT_REQUIRED on the one that may).
#[derive(Clone, Copy)]
pub struct Rwkv6LayerWeights {
    pub attn_norm: TensorId,
    /// rwkv6's LLM_NORM pair; rwkv6qwen2 has no bias
    pub attn_norm_b: Option<TensorId>,
    /// rwkv6 only (attn_norm_2, LLM_NORM)
    pub attn_norm_2: Option<TensorId>,
    pub attn_norm_2_b: Option<TensorId>,
    // time mix (rwkv6.cpp:55-78)
    pub time_mix_w1: TensorId,
    /// {time_mix_extra_dim, n_embd, 5}
    pub time_mix_w2: TensorId,
    pub time_mix_lerp_x: TensorId,
    pub time_mix_lerp_w: Option<TensorId>,
    pub time_mix_lerp_k: Option<TensorId>,
    pub time_mix_lerp_v: Option<TensorId>,
    pub time_mix_lerp_r: Option<TensorId>,
    pub time_mix_lerp_g: Option<TensorId>,
    pub time_mix_lerp_fused: Option<TensorId>,
    /// rwkv6's time_first (required there, NOT_REQUIRED on qwen2 — a missing
    /// one is what makes the qwen2 graph take the is_qrwkv path)
    pub time_mix_first: Option<TensorId>,
    pub time_mix_decay: TensorId,
    pub time_mix_decay_w1: TensorId,
    pub time_mix_decay_w2: TensorId,
    pub time_mix_key: TensorId,
    pub time_mix_value: TensorId,
    pub time_mix_receptance: TensorId,
    pub time_mix_gate: TensorId,
    /// rwkv6qwen2's optional biases (rwkv6qwen2.cpp:66-68)
    pub time_mix_key_b: Option<TensorId>,
    pub time_mix_value_b: Option<TensorId>,
    pub time_mix_receptance_b: Option<TensorId>,
    /// rwkv6's group-norm pair (rwkv6.cpp:76-77)
    pub time_mix_ln: Option<TensorId>,
    pub time_mix_ln_b: Option<TensorId>,
    pub time_mix_output: TensorId,
    // channel mix (rwkv6.cpp:80-85)
    pub channel_mix_lerp_k: Option<TensorId>,
    pub channel_mix_lerp_r: Option<TensorId>,
    pub channel_mix_key: Option<TensorId>,
    pub channel_mix_value: Option<TensorId>,
    pub channel_mix_receptance: Option<TensorId>,
    // rwkv6qwen2's SwiGLU FFN (rwkv6qwen2.cpp:72-76)
    pub ffn_norm: Option<TensorId>,
    pub ffn_gate: Option<TensorId>,
    pub ffn_down: Option<TensorId>,
    pub ffn_up: Option<TensorId>,
}

pub struct Rwkv6ModelWeights {
    pub tok_embd: TensorId,
    /// rwkv6's Block-0 LN0 pair (rwkv6.cpp:31-33); qwen2 has none
    pub tok_norm: Option<TensorId>,
    pub tok_norm_b: Option<TensorId>,
    pub output_norm: TensorId,
    pub output_norm_b: Option<TensorId>,
    pub output: TensorId,
    pub layers: Vec<Rwkv6LayerWeights>,
}

/// The rwkv6/rwkv6qwen2 hparams the graph reads (rwkv6.cpp:3-24).
#[derive(Clone)]
pub struct Rwkv6Params {
    pub n_embd: i64,
    pub wkv_head_size: i64,
    pub time_mix_extra_dim: i64,
    pub token_shift_count: i64,
    /// rwkv6's rescale_every_n_layers (0 = disabled)
    pub rescale_every_n_layers: i64,
    /// hparams.f_norm_eps (LLM_NORM)
    pub norm_eps: f32,
    /// hparams.f_norm_rms_eps (the qwen2 variant's RMS norms)
    pub norm_rms_eps: f32,
    /// hparams.n_head_kv(0) — the qwen2 GQA-style repeat of :110-117
    pub n_head_kv: i64,
    /// hparams.n_embd_r / n_embd_s of the recurrent cells
    pub n_embd_r: u32,
    pub n_embd_s: u32,
}

/// `build_rwkv_token_shift_load` (llama-graph.cpp:3558-3576), the single-seq
/// slice: `build_rs` with n_seqs == 1 degenerates to the cell, so the token
/// shift is the conv cell (`r_l`) reshaped [n_embd, token_shift_count, 1].
fn rwkv_token_shift_load(
    ctx: &mut Context,
    cell: TensorId,
    n_embd: i64,
    token_shift_count: i64,
) -> TensorId {
    ctx.reshape_3d(cell, n_embd, token_shift_count, 1)
}

/// `build_rwkv_token_shift_store` (llama-graph.cpp:3579-3599), single seq
/// (kv_head = 0): cpy of the flat n_embd*token_shift_count elements into the
/// cell.
fn rwkv_token_shift_store(
    ctx: &mut Context,
    graph: &mut Graph,
    cell: TensorId,
    token_shift: TensorId,
    n_embd: i64,
    token_shift_count: i64,
) {
    let src = ctx.view_1d(token_shift, n_embd * token_shift_count, 0);
    let dst = ctx.view_1d(cell, n_embd * token_shift_count, 0);
    let cpy = ctx.cpy(src, dst);
    graph.build_forward(ctx, cpy);
}




/// Write a scan's final state back into the layer's SSM cell — the graph-side
/// half of `ggml_build_forward_expand(gf, ggml_cpy(wkv_state, view_1d(s_l,
/// n_embd_s*n_seqs, n_embd_s*kv_head*es)))` (rwkv6-base.cpp:144-147 /
/// rwkv7-base.cpp:111-114), single seq → offset 0.
fn rwkv_state_store(
    ctx: &mut Context,
    graph: &mut Graph,
    state_cell: TensorId,
    new_state: TensorId,
    n_embd_s: i64,
) {
    let src = ctx.reshape_2d(new_state, n_embd_s, 1);
    let dst = ctx.view_1d(state_cell, n_embd_s, 0);
    let cpy = ctx.cpy(src, dst);
    graph.build_forward(ctx, cpy);
}

/// `llm_build_rwkv6_base::build_rwkv6_time_mix` (rwkv6-base.cpp:31-164), the
/// single-sequence slice. `is_qrwkv` (layer.time_mix_first == nullptr,
/// :50) selects the rwkv6qwen2 variant: sigmoid gate, no group norm, the
/// k*(1-w) pre-gating and the GLA scan; the rwkv6 variant takes silu, the
/// group norm + ln affine and the wkv6 scan.
#[allow(clippy::too_many_arguments)]
fn build_rwkv6_time_mix(
    ctx: &mut Context,
    graph: &mut Graph,
    lw: &Rwkv6LayerWeights,
    p: &Rwkv6Params,
    st: &RecurrentState,
    il: usize,
    cur: TensorId,    // att_norm, {n_embd, T} (2D — the C's reshape at :54-55)
    x_prev: TensorId, // {n_embd, T}
    t: i64,
) -> TensorId {
    let n_embd = p.n_embd;
    let head_size = p.wkv_head_size;
    let n_head = n_embd / head_size;
    let is_qrwkv = lw.time_mix_first.is_none();

    // sx = x_prev - cur (rwkv6-base.cpp:52, :54-55)
    let sx = ctx.sub(x_prev, cur);
    let sx = ctx.reshape_2d(sx, n_embd, t);
    let cur = ctx.reshape_2d(cur, n_embd, t);

    // xxx = tanh(W1 @ (sx*lerp_x + cur)), chunked in 5 (rwkv6-base.cpp:57-65)
    let mx = ctx.mul(sx, lw.time_mix_lerp_x);
    let xxx = ctx.add(mx, cur);
    let xxx = ctx.mul_mat(lw.time_mix_w1, xxx);
    let xxx = ctx.tanh(xxx);
    let extra = p.time_mix_extra_dim;
    let xxx = ctx.reshape_4d(xxx, extra, 1, 5, t);
    let xxx = ctx.permute(xxx, 0, 1, 3, 2);
    let xxx = ctx.cont(xxx); // {extra, 1, T, 5}
    let w2_ne = ctx.ne(lw.time_mix_w2);
    let w2r = ctx.reshape_4d(lw.time_mix_w2, w2_ne[0], w2_ne[1], 1, 5);
    let xxx = ctx.mul_mat(w2r, xxx); // {n_embd, 1, T, 5}
    let xxx_nb1 = ctx.nb(xxx)[1] as usize;
    let plane = (n_embd * t * 4) as usize;

    let (xw, xk, xv, xr, xg) = if let Some(fused) = lw.time_mix_lerp_fused {
        // fusing these weights makes some performance improvement (:68-77)
        let sx3 = ctx.reshape_3d(sx, n_embd, 1, t);
        let cur3 = ctx.reshape_3d(cur, n_embd, 1, t);
        let a1 = ctx.add(xxx, fused);
        let m1 = ctx.mul(a1, sx3);
        let xxx = ctx.add(m1, cur3);
        let v0 = ctx.view_2d(xxx, n_embd, t, xxx_nb1, 0 * plane);
        let v1 = ctx.view_2d(xxx, n_embd, t, xxx_nb1, 1 * plane);
        let v2 = ctx.view_2d(xxx, n_embd, t, xxx_nb1, 2 * plane);
        let v3 = ctx.view_2d(xxx, n_embd, t, xxx_nb1, 3 * plane);
        let v4 = ctx.view_2d(xxx, n_embd, t, xxx_nb1, 4 * plane);
        (v0, v1, v2, v3, v4)
    } else {
        // for backward compatibility (:78-91) — the C keeps sx/cur 2D here
        // (the :70-71 3D reshapes live inside the fused branch only)
        let v0 = ctx.view_2d(xxx, n_embd, t, xxx_nb1, 0 * plane);
        let v1 = ctx.view_2d(xxx, n_embd, t, xxx_nb1, 1 * plane);
        let v2 = ctx.view_2d(xxx, n_embd, t, xxx_nb1, 2 * plane);
        let v3 = ctx.view_2d(xxx, n_embd, t, xxx_nb1, 3 * plane);
        let v4 = ctx.view_2d(xxx, n_embd, t, xxx_nb1, 4 * plane);
        // x = (x + lerp) * sx + cur (rwkv6-base.cpp:86-90) — the {n_embd,1,1}
        // lerps broadcast over the rows
        let mut mix = |base: TensorId, lerp: TensorId| {
            let a = ctx.add(base, lerp);
            let m = ctx.mul(a, sx);
            ctx.add(m, cur)
        };
        (
            mix(v0, lw.time_mix_lerp_w.expect("time_mix_lerp_w")),
            mix(v1, lw.time_mix_lerp_k.expect("time_mix_lerp_k")),
            mix(v2, lw.time_mix_lerp_v.expect("time_mix_lerp_v")),
            mix(v3, lw.time_mix_lerp_r.expect("time_mix_lerp_r")),
            mix(v4, lw.time_mix_lerp_g.expect("time_mix_lerp_g")),
        )
    };

    // r/k/v (+ optional biases) and the gate (rwkv6-base.cpp:92-109)
    let mut r = crate::adapter::lora_mm(ctx, lw.time_mix_receptance, xr);
    let mut k = crate::adapter::lora_mm(ctx, lw.time_mix_key, xk);
    let mut v = crate::adapter::lora_mm(ctx, lw.time_mix_value, xv);
    if let Some(b) = lw.time_mix_receptance_b {
        r = ctx.add(r, b);
    }
    if let Some(b) = lw.time_mix_key_b {
        k = ctx.add(k, b);
    }
    if let Some(b) = lw.time_mix_value_b {
        v = ctx.add(v, b);
    }
    let g = crate::adapter::lora_mm(ctx, lw.time_mix_gate, xg);
    let g = if is_qrwkv {
        ctx.sigmoid(g)
    } else {
        ctx.silu(g)
    };
    ctx.set_name(r, &format!("tmx_r-{il}"));
    ctx.set_name(k, &format!("tmx_k-{il}"));
    ctx.set_name(v, &format!("tmx_v-{il}"));
    ctx.set_name(g, &format!("tmx_g-{il}"));

    // the GQA-style repeat of the qwen2 variant (rwkv6-base.cpp:110-117)
    let n_head_kv = p.n_head_kv;
    if n_head_kv != 0 && n_head_kv != n_head {
        assert_eq!(n_head % n_head_kv, 0, "rwkv6: n_head % n_head_kv");
        k = ctx.reshape_4d(k, head_size, 1, n_head_kv, t);
        v = ctx.reshape_4d(v, head_size, 1, n_head_kv, t);
        let tmp = ctx.new_tensor_4d(GgmlType::F32, head_size, n_head / n_head_kv, n_head_kv, t);
        k = ctx.repeat(k, tmp);
        v = ctx.repeat(v, tmp);
    }
    let k = ctx.reshape_3d(k, head_size, n_head, t);
    let v = ctx.reshape_3d(v, head_size, n_head, t);
    let r = ctx.reshape_3d(r, head_size, n_head, t);

    // w = exp(-exp(W2 @ tanh(W1 @ xw) + decay)) (rwkv6-base.cpp:122-127;
    // ggml_neg(x) == scale(x, -1) exactly — a sign flip)
    let wi = ctx.mul_mat(lw.time_mix_decay_w1, xw);
    let wt = ctx.tanh(wi);
    let w = ctx.mul_mat(lw.time_mix_decay_w2, wt);
    let w = ctx.add(w, lw.time_mix_decay);
    let we = ctx.exp(w);
    let ws = ctx.scale(we, -1.0);
    let w = ctx.exp(ws);
    ctx.set_name(w, &format!("tmx_w-{il}"));
    let w = ctx.reshape_3d(w, head_size, n_head, t);

    // k = k * (1 - w) on the qwen2 variant (:129-132)
    let k = if is_qrwkv {
        let kw = ctx.mul(k, w);
        ctx.sub(k, kw)
    } else {
        k
    };

    // the WKV state + scan + write-back (:133-147) — single cell. The fused
    // kernel (GGML_OP_RWKV_WKV6 / GATED_LINEAR_ATTN, wkv.rs — bit-exact vs
    // the reference) replaces the former composed stand-in: the packed dst
    // is {S*H, T + S} — view the output rows and the new state out of it,
    // then cpy the state back into the cell (rwkv6-base.cpp:139-147)
    let state_cell = st.ssm[il].expect("rwkv6 wkv state");
    let wkv_state = ctx.reshape_2d(state_cell, p.n_embd_s as i64, 1);
    let packed = if is_qrwkv {
        // pow(head_size, -0.5f) rides the C op's params (rwkv6-base.cpp:137)
        let scale = (head_size as f32).powf(-0.5);
        ctx.gated_linear_attn(k, v, r, w, wkv_state, scale)
    } else {
        let tf = lw.time_mix_first.expect("rwkv6 time_mix_first");
        ctx.rwkv_wkv6(k, v, r, tf, w, wkv_state)
    };
    let (s_, h_, t_) = (head_size, n_head, t);
    let wkv_output = ctx.view_2d(packed, s_ * h_, t_, ((s_ * h_) * 4) as usize, 0);
    let new_state = ctx.view_1d(packed, s_ * s_ * h_, ((s_ * h_) * t_ * 4) as usize);
    rwkv_state_store(ctx, graph, state_cell, new_state, p.n_embd_s as i64);
    ctx.set_name(wkv_output, &format!("wkv_output-{il}"));

    // group norm (head_count groups) + affine on the rwkv6 variant (:149-159)
    let mut cur = ctx.reshape_2d(wkv_output, n_embd, t);
    if !is_qrwkv {
        cur = ctx.reshape_3d(cur, n_embd / n_head, n_head, t);
        cur = ctx.norm(cur, 64e-5);
        cur = ctx.reshape_2d(cur, n_embd, t);
        cur = ctx.mul(cur, lw.time_mix_ln.expect("time_mix_ln"));
        cur = ctx.add(cur, lw.time_mix_ln_b.expect("time_mix_ln_b"));
    }
    let cur = ctx.mul(cur, g);
    ctx.set_name(cur, &format!("gated-{il}"));
    let cur = crate::adapter::lora_mm(ctx, lw.time_mix_output, cur);
    ctx.set_name(cur, &format!("time_mix_out-{il}"));

    // ggml_reshape_3d(cur, n_embd, n_seq_tokens, n_seqs) (:163) — n_seqs == 1
    ctx.reshape_3d(cur, n_embd, t, 1)
}

/// `llm_build_rwkv6_base::build_rwkv6_channel_mix` (rwkv6-base.cpp:9-29),
/// the LLM_ARCH_RWKV6 arm.
fn build_rwkv6_channel_mix(
    ctx: &mut Context,
    lw: &Rwkv6LayerWeights,
    cur: TensorId,
    x_prev: TensorId,
) -> TensorId {
    let sx = ctx.sub(x_prev, cur);
    let xk = ctx.mul(sx, lw.channel_mix_lerp_k.expect("channel_mix_lerp_k"));
    let xk = ctx.add(xk, cur);
    let xr = ctx.mul(sx, lw.channel_mix_lerp_r.expect("channel_mix_lerp_r"));
    let xr = ctx.add(xr, cur);
    let r = crate::adapter::lora_mm(
        ctx,
        lw.channel_mix_receptance.expect("channel_mix_receptance"),
        xr,
    );
    let r = ctx.sigmoid(r);
    let k = crate::adapter::lora_mm(ctx, lw.channel_mix_key.expect("channel_mix_key"), xk);
    let k = ctx.relu(k);
    let k = ctx.sqr(k);
    let v = crate::adapter::lora_mm(ctx, lw.channel_mix_value.expect("channel_mix_value"), k);
    ctx.mul(r, v)
}

/// verify against src/models/rwkv6.cpp:94-185 `llama_model_rwkv6::graph::graph` —
/// LN0 → per layer (LLM_NORM attn_norm → token-shifted time mix → +residual →
/// LLM_NORM attn_norm_2 → token-shifted channel mix → +residual → optional
/// rescale) → final LLM_NORM → lm_head. Token-shift state in/out per layer.
pub fn build_rwkv6_forward(
    ctx: &mut Context,
    w: &Rwkv6ModelWeights,
    p: &Rwkv6Params,
    st: &RecurrentState,
    inp: &DecodeInputs,
) -> ForwardResult {
    let t = ctx.ne(inp.tokens)[0];
    let n_layer = w.layers.len();
    let n_embd = p.n_embd;
    let tsc = p.token_shift_count;
    let mut graph = Graph::new(2048 + 4096 * n_layer);
    assert_eq!(st.n_layer(), n_layer, "RecurrentState per layer");
    assert_eq!(
        tsc, 2,
        "rwkv6: hparams.token_shift_count == 2 (rwkv6.cpp:96)"
    );

    // inpL = build_inp_embd → LN0 (rwkv6.cpp:101-102)
    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);
    inp_l = build_norm(ctx, inp_l, w.tok_norm, w.tok_norm_b, p.norm_eps);

    for il in 0..n_layer {
        let lw = &w.layers[il];
        // inpL = reshape_3d(inpL, n_embd, n_seq_tokens, n_seqs) (:114)
        let inp_l3 = ctx.reshape_3d(inp_l, n_embd, t, 1);

        // token shift load (:116-121) — att/ffn shifts are the two planes
        let token_shift =
            rwkv_token_shift_load(ctx, st.conv[il].expect("rwkv6 conv state"), n_embd, tsc);
        let ts_nb = *ctx.nb(token_shift);
        let att_shift = ctx.view_3d(
            token_shift,
            n_embd,
            1,
            1,
            ts_nb[1] as usize,
            ts_nb[2] as usize,
            0,
        );
        let ffn_shift = ctx.view_3d(
            token_shift,
            n_embd,
            1,
            1,
            ts_nb[1] as usize,
            ts_nb[2] as usize,
            n_embd as usize * 4,
        );

        let att_norm = build_norm(ctx, inp_l3, Some(lw.attn_norm), lw.attn_norm_b, p.norm_eps);
        ctx.set_name(att_norm, &format!("attn_norm-{il}"));

        // x_prev = concat(att_shift, att_norm[:, :-1]) (:126-128)
        let an_nb = *ctx.nb(att_norm);
        let _tail = ctx.view_3d(
            att_norm,
            n_embd,
            t - 1,
            1,
            an_nb[1] as usize,
            an_nb[2] as usize,
            0,
        );
        let x_prev = ctx.concat(att_shift, _tail, 1);

        let cur = build_rwkv6_time_mix(ctx, &mut graph, lw, p, st, il, att_norm, x_prev, t);

        // ffn_inp = cur + inpL (:132)
        let ffn_inp = ctx.add(cur, inp_l3);

        let ffn_norm = build_norm(ctx, ffn_inp, lw.attn_norm_2, lw.attn_norm_2_b, p.norm_eps);
        ctx.set_name(ffn_norm, &format!("ffn_norm-{il}"));

        // x_prev for the channel mix (:138-140)
        let fn_nb = *ctx.nb(ffn_norm);
        let _tail = ctx.view_3d(
            ffn_norm,
            n_embd,
            t - 1,
            1,
            fn_nb[1] as usize,
            fn_nb[2] as usize,
            0,
        );
        let x_prev = ctx.concat(ffn_shift, _tail, 1);

        // token_shift' = concat(att_norm[:, -1], ffn_norm[:, -1]) (:142-147)
        let ts_a = ctx.view_3d(
            att_norm,
            n_embd,
            1,
            1,
            an_nb[1] as usize,
            an_nb[2] as usize,
            ((t - 1) * n_embd) as usize * 4,
        );
        let ts_b = ctx.view_3d(
            ffn_norm,
            n_embd,
            1,
            1,
            fn_nb[1] as usize,
            fn_nb[2] as usize,
            ((t - 1) * n_embd) as usize * 4,
        );
        let token_shift = ctx.concat(ts_a, ts_b, 1);
        rwkv_token_shift_store(
            ctx,
            &mut graph,
            st.conv[il].expect("rwkv6 conv state"),
            token_shift,
            n_embd,
            tsc,
        );

        // the 2D reshapes of :150-153 (the inp_out_ids gather of :155-160 only
        // prunes rows — same values, the port's shared out_rows handles the
        // head-side gather)
        let ffn_inp = ctx.reshape_2d(ffn_inp, n_embd, t);
        let ffn_norm = ctx.reshape_2d(ffn_norm, n_embd, t);
        let x_prev = ctx.reshape_2d(x_prev, n_embd, t);

        // channel mix + residual (:161-162)
        let cur = build_rwkv6_channel_mix(ctx, lw, ffn_norm, x_prev);
        let mut cur = ctx.add(cur, ffn_inp);

        // rescale_every_n_layers (:164-166)
        if p.rescale_every_n_layers != 0 && (il as i64 + 1) % p.rescale_every_n_layers == 0 {
            cur = ctx.scale(cur, 0.5);
        }
        inp_l = cur;
    }

    // final norm + lm_head (rwkv6.cpp:173-184)
    let embd = build_norm(ctx, inp_l, Some(w.output_norm), w.output_norm_b, p.norm_eps);
    let embd = graph::out_rows(ctx, embd, inp.out_ids);
    let cur = crate::adapter::lora_mm(ctx, w.output, embd);
    graph.build_forward(ctx, cur);
    ForwardResult {
        logits: cur,
        graph,
        embd: Some(embd),
    }
}

/// verify against src/models/rwkv6qwen2.cpp:84-167 — the "qwen2-style" rwkv6: RMS
/// norms, sigmoid-gated GLA time mix (token_shift_count == 1) and a SwiGLU
/// FFN instead of the channel mix.
pub fn build_rwkv6qwen2_forward(
    ctx: &mut Context,
    w: &Rwkv6ModelWeights,
    p: &Rwkv6Params,
    st: &RecurrentState,
    inp: &DecodeInputs,
) -> ForwardResult {
    let t = ctx.ne(inp.tokens)[0];
    let n_layer = w.layers.len();
    let n_embd = p.n_embd;
    let tsc = p.token_shift_count;
    let mut graph = Graph::new(2048 + 4096 * n_layer);
    assert_eq!(st.n_layer(), n_layer, "RecurrentState per layer");
    assert_eq!(
        n_embd,
        st.n_embd_r as i64 / tsc,
        "rwkv6qwen2: n_embd == hparams.n_embd_r() (rwkv6qwen2.cpp:85)"
    );

    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_l3 = ctx.reshape_3d(inp_l, n_embd, t, 1);

        // token shift: one plane only (tsc == 1, :104)
        let token_shift =
            rwkv_token_shift_load(ctx, st.conv[il].expect("rwkv6 conv state"), n_embd, tsc);

        // attn_norm: RMS (no bias on this arch, :106)
        let att_norm = build_norm_rms(ctx, inp_l3, lw.attn_norm, p.norm_rms_eps);
        ctx.set_name(att_norm, &format!("attn_norm-{il}"));

        let an_nb = *ctx.nb(att_norm);
        let _tail = ctx.view_3d(
            att_norm,
            n_embd,
            t - 1,
            1,
            an_nb[1] as usize,
            an_nb[2] as usize,
            0,
        );
        let x_prev = ctx.concat(token_shift, _tail, 1);

        let cur = build_rwkv6_time_mix(ctx, &mut graph, lw, p, st, il, att_norm, x_prev, t);

        // store the last att_norm plane (:118-119)
        let token_shift = ctx.view_3d(
            att_norm,
            n_embd,
            1,
            1,
            an_nb[1] as usize,
            an_nb[2] as usize,
            ((t - 1) * n_embd) as usize * 4,
        );
        rwkv_token_shift_store(
            ctx,
            &mut graph,
            st.conv[il].expect("rwkv6 conv state"),
            token_shift,
            n_embd,
            tsc,
        );

        // ffn_inp = cur + inpL; SwiGLU FFN (:121-146)
        let ffn_inp = ctx.add(cur, inp_l3);
        let cur = ctx.reshape_2d(cur, n_embd, t);
        let ffn_inp = ctx.reshape_2d(ffn_inp, n_embd, t);

        let ffn_norm = build_norm_rms(ctx, ffn_inp, lw.ffn_norm.expect("ffn_norm"), p.norm_rms_eps);
        ctx.set_name(ffn_norm, &format!("ffn_norm-{il}"));
        let gate = crate::adapter::lora_mm(ctx, lw.ffn_gate.expect("ffn_gate"), ffn_norm);
        let up = crate::adapter::lora_mm(ctx, lw.ffn_up.expect("ffn_up"), ffn_norm);
        let sg = ctx.silu(gate);
        let cur = ctx.mul(sg, up);
        let cur = crate::adapter::lora_mm(ctx, lw.ffn_down.expect("ffn_down"), cur);
        ctx.set_name(cur, &format!("ffn_out-{il}"));
        inp_l = ctx.add(cur, ffn_inp);
    }

    // final RMS norm + lm_head (:155-166)
    let embd = build_norm_rms(ctx, inp_l, w.output_norm, p.norm_rms_eps);
    let embd = graph::out_rows(ctx, embd, inp.out_ids);
    let cur = crate::adapter::lora_mm(ctx, w.output, embd);
    graph.build_forward(ctx, cur);
    ForwardResult {
        logits: cur,
        graph,
        embd: Some(embd),
    }
}

// ----------------------------------------------------------------------
// rwkv7 / arwkv7 (src/models/rwkv7-base.cpp + rwkv7.cpp / arwkv7.cpp)
// ----------------------------------------------------------------------

/// One rwkv7/arwkv7 layer's tensors (rwkv7.cpp:67-116 / arwkv7.cpp:61-112).
#[derive(Clone, Copy)]
pub struct Rwkv7LayerWeights {
    pub attn_norm: TensorId,
    /// rwkv7's LLM_NORM pair; arwkv7 has no bias
    pub attn_norm_b: Option<TensorId>,
    /// rwkv7 only (attn_norm_2, LLM_NORM)
    pub attn_norm_2: Option<TensorId>,
    pub attn_norm_2_b: Option<TensorId>,
    // the w/a/v lora triples (rwkv7.cpp:76-93)
    pub time_mix_w0: TensorId,
    pub time_mix_w1: TensorId,
    pub time_mix_w2: TensorId,
    pub time_mix_a0: TensorId,
    pub time_mix_a1: TensorId,
    pub time_mix_a2: TensorId,
    pub time_mix_v0: TensorId,
    pub time_mix_v1: TensorId,
    pub time_mix_v2: TensorId,
    /// arwkv7's optional gating pair (arwkv7.cpp:85-86)
    pub time_mix_g1: Option<TensorId>,
    pub time_mix_g2: Option<TensorId>,
    pub time_mix_lerp_fused: TensorId,
    pub time_mix_k_k: TensorId,
    pub time_mix_k_a: TensorId,
    pub time_mix_r_k: TensorId,
    pub time_mix_key: TensorId,
    pub time_mix_value: TensorId,
    pub time_mix_receptance: TensorId,
    /// rwkv7's group-norm pair (rwkv7.cpp:108-109; NOT_REQUIRED on arwkv7)
    pub time_mix_ln: Option<TensorId>,
    pub time_mix_ln_b: Option<TensorId>,
    pub time_mix_output: TensorId,
    // channel mix (rwkv7.cpp:112-115 — no receptance/lerp_r)
    pub channel_mix_lerp_k: Option<TensorId>,
    pub channel_mix_key: Option<TensorId>,
    pub channel_mix_value: Option<TensorId>,
    // arwkv7's SwiGLU FFN (arwkv7.cpp:107-111)
    pub ffn_norm: Option<TensorId>,
    pub ffn_gate: Option<TensorId>,
    pub ffn_down: Option<TensorId>,
    pub ffn_up: Option<TensorId>,
}

pub struct Rwkv7ModelWeights {
    pub tok_embd: TensorId,
    /// rwkv7's Block-0 LN0 pair; arwkv7 has none
    pub tok_norm: Option<TensorId>,
    pub tok_norm_b: Option<TensorId>,
    pub output_norm: TensorId,
    pub output_norm_b: Option<TensorId>,
    pub output: TensorId,
    pub layers: Vec<Rwkv7LayerWeights>,
}

/// The rwkv7/arwkv7 hparams the graph reads (rwkv7.cpp:3-44).
#[derive(Clone)]
pub struct Rwkv7Params {
    pub n_embd: i64,
    pub wkv_head_size: i64,
    pub token_shift_count: i64,
    pub norm_eps: f32,
    pub norm_rms_eps: f32,
    /// hparams.n_embd_r / n_embd_s of the recurrent cells
    pub n_embd_r: u32,
    pub n_embd_s: u32,
}

/// `llm_build_rwkv7_base::build_rwkv7_channel_mix` (rwkv7-base.cpp:9-28),
/// the LLM_ARCH_RWKV7 arm (no receptance — just squared-relu key/value).
fn build_rwkv7_channel_mix(
    ctx: &mut Context,
    lw: &Rwkv7LayerWeights,
    cur: TensorId,
    x_prev: TensorId,
) -> TensorId {
    let sx = ctx.sub(x_prev, cur);
    let xk = ctx.mul(sx, lw.channel_mix_lerp_k.expect("channel_mix_lerp_k"));
    let xk = ctx.add(xk, cur);
    let k = crate::adapter::lora_mm(ctx, lw.channel_mix_key.expect("channel_mix_key"), xk);
    let k = ctx.relu(k);
    let k = ctx.sqr(k);
    crate::adapter::lora_mm(ctx, lw.channel_mix_value.expect("channel_mix_value"), k)
}

/// `ggml_l2_norm(kk, 1e-12)` composed from the existing ops — the kernel
/// (ops.cpp:4856-4903): `scale = 1/fmaxf(sqrtf(Σx²), eps)`, then `x*scale`
/// (sum accumulated in double). Used at rwkv7-base.cpp:94.
fn rwkv_l2_norm(ctx: &mut Context, x: TensorId, eps: f32) -> TensorId {
    let sq = ctx.sqr(x);
    let sum = ctx.sum_rows(sq); // {1, ne1, ne2, ne3}, f64 acc
    let sq = ctx.sqrt(sum);
    let sq = ctx.clamp(sq, eps, f32::INFINITY); // fmaxf(sqrt, eps)
    let one = ctx.fill(sq, 1.0); // same shape, all ones
    let recip = ctx.div(one, sq); // 1.0f / fmaxf(...) — one rounding
    ctx.mul(x, recip) // ggml_vec_scale_f32 == x*scale
}

/// `llm_build_rwkv7_base::build_rwkv7_time_mix` (rwkv7-base.cpp:30-137), the
/// single-sequence slice. `first_layer_value` is the v_first threading
/// (rwkv7.cpp:130: nullptr until layer 0's v is recorded).
#[allow(clippy::too_many_arguments)]
fn build_rwkv7_time_mix(
    ctx: &mut Context,
    graph: &mut Graph,
    lw: &Rwkv7LayerWeights,
    p: &Rwkv7Params,
    st: &RecurrentState,
    il: usize,
    cur: TensorId,    // att_norm {n_embd, T} (2D — the C keeps 3D with n_seqs=1)
    x_prev: TensorId, // {n_embd, T}
    v_first: &mut Option<TensorId>,
    t: i64,
) -> TensorId {
    let n_embd = p.n_embd;
    let head_size = p.wkv_head_size;
    let head_count = n_embd / head_size;
    let has_gating = lw.time_mix_g1.is_some() && lw.time_mix_g2.is_some();

    // sx repeated over the lerp planes (rwkv7-base.cpp:51-53)
    let sx = ctx.sub(x_prev, cur);
    let n_planes = if has_gating { 6 } else { 5 };
    let dummy = ctx.new_tensor_4d(GgmlType::F32, n_embd, t, 1, n_planes);
    let sx = ctx.repeat(sx, dummy);
    let ms = ctx.mul(sx, lw.time_mix_lerp_fused);
    let xxx = ctx.add(ms, cur);

    // xr/xw/xk/xv/xa(/xg) plane views (:57-64)
    let xxx_nb1 = ctx.nb(xxx)[1] as usize;
    let plane = (n_embd * t * 4) as usize;
    let v0 = ctx.view_2d(xxx, n_embd, t, xxx_nb1, 0 * plane);
    let v1 = ctx.view_2d(xxx, n_embd, t, xxx_nb1, 1 * plane);
    let v2 = ctx.view_2d(xxx, n_embd, t, xxx_nb1, 2 * plane);
    let v3 = ctx.view_2d(xxx, n_embd, t, xxx_nb1, 3 * plane);
    let v4 = ctx.view_2d(xxx, n_embd, t, xxx_nb1, 4 * plane);
    let v5 = ctx.view_2d(xxx, n_embd, t, xxx_nb1, 5 * plane);
    let (xr, xw, xk, xv, xa, xg) = (v0, v1, v2, v3, v4, if has_gating { Some(v5) } else { None });

    let r = crate::adapter::lora_mm(ctx, lw.time_mix_receptance, xr);
    // w = exp(sigmoid(W2 @ tanh(W1 @ xw) + w0) * -0.606531) (:67-70)
    let wt0 = ctx.mul_mat(lw.time_mix_w1, xw);
    let wt1 = ctx.tanh(wt0);
    let wt2 = ctx.mul_mat(lw.time_mix_w2, wt1);
    let w = ctx.add(wt2, lw.time_mix_w0);
    let wsig = ctx.sigmoid(w);
    let wsc = ctx.scale(wsig, -0.606531);
    let w = ctx.exp(wsc);

    let k = crate::adapter::lora_mm(ctx, lw.time_mix_key, xk);
    let mut v_ = crate::adapter::lora_mm(ctx, lw.time_mix_value, xv);
    if v_first.is_none() {
        *v_first = Some(v_);
    } else {
        // + sigmoid(V2 @ (V1 @ xv) + v0) * (first_layer_value - v) (:74-84)
        let fv = v_first.unwrap();
        let v10 = ctx.mul_mat(lw.time_mix_v1, xv);
        let v11 = ctx.mul_mat(lw.time_mix_v2, v10);
        let mix = ctx.add(v11, lw.time_mix_v0);
        let d = ctx.sub(fv, v_);
        let sm = ctx.sigmoid(mix);
        let g = ctx.mul(d, sm);
        v_ = ctx.add(v_, g);
    }
    let g = if let (Some(g1), Some(g2)) = (lw.time_mix_g1, lw.time_mix_g2) {
        let g10 = ctx.mul_mat(g1, xg.expect("xg"));
        let g1s = ctx.sigmoid(g10);
        Some(ctx.mul_mat(g2, g1s))
    } else {
        None
    };
    // a = sigmoid(A2 @ (A1 @ xa) + a0) (:89-91)
    let a10 = ctx.mul_mat(lw.time_mix_a1, xa);
    let a11 = ctx.mul_mat(lw.time_mix_a2, a10);
    let a12 = ctx.add(a11, lw.time_mix_a0);
    let a = ctx.sigmoid(a12);

    // kk = l2_norm(reshape(k * k_k)) ; k = k + (a-1)*(k*k_a) (:93-97)
    let kk = ctx.mul(k, lw.time_mix_k_k);
    let kk = ctx.reshape_3d(kk, head_size, head_count, t);
    let kk = rwkv_l2_norm(ctx, kk, 1e-12);
    let ka = ctx.mul(k, lw.time_mix_k_a);
    let ak = ctx.mul(a, ka);
    let d = ctx.sub(ak, ka);
    let k = ctx.add(k, d);

    let r = ctx.reshape_3d(r, head_size, head_count, t);
    let w = ctx.reshape_3d(w, head_size, head_count, t);
    let k = ctx.reshape_3d(k, head_size, head_count, t);
    let v_ = ctx.reshape_3d(v_, head_size, head_count, t);
    let a = ctx.reshape_3d(a, head_size, head_count, t);

    // the WKV7 scan + write-back (:105-114) — the fused kernel
    // (GGML_OP_RWKV_WKV7, wkv.rs — bit-exact vs the reference); the packed
    // dst's output rows and new state come out as views (rwkv7-base.cpp:107-
    // 113). ggml_neg(kk) == scale(kk, -1)
    let state_cell = st.ssm[il].expect("rwkv7 wkv state");
    let a_neg = ctx.scale(kk, -1.0); // ggml_neg(kk)
    let kk_a = ctx.mul(kk, a);
    let wkv_state = ctx.reshape_2d(state_cell, p.n_embd_s as i64, 1);
    let packed = ctx.rwkv_wkv7(r, w, k, v_, a_neg, kk_a, wkv_state);
    let (s_, h_, t_) = (head_size, head_count, t);
    let wkv_output = ctx.view_2d(packed, s_ * h_, t_, ((s_ * h_) * 4) as usize, 0);
    let new_state = ctx.view_1d(packed, s_ * s_ * h_, ((s_ * h_) * t_ * 4) as usize);
    rwkv_state_store(ctx, graph, state_cell, new_state, p.n_embd_s as i64);

    // group norm + affine when the layer carries them (:116-126)
    let mut cur = ctx.reshape_2d(wkv_output, n_embd, t);
    if let (Some(ln), Some(ln_b)) = (lw.time_mix_ln, lw.time_mix_ln_b) {
        cur = ctx.reshape_3d(cur, n_embd / head_count, head_count, t);
        cur = ctx.norm(cur, 64e-5);
        cur = ctx.reshape_2d(cur, n_embd, t);
        cur = ctx.mul(cur, ln);
        cur = ctx.add(cur, ln_b);
    }

    // the rk bonus (:127-129) — rk = Σ_dim0(k*r*r_k) {1,H,T}, v ⊙ rk
    let kr = ctx.mul(k, r);
    let rk_w = ctx.reshape_2d(lw.time_mix_r_k, head_size, head_count);
    let rk_in = ctx.mul(kr, rk_w);
    let rk = ctx.sum_rows(rk_in);
    let bonus = ctx.mul(v_, rk); // {S,H,T} ⊙ {1,H,T} broadcast
    let bonus2 = ctx.reshape_2d(bonus, n_embd, t);
    let mut cur = ctx.add(cur, bonus2);

    if let Some(g) = g {
        cur = ctx.mul(cur, g);
    }
    let cur = crate::adapter::lora_mm(ctx, lw.time_mix_output, cur);
    ctx.reshape_3d(cur, n_embd, t, 1)
}

/// verify against src/models/rwkv7.cpp:124-211 — LN0 → per layer (LLM_NORM attn_norm →
/// token-shifted wkv7 time mix (v_first threading) → +residual → LLM_NORM
/// attn_norm_2 → token-shifted channel mix → +residual) → final LLM_NORM →
/// lm_head.
pub fn build_rwkv7_forward(
    ctx: &mut Context,
    w: &Rwkv7ModelWeights,
    p: &Rwkv7Params,
    st: &RecurrentState,
    inp: &DecodeInputs,
) -> ForwardResult {
    let t = ctx.ne(inp.tokens)[0];
    let n_layer = w.layers.len();
    let n_embd = p.n_embd;
    let tsc = p.token_shift_count;
    let mut graph = Graph::new(2048 + 4096 * n_layer);
    assert_eq!(st.n_layer(), n_layer, "RecurrentState per layer");
    assert_eq!(
        tsc, 2,
        "rwkv7: hparams.token_shift_count == 2 (rwkv7.cpp:126)"
    );

    // LN0 (rwkv7.cpp:132-133)
    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);
    inp_l = build_norm(ctx, inp_l, w.tok_norm, w.tok_norm_b, p.norm_eps);

    let mut v_first: Option<TensorId> = None;

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_l3 = ctx.reshape_3d(inp_l, n_embd, t, 1);

        let token_shift =
            rwkv_token_shift_load(ctx, st.conv[il].expect("rwkv7 conv state"), n_embd, tsc);
        let ts_nb = *ctx.nb(token_shift);
        let att_shift = ctx.view_3d(
            token_shift,
            n_embd,
            1,
            1,
            ts_nb[1] as usize,
            ts_nb[2] as usize,
            0,
        );
        let ffn_shift = ctx.view_3d(
            token_shift,
            n_embd,
            1,
            1,
            ts_nb[1] as usize,
            ts_nb[2] as usize,
            n_embd as usize * 4,
        );

        let att_norm = build_norm(ctx, inp_l3, Some(lw.attn_norm), lw.attn_norm_b, p.norm_eps);
        ctx.set_name(att_norm, &format!("attn_norm-{il}"));

        let an_nb = *ctx.nb(att_norm);
        let _tail = ctx.view_3d(
            att_norm,
            n_embd,
            t - 1,
            1,
            an_nb[1] as usize,
            an_nb[2] as usize,
            0,
        );
        let x_prev = ctx.concat(att_shift, _tail, 1);

        let cur = build_rwkv7_time_mix(
            ctx,
            &mut graph,
            lw,
            p,
            st,
            il,
            att_norm,
            x_prev,
            &mut v_first,
            t,
        );

        let ffn_inp = ctx.add(cur, inp_l3);

        let ffn_norm = build_norm(ctx, ffn_inp, lw.attn_norm_2, lw.attn_norm_2_b, p.norm_eps);
        ctx.set_name(ffn_norm, &format!("ffn_norm-{il}"));

        let fn_nb = *ctx.nb(ffn_norm);
        let _tail = ctx.view_3d(
            ffn_norm,
            n_embd,
            t - 1,
            1,
            fn_nb[1] as usize,
            fn_nb[2] as usize,
            0,
        );
        let x_prev = ctx.concat(ffn_shift, _tail, 1);

        let ts_a = ctx.view_3d(
            att_norm,
            n_embd,
            1,
            1,
            an_nb[1] as usize,
            an_nb[2] as usize,
            ((t - 1) * n_embd) as usize * 4,
        );
        let ts_b = ctx.view_3d(
            ffn_norm,
            n_embd,
            1,
            1,
            fn_nb[1] as usize,
            fn_nb[2] as usize,
            ((t - 1) * n_embd) as usize * 4,
        );
        let token_shift = ctx.concat(ts_a, ts_b, 1);
        rwkv_token_shift_store(
            ctx,
            &mut graph,
            st.conv[il].expect("rwkv7 conv state"),
            token_shift,
            n_embd,
            tsc,
        );

        // 2D reshapes of :181-183 (the inp_out_ids gather prunes rows only)
        let ffn_inp = ctx.reshape_2d(ffn_inp, n_embd, t);
        let ffn_norm = ctx.reshape_2d(ffn_norm, n_embd, t);
        let x_prev = ctx.reshape_2d(x_prev, n_embd, t);

        // channel mix + residual (:190-191) — no rescale on this arch
        let cur = build_rwkv7_channel_mix(ctx, lw, ffn_norm, x_prev);
        inp_l = ctx.add(cur, ffn_inp);
    }

    // final norm + lm_head (rwkv7.cpp:199-210)
    let embd = build_norm(ctx, inp_l, Some(w.output_norm), w.output_norm_b, p.norm_eps);
    let embd = graph::out_rows(ctx, embd, inp.out_ids);
    let cur = crate::adapter::lora_mm(ctx, w.output, embd);
    graph.build_forward(ctx, cur);
    ForwardResult {
        logits: cur,
        graph,
        embd: Some(embd),
    }
}

/// verify against src/models/arwkv7.cpp:120-202 — the RMS-norm rwkv7 ("a"rwkv7): no
/// LN0, RMS attn_norm, one token-shift plane (token_shift_count == 1) and a
/// SwiGLU FFN instead of the channel mix. Optional gating pair + optional
/// ln/ln_b and a 6-or-5-plane lerp_fused (the loader's try/catch,
/// arwkv7.cpp:88-93).
pub fn build_arwkv7_forward(
    ctx: &mut Context,
    w: &Rwkv7ModelWeights,
    p: &Rwkv7Params,
    st: &RecurrentState,
    inp: &DecodeInputs,
) -> ForwardResult {
    let t = ctx.ne(inp.tokens)[0];
    let n_layer = w.layers.len();
    let n_embd = p.n_embd;
    let tsc = p.token_shift_count;
    let mut graph = Graph::new(2048 + 4096 * n_layer);
    assert_eq!(st.n_layer(), n_layer, "RecurrentState per layer");
    assert_eq!(
        n_embd,
        st.n_embd_r as i64 / tsc,
        "arwkv7: n_embd == hparams.n_embd_r() (arwkv7.cpp:121)"
    );

    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    let mut v_first: Option<TensorId> = None;

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_l3 = ctx.reshape_3d(inp_l, n_embd, t, 1);

        let token_shift =
            rwkv_token_shift_load(ctx, st.conv[il].expect("arwkv7 conv state"), n_embd, tsc);

        let att_norm = build_norm_rms(ctx, inp_l3, lw.attn_norm, p.norm_rms_eps);
        ctx.set_name(att_norm, &format!("attn_norm-{il}"));

        let an_nb = *ctx.nb(att_norm);
        let _tail = ctx.view_3d(
            att_norm,
            n_embd,
            t - 1,
            1,
            an_nb[1] as usize,
            an_nb[2] as usize,
            0,
        );
        let x_prev = ctx.concat(token_shift, _tail, 1);

        let cur = build_rwkv7_time_mix(
            ctx,
            &mut graph,
            lw,
            p,
            st,
            il,
            att_norm,
            x_prev,
            &mut v_first,
            t,
        );

        // store the last att_norm plane (arwkv7.cpp:155-156)
        let token_shift = ctx.view_3d(
            att_norm,
            n_embd,
            1,
            1,
            an_nb[1] as usize,
            an_nb[2] as usize,
            ((t - 1) * n_embd) as usize * 4,
        );
        rwkv_token_shift_store(
            ctx,
            &mut graph,
            st.conv[il].expect("arwkv7 conv state"),
            token_shift,
            n_embd,
            tsc,
        );

        // SwiGLU FFN (arwkv7.cpp:158-182)
        let ffn_inp = ctx.add(cur, inp_l3);
        let cur = ctx.reshape_2d(cur, n_embd, t);
        let ffn_inp = ctx.reshape_2d(ffn_inp, n_embd, t);

        let ffn_norm = build_norm_rms(ctx, ffn_inp, lw.ffn_norm.expect("ffn_norm"), p.norm_rms_eps);
        ctx.set_name(ffn_norm, &format!("ffn_norm-{il}"));
        let gate = crate::adapter::lora_mm(ctx, lw.ffn_gate.expect("ffn_gate"), ffn_norm);
        let up = crate::adapter::lora_mm(ctx, lw.ffn_up.expect("ffn_up"), ffn_norm);
        let sg = ctx.silu(gate);
        let cur = ctx.mul(sg, up);
        let cur = crate::adapter::lora_mm(ctx, lw.ffn_down.expect("ffn_down"), cur);
        ctx.set_name(cur, &format!("ffn_out-{il}"));
        inp_l = ctx.add(cur, ffn_inp);
    }

    // final RMS norm + lm_head (arwkv7.cpp:190-201)
    let embd = build_norm_rms(ctx, inp_l, w.output_norm, p.norm_rms_eps);
    let embd = graph::out_rows(ctx, embd, inp.out_ids);
    let cur = crate::adapter::lora_mm(ctx, w.output, embd);
    graph.build_forward(ctx, cur);
    ForwardResult {
        logits: cur,
        graph,
        embd: Some(embd),
    }
}

// ======================================================================
// gemma3n (src/models/gemma3n.cpp) — the altup/laurel multi-token machinery
//
// Per-layer embeddings (n_embd_altup-wide) + the altup stack (n_altup
// parallel streams carried in the tensor's 3rd dim) + laurel low-rank side
// path + gaussian-topk activation sparsity + the per-layer KV-reuse trick
// (n_layer_kv_from_start: layers >= it attend the *earlier* layer's cache,
// llama-model.cpp:2658-2666's layer_reuse_cb).
// ======================================================================

/// One gemma3n layer's tensors (gemma3n.cpp:45-75).
#[derive(Clone, Copy)]
pub struct Gemma3nLayerWeights {
    pub attn_norm: TensorId,
    /// the fused qkv of the create_tensor_qkv call, or separate wq/wk/wv
    /// (llama-model.cpp:3214-3244) — the reuse branch reads either
    pub wqkv: Option<TensorId>,
    pub wq: Option<TensorId>,
    pub wk: Option<TensorId>,
    pub wv: Option<TensorId>,
    pub wo: TensorId,
    pub attn_q_norm: TensorId,
    pub attn_k_norm: TensorId,
    pub attn_post_norm: TensorId,
    pub ffn_norm: TensorId,
    pub ffn_gate: TensorId,
    pub ffn_up: TensorId,
    pub ffn_down: TensorId,
    pub ffn_post_norm: TensorId,
    // altup & laurel (gemma3n.cpp:63-74)
    pub per_layer_inp_gate: TensorId,
    pub per_layer_proj: TensorId,
    pub per_layer_post_norm: TensorId,
    pub altup_correct_coef: TensorId,
    pub altup_correct_scale: TensorId,
    pub altup_predict_coef: TensorId,
    pub altup_router: TensorId,
    pub altup_router_norm: TensorId,
    pub laurel_l: TensorId,
    pub laurel_r: TensorId,
    pub laurel_post_norm: TensorId,
}

pub struct Gemma3nModelWeights {
    pub tok_embd: TensorId,
    /// lm head; gemma3n falls back to tok_embd (TENSOR_DUPLICATED) when the
    /// file has no output.weight (gemma3n.cpp:28-32)
    pub output: TensorId,
    pub output_norm: TensorId,
    pub altup_proj: TensorId,
    pub altup_unembd_proj: TensorId,
    pub per_layer_tok_embd: TensorId,
    pub per_layer_model_proj: TensorId,
    pub per_layer_proj_norm: TensorId,
    pub layers: Vec<Gemma3nLayerWeights>,
}

/// gemma3n hparams + the graph's in-class constants (models.h:836-844).
#[derive(Clone)]
pub struct Gemma3nParams {
    pub attn: AttnParams,
    pub n_embd: i64,
    pub n_altup: i64,
    pub i_altup_act: i64,
    pub n_embd_altup: i64,
    pub laurel_rank: i64,
    /// models.h:843 — number of layers using activation sparsity
    pub n_layer_sparsity: i64,
    /// models.h:844 — std_multiplier = normal_dist.icdf(0.95)
    pub f_sparsity_std_mul: f32,
    /// hparams.is_swa(il) (the 4:1 SWA pattern of load_swa_pattern(ml, 5))
    pub is_swa: Vec<bool>,
    /// hparams.n_layer_kv_from_start (gemma3n.cpp:7) — the KV-reuse boundary
    pub n_layer_kv_from_start: i64,
    /// hparams.f_attention_scale (1.0, gemma3n.cpp:8)
    pub f_attention_scale: f32,
    /// hparams.rope_freq_base_train_swa / rope_freq_scale_train_swa — the SWA
    /// layers' rope facts (get_rope_freq_base/scale, llama-model.cpp:2251-2258)
    pub freq_base_swa: f32,
    pub freq_scale_swa: f32,
    pub norm_eps: f32,
    /// the final logit soft-capping (0 = none)
    pub f_final_logit_softcapping: f32,
}

/// `gemma3n_view_2d_slice` (gemma3n.cpp:83-87) — the idx-th [ne0, ne1] plane
/// of a 3D tensor.
fn gemma3n_view_2d_slice(ctx: &mut Context, x: TensorId, idx: i64) -> TensorId {
    let ne = ctx.ne(x);
    let esz = ctx.ty(x).type_size();
    assert!(idx < ne[2], "gemma3n_view_2d_slice: idx < ne[2]");
    ctx.view_2d(
        x,
        ne[0],
        ne[1],
        (ne[0] as usize) * esz,
        (idx * ne[0] * ne[1]) as usize * esz,
    )
}

/// `graph::calc_magnitude` (gemma3n.cpp:318-320) — sqrt(Σ_rows x²).
fn gemma3n_calc_magnitude(ctx: &mut Context, x: TensorId) -> TensorId {
    let sq = ctx.sqr(x);
    let sr = ctx.sum_rows(sq);
    ctx.sqrt(sr)
}

/// `graph::gaussian_topk` (gemma3n.cpp:392-398) — relu(x - (mean + std_mul*std)).
fn gemma3n_gaussian_topk(ctx: &mut Context, x: TensorId, std_mul: f32) -> TensorId {
    let mean = ctx.mean(x); // {1, T}
    let centered = ctx.sub(x, mean);
    let n0 = ctx.ne(x)[0];
    let sq = ctx.sqr(centered);
    let sr = ctx.sum_rows(sq);
    let sc = ctx.scale(sr, 1.0 / (n0 - 1) as f32);
    let std = ctx.sqrt(sc);
    let st = ctx.scale(std, std_mul);
    let cutoff = ctx.add(mean, st);
    let d = ctx.sub(x, cutoff);
    ctx.relu(d)
}

/// `graph::laurel` (gemma3n.cpp:380-388) — the low-rank side path with its
/// RMS norm and residual.
fn gemma3n_laurel(
    ctx: &mut Context,
    lw: &Gemma3nLayerWeights,
    p: &Gemma3nParams,
    cur: TensorId,
    il: usize,
) -> TensorId {
    let tmp = crate::adapter::lora_mm(ctx, lw.laurel_l, cur);
    let tmp = crate::adapter::lora_mm(ctx, lw.laurel_r, tmp);
    let tmp = build_norm_rms(ctx, tmp, lw.laurel_post_norm, p.norm_eps);
    let tmp = ctx.add(tmp, cur);
    ctx.set_name(tmp, &format!("laurel_out-{il}"));
    tmp
}

/// `graph::altup_compute_router_modalities` (gemma3n.cpp:407-415) —
/// tanh(router @ (rms_norm(x)/n_embd)).
fn gemma3n_altup_router_modalities(
    ctx: &mut Context,
    lw: &Gemma3nLayerWeights,
    p: &Gemma3nParams,
    x: TensorId,
    il: usize,
) -> TensorId {
    let mut router_inputs = build_norm_rms(ctx, x, lw.altup_router_norm, p.norm_eps);
    router_inputs = ctx.scale(router_inputs, 1.0 / p.n_embd as f32);
    let out = ctx.mul_mat(lw.altup_router, router_inputs);
    ctx.tanh(out) // {n_altup, T}
}

/// `graph::altup_predict` (gemma3n.cpp:419-439) — the per-layer stream mix.
fn gemma3n_altup_predict(
    ctx: &mut Context,
    lw: &Gemma3nLayerWeights,
    p: &Gemma3nParams,
    cur: TensorId, // {n_embd, T, n_altup}
    il: usize,
) -> TensorId {
    let n_altup = p.n_altup;
    let t = ctx.ne(cur)[1];
    let activated = gemma3n_view_2d_slice(ctx, cur, p.i_altup_act);
    let modalities = gemma3n_altup_router_modalities(ctx, lw, p, activated, il);
    ctx.set_name(modalities, &format!("modalities-{il}"));

    let all_coefs = crate::adapter::lora_mm(ctx, lw.altup_predict_coef, modalities);
    ctx.set_name(all_coefs, &format!("all_coefs-{il}"));
    // first dim now has n_altup² elements, reshape to {n_altup, n_altup, T}
    let all_coefs = ctx.reshape_3d(all_coefs, n_altup, n_altup, t);

    // permute to [n_altup, n_embd, T] (gemma3n.cpp:430)
    let cp = ctx.permute(cur, 1, 2, 0, 3);
    let cur_permuted = ctx.cont(cp);
    let predictions = ctx.mul_mat(cur_permuted, all_coefs); // {n_embd, n_altup, T}

    // back to [n_embd, T, n_altup] (:434)
    let pp = ctx.permute(predictions, 0, 2, 1, 3);
    let predictions = ctx.cont(pp);
    let predictions = ctx.add(predictions, cur);
    ctx.set_name(predictions, &format!("predictions-{il}"));
    predictions
}

/// `graph::altup_correct` (gemma3n.cpp:444-464).
fn gemma3n_altup_correct(
    ctx: &mut Context,
    lw: &Gemma3nLayerWeights,
    p: &Gemma3nParams,
    predictions: TensorId, // {n_embd, T, n_altup}
    activated: TensorId,   // {n_embd, T}
    il: usize,
) -> TensorId {
    let (n_embd, t, n_altup) = {
        let ne = ctx.ne(predictions);
        (ne[0], ne[1], ne[2])
    };
    let modalities = gemma3n_altup_router_modalities(ctx, lw, p, activated, il);
    ctx.set_name(modalities, &format!("modalities-{il}"));

    let active_prediction = gemma3n_view_2d_slice(ctx, predictions, p.i_altup_act);
    let innovation = ctx.sub(activated, active_prediction);
    ctx.set_name(innovation, &format!("innovation-{il}"));

    let all_coefs = crate::adapter::lora_mm(ctx, lw.altup_correct_coef, modalities); // {n_altup, T}
    let all_coefs = ctx.scale_bias(all_coefs, 1.0, 1.0); // + 1.0
    ctx.set_name(all_coefs, &format!("all_coefs-{il}"));
    let all_coefs = ctx.transpose(all_coefs); // {T, n_altup}
    let all_coefs = ctx.cont_3d(all_coefs, 1, t, n_altup); // {1, T, n_altup}

    let innovation = ctx.repeat_4d(innovation, n_embd, t, n_altup, 1);
    let corrected = ctx.mul(innovation, all_coefs); // {n_embd, T, n_altup}
    let corrected = ctx.add(corrected, predictions);
    ctx.set_name(corrected, &format!("corrected-{il}"));
    corrected
}

/// verify against src/models/gemma3n.cpp:89-316 `graph::graph` —
/// scaled embeddings → altup stack projection → per layer (altup_predict →
/// attention (own KV | reused KV) + laurel → altup-correct → per-layer
/// embedding gate) → altup un-embedding merge → final RMS norm → soft-capped
/// lm_head.
///
/// The KV-reuse of the layers >= n_layer_kv_from_start reads the earlier
/// layer's cache rows (llama-model.cpp:2658-2666:
/// `n_layer_kv_from_start - (is_swa(il) ? 2 : 1)`) — the C bakes that into
/// the memory's layer map, this port points the builder at the target layer's
/// cache tensors (a builder-side reuse; the port's extra rows for the
/// reuse-only layers stay unwritten, mirroring the C's absent map entries).
///
/// PARTIAL (single-sequence driver): `build_inp_per_layer`'s multimodal half
/// (the ubatch.token == NULL branch, gemma3n.cpp:337-350) ports the padding
/// row through an F32 cpy cast but is exercised text-only here.
pub fn build_gemma3n_forward(
    ctx: &mut Context,
    w: &Gemma3nModelWeights,
    p: &Gemma3nParams,
    kv: &KvCache,
    inp: &DecodeInputs,
    sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let _ = sinfo;
    let t = n_tokens as i64;
    let n_layer = w.layers.len() as i64;
    let n_embd = p.n_embd;
    let n_embd_head = p.attn.n_embd_head_k;
    let n_head = p.attn.n_head;
    let n_head_kv = p.attn.n_head_kv;
    let n_altup = p.n_altup;
    let n_embd_altup = p.n_embd_altup;
    let mut graph = Graph::new(4096 + 1024 * n_layer as usize);

    // build_inp_embd, scaled by sqrt(n_embd) on the token path
    // (gemma3n.cpp:99-103 — the raw-embedding guard does not apply here: the
    // port's decode driver always carries tokens)
    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);
    let inp_l = ctx.scale(inp_l, (n_embd as f32).sqrt());
    ctx.set_name(inp_l, "inp_scaled--1");

    // build_inp_per_level (gemma3n.cpp:324-352) + project_per_level_inputs
    // (:357-376) — the token branch of the shared TAG_PER_LEVEL machinery
    let tok_embd_scale = (n_embd_altup as f32).sqrt();
    let mut ipl = ctx.get_rows(w.per_layer_tok_embd, inp.tokens);
    ipl = ctx.reshape_3d(ipl, n_embd_altup, n_layer, t);
    ipl = ctx.scale(ipl, tok_embd_scale);
    ctx.set_name(ipl, "inp_per_layer_selected--1");

    let per_layer_projection_scale = 1.0 / (n_embd as f32).sqrt();
    let per_layer_input_scale = 1.0 / std::f32::consts::SQRT_2;
    let mut proj = ctx.mul_mat(w.per_layer_model_proj, inp_l);
    proj = ctx.scale(proj, per_layer_projection_scale);
    proj = ctx.reshape_3d(proj, n_embd_altup, n_layer, t);
    let proj = build_norm_rms(ctx, proj, w.per_layer_proj_norm, p.norm_eps);
    ctx.set_name(proj, "per_layer_proj--1");

    let mut inp_per_layer = ctx.add(proj, ipl);
    inp_per_layer = ctx.scale(inp_per_layer, per_layer_input_scale);
    ctx.set_name(inp_per_layer, "inp_per_level--1");
    // permute to [n_embd_altup, T, n_layer] (gemma3n.cpp:374)
    let pp = ctx.permute(inp_per_layer, 0, 2, 1, 3);
    let inp_per_level = ctx.cont(pp);

    // the altup stack: project the single active altup to the rest
    // (gemma3n.cpp:119-128)
    let target_magnitude = gemma3n_calc_magnitude(ctx, inp_l);
    let inp_repeated = ctx.repeat_4d(inp_l, n_embd, t, n_altup - 1, 1);
    let mut altup_added = ctx.mul_mat(w.altup_proj, inp_repeated); // {n_embd, T, n_altup-1}
    let new_magnitude = gemma3n_calc_magnitude(ctx, altup_added);
    let am = ctx.mul(altup_added, target_magnitude);
    altup_added = ctx.div(am, new_magnitude);
    let mut inp_l = ctx.concat(inp_l, altup_added, 2); // {n_embd, T, n_altup}
    ctx.set_name(inp_l, "inp_stacked--1");

    for il in 0..n_layer as usize {
        let lw = &w.layers[il];

        // per-layer rope facts (gemma3n.cpp:133-134 → llama-model.cpp:2251-2258):
        // the SWA layers read the *_swa copies
        let (freq_base_l, freq_scale_l) = if p.is_swa[il] {
            (p.freq_base_swa, p.freq_scale_swa)
        } else {
            (p.attn.freq_base, p.attn.freq_scale)
        };

        let cur = inp_l; // {n_embd, T, n_altup}
        let predictions = gemma3n_altup_predict(ctx, lw, p, cur, il);

        let active_prediction = gemma3n_view_2d_slice(ctx, predictions, p.i_altup_act);
        let mut cur = active_prediction;
        ctx.set_name(cur, &format!("active_prediction-{il}"));

        cur = build_norm_rms(ctx, cur, lw.attn_norm, p.norm_eps);
        ctx.set_name(cur, &format!("attn_norm-{il}"));

        let laurel_out = gemma3n_laurel(ctx, lw, p, cur, il);

        // self-attention (gemma3n.cpp:152-198)
        let has_kv = (il as i64) < p.n_layer_kv_from_start;
        let cur = if has_kv {
            // build_qkv (llama-graph.cpp:1649-1735) — the qkv split of the
            // create_tensor_qkv load; gemma3n has no biases
            let (q, k, v) = match lw.wqkv {
                Some(wqkv) => {
                    let qkv = crate::adapter::lora_mm(ctx, wqkv, cur);
                    let q_dim = n_embd_head * n_head;
                    let kv_dim = n_embd_head * n_head_kv;
                    let nb1 = ctx.nb(qkv)[1] as usize;
                    let qv = ctx.view_2d(qkv, q_dim, t, nb1, 0);
                    let q = ctx.cont(qv);
                    let kv0 = ctx.view_2d(qkv, kv_dim, t, nb1, q_dim as usize * 4);
                    let k = ctx.cont(kv0);
                    let kv1 = ctx.view_2d(qkv, kv_dim, t, nb1, (q_dim + kv_dim) as usize * 4);
                    let v = ctx.cont(kv1);
                    (q, k, v)
                }
                None => {
                    let q = crate::adapter::lora_mm(ctx, lw.wq.expect("wq"), cur);
                    let k = crate::adapter::lora_mm(ctx, lw.wk.expect("wk"), cur);
                    let v = crate::adapter::lora_mm(ctx, lw.wv.expect("wv"), cur);
                    (q, k, v)
                }
            };
            let q = ctx.reshape_3d(q, n_embd_head, n_head, t);
            let k = ctx.reshape_3d(k, n_embd_head, n_head_kv, t);
            let v = ctx.reshape_3d(v, n_embd_head, n_head_kv, t);

            let q = build_norm_rms(ctx, q, lw.attn_q_norm, p.norm_eps);
            let k = build_norm_rms(ctx, k, lw.attn_k_norm, p.norm_eps);
            let v = ctx.rms_norm(v, p.norm_eps);
            ctx.set_name(q, &format!("Qcur_normed-{il}"));
            ctx.set_name(k, &format!("Kcur_normed-{il}"));
            ctx.set_name(v, &format!("Vcur_normed-{il}"));

            let q = ctx.rope_ext(
                q,
                inp.pos,
                None,
                p.attn.n_rot as i32,
                p.attn.rope_mode,
                p.attn.n_ctx_orig,
                freq_base_l,
                freq_scale_l,
                p.attn.ext_factor,
                p.attn.attn_factor,
                p.attn.beta_fast,
                p.attn.beta_slow,
            );
            let k = ctx.rope_ext(
                k,
                inp.pos,
                None,
                p.attn.n_rot as i32,
                p.attn.rope_mode,
                p.attn.n_ctx_orig,
                freq_base_l,
                freq_scale_l,
                p.attn.ext_factor,
                p.attn.attn_factor,
                p.attn.beta_fast,
                p.attn.beta_slow,
            );
            ctx.set_name(q, &format!("Qcur_pos-{il}"));
            ctx.set_name(k, &format!("Kcur_pos-{il}"));

            gemma3n_attn(
                ctx,
                &mut graph,
                kv,
                il,
                il,
                &p.attn,
                inp,
                n_kv,
                lw.wo,
                q,
                Some(k),
                Some(v),
                p.f_attention_scale,
            )
        } else {
            // reuse the KV of the earlier layer (gemma3n.cpp:176-198; the C's
            // layer_reuse_cb, llama-model.cpp:2658-2666 — 0-based layer ids)
            let reuse_to = (p.n_layer_kv_from_start - if p.is_swa[il] { 2 } else { 1 }) as usize;
            let qcur = match lw.wqkv {
                Some(wqkv) => {
                    let qkv = crate::adapter::lora_mm(ctx, wqkv, cur);
                    let q_dim = n_embd_head * n_head;
                    let qv = ctx.view_2d(qkv, q_dim, t, ctx.nb(qkv)[1] as usize, 0);
                    ctx.cont(qv)
                }
                None => crate::adapter::lora_mm(ctx, lw.wq.expect("wq"), cur),
            };
            let qcur = ctx.reshape_3d(qcur, n_embd_head, n_head, t);
            let qcur = build_norm_rms(ctx, qcur, lw.attn_q_norm, p.norm_eps);
            ctx.set_name(qcur, &format!("Qcur_normed-{il}"));
            let qcur = ctx.rope_ext(
                qcur,
                inp.pos,
                None,
                p.attn.n_rot as i32,
                p.attn.rope_mode,
                p.attn.n_ctx_orig,
                freq_base_l,
                freq_scale_l,
                p.attn.ext_factor,
                p.attn.attn_factor,
                p.attn.beta_fast,
                p.attn.beta_slow,
            );
            ctx.set_name(qcur, &format!("Qcur_pos-{il}"));

            gemma3n_attn(
                ctx,
                &mut graph,
                kv,
                il,
                reuse_to,
                &p.attn,
                inp,
                n_kv,
                lw.wo,
                qcur,
                None,
                None,
                p.f_attention_scale,
            )
        };
        let cur = build_norm_rms(ctx, cur, lw.attn_post_norm, p.norm_eps);
        ctx.set_name(cur, &format!("attn_post_norm-{il}"));

        let cur = ctx.add(cur, active_prediction);
        ctx.set_name(cur, &format!("attn_gated-{il}"));

        let al = ctx.add(cur, laurel_out);
        let attn_laurel = ctx.scale(al, 1.0 / std::f32::consts::SQRT_2);
        ctx.set_name(attn_laurel, &format!("attn_laurel-{il}"));

        let mut cur = build_norm_rms(ctx, attn_laurel, lw.ffn_norm, p.norm_eps);
        ctx.set_name(cur, &format!("ffn_norm-{il}"));

        // gelu-par FFN with optional gaussian-topk sparsity (:213-226)
        let up_proj = crate::adapter::lora_mm(ctx, lw.ffn_up, cur);
        let mut gate_proj = crate::adapter::lora_mm(ctx, lw.ffn_gate, cur);
        if (il as i64) < p.n_layer_sparsity {
            gate_proj = gemma3n_gaussian_topk(ctx, gate_proj, p.f_sparsity_std_mul);
        }
        gate_proj = ctx.gelu(gate_proj);
        let mut cur = ctx.mul(up_proj, gate_proj);
        cur = crate::adapter::lora_mm(ctx, lw.ffn_down, cur);
        ctx.set_name(cur, &format!("ffn_out-{il}"));

        let cur = build_norm_rms(ctx, cur, lw.ffn_post_norm, p.norm_eps);
        ctx.set_name(cur, &format!("ffn_post_norm-{il}"));

        let attn_ffw_laurel_gated = ctx.add(cur, attn_laurel);
        ctx.set_name(
            attn_ffw_laurel_gated,
            &format!("attn_ffw_laurel_gated-{il}"),
        );

        let mut corrected =
            gemma3n_altup_correct(ctx, lw, p, predictions, attn_ffw_laurel_gated, il);

        // corrected[1:] += first_prediction (:235-260)
        let mut first_prediction = gemma3n_view_2d_slice(ctx, corrected, p.i_altup_act);
        first_prediction = ctx.mul(first_prediction, lw.altup_correct_scale);
        first_prediction = crate::adapter::lora_mm(ctx, lw.per_layer_inp_gate, first_prediction);
        first_prediction = ctx.gelu(first_prediction); // {n_embd_altup, T}
        ctx.set_name(first_prediction, &format!("first_prediction_gated-{il}"));

        let inp_this_layer = gemma3n_view_2d_slice(ctx, inp_per_level, il as i64);
        first_prediction = ctx.mul(first_prediction, inp_this_layer);
        ctx.set_name(first_prediction, &format!("first_prediction_scaled-{il}"));

        first_prediction = crate::adapter::lora_mm(ctx, lw.per_layer_proj, first_prediction);
        first_prediction =
            build_norm_rms(ctx, first_prediction, lw.per_layer_post_norm, p.norm_eps);
        ctx.set_name(first_prediction, &format!("first_prediction_out-{il}"));

        {
            let corrected_ty_row = GgmlType::F32.row_size(n_embd as usize);
            let corrected_ty_row2 = GgmlType::F32.row_size((n_embd * t) as usize);
            let slice_first = gemma3n_view_2d_slice(ctx, corrected, 0);
            let slice_rest = ctx.view_3d(
                corrected,
                n_embd,
                t,
                n_altup - 1,
                corrected_ty_row,
                corrected_ty_row2,
                (n_embd * t) as usize * 4,
            );
            let tmp = ctx.add(slice_rest, first_prediction); // {n_embd, T, n_altup-1}
            corrected = ctx.concat(slice_first, tmp, 2); // {n_embd, T, n_altup}
        }
        let cur = corrected;
        inp_l = cur;
    }

    // merge the altups back to one (:270-290)
    let cur = {
        let cur_ty_row = GgmlType::F32.row_size(n_embd as usize);
        let cur_ty_row2 = GgmlType::F32.row_size((n_embd * t) as usize);
        let act_slice = gemma3n_view_2d_slice(ctx, inp_l, p.i_altup_act);
        let target_magnitude = gemma3n_calc_magnitude(ctx, act_slice);
        let alt_slice = ctx.view_3d(
            inp_l,
            n_embd,
            t,
            n_altup - 1,
            cur_ty_row,
            cur_ty_row2,
            (n_embd * t) as usize * 4,
        );
        let mut altup_unembd = ctx.mul_mat(w.altup_unembd_proj, alt_slice); // {n_embd, T, n_altup-1}
        let new_magnitude = gemma3n_calc_magnitude(ctx, altup_unembd);
        let am = ctx.mul(altup_unembd, target_magnitude);
        altup_unembd = ctx.div(am, new_magnitude);
        ctx.set_name(altup_unembd, "altup_unembd--1");

        // torch.mean(hidden_states, dim=0)
        let mut cur = gemma3n_view_2d_slice(ctx, inp_l, 0);
        for i in 0..(n_altup - 1) {
            let slice = gemma3n_view_2d_slice(ctx, altup_unembd, i);
            cur = ctx.add(cur, slice);
        }
        ctx.scale(cur, 1.0 / n_altup as f32)
    };
    ctx.set_name(cur, "unembd_merged--1");

    // final norm + soft-capped lm_head (:293-315)
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let embd = build_norm_rms(ctx, cur, w.output_norm, p.norm_eps);
    ctx.set_name(embd, "result_norm--1");
    let mut cur = crate::adapter::lora_mm(ctx, w.output, embd);
    if p.f_final_logit_softcapping != 0.0 {
        cur = ctx.scale(cur, 1.0 / p.f_final_logit_softcapping);
        cur = ctx.tanh(cur);
        cur = ctx.scale(cur, p.f_final_logit_softcapping);
    }
    ctx.set_name(cur, "result_output--1");
    graph.build_forward(ctx, cur);
    ForwardResult {
        logits: cur,
        graph,
        embd: Some(embd),
    }
}

/// gemma3n's `build_attn` call — the per-layer iswa cache selection of
/// `attn_kv_cached` with `wo` applied inline (build_attn's `build_lora_mm(wo,
/// cur)`, llama-graph.cpp:2906-2921), plus the KV-reuse retarget
/// (`read_layer`): a layer without its own KV scatters nothing and reads the
/// target layer's rows (llama-model.cpp:2658-2666).
#[allow(clippy::too_many_arguments)]
fn gemma3n_attn(
    ctx: &mut Context,
    graph: &mut Graph,
    kv: &KvCache,
    il: usize,
    read_layer: usize,
    p: &AttnParams,
    inp: &DecodeInputs,
    n_kv: u32,
    wo: TensorId,
    q: TensorId,
    k: Option<TensorId>,
    v: Option<TensorId>,
    f_attention_scale: f32,
) -> TensorId {
    let t = ctx.ne(q)[2];
    // gemma3n.cpp:174 passes hparams.f_attention_scale (1.0) straight through
    // as build_attn's kq_scale — no 1/sqrt(head_dim) at this call site
    let kq_scale = f_attention_scale;

    let is_swa = kv.layer_is_swa(read_layer);
    let (row_idx, kq_mask, n_kv) = if is_swa {
        let step = kv
            .swa_step
            .expect("SWA layer without the iswa step inputs (KvCache::swa_step)");
        (step.row_idx, step.kq_mask, kv.n_kv_swa())
    } else {
        (inp.row_idx, inp.kq_mask, n_kv)
    };

    // scatter the layer's own k/v (skip on the reuse path — k/v are None)
    if let (Some(k), Some(v)) = (k, v) {
        let nb2k = ctx.nb(k)[2] as usize;
        let nb2v = ctx.nb(v)[2] as usize;
        let k_rows = ctx.view_2d(k, p.n_embd_head_k * p.n_head_kv, t, nb2k, 0);
        let v_rows = ctx.view_2d(v, p.n_embd_head_v * p.n_head_kv, t, nb2v, 0);
        let k_dst = ctx.set_rows(kv.layers[il].k, k_rows, row_idx);
        let v_dst = ctx.set_rows(kv.layers[il].v, v_rows, row_idx);
        if il == 0 {
            ctx.set_name(v_dst, "vstore-0");
            ctx.set_name(v_rows, "vrows-0");
            ctx.set_name(k_dst, "kstore-0");
        }
        graph.build_forward(ctx, k_dst);
        graph.build_forward(ctx, v_dst);
    }

    // cache views of the layer (own) or the reuse target
    let k_view = kv.get_k(ctx, read_layer, p.n_embd_head_k, p.n_head_kv, n_kv);
    let v_view = kv.get_v(ctx, read_layer, p.n_embd_head_v, p.n_head_kv, n_kv);

    if p.use_flash_attn {
        let kqv = graph::flash_attn_core(ctx, q, k_view, v_view, kq_mask, kq_scale, 0.0, 0.0);
        ctx.set_name(kqv, &format!("kqv_out-{il}"));
        return crate::adapter::lora_mm(ctx, wo, kqv);
    }
    let q = ctx.permute(q, 0, 2, 1, 3);
    let k_view = ctx.permute(k_view, 0, 2, 1, 3);
    let mut kq = ctx.mul_mat(k_view, q);
    ctx.set_name(kq, &format!("kq-{il}"));
    kq = ctx.soft_max_ext(kq, Some(kq_mask), kq_scale, 0.0);
    ctx.set_name(kq, &format!("kq_soft_max-{il}"));
    let v_view = ctx.permute(v_view, 0, 2, 1, 3);
    let v_t = ctx.transpose(v_view);
    let v_c = ctx.cont(v_t);
    let kqv = ctx.mul_mat(v_c, kq);
    ctx.set_name(v_c, &format!("v_cont-{il}"));
    ctx.set_name(kqv, &format!("kqv-{il}"));
    let kqv = ctx.permute(kqv, 0, 2, 1, 3);
    let kqv = ctx.cont(kqv);
    let kqv = ctx.reshape_2d(kqv, p.n_embd_head_v * p.n_head, t);
    ctx.set_name(kqv, &format!("kqv_out-{il}"));
    crate::adapter::lora_mm(ctx, wo, kqv)
}

// ===========================================================================
// arch batch 15 (2026-10) — the P1+P2 queue of parity/AUDIT_models.md:
// qwen(v1) / maincoder / pangu-embed / plm / cogvlm / spark2-5 / muse-glimmer
// / llada / hunyuan-vl(+dense) / granite-swa / afmoe / mellum / paddleocr /
// gemma-embedding / llama-embed / mistral4 / hy-v3 / hy-v4 / mimo2 / step35
// (+ gemma4-assistant, the ctx_other draft — documented-skip, see PARITY.md
// batch 15). Every builder is a 1:1 port of its src/models/<arch>.cpp graph;
// the iswa members (spark2-5 / muse-glimmer / granite-swa / afmoe / mellum /
// mimo2 / step35) ride the port's per-layer cache selection like batch 8+.
// ===========================================================================

// ----------------------------------------------------------------------
// qwen (v1) — src/models/qwen.cpp:43-140 (the fused-QKV+bias decoder with
// the half-width SwiGLU FFN)
// ----------------------------------------------------------------------

pub struct Qwen1LayerWeights {
    pub attn_norm: TensorId,
    /// {n_embd, n_embd*3} + {n_embd*3} bias (qwen.cpp:27-28 — MHA layout)
    pub wqkv: TensorId,
    pub wqkv_b: TensorId,
    pub wo: TensorId,
    pub ffn_norm: TensorId,
    /// {n_embd, n_ff/2} (qwen.cpp:33-35 — the FFN runs at half width)
    pub ffn_gate: TensorId,
    pub ffn_down: TensorId,
    pub ffn_up: TensorId,
}

pub struct Qwen1ModelWeights {
    pub tok_embd: TensorId,
    pub output_norm: TensorId,
    pub output: TensorId,
    pub layers: Vec<Qwen1LayerWeights>,
}

#[derive(Clone)]
pub struct Qwen1Params {
    pub attn: AttnParams,
    pub norm_rms_eps: f32,
}

/// verify against src/models/qwen.cpp:43-140. Plain pre-norm decoder: fused wqkv (+bias)
/// → NEOX rope → MHA → SwiGLU at n_ff/2 (gate/up {n_embd, n_ff/2}, down
/// {n_ff/2, n_embd}); head is separate (qwen.cpp:20, required).
pub fn build_qwen1_forward(
    ctx: &mut Context,
    w: &Qwen1ModelWeights,
    p: &Qwen1Params,
    kv: &KvCache,
    inp: &DecodeInputs,
    _sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(1024);
    assert_eq!(p.attn.n_embd_head_v, p.attn.n_embd_head_k, "qwen.cpp:45");

    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_sa = inp_l;

        let cur = build_norm_rms(ctx, inp_l, lw.attn_norm, p.norm_rms_eps);

        let (q, k, v) = qkv_fused(ctx, lw.wqkv, Some(lw.wqkv_b), &p.attn, cur, t);
        let (q, k) = rope_qk(ctx, &p.attn, inp.pos, q, k);

        let kq_scale = 1.0 / (p.attn.n_embd_head_k as f32).sqrt();
        let cur = attn_kv_cached(
            ctx,
            &mut graph,
            kv,
            il,
            &p.attn,
            inp,
            n_kv,
            q,
            k,
            v,
            kq_scale,
            0.0,
            None,
            None,
            Some(lw.wo),
            None,
        );

        let ffn_inp = ctx.add(cur, inp_sa);
        let cur = build_norm_rms(ctx, ffn_inp, lw.ffn_norm, p.norm_rms_eps);
        let cur = build_ffn_silu_par(
            ctx,
            cur,
            lw.ffn_gate,
            None,
            lw.ffn_up,
            None,
            lw.ffn_down,
            None,
        );
        inp_l = ctx.add(cur, ffn_inp);
    }

    let cur = build_norm_rms(ctx, inp_l, w.output_norm, p.norm_rms_eps);
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let logits = crate::adapter::lora_mm(ctx, w.output, cur);
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

// ----------------------------------------------------------------------
// maincoder — src/models/maincoder.cpp:47-151 (QK-norm AFTER rope)
// ----------------------------------------------------------------------

pub struct MaincoderLayerWeights {
    pub attn_norm: TensorId,
    pub wqkv: Option<TensorId>,
    pub wqkv_b: Option<TensorId>,
    pub wq: Option<TensorId>,
    pub wq_b: Option<TensorId>,
    pub wk: Option<TensorId>,
    pub wk_b: Option<TensorId>,
    pub wv: Option<TensorId>,
    pub wv_b: Option<TensorId>,
    /// {n_embd_head_k * n_head, n_embd} (maincoder.cpp:31 — the Q width, not
    /// n_embd: head_dim may differ)
    pub wo: TensorId,
    pub attn_q_norm: TensorId,
    pub attn_k_norm: TensorId,
    pub ffn_norm: TensorId,
    pub ffn_gate: TensorId,
    pub ffn_down: TensorId,
    pub ffn_up: TensorId,
}

pub struct MaincoderModelWeights {
    pub tok_embd: TensorId,
    pub output_norm: TensorId,
    /// maincoder.cpp:19-23 — optional head with the tok_embd fallback
    pub output: TensorId,
    pub layers: Vec<MaincoderLayerWeights>,
}

#[derive(Clone)]
pub struct MaincoderParams {
    pub attn: AttnParams,
    pub norm_rms_eps: f32,
}

/// verify against src/models/maincoder.cpp:47-151. The Q/K RMS norms run AFTER the
/// rope (:92-96), on the per-head [n_embd_head_k] weights; FFN is plain
/// SwiGLU at full width.
pub fn build_maincoder_forward(
    ctx: &mut Context,
    w: &MaincoderModelWeights,
    p: &MaincoderParams,
    kv: &KvCache,
    inp: &DecodeInputs,
    _sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(1024);
    assert_eq!(
        p.attn.n_embd_head_v, p.attn.n_embd_head_k,
        "maincoder.cpp:48"
    );
    assert_eq!(p.attn.n_embd_head_k, p.attn.n_rot, "maincoder.cpp:50");

    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_sa = inp_l;

        let cur = build_norm_rms(ctx, inp_l, lw.attn_norm, p.norm_rms_eps);

        let (q, k, v) = if let Some(wqkv) = lw.wqkv {
            qkv_fused(ctx, wqkv, lw.wqkv_b, &p.attn, cur, t)
        } else {
            qkv_separate_parts(
                ctx,
                lw.wq.expect("maincoder wq"),
                lw.wq_b,
                lw.wk.expect("maincoder wk"),
                lw.wk_b,
                lw.wv.expect("maincoder wv"),
                lw.wv_b,
                &p.attn,
                cur,
                t,
            )
        };
        // rope FIRST (:80-90), then the Q/K norms (:92-96)
        let (q_r, k_r) = rope_qk(ctx, &p.attn, inp.pos, q, k);
        let q = build_norm_rms(ctx, q_r, lw.attn_q_norm, p.norm_rms_eps);
        let k = build_norm_rms(ctx, k_r, lw.attn_k_norm, p.norm_rms_eps);

        let kq_scale = 1.0 / (p.attn.n_embd_head_k as f32).sqrt();
        let cur = attn_kv_cached(
            ctx,
            &mut graph,
            kv,
            il,
            &p.attn,
            inp,
            n_kv,
            q,
            k,
            v,
            kq_scale,
            0.0,
            None,
            None,
            Some(lw.wo),
            None,
        );

        let ffn_inp = ctx.add(cur, inp_sa);
        let cur = build_norm_rms(ctx, ffn_inp, lw.ffn_norm, p.norm_rms_eps);
        let cur = build_ffn_silu_par(
            ctx,
            cur,
            lw.ffn_gate,
            None,
            lw.ffn_up,
            None,
            lw.ffn_down,
            None,
        );
        inp_l = ctx.add(cur, ffn_inp);
    }

    let cur = build_norm_rms(ctx, inp_l, w.output_norm, p.norm_rms_eps);
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let logits = crate::adapter::lora_mm(ctx, w.output, cur);
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

