// cogvlm — src/models/cogvlm.cpp:53-158 (the text/vision dual-weight decoder;
// the text batch runs the plain path, the embd batch the visexp twins)
// ----------------------------------------------------------------------

pub struct CogvlmLayerWeights {
    pub attn_norm: TensorId,
    /// text path (cogvlm.cpp:30-31)
    pub wqkv: TensorId,
    pub wo: TensorId,
    /// vision-expert twins (:33-34 — same shapes, required)
    pub visexp_attn_wqkv: TensorId,
    pub visexp_attn_wo: TensorId,
    pub ffn_norm: TensorId,
    pub ffn_gate: TensorId,
    pub ffn_down: TensorId,
    pub ffn_up: TensorId,
    pub visexp_ffn_gate: TensorId,
    pub visexp_ffn_down: TensorId,
    pub visexp_ffn_up: TensorId,
}

pub struct CogvlmModelWeights {
    pub tok_embd: TensorId,
    pub output_norm: TensorId,
    /// cogvlm.cpp:19-24 — optional head with the tok_embd fallback
    pub output: TensorId,
    pub layers: Vec<CogvlmLayerWeights>,
}

#[derive(Clone)]
pub struct CogvlmParams {
    pub attn: AttnParams,
    pub norm_rms_eps: f32,
}

/// verify against src/models/cogvlm.cpp:53-158. The QKV split views the fused tensor
/// with the **plain** `ggml_rope` (not rope_ext — :115-116: default
/// freq_base 10000 / freq_scale 1 / no yarn), and the layer weights are
/// picked per batch: `is_text = ubatch.token != nullptr` (:73-77) — the
/// decode path always carries tokens (the text weights); the visexp twins
/// run only for image-embedding ubatches (the mmproj side, out of the LM
/// trunk's decode path). wo_s of the vision twin is nullptr (:94).
pub fn build_cogvlm_forward(
    ctx: &mut Context,
    w: &CogvlmModelWeights,
    p: &CogvlmParams,
    kv: &KvCache,
    inp: &DecodeInputs,
    _sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(1024);
    assert_eq!(p.attn.n_embd_head_v, p.attn.n_embd_head_k, "cogvlm.cpp:58");
    assert_eq!(p.attn.n_embd_head_k, p.attn.n_rot, "cogvlm.cpp:59");

    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);
    ctx.set_name(inp_l, "embd");

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_sa = inp_l;

        let cur = build_norm_rms(ctx, inp_l, lw.attn_norm, p.norm_rms_eps);
        ctx.set_name(cur, &format!("attn_norm-{il}"));

        // is_text (:73-77) — the decode path carries tokens, so the text
        // weights run (the port's decode driver is token-driven)
        let (wqkv, wo, ffn_gate, ffn_down, ffn_up) =
            (lw.wqkv, lw.wo, lw.ffn_gate, lw.ffn_down, lw.ffn_up);
        let _ = (lw.visexp_attn_wqkv, lw.visexp_attn_wo);

        // qkv = build_lora_mm(wqkv, cur) + the three view_3d segments
        // (:105-113 — the K/V offsets are n_embd*esize / 2*n_embd*esize,
        // i.e. the MHA thirds)
        let qkv = crate::adapter::lora_mm(ctx, wqkv, cur);
        let nb1 = ctx.nb(qkv)[1] as usize;
        let hd = p.attn.n_embd_head_k as usize;
        // cogvlm.cpp:110-113 — the K/V offsets are n_embd-sized (MHA thirds)
        let n_embd_bytes = (p.attn.n_embd_head_k * p.attn.n_head) as usize * 4;
        let q = ctx.view_3d(qkv, p.attn.n_embd_head_k, p.attn.n_head, t, hd * 4, nb1, 0);
        let k = ctx.view_3d(
            qkv,
            p.attn.n_embd_head_k,
            p.attn.n_head_kv,
            t,
            hd * 4,
            nb1,
            n_embd_bytes,
        );
        let v = ctx.view_3d(
            qkv,
            p.attn.n_embd_head_v,
            p.attn.n_head_kv,
            t,
            p.attn.n_embd_head_v as usize * 4,
            nb1,
            2 * n_embd_bytes,
        );

        // plain ggml_rope (cogvlm.cpp:115-116) — default params, NEOX mode
        let rope = |ctx: &mut Context, x: TensorId| {
            ctx.rope_ext(
                x,
                inp.pos,
                None,
                p.attn.n_rot as i32,
                p.attn.rope_mode,
                0,
                10_000.0,
                1.0,
                0.0,
                1.0,
                32.0,
                1.0,
            )
        };
        let q = rope(ctx, q);
        ctx.set_name(q, &format!("Qcur-{il}"));
        let k = rope(ctx, k);
        ctx.set_name(k, &format!("Kcur-{il}"));

        let kq_scale = 1.0 / (p.attn.n_embd_head_k as f32).sqrt();
        let cur = attn_kv_cached(
            ctx,
            &mut graph,
            kv,
            il,
            &p.attn,
            inp,
            n_kv,
            q,
            k,
            v,
            kq_scale,
            0.0,
            None,
            None,
            Some(wo),
            None,
        );

        let ffn_inp = ctx.add(cur, inp_sa);
        ctx.set_name(ffn_inp, &format!("ffn_inp-{il}"));
        let cur = build_norm_rms(ctx, ffn_inp, lw.ffn_norm, p.norm_rms_eps);
        ctx.set_name(cur, &format!("ffn_norm-{il}"));
        let cur = build_ffn_silu_par(ctx, cur, ffn_gate, None, ffn_up, None, ffn_down, None);
        ctx.set_name(cur, &format!("ffn_out-{il}"));
        inp_l = ctx.add(cur, ffn_inp);
        ctx.set_name(inp_l, &format!("l_out-{il}"));
    }

    let cur = build_norm_rms(ctx, inp_l, w.output_norm, p.norm_rms_eps);
    ctx.set_name(cur, "result_norm");
    // cogvlm has no last-layer inp_out_ids gather (its graph expands all
    // rows); out_rows is the value-identical row selection of the driver
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let logits = crate::adapter::lora_mm(ctx, w.output, cur);
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

