#[derive(Clone)]
pub struct LladaParams {
    pub attn: AttnParams,
    pub norm_rms_eps: f32,
}

/// verify against src/models/llada.cpp:66-153. hparams.causal_attn = false (:16) +
/// build_attn_inp_no_cache (:82) — the same non-causal [T, T] mask family
/// dream/rnd1 run. The FFN bias tensors are loaded (NOT_REQUIRED) but the
/// graph's build_ffn call passes nullptrs (:124-128), so they stay unused.
pub fn build_llada_forward(
    ctx: &mut Context,
    w: &LladaModelWeights,
    p: &LladaParams,
    _kv: &KvCache,
    inp: &DecodeInputs,
    _sinfo: SlotInfo,
    _n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(1024);
    assert_eq!(p.attn.n_embd_head_v, p.attn.n_embd_head_k, "llada.cpp:70");
    assert_eq!(p.attn.n_embd_head_k, p.attn.n_rot, "llada.cpp:71");

    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    // build_attn_inp_no_cache (llada.cpp:82): the [t, t] all-visible mask;
    // F16 under FA (llama-graph.cpp:2748)
    let mask_ty = if p.attn.use_flash_attn {
        GgmlType::F16
    } else {
        GgmlType::F32
    };
    let kq_mask = ctx.new_tensor_2d(mask_ty, t, t);
    ctx.arena_resize_tensor(kq_mask);
    ctx.data_bytes_mut(kq_mask).unwrap().fill(0);

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_sa = inp_l;

        let cur = build_norm_rms(ctx, inp_l, lw.attn_norm, p.norm_rms_eps);

        let (q, k, v) = if let Some(wqkv) = lw.wqkv {
            qkv_fused(ctx, wqkv, lw.wqkv_b, &p.attn, cur, t)
        } else {
            qkv_separate_parts(
                ctx,
                lw.wq.expect("llada wq"),
                lw.wq_b,
                lw.wk.expect("llada wk"),
                lw.wk_b,
                lw.wv.expect("llada wv"),
                lw.wv_b,
                &p.attn,
                cur,
                t,
            )
        };
        let (q, k) = rope_qk(ctx, &p.attn, inp.pos, q, k);

        let kq_scale = 1.0 / (p.attn.n_embd_head_k as f32).sqrt();
        let cur = attn_no_cache_fa(
            ctx,
            q,
            k,
            v,
            kq_mask,
            kq_scale,
            p.attn.use_flash_attn,
            Some(lw.wo),
            lw.wo_b,
        );

        let ffn_inp = ctx.add(cur, inp_sa);
        let cur = build_norm_rms(ctx, ffn_inp, lw.ffn_norm, p.norm_rms_eps);
        let cur = build_ffn_silu_par(
            ctx,
            cur,
            lw.ffn_gate,
            None,
            lw.ffn_up,
            None,
            lw.ffn_down,
            None,
        );
        inp_l = ctx.add(cur, ffn_inp);
    }

    let cur = build_norm_rms(ctx, inp_l, w.output_norm, p.norm_rms_eps);
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let mut logits = crate::adapter::lora_mm(ctx, w.output, cur);
    if let Some(b) = w.output_b {
        logits = ctx.add(logits, b);
    }
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

