// plm — src/models/plm.cpp:48-206 (the MLA-lite arch: full-width Q heads,
// the shared k_pe repeated across heads, relu² FFN, tied head)
// ----------------------------------------------------------------------

pub struct PlmLayerWeights {
    pub attn_norm: TensorId,
    /// {n_embd, n_embd_head_k * n_head} (plm.cpp:32)
    pub wq: TensorId,
    /// {n_embd, kv_lora_rank + n_rot} (:33)
    pub wkv_a_mqa: TensorId,
    /// {kv_lora_rank} (:34)
    pub attn_kv_a_norm: TensorId,
    /// {kv_lora_rank, n_head * (qk_nope + n_embd_head_v)} (:35)
    pub wkv_b: TensorId,
    /// {n_head * n_embd_head_v, n_embd} (:36)
    pub wo: TensorId,
    pub ffn_norm: TensorId,
    pub ffn_down: TensorId,
    pub ffn_up: TensorId,
}

pub struct PlmModelWeights {
    pub tok_embd: TensorId,
    pub output_norm: TensorId,
    /// plm.cpp:24-25 — tied to tok_embd (TENSOR_DUPLICATED)
    pub output: TensorId,
    pub layers: Vec<PlmLayerWeights>,
}

#[derive(Clone)]
pub struct PlmParams {
    pub attn: AttnParams,
    pub norm_rms_eps: f32,
    pub kv_lora_rank: i64,
}

/// verify against src/models/plm.cpp:48-206. The K rows are the concat of the
/// per-head k_nope and the shared roped k_pe repeated over heads
/// (:155-157); V is the decompressed [n_embd_head_v*n_head, T] 2D view —
/// reshaped to the [hd, n_head, T] layout the cache scatter expects (same
/// contiguous bytes). FFN is relu²-SEQ; kq_scale = 1/sqrt(n_embd_head_k).
pub fn build_plm_forward(
    ctx: &mut Context,
    w: &PlmModelWeights,
    p: &PlmParams,
    kv: &KvCache,
    inp: &DecodeInputs,
    _sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(1024);

    let n_head = p.attn.n_head;
    let n_embd_head_k = p.attn.n_embd_head_k;
    let n_embd_head_qk_rope = p.attn.n_rot;
    let n_embd_head_qk_nope = n_embd_head_k - n_embd_head_qk_rope;
    let kv_lora_rank = p.kv_lora_rank;
    let n_embd_head_v = p.attn.n_embd_head_v;
    let kq_scale = 1.0 / (n_embd_head_k as f32).sqrt();

    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_sa = inp_l;

        let cur = build_norm_rms(ctx, inp_l, lw.attn_norm, p.norm_rms_eps);

        // q = wq @ cur, reshaped to heads (:81-85)
        let mut q = ctx.mul_mat(lw.wq, cur);
        q = ctx.reshape_3d(q, n_embd_head_k, n_head, t);

        // kv_pe_compresseed = wkv_a_mqa @ cur (:89)
        let kv_pe_compresseed = ctx.mul_mat(lw.wkv_a_mqa, cur);
        let kv_ty = ctx.ty(kv_pe_compresseed);
        let rs_row = kv_ty.row_size((kv_lora_rank + n_embd_head_qk_rope) as usize);

        // kv_compressed view {kv_lora_rank, T} (:93-95)
        let kv_compressed = ctx.view_2d(kv_pe_compresseed, kv_lora_rank, t, rs_row, 0);
        // k_pe view {n_rot, 1, T} (:99-102)
        let k_pe = ctx.view_3d(
            kv_pe_compresseed,
            n_embd_head_qk_rope,
            1,
            t,
            rs_row,
            rs_row,
            kv_ty.row_size(kv_lora_rank as usize),
        );

        let kv_compressed = build_norm_rms(ctx, kv_compressed, lw.attn_kv_a_norm, p.norm_rms_eps);

        // kv = wkv_b @ kv_compressed (:111)
        let kvb = ctx.mul_mat(lw.wkv_b, kv_compressed);
        let kv_ty = ctx.ty(kvb);
        let n_embd_kv = n_embd_head_qk_nope + n_embd_head_v;

        // k_nope {qk_nope, n_head, T} (:115-118)
        let k_nope = ctx.view_3d(
            kvb,
            n_embd_head_qk_nope,
            n_head,
            t,
            kv_ty.row_size(n_embd_kv as usize),
            kv_ty.row_size((n_embd_kv * n_head) as usize),
            0,
        );
        // v_states {hd_v, n_head, T} (:122-126) → cont → the 2D view of
        // :131-133 (the port re-3D-shapes for the cache scatter — same bytes)
        let v_states = ctx.view_3d(
            kvb,
            n_embd_head_v,
            n_head,
            t,
            kv_ty.row_size(n_embd_kv as usize),
            kv_ty.row_size((n_embd_kv * n_head) as usize),
            kv_ty.row_size(n_embd_head_qk_nope as usize),
        );
        let v_states = ctx.cont(v_states);

        // q rope over the trailing n_rot dims + the nope offset (:136-141)
        let q = ctx.rope_ext(
            q,
            inp.pos,
            None,
            p.attn.n_rot as i32,
            p.attn.rope_mode,
            p.attn.n_ctx_orig,
            p.attn.freq_base,
            p.attn.freq_scale,
            p.attn.ext_factor,
            p.attn.attn_factor,
            p.attn.beta_fast,
            p.attn.beta_slow,
        );
        let q = ctx.rope_set_offset(q, n_embd_head_qk_nope as i32);

        // shared roped k_pe (:145-149)
        let k_pe = ctx.rope_ext(
            k_pe,
            inp.pos,
            None,
            p.attn.n_rot as i32,
            p.attn.rope_mode,
            p.attn.n_ctx_orig,
            p.attn.freq_base,
            p.attn.freq_scale,
            p.attn.ext_factor,
            p.attn.attn_factor,
            p.attn.beta_fast,
            p.attn.beta_slow,
        );

        // k_states = concat(k_nope, repeat_4d(k_pe, ...), 0) (:155-157)
        let k_pe_rep = ctx.repeat_4d(k_pe, n_embd_head_qk_rope, n_head, t, 1);
        let k_states = ctx.concat(k_nope, k_pe_rep, 0);

        let cur = attn_kv_cached(
            ctx,
            &mut graph,
            kv,
            il,
            &p.attn,
            inp,
            n_kv,
            q,
            k_states,
            v_states,
            kq_scale,
            0.0,
            None,
            None,
            Some(lw.wo),
            None,
        );

        let ffn_inp = ctx.add(cur, inp_sa);
        let cur = build_norm_rms(ctx, ffn_inp, lw.ffn_norm, p.norm_rms_eps);
        // relu² SEQ, no gate (plm.cpp:175-180)
        let cur = build_ffn_relu_sqr(ctx, cur, lw.ffn_up, None, lw.ffn_down, None);
        inp_l = ctx.add(cur, ffn_inp);
    }

    let cur = build_norm_rms(ctx, inp_l, w.output_norm, p.norm_rms_eps);
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let logits = crate::adapter::lora_mm(ctx, w.output, cur);
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

