pub struct MellumParams {
    pub attn: AttnParams,
    pub norm_rms_eps: f32,
    /// empty when swa_type == NONE (mellum.cpp:17-19)
    pub is_swa: Vec<bool>,
    pub freq_base_swa: f32,
    pub freq_scale_swa: f32,
    pub n_expert: i64,
    pub n_expert_used: i64,
    pub expert_weights_scale: f32,
}

/// verify against src/models/mellum.cpp:74-216. Every layer is MoE (softmax, norm_w =
/// true); the SWA layers rope with `freq_scale = 1.0, ext_factor = 0.0,
/// attn_factor = 1.0` (:126-136 — the no-yarn plain rope) while the
/// full-attention layers keep the global pair (:138-149).
pub fn build_mellum_forward(
    ctx: &mut Context,
    w: &MellumModelWeights,
    p: &MellumParams,
    kv: &KvCache,
    inp: &DecodeInputs,
    _sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(2048);
    assert_eq!(p.attn.n_embd_head_v, p.attn.n_embd_head_k, "mellum.cpp:76");
    assert_eq!(p.attn.n_embd_head_k, p.attn.n_rot, "mellum.cpp:77");

    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    let kq_scale = 1.0 / (p.attn.n_embd_head_k as f32).sqrt();

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_sa = inp_l;

        let cur = build_norm_rms(ctx, inp_l, lw.attn_norm, p.norm_rms_eps);

        let (mut q, mut k, v) = if let Some(wqkv) = lw.wqkv {
            qkv_fused(ctx, wqkv, lw.wqkv_b, &p.attn, cur, t)
        } else {
            qkv_separate_parts(
                ctx,
                lw.wq.expect("mellum wq"),
                lw.wq_b,
                lw.wk.expect("mellum wk"),
                lw.wk_b,
                lw.wv.expect("mellum wv"),
                lw.wv_b,
                &p.attn,
                cur,
                t,
            )
        };
        q = build_norm_rms(ctx, q, lw.attn_q_norm, p.norm_rms_eps);
        k = build_norm_rms(ctx, k, lw.attn_k_norm, p.norm_rms_eps);

        let (q, k) = if !p.is_swa.is_empty() && p.is_swa[il] {
            // the SWA layers' plain rope (:126-136)
            let r = |ctx: &mut Context, x: TensorId| {
                ctx.rope_ext(
                    x,
                    inp.pos,
                    None,
                    p.attn.n_rot as i32,
                    p.attn.rope_mode,
                    p.attn.n_ctx_orig,
                    p.freq_base_swa,
                    1.0,
                    0.0,
                    1.0,
                    p.attn.beta_fast,
                    p.attn.beta_slow,
                )
            };
            (r(ctx, q), r(ctx, k))
        } else {
            rope_qk(ctx, &p.attn, inp.pos, q, k)
        };

        let cur = attn_kv_cached(
            ctx,
            &mut graph,
            kv,
            il,
            &p.attn,
            inp,
            n_kv,
            q,
            k,
            v,
            kq_scale,
            0.0,
            None,
            None,
            Some(lw.wo),
            None,
        );

        let ffn_inp = ctx.add(cur, inp_sa);
        let cur = build_norm_rms(ctx, ffn_inp, lw.ffn_norm, p.norm_rms_eps);
        // softmax MoE, norm_w = true (:172-188)
        let logits = crate::adapter::lora_mm(ctx, lw.ffn_gate_inp, cur);
        let cur = build_moe_ffn_silu_probs(
            ctx,
            &mut graph,
            cur,
            logits,
            lw.ffn_up_exps,
            lw.ffn_gate_exps,
            lw.ffn_down_exps,
            p.n_expert,
            p.n_expert,
            1,
            p.n_expert_used,
            true,
            p.expert_weights_scale,
            EXPERT_GATING_SOFTMAX,
            None, // mellum has no exp_probs_b (:172-178)
        );
        inp_l = ctx.add(cur, ffn_inp);
    }

    let cur = build_norm_rms(ctx, inp_l, w.output_norm, p.norm_rms_eps);
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let logits = crate::adapter::lora_mm(ctx, w.output, cur);
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

