/// verify against src/models/paddleocr.cpp:7-107 — the qwen2vl text-side graph (the
/// M-RoPE sections ride `ggml_rope_multi` with the same pos id in all 4
/// blocks for text batches). NOTE the C gathers inp_out_ids at EVERY layer's
/// end unconditionally (:65-69) — value-identical to the port's single
/// end-of-graph out_rows.
pub fn build_paddleocr_forward(
    ctx: &mut Context,
    w: &PaddleOcrModelWeights,
    p: &PaddleOcrParams,
    kv: &KvCache,
    inp: &DecodeInputs,
    _sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(1024);
    assert_eq!(
        p.attn.n_embd_head_v, p.attn.n_embd_head_k,
        "paddleocr.cpp:13"
    );
    assert_eq!(p.attn.n_embd_head_k, p.attn.n_rot, "paddleocr.cpp:14");

    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    let kq_scale = 1.0 / (p.attn.n_embd_head_k as f32).sqrt();

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_sa = inp_l;

        let cur = build_norm_rms(ctx, inp_l, lw.attn_norm, p.norm_rms_eps);

        let (q, k, v) = if let Some(wqkv) = lw.wqkv {
            qkv_fused(ctx, wqkv, lw.wqkv_b, &p.attn, cur, t)
        } else {
            qkv_separate_parts(
                ctx,
                lw.wq.expect("paddle wq"),
                lw.wq_b,
                lw.wk.expect("paddle wk"),
                lw.wk_b,
                lw.wv.expect("paddle wv"),
                lw.wv_b,
                &p.attn,
                cur,
                t,
            )
        };
        let q = ctx.rope_multi(
            q,
            inp.pos,
            None,
            p.attn.n_rot as i32,
            p.rope_sections,
            p.attn.rope_mode,
            p.attn.n_ctx_orig,
            p.attn.freq_base,
            p.attn.freq_scale,
            p.attn.ext_factor,
            p.attn.attn_factor,
            p.attn.beta_fast,
            p.attn.beta_slow,
        );
        let k = ctx.rope_multi(
            k,
            inp.pos,
            None,
            p.attn.n_rot as i32,
            p.rope_sections,
            p.attn.rope_mode,
            p.attn.n_ctx_orig,
            p.attn.freq_base,
            p.attn.freq_scale,
            p.attn.ext_factor,
            p.attn.attn_factor,
            p.attn.beta_fast,
            p.attn.beta_slow,
        );

        let cur = attn_kv_cached(
            ctx,
            &mut graph,
            kv,
            il,
            &p.attn,
            inp,
            n_kv,
            q,
            k,
            v,
            kq_scale,
            0.0,
            None,
            None,
            Some(lw.wo),
            None,
        );

        let ffn_inp = ctx.add(cur, inp_sa);
        let cur = build_norm_rms(ctx, ffn_inp, lw.ffn_norm, p.norm_rms_eps);
        let cur = build_ffn_silu_par(
            ctx,
            cur,
            lw.ffn_gate,
            None,
            lw.ffn_up,
            None,
            lw.ffn_down,
            None,
        );
        inp_l = ctx.add(cur, ffn_inp);
    }

    let cur = build_norm_rms(ctx, inp_l, w.output_norm, p.norm_rms_eps);
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let logits = crate::adapter::lora_mm(ctx, w.output, cur);
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

// ----------------------------------------------------------------------
// gemma-embedding — src/models/gemma-embedding.cpp:73-176 (the encoder-only
// arch: non-causal no-cache attention over the symmetric-SWA mask pair, the
// dual post-norms and the pre-scaled Q)
// ----------------------------------------------------------------------

/// gemma-embedding's symmetric-SWA facts (the no-cache mask pair +
/// per-layer rope pair). `None` in EncoderParams for the other encoders.
#[derive(Clone)]
pub struct GemmaEmbeddingSwa {
    pub is_swa: Vec<bool>,
    pub n_swa: u32,
    /// get_rope_freq_base/scale(cparams, il) — the *_swa pair on the SWA
    /// layers (gemma-embedding.cpp:94-95)
    pub freq_base_swa: f32,
    pub freq_scale_swa: f32,
}

/// the encoder flavor of `qkv_fused` — the same fused-QKV split keyed on
/// EncoderParams' flat head geometry (gemma-embedding is MHA-shaped).
fn qkv_fused_enc(
    ctx: &mut Context,
    lw_qkv: TensorId,
    lw_qkv_b: Option<TensorId>,
    p: &EncoderParams,
    cur: TensorId,
    t: i64,
) -> (TensorId, TensorId, TensorId) {
    let mut qkv = crate::adapter::lora_mm(ctx, lw_qkv, cur);
    if let Some(b) = lw_qkv_b {
        qkv = ctx.add(qkv, b);
    }
    let n_embd_q = p.n_embd_head * p.n_head;
    let n_embd_k = p.n_embd_head * p.n_head_kv;
    let nb1 = ctx.nb(qkv)[1] as usize;
    let hd = p.n_embd_head as usize;
    let q = ctx.view_3d(qkv, p.n_embd_head, p.n_head, t, hd * 4, nb1, 0);
    let k = ctx.view_3d(
        qkv,
        p.n_embd_head,
        p.n_head_kv,
        t,
        hd * 4,
        nb1,
        n_embd_q as usize * 4,
    );
    let v = ctx.view_3d(
        qkv,
        p.n_embd_head,
        p.n_head_kv,
        t,
        hd * 4,
        nb1,
        (n_embd_q + n_embd_k) as usize * 4,
    );
    (q, k, v)
}

/// the encoder flavor of `qkv_separate_parts`.
#[allow(clippy::too_many_arguments)]
fn qkv_separate_parts_enc(
    ctx: &mut Context,
    wq: TensorId,
    wq_b: Option<TensorId>,
    wk: TensorId,
    wk_b: Option<TensorId>,
    wv: TensorId,
    wv_b: Option<TensorId>,
    p: &EncoderParams,
    cur: TensorId,
    t: i64,
) -> (TensorId, TensorId, TensorId) {
    let mut q = crate::adapter::lora_mm(ctx, wq, cur);
    if let Some(b) = wq_b {
        q = ctx.add(q, b);
    }
    let mut k = crate::adapter::lora_mm(ctx, wk, cur);
    if let Some(b) = wk_b {
        k = ctx.add(k, b);
    }
    let mut v = crate::adapter::lora_mm(ctx, wv, cur);
    if let Some(b) = wv_b {
        v = ctx.add(v, b);
    }
    let q = ctx.reshape_3d(q, p.n_embd_head, p.n_head, t);
    let k = ctx.reshape_3d(k, p.n_embd_head, p.n_head_kv, t);
    let v = ctx.reshape_3d(v, p.n_embd_head, p.n_head_kv, t);
    (q, k, v)
}

