/// verify against src/models/gemma-embedding.cpp:73-176 — encoder graph over
/// `build_attn_inp_no_cache` (the [T, T] non-causal pair: the SWA layers
/// read the symmetric-window mask). Q runs its RMS norm then rope then the
/// `f_attention_scale` pre-scale (:107-124) with kq_scale = 1.0; the block
/// is post-normed twice and the residual joins the PRE-norm inpL (:137-140,
/// :156-159). Ends at output_norm (no lm_head — `res->t_embd` only).
pub fn build_gemma_embedding_forward(
    ctx: &mut Context,
    w: &GemmaEmbeddingModelWeights,
    p: &EncoderParams,
    rope: &EurobertRope,
    swa: &GemmaEmbeddingSwa,
    f_attention_scale: f32,
    inp: &EncodeInputs,
    n_tokens: usize,
) -> EncodeResult {
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let eps = p.f_norm_rms_eps;
    let mut graph = Graph::new(2048);

    // inpL × sqrt(n_embd) — encode batches carry tokens (:83)
    let inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    let mut inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);
    inp_l = ctx.scale(inp_l, (ctx.ne(w.tok_embd)[0] as f32).sqrt());

    let swa_mask = inp.kq_mask_swa.expect("gemma-embedding needs the swa mask");

    let mut layer_outs = Vec::new();
    for il in 0..n_layer {
        let lw = &w.layers[il];

        let (freq_base_l, freq_scale_l) = if swa.is_swa[il] {
            (swa.freq_base_swa, swa.freq_scale_swa)
        } else {
            (rope.freq_base, rope.freq_scale)
        };

        let cur = build_norm_rms(ctx, inp_l, lw.attn_norm, eps);

        let (mut q, mut k, v) = if let Some(wqkv) = lw.wqkv {
            qkv_fused_enc(ctx, wqkv, lw.wqkv_b, p, cur, t)
        } else {
            qkv_separate_parts_enc(
                ctx,
                lw.wq.expect("ge wq"),
                lw.wq_b,
                lw.wk.expect("ge wk"),
                lw.wk_b,
                lw.wv.expect("ge wv"),
                lw.wv_b,
                p,
                cur,
                t,
            )
        };
        // Q norm → rope (:107-111); K norm → rope (:113-117)
        q = build_norm_rms(ctx, q, lw.attn_q_norm, eps);
        k = build_norm_rms(ctx, k, lw.attn_k_norm, eps);
        let r = |ctx: &mut Context, x: TensorId| {
            ctx.rope_ext(
                x,
                inp.pos.unwrap(),
                None,
                rope.n_rot,
                rope.rope_mode,
                rope.n_ctx_orig,
                freq_base_l,
                freq_scale_l,
                rope.ext_factor,
                rope.attn_factor,
                rope.beta_fast,
                rope.beta_slow,
            )
        };
        let q = r(ctx, q);
        let k = r(ctx, k);

        // Q × f_attention_scale (:124) with kq_scale = 1.0 (:129)
        let q = ctx.scale(q, f_attention_scale);

        // the per-layer mask of the no-cache pair (llama-graph.cpp:2796)
        let mask = if swa.is_swa[il] {
            swa_mask
        } else {
            inp.kq_mask
        };
        let cur = attn_no_cache(ctx, q, k, v, None, mask, 1.0, Some(lw.wo), None);

        // attn_post_norm (:137)
        let cur = build_norm_rms(ctx, cur, lw.attn_post_norm, eps);
        let sa_out = ctx.add(cur, inp_l);

        let cur = build_norm_rms(ctx, sa_out, lw.ffn_norm, eps);
        let cur = build_ffn_gelu_par(ctx, cur, lw.ffn_up, lw.ffn_gate, lw.ffn_down);
        let cur = build_norm_rms(ctx, cur, lw.ffn_post_norm, eps);
        inp_l = ctx.add(cur, sa_out);

        layer_outs.push(inp_l);
    }

    let embd = build_norm_rms(ctx, inp_l, w.output_norm, eps);
    graph.build_forward(ctx, embd);
    EncodeResult {
        embd,
        layer_outs,
        graph,
    }
}

// ----------------------------------------------------------------------
// llama-embed — src/models/llama.cpp:98-248 graph<true> (the no-cache
// causal twin of the llama decoder: build_attn_inp_no_cache, no lm_head,
// `res->t_embd` only)
// ----------------------------------------------------------------------

/// verify against src/models/llama.cpp graph<embed=true> — the llama layer body over
/// the causal no-cache [T, T] mask; the rope runs like the decoder's
/// (rope_ext, the resolved factors are None on plain files — see the module
/// header's rope_factors note), and the result is the final-norm hidden
/// state only (llama.cpp:238-242 skips the lm_head entirely).
pub fn build_llama_embed_encoder(
    ctx: &mut Context,
    w: &LlamaModelWeights,
    p: &EncoderParams,
    rope: &EurobertRope,
    inp: &EncodeInputs,
    n_tokens: usize,
) -> EncodeResult {
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let eps = p.f_norm_rms_eps;
    let n_embd_head_k = p.n_embd_head;
    let n_embd_head_v = p.n_embd_head;
    let mut graph = Graph::new(2048);

    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    let mut layer_outs = Vec::new();
    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_sa = inp_l;

        let cur = build_norm_rms(ctx, inp_l, lw.attn_norm, eps);

        // the llama loader is separate-Q/K/V only (llama.cpp:107-137)
        let (q, k, v) = qkv_separate_parts_enc(
            ctx, lw.wq, lw.wq_b, lw.wk, lw.wk_b, lw.wv, lw.wv_b, p, cur, t,
        );
        let r = |ctx: &mut Context, x: TensorId| {
            ctx.rope_ext(
                x,
                inp.pos.unwrap(),
                None,
                rope.n_rot,
                rope.rope_mode,
                rope.n_ctx_orig,
                rope.freq_base,
                rope.freq_scale,
                rope.ext_factor,
                rope.attn_factor,
                rope.beta_fast,
                rope.beta_slow,
            )
        };
        let q = r(ctx, q);
        let k = r(ctx, k);

        let kq_scale = 1.0 / (n_embd_head_k as f32).sqrt();
        let cur = attn_no_cache(
            ctx,
            q,
            k,
            v,
            None,
            inp.kq_mask,
            kq_scale,
            Some(lw.wo),
            lw.wo_b,
        );

        let ffn_inp = ctx.add(cur, inp_sa);
        let cur = build_norm_rms(ctx, ffn_inp, lw.ffn_norm, eps);
        let cur = build_ffn_silu_par(
            ctx,
            cur,
            lw.ffn_gate,
            lw.ffn_gate_b,
            lw.ffn_up,
            lw.ffn_up_b,
            lw.ffn_down,
            lw.ffn_down_b,
        );
        inp_l = ctx.add(cur, ffn_inp);
        let _ = n_embd_head_v;
        layer_outs.push(inp_l);
    }

    let embd = build_norm_rms(ctx, inp_l, w.output_norm, eps);
    graph.build_forward(ctx, embd);
    EncodeResult {
        embd,
        layer_outs,
        graph,
    }
}

