/// verify against src/models/mimo2.cpp:91-256. The fused-qkv path splits the Q/K/V
/// thirds with the row_k/row_v strides (:129-137 — Q/K share head_dim_k, V
/// uses head_dim_v); the optional sinks ride build_attn (:170-174); the
/// attn output scales by f_attn_value_scale AFTER wo (:177-180); the FFN is
/// dense or the sigmoid MoE (norm_w = true, :208-219).
pub fn build_mimo2_forward(
    ctx: &mut Context,
    w: &Mimo2ModelWeights,
    p: &Mimo2Params,
    kv: &KvCache,
    inp: &DecodeInputs,
    _sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(2048);

    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    for il in 0..n_layer {
        let lw = &w.layers[il];

        // res->t_layer_inp[il] = inpL (mimo2.cpp:109, def4d406a) — the
        // eagle3-style per-layer input tap; the port's store is the
        // name + graph inclusion (llama.cpp:127 precedent)
        ctx.set_name(inp_l, &format!("layer_inp-{il}"));
        graph.build_forward(ctx, inp_l);

        let inp_sa = inp_l;

        let n_head_l = p.attn.n_head;
        let n_head_kv_l = p.attn.n_head_kv;

        let cur = build_norm_rms(ctx, inp_l, lw.attn_norm, p.norm_rms_eps);

        // the fused split with the distinct V stride (:129-137) or the
        // separate projections (:139-151)
        let (q, k, v) = if let Some(wqkv) = lw.wqkv {
            let qkv = crate::adapter::lora_mm(ctx, wqkv, cur);
            let ty = ctx.ty(qkv);
            let row_k = ty.row_size(p.attn.n_embd_head_k as usize);
            let row_v = ty.row_size(p.attn.n_embd_head_v as usize);
            let row_full = ctx.nb(qkv)[1] as usize;
            let k_off = row_k * n_head_l as usize;
            let v_off = k_off + row_k * n_head_kv_l as usize;
            let q = ctx.view_3d(qkv, p.attn.n_embd_head_k, n_head_l, t, row_k, row_full, 0);
            let k = ctx.view_3d(
                qkv,
                p.attn.n_embd_head_k,
                n_head_kv_l,
                t,
                row_k,
                row_full,
                k_off,
            );
            let v = ctx.view_3d(
                qkv,
                p.attn.n_embd_head_v,
                n_head_kv_l,
                t,
                row_v,
                row_full,
                v_off,
            );
            (q, k, v)
        } else {
            qkv_separate_parts(
                ctx,
                lw.wq.expect("mimo2 wq"),
                lw.wq_b,
                lw.wk.expect("mimo2 wk"),
                lw.wk_b,
                lw.wv.expect("mimo2 wv"),
                lw.wv_b,
                &p.attn,
                cur,
                t,
            )
        };
        let rope = |ctx: &mut Context, x: TensorId| {
            ctx.rope_ext(
                x,
                inp.pos,
                None,
                p.attn.n_rot as i32,
                p.attn.rope_mode,
                p.attn.n_ctx_orig,
                p.freq_base[il],
                p.freq_scale[il],
                p.attn.ext_factor,
                p.attn.attn_factor,
                p.attn.beta_fast,
                p.attn.beta_slow,
            )
        };
        let q = rope(ctx, q);
        let k = rope(ctx, k);

        let kq_scale = 1.0 / (p.attn.n_embd_head_k as f32).sqrt();
        let mut cur = attn_kv_cached(
            ctx,
            &mut graph,
            kv,
            il,
            &p.attn,
            inp,
            n_kv,
            q,
            k,
            v,
            kq_scale,
            0.0,
            None,
            lw.attn_sinks,
            Some(lw.wo),
            None,
        );
        // the value scale after the projection (:177-180)
        if p.v_scale != 0.0 {
            cur = ctx.scale(cur, p.v_scale);
        }

        let ffn_inp = ctx.add(cur, inp_sa);
        let cur = build_norm_rms(ctx, ffn_inp, lw.ffn_norm, p.norm_rms_eps);

        let cur = if lw.ffn_gate_inp.is_none() {
            build_ffn_silu_par(
                ctx,
                cur,
                lw.ffn_gate.expect("mimo2 ffn_gate"),
                None,
                lw.ffn_up.expect("mimo2 ffn_up"),
                None,
                lw.ffn_down.expect("mimo2 ffn_down"),
                None,
            )
        } else {
            // sigmoid MoE, norm_w = true (:208-219) — the bias rides the
            // post-gating selection only (build_moe_ffn's exp_probs_b)
            let logits = crate::adapter::lora_mm(ctx, lw.ffn_gate_inp.expect("gate_inp"), cur);
            build_moe_ffn_silu_probs(
                ctx,
                &mut graph,
                cur,
                logits,
                lw.ffn_up_exps.expect("up_exps"),
                lw.ffn_gate_exps.expect("gate_exps"),
                lw.ffn_down_exps.expect("down_exps"),
                p.n_expert,
                p.n_expert,
                1,
                p.n_expert_used,
                true,
                p.expert_weights_scale,
                EXPERT_GATING_SIGMOID,
                lw.ffn_exp_probs_b,
            )
        };

        inp_l = ctx.add(cur, ffn_inp);
    }

    // res->t_layer_inp[n_layer] = inpL (mimo2.cpp:237-243, def4d406a) — the
    // final-layer tap keeps every token row (the C narrows the downstream
    // copy, the tap tensor itself stays un-narrowed; the port's narrowing
    // happens after the norm, value-identical for the logits rows)
    ctx.set_name(inp_l, &format!("layer_inp-{n_layer}"));
    graph.build_forward(ctx, inp_l);

    let cur = build_norm_rms(ctx, inp_l, w.output_norm, p.norm_rms_eps);
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let logits = crate::adapter::lora_mm(ctx, w.output, cur);
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(cur),
    }
}

