/// verify against src/models/step35.cpp:191-365. build_qkv runs with `reshape ==
/// false` and the graph reshapes itself (:229-231 — same values as the
/// port's fused/separate helpers); Q/K norms are optional (:234-241); the
/// rope is per-layer `n_rot_l` with the freqs factors only on the
/// full-attention layers (:243-256); the head-wise gate (:266-283) and the
/// MoE/shared FFN (:302-337) follow.
pub fn build_step35_forward(
    ctx: &mut Context,
    w: &Step35ModelWeights,
    p: &Step35Params,
    kv: &KvCache,
    inp: &DecodeInputs,
    _sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(2048);

    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(ctx, w.tok_embd, inp_l, inp.tokens);

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_sa = inp_l;

        let is_swa = p.is_swa[il];
        let n_rot_l = p.n_rot[il] as i32;

        let cur = build_norm_rms(ctx, inp_l, lw.attn_norm, p.norm_rms_eps);

        let (mut q, mut k, v) = if let Some(wqkv) = lw.wqkv {
            qkv_fused(ctx, wqkv, lw.wqkv_b, &p.attn, cur, t)
        } else {
            qkv_separate_parts(
                ctx,
                lw.wq.expect("step35 wq"),
                lw.wq_b,
                lw.wk.expect("step35 wk"),
                lw.wk_b,
                lw.wv.expect("step35 wv"),
                lw.wv_b,
                &p.attn,
                cur,
                t,
            )
        };
        // optional Q/K per-head norms (:234-241)
        if let Some(qn) = lw.attn_q_norm {
            q = build_norm_rms(ctx, q, qn, p.norm_rms_eps);
        }
        if let Some(kn) = lw.attn_k_norm {
            k = build_norm_rms(ctx, k, kn, p.norm_rms_eps);
        }
        // rope at n_rot_l; factors only on the full-attention layers
        // (:244-256)
        let rf = if is_swa { None } else { lw.rope_freqs };
        let q = ctx.rope_ext(
            q,
            inp.pos,
            rf,
            n_rot_l,
            p.attn.rope_mode,
            p.attn.n_ctx_orig,
            p.freq_base[il],
            p.freq_scale[il],
            p.attn.ext_factor,
            p.attn.attn_factor,
            p.attn.beta_fast,
            p.attn.beta_slow,
        );
        let k = ctx.rope_ext(
            k,
            inp.pos,
            rf,
            n_rot_l,
            p.attn.rope_mode,
            p.attn.n_ctx_orig,
            p.freq_base[il],
            p.freq_scale[il],
            p.attn.ext_factor,
            p.attn.attn_factor,
            p.attn.beta_fast,
            p.attn.beta_slow,
        );

        let kq_scale = 1.0 / (p.attn.n_embd_head_k as f32).sqrt();
        let mut attn_out = attn_kv_cached(
            ctx, &mut graph, kv, il, &p.attn, inp, n_kv, q, k, v, kq_scale, 0.0, None, None, None,
            None,
        );
        // the head-wise gate (:266-283)
        if let Some(gw) = lw.wqkv_gate {
            let gate = crate::adapter::lora_mm(ctx, gw, cur); // the PRE-rope normed input
            let gate = ctx.sigmoid(gate);
            let nt = ctx.ne(attn_out)[1];
            let a3 = ctx.reshape_3d(attn_out, p.attn.n_embd_head_v, p.attn.n_head, nt);
            let g3 = ctx.reshape_3d(gate, 1, p.attn.n_head, nt);
            let gated = ctx.mul(a3, g3);
            attn_out = ctx.reshape_2d(gated, p.attn.n_embd_head_v * p.attn.n_head, nt);
        }
        let cur = crate::adapter::lora_mm(ctx, lw.wo, attn_out);

        let ffn_inp = ctx.add(cur, inp_sa);
        let cur = build_norm_rms(ctx, ffn_inp, lw.ffn_norm, p.norm_rms_eps);

        let cur = if lw.ffn_gate_inp.is_none() {
            build_ffn_silu_par(
                ctx,
                cur,
                lw.ffn_gate.expect("step35 ffn_gate"),
                None,
                lw.ffn_up.expect("step35 ffn_up"),
                None,
                lw.ffn_down.expect("step35 ffn_down"),
                None,
            )
        } else {
            // the bias rides the post-gating selection only (:309-321)
            let logits = crate::adapter::lora_mm(ctx, lw.ffn_gate_inp.expect("gate_inp"), cur);
            let moe_out = build_moe_ffn_silu_probs(
                ctx,
                &mut graph,
                cur,
                logits,
                lw.ffn_up_exps.expect("up_exps"),
                lw.ffn_gate_exps.expect("gate_exps"),
                lw.ffn_down_exps.expect("down_exps"),
                p.n_expert,
                p.n_expert,
                1,
                p.n_expert_used,
                p.expert_weights_norm,
                p.expert_weights_scale,
                p.expert_gating_func,
                lw.ffn_exp_probs_b,
            );
            // the always-added shared expert (:327-333)
            let sh_out = build_ffn_silu_par(
                ctx,
                cur,
                lw.ffn_gate_shexp.expect("gate_shexp"),
                None,
                lw.ffn_up_shexp.expect("up_shexp"),
                None,
                lw.ffn_down_shexp.expect("down_shexp"),
                None,
            );
            ctx.add(moe_out, sh_out)
        };

        inp_l = ctx.add(cur, ffn_inp);
    }

    // t_h_nextn is the PRE-final-norm hidden (step35.cpp:347-353)
    let embd = inp_l;
    let cur = build_norm_rms(ctx, inp_l, w.output_norm, p.norm_rms_eps);
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let logits = crate::adapter::lora_mm(ctx, w.output, cur);
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(embd),
    }
}

