#[derive(Clone)]
pub struct WavtokenizerDecParams {
    /// `f_norm_eps` — LLM_KV_ATTENTION_LAYERNORM_EPS (the LLM_NORM eps)
    pub norm_eps: f32,
    /// `f_norm_group_eps` — LLM_KV_ATTENTION_GROUPNORM_EPS
    pub norm_group_eps: f32,
    /// `n_norm_groups` — LLM_KV_ATTENTION_GROUPNORM_GROUPS
    pub n_norm_groups: i64,
    pub posnet_n_embd: i64,
    pub n_ff: i64,
}

pub struct WavtokenizerDecResult {
    /// `res->t_embd` — the decoded waveform, [n_embd_out, n_tokens]
    pub embd: TensorId,
    /// the lm_head output (the sampled next-code logits of a plain run)
    pub logits: TensorId,
    pub graph: Graph,
}

/// verify against src/models/wavtokenizer-dec.cpp:118-264
/// `llama_model_wavtokenizer_dec::graph::graph` — token embeddings →
/// transposed T-first stem conv → posnet (4×resnet / 1×attention /
/// 1×groupnorm) → convnext stack with GELU-seq FFN → lm_head + bias.
///
/// The posnet attention is a single-head bidirectional QK^T soft-max
/// (wavtokenizer-dec.cpp:185-189, no mask) over the posnet width.
pub fn build_wavtokenizer_dec_forward(
    cx: &mut Context,
    w: &WavtokenizerDecModelWeights,
    p: &WavtokenizerDecParams,
    inp_tokens: TensorId,
    n_tokens: usize,
) -> WavtokenizerDecResult {
    let _ = n_tokens;
    let mut graph = Graph::new(1024);

    // inpL = build_inp_embd(model.tok_embd) (wavtokenizer-dec.cpp:122)
    let inp_l = cx.get_rows(w.tok_embd, inp_tokens);

    let cur = cx.transpose(inp_l);
    let cur = cx.cont(cur); // [T, n_embd]

    // stem conv, "same" padding (:124-127)
    let cur = conv_1d_ph_lm(cx, w.conv1d, cur, 1, 1);
    let mut cur = cx.add(cur, w.conv1d_b); // [T, posnet.n_embd, 1]

    // posnet (:129-205)
    for (il, layer) in w.posnet_layers.iter().enumerate() {
        let inp_l = cur;
        match il {
            0 | 1 | 3 | 4 => {
                // group-norm → GEGLU-ish sigmoid gate → conv → repeat → residual
                let mut c = group_norm_lm(cx, cur, p.n_norm_groups, p.norm_group_eps);
                c = cx.mul(c, layer.norm1.unwrap());
                c = cx.add(c, layer.norm1_b.unwrap());
                let sig = cx.sigmoid(c);
                c = cx.mul(sig, c);

                c = conv_1d_ph_lm(cx, layer.conv1.unwrap(), c, 1, 1);
                c = cx.add(c, layer.conv1_b.unwrap());

                let c = group_norm_lm(cx, c, p.n_norm_groups, p.norm_group_eps);
                let c = cx.mul(c, layer.norm2.unwrap());
                let mut c = cx.add(c, layer.norm2_b.unwrap());
                let sig = cx.sigmoid(c);
                c = cx.mul(sig, c);

                c = conv_1d_ph_lm(cx, layer.conv2.unwrap(), c, 1, 1);
                c = cx.add(c, layer.conv2_b.unwrap());

                cur = cx.add(c, inp_l);
            }
            2 => {
                // single-head bidirectional attention (:163-195)
                let c = group_norm_lm(cx, cur, p.n_norm_groups, p.norm_group_eps);
                let c = cx.mul(c, layer.attn_norm.unwrap());
                let c = cx.add(c, layer.attn_norm_b.unwrap());

                let q = conv_1d_ph_lm(cx, layer.attn_q.unwrap(), c, 1, 1);
                let k = conv_1d_ph_lm(cx, layer.attn_k.unwrap(), c, 1, 1);
                let v = conv_1d_ph_lm(cx, layer.attn_v.unwrap(), c, 1, 1);

                let q = cx.add(q, layer.attn_q_b.unwrap());
                let k = cx.add(k, layer.attn_k_b.unwrap());
                let v = cx.add(v, layer.attn_v_b.unwrap());

                let q = cx.transpose(q);
                let q = cx.cont(q); // [C, T]
                let k = cx.transpose(k);
                let k = cx.cont(k);

                let kq = cx.mul_mat(k, q); // [T, T]
                let kq = cx.soft_max_ext(kq, None, 1.0 / (p.posnet_n_embd as f32).sqrt(), 0.0);

                let c = cx.mul_mat(kq, v); // [T, C]

                let c = conv_1d_ph_lm(cx, layer.attn_o.unwrap(), c, 1, 1);
                let c = cx.add(c, layer.attn_o_b.unwrap());

                cur = cx.add(c, inp_l);
            }
            5 => {
                let c = group_norm_lm(cx, cur, p.n_norm_groups, p.norm_group_eps);
                cur = cx.mul(c, layer.norm.unwrap());
                cur = cx.add(cur, layer.norm_b.unwrap());
            }
            _ => unreachable!("wavtokenizer posnet has exactly 6 blocks"),
        }
    }
    let cur = cx.transpose(cur);
    let cur = cx.cont(cur); // [C, T]

    // tok_norm is an LLM_NORM over the channel dim (:208-213)
    let cur = build_norm(cx, cur, Some(w.tok_norm), Some(w.tok_norm_b), p.norm_eps);

    let cur = cx.transpose(cur);
    let cur = cx.cont(cur); // [T, C]
    let mut inp_l = cur;

    // convnext (:217-245)
    for layer in w.convnext_layers.iter() {
        let cur = conv_1d_dw_ph_lm(cx, layer.dw, inp_l, 1, 1);
        let cur = cx.add(cur, layer.dw_b); // [T, C, 1]

        let cur = cx.transpose(cur);
        let cur = cx.cont(cur); // [C, T]

        // LLM_NORM with the layer index -1 (no cb)
        let cur = build_norm(cx, cur, Some(layer.norm), Some(layer.norm_b), p.norm_eps);

        // GELU-seq FFN, no gate (:233-238)
        let cur = cx.mul_mat(layer.pw1, cur);
        let cur = cx.add(cur, layer.pw1_b);
        let cur = cx.gelu(cur);
        let cur = cx.mul_mat(layer.pw2, cur);
        let cur = cx.add(cur, layer.pw2_b);

        let cur = cx.mul(cur, layer.gamma);

        let cur = cx.transpose(cur);
        let cur = cx.cont(cur); // [T, C]

        inp_l = cx.add(cur, inp_l);
    }
    let cur = inp_l;

    let cur = cx.transpose(cur);
    let cur = cx.cont(cur); // [C, T]

    let cur = build_norm(
        cx,
        cur,
        Some(w.output_norm),
        Some(w.output_norm_b),
        p.norm_eps,
    );

    // lm_head (:256-260) — res->t_embd is the POST-head tensor (the decoded
    // waveform, [n_embd_out, T]); the head output doubles as the sampled
    // next-code logits of a plain run
    let head = cx.mul_mat(w.output, cur);
    let head = cx.add(head, w.output_b);

    graph.build_forward(cx, head);
    WavtokenizerDecResult {
        embd: head,
        logits: head,
        graph,
    }
}

// ----------------------------------------------------------------------
// pockettts — src/models/pockettts.cpp
// ----------------------------------------------------------------------

pub struct PocketttsLayerWeights {
    pub attn_norm: TensorId,
    pub attn_norm_b: TensorId,
    /// the fused-QKV form `create_tensor_qkv` may have loaded (pockettts
    /// files are separate-Q/K/V, the slot stays Option for the 1:1 shape)
    pub wqkv: Option<TensorId>,
    pub wqkv_b: Option<TensorId>,
    pub wq: Option<TensorId>,
    pub wq_b: Option<TensorId>,
    pub wk: Option<TensorId>,
    pub wk_b: Option<TensorId>,
    pub wv: Option<TensorId>,
    pub wv_b: Option<TensorId>,
    pub wo: TensorId,
    pub ffn_norm: TensorId,
    pub ffn_norm_b: TensorId,
    pub ffn_down: TensorId,
    pub ffn_up: TensorId,
}

pub struct PocketttsModelWeights {
    pub tok_embd: TensorId,
    pub output_norm: TensorId,
    pub output_norm_b: TensorId,
    /// the duplicated token_embd the loader mounts as the head
    /// (pockettts.cpp:23-24) so a sampler can still run
    pub output: TensorId,
    pub layers: Vec<PocketttsLayerWeights>,
}

/// verify against src/models/pockettts.cpp:48-146
/// `llama_model_pockettts::graph::graph` — LayerNorm attention blocks with
/// rope NORM and a GELU-seq FFN, the last layer pruning to `inp_out_ids`
/// (:98-101), `res->t_embd` the final-norm hidden state (:137-138) and the
/// tied-embd head producing (unused) logits (:140-143).
///
/// `build_cvec` (:125) is the identity here: pockettts loads no cvec
/// tensors, and the C returns `cur` unchanged when the layer's cvec pair is
/// empty (llama-graph.cpp:2166-2187).
#[allow(clippy::too_many_arguments)]
pub fn build_pockettts_forward(
    cx: &mut Context,
    w: &PocketttsModelWeights,
    p: &AttnParams,
    kv: &KvCache,
    inp: &DecodeInputs,
    sinfo: SlotInfo,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let _ = sinfo;
    let t = n_tokens as i64;
    let n_layer = w.layers.len();
    let mut graph = Graph::new(1024);

    let mut inp_l = cx.get_rows(w.tok_embd, inp.tokens);
    inp_l = crate::adapter::lora_embd(cx, w.tok_embd, inp_l, inp.tokens);

    for il in 0..n_layer {
        let lw = &w.layers[il];

        // self-attention (pockettts.cpp:65-96)
        let cur = build_norm(
            cx,
            inp_l,
            Some(lw.attn_norm),
            Some(lw.attn_norm_b),
            p.norm_eps,
        );

        let (q, k, v) = if let Some(wqkv) = lw.wqkv {
            qkv_fused(cx, wqkv, lw.wqkv_b, p, cur, t)
        } else {
            qkv_separate_parts(
                cx,
                lw.wq.expect("pockettts wq"),
                lw.wq_b,
                lw.wk.expect("pockettts wk"),
                lw.wk_b,
                lw.wv.expect("pockettts wv"),
                lw.wv_b,
                p,
                cur,
                t,
            )
        };

        let (q, k) = rope_qk(cx, p, inp.pos, q, k);

        let kq_scale = 1.0 / (p.n_embd_head_k as f32).sqrt();
        let cur = attn_kv_cached(
            cx,
            &mut graph,
            kv,
            il,
            p,
            inp,
            n_kv,
            q,
            k,
            v,
            kq_scale,
            0.0,
            None,
            None,
            Some(lw.wo),
            None, // pockettts loads no attn_out bias
        );

        // the last layer prunes to the output rows before the residual add
        // (pockettts.cpp:98-101)
        let (cur, inp_l_pruned) = if il == n_layer - 1 && inp.out_ids.is_some() {
            let c = cx.get_rows(cur, inp.out_ids.unwrap());
            let l = cx.get_rows(inp_l, inp.out_ids.unwrap());
            (c, l)
        } else {
            (cur, inp_l)
        };

        let ffn_inp = cx.add(cur, inp_l_pruned);

        // FF (pockettts.cpp:107-121) — GELU-seq, no biases
        let cur = build_norm(
            cx,
            ffn_inp,
            Some(lw.ffn_norm),
            Some(lw.ffn_norm_b),
            p.norm_eps,
        );
        let cur = build_ffn_gelu_seq(cx, cur, lw.ffn_up, None, lw.ffn_down, None);

        let cur = cx.add(cur, ffn_inp);
        // build_cvec: identity, see the function doc

        inp_l = cur;
    }

    // result_norm / t_embd (pockettts.cpp:132-138)
    let cur = build_norm(
        cx,
        inp_l,
        Some(w.output_norm),
        Some(w.output_norm_b),
        p.norm_eps,
    );
    let embd = cur;

    // result_output — the tied-embd head (:140-143)
    let logits = crate::adapter::lora_mm(cx, w.output, cur);
    graph.build_forward(cx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(embd),
    }
}

// ===========================================================================
// MTP batch 17 (2026-09-29): the `graph_mtp` draft heads of the GLM4-style
// family — qwen35 / qwen35moe / qwen3next / glm4-moe / cohere2moe /
// bailingmoe3 / hy-v3 / mimo2 / step35 (each arch file's `LLM_GRAPH_TYPE_
// DECODER_MTP` class, built only by the MTP draft context — see the deepseek
// MTP section above for the plumbing description).
//
// All nine share the GLM4 MTP skeleton:
//   eh_proj(concat(enorm(tok_embd(tokens)), hnorm(h))) → the arch's own
//   attention+FFN block over it → the shared head norm (nextn.
//   shared_head_norm, falling back to output_norm) → the LM head (nextn.
//   shared_head_head, falling back to model.output). `res->t_h_nextn` is the
//   post-block state that seeds the next draft step.
//
// The differences the port preserves per arch: the embd_h vs embd input class
// (both carry tokens + an F32 h row — the same graph), the tok_embd fallback
// (bailingmoe3 reads model.tok_embd directly), where the inp_out_ids gather
// sits (mimo2/step35 gather BEFORE the head norm, qwen3next gathers the
// attention residual mid-graph, the rest gather after t_h_nextn), the norm
// type (cohere2moe's RMS-vs-LN switch), the shared-head fallback chain
// (mimo2 also accepts layer_out_norm), the attention extras (mimo2 sinks +
// value scale, step35 per-head gate + halved rope, qwen3* per-head Q gate,
// bailingmoe3's gated MLA over the K-only cache) and the FFN flavor.
//
// Like the deepseek MTP builders these address `kv.layers[0]` of the 1-layer
// filtered cache the MTP context carries (llama-model.cpp:2676-2679 —
// `il >= n_layer()`), so `il` inside the attention helpers is 0; the
// `inp_out_ids` row-pruning follows the port-wide convention (the graph
// computes every row; values identical).
// ===========================================================================

/// the `llama_layer::nextn` members the GLM4-style MTP blocks read — the same
/// six fields as [`DeepseekMtpNextn`] (the deepseek family shares the trio).
pub type MtpNextn = DeepseekMtpNextn;

/// `llm_graph_input_embd_h`'s embedding lookup (:557-567 of each file — the
/// `ubatch.token` arm): nextn.embed_tokens when the file ships it, else the
/// model's tok_embd.
fn mtp_tok_embd(ctx: &mut Context, tok_embd: TensorId, nextn: &MtpNextn, tokens: TensorId) -> TensorId {
    let w = nextn.embed_tokens.unwrap_or(tok_embd);
    ctx.get_rows(w, tokens)
}

/// the shared `eh_proj` trio (e.g. qwen35.cpp:577-591): RMS-norm both inputs,
/// concat, project.
fn mtp_eh_proj_rms(
    ctx: &mut Context,
    tok_embd: TensorId,
    h_in: MtpHInput,
    nextn: &MtpNextn,
    eps: f32,
) -> TensorId {
    let h_norm = build_norm_rms(ctx, h_in, nextn.hnorm, eps);
    let e_norm = build_norm_rms(ctx, tok_embd, nextn.enorm, eps);
    let concat = ctx.concat(e_norm, h_norm, 0);
    crate::adapter::lora_mm(ctx, nextn.eh_proj, concat)
}

/// the MTP head norm + LM head (e.g. qwen35.cpp:620-641): shared_head_norm →
/// output_norm fallback over the post-block state, out_rows gather, then
/// shared_head_head → output. Returns `(t_logits, t_h_nextn)`.
fn mtp_shared_head(
    ctx: &mut Context,
    cur: TensorId,
    output_norm: TensorId,
    output: TensorId,
    nextn: &MtpNextn,
    out_ids: Option<TensorId>,
    eps: f32,
) -> (TensorId, TensorId) {
    let head_norm_w = nextn.shared_head_norm.unwrap_or(output_norm);
    let cur = build_norm_rms(ctx, cur, head_norm_w, eps);
    let h_nextn = cur;
    let cur = graph::out_rows(ctx, cur, out_ids);
    let head_w = nextn.shared_head_head.unwrap_or(output);
    (crate::adapter::lora_mm(ctx, head_w, cur), h_nextn)
}

