// qwen35 — src/models/qwen35.cpp:519-644 `graph_mtp` (dense FFN)
// ---------------------------------------------------------------------------

pub struct Qwen35MtpWeights {
    pub tok_embd: TensorId,
    pub output_norm: TensorId,
    pub output: TensorId,
    pub nextn: MtpNextn,
    /// the MTP layer (a full-attention block — the loader creates the whole
    /// trunk-shaped set at index n_layer, qwen35.cpp:288-320)
    pub layer: Qwen35LayerWeights,
    // the MTP layer's geometry (hparams.n_head(n_layer) … — the trunk params'
    // per-layer vectors are trunk-length)
    pub n_head: i64,
    pub n_head_kv: i64,
    pub n_embd_head: i64,
    pub n_rot: i32,
}

/// verify against src/models/qwen35.cpp:519-644 — the dense-series MTP head. The
/// attention (:563-613) is the trunk `build_layer_attn` shape (the Q
/// projection carries a per-head sigmoid gate, IMRoPE via rope_multi with the
/// hparams sections, kq_scale from f_attention_scale); the FFN (:615-624) is
/// the dense SwiGLU.
pub fn build_qwen35_mtp_forward(
    ctx: &mut Context,
    w: &Qwen35MtpWeights,
    p: &Qwen35Params,
    kv: &KvCache,
    inp: &DecodeInputs,
    h_in: MtpHInput,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let t = n_tokens as i64;
    let mut graph = Graph::new(1024);
    let lw = &w.layer;
    let a = &p.attn;

    // :541-568 — the embd_h lookup + the eh_proj trio
    let tok_embd = mtp_tok_embd(ctx, w.tok_embd, &w.nextn, inp.tokens);
    let cur = mtp_eh_proj_rms(ctx, tok_embd, h_in, &w.nextn, a.norm_eps);
    let inp_sa = cur;

    // :570-573 attn_norm
    let cur = build_norm_rms(ctx, cur, lw.attn_norm, a.norm_eps);

    // :575-609 — the gated full attention (the trunk build_layer_attn shape)
    let q_full = crate::adapter::lora_mm(ctx, lw.wq.expect("mtp wq"), cur);
    let k = crate::adapter::lora_mm(ctx, lw.wk.expect("mtp wk"), cur);
    let v = crate::adapter::lora_mm(ctx, lw.wv.expect("mtp wv"), cur);
    let nb1 = ctx.nb(q_full)[1] as usize;
    let head_stride = (w.n_embd_head * 2 * 4) as usize;
    let q = ctx.view_3d(q_full, w.n_embd_head, w.n_head, t, head_stride, nb1, 0);
    let gate = ctx.view_3d(
        q_full,
        w.n_embd_head,
        w.n_head,
        t,
        head_stride,
        nb1,
        (w.n_embd_head * 4) as usize,
    );
    let gate = ctx.cont_2d(gate, w.n_embd_head * w.n_head, t);
    let q = build_norm_rms(ctx, q, lw.attn_q_norm.expect("mtp attn_q_norm"), a.norm_eps);
    let k = ctx.reshape_3d(k, w.n_embd_head, w.n_head_kv, t);
    let k = build_norm_rms(ctx, k, lw.attn_k_norm.expect("mtp attn_k_norm"), a.norm_eps);
    let v = ctx.reshape_3d(v, w.n_embd_head, w.n_head_kv, t);
    let rope = |ctx: &mut Context, x: TensorId| {
        ctx.rope_multi(
            x, inp.pos, None, w.n_rot, p.rope_sections, a.rope_mode, a.n_ctx_orig, a.freq_base,
            a.freq_scale, a.ext_factor, a.attn_factor, a.beta_fast, a.beta_slow,
        )
    };
    let q = rope(ctx, q);
    let k = rope(ctx, k);
    let kq_scale = if p.f_attention_scale == 0.0 {
        1.0 / (w.n_embd_head as f32).sqrt()
    } else {
        p.f_attention_scale
    };
    let cur = attn_kv_cached(
        ctx, &mut graph, kv, 0, a, inp, n_kv, q, k, v, kq_scale, 0.0, None, None, None, None,
    );
    let gate_sigmoid = ctx.sigmoid(gate);
    let cur = ctx.mul(cur, gate_sigmoid);
    let cur = crate::adapter::lora_mm(ctx, lw.wo.expect("mtp wo"), cur);

    // :611-612 residual, :615-624 the dense FFN
    let ffn_residual = ctx.add(cur, inp_sa);
    let normed = build_norm_rms(ctx, ffn_residual, lw.attn_post_norm, a.norm_eps);
    let cur = build_ffn_silu_par(
        ctx,
        normed,
        lw.ffn_gate,
        None,
        lw.ffn_up,
        None,
        lw.ffn_down,
        None,
    );
    let cur = ctx.add(cur, ffn_residual);

    // :626-641 the shared head
    let (logits, h_nextn) = mtp_shared_head(
        ctx,
        cur,
        w.output_norm,
        w.output,
        &w.nextn,
        inp.out_ids,
        a.norm_eps,
    );
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(h_nextn),
    }
}

