// glm4-moe — src/models/glm4-moe.cpp:132-289 `graph_mtp`
// ---------------------------------------------------------------------------

pub struct Glm4MoeMtpWeights {
    pub tok_embd: TensorId,
    pub output_norm: TensorId,
    pub output: TensorId,
    pub nextn: MtpNextn,
    pub layer: Glm4MoeLayerWeights,
}

/// verify against src/models/glm4-moe.cpp:132-289 — the eh_proj trio → the trunk block
/// (QKV with optional per-head Q/K norms, plain rope, wo INSIDE build_attn,
/// attn_post_norm as the FFN norm, the routed+shared MoE) → the shared head.
/// `nextn_layer_offset` is asserted 0-able at the driver (single block,
/// :141-145).
pub fn build_glm4_moe_mtp_forward(
    ctx: &mut Context,
    w: &Glm4MoeMtpWeights,
    p: &Glm4MoeParams,
    kv: &KvCache,
    inp: &DecodeInputs,
    h_in: MtpHInput,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let t = n_tokens as i64;
    let mut graph = Graph::new(1024);
    let lw = &w.layer;
    let a = &p.attn;

    // :152-185
    let tok_embd = mtp_tok_embd(ctx, w.tok_embd, &w.nextn, inp.tokens);
    let cur = mtp_eh_proj_rms(ctx, tok_embd, h_in, &w.nextn, a.norm_eps);
    let inp_sa = cur;

    // :187-190 attn_norm
    let cur = build_norm_rms(ctx, cur, lw.attn_norm, a.norm_eps);

    // :192-216 — build_qkv + the optional Q/K norms + rope (the trunk shape)
    let (mut q, mut k, v) = if let Some(wqkv) = lw.wqkv {
        qkv_fused(ctx, wqkv, lw.wqkv_b, a, cur, t)
    } else {
        qkv_separate_parts(
            ctx,
            lw.wq.expect("mtp wq"),
            lw.wq_b,
            lw.wk.expect("mtp wk"),
            lw.wk_b,
            lw.wv.expect("mtp wv"),
            lw.wv_b,
            a,
            cur,
            t,
        )
    };
    if let Some(qn) = lw.attn_q_norm {
        q = build_norm_rms(ctx, q, qn, a.norm_eps);
    }
    if let Some(kn) = lw.attn_k_norm {
        k = build_norm_rms(ctx, k, kn, a.norm_eps);
    }
    let (q, k) = rope_qk(ctx, a, inp.pos, q, k);

    // :218-223 — build_attn with wo inside
    let kq_scale = 1.0 / (a.n_embd_head_v as f32).sqrt();
    let cur = attn_kv_cached(
        ctx, &mut graph, kv, 0, a, inp, n_kv, q, k, v, kq_scale, 0.0, None, None, Some(lw.wo),
        None,
    );

    // :225-233 ffn_inp + attn_post_norm as the FFN norm
    let ffn_inp = ctx.add(cur, inp_sa);
    let cur = build_norm_rms(ctx, ffn_inp, lw.attn_post_norm, a.norm_eps);

    // :235-257 — the routed + shared experts (the trunk MoE branch; the MTP
    // layer is always MoE — ffn_gate_inp asserted, :151)
    let routed_out = build_moe_ffn_silu(
        ctx,
        &mut graph,
        cur,
        lw.ffn_gate_inp.expect("mtp ffn_gate_inp"),
        None,
        lw.ffn_up_exps.expect("mtp ffn_up_exps"),
        None,
        lw.ffn_gate_exps,
        None,
        lw.ffn_down_exps.expect("mtp ffn_down_exps"),
        None,
        lw.ffn_exp_probs_b,
        p.n_expert,
        p.n_expert_used,
        p.expert_weights_norm,
        p.expert_weights_scale,
        p.expert_gating_func,
    );
    let shared_out = build_ffn_silu_par(
        ctx,
        cur,
        lw.ffn_gate_shexp.expect("mtp ffn_gate_shexp"),
        None,
        lw.ffn_up_shexp.expect("mtp ffn_up_shexp"),
        None,
        lw.ffn_down_shexp.expect("mtp ffn_down_shexp"),
        None,
    );
    let cur = ctx.add(routed_out, shared_out);
    let cur = ctx.add(cur, ffn_inp);

    // :259-288 the shared head
    let (logits, h_nextn) = mtp_shared_head(
        ctx,
        cur,
        w.output_norm,
        w.output,
        &w.nextn,
        inp.out_ids,
        a.norm_eps,
    );
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(h_nextn),
    }
}

// ---------------------------------------------------------------------------
// cohere2moe — src/models/cohere2moe.cpp:291-439 `graph_mtp` (iswa, the
// RMS-vs-LN norm switch, the normed-input FFN, the 0.5-scaled shared expert,
// the double residual and the logit_scale head)
// ---------------------------------------------------------------------------

pub struct Cohere2MoeMtpWeights {
    pub tok_embd: TensorId,
    pub output_norm: TensorId,
    pub output: TensorId,
    pub nextn: MtpNextn,
    pub layer: Cohere2MoeLayerWeights,
}

/// verify against src/models/cohere2moe.cpp:291-439 — the cohere2 skeleton: the normed
/// attn output feeds the FFN (not the residual), rope on this layer per
/// get_rope_factors (the port passes None — no rope_freqs tensor, the same
/// convention as the trunk), the shared expert added then scaled 0.5, the
/// double residual `out + inpL + attn_out`, and f_logit_scale on the head.
pub fn build_cohere2moe_mtp_forward(
    ctx: &mut Context,
    w: &Cohere2MoeMtpWeights,
    p: &Cohere2MoeParams,
    kv: &KvCache,
    inp: &DecodeInputs,
    h_in: MtpHInput,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let t = n_tokens as i64;
    let mut graph = Graph::new(1024);
    let lw = &w.layer;
    let a = &p.attn;
    assert_eq!(a.n_embd_head_k, a.n_rot, "cohere2moe.cpp:297");

    // cohere2moe.cpp:299 — the norm-type switch
    let norm = |ctx: &mut Context, x: TensorId, w: TensorId| -> TensorId {
        if p.norm_rms_eps == 0.0 {
            build_norm(ctx, x, Some(w), None, p.norm_ln_eps)
        } else {
            build_norm_rms(ctx, x, w, p.norm_rms_eps)
        }
    };

    // :301-330
    let tok_embd = mtp_tok_embd(ctx, w.tok_embd, &w.nextn, inp.tokens);
    let cur = mtp_eh_proj_rms(ctx, tok_embd, h_in, &w.nextn, a.norm_eps);
    let inp_l = cur;

    // :332-336 attn_norm — the normed input doubles as the FFN input
    let cur = norm(ctx, cur, lw.attn_norm);
    let ffn_inp = cur;

    // :338-361 — build_qkv + rope (factors: the port's no-factors convention)
    let (mut q, mut k, v) = if let Some(wqkv) = lw.wqkv {
        qkv_fused(ctx, wqkv, lw.wqkv_b, a, cur, t)
    } else {
        qkv_separate_parts(
            ctx,
            lw.wq.expect("mtp wq"),
            lw.wq_b,
            lw.wk.expect("mtp wk"),
            lw.wk_b,
            lw.wv.expect("mtp wv"),
            lw.wv_b,
            a,
            cur,
            t,
        )
    };
    // per the C the Q/K norms are absent on cohere2moe (:341 has none)
    let (q, k) = rope_qk(ctx, a, inp.pos, q, k);

    // :363-370 — build_attn with wo + wo_b inside
    let kq_scale = 1.0 / (a.n_embd_head_v as f32).sqrt();
    let attn_out = attn_kv_cached(
        ctx, &mut graph, kv, 0, a, inp, n_kv, q, k, v, kq_scale, 0.0, None, None, Some(lw.wo),
        lw.wo_b,
    );

    // :372-391 — the MoE (+ fused gate_up variant) over ffn_inp with the
    // 0.5-scaled shared expert (build_moe_ffn_silu_gu covers both expert
    // layouts, exp_probs_b == nullptr here)
    let mut cur = build_moe_ffn_silu_gu(
        ctx,
        &mut graph,
        ffn_inp,
        lw.ffn_gate_inp.expect("mtp ffn_gate_inp"),
        lw.ffn_gate_up_exps,
        lw.ffn_up_exps,
        lw.ffn_gate_exps,
        lw.ffn_down_exps.expect("mtp ffn_down_exps"),
        p.n_expert,
        p.n_expert_used,
        p.expert_weights_norm,
        p.expert_weights_scale,
        p.expert_gating_func,
        false,
    );
    if lw.ffn_up_shexp.is_some() {
        let ffn_shexp = build_ffn_silu_par(
            ctx,
            ffn_inp,
            lw.ffn_gate_shexp.expect("mtp ffn_gate_shexp"),
            None,
            lw.ffn_up_shexp.expect("mtp ffn_up_shexp"),
            None,
            lw.ffn_down_shexp.expect("mtp ffn_down_shexp"),
            None,
        );
        cur = ctx.add(cur, ffn_shexp);
        cur = ctx.scale(cur, 0.5);
    }

    // :393-395 the double residual
    let cur = ctx.add(cur, inp_l);
    let cur = ctx.add(cur, attn_out);

    // :397-421 the shared head + logit_scale
    let head_norm_w = w.nextn.shared_head_norm.unwrap_or(w.output_norm);
    let cur = norm(ctx, cur, head_norm_w);
    let h_nextn = cur;
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let head_w = w.nextn.shared_head_head.unwrap_or(w.output);
    let mut logits = crate::adapter::lora_mm(ctx, head_w, cur);
    if p.logit_scale != 0.0 {
        logits = ctx.scale(logits, p.logit_scale);
    }
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(h_nextn),
    }
}

// ---------------------------------------------------------------------------
// bailingmoe3 — src/models/bailingmoe3.cpp:412-617 `graph_mtp` (the gated-MLA
// head over the K-only cache)
// ---------------------------------------------------------------------------

pub struct BailingMoe3MtpWeights {
    pub tok_embd: TensorId,
    pub output_norm: TensorId,
    pub output: TensorId,
    pub nextn: MtpNextn,
    pub layer: BailingMoe3LayerWeights,
}

/// verify against src/models/bailingmoe3.cpp:412-617. Deltas vs the GLM4 skeleton:
///   * `llm_graph_input_embd` with **model.tok_embd** (no nextn.embed_tokens
///     fallback — the loader has none) and a plain mul_mat eh_proj (:444-452);
///   * the gated-MLA attention of the trunk (:455-508 — wq_a path, rope on the
///     q_pe/k_pe tails, wk_b absorbed into q_nope, build_attn_inp_k with wv_b,
///     then the sigmoid attention gate and wo);
///   * `nextn.shared_head_norm` is REQUIRED (:424, the LAYER_OUT_NORM tensor)
///     and the head is a plain mul_mat on model.output (:535-539).
pub fn build_bailingmoe3_mtp_forward(
    ctx: &mut Context,
    w: &BailingMoe3MtpWeights,
    p: &BailingMoe3Params,
    kv: &KvCache,
    inp: &DecodeInputs,
    h_in: MtpHInput,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let t = n_tokens as i64;
    let mut graph = Graph::new(1024);
    let lw = &w.layer;

    let n_head = p.n_head;
    let qk_head_dim = p.n_embd_head_k_mla;
    let v_head_dim = p.n_embd_head_v_mla;
    let qk_rope_head_dim = p.n_embd_head_qk_rope;
    let qk_nope_head_dim = qk_head_dim - qk_rope_head_dim;
    let kv_lora_rank = p.n_lora_kv;
    let kq_scale = 1.0f32 / (qk_head_dim as f32).sqrt();

    // :429-452 — the embd class + eh_proj (hnorm over the embd input,
    // enorm over model.tok_embd rows, plain mul_mat)
    let tok_embd = ctx.get_rows(w.tok_embd, inp.tokens);
    let h_norm = build_norm_rms(ctx, h_in, w.nextn.hnorm, p.attn.norm_eps);
    let e_norm = build_norm_rms(ctx, tok_embd, w.nextn.enorm, p.attn.norm_eps);
    let concat = ctx.concat(e_norm, h_norm, 0);
    let cur = ctx.mul_mat(w.nextn.eh_proj, concat);

    // :455-458
    let inp_sa = cur;
    let cur = build_norm_rms(ctx, cur, lw.attn_norm, p.attn.norm_eps);
    let attn_input = cur;

    // :460-485 — the MLA projections (the trunk gated-MLA shape)
    let q_all = if let (Some(wq_a), Some(q_a_norm), Some(wq_b)) =
        (lw.wq_a, lw.attn_q_a_norm, lw.wq_b)
    {
        let q_a = ctx.mul_mat(wq_a, cur);
        let q_a = build_norm_rms(ctx, q_a, q_a_norm, p.attn.norm_eps);
        ctx.mul_mat(wq_b, q_a)
    } else {
        ctx.mul_mat(lw.wq_mla.expect("mtp wq"), cur)
    };
    let rs_head = GgmlType::F32.row_size(qk_head_dim as usize);
    let q_nope = ctx.view_3d(
        q_all,
        qk_nope_head_dim,
        n_head,
        t,
        rs_head,
        rs_head * n_head as usize,
        0,
    );
    let q_pe = ctx.view_3d(
        q_all,
        qk_rope_head_dim,
        n_head,
        t,
        rs_head,
        rs_head * n_head as usize,
        (qk_nope_head_dim * 4) as usize,
    );
    let kv_all = ctx.mul_mat(lw.wkv_a_mqa.expect("mtp wkv_a_mqa"), cur);
    let rs_row = GgmlType::F32.row_size((kv_lora_rank + qk_rope_head_dim) as usize);
    let kv_c = ctx.view_2d(kv_all, kv_lora_rank, t, rs_row, 0);
    let k_pe = ctx.view_3d(
        kv_all,
        qk_rope_head_dim,
        1,
        t,
        rs_row,
        rs_row,
        GgmlType::F32.row_size(kv_lora_rank as usize),
    );
    // the same M-RoPE branch as the trunk (graph_mtp, bailingmoe3.cpp:497-510
    // def4d406a — VL files carry sections)
    let use_mrope = p.rope_sections[0] > 0 && p.rope_sections[1] > 0;
    let sections = p.rope_sections;
    let rope = |ctx: &mut Context, x: TensorId| {
        if use_mrope {
            ctx.rope_multi(
                x,
                inp.pos,
                None,
                p.attn.n_rot as i32,
                sections,
                p.attn.rope_mode,
                p.attn.n_ctx_orig,
                p.attn.freq_base,
                p.attn.freq_scale,
                p.attn.ext_factor,
                p.attn.attn_factor,
                p.attn.beta_fast,
                p.attn.beta_slow,
            )
        } else {
            ctx.rope_ext(
                x,
                inp.pos,
                None,
                p.attn.n_rot as i32,
                p.attn.rope_mode,
                p.attn.n_ctx_orig,
                p.attn.freq_base,
                p.attn.freq_scale,
                p.attn.ext_factor,
                p.attn.attn_factor,
                p.attn.beta_fast,
                p.attn.beta_slow,
            )
        }
    };
    let q_pe = rope(ctx, q_pe);
    let k_pe = rope(ctx, k_pe);
    let kv_n = build_norm_rms(
        ctx,
        kv_c,
        lw.attn_kv_a_norm.expect("mtp attn_kv_a_norm"),
        p.attn.norm_eps,
    );

    // :487-496 absorb wk_b, concat, the K-only cache attention
    let q_nope = ctx.permute(q_nope, 0, 2, 1, 3);
    let q_nope = ctx.mul_mat(lw.wk_b.expect("mtp wk_b"), q_nope);
    let q_nope = ctx.permute(q_nope, 0, 2, 1, 3);
    let q = ctx.concat(q_nope, q_pe, 0);
    let kv_3d = ctx.reshape_3d(kv_n, kv_lora_rank, 1, t);
    let k = ctx.concat(kv_3d, k_pe, 0);
    let cur = attn_k_cached_mla(
        ctx,
        &mut graph,
        kv,
        0,
        &p.attn,
        inp,
        n_kv,
        q,
        k,
        kv_3d,
        kq_scale,
        lw.wv_b.expect("mtp wv_b"),
        None,
        None,
    );

    // :498-505 the sigmoid attention gate + wo
    let attn_gate = ctx.mul_mat(lw.wqkv_gate.expect("mtp wqkv_gate"), attn_input);
    let attn_gate = ctx.reshape_3d(attn_gate, 1, n_head, t);
    let attn_gate = ctx.sigmoid(attn_gate);
    let cur = ctx.reshape_3d(cur, v_head_dim, n_head, t);
    let cur = ctx.mul(cur, attn_gate);
    let cur_c = ctx.cont_2d(cur, v_head_dim * n_head, t);
    let cur = ctx.mul_mat(lw.wo, cur_c);

    // :507-517 ffn_norm → MoE + shared expert (the trunk clamps)
    let ffn_inp = ctx.add(cur, inp_sa);
    let normed = build_norm_rms(ctx, ffn_inp, lw.ffn_norm, p.attn.norm_eps);
    let limit = p.swiglu_clamp_exp.last().copied().unwrap_or(0.0);
    let moe = build_bailingmoe3_moe(ctx, &mut graph, normed, lw, p, limit);
    let sh_limit = p.swiglu_clamp_shexp.last().copied().unwrap_or(0.0);
    let up = crate::adapter::lora_mm(ctx, lw.ffn_up_shexp.expect("mtp ffn_up_shexp"), normed);
    let gate =
        crate::adapter::lora_mm(ctx, lw.ffn_gate_shexp.expect("mtp ffn_gate_shexp"), normed);
    let shexp = silu_par_clamped(ctx, gate, up, sh_limit);
    let shexp = crate::adapter::lora_mm(ctx, lw.ffn_down_shexp.expect("mtp ffn_down_shexp"), shexp);
    let cur = ctx.add(moe, shexp);
    let cur = ctx.add(cur, ffn_inp);

    // :519-539 — shared_head_norm REQUIRED, the plain mul_mat head
    let cur = build_norm_rms(
        ctx,
        cur,
        w.nextn.shared_head_norm.expect("bailingmoe3 MTP final norm"),
        p.attn.norm_eps,
    );
    let h_nextn = cur;
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let logits = ctx.mul_mat(w.output, cur);
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(h_nextn),
    }
}

// ---------------------------------------------------------------------------
// hy-v3 — src/models/hy-v3.cpp:239-390 `graph_mtp`
// ---------------------------------------------------------------------------

pub struct HyV3MtpWeights {
    pub tok_embd: TensorId,
    pub output_norm: TensorId,
    pub output: TensorId,
    pub nextn: MtpNextn,
    pub layer: HyV3LayerWeights,
}

/// verify against src/models/hy-v3.cpp:239-390 — the eh_proj trio → a full hy_v3
/// decoder layer (QK-norm BEFORE rope, `build_attn` with wo inside, dense or
/// sigmoid-MoE+shexp FFN) → the final norm (the vLLM final_layernorm
/// semantics — the POST-norm state seeds the next step) → the shared head.
pub fn build_hy_v3_mtp_forward(
    ctx: &mut Context,
    w: &HyV3MtpWeights,
    p: &HyV3Params,
    kv: &KvCache,
    inp: &DecodeInputs,
    h_in: MtpHInput,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let t = n_tokens as i64;
    let mut graph = Graph::new(1024);
    let lw = &w.layer;
    let a = &p.attn;
    assert_eq!(a.n_embd_head_v, a.n_embd_head_k, "hy-v3.cpp:249");
    assert_eq!(a.n_embd_head_k, a.n_rot, "hy-v3.cpp:250");

    // :259-291
    let tok_embd = mtp_tok_embd(ctx, w.tok_embd, &w.nextn, inp.tokens);
    let cur = mtp_eh_proj_rms(ctx, tok_embd, h_in, &w.nextn, p.norm_rms_eps);
    let inp_sa = cur;

    // :294-297
    let cur = build_norm_rms(ctx, cur, lw.attn_norm, p.norm_rms_eps);

    // :299-327 — the trunk attention (QK-norm before rope, wo inside)
    let (mut q, mut k, v) = if let Some(wqkv) = lw.wqkv {
        qkv_fused(ctx, wqkv, lw.wqkv_b, a, cur, t)
    } else {
        qkv_separate_parts(
            ctx,
            lw.wq.expect("mtp wq"),
            lw.wq_b,
            lw.wk.expect("mtp wk"),
            lw.wk_b,
            lw.wv.expect("mtp wv"),
            lw.wv_b,
            a,
            cur,
            t,
        )
    };
    q = build_norm_rms(ctx, q, lw.attn_q_norm, p.norm_rms_eps);
    k = build_norm_rms(ctx, k, lw.attn_k_norm, p.norm_rms_eps);
    let (q, k) = rope_qk(ctx, a, inp.pos, q, k);
    let kq_scale = 1.0 / (a.n_embd_head_k as f32).sqrt();
    let cur = attn_kv_cached(
        ctx, &mut graph, kv, 0, a, inp, n_kv, q, k, v, kq_scale, 0.0, None, None, Some(lw.wo),
        None,
    );

    // :329-334
    let ffn_inp = ctx.add(cur, inp_sa);
    let cur = build_norm_rms(ctx, ffn_inp, lw.ffn_norm, p.norm_rms_eps);

    // :336-374 — dense or the sigmoid MoE + the always-on shared expert
    let cur = if lw.ffn_gate_inp.is_none() {
        build_ffn_silu_par(
            ctx,
            cur,
            lw.ffn_gate.expect("mtp ffn_gate"),
            None,
            lw.ffn_up.expect("mtp ffn_up"),
            None,
            lw.ffn_down.expect("mtp ffn_down"),
            None,
        )
    } else {
        let logits = crate::adapter::lora_mm(ctx, lw.ffn_gate_inp.expect("mtp gate_inp"), cur);
        let moe_out = build_moe_ffn_silu_probs(
            ctx,
            &mut graph,
            cur,
            logits,
            lw.ffn_up_exps.expect("mtp up_exps"),
            lw.ffn_gate_exps.expect("mtp gate_exps"),
            lw.ffn_down_exps.expect("mtp down_exps"),
            p.n_expert,
            p.n_expert,
            1,
            p.n_expert_used,
            p.expert_weights_norm,
            p.expert_weights_scale,
            p.expert_gating_func,
            lw.ffn_exp_probs_b,
        );
        let sh_out = build_ffn_silu_par(
            ctx,
            cur,
            lw.ffn_gate_shexp.expect("mtp gate_shexp"),
            None,
            lw.ffn_up_shexp.expect("mtp up_shexp"),
            None,
            lw.ffn_down_shexp.expect("mtp down_shexp"),
            None,
        );
        ctx.add(moe_out, sh_out)
    };
    let cur = ctx.add(cur, ffn_inp);

    // :376-390 the shared head
    let (logits, h_nextn) = mtp_shared_head(
        ctx,
        cur,
        w.output_norm,
        w.output,
        &w.nextn,
        inp.out_ids,
        p.norm_rms_eps,
    );
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(h_nextn),
    }
}

// ---------------------------------------------------------------------------
// mimo2 — src/models/mimo2.cpp:261-396 `graph_mtp` (iswa, sinks, the value
// scale, the gathered h_nextn)
// ---------------------------------------------------------------------------

pub struct Mimo2MtpWeights {
    pub tok_embd: TensorId,
    pub output_norm: TensorId,
    pub output: TensorId,
    pub nextn: MtpNextn,
    pub layer: Mimo2LayerWeights,
    /// the converted-checkpoint fallback of the head norm
    /// (mimo2.cpp:381-383)
    pub layer_out_norm: Option<TensorId>,
    pub n_head: i64,
    pub n_head_kv: i64,
    /// the MTP layer's rope freqs (model.get_rope_freq_base/scale(cparams, il))
    pub freq_base: f32,
    pub freq_scale: f32,
}

/// verify against src/models/mimo2.cpp:261-396 — the fused-qkv split (wqkv REQUIRED,
/// :276), the sinks riding build_attn (:344-347), the value scale after wo
/// (:349-352), the REQUIRED dense FFN (:356-368) and the **gathered**
/// h_nextn: `inp_out_ids` gathers BEFORE the head norm (:370-374), and the
/// head-norm fallback chain adds layer_out_norm (:378-383).
pub fn build_mimo2_mtp_forward(
    ctx: &mut Context,
    w: &Mimo2MtpWeights,
    p: &Mimo2Params,
    kv: &KvCache,
    inp: &DecodeInputs,
    h_in: MtpHInput,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let t = n_tokens as i64;
    let mut graph = Graph::new(1024);
    let lw = &w.layer;
    let a = &p.attn;

    // :278-307
    let tok_embd = mtp_tok_embd(ctx, w.tok_embd, &w.nextn, inp.tokens);
    let cur = mtp_eh_proj_rms(ctx, tok_embd, h_in, &w.nextn, p.norm_rms_eps);
    let inp_sa = cur;

    // :309-312
    let cur = build_norm_rms(ctx, cur, lw.attn_norm, p.norm_rms_eps);

    // :314-337 — the fused qkv split (Q/K share head_dim_k, V its own)
    let qkv = crate::adapter::lora_mm(ctx, lw.wqkv.expect("MIMO2 MTP requires fused attn_qkv"), cur);
    let ty = ctx.ty(qkv);
    let row_k = ty.row_size(a.n_embd_head_k as usize);
    let row_v = ty.row_size(a.n_embd_head_v as usize);
    let row_full = ctx.nb(qkv)[1] as usize;
    let k_off = row_k * w.n_head as usize;
    let v_off = k_off + row_k * w.n_head_kv as usize;
    let q = ctx.view_3d(qkv, a.n_embd_head_k, w.n_head, t, row_k, row_full, 0);
    let k = ctx.view_3d(qkv, a.n_embd_head_k, w.n_head_kv, t, row_k, row_full, k_off);
    let v = ctx.view_3d(qkv, a.n_embd_head_v, w.n_head_kv, t, row_v, row_full, v_off);
    let rope = |ctx: &mut Context, x: TensorId| {
        ctx.rope_ext(
            x, inp.pos, None, a.n_rot as i32, a.rope_mode, a.n_ctx_orig, w.freq_base, w.freq_scale,
            a.ext_factor, a.attn_factor, a.beta_fast, a.beta_slow,
        )
    };
    let q = rope(ctx, q);
    let k = rope(ctx, k);

    // :339-347 build_attn (sinks + wo inside)
    let kq_scale = 1.0 / (a.n_embd_head_k as f32).sqrt();
    let mut cur = attn_kv_cached(
        ctx, &mut graph, kv, 0, a, inp, n_kv, q, k, v, kq_scale, 0.0, None, lw.attn_sinks,
        Some(lw.wo), None,
    );
    // :349-352 the value scale
    if p.v_scale != 0.0 {
        cur = ctx.scale(cur, p.v_scale);
    }

    // :354-368 — residual, ffn_norm, the REQUIRED dense FFN
    let ffn_inp = ctx.add(cur, inp_sa);
    let cur = build_norm_rms(ctx, ffn_inp, lw.ffn_norm, p.norm_rms_eps);
    let cur = build_ffn_silu_par(
        ctx,
        cur,
        lw.ffn_gate.expect("MIMO2 MTP requires dense FFN tensors"),
        None,
        lw.ffn_up.expect("MIMO2 MTP requires dense FFN tensors"),
        None,
        lw.ffn_down.expect("MIMO2 MTP requires dense FFN tensors"),
        None,
    );
    let cur = ctx.add(cur, ffn_inp);

    // :370-374 — the gather runs BEFORE the head norm (h_nextn is gathered)
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let h_nextn = cur;

    // :376-393 the head-norm fallback chain + the shared head
    let head_norm_w = w
        .nextn
        .shared_head_norm
        .or(w.layer_out_norm)
        .unwrap_or(w.output_norm);
    let cur = build_norm_rms(ctx, cur, head_norm_w, p.norm_rms_eps);
    let head_w = w.nextn.shared_head_head.unwrap_or(w.output);
    let logits = crate::adapter::lora_mm(ctx, head_w, cur);
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(h_nextn),
    }
}

