// step35 — src/models/step35.cpp:368-560 `graph_mtp` (iswa, the halved rope,
// the optional per-head gate, dense|MoE+shexp, the gathered h_nextn)
// ---------------------------------------------------------------------------

pub struct Step35MtpWeights {
    pub tok_embd: TensorId,
    pub output_norm: TensorId,
    pub output: TensorId,
    pub nextn: MtpNextn,
    pub layer: Step35LayerWeights,
    pub n_head: i64,
    pub n_head_kv: i64,
    /// hparams.is_swa(n_layer) — picks the MTP context's cache half
    pub is_swa: bool,
    /// hparams.n_rot(n_layer) — the halved full-attention dims
    pub n_rot: i32,
    pub freq_base: f32,
    pub freq_scale: f32,
}

/// verify against src/models/step35.cpp:368-560 — the eh_proj trio → a full Step3p5
/// decoder layer (build_qkv with `reshape == false` + self-reshaped 3D, the
/// optional Q/K norms, rope at n_rot_l with factors only on the full side,
/// `build_attn` wo==nullptr, the optional sigmoid per-head gate, then wo),
/// dense or sigmoid-MoE+shexp FFN, and the gathered h_nextn of mimo2's shape.
pub fn build_step35_mtp_forward(
    ctx: &mut Context,
    w: &Step35MtpWeights,
    p: &Step35Params,
    kv: &KvCache,
    inp: &DecodeInputs,
    h_in: MtpHInput,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let t = n_tokens as i64;
    let mut graph = Graph::new(1024);
    let lw = &w.layer;
    let a = &p.attn;

    // :385-413
    let tok_embd = mtp_tok_embd(ctx, w.tok_embd, &w.nextn, inp.tokens);
    let cur = mtp_eh_proj_rms(ctx, tok_embd, h_in, &w.nextn, p.norm_rms_eps);
    let inp_sa = cur;

    // :416-418
    let cur = build_norm_rms(ctx, cur, lw.attn_norm, p.norm_rms_eps);

    // :420-453 — build_qkv(reshape=false) + the self reshapes + norms + rope
    let (mut q, mut k, v) = if let Some(wqkv) = lw.wqkv {
        qkv_fused(ctx, wqkv, lw.wqkv_b, a, cur, t)
    } else {
        let q = crate::adapter::lora_mm(ctx, lw.wq.expect("mtp wq"), cur);
        let k = crate::adapter::lora_mm(ctx, lw.wk.expect("mtp wk"), cur);
        let v = crate::adapter::lora_mm(ctx, lw.wv.expect("mtp wv"), cur);
        (q, k, v)
    };
    let q = ctx.reshape_3d(q, a.n_embd_head_k, w.n_head, t);
    let k = ctx.reshape_3d(k, a.n_embd_head_k, w.n_head_kv, t);
    let v = ctx.reshape_3d(v, a.n_embd_head_v, w.n_head_kv, t);
    let mut q = q;
    if let Some(qn) = lw.attn_q_norm {
        q = build_norm_rms(ctx, q, qn, p.norm_rms_eps);
    }
    let mut k = k;
    if let Some(kn) = lw.attn_k_norm {
        k = build_norm_rms(ctx, k, kn, p.norm_rms_eps);
    }
    let rf = if w.is_swa { None } else { lw.rope_freqs };
    let rope = |ctx: &mut Context, x: TensorId| {
        ctx.rope_ext(
            x, inp.pos, rf, w.n_rot, a.rope_mode, a.n_ctx_orig, w.freq_base, w.freq_scale,
            a.ext_factor, a.attn_factor, a.beta_fast, a.beta_slow,
        )
    };
    let q = rope(ctx, q);
    let k = rope(ctx, k);

    // :455-461 build_attn (wo == nullptr)
    let kq_scale = 1.0 / (a.n_embd_head_k as f32).sqrt();
    let mut attn_out = attn_kv_cached(
        ctx, &mut graph, kv, 0, a, inp, n_kv, q, k, v, kq_scale, 0.0, None, None, None, None,
    );

    // :463-483 — the optional per-head sigmoid gate
    if let Some(gw) = lw.wqkv_gate {
        let gate = crate::adapter::lora_mm(ctx, gw, cur);
        let gate = ctx.sigmoid(gate);
        let nt = ctx.ne(attn_out)[1];
        let a3 = ctx.reshape_3d(attn_out, a.n_embd_head_v, a.n_head, nt);
        let g3 = ctx.reshape_3d(gate, 1, a.n_head, nt);
        let gated = ctx.mul(a3, g3);
        attn_out = ctx.reshape_2d(gated, a.n_embd_head_v * a.n_head, nt);
    }
    let cur = crate::adapter::lora_mm(ctx, lw.wo, attn_out);

    // :485-489
    let ffn_inp = ctx.add(cur, inp_sa);
    let cur = build_norm_rms(ctx, ffn_inp, lw.ffn_norm, p.norm_rms_eps);

    // :491-532 dense or the sigmoid MoE + the always-added shared expert
    let cur = if lw.ffn_gate_inp.is_none() {
        build_ffn_silu_par(
            ctx,
            cur,
            lw.ffn_gate.expect("mtp ffn_gate"),
            None,
            lw.ffn_up.expect("mtp ffn_up"),
            None,
            lw.ffn_down.expect("mtp ffn_down"),
            None,
        )
    } else {
        let logits = crate::adapter::lora_mm(ctx, lw.ffn_gate_inp.expect("mtp gate_inp"), cur);
        let moe_out = build_moe_ffn_silu_probs(
            ctx,
            &mut graph,
            cur,
            logits,
            lw.ffn_up_exps.expect("mtp up_exps"),
            lw.ffn_gate_exps.expect("mtp gate_exps"),
            lw.ffn_down_exps.expect("mtp down_exps"),
            p.n_expert,
            p.n_expert,
            1,
            p.n_expert_used,
            p.expert_weights_norm,
            p.expert_weights_scale,
            p.expert_gating_func,
            lw.ffn_exp_probs_b,
        );
        let sh_out = build_ffn_silu_par(
            ctx,
            cur,
            lw.ffn_gate_shexp.expect("mtp gate_shexp"),
            None,
            lw.ffn_up_shexp.expect("mtp up_shexp"),
            None,
            lw.ffn_down_shexp.expect("mtp down_shexp"),
            None,
        );
        ctx.add(moe_out, sh_out)
    };
    let cur = ctx.add(cur, ffn_inp);

    // :534-537 — the gather BEFORE the head norm (the step35 AR loop's seed)
    let cur = graph::out_rows(ctx, cur, inp.out_ids);
    let h_nextn = cur;

    // :539-558
    let head_norm_w = w.nextn.shared_head_norm.unwrap_or(w.output_norm);
    let cur = build_norm_rms(ctx, cur, head_norm_w, p.norm_rms_eps);
    let head_w = w.nextn.shared_head_head.unwrap_or(w.output);
    let logits = crate::adapter::lora_mm(ctx, head_w, cur);
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(h_nextn),
    }
}

// ===========================================================================
// t5 — src/models/t5.cpp:110-262 `graph<false>` (the decoder half of the
// full T5 arch; the encoder `graph<true>` is build_t5_encoder_forward, the
// t5encoder-arch twin, and the cross-attention inputs come from the encode
// pass's `enc.output_norm` state — the port's caller carries them, the C's
// `llama_context::cross` capture, llama-context.cpp:1625-1649)
// ===========================================================================

/// Per-layer decoder weights (t5.cpp:60-107 — `dec.blk.{i}.*`).
#[derive(Clone, Copy)]
pub struct T5DecoderLayerWeights {
    pub attn_norm: TensorId,
    /// optional {n_head, n_rel_attn_bkts} — falls back to layer 0's
    pub attn_rel_b: Option<TensorId>,
    pub wq: TensorId,
    pub wk: TensorId,
    pub wv: TensorId,
    pub wo: TensorId,
    pub attn_norm_cross: TensorId,
    pub wq_cross: TensorId,
    pub wk_cross: TensorId,
    pub wv_cross: TensorId,
    pub wo_cross: TensorId,
    pub ffn_norm: TensorId,
    /// present for t5 v1.1 / flan (gated GELU), absent for t5 1.0 (relu)
    pub ffn_gate: Option<TensorId>,
    pub ffn_down: TensorId,
    pub ffn_up: TensorId,
}

pub struct T5DecoderModelWeights {
    pub tok_embd: TensorId,
    /// `dec.output_norm` (the generic output_norm slot on arch T5)
    pub output_norm: TensorId,
    pub output: TensorId,
    pub layers: Vec<T5DecoderLayerWeights>,
}

#[derive(Clone)]
pub struct T5DecoderParams {
    pub n_head: i64,
    pub n_head_kv: i64,
    pub n_embd_head: i64,
    pub n_rel_attn_bkts: i64,
    pub f_norm_rms_eps: f32,
    pub attn: AttnParams,
}

/// the decoder-side extra inputs: the encoder's final state (the C's
/// `cross.v_embd`), the cross KQ mask [n_enc, T] and the decoder-relative
/// position buckets over the KV cells [n_kv, T] (build_inp_pos_bucket_dec,
/// causal — `relative_position_bucket(p0, p1, bkts, false)`).
pub struct T5CrossInputs {
    /// F32 [n_embd, n_enc] — the encode pass's t_embd
    pub cross_embd: TensorId,
    /// F32 (or F16) [n_enc, T] — 0 = attend (single-seq: all kept)
    pub cross_kq_mask: TensorId,
    /// I32 [n_kv, T] — the causal relative buckets
    pub pos_bucket_dec: TensorId,
}

/// verify against src/models/t5.cpp:110-262 — per decoder layer: rms attn_norm →
/// self-attention (the causal relative-position bias over the KV cells, wo
/// inside build_attn) → residual → rms attn_norm_cross → cross-attention over
/// the encoder state (Q from the normed input, K/V from embd_enc, wo_cross
/// inside) → residual → rms ffn_norm → relu-SEQ | gated-GELU-PAR FFN →
/// residual; then dec.output_norm + the LM head. The last layer's
/// inp_out_ids gather (t5.cpp:238-241) reduces rows only (the port's
/// decode picks its own rows).
pub fn build_t5_decoder_forward(
    ctx: &mut Context,
    w: &T5DecoderModelWeights,
    p: &T5DecoderParams,
    kv: &KvCache,
    inp: &DecodeInputs,
    cross: &T5CrossInputs,
    n_kv: u32,
    n_tokens: usize,
) -> ForwardResult {
    let t = n_tokens as i64;
    let n_enc = ctx.ne(cross.cross_embd)[1];
    let n_embd_head = p.n_embd_head;
    let mut graph = Graph::new(1024);
    assert_eq!(n_embd_head, p.attn.n_embd_head_k);

    let mut inp_l = ctx.get_rows(w.tok_embd, inp.tokens);
    let n_layer = w.layers.len();

    for il in 0..n_layer {
        let lw = &w.layers[il];
        let inp_sa = inp_l;

        // self-attention (t5.cpp:123-140)
        let cur = build_norm_rms(ctx, inp_l, lw.attn_norm, p.f_norm_rms_eps);
        let q = crate::adapter::lora_mm(ctx, lw.wq, cur);
        let k = crate::adapter::lora_mm(ctx, lw.wk, cur);
        let v = crate::adapter::lora_mm(ctx, lw.wv, cur);
        let q = ctx.reshape_3d(q, n_embd_head, p.n_head, t);
        let k = ctx.reshape_3d(k, n_embd_head, p.n_head_kv, t);
        let v = ctx.reshape_3d(v, n_embd_head, p.n_head_kv, t);

        // the relative bias table falls back to layer 0's (t5.cpp:129)
        let attn_rel_b = match lw.attn_rel_b {
            Some(b) => b,
            None => w.layers[0].attn_rel_b.expect("t5: no layer carries attn_rel_b"),
        };
        let kq_b = build_pos_bias(ctx, cross.pos_bucket_dec, attn_rel_b);

        let cur = attn_kv_cached_bias(
            ctx, &mut graph, kv, il, &p.attn, inp, n_kv, q, k, v, Some(kq_b), Some(lw.wo),
        );
        let cur = ctx.add(cur, inp_sa);
        let inp_ca = cur;

        // cross-attention (t5.cpp:142-189) — Q from the normed input, K/V from
        // the encoder state, the cross mask, wo_cross inside build_attn
        let cur = build_norm_rms(ctx, cur, lw.attn_norm_cross, p.f_norm_rms_eps);
        let q = crate::adapter::lora_mm(ctx, lw.wq_cross, cur);
        let k = crate::adapter::lora_mm(ctx, lw.wk_cross, cross.cross_embd);
        let v = crate::adapter::lora_mm(ctx, lw.wv_cross, cross.cross_embd);
        let q = ctx.reshape_3d(q, n_embd_head, p.n_head, t);
        let k = ctx.reshape_3d(k, n_embd_head, p.n_head_kv, n_enc);
        let v = ctx.reshape_3d(v, n_embd_head, p.n_head_kv, n_enc);
        let cur = attn_no_cache(
            ctx,
            q,
            k,
            v,
            None,
            cross.cross_kq_mask,
            1.0,
            Some(lw.wo_cross),
            None,
        );

        // the last layer gathers the output rows (t5.cpp:238-241)
        let (mut cur, mut inp_ca) = (cur, inp_ca);
        if il == n_layer - 1 {
            if let Some(ids) = inp.out_ids {
                cur = ctx.get_rows(cur, ids);
                inp_ca = ctx.get_rows(inp_ca, ids);
            }
        }
        let ffn_inp = ctx.add(cur, inp_ca);

        // FFN (t5.cpp:193-221): gate present → GELU+PAR (flan), else RELU+SEQ
        let cur = build_norm_rms(ctx, ffn_inp, lw.ffn_norm, p.f_norm_rms_eps);
        let ffn_out = match lw.ffn_gate {
            Some(gate) => {
                // build_ffn LLM_FFN_GELU + LLM_FFN_PAR
                let g = crate::adapter::lora_mm(ctx, gate, cur);
                let g = ctx.gelu(g);
                let u = crate::adapter::lora_mm(ctx, lw.ffn_up, cur);
                let prod = ctx.mul(g, u);
                crate::adapter::lora_mm(ctx, lw.ffn_down, prod)
            }
            None => {
                // build_ffn LLM_FFN_RELU + LLM_FFN_SEQ (gate == NULL)
                let u = crate::adapter::lora_mm(ctx, lw.ffn_up, cur);
                let u = ctx.relu(u);
                crate::adapter::lora_mm(ctx, lw.ffn_down, u)
            }
        };
        inp_l = ctx.add(ffn_out, ffn_inp);
    }

    // dec.output_norm + the LM head (t5.cpp:243-262)
    let embd = build_norm_rms(ctx, inp_l, w.output_norm, p.f_norm_rms_eps);
    let cur = graph::out_rows(ctx, embd, inp.out_ids);
    let logits = crate::adapter::lora_mm(ctx, w.output, cur);
    graph.build_forward(ctx, logits);
    ForwardResult {
        logits,
        graph,
        embd: Some(embd),
    }
}

/// `attn_kv_cached` with the t5 relative-position bias — the kq_b add between
/// the matmul and the softmax (build_attn_mha, llama-graph.cpp:2706-2710);
/// everything else is the shared non-FA cache path.
#[allow(clippy::too_many_arguments)]
fn attn_kv_cached_bias(
    ctx: &mut Context,
    graph: &mut Graph,
    kv: &KvCache,
    il: usize,
    p: &AttnParams,
    inp: &DecodeInputs,
    n_kv: u32,
    q: TensorId,
    k: TensorId,
    v: TensorId,
    kq_b: Option<TensorId>,
    wo: Option<TensorId>,
) -> TensorId {
    let t = ctx.ne(q)[2];

    // scatter K/V into the cache (dims 0/1 merged)
    let nb2 = ctx.nb(k)[2] as usize;
    let k_rows = ctx.view_2d(k, p.n_embd_head_k * p.n_head_kv, t, nb2, 0);
    let k_dst = ctx.set_rows(kv.layers[il].k, k_rows, inp.row_idx);
    graph.build_forward(ctx, k_dst);
    let nb2 = ctx.nb(v)[2] as usize;
    let v_rows = ctx.view_2d(v, p.n_embd_head_v * p.n_head_kv, t, nb2, 0);
    let v_dst = ctx.set_rows(kv.layers[il].v, v_rows, inp.row_idx);
    graph.build_forward(ctx, v_dst);

    // cache views [head_dim, n_head_kv, n_kv, 1]
    let k_view = kv.get_k(ctx, il, p.n_embd_head_k, p.n_head_kv, n_kv);
    let v_view = kv.get_v(ctx, il, p.n_embd_head_v, p.n_head_kv, n_kv);

    // [head_dim, heads, T] → [head_dim, T, heads]
    let q = ctx.permute(q, 0, 2, 1, 3);
    let k_view = ctx.permute(k_view, 0, 2, 1, 3);

    let kq = ctx.mul_mat(k_view, q);
    // the relative-position bias rides between the matmul and the softmax
    let kq = match kq_b {
        Some(b) => ctx.add(kq, b),
        None => kq,
    };
    let kq = ctx.soft_max_ext(kq, Some(inp.kq_mask), 1.0, 0.0);

    // non-FA v path (llama-graph.cpp:2709-2715): permute → transpose → cont
    let v_view = ctx.permute(v_view, 0, 2, 1, 3);
    let v_t = ctx.transpose(v_view);
    let v_c = ctx.cont(v_t);
    let kqv = ctx.mul_mat(v_c, kq); // [head_dim, T, heads]

    // back to [n_embd, T] (llama-graph.cpp:2724-2727)
    let kqv = ctx.permute(kqv, 0, 2, 1, 3);
    let kqv = ctx.cont(kqv);
    let kqv = ctx.reshape_2d(kqv, p.n_embd_head_v * p.n_head, t);

    match wo {
        Some(wo) => crate::adapter::lora_mm(ctx, wo, kqv),
        None => kqv,
    }
}

// ===========================================================================
// delta-net-base.cpp:289-374 `build_delta_net_autoregressive` — the NON-fused
// single-token path (`cparams.fused_gdn_ar == false`; the reference CPU build
// keeps the fused op on by default, llama-context.cpp:233, so this arm is
// unreachable through any reference CLI surface — the acceptance is the
// ggml-level bit-compare of tests/mtp2_e2e against parity/ref_dnet_ar_dump.c,
// which builds the identical op chain with the reference ggml).
//
// The chunked half (delta-net-base.cpp:17-287) is ported too, as
// build_delta_net_chunking below (arch batch 18, which added GGML_OP_SOLVE_TRI
// + GGML_OP_DIAG + GGML_OP_SET + UNARY-NEG to crates/ggml) — accepted the
// same way, against parity/ref_dnet_ch_dump.c (GDA + KDA cases, bit-identical).
// ===========================================================================

/// verify against src/models/delta-net-base.cpp:289-374 — the one-token delta rule:
/// `s = exp(g)*s; sk = sum_rows(s*k); d = (v - sk^T)*b; s += repeat(k, s)*d^T;
/// o = permute(sum_rows(s*q))`. All inputs/outputs follow the C shapes:
/// q/k [S_k, H_k, 1, n_seqs], v [S_v, H_v, 1, n_seqs], g [1|S_v, H_v, 1, B],
/// b [1, H_v, 1, B], s [S_v, S_v, H_v, B]; returns `(o, s_new)` with
/// o [S_v, H_v, 1, B] and s_new [S_v, S_v, H_v, B].
pub fn build_delta_net_autoregressive(
    ctx: &mut Context,
    q: TensorId,
    k: TensorId,
    v: TensorId,
    g: TensorId,
    b: TensorId,
    s: TensorId,
) -> (TensorId, TensorId) {
    let n_seqs = ctx.ne(s)[3];
    let h_v = ctx.ne(s)[2];

    // q = scale(q, 1/sqrt(S_k)) (delta-net-base.cpp:325)
    let s_k = ctx.ne(q)[0];
    let q = ctx.scale(q, 1.0 / (s_k as f32).sqrt());

    // permutes (0, 2, 1, 3) — [S, n_tokens(=1), H, n_seqs]
    let q = ctx.permute(q, 0, 2, 1, 3);
    let k = ctx.permute(k, 0, 2, 1, 3);
    let v = ctx.permute(v, 0, 2, 1, 3);

    // g → [1, g.ne0, H_v, B]; b → [1, 1, H_v, B] (:340-341)
    let g_ne0 = ctx.ne(g)[0];
    let g = ctx.reshape_4d(g, 1, g_ne0, h_v, n_seqs);
    let b = ctx.reshape_4d(b, 1, 1, h_v, n_seqs);

    // s = s * exp(g) (:344-345)
    let g = ctx.exp(g);
    let s = ctx.mul(s, g);

    // sk = sum_rows(s * k) — [1, S_v, H_v, B] (:348-350)
    let sk = ctx.mul(s, k);
    let sk = ctx.sum_rows(sk);

    // d = (v - transpose(sk)) * b — [S_v, 1, H_v, B] (:353-356)
    let sk_t = ctx.transpose(sk);
    let d = ctx.sub(v, sk_t);
    let d = ctx.mul(d, b);

    // d_t = transpose(d) — [1, S_v, H_v, B] (:359-360)
    let d_t = ctx.transpose(d);

    // kd = repeat(k, s) * d_t; s = s + kd (:363-365)
    let k = ctx.repeat(k, s);
    let kd = ctx.mul(k, d_t);
    let s = ctx.add(s, kd);

    // o = permute(sum_rows(s*q), 2, 0, 1, 3) — [S_v, H_v, 1, B] (:368-370)
    let s_q = ctx.mul(s, q);
    let o = ctx.sum_rows(s_q);
    let o = ctx.permute(o, 2, 0, 1, 3);
    (o, s)
}

// ===========================================================================
// delta-net-base.cpp:17-287 `build_delta_net_chunking` — the NON-fused
// chunked prefill path (`cparams.fused_gdn_ch == false`). Like the AR half
// above, the reference CPU build can never reach it: `fused_gdn_ch` is
// hardwired true (llama-context.cpp:234, no CLI flag exists to clear it), so
// no reference *model* graph exercises this code. The acceptance mirrors
// batch 17's AR arm: a ggml-level bit-compare of tests/mtp2_e2e against
// parity/ref_dnet_ch_dump.c — the same op chain (this function, verbatim)
// built with the *reference ggml*, whose CPU backend does implement
// GGML_OP_SOLVE_TRI (ops.cpp:10824) and GGML_OP_DIAG (ops.cpp:5434) even
// though no llama.cpp model emits them. Arch batch 18 adds those two ops to
// the port's ggml (plus GGML_OP_SET / UNARY-NEG the chunk loop needs).
// ===========================================================================

/// get_slice_2d (delta-net-base.cpp:6-11): one c-slice of dim 2 —
/// `[x, y, c, b]` → `[x, y, 1, b]` at byte offset `nb[2]*c`.
fn dnet_get_slice_2d(ctx: &mut Context, t: TensorId, c: i64) -> TensorId {
    let (ne, nb) = (ctx.ne(t), ctx.nb(t));
    ctx.view_4d(
        t,
        ne[0],
        ne[1],
        1,
        ne[3],
        nb[1] as usize,
        nb[2] as usize,
        nb[3] as usize,
        (nb[2] as usize) * c as usize,
    )
}

/// verify against src/models/delta-net-base.cpp:17-287 `build_delta_net_chunking` —
/// the chunkwise (WY/UT-transform) delta rule: pad to a multiple of CS=64
/// (GDA; 16 for the KDA g layout), build the intra-chunk decay masks from
/// cumsum(g), solve `(I + tril(kβkᵀ))⁻¹ · (-tril(kβkᵀ))` per chunk
/// (GGML_OP_SOLVE_TRI — the UT transform), then walk the chunks carrying the
/// recurrent state. All inputs/outputs follow the C shapes: q/k
/// [S_k, H_k, T, B], v [S_v, H_v, T, B], g [1|S_v, H_v, T, B], b
/// [1, H_v, T, B], s [S_v, S_v, H_v, B]; returns `(o, s_new)` with o
/// [S_v, H_v, n_tokens, B] and s_new [S_v, S_v, H_v, B].
#[allow(clippy::too_many_arguments)]
pub fn build_delta_net_chunking(
    ctx: &mut Context,
    q: TensorId,
    k: TensorId,
    v: TensorId,
    g: TensorId,
    b: TensorId,
    s: TensorId,
) -> (TensorId, TensorId) {
    use ggml::ops::{GGML_TRI_TYPE_LOWER, GGML_TRI_TYPE_LOWER_DIAG};

    let s_k = ctx.ne(q)[0];
    let h_k = ctx.ne(q)[1];
    let n_tokens = ctx.ne(q)[2];
    let n_seqs = ctx.ne(q)[3];
    let s_v = ctx.ne(v)[0];
    let h_v = ctx.ne(v)[1];
    let kda = ctx.ne(g)[0] == s_k && ctx.ne(g)[1] == h_k;

    debug_assert_eq!(s_k, s_v);
    debug_assert!(h_v % h_k == 0);

    // q = scale(q, 1/sqrt(S_k)) (:46-48)
    let q = ctx.scale(q, 1.0f32 / (s_k as f32).sqrt());

    // permutes (0, 2, 1, 3) — [S, n_tokens, H, n_seqs] (:50-54)
    let q = ctx.permute(q, 0, 2, 1, 3);
    let k = ctx.permute(k, 0, 2, 1, 3);
    let v = ctx.permute(v, 0, 2, 1, 3);
    let g = ctx.permute(g, 0, 2, 1, 3);
    let b = ctx.permute(b, 0, 2, 1, 3);

    // chunk size (:56) — KDA's per-key decay uses 16, GDA's per-head 64
    let cs = if kda { 16i64 } else { 64i64 };
    let pad = (cs - n_tokens % cs) % cs;
    let n_chunks = (n_tokens + pad) / cs;

    // right-pad dim 1 with zeros to n_chunks*CS (:58-63)
    let q = ctx.pad(q, 0, pad as i32, 0, 0);
    let k = ctx.pad(k, 0, pad as i32, 0, 0);
    let v = ctx.pad(v, 0, pad as i32, 0, 0);
    let g = ctx.pad(g, 0, pad as i32, 0, 0);
    let b = ctx.pad(b, 0, pad as i32, 0, 0);

    let v_b = ctx.mul(v, b);
    let k_b = ctx.mul(k, b);

    // fold the head and batch dims together (:65-73)
    let q = ctx.reshape_4d(q, s_k, cs, n_chunks, h_k * n_seqs);
    let k = ctx.reshape_4d(k, s_k, cs, n_chunks, h_k * n_seqs);
    let k_b = ctx.reshape_4d(k_b, s_k, cs, n_chunks, h_v * n_seqs);
    let v = ctx.reshape_4d(v, s_v, cs, n_chunks, h_v * n_seqs);
    let v_b = ctx.reshape_4d(v_b, s_v, cs, n_chunks, h_v * n_seqs);

    let g_ne0 = ctx.ne(g)[0];
    let g = ctx.reshape_4d(g, g_ne0, cs, n_chunks, h_v * n_seqs);
    let b = ctx.reshape_4d(b, 1, cs, n_chunks, h_v * n_seqs);

    // g_cs — cumsum over the chunk axis after a transpose (:75-78)
    // [CS, g_0, n_chunks, H_v * n_seqs]
    let g_t = ctx.transpose(g);
    let g_t = ctx.cont(g_t);
    let g_cs = ctx.cumsum(g_t);

    let (kb, kq) = if kda {
        // the KDA branch (:80-122): per-key decay masks
        let chb = n_chunks * h_k * n_seqs;

        let g_cs_i = ctx.reshape_4d(g_cs, cs, 1, s_k, chb); // [CS, 1, S_k, CHB]
        let g_cs_j = ctx.reshape_4d(g_cs, 1, cs, s_k, chb); // [1, CS, S_k, CHB]
        let g_cs_j = ctx.repeat_4d(g_cs_j, cs, cs, s_k, chb);

        // decay_mask = tril(exp(g_cs_j - g_cs_i)) (:94-98)
        let decay_mask = ctx.sub(g_cs_j, g_cs_i);
        let decay_mask = ctx.tri(decay_mask, GGML_TRI_TYPE_LOWER_DIAG);
        let decay_mask = ctx.exp(decay_mask);

        // [S_k, CS_j, CS_i, CHB] — second/third chunk dims switched (:100-101)
        let decay_mask = ctx.permute(decay_mask, 2, 1, 0, 3);
        let decay_mask = ctx.cont_4d(decay_mask, s_k, cs, cs, chb);

        let k_b_i = ctx.reshape_4d(k_b, s_k, cs, 1, chb);
        let k_j = ctx.reshape_4d(k, s_k, 1, cs, chb);
        let q_i = ctx.reshape_4d(q, s_k, cs, 1, chb);

        let decay_k_b_i = ctx.mul(decay_mask, k_b_i);
        let decay_q_i = ctx.mul(decay_mask, q_i);

        // (:120-123)
        let kb = ctx.mul_mat(decay_k_b_i, k_j);
        let kq = ctx.mul_mat(decay_q_i, k_j);

        let kb = ctx.reshape_4d(kb, cs, cs, n_chunks, h_v * n_seqs);
        let kb_t = ctx.transpose(kb);
        let kb = ctx.cont(kb_t);
        let kq = ctx.reshape_4d(kq, cs, cs, n_chunks, h_v * n_seqs);
        let kq_t = ctx.transpose(kq);
        let kq = ctx.cont(kq_t);
        (kb, kq)
    } else {
        // the GDA branch (:124-146): per-head decay mask
        let g_cs_i = g_cs;
        let g_cs_j = ctx.reshape_4d(g_cs, 1, cs, n_chunks, h_v * n_seqs);
        let g_cs_j = ctx.repeat_4d(g_cs_j, cs, cs, n_chunks, h_v * n_seqs);

        // decay_mask = tril(exp(g_cs_j - g_cs_i)) (:131-135)
        let decay_mask = ctx.sub(g_cs_j, g_cs_i);
        let decay_mask = ctx.tri(decay_mask, GGML_TRI_TYPE_LOWER_DIAG);
        let decay_mask = ctx.exp(decay_mask);

        // kb = (k k_bᵀ) ∘ decay; kq = (k qᵀ) ∘ decay (:138-143)
        let kb = ctx.mul_mat(k, k_b);
        let kb = ctx.mul(kb, decay_mask);
        let kq = ctx.mul_mat(k, q);
        let kq = ctx.mul(kq, decay_mask);
        (kb, kq)
    };

    // kq = tril(kq); attn = tril(kb) (:148-153)
    let kq = ctx.tri(kq, GGML_TRI_TYPE_LOWER_DIAG);
    let attn = ctx.tri(kb, GGML_TRI_TYPE_LOWER);

    // identity = diag(fill(view_1d(attn, CS), 1.0)) (:155-160)
    let identity = ctx.view_1d(attn, cs, 0);
    let identity = ctx.fill(identity, 1.0);
    let identity = ctx.diag(identity);

    // lhs = attn + I; attn = (I + attn)⁻¹ · (-attn) + I — the UT transform
    // (:162-171), GGML_OP_SOLVE_TRI on the strict-lower + I system
    let lhs = ctx.add(attn, identity);
    let attn = ctx.neg(attn);
    let lin_solve = ctx.solve_tri(lhs, attn, true, true, false);
    let attn = ctx.add(lin_solve, identity); // [CS, CS, n_chunks, H_k * n_seqs]

    // v = (v_bᵀ attn) (:173-174)
    let v_b_t = ctx.transpose(v_b);
    let v_bt = ctx.cont(v_b_t);
    let v = ctx.mul_mat(v_bt, attn);

    // g_exp / k_cumdecay / q_g_exp (:176-186)
    let g_exp = ctx.exp(g_cs);
    let k_b_t = ctx.transpose(k_b);
    let k_b = ctx.cont(k_b_t);
    let kbg = ctx.mul(k_b, g_exp);
    let k_cd = ctx.mul_mat(kbg, attn); // [CS, S_k, n_chunks, H_k * n_seqs]

    let g_exp_t = ctx.transpose(g_exp);
    let g_exp_t = ctx.cont(g_exp_t);
    let q_g_exp = ctx.mul(q, g_exp_t);

    // key_gdiff — the vectorized g_last/g_diff last-state trick (:188-216)
    // g_last: the last element of g_cumsum along the CS axis (ne0)
    let (g_ne, g_nb) = (ctx.ne(g_cs), ctx.nb(g_cs));
    let g_last = ctx.view_4d(
        g_cs,
        1,
        g_ne[1],
        g_ne[2],
        g_ne[3],
        g_nb[1] as usize,
        g_nb[2] as usize,
        g_nb[3] as usize,
        GgmlType::F32.row_size((g_ne[0] - 1) as usize),
    );
    let g_last = ctx.cont(g_last);
    let g_last_exp = ctx.exp(g_last);
    let g_last_exp_t = ctx.transpose(g_last_exp);
    let g_diff_sub = ctx.sub(g_cs, g_last);
    let g_diff = ctx.neg(g_diff_sub);
    let g_diff_exp = ctx.exp(g_diff);
    let g_diff_exp_t = ctx.transpose(g_diff_exp);
    let g_diff_exp_t = ctx.cont(g_diff_exp_t);
    let kg = ctx.mul(k, g_diff_exp_t); // [S_k, CS, n_chunks, H_v * n_seqs]
    let kg_t = ctx.transpose(kg); // [CS, S_k, n_chunks, H_v * n_seqs]
    let kg_t = ctx.cont(kg_t);

    // state as [S_v, S_v, 1, H_v * n_seqs] (:218-219)
    let s = ctx.reshape_4d(s, s_v, s_v, 1, h_v * n_seqs);

    // v_t — [CS, S_v, n_chunks, H_v * n_seqs] (:221)
    let v_t = ctx.transpose(v);
    let v_t = ctx.cont(v_t);

    // the chunk walk (:223-264)
    let mut v = v;
    let mut s = s;
    for chunk in 0..n_chunks {
        let ch_k_cd = dnet_get_slice_2d(ctx, k_cd, chunk); // [S_k, CS, 1, H*ns]
        let ch_v_t = dnet_get_slice_2d(ctx, v_t, chunk); // [CS, S_v, 1, H*ns]
        let ch_kq = dnet_get_slice_2d(ctx, kq, chunk); // [CS, CS, 1, H*ns]
        let ch_q_g_exp = dnet_get_slice_2d(ctx, q_g_exp, chunk); // [S_k, CS, 1, H*ns]
        let ch_kg_t = dnet_get_slice_2d(ctx, kg_t, chunk); // [CS, S_k, 1, H*ns]

        // v' = k_cumdecay @ s (:226-228)
        let v_t_p = ctx.mul_mat(ch_k_cd, s); // [CS, S_v, 1, H*ns]

        // v_new = vᵀ - v' (:231-232)
        let v_t_new = ctx.sub(ch_v_t, v_t_p);

        // v_attn = v_new @ (tril decay kq) (:235-236)
        let v_attn = ctx.mul_mat(v_t_new, ch_kq); // [S_v, CS, 1, H*ns]

        // attn_inter = s @ (q ∘ exp(g)) (:239-240)
        let attn_inter = ctx.mul_mat(s, ch_q_g_exp); // [S_v, CS, 1, H*ns]

        // o_ch = attn_inter + v_attn (:243-244)
        let o_ch = ctx.add(attn_inter, v_attn);

        // write the chunk's output rows back into v (:246)
        let v_nb = ctx.nb(v);
        v = ctx.set_inplace(
            v,
            o_ch,
            v_nb[1] as usize,
            v_nb[2] as usize,
            v_nb[3] as usize,
            (v_nb[2] as usize) * chunk as usize,
        );

        // s = s*g_last + kgdmulvnew (:249-263)
        let kgv = ctx.mul_mat(ch_kg_t, v_t_new); // [S_k, S_v, 1, H*ns]
        let ch_g_last_exp_t = dnet_get_slice_2d(ctx, g_last_exp_t, chunk);
        s = ctx.mul(s, ch_g_last_exp_t);
        s = ctx.add(s, kgv);
    }

    // truncate the padding and restore the head/batch dims (:267-273)
    let rs = |n: i64| GgmlType::F32.row_size(n as usize);
    let o = ctx.view_4d(
        v,
        s_v,
        n_tokens,
        h_v,
        n_seqs,
        rs(s_v),
        rs(s_v * cs * n_chunks),
        rs(s_v * cs * n_chunks * h_v),
        0,
    );
    let o = ctx.permute(o, 0, 2, 1, 3); // [S_v, H_v, n_tokens, n_seqs]
    let s = ctx.reshape_4d(s, s_v, s_v, h_v, n_seqs);
    (o, s)
}

// ===========================================================================
// glm5-next (GLM-5.3-Flash, def4d406a) — hybrid KDA (linear) + nope MLA with
// a k-pool DSA indexer, mHC residual streams, DeepSeek-style MoE
// (src/models/glm5-next.cpp). The trunk graph (:549-682) rides the port's
// `HybridIdxCache` (kv_cache.rs — llama_memory_hybrid_idx): the attn half is
// the K-only MLA `KvCache`, the recurrent half the `RecurrentState`, the
// indexer the idx cache whose kpool layout feeds `Glm5KpoolStep`.
// ===========================================================================

/// the per-layer tensor set of glm5-next (glm5-next.cpp:61-186)
